  (22, 'facility', 'an ability or skill at doing something:', 'His facility for memorizing dates was astonishing.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23, 'faculty', 'a natural ability to hear, see, think, move, etc.:', 'Even at the age of 100, she still had all her faculties.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24, 'faculty', 'a special ability to do a particular thing:', 'She has a faculty for inspiring confidence in people.
