  (54, 'tolerance', 'the ability to deal with something unpleasant or annoying, or to continue existing despite bad or difficult conditions:', 'My tolerance of/for heat is considerably greater after having lived in the Far East for a couple of years.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
