  (814, 'element', 'a small amount of an emotion or quality:', 'There was certainly an element of truth in what she said.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (815, 'element', 'a small amount or degree:', 'There was an element of truth in what she said, but it was an exaggeration.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (816, 'far', 'very much:', 'This car is far better than our old one.
