  (916, 'inflammatory', 'intended or likely to cause anger or hate:', 'The men were using inflammatory language/making inflammatory remarks about the other team''s supporters.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (917, 'irritation', 'the feeling of being angry or annoyed, or something that makes you feel like this:', 'That kind of behaviour is sure to cause irritation.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (918, 'kill', 'If you say that someone will kill you, you mean that they will be very angry with you:', 'My sister would kill me if she heard me say that.', 'verb', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
