  (930, 'furiously', 'in an extremely angry way:', 'She marched out of the house furiously.', 'adverb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (931, 'jealously', 'in a way that shows you are jealous (= unhappy and angry) because of something someone has got:', 'She eyed Gwen''s engagement ring jealously.', 'adverb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (932, 'jealously', 'in a way that shows you are jealous (= unhappy and angry) because you do not want to share someone''''s love and attention:', 'He was accused of jealously beating up his wife''s co-worker.', 'adverb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (933, 'snappily', 'angrily, or in a way that shows you are annoyed:', '"She doesn''t like dogs," he interrupted, almost snappily.
