  (1053, 'grate', 'to have an annoying or painful effect:', 'His constant whining for attention is beginning to grate on my nerves.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1054, 'irritate', 'to annoy or make angry:', 'After a while the noise began to irritate him.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1055, 'nark', 'to annoy someone:', 'I was a bit narked by David''s comment.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1056, 'needle', 'to purposely annoy someone by making critical remarks or jokes:', 'I hate to be needled about my weight.', 'verb T', NULL, NULL, 'infml', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
