INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1079, 'solution', 'an answer to a problem:', 'It seemed a reasonable solution to a difficult problem.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1080, 'rejoin', 'to give a quick answer to what someone has said, in an angry or humorous way:', '"No, I do not have time to help you," he rejoined impatiently.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
