INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1116, 'loom', 'to appear as a large, often frightening or unclear shape or object:', 'Dark storm clouds loomed on the horizon.', 'verb I', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
