  (1281, 'appeal', 'to request formally that a decision, esp. a legal or official one, be changed:', '[ T ] The verdict was appealed to a higher court.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1282, 'contest', 'If you contest a formal statement, a claim, a judge''''s decision, or a legal case, you say formally that it is wrong or unfair and try to have it changed:', 'We will certainly contest any claims made against the safety of our products.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1283, 'battle', 'an argument between two groups or against a situation that a group wants to change:', 'The aid agency continues the battle against ignorance and superstition.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1284, 'blow', 'a sudden argument:', 'The expected blow-up among the students never happened.', 'noun C', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
