INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1312, 'book', 'to arrange to have a seat, room, performer, etc. at a particular time in the future:', '[ + two objects ] I''ve booked us two tickets to see "Carmen"/I''ve booked two tickets for us to see "Carmen".
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1313, 'book', 'to arrange to have the use of a seat, room, etc. at a particular time in the future:', '[ T ] Our travel agent booked us on a flight to Paris.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1314, 'book', 'Someone who books a performer arranges a performance:', '[ T ] They booked the Rolling Stones for two concerts in New York.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
