  (1321, 'orchestrate', 'to arrange something carefully, and sometimes unfairly, so as to achieve a wanted result:', 'Their victory was largely a result of their brilliantly orchestrated election campaign.', 'verb T, often passive', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
