  (1339, 'misorder', 'to put things in the wrong order:', 'It was suggested that some children misorder compound nouns because they do not appreciate the semantic relationship between the parts.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (1340, 'given', 'already decided, arranged, or agreed:', 'At the given signal, the group rushed forward to the barrier.
