INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (2593, 'family', 'a large group of related types of animal or plant:', 'The lion is a member of the cat family.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (2594, 'noncellular', 'not involving or made of cells:', 'Plasma is the non-cellular portion of the blood.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (2595, 'family', 'a large group of related types of animals or plants:', 'The lion is a member of the cat family.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (2596, 'order', '(used in the classification of plants and animals) a group of related plants or animals:', 'An order is below a class and above a family.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (2597, 'segregate', '(of pairs of alleles (= different forms of the same gene)) to separate during meiosis (= the cell division that happens as part of the process of producing young animals or plants) and pass separately to separate gametes (= reproductive cells):', 'Disruption of the spindle can cause chromosomes to segregate abnormally at either of the two meiotic divisions.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (2598, 'segregation', 'the separation of pairs of alleles (= different forms of the same gene) during meiosis (= the cell division that happens as part of the process of producing young animals or plants) so that they pass separately to separate gametes (= reproductive cells):', 'Mendel''s first law states that genes do not blend, but pass intact from one generation to the next, after segregation.
