  (2710, 'sign', 'a movement of the hands or body that gives information or an instruction:', 'He kept giving me the cut-throat sign to end the speech.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
