  (2850, 'dead', 'If a place is dead, it is too quiet and nothing interesting happens there:', 'The city centre is quite lively during the day, but it''s totally dead at night.', 'adjective', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (2851, 'deadly', 'extremely boring:', 'The party was deadly.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
