INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (2991, 'light', 'the brightness that comes from the sun, fire, etc. and from electrical devices, and that allows things to be seen:', 'a bright light
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (2992, 'light', 'a piece of equipment that produces light, such as a lamp or a bulb:', 'Could you switch/turn the light on/off, please?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (2993, 'light', 'traffic lights (= a set of red, yellow, and green lights that control the movement of vehicles, usually at a point where two or more roads join):', 'She stopped at the lights and saw him on the other side of the road.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
