INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3011, 'air', 'If a programme or a person is on/off (the) air, they are/are not broadcasting on radio or television:', 'The radio station is on air from 6 a.m.', 'noun', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3012, 'air', 'to broadcast something or be broadcast on radio or television:', 'The game will be aired live on CBS at 7.00 tonight.
