INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3025, 'channel', 'a range of frequencies (= the numbers of waves produced within a particular period, especially one second) used to broadcast signals or radio or television programmes, especially those used by a particular station:', 'Pilots are supposed to monitor one of two emergency radio channels in case they need to communicate with fighter interceptors.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3026, 'station', 'a company that broadcasts radio or television programmes:', 'a radio/television station
