  (3130, 'firebrand', 'a piece of burning wood:', 'With firebrands in their hands, they ran to to the murderers'' houses, determined to burn them down.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3131, 'explode', 'to burst violently and usually with a loud noise, or to cause this to happen:', '[ I ] A bomb exploded nearby.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3132, 'explosion', 'the fact of something such as a bomb exploding:', 'The fire was thought to have been caused by a gas explosion.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3133, 'explosion', 'a violent burst, often with a loud noise:', '[ C ] The fire was caused by a gas explosion.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3134, 'explosive', 'exploding or able to explode easily:', 'Certain gases are highly explosive.
