INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3145, 'hedging', 'bushes or small trees planted very close together, especially along the edges of a garden, field, or road:', 'One of my favourite parts of the garden is a raised lawn, flanked by two lines of yew hedging.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3146, 'hedging', 'the activity of planting, cutting, or looking after hedging in a garden, field, etc.:', 'He did odd jobs for people such as roofing and hedging.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3147, 'account', 'an agreement with a shop or business that allows you to buy things and pay for them later:', 'Could you put it on/charge it to my account (= can I pay for it later), please?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3148, 'account', 'a customer who does business with a company:', 'If the advertising agency loses this account, it will make a big dent in their profits.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
