  (3760, 'turn', 'to change the direction in which you are facing or moving, or to cause someone or something to face or move in a different direction:', '[ I ] They told us to turn right at the first traffic light.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3761, 'turn', 'If you turn something or turn something over, you place the surface that was on top on the bottom:', '[ T ] He turned the pages of a magazine.
