INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3768, 'turn', 'a change in the direction in which you are moving or facing:', 'When you see the school on the left, make a right turn.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3769, 'turn', 'Something that is on the turn is about to change direction:', 'The tide is on the turn.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3770, 'turn', 'the point at which something changes or moves in a different direction:', 'the turn of the tide
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3771, 'interpret', 'to change what someone is saying into the words of another language; translate:', '[ I ] I had to ask someone to interpret for me because I don’t know any Italian.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3772, 'distort', 'to change something so that it is false or wrong, or no longer means what it was intended to mean:', 'She accused her opponent of distorting the truth.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3773, 'movement', 'a change in the place or position of your body or a part of your body:', '[ C ] the movements of the dancers
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3774, 'movement', 'the act or process of changing a situation or event, or of changing the way something happens or is done:', '[ C ] There has been a movement toward smaller families.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3775, 'diversion', 'a different route that is used because a road is closed:', 'Traffic diversions will be kept to a minimum throughout the festival.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3776, 'diversion', 'the fact of something being sent somewhere different from where it was originally intended to go:', 'the diversion of money to other projects', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3777, 'diversion', 'the act of causing something or someone to turn in a different direction, or to be used for a different purpose:', '[ U ] A snowstorm closed the airport, and the diversion of air traffic was therefore necessary.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3778, 'move', 'an occasion when you go to live or work in a different place:', 'We''ve had four moves in three years.', 'noun', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3779, 'move', 'an act of moving:', 'She held the gun to his head and said, "One move and you''re dead!"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3780, 'move', 'a movement or series of movements that form part of a dance:', 'I picked up some new dance moves.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3781, 'move', 'in some board games, a change of the position of one of the pieces used to play the game, or a change of position that is allowed by the rules, or a player''''s turn to move their piece:', 'It takes a long time to learn all the moves in chess.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3782, 'movement', 'a change of position or place:', '[ U ] Fire doors should be kept closed to prevent the movement of fire from one area to another.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3783, 'backpedal', 'to change an opinion that you had expressed before, or do something different from what you had said you would do:', 'As soon as I said I thought she was wrong, she started backpedalling.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3784, 'backtrack', 'to say that you did not mean something you said earlier or say that you have changed your opinion:', '[ + speech ] "All right," he backtracked, "It''s possible that I was mistaken."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3785, 'move', 'to (cause to) change an opinion or the way in which you live or work:', 'He''s made up his mind, and nothing you can say will move him on the issue.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3786, 'movement', 'a situation in which people change their opinion or the way that they live or work:', 'There has been a movement towards more women going back to work while their children are still young.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3787, 'pivot', 'to change your opinions, statements, decisions, etc. so that they are different to what they were before:', 'He has pivoted to bring himself in line with the rest of the candidates.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3788, 'move', 'to go to a different place to live or work:', 'We''re moving to Paris.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3789, 'move', 'to leave your home in order to live in a new one:', 'We''re moving house next week.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3790, 'bump', 'to remove someone or something from a particular position, sometimes to a different one:', 'He had been playing badly and was bumped from the team.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3791, 'bump', 'to refuse to let someone fly on a plane on which they have booked a seat and put them on a different flight, or to move a passenger to a different type of seat:', 'If you are bumped from an oversold flight you are entitled to compensation.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3792, 'bump', 'to add something to an old thread (= a series of messages and replies) on an online message board so that it moves up to the top, and people notice it and start replying to it again:', 'I''m bumping this old thread because I have a few relevant recommendations.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3793, 'movable', 'able to be moved:', 'We have movable screens dividing our office into working areas.', 'adjective not gradable', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (3794, 'move', 'to (cause to) change position:', 'I''m so cold I can''t move my fingers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
