INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (4166, 'analog', 'An analog clock or watch shows the time using numbers around the edge and hands that point to the numbers:', 'Use standard analog clocks at home to help your child learn how to tell time.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (4167, 'analogue', 'An analogue clock or watch shows the time using numbers around the edge and hands that point to the numbers:', 'You can choose to have the time display as an analogue or digital clock.
