INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (4195, 'braid', 'a thin strip of cloth or twisted threads that is attached to clothes, uniforms, or other things made of cloth, as a decoration:', 'The captain of the ship wore a cap decorated with gold braid (= twisted gold threads).', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (4196, 'braid', 'a thin strip of cloth or twisted threads used as decoration esp. in uniforms:', 'gold braid', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
