  (4236, 'jumper', 'a piece of clothing with long sleeves that is usually made from wool, is worn on the upper part of the body and does not open at the front:', 'a red woolly jumper', 'noun C', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (4237, 'launder', 'to wash, dry, and iron clothes, sheets, etc.:', 'freshly laundered sheets', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (4238, 'launderer', 'a person or company whose job is washing, drying, and ironing clothes, sheets, etc.:', 'Brother Andrew also performed the duties of launderer, nurse, and barber.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
