INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (4368, 'pool', 'a number of people or a quantity of a particular thing, such as money, collected together for shared use by several people or organizations:', 'Patrick crashed a Ford that he''d borrowed from the car pool at work.
