  (4991, 'compare', 'If something or someone does not compare with something or someone else, the second thing is very much better than the first:', 'Instant coffee just doesn''t compare with freshly ground coffee.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
