  (4993, 'compare', 'to consider or suggest that something is similar or equal to something else:', '[ I ] Instant coffee doesn’t compare with freshly ground coffee (= fresh coffee is much better).', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
