  (5453, 'swamp', 'to cover a place or thing with a large amount of water:', 'The boat was swamped by an enormous wave.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (5454, 'bound', 'used to describe a book that is covered or held together in the stated way:', 'a leather-bound book
