INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (5468, 'peel', 'If a layer or covering peels, it slowly comes off, and if you peel a layer or covering, you remove it slowly and carefully:', 'We peeled the wallpaper off the walls.
