  (5749, 'break', 'If you break a part of your body, you damage a bone which cracks or separates into pieces:', '[ T ] The top women’s downhill skier broke her leg in a freak collision.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (5750, 'break', 'If you break a bill of a particular amount of money, you exchange it for smaller bills whose total equals the amount of your bill:', '[ T ] Can you break a $50 bill for me?', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
