  (6030, 'however', 'despite whatever amount or degree:', 'However hungry I am, I never seem to be able to finish off a whole pizza.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6031, 'however', 'to whatever amount or degree:', 'However fast we drive, we’re not going to get there in time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6032, 'shade', 'a type or degree of a colour:', 'Their kitchen is painted an unusual shade of yellow/an unusual yellow shade.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6033, 'shade', 'something that is slightly different from other, similar things:', 'They are hoping to satisfy all shades of public opinion.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
