  (6088, 'recount', 'to describe the particular events of an experience, or to tell a story:', 'She recounted some of her experiences working as a nurse in a hospital emergency room.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6089, 'represent', 'to show or describe something or someone:', '[ + -ing verb ] The statue represents St. George killing the dragon.
