  (6624, 'aggressiveness', 'the quality in a disease of spreading quickly and being difficult to cure:', 'A biopsy is the most effective means of determining the aggressiveness of the cancer.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6625, 'aggressiveness', 'the quality in a treatment of being very strong and possibly harmful, because a condition is serious and difficult to cure:', 'A classification system is essential for making decisions about aggressiveness of treatment.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6626, 'benign', 'A benign growth is not cancer and is not likely to be harmful:', 'a benign tumour', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
