  (6627, 'cancer', 'a disease in which cells in the body grow without control, or a serious medical condition caused by this disease:', '[ U ] He died from cancer of the stomach.', 'noun C/U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6628, 'clap', 'slang for
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6629, 'diagnostic', 'identifying a particular illness using a combination of signs and symptoms:', 'a diagnostic test
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6630, 'epidemic', 'the appearance of a particular disease in a large number of people at the same time:', 'a flu epidemic', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
