  (6631, 'incurable', 'not able to be cured:', 'Parkinson''s disease is a debilitating and incurable disease of the nervous system.', 'adjective', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6632, 'infect', 'to pass a disease to a person, animal, or plant:', 'The ward was full of children infected with TB.
