  (6633, 'infect', 'If a place, wound, or substance is infected, it contains bacteria or other things that can cause disease:', 'The meat had been infected by E coli bacteria.', 'verb T', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6634, 'infected', '(of a person or animal) affected by an organism that can cause disease:', 'Scientists believe people died after eating meat from infected cattle.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6635, 'infected', '(of a substance, object, etc.) containing bacteria or other organisms that can cause disease:', 'The virus can be spread through sexual contact and infected needles.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6636, 'infection', 'a condition in which bacteria or viruses that cause disease have entered the body:', 'a serious infection
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6637, 'malady', 'a disease:', 'All the rose bushes seem to be suffering from the same mysterious malady.', 'noun C', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6638, 'malignant', 'A malignant disease or growth is cancer or is related to cancer, and is likely to be harmful:', 'The process by which malignant cancer cells multiply isn''t fully understood.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6639, 'malignantly', 'in a way that is related to cancer and is likely to be harmful:', 'Fat can make a healthy cell malignantly transform into a tumour cell.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6640, 'multifocal', '(of a disease) existing in more than one place in the body or part of the body :', 'It was originally thought it was a multifocal cancer, each developing individually.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6641, 'nonaggressive', 'A nonaggressive disease, especially cancer, does not spread quickly and has a good chance of being cured:', 'She was diagnosed with nonaggressive skin cancer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6642, 'pathological', 'involving or relating to pathology (= the scientific study of disease):', 'These pathological findings are in agreement with clinical studies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6643, 'pathological', 'relating to or caused by a disease:', 'a pathological condition/complaint', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6644, 'pathologically', 'in a way that relates to disease, especially its causes and effects or its diagnosis by the scientific examination of body tissue:', 'The cancer was proven to be stage B, pathologically.
