INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6786, 'polarized', 'divided into two completely opposing groups:', 'The debate is becoming polarized and there seems to be no middle ground.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6787, 'polarization', 'the act of dividing something, especially something that contains different people or opinions, into two completely opposing groups:', 'The polarization of society into rich and poor can clearly be seen in urban areas.
