  (6801, 'execute', 'to do or perform something planned:', 'Now that we have approval, we can go ahead and execute the plan.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6802, 'give', 'to perform an action:', '[ + two objects ] She gave me a smile/strange look.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (6803, 'give', 'to organize a party, meal, etc.:', 'They''re always giving parties.
