INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (7193, 'college', 'any place for specialized education after the age of 16 where people study or train to get knowledge and/or skills:', 'a teacher training college
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (7194, 'college', 'one of the separate and named parts into which some universities are divided:', 'King''s College, Cambridge
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (7195, 'college', 'in Britain and Australia, used in the names of some schools for children, especially private schools (= where education is paid for by parents):', 'Cheltenham Ladies'' College', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (7196, 'comprehensive', 'used in the UK to describe a school or type of education for children of all abilities above the age of eleven, paid for by the state:', 'Is the school selective or comprehensive?
