INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (7447, 'invite', 'to act in a way that causes or encourages something to happen or someone to believe or feel something:', 'Behaving provocatively in class is just inviting trouble.
