  (7881, 'interchange', 'an exchange, especially of ideas or information, between different people or groups:', 'An international medical conference was established for the interchange of new ideas and approaches.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (7882, 'interchange', 'an exchange, esp. of ideas or information, between different people or groups:', '[ U ] They hope to encourage the free interchange of ideas.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
