INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8426, 'clamp', 'If the police or another person in authority clamps a vehicle, they fix a metal device to one of its wheels, usually because it is parked illegally. The device is usually only removed when the owner pays an amount of money:', 'When I finally got back, I found my car had been clamped.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8427, 'clip', 'to fasten something with a clip:', 'You can always tell a real bow tie from one that clips on.
