INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8684, 'location', 'a place away from a studio where all or part of a film or a television show is recorded:', 'The documentary was made on location in the Gobi desert.', 'noun', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8685, 'non-documentary', 'not having the features of a documentary (= a film or television or radio programme that gives facts and information about a subject):', 'He is the first non-documentary filmmaker to have secured rights to the singer''s life and music.
