  (8946, 'buoyant', 'able to float:', 'Cork is light and buoyant.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8947, 'buoyantly', 'in a way that relates to floating or the ability to float:', 'They were sailing swiftly and buoyantly on long rocking waves.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8948, 'noodle', 'a light, cylinder-shaped object that floats on water and that you hold onto or put under your arms when you are learning to swim or exercising in the water:', 'Using water weights, noodles, or even pool toys, you''ll swim, jog, stretch and lift your way into better shape.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8949, 'raft', 'a flat floating structure for travelling across water, often made of pieces of wood tied roughly together and moved along with a paddle (= pole with a flat end):', 'We lashed together anything that would float to make a raft.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8950, 'raft', 'a small rubber or plastic boat that can be filled with air:', 'a rubber raft
