INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8953, 'deck', 'one of the floors of a bus:', 'the upper/top deck of the bus', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8954, 'deck', 'on a level of a ship below the main deck:', 'Our cabin was below decks.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8955, 'deck', 'a wooden floor outside a house, usually with railings (= a low fence) and without a roof:', 'In summer, we always eat out on the deck – except when it rains.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8956, 'deck', 'A ship’s deck is a floor laid between the sides of the ship:', 'Waves washed over the deck.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8957, 'level', 'a floor in a large building:', 'The library has three levels, with a conference centre at ground level.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8958, 'mat', 'a small piece of strong material that covers and protects part of a floor:', 'Wipe your feet on the mat before you come inside.', 'noun C', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8959, 'dough', 'flour mixed with water and often yeast, fat, or sugar, so that it is ready for baking:', 'bread dough
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8960, 'current', 'a movement of water, air, or electricity in a particular direction:', 'to swim against/with the current
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8961, 'gush', 'to flow or send out quickly and in large amounts:', 'Oil gushed (out) from the hole in the tanker.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8962, 'gush', 'a large amount of liquid or gas that flows quickly:', 'Showers with pumps are more expensive, but they deliver a really powerful gush of water.', 'noun S', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8963, 'gush', 'to flow or pour out suddenly in large amounts:', 'Water gushed out of the broken pipe.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8964, 'run', 'to (cause something to) flow or produce liquid :', 'I can feel trickles of sweat running down my neck.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8965, 'run', '(of colours in clothes, etc.) to come out or spread:', 'I must have washed my dress at too high a temperature, because the colour has run.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8966, 'run', 'to cause a liquid to flow, or to produce a liquid that flows:', '[ T ] He ran a little cold water into the sink.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8967, 'runny', 'producing a lot of liquid, or of a substance partly liquid:', 'a runny nose
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8968, 'shed', 'to make blood or tears flow:', 'He didn’t shed one tear when his old car was stolen.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8969, 'spout', 'to flow or send out liquid or flames quickly and with force, in a straight line:', 'Flames spouted (out) from the oil wells.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8970, 'spout', 'a stream of liquid coming out of something with some force:', 'A spout of water shot out of the geyser.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
