  (8971, 'spout', 'to send out liquid or flames quickly and with force, or of liquid or flame to flow quickly:', '[ T ] The volcano spouted flames and red-hot rocks.', 'verb I/T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
