  (8973, 'stream', 'to move continuously in one direction:', 'We were all very excited as we streamed out of our final exam.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8974, 'stream', 'a continuous flow:', 'The faucet leaked in a steady stream.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8975, 'stream', 'to move continuously:', 'Record numbers of applications were streaming into our offices.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8976, 'wash', 'If water washes somewhere, it flows there, usually repeatedly:', 'She stood on the shore and let the water wash over her tired feet.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8977, 'wash', '(of the sea) to carry something or someone to or away from a place:', 'Overnight the waves had washed up a lot of rubbish.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8978, 'wash', '(the sound made) when the sea moves against land, etc.:', 'Outside the house, she could hear the gentle wash of the waves on the beach.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8979, 'wash', '(esp. of water) to flow or to cause to flow, often carrying something along:', '[ I ] Waves washed against the boat.
