  (8980, 'wash', 'If something is washed away, it is carried off by heavy rain or a flood:', '[ M ] Even trees and cars were washed away in this flood.', 'verb I/T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8981, 'wash', 'If something washes up or washes ashore, water has moved it there:', '[ M ] That storm washed a lot of crabs up on the shore.', 'verb I/T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8982, 'pour', 'to flow quickly and in large amounts, or to cause (something) to flow in large amounts:', '[ I ] Water poured into the basement.
