  (8983, 'pour', 'If you say about the weather that it is pouring, you mean that it is raining heavily:', '[ I ] You’d better take an umbrella – it’s pouring out there.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
