  (8995, 'wheel', 'to fly repeatedly in a circular pattern:', 'She watched a flock of seagulls wheeling high above her.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8996, 'flight', 'an aircraft trip, or the occasion of being a passenger in an aircraft:', '[ C ] We’ll be arriving home on Tuesday on flight 147.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8997, 'flight', 'Flight is also the act or process of flying:', '[ C ] We watched a flight of geese (= a group flying together).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (8998, 'soaring', 'rising high in the air while flying without moving the wings or using power:', 'It is a mysterious region of castles and soaring eagles.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
