  (9061, 'cocktail', 'a small dish of particular foods sometimes eaten at the beginning of a meal:', '[ C ] I’d like the shrimp cocktail, please.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
