INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (9063, 'cookie', 'a sweet, usually round, flat cake:', 'She served chocolate chip/oatmeal/peanut butter cookies for dessert.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (9064, 'corn', '(the seeds of) plants, such as wheat, maize, oats, and barley, that can be used to produce flour:', 'a sheaf of corn
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (9065, 'corn', 'a tall plant grown in many parts of the world for its yellow seeds, which are eaten as food, made into flour, or fed to animals:', 'corn-fed chickens
