  (9066, 'corn', 'a tall plant grown for its whole yellow or white seeds which are eaten cooked, made into flour, or fed to animals:', 'Let’s pick up a half dozen ears of corn for supper.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (9067, 'curry', 'to make a curry with something:', 'Let''s curry the leftover meat.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
