INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (9685, 'pool', 'a game in which two people use cues (= long, thin poles) to hit 16 coloured balls into six holes around the edge of a large table covered in soft cloth:', 'a pool table/room/hall
