  (9752, 'softness', 'the quality of not being severe or forceful enough, especially in criticizing or punishing someone who has done something wrong:', 'He was criticized for his softness on crime.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
