  (9788, 'mine', 'to use special software to try to obtain new cryptocurrency (= digital currency produced by a public network rather than by a government):', 'Since 2009, the number of bitcoins mined has skyrocketed.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (9789, 'darken', '(of a place or the sky) to become dark:', 'The sky darkened as thick smoke billowed from the blazing oil well.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
