  (9803, 'intervene', 'to become involved intentionally in a difficult situation in order to change it or improve it, or prevent it from getting worse:', 'The superpowers began to intervene in local struggles in Africa.', 'verb I', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (9804, 're-engage', 'to become involved, or have contact, with someone or something again, for a second, third, etc. time:', 'The campaign is trying to help former students re-engage with the university.
