  (9823, 'alight', 'to get out of a vehicle, especially a train or bus:', 'The suspect alighted from the train at Euston and proceeded to Heathrow.', 'verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (9824, 'make', 'to succeed in getting a place in a team:', 'She failed to make the Olympic squad.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (9825, 'reconceive', 'to become pregnant for a second, third, etc. time:', 'The study examines the effects of a postmiscarriage menstrual period prior to reconceiving.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (9826, 'set', 'to get something ready so that it comes into operation or can be used:', '[ + to infinitive ] The heating is set to come on at 5 p.m.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
