INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10165, 'decline', 'a change to a lower amount; the process of becoming less in quality or strength:', '[ C usually sing ] Unemployment increased this month after a modest decline.
