  (10167, 'intrusion', 'the act of going into a place or becoming involved in a situation where you are not wanted or do not belong:', '[ U ] They complained that building a new airport nearby would be a noisy intrusion on their quiet lives.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10168, 'social', 'relating to activities in which you meet and spend time with other people and that happen during the time when you are not working:', 'I had an active social life when I was at college.
