  (10180, 'hill climbing', 'a sport in which cyclists (= people riding bicycles) compete to see who is the fastest on a route which goes up a hill:', 'Altogether, he won nearly 300 cycle racing prizes for road, track and hill climbing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10181, 'hill climbing', 'the activity of walking for pleasure in areas with a lot of hills:', 'What followed were many happy years with her beloved husband walking and hill climbing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10182, 'golden', 'made of gold:', 'a golden necklace', 'adjective', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10183, 'golden', 'the colour of gold:', 'golden hair/skin
