INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10463, 'generation', 'all the people of about the same age within a society or within a particular family, or the usual period of time from a person’s birth to the birth of his or her children:', 'the last/next generation
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10464, 'generation', 'A generation is also a group of products or machines that are all at the same stage of development:', 'a new generation of cancer drugs
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10465, 'government', 'the group of people who officially control a country:', 'the government of Israel
