INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10575, 'cannon', 'a large, powerful gun, usually attached to two or four wheels, that was used in the past to fire heavy stone or metal balls:', 'The 5,000-pound cannon predates the Civil War.
