  (10576, 'cannon', 'a gun fastened to an aircraft:', 'A burst of fire was discharged by the jet''s 20mm cannon.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10577, 'double-barreled', 'A double-barreled gun has two barrels (= parts shaped like tubes):', 'a double-barreled shotgun', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
