  (10578, 'mortar', 'a large gun with a short, wide barrel (= a part shaped like a tube) that fires bombs or other explosives very high into the air, or an explosive device shot from such a gun:', 'The truck was packed with heavy weapons, including rocket launchers, mortars, and rockets.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10579, 'muzzle', 'the end of a gun barrel, where the bullets come out:', 'Always point the muzzle in a safe direction.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10580, 'piece', 'a gun:', 'an artillery piece
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10581, 'shooter', 'a gun:', 'They turned up at my house and one of them pulled out a shooter.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
