  (10917, 'welfare', 'physical and mental health and happiness:', 'We were concerned for our parents’ welfare when we heard about the storm in Florida.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10918, 'donut hole', 'for people on a particular kind of Medicare plan for prescription drugs (= ones that can only be bought if a doctor orders them for you), the fact of having to pay for a drug because its cost is between two levels at which the cost will be paid by their plan:', 'Many seniors fall into the donut hole with Medicare Part D.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (10919, 'doughnut hole', 'for people on a particular kind of Medicare plan for prescription drugs (= ones that can only be bought if a doctor orders them for you), the fact of having to pay for a drug because its cost is between two levels at which the cost will be paid by their plan:', 'The doughnut hole is the gap in coverage when Part D members reach $2,250 in prescription costs.
