INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11295, 'prick', 'the act of making a very small hole in the surface of something with a sharp object, or a hole that is made like this:', 'The test requires a small blood sample from a heel prick.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11296, 'prick', 'the pain that is felt when a hole is made in the surface of the skin with a sharp object :', 'Many also find the pain - which feels like a series of burning pricks - unbearable.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
