INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11950, 'point', 'If something points in a particular direction, it is turned towards that direction:', 'The road sign points left.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11951, 'strongly', 'in a persuasive or determined way:', 'He is strongly opposed to censorship.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11952, 'sim', 'a 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11953, 'red-eye', 'the red colour that a person''''s eyes seem to be in some photographs:', 'a flash which minimizes red-eye', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11954, 'like', 'The like poles (= ends) of a magnet (= an object that both attracts and pushes away iron and steel objects) are the ends which have the same charge (= negative or positive type of energy) and repel (= push away) each other:', 'Like poles repel, unlike poles attract.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11955, 'unlike', 'The unlike poles (= ends) of a magnet (= an object that both attracts and pushes away iron and steel objects) are the opposite ends, which attract each other:', 'Like poles repel; unlike poles attract.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11956, 'graphically', 'in a way that uses, consists of, or relates to graphs, or to drawing or printing:', 'Include a diagram that represents this data graphically.', 'adverb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11957, 'flip', 'to change from supporting one political party to supporting a different one; to make people in a particular place do this:', 'They produced a list of the districts that are considered most likely to flip in the upcoming elections.
