  (11958, 'radically', 'in a way that supports or relates to the belief that there should be great or extreme social or political change:', 'Applegarth, a radically minded Liberal, was at the centre of all the political and industrial issues of the 1860s.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
