INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11960, 'sub', 'short for sub-edit: to check and make changes to a text, in order to prepare it for being printed:', 'You might think that those who sub the magazine know their lords from their ladies - it should read Lord Olivier or Laurence Olivier, but never Lord Laurence Olivier.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11961, 'sub', 'short for sub-edit: to work as a sub-editor (= someone who checks and makes changes to texts, in order to prepare them for being printed):', 'We worked together on the Guardian, where she subbed on the foreign desk.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11962, 'anchor', 'the member of a team who goes last in a relay (= a type of race between two or more teams in which each person in the team runs or swims part of the race):', 'As anchor in the relay, he closed a 4-metre gap to seize victory.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11963, 'anchor', 'to be the member of a team who goes last in a relay (= a type of race between two or more teams in which each person in the team runs or swims part of the race):', 'He won the 100-and 200-metre sprints and anchored two winning relay teams.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11964, 'lap', 'to go past someone in a race who has been round the track one less time than you:', 'He finished last after being lapped twice by the leading runners.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
