INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (11974, 'dipole', 'two poles that have opposite and equal electrical charge or magnetic force, with a space between them:', 'Geomagnetic South Pole represents the axis of the Earth''s magnetic dipole.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
