  (11975, 'dipole', 'a molecule with an area of negative charge and an area of positive charge that are separated:', 'Many molecules (such as those of water) are electric dipoles, meaning that they have a partial positive charge at one end and a partial negative charge at the other.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
