INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12717, 'trade', 'a job, esp. one that needs special skill and that involves working with your hands, or the type of work in which such skills are needed:', '[ C ] the building trades
