  (12783, 'meander', 'a journey that has no particular direction:', 'The TV series continues its haphazard meander around the globe - this week in Portugal.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
