  (12786, 'account', 'to think of someone or something in the stated way:', 'She was accounted a genius by all who knew her work.', 'verb T, + obj + noun/adj', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12787, 'assess', 'to decide the quality or importance of something:', 'A college is going to assess a student’s ability based on grades.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
