  (12788, 'assess', 'To assess is also to judge the cost or value of something:', 'Government officials assessed the flood damage in the millions of dollars.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
