  (12789, 'brand', 'to consider or refer to someone as being bad or as having done something bad:', 'They branded him as a man without moral convictions.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12790, 'conclude', 'to judge or decide something after thinking carefully about it:', '[ + that ] The jury concluded from the evidence that the defendant was innocent.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12791, 'conclude', 'to judge after some consideration:', '[ + that clause ] We concluded that we could not afford to buy a new car.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12792, 'find', 'to make a judgment in a law court:', '[ + obj + adj  ] In a unanimous verdict, the jury found him guilty/not guilty of the murder.', 'verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12793, 'find', 'to make a judgment in a law court:', '[ T ] to be found guilty/innocent', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12794, 'gauge', 'to make a judgment about something, usually people''''s feelings:', 'A poll was conducted to gauge consumers'' attitudes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12795, 'justice', 'a judge in a law court:', 'The president is expected to name a new Supreme Court justice within the next few days.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12796, 'justice', 'used before the name of a judge in the High Court:', 'Mr Justice Ellis', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12797, 'justice', 'a judge, esp. of one of the higher courts of law:', 'a justice of the US Supreme Court', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12798, 'measure', 'to judge the quality, effect, importance, or value of something:', 'There is no way of measuring the damage done to morale.', 'verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12799, 'pass', 'to express a judgment or opinion about something, especially someone else''''s behaviour:', 'As a convicted criminal, he''s in no position to pass judgment (on the rest of us).', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12800, 'put', 'to judge something or someone in comparison with other similar things or people:', 'I''d put him among the top six tennis players of all time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12801, 'put', 'to judge something or someone in comparison with other similar things or people:', 'I’d put him among the top six tennis players of all time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12802, 'rate', 'to judge the value or character of someone or something:', 'How do you rate him as a football player?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12803, 'rate', 'to be considered to be something of a particular quality:', 'That rates as the worst film I''ve ever seen.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12804, 'reason', 'to think about and make a good judgment about:', '[ + (that) clause ] He reasoned (that) he had only four or five years left as an athlete.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (12805, 'referee', 'a person who is in charge of a sports game and who makes certain that the rules are followed:', 'We only lost the game because the referee was biased.', 'noun C', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
