  (13152, 'mass', 'involving or having an effect on a large number of people or things:', 'weapons of mass destruction
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13153, 'mountain', 'a large amount of something:', 'I''ve got a mountain of work to do.', 'noun C', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
