INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13376, 'trial', 'the hearing of statements and showing of objects, etc. in a law court to judge if a person is guilty of a crime or to decide a case or a legal matter:', 'trial proceedings
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13377, 'trial', 'the examination in a court of law of the facts of a case to decide whether a person is guilty of a crime or responsible for an injury to another person:', '[ C ] a criminal/civil trial
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13378, 'trial', 'If someone is on trial, the case in which that person''''s guilt is being judged has begun:', 'He was on trial for assault and robbery.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13379, 'interest', 'an involvement or a legal right, usually relating to a business or possessions:', 'He is a multi-millionaire with business interests around the world.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13380, 'patent', 'the official legal right to make or sell an invention for a particular number of years:', 'In 1880 Alexander Graham Bell was granted a patent on an apparatus for signalling and communicating called a Photophone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13381, 'patent', 'A patent invention is protected by law so that only particular people or companies have the right to make or sell it:', 'a patent screwdriver', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13382, 'title', 'the legal right to own a piece of land or a building, or a document that proves this right:', 'If you wish to sell the property, you will first have to prove your title to it.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13383, 'title', 'the legal right to own something, esp. a piece of land or a building:', 'That little paper is your title to the car, so don’t lose it.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13384, 'clause', 'a part of a written legal document:', 'He had a clause in his movie contract that let him work in the theater.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13385, 'pleading', 'a formal written document stating the reasons for bringing a legal action against someone, or the reaction to those reasons given by the defence (= the accused person or their lawyers):', 'The case begins when the pleadings are filed with the court.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13386, 'diversion', 'a system that allows someone to avoid having a permanent criminal record, or to avoid punishment as a criminal, if they complete a course of treatment or study:', 'Pretrial diversion is a program for certain first-time offenders to give them a chance to avoid being marked by a felony conviction for the rest of their lives.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
