  (13527, 'cast', 'to provide an explanation for a situation or problem, or information that makes it easier to understand:', 'The discovery of the dinosaur skeleton has cast light on why they became extinct.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
