  (13596, 'popular', 'liked, enjoyed, or admired by many people or by most people in a particular group:', 'In-line skating is increasingly popular.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
