  (13599, 'apt', 'to be likely to do something or to often do something:', 'The kitchen roof is apt to (= likely to) leak when it rains.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13600, 'apt', 'likely:', 'This old roof is apt to leak when it rains.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
