  (13729, 'juice', 'the liquid that comes from fruits and vegetables:', '[ U ] orange/tomato juice
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13730, 'juices', 'liquid in meat or in a person’s body:', 'the digestive juices', 'plural noun', NULL, NULL, 'infml', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13731, 'juicy', 'Juicy foods contain a lot of juice and are enjoyable to eat:', 'a nice juicy orange/steak', 'adjective', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (13732, 'osmosis', 'the process in plants and animals by which a liquid moves gradually from one part of the body or the plant to another through a membrane (= cell covering):', 'Fluid flows back into the tiny blood vessels by osmosis.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
