  (13821, 'plant', 'a living thing that usually produces seeds and typically has a stem, leaves, roots, and sometimes flowers:', 'We brought a house plant as a gift when we spent the weekend with our friend Sylvia.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
