INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14117, 'wish', 'to hope that something you want will be made real because of good luck or magical powers:', '[ + that ] I remember blowing out the candles on my birthday cake and wishing that John Lee would be my boyfriend.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14118, 'wish', 'a hope that is made real with magical powers:', '[ + that ] If I could have just one wish I suppose it would be that all the fighting in the world would stop tomorrow.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14119, 'brownie', 'a small imaginary creature in old stories, said to be helpful to humans:', 'In this ancient woodland brownies, elves, and fairies were often seen.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
