  (14658, 'A, a', 'a mark that means excellent, given to something of the highest quality, esp. school work:', 'The teacher gave me an A for my essay.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
