  (14908, 'saddle', 'a large piece of meat taken from the middle of the back of an animal:', 'saddle of lamb', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14909, 'shoulder', 'a piece of meat that includes the upper part of an animal''''s front leg:', 'I''ve bought a shoulder of lamb for Sunday lunch.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14910, 'skirt', 'beef (= meat from a cow) that is cut from the bottom part of the side of the animal:', 'There''s an increasing market for the cheaper cuts of beef such as skirt.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
