INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14914, 'optics', 'the public''''s opinion and understanding of a situation after seeing it as the media shows it, and the possible political effects of this:', 'The political optics of this are horrible for the GOP.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14915, 'syndicate', 'an organization that supplies articles and photographs to different newspapers and magazines for publishing:', 'His cartoons are distributed by United Press Syndicate.', 'noun C, + sing/pl verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14916, 'outlet', 'an organization that broadcasts programmes or publishes news:', 'News outlets are sensitive to charges of bias.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14917, 'HMO', 'abbreviation for health maintenance organization: a group that provides healthcare to people who pay to join it:', 'For a monthly flat fee, paid by the consumer or employer, HMOs provide a specified list of medical services both in and outside the hospital.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14918, 'anti-shock', 'intended to reduce or prevent the effects of shock (= a medical condition caused by severe injury, loss of blood, or fear):', 'The patient had a sudden severe drop in blood pressure, which required anti-shock therapy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14919, 'anti-shock', 'Military anti-shock trousers or suits are designed to treat patients with severe injuries who have lost a lot of blood:', 'The concept of military anti-shock trousers (MAST) was first described in 1903.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14920, 'calculus', 'a mass of a hard mineral substance that is formed in the body, for example in the kidneys or gall bladder:', 'Stones that form in the kidney or bladder are called urinary calculi.', 'noun', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14921, 'calculus', 'a hard substance that forms on the teeth :', 'The disease process begins when plaque on the tooth hardens to tartar, which hardens further to become calcified tartar, or calculus.', 'noun', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14922, 'clinical', 'used to refer to medical work or teaching that relates to the examination and treatment of ill people:', 'clinical tests/training
