  (14923, 'clinically', 'according to medical science and examination of patients:', 'Doctors pronounced him clinically dead.', 'adverb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14924, 'clinically', 'relating to the results of clinical tests or experiments:', 'This toothpaste has been clinically proven to protect your teeth.', 'adverb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14925, 'ct', 'abbreviation for computerized tomography: the use of X-rays to make three-dimensional images (= ones that have or appear to have height, depth, and width) of flat sections of the body:', 'Brain imaging using CT and MRI revealed damage to the right cerebral hemisphere.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
