  (14933, 'retrograde', 'used to describe the fact that someone is unable to remember things that happen before a particular event:', 'There is evidence to show that ECT can cause both retrograde (i.e. before treatment) and anterograde (i.e. after treatment) memory loss.', 'adjective', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14934, 'seizure', 'a very sudden attack of an illness in which someone becomes unconscious or develops violent movements:', 'an epileptic seizure', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14935, 'seizure', 'a sudden failure of the heart:', 'His aunt died of a seizure.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
