  (14940, 'treatment', 'the use of drugs, exercises, etc. to improve the condition of an ill or injured person, or to cure a disease:', '[ U ] Chronic back pain may not respond to treatment.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
