INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14958, 'doctor', 'a person with a medical degree whose job is to treat people who are ill or hurt:', 'The doctor prescribed some medication.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14959, 'doctor', 'the place where a doctor works:', 'He went to the doctor''s this morning for a check-up.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14960, 'doctor', 'a person with a medical degree whose job is to treat people who are ill or injured:', 'This health plan lets you choose your own doctor.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14961, 'drug', 'any natural or artificially made chemical that is used as a medicine:', 'anti-cancer/fertility/pain-killing drugs
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14962, 'drug', 'any chemical that is used as a medicine:', 'over-the-counter/prescription drugs', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14963, 'operable', 'able to be treated by an operation:', 'In about half of diagnosed cases, the condition is operable.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14964, 'over the counter', 'An over-the-counter drug is bought from a shop without the person who buys it having visited a doctor first:', 'an over-the-counter medicine', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14965, 'pill', 'a small solid piece of medicine that a person swallows without chewing (= crushing with the teeth):', 'a sleeping pill
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14966, 'pill', 'a type of pill for women that is taken every day in order to prevent them from becoming pregnant:', 'Are you on the pill?', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14967, 'prescribed', 'decided by a doctor as treatment:', 'The patient was taking a widely prescribed sedative.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14968, 'prescription', 'a piece of paper on which a doctor writes the details of the medicine or drugs that someone needs:', 'a doctor''s prescription
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14969, 'prescription', 'a doctor’s written direction for the medicine that someone needs and how it is to be used, or the medicine itself:', 'The doctor gave me prescriptions for antibiotics and cough syrup.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14970, 'tablet', 'a small, solid piece of medicine:', 'a sleeping tablet
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14971, 'tablet', 'a small, round, solid object made of medicine; a pill:', 'aspirin tablets', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14972, 'tonic', 'something that makes you feel stronger or happier:', 'The magazine is lively and interesting - the pictures alone are a tonic.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14973, 'topical', 'A topical medical product is used on the outside of the body:', 'This lotion is for topical application only.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14974, 'topically', 'used on the outside of the body:', 'The cream is applied topically, that is, to the skin.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14975, 'moderate', 'being within a middle range in size, amount, or degree; neither great nor little:', 'The rent has gone up over the years, but in moderate amounts.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14976, 'moderately', 'within a middle range in size, amount, or degree; neither great nor little:', 'The new apartment complex will be moderately priced for middle-income people.', 'adverb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14977, 'moderate', 'neither small nor large in size, amount, degree, or strength:', 'The cabin is of moderate size - just right for a small family.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14978, 'date', 'to regularly spend time with someone you have a romantic relationship with:', 'They dated for five years before they got married.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14979, 'encounter', 'to meet someone unexpectedly:', 'On their way home they encountered a woman selling flowers.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14980, 'see', 'to meet or visit someone, or to visit a place:', 'We''re seeing friends this weekend.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14981, 'see', 'to have a romantic relationship with someone:', 'How long has she been seeing him?', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14982, 'see', 'to meet, visit, or spend time with someone:', 'I saw Darlene last week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14983, 'sit', 'to hold an official meeting of a committee, court, etc.:', 'The court will sit tomorrow morning.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14984, 'sit', '(of a legislature or court) to have an official meeting or series of meetings:', 'The Supreme Court sits from October to June.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14985, 'welcome', 'to meet and speak to someone in a friendly way when they arrive:', 'The visitors were warmly welcomed by the head of the department.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14986, 'welcome', 'to meet or speak to someone in a friendly way when that person comes to the place where you are:', 'We went next door to welcome our new neighbors.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14987, 'network', 'to meet people who might be useful to know, especially in your job:', 'I don''t really enjoy these conferences, but they''re a good opportunity to network.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14988, 'date', 'to regularly spend time with someone you have a romantic relationship with:', '[ I ] They dated for five years before they got married.', 'verb I/T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14989, 'introduce', 'to arrange for you to meet and learn the name of another person:', 'I’d like to introduce you to my friend, Sally.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14990, 'introduce', 'To introduce is also to formally present someone to a group:', 'It’s my distinct honor to introduce the president of the United States of America.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14991, 'rally', 'to bring or come together in order to provide support or make a shared effort:', '[ I ] African-American groups rallied around the president when he was under attack.', 'verb I/T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14992, 'assembly', 'a group of people, especially one that meets regularly for a particular purpose, such as government, or, more generally, the process of coming together, or the state of being together:', 'the United Nations General Assembly
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14993, 'assembly', 'one of the two parts of the government that makes laws in many US States:', 'the New York Assembly
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14994, 'assembly', 'a meeting in a school of several classes, usually at the beginning of the school day, to give information or to say prayers together:', 'All pupils are expected to attend school assembly.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14995, 'breakout', 'used in connection with smaller groups that separate from a meeting to discuss a particular issue, before returning to the main meeting:', 'a breakout session/meeting', 'adjective before noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14996, 'conference', 'an event, sometimes lasting a few days, at which there is a group of talks on a particular subject, or a meeting in which especially business matters are discussed formally:', 'a conference on women''s rights
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14997, 'conference', 'to be in a meeting:', 'Ms O''Neill isn''t available at the moment. She''s in conference.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14998, 'congress', 'a large formal meeting of representatives from countries or societies at which ideas are discussed and information is exchanged:', 'an international/medical congress
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (14999, 'convention', 'a large formal meeting of people who do a particular job or have a similar interest, or a large meeting for a political party:', 'the national Democratic convention
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15000, 'convention', 'a large event where fans of (= people who are very enthusiastic about) a particular TV programme, film, computer game, etc. can meet each other and some of the people involved in making the programme, film, etc.:', 'Thousands of people were in town for the country''s largest annual comic book convention.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15001, 'convention', 'a large meeting of a group of people who are involved in the same type of work or who have similar interests:', 'the Dairy Association’s annual convention
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15002, 'convention', 'A political convention is a meeting of a political party, esp. to choose someone to represent it in an election for a public office:', 'the Democratic/Republican national convention', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15003, 'date', 'a social meeting planned before it happens, especially one between two people who have or might have a romantic relationship:', 'He asked her out on a date.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15004, 'date', 'a person you have a romantic meeting with:', 'Who''s your date for the prom?', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15005, 'date', 'a social meeting planned in advance:', 'We made a date to meet Evelyn and Josie at noon tomorrow for lunch.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15006, 'date', 'A date is a person you are planning to meet socially and in whom you might have a romantic interest:', 'Who is your date for the prom?', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15007, 'forum', 'a situation or meeting in which people can talk about a problem or matter especially of public interest:', 'a forum for debate/discussion', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15008, 'hearing', 'an official meeting that is held to collect the facts about an event or problem:', 'A disciplinary hearing will examine charges of serious professional misconduct against three surgeons.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15009, 'hearing', 'an official meeting that is held to gather the facts about an event or problem:', 'A Senate subcommittee is holding hearings about the mortgage crisis.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15010, 'presser', 'a meeting at which a person or an organization makes a public statement and reporters can ask questions:', 'I''ll be interested to hear what he has to say in his presser.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15011, 'rally', 'a public meeting of a large group of people, especially supporters of a particular opinion:', '5,000 people held an anti-nuclear rally.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15012, 'rally', 'a public meeting of a large group of people, esp. to show support for a particular opinion, political party, or sports team:', 'He helped organize the first national rally against the war.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15013, 'salon', 'a meeting of writers, painters, etc., at the house of someone famous or important:', 'a literary salon', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15014, 'stand up', 'A stand-up meeting is one at which people stand, rather than sit:', 'the hotel''s stand-up management meetings', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15015, 'summit', 'an important formal meeting between leaders of governments from two or more countries:', 'a summit meeting
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15016, 'summit', 'a meeting of government leaders from several countries:', 'The economic summit did not accomplish all that the President had hoped it would.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15017, 'town hall', 'a public meeting at which a politician or official speaks about his or her policies and answers questions from members of the public:', 'Last week he spoke on the economy at a town hall in Austintown, Ohio.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15018, 'welcome', 'If someone is welcome, you are pleased when they visit you:', 'Come and see us whenever you''re in town - you''re always welcome/you''ll always be welcome.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15019, 'welcome', 'to show someone that you are pleased that they are with you:', 'The restaurant makes children very welcome.', 'adjective', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15020, 'welcome', 'the way in which someone is met and spoken to when they arrive in a place:', 'They were given a warm (= very friendly) welcome.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15021, 'welcome', 'to stay too long:', 'I left after two days - I didn''t want to outstay my welcome.', 'noun', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15022, 'workshop', 'a meeting of people to discuss and/or perform practical work in a subject or activity:', 'a drama/poetry/training workshop
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15023, 'networking', 'the activity of meeting people who might be useful to know, especially in your job:', 'Students find networking essential to getting the right job.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15024, 'workshop', 'a meeting in which people discuss and show how to do a job or perform an activity, so that everyone can learn:', 'a teacher-training workshop', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15025, 'fuse', 'to melt or make two things melt together, especially at a high temperature:', 'The heat of the fire fused many of the machine''s parts together.', 'verb I, T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15026, 'fellow', 'a member of a group of teachers of high rank at a particular college or university or of particular academic societies:', 'Georgia''s a fellow of Clare College, Cambridge.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15027, 'fellow', 'a member of an official organization for a particular subject or job:', 'He''s a fellow of the Royal Institute of Chartered Surveyors.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15028, 'fellow', 'a member of some groups that you must have special training to join:', 'Dr. Rodriguez is a Fellow of the American College of Physicians.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15029, 'on', 'used to show when someone is a member of a group or organization:', 'Have you ever served on a jury?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15030, 'one', 'a member of a group of people or things:', 'One of their daughters has just had a baby.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15031, 'cache', 'an area or type of computer memory in which information that is often in use can be stored temporarily and got to especially quickly:', '256 Kb secondary cache', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15032, 'ghost', 'a memory, usually of something or someone bad:', 'The ghost of the old dictator still lingers on.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15033, 'hazy', 'not remembering things clearly:', 'hazy memories of childhood', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15034, 'conditioning', 'the process of training or influencing a person or animal mentally so that they do or expect a particular thing without thinking about it:', 'Conditioning starts as soon as boys are given guns to play with and girls are given dolls.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15035, 'psychic', '(especially of an illness) of the mind rather than the body:', 'psychic problems', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15036, 'psychical', 'relating to or happening in the mind rather than in the body:', 'Yoga was an effort to attain perfection through the control of the different elements of human nature, physical and psychical.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15037, 'trance', 'a temporary mental condition in which someone is not completely conscious of and/or not in control of himself or herself:', 'First she goes/falls into a deep trance, and then the spirit voices start to speak through her.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15038, 'maturity', 'the state of being mentally and emotionally well-developed, and therefore responsible:', 'It takes maturity to be a leader.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15039, 'bipolar', 'affected by bipolar disorder (= a mental health condition in which a person can at times be very depressed and at other times very excited and energetic):', 'I now realize I have been bipolar since my teens.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15040, 'cracked', 'an offensive word to describe someone who has a mental health condition, or who does not behave in a reasonable way :', 'The neighbours thought he was cracked.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15041, 'cracked', 'silly or stupid:', 'In my opinion, that''s a totally cracked idea.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15042, 'unipolar', 'relating to or experiencing periods of either depression or mania but not both:', 'Unipolar depression can involve anxiety and other symptoms - but no manic episodes.', 'adjective', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15043, 'madness', 'a word for mental illness, which was used by doctors in the past but is now offensive:', 'She felt as if she were sliding into madness.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15044, 'mania', 'a state in which someone directs all their attention to one particular thing:', 'Van Gogh suffered from acute persecution mania.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15045, 'vision', 'an idea or mental image of something:', 'We see in his novels his sinister, almost apocalyptic, vision of the future.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15046, 'vision', 'an experience in which you see things that do not exist physically, when your mind is affected powerfully by something such as deep religious thought or drugs or mental illness:', 'She had visions in which the angel Gabriel appeared to her.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15047, 'vision', 'an imagined mental image of something:', 'We lack a vision of what love really is.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15048, 'image', 'a picture in your mind or an idea of how someone or something is:', 'I have an image in my mind of how I want the garden to be.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15049, 'image', 'the way that something or someone is thought of by other people:', 'The aim is to improve the public image of the police.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15050, 'image', 'a mental picture or idea that forms in a reader''''s or listener''''s mind from the words that they read or hear:', 'The poem is full of images of birth and new life.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15051, 'will', 'the mental power used to control and direct your thoughts and actions, or a determination to do something, despite any difficulties or opposition:', 'From an early age she had a very strong will.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15052, 'will', 'what someone wants to happen:', 'It was God''s will.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15053, 'will', 'the mental power used to control and direct your thoughts and actions, or a determination to do something, despite any difficulties or opposition:', '[ C ] He’ll need an iron will to stick to that diet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15054, 'will', 'Someone’s will is also what the person wants to happen:', '[ U ] I went there against my will.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15055, 'will', 'to try to make something happen by using your thoughts:', 'She willed herself to remain optimistic.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15056, 'anal', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15057, 'anally', 'in a way that relates to being too worried about being organized or tidy:', 'He anally straightens all the pens so that they''re exactly in line.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15058, 'high', 'not thinking or behaving normally because of taking drugs:', 'He was high on heroin at the time.', 'adjective', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15059, 'high', 'a period of extreme excitement or happiness when you feel full of energy, often caused by a feeling of success, or by drugs or alcohol or a religious experience:', 'Exercise gives you a high.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15060, 'agile', 'able to think quickly and clearly:', 'For a man of 80, he has a remarkably agile mind.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15061, 'psychically', 'in a way that relates to the mind rather than the body:', 'If we''re not physically exhausted, we''re psychically exhausted.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15062, 'mad', 'mentally ill, or unable to behave in a reasonable way; insane:', 'In his years as a prisoner of war, he often felt as if he might go mad.', 'adjective -er/-est only', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15063, 'maniac', 'a person who behaves in an uncontrolled way, not worrying about risks or danger:', 'Some maniac was running down the street waving a massive metal bar.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15064, 'schizo', 'a person with the medical condition of schizophrenia:', 'At the time he was treating schizos and depressives.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15065, 'schizo', 'having or relating to the medical condition of schizophrenia:', 'My mother''s current diagnosis is schizo affective disorder, bipolar type.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15066, 'unbalanced', 'mentally ill:', 'His relatives have said he became unbalanced after the death of his father.', 'adjective', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15067, 'gaga', 'unable to think clearly and make decisions because of old age:', 'My granny''s 94 and she''s a bit gaga.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15068, 'citation', 'law A citation is an official notice from a court of law:', '[ C ] The court could issue a citation against her for disclosing information.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15069, 'cite', 'to mention something as proof for a theory or as a reason why something has happened, or to speak or write words taken from a written work:', 'He cited a study of the devices as proof that the company knew they were dangerous.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15070, 'cite', 'To cite someone else’s words when speaking or writing is to use them:', 'If you cite too many writers, readers will wonder if you have any ideas of your own.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15071, 'cite', 'In law, a person or organization which is cited is named in a legal action:', 'The mine operator was cited with 33 violations of federal safety standards.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15072, 'reference', 'a mention of something:', 'Knowing what had happened, I avoided making any reference to (= mentioning) weddings.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15073, 'suggest', 'to mention an idea, possible plan, or action for other people to consider:', 'I suggested an Italian restaurant near the station for the party.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15074, 'suggest', 'to mention an idea, possible plan, or action for other people to consider:', 'They were wondering where to hold the office party and I suggested the Italian restaurant on Main Street.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15075, 'so', 'used to avoid repeating a phrase mentioned earlier:', '"I hope they stay together." "I hope so too."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15076, 'so', 'used to say that a situation mentioned earlier is correct or true:', '"Is it true that we''re not getting a pay increase this year?" "I''m afraid so."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15077, 'so', 'used to say that a fact that has just been stated is certainly true:', '"My eyes are slightly different colours." "So they are."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15078, 'so', 'used instead of repeating an adjective that has already been mentioned:', 'She''s reasonable to work with - more so than I was led to believe.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15079, 'so', 'used, especially by children, to argue against a negative statement:', '"You didn''t even see the movie." "I did so!"', 'adverb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
