  (15113, 'steel', 'a strong metal that is made by processing iron to remove some of the carbon:', 'steel doors/girders
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15114, 'sterling', '(of precious metal, especially silver) of a particular standard of purity:', 'a sterling silver candlestick', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15115, 'tarnished', 'If metal is tarnished it has become less bright or a different colour:', 'The photographs were in tarnished silver frames.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15116, 'untarnished', 'If metal is untarnished, it has not lost its shine:', 'The urn was encased in untarnished gold.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15117, 'shot', 'a mass of small metal balls that are shot from a gun:', 'Shotgun cartridges contain lead shot.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
