  (15857, 'snap', 'to quickly return to a previous place or condition:', 'After substantial losses last year, the company has snapped back to profitability (= started making profits again).', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15858, 'snap', 'If something snaps shut or is snapped shut, it closes quickly with a sudden sharp sound:', 'She snapped her book shut and got up to leave.
