  (15983, 'shake', 'short, quick movements from side to side that your body makes because you are ill, are frightened, or have drunk too much alcohol:', 'I watched her hands as she prepared coffee and she definitely had the shakes.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (15984, 'shake', 'the act of moving something backward and forward or up and down in quick, short movements:', 'Give the bottle a shake.
