  (15985, 'shake', 'The shakes is a condition in which most or all of your body moves slightly from cold, fear, or illness:', 'Just thinking about the upcoming interview gave him the shakes.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
