  (16971, 'steep', 'A steep rise or fall is one that goes very quickly from low to high or from high to low:', 'There has been a steep increase/rise in prices.', 'adjective', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (16972, 'steep', '(of a slope) rising or falling at a sharp angle:', 'The train slowed as it went up a steep incline.', 'adjective -er/-est only', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
