  (16979, 'sad', 'If something looks sad, it looks worse than it should because it is not being cared for:', 'Give those flowers some water - they''re looking a little sad.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
