  (17611, 'immediately', 'now or without waiting or thinking:', 'The plane began to turn to the left almost immediately after takeoff.', 'adverb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (17612, 'just', 'now, very soon, or very recently:', '"Where are you, Jim?" "I''m just coming."
