INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (17628, 'common denominator', 'a number that can be divided exactly by all the denominators (= numbers under the line) in a group of fractions:', '12 is a common denominator of 1/3 and 1/4.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (17629, 'count', 'to say numbers one after the other in order, or to calculate the number of people or things in a group:', 'Let''s count out loud (= speak the words) from one to ten.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (17630, 'count', 'to count the number of people present somewhere:', 'There look to be about 50 people here - I haven''t counted heads yet.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (17631, 'count', 'the act of counting, or the total number of things counted:', 'Having done a quick count, I find I''ve planted 25 different ferns.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (17632, 'count', 'the act of counting the votes in an election, or the event when this happens:', 'Early counts show Mr Adams in the lead.
