  (17636, 'count', 'when a particular number is reached:', 'On the count of three, I''d like you all to stand up.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (17637, 'cube', 'If you cube a number, you multiply it twice by itself:', '2 cubed (= 2 x 2 x 2) equals 8, and is written 23.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
