  (17657, 'multiple', 'a number that can be divided by a smaller number an exact number of times:', '18 is a multiple of 3, because 18 = 3 x 6.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
