  (18282, 'position', 'a way of thinking about a particular matter; opinion:', 'Our position is that we’ve made a very fair offer to settle this dispute.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
