INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (18335, 'counter', 'to react to something with an opposing opinion or action; to defend yourself against something:', '[ T ] To counter the inaccuracies in the movie, researchers used computer models to project climate changes.', 'verb I/T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (18336, 'object', 'to feel or express opposition, dislike, or disapproval:', '[ I ] I don’t think anyone will object to leaving early.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (18337, 'anti-crack', 'opposed to or not allowing the use of the illegal drug crack cocaine :', 'His songs have a strong anti-crack message.
