  (19157, 'engineer', 'a person specially trained to design and build machines, structures, and other things, including bridges, roads, vehicles, and buildings:', 'He is an engineer at a large electronics company.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19158, 'excited', 'feeling very happy and enthusiastic:', 'An excited crowd waited for the singer to arrive.
