  (19579, 'exposure', 'one of the positions in a strip of film that can produce a photograph:', 'Get a roll of film with 36 exposures.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19580, 'focused', 'clear:', 'a focused image', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19581, 'grain', 'the pattern of extremely small spots of black and white or colour, that form a photographic or film image, or one of these small spots:', 'fine/coarse-grain film', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19582, 'negative', 'a piece of film from which a photograph can be produced, and in which light and dark areas appear the opposite to the way in which they appear in the photograph:', 'black-and-white/colour negatives
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19583, 'overexpose', 'to give too much light to a piece of photographic film when taking a photograph:', 'Unfortunately the light was too bright and my pictures were all overexposed.
