  (19734, 'Wimbledon', 'an area in the southwest of London:', 'They were living in Wimbledon, one of the capital''s most expensive suburbs.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19735, 'about', 'in or near a place:', 'Is John about (= somewhere near)?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19736, 'address', 'the specific place where a person, business, or organization can be found and where mail can be received:', 'What is your street address now?
