  (19737, 'address', 'An address is also a group of letters or numbers and an @ symbol used to send electronic mail to someone:', 'My e-mail address is pjh17@cambridge.org.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19738, 'address', 'to write or print the specific place where a person, business, or organization can be found on something to be sent there:', 'I addressed envelopes all morning.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19739, 'age', 'used to form nouns that are names of places:', 'orphanage
