  (19740, 'approachable', 'If a place is approachable, you can reach it or get near to it:', 'It''s one of the few lakeside villages approachable by car.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19741, 'area', 'a particular part of a place, piece of land, or country:', 'All areas of the country will have some rain tonight.
