INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (19884, 'quarantine', 'a period of time in which people or animals are not allowed to enter or leave a particular area or building where some or all of those in it have been affected by a harmful substance or disease, until the danger of harming others has passed:', 'Two farms north of the city were placed under quarantine due to an anthrax outbreak among livestock.
