INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (20012, 'quarantine', 'a period of time in which something such as a product or plant that is infected or poisonous, or that contains substances that could be dangerous, is kept in a place where it cannot harm anyone or anything until it is no longer dangerous or can be dealt with safely:', 'Oregon has imposed an emergency quarantine on oak firewood from California to slow the spread of the fungus.
