  (20110, 'gas', 'to kill or injure a person by making them breathe poisonous gas:', 'Hundreds of thousands of soldiers were gassed in the First World War.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (20111, 'venomous', 'A venomous snake, insect, etc., produces venom (= a poisonous liquid that can be put into another animal''''s body by biting or stinging):', 'Possible hazards include mosquitoes, sandflies, and venomous snakes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (20112, 'toxic', 'poisonous:', 'toxic waste/chemicals/effluent', 'adjective', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
