INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (20451, 'nuclear', 'being or using the power produced when the nucleus of an atom is divided or joined to another nucleus:', 'nuclear energy/power
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (20452, 'nuclear', 'relating to weapons, or the use of weapons, which use the power produced when the nucleus of an atom is divided or joined to another nucleus:', 'a nuclear war/attack
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (20453, 'puissance', 'great strength, power, or influence:', 'a King of high degree, a lord of power and puissance', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
