  (20454, 'spell', 'a magic power produced by speaking a set of words or taking a specific set of actions:', 'He was placed under a spell that could be broken only when the princess kissed him.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (20455, 'strength', 'the ability to do things that need a lot of physical or mental effort:', 'She had the strength and stamina to take the lead and win the gold medal.
