INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (20461, 'virile', 'powerful, strong, and energetic:', 'In this role, Durante is able to give full expression to that wonderfully virile voice.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (20462, 'virility', 'strength or power:', 'a country''s economic virility', 'noun U', NULL, NULL, 'approving', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
