  (20471, 'establishment', 'An establishment is a particular place of business:', 'Visitors come to shop in the fashionable new establishments downtown.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (20472, 'forcibly', 'in a way that has a strong effect:', 'They will all argue forcibly that poor people need more money.
