  (21144, 'repulse', 'to push away or refuse something or someone unwanted, especially to successfully stop a physical attack against you:', 'The enemy attack was quickly repulsed.', 'verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21145, 'stick', 'to push a pointed object into or through something, or (of a pointed object) to be pushed into or through something and stay there:', 'She stuck the needle into my arm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21146, 'stick', 'to push something pointed into or through something, or to be pushed into or through something:', '[ T ] I simply cannot watch when someone sticks a needle in my arm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
