INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21335, 'who', 'used especially in questions as the subject or object of a verb, when asking which person or people, or when asking what someone''''s name is:', 'Who did this?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21336, 'who', 'used with verbs that relate to knowing, when you want to say that something is not known:', '"Are they going to get married?" "Who knows?" (= It is not possible to know at the moment.)
