  (21340, 'fast', 'used to describe something that is full of speed and excitement:', 'It''s not a relaxing movie - it''s pretty fast and furious.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21341, 'fast', 'moving or happening quickly or able to move or happen quickly:', 'a fast car
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21342, 'mercurial', 'changing suddenly and often:', 'a mercurial temperament
