INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21769, 'pulse', 'the regular beating of the heart, especially when it is felt at the wrist or side of the neck:', 'The child''s pulse was strong/weak.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21770, 'pulse', 'a short period of energy that is repeated regularly, such as a short, loud sound or a short flash of light:', 'The data, normally transmitted electronically, can be changed into pulses of light.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21771, 'pulse', 'the action of switching power on and off again quickly on a food processor (= an electric machine that cuts and mixes food) to mix food:', 'Give the mixture a pulse or two until it is broken down.
