INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21821, 'close', 'having direct family connections or shared beliefs, support, and sympathy:', 'There weren''t many people at the funeral - just close family/relatives.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21822, 'close', 'People who are close know each other very well and like each other a lot, or they see and talk to each other a lot:', 'Mira is one of my closest friends.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21823, 'closely', 'in a way that is directly connected or has a strong relationship:', 'English and German are closely related.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21824, 'closeness', 'the quality of knowing someone very well, liking them a lot, and wanting to spend a lot of time together:', 'A special closeness is supposed to exist between twins.', 'noun U', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21825, 'connect', 'to feel close to someone or have a good relationship with them:', 'She has a remarkable ability to connect with a wide variety of people.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21826, 'liaison', 'a sexual relationship, especially between two people not married to each other:', 'He''s had a number of liaisons.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21827, 'live in', 'A live-in sexual partner lives in someone''''s home but is not married to that person:', 'a live-in lover', 'adjective before noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21828, 'on-off', 'that is not continuous; that stops and starts again:', 'an on-off romance
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21829, 'reconnect', 'to improve a relationship that has become less good or less close:', 'The candidate is making an effort to reconnect with rural voters.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21830, 'reconnect', 'to make you feel or understand something that you had stopped feeling or understanding:', 'Traditional celebrations reconnect us with history.', 'verb I, T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21831, 'separate', 'to start to live in a different place from your husband or wife because the relationship has ended:', 'My parents separated when I was six and divorced a couple of years later.', 'verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21832, 'tight', 'If two people are tight, they know each other very well and like each other a lot:', 'The two of them were pretty tight at school.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21833, 'two-way', 'A two-way situation involves two people or two groups of people working together to achieve a shared aim:', 'Negotiations are a two-way thing - both sides have to come to a compromise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21834, 'with', 'relating to or in the case of a person or thing:', 'How are things with you?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21835, 'lounge', 'to stand or sit in a relaxed way:', 'She was lounging on the beach.', 'verb I', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21836, 'mellow', '(of a person or mood) to become more relaxed and pleasant:', '[ I ] She used to be very impatient, but she’s mellowed.', 'verb I/T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21837, 'rest', 'to stop being active for a period of time in order to relax and get back your strength, or to cause someone or something to stop doing an activity in order to get back strength:', '[ I ] We hiked for five miles and then rested for a while.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21838, 'rest', 'At rest means not doing anything active or not moving:', 'The cat seemed coiled to spring, even when it was at rest.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21839, 'unwind', 'to relax and allow your mind to be free from worry after a period of work or some other activity that has made you worried:', 'A glass of wine in the evening helps me to unwind after work.', 'verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21840, 'unwind', 'to relax after a period of work or anxiety:', 'I’m just going to watch some TV and unwind.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21841, 'casualization', 'the process of something such as people''''s clothes or behaviour becoming less formal and more relaxed:', 'By the late 1990s, the casualization of our wardrobes was entrenched.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21842, 'decompression', 'the process of relaxing:', 'Last weekend we were all in need of a little decompression.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21843, 'chill', 'relaxed:', 'We''re a lot more chill about this than our parents were.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21844, 'mellow', 'relaxed and pleasant or not severe:', 'a mellow mood/atmosphere
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21845, 'mellow', '(of a person or mood) relaxed and pleasant:', 'He looks mellow on stage, but he’s always tense before the show.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21846, 'chill room', 'a room that people can use to relax in, for example at a dance club or office:', 'The club has three rooms, a chill room, and two dance floors.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21847, 'free', 'to release someone from something that is unwanted or unpleasant:', 'He longed to be freed of all his obligations.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21848, 'free', 'to release someone or something from limits or controls:', '[ + to infinitive ] The inheritance freed him to travel.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21849, 'free', 'to allow someone to leave a prison or place where they have been kept:', 'The hostages were all freed.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21850, 'drainer', 'a frame made of plastic, metal, or wood, placed on the surface next to a sink to hold things while they dry:', 'Jim washed up his cup carefully and placed it in the plastic drainer.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21851, 'drainer', 'a surface next to a sink where plates, knives, forks, etc. are left to dry after they have been washed:', 'The sink is stainless steel with an integral stainless steel drainer.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21852, 'drainer', 'a container with holes for letting liquid run out of something:', 'This is a very clever vegetable drainer which clips on to pans so you do not need a colander.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21853, 'drainer', 'a person whose job is to drain water (= allow it to flow away) from an area:', 'He was working as a drainer on a building site.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21854, 'Marian', 'relating to the Virgin Mary, the mother of Jesus Christ:', 'a Marian prayer', 'adjective', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21855, 'adore', 'to worship:', 'Let us adore God for all his works.', 'verb T, not continuous', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21856, 'cult', 'a religious group, often living together, whose beliefs are considered extreme or strange by many people:', 'Their son ran away from home and joined a religious cult.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (21857, 'cult', 'a particular system of religious belief:', 'the Hindu cult of Shiva', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
