  (21999, 'detoxified', 'to stop using drugs or alcohol or eating certain foods for a period of time in order to get rid of harmful substances from your body:', 'The idea of the diet was to detoxify the body.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (22000, 'lubricate', 'to make a process happen easily and without problems, especially by giving money:', 'Money can lubricate a deal by making minor concessions easier to accept.
