  (22002, 'snowplough', 'to remove or deal with problems for a child, so they never have to do anything difficult or never fail, and do not learn how to do things for themselves:', 'Are you snowploughing your kid?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (22003, 'snowplow', 'to remove or deal with problems for a child, so they never have to do anything difficult or never fail, and do not learn how to do things for themselves:', 'Are you snowplowing your kid?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
