  (22006, 'purge', 'to get rid of something unwanted, harmful, or evil:', 'Roman Catholics go to confession to purge their souls/themselves (from/of sin).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (22007, 'bail', 'to remove water from a boat using a container:', 'The boat''s sinking! Start bailing quickly!', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
