INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (22023, 'snowploughing', 'the behaviour of a parent who removes or deals with problems for a child, so they never have to do anything difficult and never fail, and do not learn how to do things for themselves:', 'Snowploughing is the new parenting trend that is ruining children''s lives.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (22024, 'snowplowing', 'the behavior of a parent who removes or deals with problems for a child, so they never have to do anything difficult and never fail, and do not learn how to do things for themselves:', 'Snowplowing is the new parenting trend that is ruining children''s lives.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (22025, 'stripping', 'the act of taking off all of your clothes, or of taking off all of another person''''s clothes:', 'Everyone has to go through the process of stripping and showering before they can have any contact with the test animals.
