  (22027, 'shelling', 'the act of removing the hard outer covering of something, especially nuts, eggs, or some vegetables:', 'The shelling of peanuts and corn was always done for days and usually lasted long into the nights.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (22028, 'purging', 'the act of getting rid of people from an organization because you do not agree with them :', 'He then announced a large-scale purging of the federal police.
