  (22029, 'purging', 'the act of taking names off an official list, sometimes in a way that is not legal :', 'The purging of the voters'' roll appears to have disproportionately affected black voters.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (22030, 'lubrication', 'the act of making a process happen easily and without problems:', 'A cut in the discount rate is a little lubrication for the system.
