  (22412, 'stack', 'a tall piece of rock sticking out of the sea near the coast, formed by the action of the waves against the rock on the coast:', 'The Twelve Apostles is the name of a series of limestone stacks protruding dramatically from the sea.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
