  (22706, 'hint', 'to say or do something that shows in an indirect way what you think or want:', '[ + that clause ] My parents have hinted that they’ll pay for a European vacation after I graduate from college.', 'verb I/T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
