  (22889, 'sound', 'to seem like something, from what is said or written:', 'That sounds like a good idea.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (22890, 'sound', 'to seem angry, happy, rude, etc. when you speak:', 'He sounded very depressed when we spoke on the phone yesterday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (22891, 'sound', 'to suggest a particular feeling, state, or thing by the way something is said or a noise is made:', '[ L ] He sounded rather discouraged when I called him yesterday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
