  (23353, 'stern', 'the back part of a ship or boat:', 'The Red Ensign, the flag of the British Merchant Navy, is rarely seen these days except on the sterns of a few cruise liners and cross-Channel ferries.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23354, 'sub', 'short for submarine: a ship that can travel underwater:', 'a nuclear sub', 'noun C', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23355, 'supercarrier', 'a very large aircraft carrier (= a large ship that carries military aircraft and has a long, flat surface where they take off and land):', 'The nuclear-powered supercarrier will take part in exercises in the north Atlantic.
