INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23437, 'shorty', 'a short person:', 'That coat reaches your ankles, shorty!', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23438, 'stop', 'a short period of time when you stay at a place, or the place where you stay:', 'It was a five-hour drive including a 30-minute stop for lunch.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23439, 'stop', 'A stop is a place where a bus or train pauses to allow passengers to get off and on:', 'I’m getting off at the next stop.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23440, 'briefly', 'for a short time:', 'We chatted briefly about the weather.', 'adverb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23441, 'moment', 'a very short period of time:', 'Can you wait a moment?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23442, 'moment', 'a very short period of time:', 'Hold still for a moment while I tie your shoe.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23443, 'tick', 'a very short time:', 'Hold on/Hang on a tick - I''m not quite ready.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23444, 'contract', 'to make or become shorter or narrower, or smaller:', '[ I ] When wet fibers dry, they contract.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23445, 'telescope', 'to shorten something:', 'Redford telescoped decades of history into a two-hour TV show.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23446, 'abridgment', 'a book, play, or piece of writing that has been made shorter by removing some details or less important information:', 'The books are abridgments of well-known classics.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23447, 'abridgment', 'the act of making a book, play, or piece of writing shorter by removing some details or information:', 'Drastic abridgment makes this story even more difficult to understand.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23448, 'could', 'used for saying, especially angrily, what you think someone else should do:', 'Well, you could try to look a little more enthusiastic!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23449, 'could', 'used for saying what you think someone else should do:', 'You could try to look a little more enthusiastic.', 'modal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23450, 'might', 'used to suggest, especially angrily, what someone should do to be pleasant, correct, polite, etc.:', 'You might at least try to look like you''re enjoying yourself!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23451, 'might', 'used to suggest, esp. angrily, what someone should do to be pleasant or polite:', 'You might at least try to look like you’re enjoying yourself!', 'modal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23452, 'shrug', 'the action of raising and lowering your shoulders to express something:', '"I''m afraid there''s nothing I can do about your problem," she said with a shrug.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23453, 'bawl', 'to shout in a very loud voice:', 'She bawled at me to sit down.', 'verb I, T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23454, 'cheer', 'a loud shout of approval or encouragement:', 'Her speech was received with cheers and a standing ovation.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23455, 'cry', 'to call out loudly:', '[ + speech ] "Watch out!" she cried.', 'verb I, T', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
