  (23498, 'run', 'If a film is running at a particular place, you can see it there:', 'What''s running at the the Metro this week?', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23499, 'run', 'to show something in a newspaper or magazine, or on television:', 'Both parties are already running campaign ads.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
