INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (23502, 'splash', 'to print or show something, or be printed or shown, in a very noticeable way:', 'Several newspapers splashed colour pictures of the star across their front pages.
