INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24616, 'cup', 'a specially designed cup, usually with two handles and often made of silver, given as a prize in a sports competition or in a game or match in which the winner receives such a cup:', 'Sheila won this cup in the school squash championship.
