INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24621, 'goal', 'an area on a playing field, that usually has two posts with a net fixed behind them, where players try to send the ball in order to score in sports such as football and hockey:', 'Black kicked/headed the ball into/towards the goal.', 'noun C', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24622, 'goal', 'a point scored in some sports, such as football and hockey, when a player gets the ball into this area:', 'Brazil won by three goals to one.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24623, 'goal', 'to be the player who tries to prevent the other team from scoring goals:', 'Who is playing in goal for Milan this evening?', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24624, 'goal', 'a goal area that has been left without any defenders:', 'Young rolled the ball across the six-yard box for Rooney to tap the ball into the open goal.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24625, 'group', 'a number of football teams who play each other in a competition. The winners of the group move onto the next stage of the competion :', 'The Danes were the surprise winners of their group.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24626, 'group', 'the first part of a football competition in which teams are divided into groups and play only the other teams in their group. The winners of each group move onto the next stage of the competition:', 'The team failed to progress beyond the group stages of Euro 2012.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24627, 'grubber', 'in rugby, a forward kick of the ball along the ground:', 'Jon Greene''s grubber was crucial in England''s win over Australia.
