  (24633, 'league', 'a group of teams playing a sport who take part in competitions between each other:', 'Who do you think will win the league championship this year?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24634, 'logroll', 'to take part in logrolling (= a sport in which two people try to stay standing on a floating tree branch or other long, rounded object, while trying to make the other person fall off):', 'Want to learn how to logroll? Here''s what you do: Put a log in the water, then stand on top of it.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24635, 'logrolling', 'a sport in which two people try to stay standing on a floating log (= a thick piece of a tree trunk or branch), or other long, rounded object, while trying to make the other person fall off:', 'The group''s eventual goal is to bring logrolling to the Olympics.
