  (24647, 'seeded', 'especially of a tennis player, given a place on the list of those expected to win games in a particular competition because of the way they have played in the past:', 'seeded players', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24648, 'seeded', 'being seeded in the position mentioned:', 'The fifth-seeded Browne crushed the defending champion.', 'suffix', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24649, 'shoot', 'to try to score points for yourself or your team, in sports involving a ball, by kicking, hitting, or throwing the ball towards the goal:', 'He shot from the middle of the field and still managed to score.', 'verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24650, 'shot', 'a kick, hit, or throw of the ball that is intended to score points in a sport such as cricket, football, tennis, or golf:', 'And that was a great shot by Márquez!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24651, 'sideline', 'a line that shows the position of the side of an area where a sport is played:', 'The ball fell just inside/on/outside the sideline.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24652, 'signing', 'in sport, a player who has signed a legal agreement to play for a team:', 'The club''s summer signings will take time to settle in.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24653, 'skeleton', 'a small toboggan (= an object used for sliding over snow and ice) for one person, ridden with the person lying on their front with their head first:', 'She found herself riding the thin skeleton sled down a steep, ice-covered track at speeds as high as 80 mph.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24654, 'skeleton', 'the sport or event of using a skeleton to race down a track made of ice:', 'The skeleton has been one of the best events at the Winter Olympics for the Great Britain team.
