  (24678, 'field', '(in baseball) to catch or pick up the ball after it has been hit in order to prevent the other team from scoring:', '[ T ] He fielded the ball cleanly and threw to first base.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
