  (24717, 'volley', '(in tennis and other sports) a hit to return a ball before it touches the ground:', 'I was ahead in the first game, but then hit a bad volley and a bad forehand.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24718, 'playability', '(of a surface on which sports are played) the quality of being easy to play on, or the degree to which a surface is like this :', 'Playability and ball bounce are two of the advantages of the Omnicourt Pro tennis court.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24719, 'playable', 'If a surface on which sports are played is playable, it is easy or possible to play on:', 'The tennis courts were a little worn but very playable.
