INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24724, 'mace', 'a brand name for a type of chemical in a container that, when sprayed (= forced out in small drops) into a person''''s face, causes pain in the eyes and tears to be produced:', 'When the clerk confronted the man, he sprayed her with mace.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24725, 'carried', 'to take something from one person or thing and give it to another person or thing:', 'Malaria is a disease carried by mosquitoes.', 'verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24726, 'carrier', 'someone who does not suffer from a disease but has the infection or genetic fault that causes it and can give the disease to someone else:', 'There are an estimated 1.5 million HIV carriers in the country.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24727, 'carry', 'to take something from one person or thing and give it to another person or thing; to spread:', 'The mosquitoes will be studied to see if they carry the virus.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24728, 'diffuse', 'spread out and not directed in one place:', 'a diffuse light
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24729, 'fly', 'If rumours, accusations, etc. fly, they are passed quickly from one person to another and cause excitement:', 'Rumors are flying that the school may close.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24730, 'propagate', 'to spread opinions, lies, or beliefs among a lot of people:', 'The government have tried to propagate the belief that this is a just war.
