  (24893, 'snitch', 'to steal, or to take without permission:', 'I snitched a pencil from your desk – hope you don’t mind.', 'verb', NULL, NULL, 'infml', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24894, 'swipe', 'to steal:', 'Okay, who swiped my keys?', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24895, 'swipe', 'to steal:', 'He was trying to swipe a sweatshirt.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24896, 'puffer', 'a steamboat (= a boat that is driven by steam):', 'The puffer was lying over slightly to one side and her mast lay at an awkward, unnatural angle.
