  (24897, 'puffer', 'a steam train (= a train pulled by an engine powered by steam):', 'The venerable puffer will make three excursions a day between York and Scarborough from 20 July to 31 August.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
