  (24986, 'check', 'to stop someone from doing or saying something, or to prevent something from increasing or continuing:', 'They have begun to vaccinate children in an attempt to check the spread of the disease.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
