  (24987, 'check', 'to stop someone from doing or saying something, or to prevent something from increasing or continuing:', 'He started to interrupt but checked himself and said nothing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
