  (24990, 'cut', 'to stop someone from talking before they have finished what they were saying:', 'He started to explain, but she cut him short.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24991, 'cut', 'used to tell someone to stop talking or stop behaving in an annoying way:', 'Just cut it out! I''ve had enough of your time wasting.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24992, 'cut', 'to stop or interrupt something, or to stop working suddenly or cause this to happen:', '[ I always + adv/prep ] Since his illness he’s cut out eating sweets altogether.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (24993, 'cut', 'to stop or interrupt something suddenly, or to stop someone from speaking:', 'We were cut off in the middle of our phone conversation.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
