  (25310, 'keen', '(esp. of emotions and beliefs) strongly felt:', 'a keen interest in painting', 'adjective -er/-est only', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (25311, 'sharp', 'strongly felt:', 'As he leaned over, he felt a sudden, sharp pain in his lower back.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (25312, 'barrage', 'a structure that is built across a river to provide water for farming, to produce electricity, or to allow boats to travel more easily:', 'The proposed tidal barrage would generate enough electricity to supply 80,000 homes.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
