  (25836, 'floor', 'to surprise or confuse someone so much that they are unable to think what to say or do next:', 'I didn''t know what to say - I was completely floored.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
