  (26034, 'appropriation', 'the act of taking something such as an idea, custom, or style from a group or culture that you are not a member of and using it yourself:', 'The emergence of a global culture of hip hop raises issues of racial and cultural appropriation.', 'noun C, U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26035, 'on', 'showing that a drug is taken or used:', 'My doctor put me on antibiotics.', 'preposition', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26036, 'poaching', 'the catching and killing of animals without permission on someone else''''s land:', 'Poaching poses a huge threat to the survival of this rare animal.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26037, 'poaching', 'the act of taking and using something, usually an idea, for yourself unfairly or dishonestly:', 'The show was a shameless poaching of ideas.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26038, 'poaching', 'the act of persuading someone who works for someone else to come and work for you:', 'Poaching of staff was having a negative effect on the business.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26039, 'runner', 'someone who takes illegal drugs or weapons from one place to another:', 'a gun-runner', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26040, 'seizure', 'the action of taking something by force or with legal authority:', 'seizure of power/property/control
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26041, 'diversion', 'something that takes your attention away from something else:', 'Shoplifters often work in pairs, with one creating a diversion to distract the staff while the other steals the goods.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26042, 'diversion', 'an activity you do for entertainment:', 'Reading is a pleasant diversion.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26043, 'diversionary', 'taking your attention away from something else:', 'The proposal was dismissed as a diversionary tactic intended to distract attention from the real problems.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
