INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26045, 'deduction', 'an amount that is taken away from the money you are paid before you officially receive it:', 'After deductions, his taxable income is $30,000.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26046, 'removal', 'the act of taking something or someone away from somewhere or something:', 'stain removal
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26047, 'removal', 'the business of transporting furniture and other possessions when people move to a new home:', 'Does your firm do removals?', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26048, 'controlled', 'involving careful, intentional actions that limit risk or danger:', 'Police carried out a controlled explosion on a suspicious vehicle.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26049, 'controlled', 'not allowing your emotions to be strongly expressed or to influence your behaviour:', 'He says he is a far more controlled and thoughtful person than he was when he was younger.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26050, 'adoption', 'the act of legally taking a child to be taken care of as your own:', 'She was homeless and had to put her child up for adoption (= ask for the child to be taken by someone else as their own).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26051, 'adoption', 'the act of taking another person''''s child legally into your family to raise as your own child:', '[ C ] The agency handles about a hundred adoptions a year.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26052, 'absorption', 'the situation in which one company takes control of another so that they become one company:', 'Reports confirmed the absorption of Kode''s operations into DCM''s offices.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26053, 'drainer', 'something that takes a lot of power from a battery (= a device that produces electricity to provide power for phones, cars, etc.), so that in the end it uses it all up:', 'Just be aware that having some apps permanently connected on your phone can be a battery drainer.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26054, 'drainer', 'something or someone that uses a person''''s energy so that they feel very tired or less powerful:', 'Constantly having to prove yourself is an emotional drainer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26055, 'delivery', 'the act of taking goods, letters, or packages to people''''s houses or places of work:', '[ C ] The company gets two deliveries a day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26056, 'apprehension', 'the act of catching and putting a person under police control:', 'There’s an $8000 reward for the apprehension of the perpetrators.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26057, 'catch', 'the act of taking hold of something that is thrown or comes through the air:', '[ C ] The ball was hit well, but the centerfielder made a leaping, one-handed catch to end the game.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26058, 'catch', 'Catch is also the activity of throwing and receiving a ball with another person:', '[ U ] My kids are always begging me to play catch.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26059, 'absorption', 'the process of taking something into another substance:', 'Some poisonous gases can enter the body by absorption through the skin.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26060, 'absorption', 'the process by which a substance or object takes in a liquid, gas, waves, or chemical and makes it a part of itself:', 'Using a special numerical procedure, they calculated the absorption spectrum (= the range of light waves that are left when some have been absorbed by something that they passed through).', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26061, 'withdrawal', 'when you take money out of a bank account:', 'The bank became suspicious after several large withdrawals were made from his account in a single week.', 'noun', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26062, 'withdrawal', 'the process or action of a military force moving out of an area:', 'The commander-in-chief was given 36 hours to secure a withdrawal of his troops from the combat zone.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26063, 'joiner', 'someone who agrees to take part in an arrangement or become a member of an organization:', 'Recent joiners are in a worse position than existing members.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26064, 'joiner', 'a person who likes to get involved in activities with groups of people:', 'I don''t think you''ll persuade David to come along to tonight''s meeting - he''s not much of a joiner.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
