INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26067, 'drop off', 'an act of taking someone or something to a particular place, usually by car, and leaving them there:', 'The van belonged to a delivery driver making a drop-off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26068, 'drop off', 'a place where someone or something is brought, usually by car, and left:', 'Never dispose of antifreeze or paint thinner down the drain; take them to a hazardous waste drop-off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26069, 'filler', 'a short text or drawings used to fill extra space in a magazine or newspaper, or talk, music, etc. used to fill extra time in a radio or television broadcast:', 'We used the clip as a filler after one of our guests dropped out of the show.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
