INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26238, 'pilot', 'a programme that is made to introduce a new radio or television series and test how popular it is:', 'If you''d seen the pilot, you''d know why they decided not to make a complete series of programmes!', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
