  (26250, 'blind', 'used to refer to a scientific test in which either the people being tested or the person testing them, or both, do not know what is being tested:', 'In blind trials, users who were given both drugs orally were unable to distinguish between the effects of heroin and methadone.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
