  (26264, 'print', 'letters, numbers, or symbols that have been produced on paper by a machine using ink:', 'The title is in bold print.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26265, 'print', 'newspapers, books, and magazines:', 'The debate is still raging, both in print and online.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26266, 'print', 'If a book is in print, it is possible to buy a new copy of it, and if it is out of print, it is not now possible:', 'Is her work still in print?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26267, 'print', 'to produce writing or images on paper or other material with a machine:', 'The leaflets will be printed on recycled paper.
