  (26268, 'print', 'to include a piece of writing in a newspaper or magazine:', 'Some newspapers still refuse to print certain swear words.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26269, 'print', 'to produce a newspaper, magazine, or book in large quantities:', '20,000 copies of the novel will be printed in hardback.', 'verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
