  (26922, 'scoop', 'a tool with a handle and a curved, open end, used to dig out and move an amount of something:', 'an ice-cream scoop', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26923, 'scoop', 'A scoop is also the amount held by a scoop:', 'Just one scoop of mashed potatoes for me, please.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
