INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (26927, 'skimmer', 'a piece of equipment that records someone''''s credit card or bank account details so that their bank account can be used illegally:', 'They used a card skimmer at a cash machine to clone account details.
