INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27188, 'undercut', 'a cut shaped like a V that is made at the bottom of the trunk (= thick main stem) of a tree before it is cut down, to control the direction in which it falls :', 'The undercut is a V-shaped notch cut into the side of the tree in the direction of falling.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27189, 'branch', 'one of the parts of a tree that grows out from the main trunk and has leaves, flowers, or fruit on it:', 'bare/leafy/flowering branches
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27190, 'branch', 'one of the parts of a tree that grows out from the main trunk and has leaves, flowers, or fruit on it:', 'After the storm, the ground was covered with twigs and branches.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27191, 'weeping', '(of trees) having branches that hang down :', 'Weeping willows along the river bank dragged the tips of their branches through the water.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
