  (27234, 'court', 'to try to get something, especially attention or support from other people:', 'She courts publicity by inviting journalists to extravagant parties.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27235, 'pursue', 'to try very hard to persuade someone to accept a job:', 'The company has been pursuing Holton for some time, but so far he has rejected all their offers.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27236, 'pursue', 'to try to discover information about a subject:', 'We will not be pursuing this matter any further.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27237, 'pursue', 'to try very hard to persuade someone to have a relationship with you:', 'He''s been pursuing her for months and yet she''s so clearly not interested.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27238, 'crawl', 'to try hard to please in order to get an advantage:', 'I don''t like people who crawl.
