  (27672, 'yet', 'still; until the present time:', 'I haven''t spoken to her yet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27673, 'yet', 'the best, worst, etc. until now:', 'Of all the songs I''ve heard tonight, that''s the best yet.', 'adverb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
