  (27674, 'yet', 'until and including this time:', 'We haven''t needed extra staff as yet, but we may in the future.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27675, 'curious', 'unusual and therefore worth noticing:', 'A curious figure in a red cape and black boots darted into the building.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27676, 'edgy', 'unusual in a way that is fashionable or exciting:', 'edgy art installations', 'adjective', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27677, 'freak', 'extremely unusual or unlikely:', 'She died in a freak automobile accident.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27678, 'some', 'used before a noun and spoken with emphasis to show that something is unusual:', 'Some party that turned out to be – nobody showed up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27679, 'strange', 'unusual and unexpected, or difficult to understand:', 'He has some very strange ideas about women!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27680, 'strange', 'to feel uncomfortable and not normal or correct:', 'I hope that fish was all right - my stomach feels a little strange .', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27681, 'strange', 'not familiar, or difficult to understand; different:', 'We kept hearing strange noises coming from the attic.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27682, 'spectacle', 'an unusual or unexpected event or situation that attracts attention, interest, or disapproval:', 'It was a strange spectacle to see the two former enemies shaking hands and slapping each other on the back.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27683, 'spectacle', 'an unusual or unexpected event or situation that attracts attention:', 'an amazing/terrible spectacle
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27684, 'maverick', 'a person who thinks and acts in an independent way, often behaving differently from the expected or usual way:', 'a political maverick
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27685, 'freak', 'someone or something that is strange or unusual and not like others of its type:', 'In my school, everyone thought you were some kind of freak if you didn’t like sports.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
