  (27686, 'stretch', 'an unusual and sometimes difficult situation:', 'Playing two games in two days is a bit of a stretch for us, but I think we’ll make it.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27687, 'uncommon', '(esp. of a human quality) unusually large in amount or degree:', 'She’s a woman of uncommon kindness.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27688, 'waste', 'unwanted matter or material of any type, especially what is left after useful substances or parts have been removed:', 'This city produces 20 million tons of household waste each year.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27689, 'waste', 'unwanted matter or material of any type, esp. what is left after use:', '[ C ] hazardous/toxic wastes
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27690, 'peanut gallery', 'people who give unwanted or unhelpful advice or opinions:', 'As usual, the online peanut gallery was quick to criticize.', 'noun C, usually singular', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27691, 'threat', 'the possibility that something unwanted will happen, or a person or thing that is likely to cause something unwanted to happen:', '[ U ] A threat of rain is in today’s forecast.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27692, 'faint', 'to feel weak, as if you are about to become unconscious:', 'She felt faint with hunger.', 'adjective', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27693, 'top', 'in the highest or upper part:', 'She tripped over the top step and nearly fell.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27694, 'circle', 'an upper floor in a theatre or cinema where people sit to watch the performance:', 'Shall I get seats in the circle or in the stalls?', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27695, 'top', 'in the part nearest to the highest part; in the upper part:', 'The top few steps were damaged and broken.', 'adjective before noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27696, 'offend', 'to make someone upset or angry:', '[ + that ] I think she was offended that she hadn''t been invited to the party.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27697, 'oversensitive', 'too easily upset:', 'I think you''re being a little oversensitive - she didn''t mean it as a criticism.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27698, 'roil', 'to cause something to stop working in the usual or expected way:', 'Fears about Japan roiled world financial markets last week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27699, 'sensitive', 'easily upset by the things people say or do, or causing people to be upset, embarrassed, or angry:', 'Her reply showed that she was very sensitive to criticism.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27700, 'sensitive', 'A sensitive subject, situation, etc. needs to be dealt with carefully in order to avoid upsetting people:', 'Sex education and birth control are sensitive issues.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27701, 'sensitive', '(of a person) easily upset:', 'Tom is extremely sensitive about his hair.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27702, 'sensitively', 'in a way that involves becoming upset or angry easily:', 'Maybe I''m reacting too sensitively.', 'adverb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27703, 'sensitiveness', 'the quality of being easily upset by the things people say or do:', 'Because of her sensitiveness, she had few friends.
