  (27704, 'sensitiveness', '(of a subject, situation, etc.) the quality of needing to be dealt with carefully in order to avoid upsetting people:', 'I fully realize the sensitiveness of the issue.', 'noun U', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
