  (27780, 'push', 'To push is also to cause something to move or change in a stated direction:', '[ M ] Rising demand tends to push prices up.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27781, 'comb', 'to arrange your hair by pulling a comb through it:', 'She combed her hair and put on some lipstick.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27782, 'manipulate', 'to control something using the hands:', 'The wheelchair is designed so that it is easy to manipulate.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27783, 'manipulate', 'to treat a part of the body, using the hands to push back bones into the correct position and put pressure on muscles:', 'The doctor manipulated the base of my spine and the pain disappeared completely.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27784, 'anchor', 'to keep a boat from moving by dropping a heavy metal object attached to it by a rope or chain into the water so that it rests on the bottom:', '[ T ] We anchored our sailboat near the shore.', 'verb I/T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27785, 'substitute', 'to use something or someone instead of another thing or person:', 'You can substitute oil for butter (= use oil instead of butter) in this recipe.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27786, 'substitute', 'to perform the same job as another thing or person or to take their place:', 'Gas-fired power stations will substitute for less efficient coal-fired equipment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27787, 'cut', 'to break the surface of something, or to divide or make something smaller, using a sharp tool, especially a knife:', 'to cut a slice of bread
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27788, 'cultivate', 'to prepare land and grow crops on it, or to grow a particular crop:', 'Most of the land there is too poor to cultivate.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27789, 'recultivate', 'to prepare land for a second, third, etc. time and grow crops on it, or to grow a particular crop for a second, third, etc. time:', 'Many hectares of farmland have been recultivated since the unexploded mines have been defused.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27790, 'shout', 'to speak with a very loud voice, often as loud as possible, usually when you want to make yourself heard in noisy situations, or when the person you are talking to is a long way away or cannot hear very well:', 'There''s no need to shout, I can hear you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27791, 'shout', 'to express strong emotions, such as anger, fear, or excitement, or to express strong opinions, in a loud voice:', 'Dad really shouted at me when I broke the window.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27792, 'shout', 'to try to attract attention in a loud voice:', 'I heard them shouting for help, but there was nothing I could do.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27793, 'operate', 'to cut a body open in order to repair, remove, or replace an unhealthy or damaged part:', 'Doctors will operate on her tomorrow morning.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27794, 'thinking', 'the process of using your mind to understand matters, make judgments, and solve problems:', 'I’ve done some serious thinking about our relationship.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27795, 'bite', 'the act of using your teeth to cut and tear something, or the piece torn away:', 'He took a few bites of the chicken and drank some water.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27796, 'bite', 'A bite is also a sore place on the surface of your skin made by an insect:', 'mosquito bites', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27797, 'usage', 'the use of something, the way in which it is used, or how much it has been used:', 'The study tracks credit card usage over the last ten years.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27798, 'usage', 'the way in which words are used by the people who speak and write a particular language, or an example of such use:', '[ C ] We use African-American, which is the current preferred usage.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
