INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27800, 'force', 'to use physical strength or effort to make something move or open:', 'Move your leg up gently when you''re doing this exercise, but don''t force it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27801, 'force', 'to break a lock, door, window, etc. in order to allow someone to get in:', 'I forgot my key, so I had to force a window.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27802, 'force', 'to use physical strength or effort to make something move or open:', 'If the piece won’t fit in the hole, don’t force it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27803, 'force', 'To force a lock, door, window, etc., is to break it in order to get in:', 'I forgot my house key, so I had to force a window.', 'verb T', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27804, 'hose', 'to clean something with water:', 'They have to hose down the streets.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27805, 'push', 'to use physical pressure or force, especially with your hands, in order to move something into a different position, usually one that is further away from you:', 'Can you help me move this table? You push and I''ll pull.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27806, 'think', 'to use your mind to understand matters, make judgments, and solve problems:', 'I’ll have to think about this.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27807, 'consume', 'to use fuel, energy, time, or a product, especially in large amounts:', 'Our high living standards cause our current population to consume 25 percent of the world''s oil.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27808, 'consume', 'to eat or drink something:', 'He consumes huge amounts of bread with every meal.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27809, 'consume', 'to watch or read forms of media (= the internet, television, newspapers, magazines, etc.) or take in information from these:', 'The internet has completely changed how people consume media.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27810, 'consumed', 'to use fuel, energy, or time, especially in large amounts:', 'Our high living standards cause our current population to consume 25 percent of the world''s oil.', 'verb T', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27811, 'consumed', 'to eat or drink, especially a lot of something:', 'He consumes huge amounts of bread with every meal.', 'verb T', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
