  (27819, 'bite', 'When a fish bites, it swallows the food on the hook (= curved piece of wire) at the end of a fishing line:', 'The fish aren''t biting today.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27820, 'bite', 'to use your teeth to cut into something:', '[ I/T ] He bit (into) the apple.
