  (27821, 'bite', 'If an insect bites, it breaks the surface of the skin of a person and leaves a sore place:', '[ I ] We can’t eat outside tonight – the mosquitoes are biting.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27822, 'bite', 'A fish bites when it takes a fishing hook into its mouth:', '[ I ] We were on the lake all day, but the fish just weren’t biting.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
