INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27957, 'horn', 'a device on a vehicle that is used to make a loud sound as a warning or signal:', 'Angry drivers were honking their horns.', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27958, 'hybrid', 'a vehicle with an engine that uses both petrol and another type of energy, usually electricity:', 'Most car manufacturers now offer hybrids.', 'noun C', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (27959, 'hybrid', 'a bicycle that has a mixture of features of different specialized bicycles, so that it works well in a range of conditions:', 'You can rent hybrids, racers, or mountain bikes.
