  (28369, 'spirit', 'used to approve or encourage someone''''s positive attitude (= way of thinking) or action:', '"Come on, we can win this game." "That''s the spirit."', 'noun', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
