INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (28371, 'cultural', 'relating to the habits, traditions, and beliefs of a society:', 'The US is often accused of cultural imperialism.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (28372, 'culturally', 'in a way that relates to the habits, traditions, and beliefs of a society:', 'a culturally diverse society
