  (28567, 'forthcoming', 'friendly and helpful, willing to give information or to talk:', 'I had difficulty getting any details. He wasn''t very forthcoming.', 'adjective', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
