  (28575, 'carried', 'to win the support, agreement, or sympathy of a group of people:', 'The bosses'' plans to reorganize the company won''t succeed unless they can carry the workforce with them.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
