  (28576, 'carry', 'to win the support, agreement, or sympathy of a group of people:', 'Gore is expected to carry (= get the most votes in) the midwestern states.', 'verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 1);
