  (33357, 'give someone a hard time', 'to make things difficult or unpleasant for someone:', 'Her kids always give her a hard time when she takes them shopping.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33358, 'give someone a heads up', 'to tell someone that something is going to happen:', 'I just wanted to give you all a heads up that we will be talking about the first two chapters of the book tomorrow.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33359, 'give someone a leg up', 'to help someone to climb over something', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33360, 'give someone a leg up', 'to help someone to improve their situation, especially at work', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33361, 'give someone a mouthful', 'to shout something angry at someone, usually using offensive language:', 'A taxi driver wound down his window and gave the cyclist a mouthful.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33362, 'give someone a piece of your mind', 'to tell someone why you are angry with that person:', 'I’d like to give her a piece of my mind.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33363, 'give someone a piece of your mind', 'to speak angrily to someone about something they have done wrong:', 'I''m going to give that mechanic a piece of my mind if the car''s not fixed this time.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33364, 'give someone a run for his/her/their money', 'to not allow someone to win easily:', 'We''re going to give the other candidate a run for her money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33365, 'give someone a shout', 'to tell someone something:', 'Give me a shout when you''ve finished in the bathroom.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33366, 'give someone an inch and they''''ll take a mile', 'said about someone who has been given a small amount of power or freedom to do something, and then has tried to get a lot more', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33367, 'give someone evils', 'to look at someone in a way that shows you are angry or dislike them:', 'Complete strangers gave her evils in the street.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33368, 'give someone five', 'to hit someone''''s open hand with your own to celebrate doing something well or achieving something, especially in sports', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33369, 'give someone food for thought', 'to make someone think seriously about something', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33370, 'give someone grief', 'to criticize or mock (= laugh at) someone for something:', 'Jane gave me more grief than any other senator. She was constantly in my face.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33371, 'give someone grief', 'to cause someone pain or problems:', 'I injured my knee two years ago and it still gives me grief.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33372, 'give someone hell', 'If someone gives you hell, they criticize you severely:', 'She gave me hell for being 20 minutes late.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33373, 'give someone hell', 'If something gives you hell, it causes you a lot of pain:', 'These new shoes are giving me hell.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33374, 'give someone pause', 'to cause someone to stop and think about what they were doing or intending to do', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33375, 'give someone something to talk about', 'to provide someone with an interesting subject to discuss:', 'Our new car will give the neighbours something to talk about.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33376, 'give someone the benefit of the doubt', 'to believe something good about someone, rather than something bad, when you have the possibility of doing either:', 'I didn''t know whether his story was true or not, but I decided to give him the benefit of the doubt.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33377, 'give someone the cold shoulder', 'to intentionally ignore someone or treat someone in an unfriendly way:', 'I thought she really liked me, but the next day she gave me the cold shoulder.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33378, 'give someone the elbow', 'to end your romantic relationship with someone', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33379, 'give someone the finger', 'to show someone in an offensive way that you are angry with that person by turning the back of your hand towards them and putting your middle finger up', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33380, 'give someone the glad eye', 'to look at someone in a way that shows you find them sexually attractive:', 'All the men were giving her the glad eye.', 'idiom', NULL, NULL, 'old-fashioned, slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33381, 'give someone the heave-ho', 'to take someone''''s job away from them, usually because that person has done something wrong:', 'The newspaper''s foreign editor was given the heave-ho yesterday.', 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33382, 'give someone the heave-ho', 'to end a romantic relationship with someone', NULL, 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33383, 'give someone the jimjams', 'to make someone feel nervous or frightened:', 'Stop it. You''re giving me the jimjams.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33384, 'give someone the jitters', 'to make someone nervous or frightened:', 'Come away from that cliff edge! You''re giving me the jitters!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33385, 'give someone the push', 'to tell someone to leave their job:', 'I heard he''d been given the push.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33386, 'give someone the push', 'to end a relationship with someone:', 'Oh, give him the push - he''s a loser.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33387, 'give someone the shits', 'to annoy someone', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33388, 'give someone the time of day', 'If someone will not give you the time of day, they are unfriendly and refuse to speak to you:', 'We had an argument with our neighbours, and now they won''t even give us the time of day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33389, 'give someone what for', 'to speak angrily to someone whose behaviour you strongly disapprove of', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33390, 'give something a whirl', 'to attempt to do something, often for the first time:', 'I''ve never danced salsa before but I''ll give it a whirl.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33391, 'give something away', 'to give something to someone without asking for payment:', 'The shop is giving away a sample to every customer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33392, 'give something away', 'to tell people something secret, often without intending to:', 'The party was meant to be a surprise, but Sharon gave it away.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33393, 'give something away', 'to allow an opponent to score a goal or win a game by making a mistake or doing something very badly :', 'You can''t give away goals as easily as we did and win games at this level.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33394, 'give someone away', 'to show someone''''s secret feelings:', 'She thinks no one knows how much she likes him, but her face when I said he''d be there really gave her away!', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33395, 'give someone away', 'in a marriage ceremony, to formally bring a woman who is getting married to the front of the church so that she is standing at the side of her future partner, and then to give permission for her to marry:', 'The bride was given away by her father.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33396, 'give something back', 'to return something to the person who gave it to you:', 'Has she given you those books back yet?', 'phrasal verb', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33397, 'give something off', 'to produce heat, light, a smell, or a gas:', 'That tiny radiator doesn''t give off much heat.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33398, 'give something over to something/someone', 'to give another person the use of something, or the responsibility for something or someone:', 'We''ve given the attic over to the children.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33399, 'give something up as a bad job', 'to stop doing something because you do not feel it is worth continuing:', 'After three attempts to mend it, I gave it up as a bad job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33400, 'give something your best shot', 'to do something as well as you can', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33401, 'give something/someone a wide berth', 'to avoid a person or place:', 'I tend to give the city centre a wide berth on Saturdays because it''s so busy.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33402, 'give the game away', 'to spoil a surprise or a joke by telling someone something that should have been kept secret:', 'It''s a secret, so don''t give the game away, will you?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33403, 'give the green light to something', 'to give permission for someone to do something or for something to happen:', 'The council has given the green light to the new shopping centre.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33404, 'give the lie to something', 'to prove that something is not true:', 'The fact that the number of deaths from cancer in the area has doubled surely gives the lie to official assurances of the safety of nuclear power.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33405, 'give up', 'to stop trying to guess:', 'You''ll never guess the answer - do you give up?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33406, 'give up something', 'to stop owning, using, or claiming something:', 'They were forced to give up their home because they couldn''t pay the mortgage.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33407, 'give up something', 'to stop hoping that a particular thing will happen:', 'We still haven''t given up hope of finding her alive.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33408, 'give up (something)', 'to stop doing something before you have finished it, usually because it is too difficult:', '[ + -ing verb ] I''ve given up trying to help her.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33409, 'give (something) up', 'If you give up a habit, such as smoking, or something such as alcohol, you stop doing it or using it:', '[ + -ing verb ] I gave up smoking two years ago.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33410, 'give something up', 'to stop doing a regular activity or job:', '[ + -ing verb ] He''s given up driving since his illness.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33411, 'give something up', 'used to ask people to clap their hands to show their enjoyment or approval of a performance:', 'Ladies and gentlemen, will you give it up for Danny Jones.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33412, 'give someone up', 'to stop having a friendship with someone:', 'She seems to have given up all her old friends.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33413, 'give someone up', 'to stop expecting that someone will arrive:', 'I''ve been waiting half an hour - I''d almost given up on you.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33414, 'give someone up', 'to think that someone is certain to die or to be dead:', 'The doctors had virtually given her up for dead, but she eventually recovered.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33415, 'give yourself up', 'to allow the police or an enemy to take you as a prisoner:', 'The gunman gave himself up to the police.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33416, 'give up on someone/something', 'to expect someone or something to fail:', 'Most people gave up on him when he dropped out, but he went back and earned his degree two years later.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33417, 'give up the ghost', 'to die', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33418, 'give up the ghost', 'If a machine gives up the ghost, it stops working:', 'Our old TV had finally given up the ghost.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33419, 'give up the ghost', 'to stop trying to do something because you know that you will not succeed:', 'All I''d cherished from early childhood had been denied me, so I simply gave up the ghost.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33420, 'give voice to something', 'to express your thoughts or feelings in words:', 'I always had doubts about the project but I never gave voice to them.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33421, 'give way', 'to allow other vehicles to go past before you move onto a road:', 'You have to give way to traffic coming from the right.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33422, 'give way', 'to break, especially when under pressure from strong forces:', 'Because of an unusually strong current, the bridge''s central support gave way, tipping a coach into the river.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33423, 'give way', 'to stop arguing or fighting against someone or something:', 'Neither of them will give way, so they could be arguing for a very long time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33424, 'give way to something', 'to be replaced by something, especially because it is better, cheaper, easier, etc.:', 'In some areas, modern intensive farming is giving way to the re-introduction of traditional methods.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33425, 'give your head a shake', 'used to tell someone that they are being silly or unreasonable and should change the way they think about things:', 'Give your head a shake, people, and figure it out: more cars on the road is not the solution.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33426, 'give your life to something', 'to continue to have a close involvement in a particular thing for the whole of your life:', 'She gave her life to cancer research.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33427, 'give your right arm', 'If you say that you would give your right arm to do or have something, you mean you would like it very much:', 'I would give my right arm to meet the president.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33428, 'give your word', 'to promise:', 'He gave his word that he would marry her and she had no cause to doubt him.', 'idiom', 'C1', NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33429, 'give yourself over/up to something', 'to spend all your time and energy doing or feeling something:', 'After her death he gave himself over to grief.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33430, 'give/allow something full play', 'to develop and use emotions or ideas completely:', 'The move from stage to movies allowed Gildit to give full play to his sense of the fantastic.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33431, 'give/hand something to someone on a (silver) platter', 'to allow someone to get something very easily, without having to work for it:', 'If you sell your share in the company now, you''re handing the ownership to him on a silver platter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33432, 'give/hand something to someone on a plate', 'to allow someone to get or win something very easily:', 'They were handed the contract on a plate.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33433, 'give/lend someone a helping hand', 'to help someone:', 'These tax cuts will give industry a helping hand.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33434, 'given half a/the chance', 'If someone would do something given half a chance, they would certainly do it if the opportunity came up:', 'I''d give up work given half a chance.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33435, 'given the chance/choice', 'if I were allowed to, or if I could choose:', 'Given the chance, I''d spend all day reading.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33436, 'glam (yourself) up', 'to dress yourself attractively and put on make-up, etc.:', 'Have I got time to glam (myself) up?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33437, 'glance off (something)', 'to hit or touch something quickly and lightly at an angle and move away in another direction:', 'The bullets glanced off the car.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33438, 'glass something in/over', 'to use glass to fill the open spaces in something or to cover something:', 'We glassed in the porch to make a small conservatory.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33439, 'glom onto something/someone', 'to become very interested in something such as a new idea or fashion or in someone:', 'Retailers are glomming onto a new fashion among teens for outsize clothes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33440, 'glom onto something/someone', 'to get or take something that you want:', 'He glommed onto a couple of my comics and I can''t get them back from him.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33441, 'glory in something', 'to feel or show that you are very proud and happy about something:', 'He is still glorying in the success of his first Hollywood film.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33442, 'gloss over something', 'to avoid considering something, such as an embarrassing mistake, to make it seem not important, and to quickly continue talking about something else:', 'She glossed over the company''s declining profits.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33443, 'glued to something', 'giving something your full attention:', 'During football season, he’s glued to the TV.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33444, 'glued to the spot', 'unable to move because you are very frightened, nervous, or interested:', 'I just stood there, glued to the spot.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33445, 'gnash your teeth', 'to bring your teeth forcefully together when you are angry:', 'The monster roared and gnashed its teeth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33446, 'gnash your teeth', 'to complain angrily and noisily about something:', 'New Yorkers gnashed their teeth about the governor''s decision to raise property taxes.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33447, 'gnashing of teeth', 'angry noise and upset:', 'There has been much gnashing of teeth about the proposal to close the hospital.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33448, 'gnaw away at something', 'to gradually reduce or spoil something:', 'Bad debts are continuing to gnaw away at the bank''s profits.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33449, 'go (all) round the houses', 'to waste time doing or asking something in a very complicated way', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33450, 'go (all) round the houses', 'to take a route that is much longer than necessary:', 'I got the number 26 bus and that one goes all round the houses.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33451, 'go (and) jump in the lake', 'a rude way of telling someone to go away and stop annoying you:', 'He just wouldn''t leave me alone, so finally I told him to go jump in the lake.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33452, 'go (around) in circles', 'to do a lot or seem very busy without achieving anything:', 'We just keep going around in circles, talking without deciding anything.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33453, 'go (like/down) a bomb', 'to be very successful or popular:', 'The party''s really going a bomb, isn''t it?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33454, 'go AWOL', 'If something has gone AWOL, it is not in its usual place or has been stolen:', 'Two computers have gone AWOL from the office.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33455, 'go Dutch', 'to agree to share the cost of something, especially a meal', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33456, 'go a bundle on something', 'to like something very much:', 'usually in negative I don''t go a bundle on his taste in clothes.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33457, 'go a long way', 'If you say that someone will go a long way, you mean that they will be very successful.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33458, 'go a long way toward(s) doing something', 'to be very helpful:', 'The money raised will go a long way towards providing essential food and medicine.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33459, 'go about something', 'to begin to do something or deal with something:', 'What''s the best way of going about this?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33460, 'go about your business', 'to continue doing what you usually do:', 'In spite of last night''s terrorist attack, most people seem to be going about their business as if nothing had happened.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33461, 'go above and beyond (sth)', 'to do more or better than would usually be expected of someone:', 'He''s always been a good friend, but while I was ill he really went above and beyond.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33462, 'go after someone', 'to chase or follow someone in order to catch them:', 'The police went after him but he got away.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33463, 'go after something', 'to try to get something:', 'Are you planning to go after Paul''s job when he leaves?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33464, 'go against someone', 'If a decision or vote goes against someone, they do not get the result that they wanted:', 'The judge''s decision went against us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33465, 'go against something/someone', 'to oppose or disagree with something or someone:', 'Public opinion is going against the government on this issue.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33466, 'go against the flow', 'to do or say the opposite of what most people are doing or saying:', 'With this new book, she is going against the flow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33467, 'go against the grain', 'If something goes against the grain, you would not usually do it because it would be unusual:', 'These days it goes against the grain to show too much respect for authority.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33468, 'go ahead', 'to start to do something:', 'We''ve received permission to go ahead with the music festival in spite of opposition from local residents.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33469, 'go ahead', 'said to someone in order to give them permission to start to do something:', '"Could I ask you a rather personal question?" "Sure, go ahead."', 'phrasal verb', 'B2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33470, 'go ahead', 'If an event goes ahead, it happens:', 'The festival is now going ahead as planned.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33471, 'go all out', 'to put all your energy or enthusiasm into what you are doing:', 'The team went all out for a win.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33472, 'go all the way', 'to have sex, especially after a period of kissing and touching:', 'Did you go all the way last night?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33473, 'go along', 'to go to a place or event, usually without much planning:', 'I might go along to the party later.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33474, 'go along', 'as you are doing a job or activity:', 'We have a flexible approach to what we''re doing that allows us to make any necessary changes as we go along.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33475, 'go along with something/someone', 'to support an idea, or to agree with someone''''s opinion:', 'Kate''s already agreed, but it''s going to be harder persuading Mike to go along with it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33476, 'go and...', 'used to express disapproval of something that is done:', 'He''s gone and lost (= he has lost) that wallet I gave him for his birthday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33477, 'go ape', 'to become extremely angry:', 'She went ape because I was half an hour late.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33478, 'go around', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33479, 'go around (somewhere)', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33480, 'go around something', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33481, 'go arse over tit/tip', 'a rude phrase meaning to lose your balance suddenly and fall over:', 'I fell off my bike and went arse over tit.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33482, 'go ass over (tea)kettle', 'a rude phrase meaning to lose your balance suddenly and fall over', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33483, 'go at someone', 'to attack someone:', 'Suddenly, he went at me with a knife.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33484, 'go at something', 'to start doing something with a lot of energy and enthusiasm:', 'He went at (= ate eagerly) his dinner as if he hadn''t had anything to eat for weeks.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33485, 'go away', 'to leave a place:', 'Go away and leave me alone!', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33486, 'go away', 'to leave your home in order to spend time somewhere else, usually for a holiday:', 'We usually go away for the summer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33487, 'go away', 'to disappear:', 'It was weeks before the bruises went away.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33488, 'go back', 'to return:', 'That restaurant was terrible - I''m never going back there again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33489, 'go back', 'to be returned:', 'When are these library books supposed to go back ?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33490, 'go back', 'to have existed since a time in the past:', 'Their relationship goes back to when they were at college together.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33491, 'go back a long way', 'If people go back a long way, they have known each other for a long time.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33492, 'go back on something', 'to fail to keep a promise, or to change a decision or agreement:', 'The government looks likely to go back on its decision to close the mines.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33493, 'go back to sleep!', 'used to tell someone off for not paying attention:', '"Sorry, what did you say?" "Oh, go back to sleep!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33494, 'go back to someone', 'to start a relationship again with a person you had a romantic relationship with in the past:', 'I hear he''s ended the affair and gone back to his wife.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33495, 'go back to something', 'to start doing something again that you were doing before:', 'It''s time to go back to work.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33496, 'go back to the drawing board', 'to start planning something again because the first plan failed', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33497, 'go beet red', 'to have a red face because you are embarrassed:', 'Whenever I talked about his past life, he would go beet red.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33498, 'go begging', 'If something is going begging, it is available to be taken because no one else wants it:', 'If that bottle of wine is going begging, I''ll have it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33499, 'go belly up', 'If a company or plan goes belly up, it fails:', 'The business went belly up after only six months.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33500, 'go blank', 'to forget something that you know, often temporarily:', 'I went blank and couldn''t think of a single example.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33501, 'go by', 'to move past, in space or time:', 'You can watch the trains going by from this window.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33502, 'go by', 'in the past:', 'The house was a train station in days gone by.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33503, 'go by something', 'to follow something or be shown the way by something:', 'I''m sorry, madam, but we have to go by the rules.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33504, 'go by something', 'to base an opinion, decision, or judgment on something:', 'What do you go by when you''re deciding whether or not to employ someone?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33505, 'go by the board', 'to be forgotten or not used:', 'Does this mean our holiday plans will have to go by the board?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33506, 'go cap in hand to someone', 'to ask someone in a polite and sincere way for something, especially money or to be forgiven', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33507, 'go commando', 'to not wear any underwear', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33508, 'go dark', 'to stop all activities or communication, especially temporarily but for a fairly long period:', 'Theatres have gone dark, and arts groups have disbanded.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33509, 'go dark', '(of a spy or secret agent) to stop communicating for a period of time with the people you are secretly working for:', 'She was undercover and thought the gang were onto her, so she went dark.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33510, 'go down', 'to move down to a lower level or place:', 'He went down on his knees and begged for forgiveness.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33511, 'go down', 'to reach or go as far as:', 'Its roots can go down three metres.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33512, 'go down', 'When the sun goes down, it moves down in the sky until it cannot be seen any more:', 'On summer evenings we would sit on the veranda and watch the sun go down.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33513, 'go down', 'to be reduced in price, value, amount, quality, level, or size:', 'The temperature went down to minus ten last night.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33514, 'go down', 'to be remembered or recorded in a particular way:', 'Hurricane Katrina will go down in the record books as the costliest storm ever faced by insurers.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33515, 'go down', 'to be received in a particular way:', 'The joke didn''t go down very well.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33516, 'go down', 'to lose or be defeated:', 'England''s unbeaten run of ten games ended last night when they went down 4–2 to France.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33517, 'go down', 'If a football team goes down, it drops to a lower division (= group of teams who play each other):', 'At the end of the season, the three teams at the bottom go down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33518, 'go down', 'to be put in prison:', 'She went down for three years for her part in the robbery.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33519, 'go down', 'If a computer system goes down, it stops working:', 'The battery should prevent the computer system from going down in the event of a power cut.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33520, 'go down', 'If an event such as a crime or a deal goes down, it happens:', 'I tried to tell Tyrell what was going down, but he wouldn''t listen.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33521, 'go down', 'If you go down from a college or university, especially Oxford University or Cambridge University, you leave either permanently or on holiday.', NULL, 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33522, 'go down as/in something', 'to be remembered or recorded in a particular way:', 'Hurricane Katrina will go down as one of the worst storms of this century.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33523, 'go down in the annals', 'to be remembered as an important event, person, etc.:', 'Quite whether he will go down in the annals of American history as a great leader remains to be seen.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33524, 'go down like a lead balloon', 'If something that you say or show to people goes down like a lead balloon, they do not like it at all:', 'My joke about the alcoholic went down like a lead balloon.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33525, 'go down on someone', 'to use the tongue and lips to touch someone''''s sexual organs in order to give pleasure', NULL, 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33526, 'go down swinging/fighting', 'to continue to fight or to make a strong, determined effort even though you are likely to fail or lose:', 'They beat us in the end, but we went down swinging.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33527, 'go down the gurgler', 'If work or money goes down the gurgler, it is wasted:', 'So say he gives up his training, that''s four thousand dollars down the gurgler.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33528, 'go down the pan', 'to fail or to be lost or destroyed:', 'We don''t want to see our business go down the pan.', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33529, 'go down the tubes', 'to fail completely:', 'If business doesn''t pick up soon, the company will go down the tubes.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33530, 'go down the wrong way', 'If food or drink goes down the wrong way, it goes down the wrong tube in your throat and causes you to cough or stop breathing for a short time.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33531, 'go down with something', 'to start to suffer from an infectious disease:', 'Half of Martha''s class has gone down with flu.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33532, 'go downhill', 'to gradually become worse:', 'After his wife died, his health started to go downhill.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33533, 'go easy', 'to not take or use too much of something:', 'Go easy on/with the cream - I haven''t had any yet.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33534, 'go easy', 'to treat someone in a gentle way and not criticize them or punish them:', 'Go easy on the new students.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33535, 'go easy on someone', 'to treat someone in a gentle way, esp. when you want to be or should be more severe:', 'Do you think judges should go easy on criminals if they''re teenagers?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33536, 'go easy on something', 'to not take or use too much of something:', 'The doctor told me to go easy on the spicy food for a while.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33537, 'go far', 'to be very successful in the future:', 'She''s a very talented writer - I''m sure she''ll go far.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33538, 'go figure!', 'used when you tell someone a fact and you then want to say that the fact is surprising, strange or stupid:', 'It''s a terrible movie and it made $200 million. Go figure!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33539, 'go fly a kite', 'used to tell someone who is being annoying to go away', NULL, 'idiom', NULL, NULL, 'informal old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33540, 'go for broke', 'to risk everything in the hope of having great success', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33541, 'go for it', 'to do anything you have to in order to get something:', '"I''m thinking of applying for that job." "Go for it!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33542, 'go for someone', 'to attack someone:', 'Their dog had to be put to sleep after it went for the postwoman.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33543, 'go for something', 'to choose something:', 'Instead of butter, I always go for margarine or a low-fat spread.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33544, 'go for something', 'to like or admire:', 'I don''t go for war films in a big way (= very much).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33545, 'go for something', 'to try to have or achieve something:', 'She tripped me as I went for the ball.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33546, 'go for something', 'If something goes for a certain amount of money, it is sold for that amount:', 'The painting is expected to go for at least a million dollars.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33547, 'go for the jugular', 'to make a serious effort to defeat someone, usually by criticizing or harming them in a cruel way:', 'Cunningham went straight for the jugular, telling him that his work was a complete disaster.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33548, 'go from bad to worse', 'If a situation goes from bad to worse, it was difficult and unpleasant, and is becoming even more so:', 'Things have gone from bad to worse.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33549, 'go from strength to strength', 'to gradually become more successful:', 'The firm''s gone from strength to strength since the new factory was built.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33550, 'go gold', 'If a recording of a popular song, or of a collection of popular songs, goes gold, it sells a large number of copies.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33551, 'go great guns', 'to go fast or successfully:', 'For the first 400 metres he was going great guns, but then he fell and that lost him the race.', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33552, 'go hand in hand with something', 'If something goes hand in hand with something else, it is closely related to it and happens at the same time as it or as a result of it:', 'Prosperity goes hand in hand with investment.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33553, 'go hang (yourself)', 'You say that someone can go hang (himself or herself) if you do not care what that person says or does about something:', 'If she''s expecting the report by tomorrow, she can go hang.', 'idiom', NULL, NULL, 'informal, old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33554, 'go haywire', 'to stop working correctly:', 'They told us later in the hospital that his heart had gone haywire.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33555, 'go hog wild', 'to become too excited and eager about something, often so that you do too much:', 'There''s no need to go hog wild just because it''s Sarah''s birthday - she won''t want such a fuss.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33556, 'go in', 'to enter a place:', 'I looked through the window, but I didn''t actually go in.', 'phrasal verb', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33557, 'go in', 'If the sun goes in, it becomes hidden from view by clouds.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33558, 'go in', 'If a fact or piece of information goes in, you understand it or remember it:', 'No matter how many times you tell him something, it never seems to go in.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33559, 'go in for something', 'to do something regularly, or to enjoy something:', 'I''ve never really gone in for classical music, but I love jazz.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33560, 'go in for something', 'to take part in a competition:', 'Are you planning to go in for the 100 metres race?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33561, 'go in on something', 'to be involved in an activity that involves others:', 'He bought a jet for personal use, inviting three friends to go in on it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33562, 'go in one ear and out the other', 'If you say that something you hear goes in one ear and out the other, you mean you quickly forget it:', 'If I have to listen to something I don''t understand, it just goes in one ear and out the other.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33563, 'go into orbit', 'to increase or succeed very quickly or to be in a state of extreme activity:', 'Prices have gone into orbit this year.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33564, 'go into reverse', 'If a situation goes into reverse, it becomes the opposite of what it was before:', 'The trend towards home ownership has gone into reverse.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33565, 'go into rhapsodies', 'to express very great enthusiasm and admiration for something:', 'She went into rhapsodies over/about the chocolate cake.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33566, 'go into something', 'to start doing a particular type of work:', 'My son''s planning to go into journalism.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33567, 'go into something', 'to start an activity, or start to be in a particular state or condition:', 'The drug is still being tested and will not go into commercial production for at least two years.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33568, 'go into something', 'to discuss, examine, describe, or explain something in a detailed or careful way:', 'This is the first book to go into her personal life as well as her work.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33569, 'go into something', 'If time, money, or effort goes into a product or activity, it is used when producing or doing it:', 'A considerable amount of time and effort has gone into this exhibition.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33570, 'go into something', 'If a vehicle goes into something such as a tree or a wall, it hits it:', 'Their car was travelling at 50 miles an hour when it went into the tree.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33571, 'go into/enter the church', 'to become a priest:', 'He was in his thirties when he decided to enter the church.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33572, 'go it alone', 'to do something without other people:', 'He''s decided to leave the band and go it alone as a singer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33573, 'go like a bomb', 'to move very quickly:', 'His new car goes like a bomb.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33574, 'go native', 'If a person who is in a foreign country goes native, they begin to live and/or dress like the people who live there.', NULL, 'idiom', NULL, NULL, 'disapproving, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33575, 'go nuts', 'to become extremely angry:', 'My sister will go nuts when she finds out I crashed her car.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33576, 'go off', 'If a light or a machine goes off, it stops working:', 'The lights went off in several villages because of the storm.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33577, 'go off', 'If a bomb goes off, it explodes:', 'The bomb went off at midday.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33578, 'go off', 'If a gun goes off, it fires:', 'His gun went off accidentally.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33579, 'go off', 'If food or drink goes off, it is not good to eat or drink any more because it is too old:', 'This bacon smells a bit funny - do you think it''s gone off?', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33580, 'go off', 'If a warning device goes off, it starts to ring loudly or make a loud noise:', 'The alarm should go off automatically as soon as smoke is detected.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33581, 'go off', 'to leave a place and go somewhere else:', 'She''s gone off on holiday with Tony.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33582, 'go off', 'to happen in a particular way:', 'The protest march went off peacefully.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33583, 'go off', 'to become worse in quality:', 'That paper''s really gone off since they got that new editor.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33584, 'go off someone/something', 'to stop liking or being interested in someone or something:', 'I went off beefburgers after I got food poisoning from a takeaway.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33585, 'go off on a tangent', 'to suddenly start talking or thinking about a completely new subject:', 'It''s hard to get a firm decision out of him - he''s always going off on a tangent.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33586, 'go off on one', 'to suddenly become very angry and start shouting or behaving violently:', 'He went off on one because he thought I was threatening his dog.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33587, 'go off the boil', 'to lose interest or become less urgent:', 'They were really excited about the project, but now they seem to have gone off the boil.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33588, 'go off the deep end', 'to get very angry about something or lose control of yourself', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33589, 'go off the rails', 'to start behaving in a way that is not generally acceptable, especially dishonestly or illegally:', 'He went off the rails in his first year at university.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33590, 'go off with a bang', 'If a party or event goes off with a bang, it is very exciting and successful.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33591, 'go off with someone', 'to leave a wife, husband, or partner in order to have a sexual or romantic relationship with someone else:', 'Did you know that Hugh had gone off with his sister-in-law?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33592, 'go off with something', 'to take something without getting permission from the owner first:', 'I wish you''d stop going off with my car without asking me beforehand.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33593, 'go off-piste', 'to do something different to what is normal or expected:', 'The presenter went off-piste from the script, with hilarious consequences.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33594, 'go on', 'to happen:', 'I''m sure we never hear about a lot of what goes on in government.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33595, 'go on', 'to continue:', 'Please go on with what you''re doing and don''t let us interrupt you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33596, 'go on', 'to move to the next thing or stage:', '[ + to infinitive ] She admitted her company''s responsibility for the disaster and went on to explain how compensation would be paid to the victims.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33597, 'go on', 'to start operating:', 'The spotlights go on automatically when an intruder is detected in the garden.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33598, 'go on', 'to start talking again after a pause:', 'She paused to have a sip of coffee and then went on with her account of the accident.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33599, 'go on', 'something that you say to encourage someone to say or do something:', 'Go on, what happened next?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33600, 'go on', 'to talk in an annoying way about something for a long time:', 'He went on and on until I finally interrupted him and told him I had to go.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33601, 'go on', 'used when encouraging someone to do something:', 'Go on, have another drink.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33602, 'go on', 'something that you say in order to agree to do or allow something that you did not want to do or to allow before:', '"Are you sure you don''t want another slice of cake?" "Oh go on then, but just a small one."', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33603, 'go on', 'to continue or pass:', 'Tomorrow will start cold but it should get warmer as the day goes on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33604, 'go on', 'used when you do not believe someone', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33605, 'go on something', 'to use a piece of information in order to help you discover or understand something:', 'I''m only going on what I overheard him saying to Chris, but I think he''s planning to leave next month.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33606, 'go on record', 'If you go on record or if you are on record as saying something, you say it publicly and officially and it is written down.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33607, 'go on the block', 'to be sold at an auction (= public sale)', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33608, 'go on the stage', 'to become an actor:', 'At the age of ten, he decided that he wanted to go on the stage.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33609, 'go one better', 'to do something that is more advanced or more generous than someone else:', 'I gave her a card, but my brother went one better and bought her a present.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33610, 'go out', 'to leave a room or building, especially in order to do something for entertainment:', 'Please close the door as you go out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33611, 'go out', 'to have a romantic and usually sexual relationship with someone:', 'How long have you been going out with him?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33612, 'go out', 'If the tide goes out, it moves back and covers less of the beach.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33613, 'go out', 'If a light or something that is burning goes out, it stops producing light or heat:', 'When I woke up the fire had gone out.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33614, 'go out', 'to lose when you are playing in a sports competition, so that you must stop playing in the competition:', 'England went out to France in the second round of the championship.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33615, 'go out (of) the window', 'If a quality, principle, or idea goes out of the window, it does not exist any more:', 'Then people start drinking and sense goes out of the window.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33616, 'go out for something', 'to try to become part of a sports team:', 'Unable to play ball with his hand in a cast, he went out for track.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33617, 'go out like a light', 'to go to sleep very quickly or to become unconscious very quickly', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33618, 'go out of your way', 'to try very hard to do something, especially for someone else:', 'They really went out of their way to make us feel welcome.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33619, 'go out to someone', 'If your thoughts or sympathies go out to someone in a difficult or sad situation, you think of that person and feel sorry for them:', 'Our deepest sympathies go out to her husband and children.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33620, 'go over', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33621, 'go over something', 'to examine or look at something in a careful or detailed way:', 'Forensic scientists are going over the victim''s flat in a search for clues about the murderer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33622, 'go over something', 'to study or explain something:', 'I always go over my notes just before I go into an exam.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33623, 'go over someone''''s head', 'to speak to or ask permission from someone who has more authority than the person who you would normally go to in that situation:', 'Amanda was refusing to give me the week off so I went over her head and spoke to the boss.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33624, 'go over to something', 'to change to something new or to a new way of doing things:', 'Many firms are going over to new technologies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33625, 'go over to something', 'to change to a different person speaking or a different place during a television or radio programme:', 'We''re now going over to Kate Smith speaking live from Baghdad.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33626, 'go overboard', 'to do something too much, or to be too excited or eager about something:', 'I don''t think there''ll be more than six people eating, so I wouldn''t go overboard with the food.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33627, 'go pear-shaped', 'If a plan goes pear-shaped, it fails:', 'We''d planned to go away for the weekend, but it all went pear-shaped.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33628, 'go places', 'to be likely to be successful in the future:', 'They said that the group was clearly going places.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33629, 'go play with yourself!', 'a rude way of telling someone to go away and stop annoying you:', 'Oh, go play with yourself!', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33630, 'go pop', 'to explode:', 'If I eat any more I''m going to go pop!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33631, 'go postal', 'to become very angry and do something violent:', 'The man went postal and shot twelve of his colleagues.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33632, 'go private', 'to pay for private health care or private education:', 'People who can afford to go private can pick and choose the surgeon who operates on them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33633, 'go private', 'of a public company, to become privately owned:', 'None of the companies reverted to state control once they went private.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33634, 'go public', 'to become a company in which anyone can invest:', 'The company went public in 2013.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33635, 'go public (with something)', 'to make something known that was secret before:', 'We will not go public with the results until tomorrow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33636, 'go round', 'to spin like a wheel', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33637, 'go round', 'If there is enough of something to go round, there is enough for everyone in a group of people:', 'Are there enough pencils to go round?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33638, 'go round', 'to spend your time behaving in the stated way:', '[ + -ing verb ] You can''t go round being rude to people.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33639, 'go round', 'to visit someone in their home:', 'I''m just going round to Martha''s for half an hour.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33640, 'go round (somewhere)', 'to go or be given from one person to another, or to move from one place to another:', 'A nasty flu bug is going round (the school) at the moment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33641, 'go round something', 'to travel to all, or the main, parts of a place that you are visiting in order to find out what it is like or to learn about it:', 'For a few weeks in the summer, visitors are able to go round the palace.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33642, 'go shares', 'to divide something such as a cost between you:', 'Why don''t we go shares on lunch?', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33643, 'go stag', 'If a man goes stag to an event, he goes without a partner.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33644, 'go steady on something', 'to not use too much of something:', 'Go steady on the milk, Dan - that''s our last bottle.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33645, 'go the distance', 'to manage to continue until the end of a competition', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33646, 'go the extra mile', 'to make more effort than is expected of you:', 'He''s a nice guy, always ready to go the extra mile for his friends.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33647, 'go the whole hog', 'to do something as completely as possible:', 'Having already limited local taxation, why not go the whole hog and abolish it completely?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33648, 'go through', 'If a law, plan, or deal goes through, it is officially accepted or approved:', 'A city council member said that the proposals for the new shopping centre were unlikely to go through.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33649, 'go through something', 'to experience a difficult or unpleasant situation:', 'I''ve been going through a bad patch recently.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33650, 'go through something', 'to examine something that contains a collection of things carefully in order to organize them or find something:', 'I''m going through my wardrobe and throwing out all the clothes I don''t wear any more.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33651, 'go through something', 'to do something in order to practise or as a test:', 'Why don''t we go through the whole demonstration once more?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33652, 'go through something', 'to use a lot of something:', 'Before I gave up coffee, I was going through five cups a day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33653, 'go through a bad/difficult/rough/sticky patch', 'to experience a lot of problems in a period of your life:', 'Andy''s going through a rough patch at the moment - his wife wants a divorce.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33654, 'go through fire and water', 'to experience many difficulties or dangers in order to achieve something', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33655, 'go through the floor', 'to fall to very low levels:', 'House prices have gone through the floor this year.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33656, 'go through the mill', 'to have a lot of problems or difficulties:', 'Many people who have been divorced have been through the mill psychologically.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33657, 'go through the motions', 'to do something without thinking it is very important or having much interest in it:', 'He says he''s been investigating my complaint, but I feel he''s just going through the motions.', 'idiom', 'C2', NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33658, 'go through the roof', 'to rise to a very high level:', 'Prices have gone through the roof.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33659, 'go through the roof', 'to get very angry:', 'When I was expelled from school, my parents went through the roof.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33660, 'go through the wringer/put someone through the wringer', 'to have a difficult experience that upsets you a lot, or to make someone experience this:', 'The girl''s parents have been through the wringer since she disappeared.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33661, 'go through with something', 'to do something unpleasant or difficult that has already been agreed or promised:', 'He''d threatened to divorce her but I never thought he''d go through with it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33662, 'go to bat for someone', 'to support someone when the person needs help:', 'Senators will go to bat for companies that pay lots of taxes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33663, 'go to bed with someone', 'to have sex with someone', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33664, 'go to blazes', 'used to tell someone to go away', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33665, 'go to great lengths', 'to try very hard to achieve something:', 'Some people go to great lengths to make their homes attractive.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33666, 'go to hell', 'used to angrily tell someone to stop talking and go away:', '"Anyway, it''s your own fault." "Oh, go to hell!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33667, 'go to hell and back', 'to live through an extremely unpleasant, difficult, or painful experience:', 'I''ve been to hell and back over this court case.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33668, 'go to pieces', 'to become unable to think clearly and control your emotions because of something unpleasant or difficult that you have experienced:', 'She went to pieces at the funeral.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33669, 'go to pot', 'infml to become worse or be spoiled because of lack of care or effort:', 'Our old neighborhood has gone to pot.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33670, 'go to sleep', 'If your arm or leg has gone to sleep, you cannot feel or control it, often because you have been sitting or lying for too long in a strange position.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33671, 'go to someone', 'to be given or sold to someone:', 'Who did the award for Best Actress go to?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33672, 'go to someone''''s head', 'If something goes to someone''''s head, it makes that person think that they are very important and makes them a less pleasant person:', 'Don''t let fame/success go to your head.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33673, 'go to someone''''s head', 'If alcohol goes to your head, it makes you feel slightly drunk:', 'Champagne always goes straight to my head.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33674, 'go to the bad', 'to become a morally bad person:', 'She thought her children would go to the bad unless they were strictly brought up.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33675, 'go to the bathroom', 'to use the toilet:', 'Wait a moment - I just need to go to the bathroom.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33676, 'go to the country', 'to have an election:', 'The prime minister has decided to go to the country.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33677, 'go to the devil', 'something you say to someone annoying or bad to tell them to go away for ever', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33678, 'go to the dogs', 'If a country or organization is going to the dogs, it is becoming very much less successful than it was in the past.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33679, 'go to the stake for something', 'to defend an action, opinion, or belief despite the risks that are involved:', 'She was prepared to go to the stake for her views.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33680, 'go to the trouble to do something', 'to make an effort to do something:', 'If the police had gone to the trouble of looking up his record, they would not have released him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33681, 'go to the wall', 'to be destroyed or fail:', 'After nine months of massive losses the company finally went to the wall.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33682, 'go to the wall', 'to do everything you can to achieve something or help someone:', 'These guys will go to the wall for you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33683, 'go to town', 'to do something in a detailed and enthusiastic way, especially by spending a lot of money:', 'They''ve really gone to town on their wedding.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33684, 'go to town (on something)', 'to do something eagerly and as completely as possible:', 'Kayla and Josh really went to town on their wedding.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33685, 'go toe to toe', 'to be willing or able to compete or fight with someone in a strong, forceful, determined way:', 'We had a good candidate who stood toe to toe with the President and beat him in three debates.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33686, 'go toe to toe', 'to have equal or similar scores, or to be performing equally well in a competition, so that it is not clear who will win:', 'The pair went toe to toe until the third set, when Azarenka squandered two match points.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33687, 'go together', 'to look good together:', 'Do you think the cream dress and the blue jacket go together?', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33688, 'go together', 'to happen or be found together:', 'Wisdom and maturity don''t necessarily go together.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33689, 'go together', 'If two people are going together, they have a romantic or sexual relationship with each other.', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33690, 'go too far', 'to behave in a way that upsets or annoys people:', 'His jokes are funny, but sometimes he goes too far.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33691, 'go under', 'to sink:', 'The ship went under just minutes after the last passenger had been rescued.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33692, 'go under', 'If a company goes under, it fails financially:', 'The charity will go under unless a generous donor can be found within the next few months.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33693, 'go under the knife', 'to have a medical operation:', 'More and more women are choosing to go under the knife to improve their appearance.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33694, 'go up', 'to move higher, rise, or increase:', 'The average cost of a new house has gone up by five percent to £276,500.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33695, 'go up', 'to suddenly explode:', 'There''s a gas leak and the whole building could go up at any moment.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33696, 'go up', 'If a sign goes up, it is fixed into position:', 'The new "No Parking" signs went up yesterday.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33697, 'go up', 'If a building goes up, it is built:', 'A new factory is going up at the site of the old airport.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33698, 'go up', 'If you go up to a college or university, especially Oxford University or Cambridge University, you begin studying there, or continue studying after a holiday.', NULL, 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33699, 'go up in flames', 'to burn or be destroyed by fire:', 'The factory went up in flames.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33700, 'go up in flames', 'to be damaged or destroyed:', 'His career went up in flames when he was jailed for theft.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33701, 'go up in smoke', 'to be wasted:', 'When the business went bankrupt, twenty years of hard work went up in smoke.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33702, 'go up to something', 'to reach as far as something:', 'The path going up to the back door is very muddy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33703, 'go walkabout', 'If you say that an object has gone walkabout you mean that it is missing, often because someone has taken it:', 'My pen was here this morning but it seems to have gone walkabout.', 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33704, 'go west', 'If something goes west, it is lost, damaged, or spoiled in some way:', 'I couldn''t get a ticket - that''s my last chance to see the show gone west.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33705, 'go whole hog', 'to do something as completely as possible:', 'He decided to go whole hog and wear a tuxedo rather than just a suit.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33706, 'go with a bang', 'If a party or event goes with a bang, it is very exciting and successful.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33707, 'go with something', 'If one thing goes with another, they suit each other or they look or taste good together:', 'This wine goes particularly well with seafood.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33708, 'go with something', 'If a problem, activity, or quality goes with another one, they often happen or exist together and the first thing is often caused by the second:', '[ + -ing verb ] What are the main health problems that go with smoking?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33709, 'go with someone', 'to have a romantic or sexual relationship with someone:', 'Did he ever go with anyone else while they were living together?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33710, 'go with someone/something', 'to accept an idea or agree with a person:', 'I think we can go with the advertising agency''s suggestions, don''t you?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33711, 'go with the flow', 'to do what other people are doing or to agree with other people because it is the easiest thing to do:', 'Just relax and go with the flow!', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33712, 'go with the territory', 'to be part of a particular activity:', 'Criticism goes with the territory in politics.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33713, 'go without (something)', 'to not have something or to manage to live despite not having something:', 'They were poor as children, and sometimes had to go without.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33714, 'go wrong', 'to make a mistake or a bad decision:', 'If you just follow the signs to the park, you can’t go wrong.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33715, 'go wrong', 'If a situation goes wrong, there are problems or there is a bad result:', 'I was so worried that something had gone wrong that I called the police.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33716, 'go your (own) separate ways', 'If two or more people go their separate ways, they stop being together:', 'In 1983 the group disbanded and went their separate ways.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33717, 'go your own (sweet) way', 'to do what you want without considering other people:', 'It doesn''t matter how much advice I give Cathy, she always goes her own sweet way.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33718, 'go your own/separate way', 'When people or groups of people choose to go their own way, they decide to live or work without continuing their previous personal or business relationship:', 'After a couple of years together, we realized we weren''t really happy and decided to go our separate ways.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33719, 'go/be back to square one', 'to be forced to think of a new course of action because your first course of action failed:', 'The deal with the house fell through so I''m afraid we''re back to square one.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33720, 'go/be run to ground', 'to hide in order to escape someone or something following you:', 'He found the media attention intolerable and went to ground for several months.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33721, 'go/come down in the world', 'to have less money or a worse social position than you had before:', 'They used to live in a big house with lots of servants, but they''ve come down in the world since then.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33722, 'go/come up in the world', 'to have more money or a better social position than you had before:', 'Roger and Ann have gone up in the world - these days they only ever travel first-class.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33723, 'go/come with the territory', 'to be an expected fact or result of a particular situation or position:', 'The public attention that famous people get just goes with the territory.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33724, 'go/do the rounds', 'to go from person to person or place to place:', 'That story has gone the rounds in our office.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33725, 'go/get back to nature', 'to start living a more simple life, often in the country', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33726, 'go/get/head nowhere', 'to not have any success or achieve anything:', 'I''m trying to persuade her to come, but I''m getting nowhere.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33727, 'go/jump through hoops', 'to do a lot of difficult things before you are allowed to have or do something you want', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33728, 'go/run around in circles', 'to keep doing or talking about the same thing without achieving anything:', 'The discussion kept going around in circles.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33729, 'go/run round in circles', 'to keep doing or talking about the same thing without achieving anything:', 'The discussion kept going round in circles.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33730, 'go/sell like hot cakes', 'to be bought quickly and in large numbers:', 'The new game is apparently selling like hot cakes.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33731, 'go/sell like hotcakes', 'to be bought quickly and in large numbers', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33732, 'go/send something/someone flying', 'to fall, or to cause something or someone to fall or move through the air, suddenly and by accident:', 'I tripped going up the stairs and I/my books went flying.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33733, 'go/swim against the tide', 'to not follow what everyone else is doing', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33734, 'go/swim with the tide', 'to follow what everyone else is doing:', 'I thought I''d just swim with the tide and leave when everyone else does.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33735, 'go/turn beetroot (red)', 'to have a red face because you are embarrassed:', 'Whenever I talked about his past life, he would go beetroot.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33736, 'go/turn green', 'to look pale and ill as if you are going to vomit', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33737, 'go/walk down the aisle', 'to get married', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33738, 'gobble something up', 'to gobble', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33739, 'gobble something up', 'to use a lot of your supply of something, usually money:', 'The mounting legal costs quickly gobbled up their savings.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33740, 'gobs of something', 'large amounts of something:', 'He''s got gobs of money.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33741, 'going away', 'In sports, if a team or person wins a competition going away, they win it by a lot of points, goals, etc.:', 'They seemed to score at will in the final period and the Knicks won going away.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33742, 'good and ...', 'very:', 'Drink your coffee while it''s good and hot.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33743, 'good and proper', 'completely:', 'The table is broken good and proper.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33744, 'good cop, bad cop', 'used to describe a situation in which two police officers or any two people try to achieve something together, by one of them being friendly and pleasant and the other using threats or force:', 'The good cop - bad cop scenario is given a dizzying, dazzling twist in this movie.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33745, 'good heavens/grief/gracious!', 'used to emphasize how surprised, angry, shocked, etc. you are', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33746, 'good idea', 'used for saying that you like or agree with someone''''s suggestion:', '"You could grow roses or honeysuckle up that wall." "Good idea!"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33747, 'good job!', 'used for praising someone for something they have done well:', 'The house looks great - good job, guys!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33748, 'good riddance', 'I am happy that someone or something is gone:', 'Our neighbors and their nasty dogs have moved out – good riddance!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33749, 'good shout', 'used for saying that you think something is a good idea:', '"Anyone fancy a burger?" "Good shout."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33750, 'good show', 'used as an expression of approval:', 'Good show chaps, you completed the course in the time allowed.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33751, 'good things come in small packages', 'said to emphasize that something does not need to be big in order to be good', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33752, 'good/bad karma', 'the good or bad general character or feeling among a group of people or in a place:', 'In the early 60s hippies arrived, attracted by the island''s "good karma" and physical beauty.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33753, 'good/great/lovely stuff!', 'something you say to encourage or praise someone:', '"The sales figures are up this week." "Great stuff!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33754, 'goodbye to something', 'used when accepting that there is no possibility of getting, keeping, or achieving a particular thing:', 'She only finished sixth - that surely means goodbye to a place in the final.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33755, 'goof around', 'to spend time doing nothing important or behaving in a silly way:', 'The boys spent the whole summer just goofing around.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33756, 'goof off', 'to avoid doing any work:', 'The teacher told them to stop goofing off and get back to work.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33757, 'goof up', 'to do something badly or make a silly mistake that causes something to fail:', 'He''s just waiting for Susan to goof up so he can get her job.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33758, 'got it in one!', 'something that you say when someone has guessed something correctly:', '"Don''t tell me - is Anna pregnant again?" "Got it in one!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33759, 'gouge something out', 'to remove something by digging or cutting it out of a surface:', 'In Shakespeare''s play "King Lear" the Earl of Gloucester''s eyes are gouged out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33760, 'grab at something/someone', 'to try to get hold of someone or something quickly, with your hand', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33761, 'graft sth onto sth', 'to try to combine one idea, method, etc. with another, especially when the two things are very different:', 'The editors attempted to graft new reporting onto previously published articles.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33762, 'grand old age', 'If a person or animal lives to a grand old age, they live until they are very old:', 'He lived to the grand old age of 97.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33763, 'grandfather sb/sth into sth', 'to allow someone to continue to do or to have something that a new law or rule makes illegal:', 'Most existing companies will be grandfathered into the old system for up to five years.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33764, 'grapple with someone', 'to hold onto someone and fight with them:', 'Two officers grappled with the gunman.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33765, 'grapple with something', 'to try to deal with or understand a difficult problem or subject:', 'Today, many Americans are still grappling with the issue of race.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33766, 'grasp at something', 'to try to take an opportunity:', 'Certainly if the job were offered me I''d grasp at the chance.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33767, 'grasp at something', 'to try to hold or touch something:', 'She grasped at his shirt as he ran past.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33768, 'grasp the nettle', 'to force yourself to be brave and do something that is difficult or unpleasant:', 'You''ve been putting off making that phone call for days - I think it''s about time you grasped the nettle!', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33769, 'grasping at straws', 'trying to find some way to succeed when nothing you choose is likely to work:', 'We searched all the backup tapes, trying to find the missing files, but we knew we were grasping at straws.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33770, 'grasping at straws', 'trying to find a reason to feel hopeful in a bad situation:', 'I knew my mother was dying, but I was grasping at straws and denying reality.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33771, 'grass on someone', 'If a person grasses on someone else, they tell the police or someone in authority about something bad that that person has done:', 'Dan grassed on them to the local police.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33772, 'grass something over', 'to grow grass on an area of land', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33773, 'grateful/thankful for small mercies', 'If someone should be grateful/thankful for small mercies, they should be grateful for something because it is not as bad as it could have been:', 'She wasn''t badly hurt in the accident, so we''re grateful for small mercies.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33774, 'gravitate toward/to something/someone', 'to be attracted by or to move in the direction of something or someone:', 'Susie always gravitates toward the older children in her playgroup.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33775, 'gravitate towards/to something/someone', 'to be attracted by or to move in the direction of something or someone:', 'Susie always gravitates towards the older children in her playgroup.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33776, 'grease someone''''s palm', 'to secretly give someone money in order to persuade them to do something for you', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33777, 'great minds think alike', 'said to someone just after you have discovered that they have had the same idea as you', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33778, 'green with envy', 'wishing very much that you had what someone else has:', 'When I heard about his new job I was green with envy.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33779, 'greener pastures', 'a new place or activity that offers new opportunities:', 'Many scientists working for the government have left for greener pastures in the private sector.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33780, 'greet/welcome someone with open arms', 'to show someone that you are very pleased to see them', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33781, 'grin and bear it', 'to accept something bad without complaining:', 'I really don''t want to go, but I guess I''ll just have to grin and bear it.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33782, 'grin/smile from ear to ear', 'to look extremely happy:', '"We''ve had a fantastic response!" he said, grinning from ear to ear.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33783, 'grind someone down', 'to treat someone so badly for such a long time that they are no longer able to fight back:', 'Ground down by years of abuse, she did not have the confidence to leave him.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33784, 'grind something into something', 'to press something hard into something else using a twisting movement:', 'Sara angrily ground her cigarette into the ashtray.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33785, 'grind something out', 'to produce the same thing, especially a boring thing, again and again:', 'The band ground out the same tunes it had been playing for 20 years.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33786, 'grind the faces of the poor', 'Someone who grinds the faces of the poor, treats poor people very badly, often to get money from them.', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33787, 'grind to a halt', 'to stop or no longer work well:', 'Traffic ground to a halt.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33788, 'grind to a halt/standstill', 'to stop slowly:', 'The car ground to a halt right in the middle of the street.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33789, 'grit your teeth', 'to press your top and bottom teeth together, often in anger:', 'He gritted his teeth in silent fury.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33790, 'grit your teeth', 'to accept a difficult situation and deal with it in a determined way:', 'We had to grit our teeth and agree with their conditions because we wanted the contract.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33791, 'groan with/under (the weight of) something', 'to carry a very large quantity of something:', 'The tables were positively groaning with food.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33792, 'grope for something', 'to try to think of something, especially the right words, the correct answer, etc.:', 'I''m groping for the right words here.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33793, 'gross someone out', 'If something grosses you out, you think it is very unpleasant or disgusting:', 'He smells and he''s dirty - he really grosses me out.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33794, 'gross something up', 'to increase an amount by adding something that is not normally included, such as tax:', 'All costs were grossed up for tax deductions.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33795, 'grow apart', 'If two people in a close relationship grow apart, or if they grow away from each other, they gradually begin to have a less close relationship, usually because they no longer have the same interests and want the same things:', 'There was nobody else involved - we just grew apart.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33796, 'grow into someone/something', 'to develop into a particular type of person or thing:', 'He''s grown into a fine, responsible young man.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33797, 'grow into something', 'If children grow into clothes, they gradually become big enough to wear them.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33798, 'grow on someone', 'If someone or something grows on you, you like him, her, or it more and more than you did at first:', 'I wasn''t sure about this album when I bought it, but it''s really grown on me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33799, 'grow out of something', 'If children grow out of clothes, they become too big to fit into them.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33800, 'grow out of something', 'If you grow out of an interest or way of behaving, you stop having or doing it as you become older:', 'Lucas says he wants to join the army when he turns 18, but I hope he''ll grow out of the idea.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33801, 'grow out of something', 'If an idea grows out of another one, it develops from it:', 'The idea for the story grew out of a strange experience I had last year.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33802, 'grow up', 'to gradually become an adult:', 'I grew up in Scotland (= I lived there when I was young).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33803, 'grow up', 'to behave like an adult; used to criticize someone who you think is being silly or unreasonable:', 'Everyone should just grow up and treat each other with respect.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33804, 'grow up', 'If a town or city grows up in a particular place or way, it develops there or in that way:', 'The city grew up originally as a crossing point on the river.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33805, 'grub something up/out', 'to dig something out of the ground to get rid of it:', 'She spent the morning in the garden, grubbing up weeds.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33806, 'guard against something', 'to take careful action in order to try to prevent something from happening:', 'Regular exercise helps guard against heart disease.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33807, 'guess at something', 'to try to imagine something when you have little knowledge or experience of it:', 'There are no photographs of him, so we can only guess at what he looked like.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33808, 'guilty as charged', 'responsible for doing something illegal that you have been accused of in court:', 'They were guilty as charged and fairly tried, and therefore justice was served.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33809, 'guilty as charged', 'used to admit that what someone has been accused of is true, often when you think this is not really bad:', 'Guilty as charged! I am an Elvis fan!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33810, 'gulp down something', 'to eat or drink something quickly:', 'He hardly has time to gulp down a piece of pizza.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33811, 'gulp something back', 'to try not to show that you are upset, usually by swallowing hard:', 'She gulped back the tears.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33812, 'gum something up', 'to prevent something from working or opening in the usual way because of being blocked or stuck :', 'When I woke up this morning my eyes were all gummed up.', 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33813, 'gun for something', 'to make a great effort to win or obtain something:', 'Irwin is gunning for his third straight championship.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33814, 'gun for someone', 'to make a great effort to defeat or hurt someone:', 'We know all the other teams are gunning for us.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33815, 'gun for someone', 'If someone is gunning for someone else, that person can also be trying to shoot or attack the other one.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33816, 'gun someone down', 'to shoot someone and kill or seriously injure them, often when that person cannot defend himself or herself:', 'The police officer was gunned down as he took his children to school.', 'phrasal verb', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33817, 'gussy someone/something up', 'to make someone or something look more attractive or impressive:', 'The museum will put finishing touches on new exhibits and gussy up old ones in time for the grand reopening.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33818, 'hack away at sth', 'to slowly reduce the amount of money, staff, or resources that are needed in order to be successful:', 'Profits are in a free fall, and companies are slashing spending on new equipment and hacking away at payrolls.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33819, 'hack someone off', 'to make someone feel annoyed:', 'He leaves all the difficult stuff for me to do, and it really hacks me off.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33820, 'had best', 'used to suggest an action or to show that it is necessary:', 'You had best tell her (= it would be wise if you told her) that you won''t be able to come to her party.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33821, 'had better/best do something', 'If you had better/best do something, you should do it or it would be good to do it:', 'I''d better leave a note so they''ll know I''ll be late.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33822, 'had it coming (to you)', 'If someone had it coming, something bad happened to them that was deserved:', 'He''s been fired but, with all that time he took off, he had it coming really.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33823, 'hail from somewhere', 'to come from or to have been born in a particular place:', 'Joe originally hails from Toronto.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33824, 'hail someone/something as something', 'to praise a person or an achievement by comparing them to someone or something very good:', 'She''s been hailed as one of the best young dancers today.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33825, 'half a loaf is better than none', 'said about a situation in which you must accept less than you wanted', NULL, 'idiom', NULL, NULL, 'old-fashioned, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33826, 'half the battle', 'a large part of the effort or work that is needed:', 'With so many search engines on the Web, deciding which one is best is half the battle.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33827, 'ham it up', 'to perform or behave in a false way, especially in a way that is too obvious or that makes people laugh', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33828, 'hammer away at something', 'to work without stopping and with a lot of effort', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33829, 'hammer something home', 'to make certain that something is understood by expressing it clearly and forcefully:', 'The advertising campaign will try to hammer home the message that excessive drinking is a health risk.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33830, 'hammer something into someone', 'to force someone to understand something by repeating it a lot:', 'I always had it hammered into me that I mustn''t lie.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33831, 'hammer something out', 'to reach an agreement or solution after a lot of argument or discussion:', 'Three years after the accident the lawyers finally managed to hammer out a settlement with the insurance company.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33832, 'hammer sth down', 'to reduce prices or costs by a large amount:', 'Government policies designed to help consumers by hammering down the price of cars also played their part in the company''s plans to axe 2,000 jobs .', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33833, 'hand in glove', 'working together, often to do something dishonest:', 'It was rumoured at the time that some of the gangs were working hand in glove with the police.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33834, 'hand in hand', 'holding each other''''s hand:', 'I saw them walking hand in hand through town the other day.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33835, 'hand off', 'in American football, to pass by putting the ball directly into the hands of another player:', 'Favre handed off to Grant.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33836, 'hand something off', 'to pass or give something to someone:', '"Look over there!" he said, handing off his binoculars to the woman standing next to him.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33837, 'hand something off', 'in American football, to pass the ball directly into the hands of another player:', 'He was happy to hand off the ball more at the start of this season.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33838, 'hand something off', 'to give another person control of something, or responsibility for dealing with him, her, or it:', 'The work could be handed off to another firm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33839, 'hand over fist', 'If you make or lose money hand over fist, you make or lose a lot of money very quickly:', 'Business was good and we were making money hand over fist.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33840, 'hand something around', 'to pass or offer something to all the people in a group:', 'Adam, could you hand around the cookies?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33841, 'hand something back', 'to return something to the person who gave it to you:', '[ + two objects ] "No, I''ve never seen him before," I said, handing her back the photograph.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33842, 'hand something down', 'to give something to someone younger than you in the family because you want them to have it or because you no longer need it:', 'This necklace was handed down to my mother by my grandmother.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33843, 'hand something down', 'to pass traditions from older people to younger ones:', 'a custom handed down through the generations', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33844, 'hand something down', 'to announce an official decision, especially in a court of law:', 'The court handed down an eight-year sentence.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33845, 'hand something in', 'to give something to someone in a position of authority:', 'Have you handed in your history essay yet?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33846, 'hand something out', 'to give something to each person in a group or place:', 'The teacher asked her to hand out the worksheets.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33847, 'hand something out', 'to give something such as a prize or reward, especially generously or in large amounts:', 'He is not known for handing out effusive praise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33848, 'hand something out', 'to announce an official decision, especially in a court of law:', 'She said she was pleased with the judge''s decision to hand out a harsher punishment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33849, 'hand something over', 'to give something to someone else:', 'We were ordered to hand over our passports.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33850, 'hand something/someone over', 'to give another person control of someone or something, or responsibility for dealing with him, her, or it:', 'The hijacker was handed over to the French police.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33851, 'hand something round', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33852, 'hand sth on', 'to give something to someone else:', 'hand sth on to sb The business will be handed on to his family or sold.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33853, 'hand sth on', 'to give responsibility for something to someone else:', 'A year ago, she handed on the administrative directorship to become development director.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33854, 'handbags (at dawn)', 'used to talk about a situation in which two football players seem angry and threatening but do not actually fight:', 'It wasn''t a serious confrontation - just handbags.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33855, 'handle/treat someone with kid gloves', 'to be very polite or kind to someone because you do not want to make them angry or upset', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33856, 'hands down', 'definitely:', 'If we had a race, he’d win hands down.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33857, 'hang around', 'to move or do things slowly:', 'Go and pack but don''t hang around - we have to go in an hour.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33858, 'hang around (somewhere)', 'to wait or spend time somewhere, usually for no particular reason:', 'I spent most of my youth hanging around the bars of Dublin.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33859, 'hang around with someone', 'to spend time with someone:', 'I got into drugs because I was hanging around with the wrong people.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33860, 'hang back', 'to be slow to do something, often because of fear or having no confidence:', 'There''s no need to hang back - you can sing as well as anyone.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33861, 'hang by a thread', 'If a serious situation hangs by a thread, it means that even a slight change can decide what will happen and that a bad result such as death, failure, etc. is likely:', 'The mayor''s political future has been hanging by a thread since the fraud scandal.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33862, 'hang in there', 'said as a way of telling someone to not give up, despite difficulties:', 'Work can get tough in the middle of a term but hang in there and it''ll be OK.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33863, 'hang on', 'to wait for a short time:', 'Sally''s on the other phone - would you like to hang on?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33864, 'hang on', 'to hold or continue holding onto something:', 'Hang on tight - it''s going to be a very bumpy ride.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33865, 'hang something on someone', 'to blame someone for something, especially something they did not do:', 'I wasn''t anywhere near the house when the window was broken, so you can''t hang that on me!', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33866, 'hang on/upon something', 'to give careful attention to something, especially something that someone says:', 'He hangs on her every word as if she were some sort of goddess.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33867, 'hang on/upon something', 'to depend on something:', 'The safety of air travel hangs partly on the thoroughness of baggage checking.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33868, 'hang onto something', 'to keep something:', 'You should hang onto that painting - it might be valuable.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33869, 'hang out', 'to spend a lot of time in a place or with someone:', 'You still hang out at the pool hall?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33870, 'hang over something', 'If a threat or doubt hangs over a place or a situation, it exists:', 'Uncertainty again hangs over the project.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33871, 'hang round (somewhere)', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33872, 'hang round with someone', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33873, 'hang someone out to dry', 'to allow someone to be punished, criticized, or made to suffer in a way that is unfair, without trying to help them:', 'They felt they had been hung out to dry by their employers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33874, 'hang the cost/expense', 'the cost is not important:', 'Just buy it and hang the expense!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33875, 'hang together', 'If people hang together, they help each other and work together to achieve something:', 'If the opposition party can hang together over the next six months, they might just stand a chance of being elected.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33876, 'hang together', 'If the parts of something hang together, they are well organized or they seem to be true or correct:', 'Somehow her story doesn''t quite hang together.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33877, 'hang tough', 'to not change your actions or opinions although other people try to make you do this:', 'The president is hanging tough on the hostage crisis.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33878, 'hang up', 'to end a phone conversation:', 'He started shouting so I hung up (on him).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33879, 'hang something up', 'to stop using and needing something because you have given up the sport or activity it is used for:', 'So when did you hang up your boxing gloves/golf clubs/ballet shoes?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33880, 'hang your head', 'to be ashamed or unhappy:', 'We played a great game – we have no reason to hang our heads.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33881, 'hang/hold fire', 'to delay making a decision:', 'Ideally we would settle the matter now, but I think we should hang fire until the general situation becomes clearer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33882, 'hang/hold on like grim death', 'to hold on very tightly to something, despite great difficulty:', 'Darren always drives and I sit behind him, hanging on like grim death.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33883, 'hang/stay loose', 'to be calm and relaxed', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33884, 'hanker after/for something', 'to have a strong wish for something, especially if you cannot or should not have it:', 'What did you hanker after most when you were in prison?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33885, 'happen along/by (somewhere)', 'to go to a place by chance or without planning to:', 'I''d have drowned if he hadn''t happened along and pulled me out of the river.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33886, 'happen on/upon something/someone', 'to find or meet something or someone by chance:', 'Eventually they happened on a road leading across the desert.', 'phrasal verb', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33887, 'happy ever after', 'happy or happily for the rest of your life, especially in a romantic relationship:', 'They were all going to live in the country and be happy ever after.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33888, 'happy ever after', 'a situation in which someone is happy and satisfied for the rest of their life, especially in a romantic relationship:', 'But some weddings don''t lead to happy ever after.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33889, 'happy place', 'a memory, situation, or activity that makes you feel happy:', 'Print design is my happy place.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33890, 'hard Brexit', 'a Brexit in which the United Kingdom stops being a member of the European single market and gets full control of its own law-making and immigration:', 'Investors worried about a "hard Brexit" sent the pound to a three-decade low.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33891, 'hard at it', 'putting a lot of effort into what you are doing:', 'That''s what I like to see - everybody hard at it!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33892, 'hard feelings', 'anger towards someone that you have argued with:', 'So we''re friends again, are we? No hard feelings?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33893, 'hard luck!', 'used to express sympathy to someone because something slightly bad has happened:', '"We lost again." "Oh, hard luck!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33894, 'hard to swallow', 'difficult to believe:', 'I found her story rather hard to swallow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33895, 'hard/hot/close on someone''''s heels', 'following someone very closely:', 'She ran down the steps with a group of journalists hard on her heels.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33896, 'hard/tough as nails', 'not feeling or showing any emotions such as sympathy, fear, or worry', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33897, 'hard/tough cheese!', 'something that you say to indicate that you have no sympathy for someone or cannot do anything to help them:', 'This is the only food we have left, and if you don''t like it, hard cheese.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33898, 'harden your heart', 'to make yourself stop feeling kind or friendly towards someone:', 'You''ve just got to harden your heart and tell him to leave.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33899, 'hardly/barely put one foot in front of the other', 'If you can hardly/barely put one foot in front of the other, you are having difficulty walking:', 'I was so tired that I could hardly put one foot in front of the other.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33900, 'hark at someone!', 'said to someone who has just accused you of something that you think that person is guilty of himself or herself:', 'Hark at him calling me lazy when he never walks anywhere if he can drive!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33901, 'hark back', 'to remember or to cause someone to remember something from the past:', 'The director’s latest film harks back to the era of silent movies.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33902, 'hark back to something', 'If someone harks back to something in the past, they talk about it again and again, often in a way that annoys other people:', 'He''s always harking back to his childhood and saying how things were better then.', 'phrasal verb', NULL, NULL, 'old use', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33903, 'hark back to something', 'If something harks back to something in the past, it is similar to it:', 'The director''s latest film harks back to the early years of cinema.', 'phrasal verb', NULL, NULL, 'old use', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33904, 'harm a hair on someone''''s head', 'to hurt someone:', 'If he so much as harms a hair on her head, I won''t be responsible for my actions.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33905, 'harp on (about sth)', 'to talk or complain about something many times:', 'He''s always harping on about lack of discipline.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33906, 'harp on sth', 'to talk or complain about something many times:', 'He''s always harping on our lack of discipline.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33907, 'has the cat got your tongue?', 'something you say to someone when you are annoyed because they will not speak:', 'What''s the matter? Has the cat got your tongue?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33908, 'hash something out', 'to talk about something with someone else in order to reach agreement about it:', 'You two hash out the details of the presentation.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33909, 'hash something up', 'to spoil something by doing it badly:', 'The first interview was all right but I think I hashed up the second one.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33910, 'hate on someone', 'to criticize someone or say bad things about them, in an unpleasant and public way:', 'These kids get hated on for no good reason at all.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33911, 'hate someone''''s guts', 'to dislike someone very much', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33912, 'hats off to someone', 'said to praise and thank someone for doing something helpful:', 'Hats off to Connie for finding such a splendid venue for a party!', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33913, 'haul ass', 'to move very quickly to a different place:', 'When the shooting started we hauled ass out of there.', 'idiom', NULL, NULL, 'very informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33914, 'haul someone up', 'to force someone to go somewhere or see someone in order to be punished or to answer questions about their behaviour:', 'He was hauled up in court/in front of a judge.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33915, 'haul someone/something away', 'to take someone or something somewhere:', 'Most of the buildings are simply flattened and hauled away to local dumps.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33916, 'haul/drag someone over the coals', 'to speak angrily to someone because they have done something you disapprove of:', 'He was hauled over the coals for coming in late for work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33917, 'have (all) the makings of something', 'to seem likely to develop into something:', 'She has the makings of a great violinist.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33918, 'have (got) a hand in something', 'to be involved with something or have influence on something:', 'Who planned the party – I bet you had a hand in it, didn''t you?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33919, 'have (got) it bad', 'to be very much in love', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33920, 'have (got) it made', 'to be certain to be successful and have a good life, often without much effort:', 'With his father at the head of the firm, he''s got it made.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33921, 'have (got) only yourself to blame', 'to be responsible for something bad that has happened:', 'He didn’t study, so he’s got only himself to blame if he fails.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33922, 'have (got) sb sussed', 'to understand what someone is like:', 'I reckon I''ve got him sussed.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33923, 'have (got) sth sussed', 'to realize, understand, or know something about a situation, plan, etc.:', 'All those people who you thought had it sussed are in fact faking it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33924, 'have (got) someone by the short and curlies', 'to have someone in your power', NULL, 'idiom', NULL, NULL, 'very informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33925, 'have (got) someone''''s back', 'to be ready to protect or defend someone:', 'Don''t worry. I''ve got your back.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33926, 'have (got) something licked', 'to have solved a problem', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33927, 'have (got) something on', 'If you have clothes or shoes on, you are wearing them:', 'I loved that dress you had on last night.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33928, 'have (got) something on', 'If you have something on, you have planned to do it:', 'Do you have anything on this week?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33929, 'have (got) the hots for someone', 'to be very sexually attracted to someone:', 'She''s got the hots for this guy in her office.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33930, 'have (got) to hand it to someone', 'If you say you have (got) to hand it to someone you mean that they have been very successful or skilful:', 'I mean you''ve got to hand it to her, she''s brought up those three children all on her own.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33931, 'have (got) your hands full', 'to be very busy or involved with something:', 'I’ve got my hands full right now with a sick baby.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33932, 'have (got) your heart set on something', 'to want something very much, so that you would be very disappointed if you do not get it:', 'She’s got her heart set on ballet lessons.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33933, 'have (just about) had it', 'infml to not be willing or able to continue doing something:', 'We’ve been to three museums today and I’ve just about had it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33934, 'have (just about) had it', 'If something has had it, it is not working any longer:', 'This old vacuum cleaner has had it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33935, 'have (more than) your share of something', 'to have had a lot or too much of something:', 'We’ve had our share of problems with the new computer system.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33936, 'have (sexual) relations (with someone)', 'to have sex or a sexual relationship with someone:', 'The couple had been having sexual relations for a year.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33937, 'have (someone''''s) blood on your hands', 'to be responsible for someone''''s death:', 'The leaders of this war have the blood of many thousands of people on their hands.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33938, 'have a (good) head for something', 'to have a natural ability to do something well:', 'Kim has a head for numbers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33939, 'have a (good) nose for something', 'to be good at finding things of the stated type:', 'She has a good nose for a bargain.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33940, 'have a ball', 'to enjoy yourself very much:', '"So how was the party last night?" "Oh, it was great - we had a ball!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33941, 'have a bee in your bonnet', 'to keep talking about something again and again because you think it is very important:', 'She never stops talking about healthy eating - she''s got a real bee in her bonnet about it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33942, 'have a blonde moment', 'to forget something or do something silly, in a way that is sometimes thought to be typical of women with blonde hair', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33943, 'have a bone to pick with someone', 'to want to talk to someone about something annoying they have done:', 'I''ve got a bone to pick with you - you''ve been using my shaver again.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33944, 'have a bumpy ride', 'to have a difficult time:', 'She''s had a bumpy ride at work over the last few months.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33945, 'have a bun in the oven', 'to be pregnant', NULL, 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33946, 'have a butcher''''s', 'to look at something:', 'Let''s have a butcher''s at your present, then.', 'idiom', NULL, NULL, 'old-fashioned, slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33947, 'have a card up your sleeve', 'to have an advantage that other people do not know about:', 'England have definitely been the weaker side, but I think they''ve still got one or two cards up their sleeve.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33948, 'have a care', 'used to tell someone to be more careful', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33949, 'have a chip on your shoulder', 'to seem angry all the time because you think you have been treated unfairly or feel you are not as good as other people:', 'He''s got a chip on his shoulder about not having been to university.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33950, 'have a corner on a market', 'If a company has a corner on a particular market, it is more successful than any other company at selling a particular type of product.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33951, 'have a cow', 'to be very worried, upset, or angry about something:', 'My mother had a cow when I said I was going to buy a motorbike.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33952, 'have a face like the back end of a bus', 'to be very ugly', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33953, 'have a face like thunder', 'to look extremely angry:', 'She suddenly came into the room with a face like thunder.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33954, 'have a familiar ring (to it)', 'to seem or sound like something you have heard or seen before:', 'Her name had a familiar ring to it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33955, 'have a few (too many)', 'to drink quite a large number of, or too many, alcoholic drinks:', 'By the look of her, she''d had a few even before she arrived at the party.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33956, 'have a few, several, etc. irons in the fire', 'to be involved with many activities or jobs at the same time or to make certain that there are always several possibilities available:', 'If that job application doesn''t work out I''ve got a couple more irons in the fire.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33957, 'have a field day', 'to take advantage of an opportunity to do something you enjoy:', 'The newspapers had a field day when the wedding was announced (= they wrote a lot about it and printed many photographs of it).', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33958, 'have a finger in every pie', 'to be involved in and have influence over many different activities, often in a way that people do not approve of', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33959, 'have a finger in the pie', 'to be involved in something, often when your involvement is not wanted', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33960, 'have a fit', 'to become very angry:', 'My mother threw a fit when she saw the mess we made.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33961, 'have a fling', 'to have a short sexual relationship with someone:', 'She''s been having a fling with her boss.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33962, 'have a foot in both camps', 'to be connected to two groups with opposing interests', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33963, 'have a frog in your throat', 'to have difficulty in speaking because your throat feels dry and you want to cough', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33964, 'have a good innings', 'If you say that someone has had a good innings, you mean that they have had a long and successful life:', 'He was 86 when he died so I suppose he''d had a good innings.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33965, 'have a good run for your money', 'to have a good enough time:', 'I''ve achieved a lot in my life and I feel I''ve had a good run for my money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33966, 'have a good war', 'to behave in a way that is successful and admired during a war, or during a difficult time period that can be seen as similar to a war:', 'Unlike so many of his shell-shocked generation, Spencer had a good war.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33967, 'have a good/healthy pair of lungs', 'You say that a baby has a good/healthy pair of lungs when it cries loudly.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33968, 'have a grandstand view', 'to be in a position where you can see something very well:', 'From our hotel room window, we had a grandstand view of the parade.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33969, 'have a heart of gold', 'to be very kind and generous:', 'She has a heart of gold.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33970, 'have a heart of stone', 'to be unkind or cruel', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33971, 'have a heart!', 'used to ask someone to be kinder to you:', 'Don''t make me write it again! Have a heart!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33972, 'have a heavy foot', 'to drive a car too fast:', 'She has a heavy foot - does the trip in half the time it takes me!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33973, 'have a horror of something', 'to hate something very much or be very frightened of something:', 'It may be childish but I have a horror of worms.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33974, 'have a horse in the race', 'to be personally involved in or affected by something:', 'It''s probably going to bring a lot of people out to the election because everyone will have a horse in the race.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33975, 'have a leg up on someone', 'to have an advantage over someone', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33976, 'have a lot of time for someone', 'to like someone and be interested in them:', 'She''s really nice - I have a lot of time for Helen.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33977, 'have a lot to say for yourself', 'to talk too much and seem to have a high opinion of yourself', NULL, 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33978, 'have a memory like an elephant', 'to be able to remember things easily and for a long period of time', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33979, 'have a mind of its own', 'A machine or other object can be said to have a mind of its own if it seems to be controlling the way it behaves or moves, independently of the person using it:', 'This shopping trolley has a mind of its own.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33980, 'have a nice, good, etc. line in something', 'to do something skilfully and successfully:', 'He has a good line in anecdotes.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33981, 'have a nodding acquaintance with someone/something', 'to know someone slightly or have a slight knowledge of a subject:', 'She has only a nodding acquaintance with the issues involved.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33982, 'have a passing/slight/nodding acquaintance with something', 'to have very little knowledge or experience of a subject:', 'I''m afraid I have only a nodding acquaintance with his works.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33983, 'have a problem with something/someone', 'to find something or someone annoying or offensive:', 'I have a real problem with people who use their mobile phones on the train.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33984, 'have a rare old time', 'to enjoy yourself very much:', 'We went on a tour of the city''s bars and had a rare old time.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33985, 'have a rare old time', 'to have difficulty:', 'We had a rare old time trying to get tickets.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33986, 'have a ringside seat', 'to be in a position where you can see or observe something very well:', 'He had a ringside seat for the dramas of the Clinton years.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33987, 'have a roving eye', 'If you say that someone has a roving eye, you mean that they are always sexually interested in people other than their partner:', 'By his own admission he had a roving eye and was easily infatuated.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33988, 'have a screw loose', 'If you say that someone has a screw loose, you mean that they behave in a strange way and seem slightly mentally ill.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33989, 'have a sharp tongue', 'to be someone who often criticizes and speaks in a severe way:', 'Jane has a sharp tongue, so be warned.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33990, 'have a short fuse', 'to get angry very easily', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33991, 'have a short memory', 'to forget things quickly', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33992, 'have a sook', 'to refuse to smile and be pleasant to people because you are angry or unhappy about something:', 'Bullies usually have a sook after they''ve been called out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33993, 'have a stick up your arse', 'a rude phrase meaning to be very serious and easily offended, and always want rules to be obeyed:', 'She has a stick up her arse and likes lecturing people.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33994, 'have a stick up your ass', 'a rude phrase meaning to be very serious and easily offended, and always want rules to be obeyed:', 'She has a stick up her ass and likes lecturing people.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33995, 'have a sting in the/its tail', 'If something, such as a story or joke, has a sting in the/its tail, it has a surprising or unpleasant part that only becomes clear at the end.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33996, 'have a strong stomach', 'to be able to smell, taste, or see unpleasant things without feeling ill or upset:', 'You need to have a very strong stomach to watch some of the surgery scenes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33997, 'have a strop on', 'to be in a bad mood:', 'Why have you got such a strop on - what''s happened?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33998, 'have a thin time (of it)', 'to have bad or unhappy experiences:', 'He''s been having a thin time (of it) since his accident.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (33999, 'have a thing about something/someone', 'to like or dislike something or someone very much:', 'Ben''s got a thing about Harley Davidsons - he''s got three of them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34000, 'have a weak stomach', 'to easily feel ill or upset when you smell, taste, or see something unpleasant', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34001, 'have a whale of a time', 'to enjoy yourself very much:', 'We had a whale of a time on holiday.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34002, 'have a word in someone''''s ear', 'to give someone a piece of advice or information secretly', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34003, 'have a, some, etc. say in something', 'to be involved in making a decision about something:', 'When he''s 18, he''ll begin to have a/some say in the running of the family business.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34004, 'have a/the feeling', 'to think or believe something, usually based on a guess or on your emotions:', 'I have a feeling we''ll meet again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34005, 'have a/the ring of truth', 'to seem to be true:', 'This story has the ring of truth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34006, 'have all the cares of the world on your shoulders', 'to be very worried by many different problems:', 'You look as if you have all the cares of the world on your shoulders.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34007, 'have an accident', 'to urinate or excrete (= pass solid waste) when you do not intend to:', 'Even a six-year-old can have an accident at night sometimes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34008, 'have an ax to grind', 'to have a selfish reason or strong opinion that influences your actions:', 'The study should be conducted by a firm that has no axe to grind.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34009, 'have an axe to grind', 'to have a strong personal opinion about something that you want people to accept and that is the reason why you do something:', 'Environmentalists have no political axe to grind - they just want to save the planet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34010, 'have an ear for something', 'If someone has an ear for music or languages, they are good at hearing, repeating, and understanding these sounds:', 'She''s never had much of an ear for languages.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34011, 'have an eye for something', 'to be good at noticing a particular type of thing:', 'She has an eye for detail.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34012, 'have an eye to/for the main chance', 'Someone who has an eye to/for the main chance is always ready to use a situation to their own advantage.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34013, 'have another think coming', 'to need to consider something again, because you are wrong:', 'If you think I''m going to pay for everything, you''ve got another think coming.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34014, 'have another/more than one string to your bow', 'to have more than one interest, skill, or resource that you can use if you need to:', 'I enjoy my work, but I''d like to have another string to my bow in case I lose my job.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34015, 'have ants in your pants', 'to not be able to keep still because you are very excited or worried about something', NULL, 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34016, 'have bats in the belfry', 'to be silly and slightly crazy and behave in a confused way', NULL, 'idiom', NULL, NULL, 'old-fashioned, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34017, 'have been around the ridges', 'If you have been around the ridges, you have a lot of experience.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34018, 'have big ideas', 'to have plans that need great effort, skill, and luck to achieve:', 'She''s got big ideas about starting up her own company.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34019, 'have bigger/other fish to fry', 'to have something more important to do', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34020, 'have butterflies (in your stomach)', 'to feel very nervous, usually about something you are going to do:', 'I had terrible butterflies before I gave that talk in Venice.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34021, 'have come a long way', 'to have advanced to an improved or more developed state:', 'Information technology has come a long way in the last 20 years.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34022, 'have deep pockets', 'to have a lot of money or wealth:', 'The politicians with the deepest pockets usually win the election.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34023, 'have dibs on something', 'to have the first right to use something, before anyone else:', 'I’ve got dibs on the sofa.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34024, 'have egg on your face', 'If you have egg on your face, you look stupid because of something that you have done:', 'This latest scandal has left the government with egg on its face.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34025, 'have eyes in the back of your head', 'to know everything that is happening around you:', 'Parents of young children need to have eyes in the back of their heads.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34026, 'have faith!', 'If you tell someone to have faith, you are encouraging them to stay confident:', 'Have faith! Everything will work out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34027, 'have fears for someone/something', 'to be worried about someone or something:', 'The climbers are a day late returning from the mountain and we are beginning to have fears for their safety.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34028, 'have feet of clay', 'to have a bad quality that you keep hidden:', 'Some of the greatest geniuses in history had feet of clay.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34029, 'have friends in high places', 'to know important people who can help you get what you want', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34030, 'have fun and games', 'to have difficulty doing something:', 'We had real fun and games trying to bath the dog.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34031, 'have gimlet eyes', 'to look at things very carefully and not miss anything', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34032, 'have got something there', 'If you say that a person has got something there, you mean they have said or discovered an important or interesting thing.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34033, 'have had it (up to here) with', 'to have suffered because of someone or something and to be no longer able to bear him, her, or it:', 'I''ve had it up to here with you - get out!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34034, 'have had it with someone/something', 'to not be willing to continue to deal with someone or something:', 'I’ve had it with this job – I’m quitting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34035, 'have had its/your day', 'to be much less popular than before:', 'She sold a lot of books in the 1990s, but she''s had her day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34036, 'have had your chips', 'to have lost your position, importance, or power', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34037, 'have half a mind/a good mind to do something', 'to think that you might do something, often because something has annoyed you:', 'I have a good mind to go without him if he''s going to be such an idiot!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34038, 'have heard of someone/something', 'If you have heard of someone or something, you know that that person or thing exists:', 'It''s a tiny country that most people have never even heard of.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34039, 'have hysterics', 'to get extremely angry or upset:', 'She''ll have hysterics when she finds out how much money is missing.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34040, 'have inner resources', 'to have the ability to help yourself manage or achieve something:', 'He can''t cope with difficult situations on his own - he has no inner resources.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34041, 'have it all to play for', 'If someone has it all to play for, the result of a competition or situation is still not known, and they still have the chance to win or be successful. :', 'We are looking forward to the challenge and we have it all to play for.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34042, 'have it both ways', 'to get advantages from two opposing things:', 'You can''t have it both ways - you either work longer and get paid more or have more leisure time and get paid less.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34043, 'have it coming (to you)', 'infml to deserve what happens to you, esp. something bad:', 'He got a ticket for speeding, but he had it coming.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34044, 'have it in for someone', 'to be determined to harm or criticize someone:', 'She''s always had it in for me.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34045, 'have it in you', 'to have a particular quality or ability:', 'His speech was really funny - we didn''t know he had it in him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34046, 'have it off', 'to have sex:', 'He was having it off with his friend''s wife.', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34047, 'have it on the highest authority', 'to have been told something by someone who knows the truth:', 'I have it on the highest authority that they are getting a divorce.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34048, 'have it out with someone', 'to talk to someone about something they have done that makes you angry, in order to try to solve the problem:', 'She''d been late for work every morning and I thought I''d better have it out with her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34049, 'have kittens', 'to be very worried, upset, or angry about something:', 'My mother nearly had kittens when I said I was going to buy a motorbike .', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34050, 'have legs', 'If a story in the news has legs, it will continue for a long time:', 'This latest scandal has legs - you''ll probably still be reading about it in a year''s time.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34051, 'have legs', 'If something has legs, it can continue to exist and be successful:', 'The business has legs.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34052, 'have money', 'to be rich:', 'I believe her family has money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34053, 'have money to burn', 'to spend a lot of money on things that are not necessary:', 'I don''t know what her job is but she certainly seems to have money to burn.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34054, 'have nerves of steel', 'to be very brave:', 'You need to have nerves of steel to be a fighter pilot.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34055, 'have news for someone', 'used to say that someone is going to be unpleasantly surprised because something will not be as they want it to be:', 'I''ve got news for him, if he thinks he can keep living here free of charge.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34056, 'have no business doing something', 'to have no right to do something:', 'You had no business reading my private letters.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34057, 'have no time for someone', 'to disapprove of someone and not want to be involved with them:', 'I have no time for people who are always complaining.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34058, 'have none of something', 'to refuse to accept, agree with, or support something:', 'She tried to persuade him to retire, but he would have none of it.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34059, 'have nothing on someone or something', 'to not be as good as someone or something:', 'He''s a good player, but he''s got nothing on his brother.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34060, 'have nothing to do with someone/something', 'to not involve someone or something:', 'This argument has nothing to do with me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34061, 'have nothing to lose', 'to be in a situation that could improve by doing something and that will not be any worse if you fail at it:', 'Since I had nothing to lose, I accepted the offer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34062, 'have nothing to say for yourself', 'to not be willing to take part in conversations or express your opinions', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34063, 'have occasion to do something', 'to need to do something:', 'Of course, as a teacher I had authority, but rarely did I have occasion to use it.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34064, 'have one foot in the grave', 'to be very old and near death', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34065, 'have seen better days', 'to be old and in bad condition:', 'That jacket has seen better days. Why don''t you get a new one?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34066, 'have shit for brains', 'to be extremely stupid:', 'Don''t ask Jack to do anything - he''s got shit for brains.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34067, 'have shot your bolt', 'to have already achieved all that you have the power, ability, or strength to do and to be unable to do more:', 'He started off the game well but seemed to have shot his bolt by half-time.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34068, 'have skin in the game', 'to be directly involved in or affected by something, especially financially:', 'If people have skin in the game, preventable costs fall.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34069, 'have someone by the balls', 'to have someone in a situation where you have complete power over them', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34070, 'have someone eating out of your hand', 'to easily make someone do or think what you want:', 'Within two minutes of walking into the classroom, she had the kids eating out of her hand.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34071, 'have someone in the palm of your hand', 'to have complete control over someone and to be able to make them do anything you want:', 'He had the audience in the palm of his hand.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34072, 'have someone on', 'to persuade someone that something is true when it is not, usually as a joke:', 'That''s your new car? You''re having me on!', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34073, 'have someone over a barrel', 'to put someone in a very difficult situation in which the person has no choice about what they do:', 'She knows I need the work so she''s got me over a barrel in terms of what she pays me.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34074, 'have someone taped', 'to know about and be able to deal with a person or situation', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34075, 'have someone to thank (for something)', 'If you have someone to thank for something, that person is responsible or to blame for it:', 'You have John to thank for this problem.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34076, 'have someone up', 'to take someone to court for a trial:', 'He was had up for burglary.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34077, 'have someone''''s guts for garters', 'If you say you will have someone''''s guts for garters, you mean that you will punish them severely:', 'If that boy has taken my bike again, I''ll have his guts for garters!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34078, 'have someone''''s number', 'to know a lot about someone and so have an advantage over them:', 'Don''t worry, I''ve got his number, he doesn''t fool me.', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34079, 'have someone/something hanging round your neck', 'to be limited in what you can do by someone or something:', 'The last thing I want is a couple of kids hanging round my neck!', 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34080, 'have something coming out of your ears', 'to have more of something than you want or need:', 'He''s going to have money coming out of his ears if this deal comes off.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34081, 'have something down to a fine art', 'to be able to do something very well or quickly, often because you have done it so many times', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34082, 'have something going for you', 'If you have something going for you, or if something has something going for it, there are certain advantages that will make the end result successful:', 'They''ve got a happy marriage, great careers, wonderful kids - in fact they''ve got everything going for them.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34083, 'have something going with someone', 'If you have something going with someone, you are involved in a sexual relationship with them:', 'Didn''t he have something going with one of his students?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34084, 'have something in common', 'to share the same interests or have similar characteristics:', 'I didn’t think Larry and Patricia had anything in common, but they talked all evening.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34085, 'have something in hand', 'to have something well organized or under control:', 'The police have the situation in hand.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34086, 'have something in hand', 'If you have something in hand, you have not yet used it and it is still available:', 'I had enough money in hand to buy a new car.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34087, 'have something in mind', 'to have a plan or intention:', 'Did you have anything in mind for Helen''s present?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34088, 'have something in your pocket', 'to be certain to win or succeed at something:', 'Last year''s winners again have the championship firmly in their pocket.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34089, 'have something on good authority', 'to be able to believe a piece of information because you trust the person who told you it:', 'I have it on good authority that she''s getting married.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34090, 'have something on the brain', 'to not be able to stop thinking or talking about one particular thing:', 'You''ve got cars on the brain. Can''t we talk about something else for a change?', 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34091, 'have something on your hands', 'If you have a difficult situation on your hands, you have to deal with it:', 'If the police carry on like this they''ll have a riot on their hands.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34092, 'have something on your hands', 'to be to blame for something:', 'We have the blood of these people on our hands (= we are responsible for their death or injury).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34093, 'have something on your mind', 'to be worrying about something:', 'Paul has a lot on his mind at the moment.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34094, 'have something on your plate', 'to have something, usually a large amount of important work, to deal with:', 'She''s got a lot on her plate - especially with two new projects starting this week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34095, 'have something on your side', 'If you have something on your side, it gives you an advantage when you are trying to achieve something:', 'I thought I would get the job, but the other person who was being considered for it had experience on his side.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34096, 'have something out', 'to have something removed from your body:', 'You''ll have to have that tooth out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34097, 'have something to play with', 'If you have a particular amount of time or money to play with, that amount is available for you to use:', 'Having only $800 to play with, they bought a second-hand piano.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34098, 'have something under your belt', 'to have learned or succeeded in something that might be an advantage in the future:', 'Basic computer skills are a good thing to have under your belt.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34099, 'have something up your sleeve', 'to have secret plans or ideas:', 'If I know Mark he''ll have one or two tricks up his sleeve.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34100, 'have something, will travel', 'said if you want to go on a journey and use a particular skill:', 'The ad in the newspaper read "Have English language skills, will travel".', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34101, 'have something/nothing to show for something', 'If you have something/nothing to show for your work or effort, you have/have not won any advantage from it:', 'I worked for two weeks, and $50 was all I had to show for it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34102, 'have sticky fingers', 'to be likely to steal:', 'The last person we hired as a cashier turned out to have sticky fingers.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34103, 'have the blues', 'to feel sad', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34104, 'have the ear of someone', 'If you have the ear of an important person, your ideas are listened to and considered important by that person.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34105, 'have the inside track', 'to have a special position within an organization, or a special relationship with a person that gives you advantages that other people do not have', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34106, 'have the last laugh', 'to finally get an advantage from an argument or disagreement, when it seemed that you would not', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34107, 'have the last word on something', 'to be the person who makes a decision without asking anyone else:', 'Carol has the last word on whether we go.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34108, 'have the measure of someone/something', 'to understand what someone or something is like and to know how to deal with him, her, or it:', 'I don''t think she''s under any illusions about her husband - she has the measure of him.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34109, 'have the odds/cards stacked against you', 'to be very unlikely to succeed because you are not in an good position', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34110, 'have the patience of a saint', 'to always be calm and never allow anything to upset you', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34111, 'have the wind at your back', 'to be in a good situation in which you can succeed:', 'The president has the wind at his back on this issue.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34112, 'have the world at your feet', 'to be extremely successful and admired by a large number of people:', 'Five years after her debut, the diminutive star of the Royal Ballet has the world at her feet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34113, 'have thin/thick skin', 'to be easily/not easily upset by criticism:', 'I don''t worry about what he says - I have a very thick skin.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34114, 'have time on your hands', 'to have nothing to do:', 'Gina has some time on her hands, so she is taking a college course.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34115, 'have time to kill', 'to have nothing to do for a particular period:', 'We''ve got some time to kill before we leave - do you want to have some coffee.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34116, 'have to do with something', 'to be about something:', 'My question has to do with last week’s assignment.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34117, 'have two left feet', 'to move in a very awkward way when dancing:', 'When we danced together, I discovered he had two left feet.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34118, 'have what it takes (to do something)', 'to have the qualities or character needed to be successful:', 'She doesn’t have a college degree, but I think she has what it takes to do the job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34119, 'have your (fair) share of something', 'to have a lot or more than enough of something bad:', 'We certainly have our share of problems at the moment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34120, 'have your back to/against the wall', 'to have very serious problems that limit the ways in which you can act:', 'He owes money to everyone - he really has his back to the wall now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34121, 'have your business, sensible, etc. head on', 'used for saying that you are considering something from a particular way of thinking:', 'I had my sensible head on that morning and knew we couldn''t afford to buy the car.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34122, 'have your cake and eat it (too)', 'to have or do two good things at the same time that are impossible to have or do at the same time:', 'You can''t have your cake and eat it - if you want more local services, you can''t expect to pay less tax.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34123, 'have your day in court', 'to get an opportunity to give your opinion on something or to explain your actions after they have been criticized:', 'She was determined to get her day in court and the TV interview would give it to her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34124, 'have your differences', 'to disagree with someone on one or more matters:', 'We’ve had our differences, but we''ve learned how to work together very well.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34125, 'have your eye on something', 'to have seen something that you want and intend to get:', 'She''s had her eye on a bike for some time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34126, 'have your feet on the ground', 'to be practical and able to take care of yourself:', 'Don’t worry about Kerry – she’s a smart girl who has her feet on the ground.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34127, 'have your finger on the trigger', 'used to say that someone is ready and prepared to do something, especially something violent:', 'They have their finger on the trigger to start a nuclear war.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34128, 'have your fingers in the till', 'to steal money from the place where you work', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34129, 'have your hands full', 'to be so busy that you do not have time to do anything else:', 'I''d love to help but I''ve got my hands full organizing the school play.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34130, 'have your head (buried/stuck) in a book', 'to be reading:', 'Rose always has her head buried in a book.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34131, 'have your head (stuck) up your (own) ass', 'an offensive phrase meaning to not pay attention to what is happening; to behave in a silly or stupid way:', 'He admitted that a lot of his co-workers had their heads up their asses.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34132, 'have your head in the clouds', 'to not know the facts of a situation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34133, 'have your head screwed on (the right way)', 'to be practical and wise:', 'Ask Lois to help - she''s got her head screwed on the right way.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34134, 'have your head up your arse', 'an offensive phrase meaning to not pay attention to what is happening; to behave in a silly or stupid way:', 'This guy has his head up his arse.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34135, 'have your knife into someone', 'to try to upset or harm someone because you dislike them', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34136, 'have your nose in a book', 'to be reading:', 'She always has her nose in a book.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34137, 'have your tubes tied', 'If a woman has her tubes tied, she has a medical operation in which her fallopian tubes are closed to stop her eggs being released so that she cannot become pregnant.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34138, 'have your wits about you', 'to think and react quickly when something dangerous or difficult happens unexpectedly:', 'She managed to keep her wits about her and escaped unharmed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34139, 'have your work cut out (for you)', 'to have something very difficult to do:', 'She''ll really have her work cut out to finish all those reports by the end of the week.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34140, 'have your/its moments', 'to be sometimes very good or successful:', 'This album may not be as good as their last one but it has its moments.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34141, 'have/get your shit together', 'to be or become effective, organized, and skilful:', 'One of these days I''ll get my shit together.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34142, 'have/get your snout in the trough', 'to have or get a share of a supply of money or some other advantage that people eagerly and sometimes dishonestly take:', 'The council had been handing out grants indiscriminately, and people were hurrying to get their snouts in the trough.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34143, 'have/hold all the aces', 'to be in a strong position when you are competing with someone else because you have all the advantages:', 'In a situation like this, it''s the big companies who hold all the aces.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34144, 'have/hold the whip hand', 'to be the person or group that has the most power in a situation:', 'During the last decade the right wing of the party has held the whip hand.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34145, 'have/keep (all) your wits about you', 'to be ready to think quickly in a situation and react to things that you are not expecting:', 'Cycling is potentially very dangerous in the city - you have to keep your wits about you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34146, 'have/keep your ear to the ground', 'to pay attention to everything that is happening around you and to what people are saying', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34147, 'have/keep your feet on the ground', 'to be very practical and see things as they really are', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34148, 'have/keep your finger on the pulse', 'to be/stay familiar with the most recent changes or improvements:', 'The situation changes daily, so you need to keep your finger on the pulse.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34149, 'have/keep your options open', 'to wait before making a choice:', 'I''m going to keep my options open while I find out about studying abroad.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34150, 'have/know something down pat', 'to know something so well that you can say or do it without having to try or think:', 'I''d given the talk so many times I had it down pat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34151, 'have/know something off pat', 'to know something so well that you can say or do it without having to try or think:', 'I''d given the talk so many times I had it off pat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34152, 'have/lead a sheltered life', 'to have a life in which you are protected too much and experience very little danger, excitement, or change:', 'Until going to college, she had led a very sheltered life.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34153, 'have/make a stab at something', 'to attempt to do something although you are not likely to be very successful:', 'I''d never tried snorkelling before but I had a stab at it while I was in Greece.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34154, 'have/put your head on the block', 'to risk a bad thing happening to you by doing something or helping someone:', 'I''m not going to put my head on the block for you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34155, 'have/take a dump', 'to pass the contents of the bowels out of the body', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34156, 'have/take a notion to do something', 'to suddenly want to do something:', 'I had a notion to write them a letter.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34157, 'have/take pride of place', 'to have the most important position in a group of things:', 'A portrait of his grandfather takes pride of place in the entrance hall.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34158, 'have/throw a fit', 'to become very angry or worried, often shouting a lot:', 'She''ll throw a fit when she sees the mess you''ve made.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34159, 'having said that', 'despite what has just been said:', 'He forgets most things, but having said that, he always remembers my birthday.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34160, 'haze over', 'If the sky hazes over, the air becomes less clear, especially because of heat:', 'The sky began to haze over in the afternoon.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34161, 'he who fights and runs away, lives to fight another day', 'used to say that it can be a good and acceptable decision to leave a difficult situation', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34162, 'he who laughs last, laughs longest/best', 'said to emphasize that the person who has control of a situation in the end is most successful, even if other people had seemed originally to have an advantage', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34163, 'he who pays the piper calls the tune.', 'said to emphasize that the person who is paying someone to do something can decide how it should be done', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34164, 'he/she deserves whatever/everything he/she gets', 'said if you think someone should have to suffer because of their bad behaviour:', 'After all the harm she''s done, she deserves whatever she gets.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34165, 'head and shoulders above', 'If someone or something is head and shoulders above other people or things, he, she, or it is a lot better than them:', 'There''s no competition - they''re head and shoulders above the rest.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34166, 'head down', 'if share prices or currencies head down, they lose value:', 'Traders who think a particular company''s shares are headed down make a profit by borrowing stock and selling it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34167, 'head for something', 'If you are heading for a bad situation, you are likely to experience it soon, because of your own actions or behaviour:', 'They''re heading for disaster if they''re not careful.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34168, 'head in the game', 'If someone has their head in the game, they are paying very careful attention to what they are doing:', 'It is important for all the jurors to have their heads in the game.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34169, 'head off', 'to start a journey or leave a place:', 'What time are you heading off?', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34170, 'head someone/something off', 'to force someone or something to change direction:', 'I tried to head the dog off by running towards it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34171, 'head something off', 'to prevent a difficult or unpleasant situation from happening:', 'The company is putting up wages to head off a strike.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34172, 'head over heels (in love)', 'completely in love', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34173, 'head something off', 'to stop something from happening:', 'The team would help developing countries head off such disasters.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34174, 'head something up', 'to lead or control a group, part of a company, etc.:', 'He headed up a Miami-based legal team.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34175, 'head/mind is whirling', 'If your head/mind is whirling, your mind is full of thoughts and images and you are so excited that you cannot relax.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34176, 'heads I win, tails you lose', 'said about a situation in which you will win whatever happens', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34177, 'heads or tails?', 'asked before you throw a coin into the air and want someone else to guess which side it will land on', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34178, 'heads will roll!', 'something that is said to mean that people will be punished for something bad that has happened', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34179, 'heap something on someone', 'to give someone a lot of praise, criticism, etc.:', 'He deals well with all the criticism heaped on him.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34180, 'hear (something) through/on the grapevine', 'to hear news from someone who heard the news from someone else:', 'I heard through the grapevine that he was leaving - is it true?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34181, 'hear from someone', 'If you hear from someone, you get a letter, email, or phone call from that person, or that person tells you something:', 'We haven''t heard from her for ages.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34182, 'hear someone out', 'to listen to someone until they have said everything they want to say:', 'At least hear me out before making up your mind.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34183, 'hear something of someone', 'to receive news about someone:', 'We haven''t heard anything of Jan for months.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34184, 'hear tell (of)', 'If you hear tell (of) something, someone tells you about it.', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34185, 'hear warning bells', 'used to describe a situation when people see signs that something bad has started or is going to happen:', 'For me, the warning bells started to ring when she lost all that weight.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34186, 'hear wedding bells', 'to think that someone is going to get married:', 'She knew that if she brought her boyfriend home her mother would start hearing wedding bells.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34187, 'hear, hear!', 'said to strongly agree with what someone else has just said', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34188, 'hear/see the last of something', 'If you hear or see the last of something or someone unpleasant or difficult, that person or thing does not cause you trouble again:', 'I paid them $100 for the damage and I hope that''s the last I''ll hear of it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34189, 'heart and soul', 'completely:', 'She loves those children heart and soul.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34190, 'heat up something', 'to make something warm or hot:', 'Let''s see what happens when I heat it up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34191, 'heat up something', 'If a situation heats up, it becomes more extreme:', 'With the political climate heating up, we can expect to hear a lot more from both candidates.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34192, 'heave a sigh of relief', 'to suddenly feel very happy because something unpleasant has not happened or has ended:', 'We both heaved a sigh of relief when she left.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34193, 'heavens (above)!', 'used to express surprise or anger', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34194, 'heavy hitter', 'someone who is powerful and has achieved a lot:', 'Have you seen his résumé? He''s a real heavy hitter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34195, 'heavy with sth', 'If something is heavy with something else, it has a lot of it or is full of it:', 'The trees were heavy with fruit.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34196, 'hedge your bets', 'to protect yourself against loss by supporting more than one possible result or both sides in a competition:', 'They''re hedging their bets and keeping up contacts with both companies.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34197, 'hell for leather', 'If you go, run, ride, etc. hell for leather, you go as fast as you can.', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34198, 'hell of a', 'extremely, or extremely big:', 'It''s a/one hell of a big decision to take.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34199, 'hell on earth', 'an extremely unpleasant place or situation:', 'Soldiers who survived the war described it as hell on earth.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34200, 'hell yes/no', 'used to emphasize that you strongly agree or disagree, like or dislike something, etc.:', '"Are you gonna go?"—"Hell yes! Try to stop me!"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34201, 'hello stranger', 'said to a person that you know but have not seen for a long time:', 'Hello stranger, I haven''t seen you for weeks!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34202, 'help (someone) out', 'If you help out, you do a part of someone''''s work or give someone money:', 'Her parents helped (her) out with a £500 loan.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34203, 'hem and haw', 'to be uncertain and take a long time deciding something:', 'We hemmed and hawed for months before actually deciding to buy the house.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34204, 'hem someone in', 'to surround someone and prevent them from moving or doing what they want to do:', 'When they reached Trafalgar Square, the demonstrators were hemmed in by the police.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34205, 'her/his heart is in the right place', 'used to say that someone has good intentions:', 'He''s an odd man but his heart is in the right place.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34206, 'here and there', 'in different places:', 'There were a few books here and there, but apart from that the room was quite bare.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34207, 'here goes!', 'said just before you do something brave or something that you have never done before:', 'Well, I''ve never ridden a motorbike before, so here goes!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34208, 'here to stay', 'If something is here to stay, it has stopped being unusual and has become generally used or accepted:', 'Blogging is here to stay.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34209, 'here today, gone tomorrow', 'said about something that lasts only a short time:', 'A lot of new internet companies are here today and gone tomorrow.', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34210, 'here we go', 'a phrase often sung repeatedly by English football crowds when their team is successful', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34211, 'here we go (again)', 'said when something bad starts happening again:', 'Oh, here we go again! Claude''s just asked to borrow some more money from me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34212, 'here you go', 'this is the object you asked me to give you:', '"Would you please pass the sugar?" "Here you go."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34213, 'here''''s mud in your eye!', 'sometimes said by people in a friendly way just before drinking an alcoholic drink together', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34214, 'here''''s to ...', 'said when asking a group of people to hold up their glasses and then drink as an expression of good wishes to someone or hope for the success of something:', 'Here''s to the happy couple!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34215, 'hero to zero', 'a situation in which someone changes quickly from being very popular or successful to being very unpopular or unsuccessful:', 'In a demonstration of the fickleness of the public, the Prime Minister has gone from hero to zero in just four months.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34216, 'hide out', 'to stay somewhere where you cannot be found:', 'Criminals often hide out in these empty apartments.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34217, 'hide your light under a bushel', 'to keep your good qualities and abilities secret from other people', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34218, 'high and mighty', 'behaving as if you are much more important than other people:', 'He was acting all high and mighty.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34219, 'hike something up', 'to lift or raise something with a quick movement:', 'She hiked up her skirt and climbed onto the bicycle.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34220, 'hinge on/upon something', 'If one thing hinges on another, the first thing depends on the second thing or is very influenced by it:', 'The prosecution''s case hinged on the evidence of a witness who died before the trial.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34221, 'hinge on/upon something', 'If a story or situation hinges on an idea or subject, it develops from that idea or that is the most important subject in it:', 'The film''s plot hinges on a case of mistaken identity.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34222, 'hire something/someone out', 'to allow someone to use something or someone temporarily in exchange for money:', 'UK How much do you charge for hiring out a bicycle for a week?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34223, 'hire yourself out', 'to arrange to be paid to do a job for another person or company:', 'He began hiring himself out as a freelance computer expert.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34224, 'hit back', 'to attack or criticize someone who has attacked or criticized you:', 'In tonight''s speech, the minister is expected to hit back at critics who have attacked her handling of the crisis.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34225, 'hit home', 'to cause you to realize exactly how unpleasant or difficult something is:', 'The full horror of the war only hit home when we started seeing the television pictures of it in our living rooms.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34226, 'hit it off (with someone)', 'to be friendly with each other immediately:', 'We had similar ideas about the show, and the two of us hit it off right away.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34227, 'hit on someone', 'to show someone that you are sexually attracted to them:', 'Some guy hit on me while I was standing at the bar.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34228, 'hit on/upon something', 'to think of an idea when you didn''''t expect or intend to, especially one that solves a problem:', 'When we first hit on the idea, everyone told us it would never work.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34229, 'hit out', 'to criticize something or someone strongly:', 'The Medical Association yesterday hit out at government cuts in healthcare services.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34230, 'hit sb up (for sth)/hit sb for sth', 'to ask someone for money:', 'She planned to hit him up for a raise.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34231, 'hit someone between the eyes', 'to shock someone or have a sudden strong effect on someone', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34232, 'hit someone up', 'to ask someone for something:', 'She hit me up for $20.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34233, 'hit someone where it hurts', 'to do or say something to someone that will upset them as much as possible:', 'He''s always worrying about his weight, so if you want to hit him where it hurts, tell him he''s looking a bit fat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34234, 'hit someone where they live', 'to affect someone in a very deep and personal way:', 'The words to that song really hit me where I live.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34235, 'hit the ball out of the park', 'in baseball, to hit the ball so hard that it goes out of the area of play:', 'He''s been hitting them out of the park all season.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34236, 'hit the ball out of the park', 'to do something extremely well:', 'The two chefs hit the ball out of the park with this entrée.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34237, 'hit the books', 'to study:', 'I can''t go out tonight. I need to hit the books.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34238, 'hit the bottle', 'to start to drink too much alcohol', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34239, 'hit the ceiling/roof', 'to become extremely angry:', 'Dad''ll hit the ceiling when he finds out I''ve left school.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34240, 'hit the deck', 'to lie down quickly and suddenly so that you are hidden from view or protected from something dangerous', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34241, 'hit the ground running', 'to immediately work hard and successfully at a new activity', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34242, 'hit the hay/sack', 'to go to bed in order to sleep:', 'I have a busy day tomorrow, so I think I''ll hit the sack.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34243, 'hit the headlines', 'to appear in the news suddenly or receive a lot of attention in news reports:', 'He hit the headlines two years ago when he was arrested for selling drugs to the mayor''s nephew.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34244, 'hit the jackpot', 'to win the largest prize in a competition or game', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34245, 'hit the jackpot', 'to have a big success or make a big profit, usually through luck:', 'He seems to have hit the jackpot with his new invention.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34246, 'hit the nail on the head', 'to describe exactly what is causing a situation or problem:', 'I think Mick hit the nail on the head when he said that what''s lacking in this company is a feeling of confidence.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34247, 'hit the panic button', 'to react to a situation with fear and confusion:', 'The coach isn''t going to hit the panic button just because we lost two games.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34248, 'hit the road', 'to leave a place or begin a journey:', 'I''d love to stay longer but I must be hitting the road.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34249, 'hit the roof', 'to become extremely angry:', 'Dad will hit the roof when he finds out I dented the car.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34250, 'hit the sack', 'infml to go to bed in order to sleep:', 'I’ve got a busy day tomorrow, so I think I’ll hit the sack.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34251, 'hit the skids', 'to fail:', 'His career hit the skids after his illness.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34252, 'hit the spot', 'to be exactly what is needed:', 'That bacon sandwich really hit the spot!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34253, 'hit the wall', 'to reach a point when you are running, exercising, playing sports, etc. where you are so physically tired you feel you cannot continue:', 'Many marathon runners hit the wall at around 20 miles.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34254, 'hit your stride', 'to become familiar with and confident at something you have recently started doing:', 'Let''s wait until she''s hit her stride before we ask her to negotiate that contract.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34255, 'hit/press/push the panic button', 'to do something quickly without thinking about it in order to deal with a difficult or worrying situation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34256, 'hit/touch a (raw) nerve', 'to upset someone:', 'She touched a raw nerve when she mentioned that job he didn''t get.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34257, 'hitch something up', 'to pull something, especially trousers or a skirt, upwards to a slightly higher position:', 'She hitched her skirt up before wading across the stream.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34258, 'hitch something up', 'If you hitch up a vehicle, you connect it so that it can be pulled, and if you hitch up an animal to a vehicle, you connect it so that it can pull the vehicle:', 'We watched as the farmer hitched up a team of oxen.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34259, 'hither and thither', 'in many directions:', 'In clearer water, one encounters shoals of tiny fish, which dart hither and thither like flights of arrows.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34260, 'hive something off', 'to separate one part of a company, usually by selling it:', 'The plan is to hive off individual companies as soon as they are profitable.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34261, 'hog the road', 'to drive so that other vehicles cannot go past', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34262, 'hold (down) the fort', 'to have responsibility for something while someone is absent:', 'I''ll be out of the office for a few hours - will you hold the fort until I get back?', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34263, 'hold a clinic', 'to be available at a particular place to provide medical care to members of the public:', 'Dr Clark holds a clinic on Tuesday mornings.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34264, 'hold a clinic', 'to be available at a particular place to provide advice to members of the public:', 'Our MP holds a clinic every Friday evening.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34265, 'hold all the cards', 'to be in a strong position when you are competing with someone else, because you have all the advantages:', 'Management holds all the cards when it comes to the negotiations over job cuts.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34266, 'hold back', 'to not do something, often because of fear or because you do not want to make a bad situation worse:', 'He held back, terrified of going into the dark room.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34267, 'hold someone/something back', 'to stop someone or something developing or doing as well as they should:', 'She felt that having children would hold her back.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34268, 'hold someone/something back', 'If you hold someone or something back, you stop him, her, or it from coming or moving forward:', 'Sandbags will hold the flood waters back for a while.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34269, 'hold something back', 'to keep information secret from someone deliberately', NULL, 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34270, 'hold something back', 'to stop yourself showing an emotion:', 'He spoke slowly, to hold back his growing anger.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34271, 'hold back on sth', 'to wait for a period of time before doing something:', 'We held back on the product release until the third quarter.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34272, 'hold court', 'to receive a lot of attention from other people who stand or sit around you to listen, especially on a social occasion:', 'Patrick is holding court at the end table.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34273, 'hold down a job', 'to manage to keep a job for a period of time', NULL, 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34274, 'hold everything!', 'used to tell someone to stop what they are doing:', 'Hold everything! He''s changed his mind again.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34275, 'hold forth', 'to talk about a particular subject for a long time, often in a way that other people find boring:', 'She held forth all afternoon about/on government incompetence.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34276, 'hold it!', 'used to tell someone to wait or stop doing something:', 'Hold it! I don''t have my coat on yet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34277, 'hold it/that against someone', 'to like someone less because they have done something wrong or behaved badly in the past:', 'He made a mistake but I don''t hold it against him - we all make mistakes.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34278, 'hold off', 'to not do something immediately:', '[ + -ing verb ] Let''s hold off making a decision until next week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34279, 'hold off', 'If rain or a storm holds off, it does not start immediately.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34280, 'hold someone off', 'to stop someone from attacking or defeating you:', 'How much longer will the resistance fighters be able to hold off the enemy?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34281, 'hold on', 'used to tell someone to wait for a short time:', 'Hold on, I''ll check in my diary.', 'phrasal verb', 'B1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34282, 'hold on', 'used to say that you are confused or surprised by something that you have just heard or read and want to understand it:', 'Now hold on, Ed, that wasn''t what we agreed at all!', 'phrasal verb', 'C1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34283, 'hold on', 'to manage to stay alive or to deal with a difficult situation:', 'We just had to hold on until help arrived.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34284, 'hold on', 'to hold something or someone firmly with your hands or arms:', 'She held on tightly to his waist.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34285, 'hold on to/onto sth/sb', 'to keep something or someone that is important or useful:', 'I held onto the tech shares after the stock market fell because I knew they would recover.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34286, 'hold on/tight', 'to continue doing something or staying somewhere although it is difficult or unpleasant to do so:', 'Hold on and I’ll go and get some help.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34287, 'hold onto someone/something', 'to hold something or someone firmly with your hands or your arms:', 'Hold onto the rope and don''t let go.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34288, 'hold onto/on to something', 'to keep something you have:', 'Hold on to your ticket - you''ll need it later.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34289, 'hold out', 'to continue to defend yourself against an enemy or attack without being defeated:', 'They won''t be able to hold out much longer under this sort of bombardment.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34290, 'hold out', 'If a supply of something such as food or money holds out, there is enough of it to last for a particular period of time.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34291, 'hold something out', 'to offer a possibility, solution, hope, etc.:', 'Few people hold out any hope of finding more survivors.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34292, 'hold out for something', 'to wait until you get what you want:', 'The workers are holding out for a ten percent pay rise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34293, 'hold out on someone', 'to refuse to give help or information to someone:', 'Don''t hold out on me - I need to know who did it.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34294, 'hold out on someone', 'to refuse to give money to someone', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34295, 'hold out/offer an olive branch', 'to do or say something in order to show that you want to end a disagreement with someone:', 'He held out an olive branch to the opposition by releasing 42 political prisoners.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34296, 'hold sb to account', 'to make someone accept that they are responsible for something and explain their actions or decisions:', 'Holding those in power to account is the essence of democracy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34297, 'hold someone in high/low repute', 'to respect someone very much/very little:', 'My father was held in high repute by his colleagues.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34298, 'hold someone ransom', 'to force someone to do something by putting that person in a situation where they have no choice:', 'He claimed his country was being held ransom by threats of withdrawing aid.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34299, 'hold someone to ransom', 'to force someone to do something by putting that person in a situation where they have no choice:', 'He claimed his country was being held to ransom by threats of withdrawing aid.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34300, 'hold someone to something', 'to make someone do what they promised or agreed to do:', 'We''ll hold him to the exact terms of the contract.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34301, 'hold someone/something down', 'to keep someone or something in a particular place or position and to stop him, her, or it from moving:', 'He was struggling so much it took three officers to hold him down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34302, 'hold something down', 'to keep something, especially costs, at a low level:', 'to hold down prices/wages', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34303, 'hold someone/something up to ridicule', 'to laugh unkindly and publicly at someone or something, or to make someone or something seem stupid:', 'Her plans were held up to ridicule.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34304, 'hold something against someone/something', 'to consider something as a reason to have a bad opinion about someone or something:', 'He made a mistake, but I don’t hold it against him – we all make mistakes.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34305, 'hold something over', 'to delay something:', 'The nomination was held over until the Senate adjourned.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34306, 'hold something over', 'If a film, play, etc. is held over, it is shown or performed more times than was originally planned, usually because it is very popular with the public.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34307, 'hold someone over', 'to delay someone from leaving:', 'The weather held us over in Denver for two days.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34308, 'hold something up as something', 'to use someone or something as an example of something, especially something very good:', 'Sweden is often held up as an example of a successful social democracy.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34309, 'hold still', 'used to tell someone to stop moving:', 'Hold still, this won''t hurt.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34310, 'hold sway', 'to have power or a very strong influence:', 'Fundamentalist beliefs hold sway over whole districts, ensuring the popularity of religious leaders.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34311, 'hold that thought', 'used for telling someone to remember an idea or thought that has just been mentioned, especially because it will be useful later', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34312, 'hold the balance of power', 'to be able to support either opposing side in a competition, etc. and therefore be able to decide who will win:', 'If independents do end up holding the balance of power, then they decide whether Labor or the Liberals govern for the next four years.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34313, 'hold the floor', 'to speak to a group of people, often for a long time, without allowing anyone else to speak', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34314, 'hold the fort', 'to have responsibility for something while someone else is absent:', 'I’m leaving my husband to hold the fort while I’m away.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34315, 'hold the key', 'to have control of something:', 'Because the two main parties have won almost the same number of votes, the minority group holds the key to the result.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34316, 'hold the phone', 'used for telling someone to wait, for example because you are going to say something surprising; sometimes used humorously when something is not surprising at all:', 'It may sound like a great offer, but hold the phone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34317, 'hold the reins', 'be in control:', 'She''s the boss but her secretary often seems to hold the reins.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34318, 'hold the road', 'If a vehicle holds the road, its wheels stay firmly on the road and do not slide while moving.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34319, 'hold together (something)', 'to keep (a group or organization) complete or in its original state or condition:', 'Social relationships held the Crow people together into the 20th century.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34320, 'hold true', 'to continue to be true:', 'Their arguments were valid a hundred years ago and they still hold true today.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34321, 'hold up', 'to remain strong or successful:', 'Will his alibi hold up (= continue to seem true) in court?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34322, 'hold someone/something up', 'to delay someone or something:', 'Traffic was held up for several hours by the accident.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34323, 'hold someone/something up', 'to steal from someone using violence or the threat of violence:', 'They held the same bank up twice in one week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34324, 'hold something up', 'If a centre forward holds up the ball, they keep control of a long pass from a defender on the same team until other members of the team can reach the opponent''''s half of the playing field:', 'Lukaku used his strength to hold up the ball, giving Baines time to sprint downfield in support.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34325, 'hold water', 'If a reason, argument, or explanation holds water, it is true:', 'Her alibi just didn''t hold water.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34326, 'hold your head (up) high', 'to be very confident and proud:', 'If you know that you did your best, you can hold your head high.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34327, 'hold your horses', 'used to tell someone to stop and consider carefully their decision or opinion about something:', 'Just hold your horses, Bill! Let''s think about this for a moment.', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34328, 'hold your nose', 'to press your nose tightly between thumb and finger in order to close it:', 'I have to hold my nose when I jump into water.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34329, 'hold your nose', 'to do something you find unpleasant or do not want to do because the other choices are worse:', 'He spent days trying to convince congressional colleagues to hold their noses and vote for the bill.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34330, 'hold your own', 'to be as successful as other people or things in a situation:', 'Josie can hold her own in any argument.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34331, 'hold your own', 'to not become more ill or more weak:', 'He''s still ill but holding his own.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34332, 'hold your tongue', 'to not speak:', 'Hold your tongue, young man!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34333, 'hold/keep someone/something at bay', 'to prevent someone or something unpleasant from harming you:', 'Exercise can help keep fat at bay.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34334, 'hold/put your hands up', 'to admit that something bad is true or that you have made a mistake:', 'I know I''m bossy and I hold my hands up to that.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34335, 'hold/stand fast', 'to firmly remain in the same position or keep the same opinion:', 'The rebels are standing fast and refuse to be defeated.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34336, 'hold/stand firm', 'to remain in the same place or at the same level:', 'The protesters stood firm as the police tried to disperse them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34337, 'hole up (somewhere)', 'to stay in a safe place, often as a way of avoiding something or hiding from someone:', 'We''d better find some shelter and hole up until the storm passes.', 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34338, 'holed below the waterline', 'damaged in a way that is not immediately obvious but that will in the end cause someone or something to fail completely:', 'Rising national debt meant any plans for big projects had been holed below the waterline.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34339, 'hollow something out', 'to make an empty space inside something:', 'Sand carried by the wind has hollowed out the base of the cliff.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34340, 'home away from home', 'a place where you feel as comfortable as you do in your own home:', 'The hotel was a real home away from home.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34341, 'home free', 'infml having finished the difficult or dangerous part of an activity and sure of finishing it successfully:', 'Once you get past the essay questions on the test, you’re home free.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34342, 'home from home', 'a place where you feel as comfortable as you do in your own home:', 'The hotel was a real home from home.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34343, 'home in on something/someone', 'to aim for:', 'The missile homed in on the ship.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34344, 'home in on something/someone', 'to find and give a lot of attention to something or someone:', 'The report homed in on the weaknesses in the management structure.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34345, 'honest (to God/goodness)', 'used to emphasize that what you are saying is true:', 'I tried to be nice to him, honest to God I did!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34346, 'honesty is the best policy', 'said to advise someone that it is better to tell the truth than to lie', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34347, 'hoof it', 'to walk somewhere, or to walk somewhere quickly:', 'We missed the bus and had to hoof it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34348, 'hook (someone/something) up (to something)', 'to connect a machine to a power supply or to another machine, or to connect a person to a piece of medical equipment:', 'Can we hook up to the electricity supply at the campsite?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34349, 'hook (sth) into sth', 'to become connected or to connect something to a computer or telephone system:', 'After the takeover, one of the company''s first acts was to hook the newly acquired bank into its own computer systems.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34350, 'hook up', 'to meet or begin to work with another person or other people:', 'He hooked up with the other members of the band in Amsterdam.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34351, 'hook up', 'to begin a romantic or sexual relationship with someone:', 'When did you two first hook up?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34352, 'hook up (with sb/sth)', 'to meet or begin to work with another person or organization:', 'a conference where startup companies can hook up with investors', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34353, 'hook sb up (with sb/sth)', 'to arrange for someone to meet or work with another person or organization:', 'We videotape applicants in practice interviews and hook them up with employers.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34354, 'hook, line, and sinker', 'completely:', 'I forged the note and the teacher fell for it hook, line, and sinker.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34355, 'hoover something up', 'to remove something from a floor or other surface using a vacuum cleaner (= a machine that sucks up dust and dirt):', 'We''ll hoover up the debris, then we will sit down and open a bottle of wine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34356, 'hoover something up', 'to use something quickly and eagerly:', 'The country is hoovering up ever more commodities because its economy is growing so quickly.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34357, 'hop it', 'used to tell someone to go away', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34358, 'hope against hope', 'to hope very strongly that something will happen, although you know it is not likely:', 'They''re just hoping against hope that she''s still alive.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34359, 'hope for the best', 'to hope that something will be successful or happen in the way you want, even if it seems unlikely:', 'I''ve repaired it as well as I can - we''ll just have to hope for the best.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34360, 'hope over experience', 'said in order to express the idea that someone hopes that something will work well in the future, although experience shows that it has not worked well in the past:', 'Hasty company mergers are often a triumph of hope over experience.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34361, 'hope springs eternal', 'said when you continue to hope that something will happen, although it seems unlikely', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34362, 'hope/wish/swear to God', 'used for emphasis:', 'I hope to God (that) he turns up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34363, 'hopping mad', 'very angry', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34364, 'horn in', 'to try to become involved in a discussion or activity when you are not wanted:', 'She''s always horning in on our conversations.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34365, 'horror of horrors', 'said when you are telling someone about a very bad or embarrassing situation:', 'Then, horror of horrors, I discovered that my zip had been undone the whole time I was talking to her.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34366, 'horse around', 'to behave in a silly and noisy way:', 'He was horsing around in the kitchen and broke my favourite bowl.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34367, 'horses for courses', 'used to say that it is important to choose suitable people for particular activities because everyone has different skills', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34368, 'hostage to fortune', 'an action or statement that could create problems for you later:', 'The prime minister was extremely cautious, saying nothing inflammatory and giving no hostages to fortune.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34369, 'hot air', 'If something that someone says is hot air, it is not sincere and will have no practical results:', 'His promises turned out to be a lot of hot air.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34370, 'hot and heavy', 'If something or someone is hot and heavy, they are full of strong emotions or sexual feelings:', 'Guess who I saw getting hot and heavy on the dance floor?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34371, 'hot off the press', 'News that is hot off the press has just been printed and often contains the most recent information about something.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34372, 'hot to trot', 'sexually excited and wanting to find someone to have sex with', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34373, 'hot under the collar', 'embarrassed or angry about something:', 'When I suggested he was mistaken he got rather hot under the collar.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34374, 'hot up', 'If an event or situation hots up, it becomes more exciting and more things start to happen:', 'A few days before the elections, the pace began to hot up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34375, 'hound someone out', 'to force someone to leave a job or a place:', 'He claims he was hounded out of his job by a group of students who disapproved of his views.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34376, 'hour after hour', 'for many hours without stopping:', 'I sat by her bedside for hour after hour.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34377, 'hours (and hours)', 'infml a long time:', 'I spent hours filling out forms.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34378, 'house of cards', 'a complicated organization or plan that is very weak and can easily be destroyed or easily go wrong', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34379, 'how about that?', 'used to emphasize that something is surprising:', 'Sales are up by 36 percent. How about that?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34380, 'how about...?', 'used to make a suggestion:', 'How about the cinema tonight?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34381, 'how about...?', 'used when asking someone about a different thing:', 'You don''t eat meat, do you? How about fish?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34382, 'how are things (with you)?', 'informal for "how are you?"', NULL, 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34383, 'how are you fixed for something?', 'used to ask how much of something someone has, or to ask about someone''''s arrangements:', 'How are you fixed for cash?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34384, 'how are you keeping?', 'used to ask if someone is well:', 'How''s your mother keeping?', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34385, 'how are you placed for...?', 'used to ask someone if they have enough money, time, etc.:', 'How are you placed for money?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34386, 'how come?', 'used to ask about the reason for something:', 'So how come you got an invitation and not me?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34387, 'how dare she, you, etc.!', 'used to express anger about something someone has done:', 'How dare you use my car without asking!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34388, 'how dare you do something', 'I am very surprised and shocked by what you are doing:', 'How dare you question my authority?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34389, 'how do you do?', 'a formal greeting for someone that you have not met before:', '"I''m Jack Stewart." "How do you do? I''m Angela Black."', 'idiom', 'A2', NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34390, 'how do you do', 'a difficult, worrying, and unpleasant situation:', '"I had a row with my sister and now she''s refusing to talk to me." "Well, that''s a fine how do you do!"', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34391, 'how do you like...?', 'used when asking someone how they like their drinks made:', '"How do you like your tea?" "Milk and one sugar, please."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34392, 'how do you like...?', 'used when asking someone for an opinion:', 'How do you like my new shoes?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34393, 'how does... grab you?', 'used to ask if someone would like to do something or is interested in something:', 'We could have a picnic in the park. How does that grab you?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34394, 'how long is a piece of string?', 'said when you cannot answer a question about the length, size, amount, etc. of something because it could be any length, size, etc.:', 'Asked how long this will take, she replies: "How long is a piece of string?"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34395, 'how sb rolls', 'how someone generally likes to do things:', 'Not a good system you say, but that''s how I roll.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34396, 'how should I know?', 'I cannot be expected to know:', '"Where''s Mikey?" "How should I know? He''s hardly ever in the office these days."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34397, 'how the other half lives', 'something people say when they see or hear about the lives of people who are richer than them', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34398, 'how was I to know?', 'used to say that something you did wrong was not your fault because you did not have enough information:', 'I just wanted to give her a surprise; how was I to know you''d already bought tickets?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34399, 'how would you like...?', 'said to suggest that someone would not like to be in a situation experienced by someone else:', 'I''m not surprised he shouted at you! How would you like to be pushed into a wall?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34400, 'how''''s life (treating you)?', 'said as an informal greeting', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34401, 'how''''s tricks?', 'how are you?:', '"Hi, how''s tricks?" "Oh, fine, how are you doing?"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34402, 'how''''s you?', 'an informal way to greet someone you know and ask how they are:', 'How''s you? How was work today?', 'idiom', NULL, NULL, 'informal, spoken', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34403, 'how, what, why, etc. on earth...', 'used when you are extremely surprised, confused, or angry about something:', 'How on earth did this happen?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34404, 'how/what about...?', 'used when suggesting or offering something to someone:', 'How about a trip to the zoo this afternoon?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34405, 'hue and cry', 'a noisy expression of public anger or disapproval:', 'There has been a great hue and cry about the council''s plans to close the school.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34406, 'huff and puff', 'to breathe loudly, usually after physical exercise:', 'We were huffing and puffing by the time we''d climbed to the top of the hill.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34407, 'huff and puff', 'to complain loudly and express disapproval:', 'They huffed and puffed about the price but eventually they paid up.', 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34408, 'hum and haw', 'to be uncertain and take a long time deciding something:', 'We hummed and hawed for months before actually deciding to buy the house.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34409, 'hung, drawn, and quartered', 'In the past, if someone was hung, drawn, and quartered, the person was hanged by the neck and their body was cut into pieces.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34410, 'hunger after/for something', 'to want something very much:', 'I hunger for your touch.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34411, 'hunker down', 'to sit down on your heels:', 'We hunkered down around the campfire, toasting marshmallows.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34412, 'hunker down', 'to make yourself comfortable in a place or situation, or to prepare to stay in a place or position for a long time, usually in order to achieve something or for protection:', 'The press have hunkered down for the night outside the palace, waiting for news of the royal birth.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34413, 'hunt someone/something down', 'to search everywhere for someone or something until you find him, her, or it:', 'The terrorists must be hunted down and brought to justice.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34414, 'hunt/search high and low', 'to search everywhere for something:', 'I''ve been hunting high and low for that certificate and I still can''t find it!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34415, 'hurl/throw/sling mud at someone', 'to say insulting or unfair things about someone, especially to try to damage their reputation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34416, 'hurry (someone/something) up', 'to move or do things more quickly than normal or to make someone do this:', 'Hurry up or we''ll miss the train.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34417, 'hurry (someone/something) up', 'to do something very soon:', 'All I wanted was for those people to hurry up and leave.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34418, 'hurry up and do something', 'to do something very soon:', 'All I wanted was for these very boring people to hurry up and leave.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34419, 'hurt someone''''s feelings', 'to upset someone by criticizing them or by refusing something that they have offered you', NULL, 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34420, 'hush something up', 'to try to prevent people from discovering particular facts:', 'There was some financial scandal involving one of the ministers but it was all hushed up.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34421, 'hype someone up', 'to make someone feel very excited:', 'I always feel hyped up before an exam.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34422, 'ice over', 'If an area of water ices over, it becomes covered with a layer of ice:', 'The lake has iced over.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34423, 'ice up', 'to become covered in ice and often stop working:', 'The plane was delayed because the engine had iced up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34424, 'identify with someone', 'to feel that you are similar to someone in some way and that you can understand that person or their situation because of this:', 'Many women of normal weight feel unable to identify with the super-thin models in fashion magazines.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34425, 'identify someone/something with something', 'to believe that someone or something is closely connected or involved with something:', 'Many football fans are unfairly identified with violent behaviour.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34426, 'idle something away', 'to spend a period of time relaxing and doing very little:', 'We idled away the hours drinking and playing cards.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34427, 'if I may be/make so bold (as to)', 'a polite way of asking for or suggesting something when you do not want to offend someone:', 'If I may be so bold, you still haven''t mentioned why you''re here.', 'idiom', NULL, NULL, 'old-fashioned, formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34428, 'if I were in your shoes', 'used when you want to tell someone what you would do in their situation:', 'If I were in your shoes, I think I''d write to her rather than try to explain over the phone.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34429, 'if I were you', 'used when you give someone advice:', 'If I were you, I''d probably go.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34430, 'if all else fails', 'if what was planned cannot happen:', 'We could go to the beach or to my sister''s house, and if all else fails, we can always find something to do at home.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34431, 'if and when', 'at the time that something happens:', 'We don''t own a car - we just rent one if and when we need it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34432, 'if anything', 'used when saying that what people may believe is not true, and the opposite may be true:', 'Her success hasn''t caused tension - if anything, it''s helped our marriage.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34433, 'if anything', 'used when saying that there may be nothing:', 'We need to assess what happened and what, if anything, we could have done to prevent it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34434, 'if at first you don''''t succeed, try, try again', 'said to encourage someone who has failed at something to try to do it again', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34435, 'if ever there was one', 'used to emphasize that what you are saying is true:', 'It was a brilliant performance if ever there was one.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34436, 'if it ain''''t broke, don''''t fix it', 'said when you recognize that something is in a satisfactory state, and there is no reason to try to change it', NULL, 'idiom', NULL, NULL, 'informal, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34437, 'if it''''s not one thing, it''''s another', 'used when bad things keep happening to you', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34438, 'if it/a thing is worth doing, it''''s worth doing well', 'used to emphasize that if you are going to spend time doing a piece of work, you should do it as well as possible', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34439, 'if looks could kill...', 'said when you see someone look very angrily at someone else', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34440, 'if my memory serves me right', 'if I remember correctly:', 'I think he was called Blake, if my memory serves me right.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34441, 'if need be', 'if it is necessary:', 'If need be, we can take two cars.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34442, 'if only', 'used when you want to say how doing something would make it possible to avoid something unpleasant:', 'If only she''d listen to what he''s saying, I''m sure they could solve the problem.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34443, 'if the cap fits (wear it)', 'used to tell someone that they should accept a criticism that another person has made', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34444, 'if the shoe fits (wear it)', 'used to tell someone that they should accept a criticism that another person has made', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34445, 'if the worst comes to the worst', 'if the situation develops in the most serious or unpleasant way:', 'We should be in when you arrive, but if the worst comes to the worst, the neighbours have a spare key and will let you into the house.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34446, 'if worse/worst comes to worst', 'if the situation develops in the most serious or unpleasant way:', 'We should be in when you arrive, but if worst comes to worst, the neighbors have a spare key and will let you into the house.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34447, 'if you ask me', 'said when giving your opinion on something:', 'If you ask me, people should go on a training course before they become parents.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34448, 'if you can''''t beat ''''em, join ''''em', 'said when you accept that you cannot be as successful as other people without doing what they do, even though you do not approve of or agree with it', NULL, 'idiom', NULL, NULL, 'informal, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34449, 'if you can''''t stand the heat, get out of the kitchen', 'used as a way to tell someone that they should either stop complaining about a difficult or unpleasant activity, or stop doing it', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34450, 'if you don''''t mind me saying/asking', 'used in order to be more polite when you say something that could slightly upset, annoy, or embarrass someone:', 'If you don''t mind me saying (so), I think the soup needs a little more salt.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34451, 'if you like', 'used for asking if someone agrees with a suggestion:', 'We can leave now if you like.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34452, 'if you take my meaning', 'used to say that you have left out information or your opinion from what you have just said, but that you expect the person listening still to understand it:', 'Let''s just say we had "problems", if you take my meaning.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34453, 'if you will', 'used to say that a particular expression is one way of saying something, especially to suggest that some people may not choose to say it that way:', 'I did very well in school , with a "genius IQ" if you will.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34454, 'if you''''ll pardon the expression', 'said before or after using language that other people might consider shocking:', 'The man doesn''t know his arse from his elbow, if you''ll pardon the expression.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34455, 'if/when it comes to the crunch', 'if/when a situation becomes extremely serious and a decision must be made:', 'If it comes to the crunch and you and your husband do split up, you can always stay with us.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34456, 'if/when push comes to shove', 'If something can be done if push comes to shove, it can be done if the situation becomes so bad that you have to do it:', 'If push comes to shove, we can always sell the car.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34457, 'ignorance is bliss', 'said to emphasize that sometimes it is better for you if you do not know all the facts about a situation', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34458, 'ill at ease', 'feeling anxious and not relaxed:', 'He looked ill at ease in the room full of reporters.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34459, 'imbue something/someone with something', 'to fill something or someone with a particular feeling, quality, or idea:', 'His poetry is imbued with deep, religious feeling.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34460, 'impinge on/upon someone/something', 'to have an effect on something, often causing problems by limiting it in some way:', 'The government''s spending limits will seriously impinge on the education budget.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34461, 'impress something on/upon someone', 'to make someone understand or be familiar with the importance or value of something:', 'Mr Simmons tried to impress on me how much easier my life would be if I were better organized.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34462, 'improve on/upon something', 'to do something in a better way or with better results than before:', 'Last time she ran the race in 20 minutes, so she''s hoping to improve on that.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34463, 'impute something to someone', 'to say that someone is responsible for something that has happened, or that something is the cause of something else:', 'They imputed the error to the lawyer who was handling her case.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34464, 'impute something to someone', 'to believe that someone or something has a particular characteristic, quality, or meaning:', 'He arrogantly imputed stupidity to anyone who disagreed with him.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34465, 'in God''''s/heaven''''s name', 'used to add force to something that is said. Some people find the use of "God" offensive:', 'What in God''s name caused that outburst?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34466, 'in a ... place', 'used to talk about someone''''s feelings, situation, or mental condition:', 'I feel like I''m in a better place about who I am.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34467, 'in a class by your/itself', 'excellent, or the best of its kind:', 'Her singing is in a class by itself.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34468, 'in a dream', 'not conscious of what is happening around you because other thoughts are filling your mind:', 'I didn''t hear what you were saying - I was in a dream.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34469, 'in a flash', 'quickly or suddenly:', 'The ceremony was over in a flash.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34470, 'in a flutter', 'in a confused and excited state:', 'When economic statistics are first published they grab headlines and put markets in a flutter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34471, 'in a heartbeat', 'very quickly, without needing to think about it:', 'I''d do it again in a heartbeat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34472, 'in a huff', 'feeling angry and upset:', 'When Julia criticized his art, Geraldo left in a huff.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34473, 'in a manner of speaking', 'used for saying that something is partly true:', 'She''s his partner, in a manner of speaking.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34474, 'in a nutshell', 'very briefly, giving only the main points:', '"What went wrong?" "In a nutshell, everything."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34475, 'in a pinch', 'Something that you can do in a pinch can be done if it is really necessary, but it will be difficult, not perfect, or not what you would really like:', 'I need $20,000 to set up the business, but I suppose $15,000 would do in a pinch.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34476, 'in a spin', 'worried and confused:', 'She''s in a spin over the arrangements for the party.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34477, 'in a stew', 'If someone is in a stew, that person is in a difficult situation that causes them to feel worried or upset:', 'William is in a stew about/over his tax return.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34478, 'in a way', 'considered in a particular manner:', 'In a way, I hope he doesn’t win.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34479, 'in a word', 'said when you are going to give your opinion about something quickly and directly:', 'In a word, she''s lying.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34480, 'in a world of your own', 'thinking your own thoughts and ideas and not giving much attention to what is happening around you:', 'When she was young, she lived in a world of her own and had very few friends.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34481, 'in advance', 'before a particular time, or before doing a particular thing:', 'If you''re going to come, please let me know in advance.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34482, 'in advance of something/someone', 'before something or someone:', 'She arrived in advance of everyone else.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34483, 'in all', 'with everything added together to make a total:', 'The bill came to £25 in all.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34484, 'in all but name', 'existing as a fact but not officially described that way:', 'She is vice-president in all but name.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34485, 'in all conscience', 'without feeling guilty:', 'You couldn''t, in all conscience, ask her to pay the whole bill!', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34486, 'in all honesty/seriousness/truthfulness', 'said when expressing your opinion honestly, seriously, or truthfully:', 'In all honesty, I do have some criticisms to make.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34487, 'in all my (born) days', 'in all of my life:', 'I''ve never seen anything so strange in all my born days.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34488, 'in all weathers', 'If something is done in all weathers, it is done in every type of weather:', 'He goes fishing in all weathers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34489, 'in any case', 'whatever happens or happened:', 'You should be able to catch a bus, but in any case you can always take a taxi home.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34490, 'in any event', 'whatever happens:', 'I hope to see her this afternoon, but in any event I’m leaving town tomorrow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34491, 'in arrears', 'owing money that should have been paid already:', 'My account is badly in arrears.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34492, 'in arrears', 'If someone is paid in arrears, they are paid at the end of the period of time during which the money was earned:', 'I''m paid a week in arrears.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34493, 'in back of', 'behind:', 'The garbage cans are in back of the house.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34494, 'in balance', 'spending no more money in a budget (= financial plan) than is taken in during a particular period:', 'We want to cut the budget to get it in balance by next year.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34495, 'in ballast', '(of a ship) not carrying any cargo (= goods), but with containers filled with sea water to add weight:', 'vessels arriving at the port laden or in ballast
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34496, 'in bed', 'having sex:', 'She found her boyfriend in bed with another woman.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34497, 'in bed', 'referring to sexual activity:', 'He likes to make people think that he''s good in bed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34498, 'in black and white', 'in writing:', 'I had to believe it, because it was there in black and white.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34499, 'in blissful ignorance', 'not knowing any of the unpleasant facts about something:', 'All the time his business was failing, he kept his wife and family in blissful ignorance.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34500, 'in broad daylight', 'If a crime is committed in broad daylight, it happens during the day, when it could have been seen and prevented:', 'Thieves had broken into the house in broad daylight.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34501, 'in buckets', 'in great amounts:', 'The rain came down in buckets.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34502, 'in business', 'able to start doing something that you had planned:', 'Once we get the computer installed we’ll be in business.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34503, 'in charge (of something/someone)', 'responsible for something or someone:', 'Who’s in charge here?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34504, 'in check', 'being controlled within reasonable limits:', 'We’ve got to find ways of keeping our expenses in check.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34505, 'in cold blood', 'If someone kills in cold blood, they kill in a way that seems especially cruel because it seems to show no emotion.', NULL, 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34506, 'in commission', 'If something, such as a machine or a military ship, is in commission it is working and ready for use.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34507, 'in concert', 'playing or singing with other musicians in a public performance:', 'She was appearing in concert at Carnegie Hall.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34508, 'in concert', 'together:', 'If the member countries would act in concert, the problem might be solved more easily.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34509, 'in conclusion', 'fmlfinally:', 'In conclusion, I''d like to express my thanks to everyone who participated in this project.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34510, 'in deep (trouble)', 'in serious trouble:', 'You will be in deep trouble with Dad if you don''t tell him the truth now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34511, 'in deep doo-doo', 'in a lot of trouble:', 'Would it be safe to say the state budget is in deep doo-doo?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34512, 'in dire straits', 'in a very bad situation that is difficult to fix:', 'These kids are in dire straits, and the schools are doing nothing to help them!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34513, 'in fact', 'actually:', 'He was in fact near death by the time they reached him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34514, 'in fits of laughter', 'laughing a lot:', 'His stories had them in fits of laughter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34515, 'in flower', 'If a plant is in flower, it has open flowers:', 'Our roses are usually in flower from April to November.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34516, 'in foal', '(of a female horse) pregnant:', 'Two of the mares are in foal.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34517, 'in for a penny (in for a pound)', 'something you say that means that since you have started something or are involved in it, you should complete the work although it has become more difficult or complicated than you had expected', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34518, 'in for something', 'going to experience something:', 'It looks like we’re in for rain.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34519, 'in force', 'in large numbers:', 'Volunteers turned out in force to plant pines, crab-apple trees, and lilac bushes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34520, 'in force', 'If laws, rules, or systems are in force, they exist and are being used:', 'New regulations limiting fishing on this river are now in force.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34521, 'in front of', 'done or said when the person you are talking about is present:', 'Why did you have to embarrass me in front of all those people?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34522, 'in full cry', 'talking continuously about something in a noisy or eager way:', 'The opposition was in full cry in Parliament last night over the proposed changes to the education bill.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34523, 'in full swing', 'at a stage when the level of activity is at its highest:', 'When we got there, the party was in full swing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34524, 'in glorious technicolor', 'very colourful or too brightly coloured:', 'Her room was painted in glorious technicolor.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34525, 'in good conscience', 'without feeling guilty:', 'You couldn''t, in good conscience, ask her to pay the whole bill!', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34526, 'in good faith', 'If something is done in good faith, it is done sincerely and honestly:', 'She was acting in good faith for her client.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34527, 'in good hands', 'managed or cared for with great attention:', 'You’ll be in good hands with her – she’s a terrific lawyer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34528, 'in good time', 'early:', 'We''ll be at the airport in good time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34529, 'in good, bad, etc. repair', 'in good, bad, etc. condition:', 'The house is in very good repair.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34530, 'in hand', 'being worked on or dealt with now:', 'They''ve had plenty of time to prepare, so the arrangements should be well in hand (= almost ready).', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34531, 'in harness with', 'working together to achieve something', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34532, 'in high gear', 'very active and productive:', 'The movie really goes into high gear when Williams appears on screen.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34533, 'in his/her/their wisdom', 'something that you say when you do not understand why someone has done something stupid:', 'The council, in its wisdom, decided to close the library and now the building stands empty.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34534, 'in hot pursuit', 'following someone closely, trying hard to catch them:', 'The gang drove off, with the police in hot pursuit.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34535, 'in hot water', 'in a difficult situation in which you are likely to be punished:', 'Emails that criticize others can land you in hot water, so be careful what you write.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34536, 'in inverted commas', 'used in spoken English after a word or phrase to show that it has not been used accurately or that the opposite meaning is intended:', 'Sick prisoners in the camp were "cared for", in inverted commas, by guards, not nurses.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34537, 'in kind', '(of payment) given in the form of goods or services and not money:', 'She wouldn''t take any money but said I could pay her in kind by lending her the car.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34538, 'in kind', 'If you do something in kind, you do the same thing to someone that they have just done to you.', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34539, 'in knots', 'If your stomach is in knots, it feels tight and uncomfortable because you are nervous or excited.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34540, 'in lieu of', 'instead of:', 'The company is allowing workers to receive cash in lieu of vacation time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34541, 'in light of something', 'because of:', 'In light of recent incidents, we are asking our customers to take particular care of their personal belongings.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34542, 'in limbo', 'in a situation where you do not know what will happen or when something will happen:', 'We were in limbo for weeks while the jury tried to make a decision in the case.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34543, 'in line for something', 'likely to get a job or benefit:', 'I’m in line for a promotion.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34544, 'in line with something', 'similar to, or at the same level as something:', 'The company''s results are in line with stock market expectations.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34545, 'in line with something', 'according to or following something such as a rule or principle:', 'A workforce diversity committee will set specific objectives in line with the policy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34546, 'in luck', 'experiencing a surprisingly good situation:', '"Do you have any tickets for tonight’s game?" "You’re in luck – we have two left."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34547, 'in memory of someone', 'as a way of remembering someone who has died:', 'A service was held in memory of those who had died in the fighting.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34548, 'in midstream', 'in the middle of an activity, often one that is interrupted:', 'She interrupted him in midstream to ask a question.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34549, 'in mint condition', 'in excellent condition, as if new:', 'Alex’s old Cadillac is in mint condition.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34550, 'in my book', 'in my opinion:', 'She''s never lied to me, and in my book that counts for a lot.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34551, 'in my day', 'when I was young:', 'Kids take so much for granted nowadays - in my day a new bike was really special.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34552, 'in name only', 'If a situation exists in name only, it is officially described that way, although that description is not completely accurate:', 'A large percentage of the population is Catholic, though many are so in name only.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34553, 'in no time (at all)', 'very quickly:', 'Now that we’re on the highway, we’ll be there in no time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34554, 'in no uncertain terms', 'very clearly and often unkindly:', 'She was told in no uncertain terms that the magazine had no interest in her short stories.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34555, 'in no way', 'not at all:', 'She added that she had in no way intended to offend anybody.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34556, 'in on something', 'involved with or knowing about a particular activity or plan:', 'He seems to be in on everything that happens at work.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34557, 'in on the ground floor', 'involved in something from its beginning:', 'Can someone tell me how you get in on the ground floor of a deal like that?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34558, 'in on the ground floor', 'involved in something from its beginning:', 'Can someone tell me how you get in on the ground floor of a deal like that?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34559, 'in ones and twos', 'in small numbers:', 'The replies came back in ones and twos.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34560, 'in order', 'right for the occasion:', 'I think congratulations are in order for the new graduates in the room!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34561, 'in order for something to happen', 'if you want a particular result:', 'In order for us to win, we’ll all have to try a little harder.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34562, 'in order to do something', 'with the aim or purpose of doing something:', 'He came home early in order to see the children before they went to bed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34563, 'in other words', 'to explain it more clearly:', 'He was economical with the truth – in other words, he lied.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34564, 'in passing', 'while talking or thinking about something else:', 'Leo mentioned in passing that you are going on vacation next week.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34565, 'in person', 'by meeting with someone rather than talking on the phone, e-mailing, or writing to the person:', 'You must apply for the license in person.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34566, 'in phase/out of phase', 'If two things are happening in/out of phase they are reaching the same or related stages at the same time/at different times.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34567, 'in pieces', 'in separate parts rather than as a single thing:', 'The little house was shipped in pieces from France and then reassembled.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34568, 'in pieces', 'broken into small parts:', 'The precious vase lay in pieces on the floor.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34569, 'in pieces', 'completely destroyed:', 'My marriage was in pieces - there was nothing left except animosity.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34570, 'in pieces', 'extremely upset:', 'She was in pieces when she heard he''d died.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34571, 'in pieces', 'in small amounts:', 'They''re going to get information in pieces.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34572, 'in plain sight', 'in a place where people can clearly see something:', 'Don''t leave expensive items out in plain sight.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34573, 'in pocket', 'having more money than you started with after an activity involving money:', 'Even when we''ve paid all our expenses, we should still be several hundred pounds in pocket.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34574, 'in someone''''s pocket', 'in a situation where someone has power or control over you:', 'The head teacher has the school governors completely in her pocket/The school governors are completely in the head teacher''s pocket.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34575, 'in regard to someone/something', 'in relation to someone or something:', 'I am calling in regard to your recent inquiry.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34576, 'in relation to something', 'in connection with something:', 'The drug is being studied for possible beneficial effects in relation to migraine headaches.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34577, 'in relation to something', 'In relation to also means compared with:', 'She checked the map to see where Miami is in relation to Orlando.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34578, 'in respect of something', 'in connection with something:', 'I am writing with respect to your letter of 15 June.', 'idiom', 'B2', NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34579, 'in return for something', 'as an exchange for something:', 'The farmer offered us food in return for our work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34580, 'in ribbons', 'torn into narrow strips:', 'Her coat was in ribbons.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34581, 'in rotation', 'one after the other, in a regular order:', 'There are ten employees and they do the various jobs in rotation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34582, 'in safe hands', 'being cared for or dealt with by someone skilled:', 'Dr Bailey is doing the operation, so your wife is in safe hands.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34583, 'in sb''''s gift/in the gift of sb', 'If something is in someone''''s gift, that person can decide who to give it to:', 'Appointments to these posts were in the gift of the monarch.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34584, 'in secret', 'in a private place with no one else present and without other people knowing:', 'The negotiators were meeting in secret for several months before the peace agreement was made public.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34585, 'in secret', 'only in someone''''s thoughts, without telling other people:', 'He says he loathes her, but I think in secret he really likes her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34586, 'in seventh heaven', 'extremely happy:', 'Since they got married, they’re in seventh heaven .', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34587, 'in shirtsleeves', 'dressed informally, wearing a shirt with no jacket over it:', 'Because it was so hot, the men were all in their shirtsleeves.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34588, 'in short', 'used before describing something or someone in as few words and as directly as possible:', 'He''s disorganized, inefficient, never there when you want him - in short, the man''s a pain.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34589, 'in short supply', 'only available in small amounts:', 'Money was in short supply.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34590, 'in small doses', 'for short periods of time:', 'I can only stand opera in small doses.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34591, 'in so many words', 'directly, or in a way that makes it very clear what you mean:', '"Did he say he was unhappy with Anna?" "Well, not in so many words, but that was certainly the impression I got."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34592, 'in someone''''s capable hands', 'being dealt with by the person mentioned:', 'I''m going away next week, so I''ll be leaving everything in your capable hands.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34593, 'in someone''''s crosshairs', 'If you are in someone''''s crosshairs, they intend to catch, arrest, or stop you:', 'He''s in the law''s crosshairs now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34594, 'in someone''''s eyes', 'in someone''''s opinion:', 'And although she was probably just an ordinary-looking kid, in my eyes she was the most beautiful child on the face of the planet.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34595, 'in someone''''s good/bad books', 'If you are in someone''''s good/bad books, they are pleased/not pleased with you:', 'He''s in Melanie''s bad books because he arrived two hours late.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34596, 'in someone''''s hour of need', 'at a time when someone really needs help:', 'She helped me in my hour of need.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34597, 'in someone''''s infinite wisdom', 'used to show that you do not understand why someone has done something and that you think it was a stupid action:', 'The authorities, in their infinite wisdom, decided to close the community centre.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34598, 'in someone''''s words', 'used when you repeat what someone said:', 'His wife, Mary, was 25 years his junior and, in his words, "my guiding light".', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34599, 'in someone’s debt', 'grateful for something someone did for you:', 'I’m in the senator’s debt for getting my husband a visa.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34600, 'in someone’s employ', 'working for someone:', 'Mr. Neil is currently in our employ.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34601, 'in spades', 'in large amounts or to a very great degree:', 'My dog has personality in spades.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34602, 'in spite of something', 'even though there is something unpleasant or bad happening:', 'In spite of his injury, Ricardo will play in Saturday’s game.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34603, 'in step with someone/something', 'in agreement with someone or something:', 'She is very much in step with the times.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34604, 'in step with someone/something', 'In step with can also mean at the same speed or level as someone or something:', 'Gasoline prices rose in step with oil prices.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34605, 'in stitches', 'If a joke or funny story has you in stitches, it makes you laugh a lot.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34606, 'in store (for someone/something)', 'planned or likely to happen:', 'We have a big surprise in store for you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34607, 'in tandem', 'at the same time:', 'The heart and lungs will be transplanted in tandem.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34608, 'in tandem', 'If two pieces of equipment, people, etc. are working in tandem, they are working together, especially well or closely:', 'I want these two groups to work/operate in tandem on this project.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34609, 'in terms of something', 'in relation to something:', 'We try to do what is best for our customers in terms of the quality of our products.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34610, 'in terror of your life', 'frightened that you will be killed', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34611, 'in the (grand) scheme of things', 'considering everything:', 'In the scheme of things, having lots of money isn''t as important as having friends.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34612, 'in the air', 'If something is in the air, you feel that it is happening or about to happen:', 'With these elections, it feels like change is in the air.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34613, 'in the area of', 'approximately:', 'The repair work will cost in the area of £200.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34614, 'in the back of your mind', 'held as an idea in your mind, but not thought about frequently', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34615, 'in the bag', 'certain to be won, achieved, or obtained:', 'When the score got to 8 to 2 we knew the game was in the bag.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34616, 'in the balance', 'If a situation is in the balance, it has reached a stage where it will soon be decided one way or another:', 'The game hung in the balance until the last minute.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34617, 'in the black', 'earning more money than you spend:', 'This year our business is in the black.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34618, 'in the blink of an eye', 'extremely quickly:', 'In the blink of an eye, he was gone.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34619, 'in the bosom of something', 'If you are in the bosom of a group of people, especially your family, you are with them and protected and loved by them.', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34620, 'in the brain/looks department', 'in intelligence or beauty:', 'He''s somewhat lacking in the brain department.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34621, 'in the buff', 'naked', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34622, 'in the can', 'If a film is in the can, filming has finished and it is ready to be prepared for showing to the public.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34623, 'in the cards', 'likely to happen:', 'Marriage isn''t in the cards for me right now – I''m focused on my career.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34624, 'in the clear', 'not guilty of a crime, or not involved in doing something bad:', 'His lawyers say that Wilson is in the clear.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34625, 'in the club', 'pregnant', NULL, 'idiom', NULL, NULL, 'old-fashioned, slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34626, 'in the cold light of day', 'If you think about something in the cold light of day, you think about it clearly and calmly, without the emotions you had at the time it happened, and you often feel sorry or ashamed about it:', 'The next morning, in the cold light of day, Sarah realized what a complete idiot she had been.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34627, 'in the country of the blind, the one-eyed man is king', 'said about a difficult situation in which someone with only a few skills is in a better position and more successful than those people who have none', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34628, 'in the dark', 'not informed about things that might be useful to know:', 'Our boss tends to keep us in the dark most of the time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34629, 'in the dead of night/winter', 'in the middle of night/winter:', 'The fire broke out in the dead of night.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34630, 'in the depth(s) of somewhere', 'in the middle of somewhere, and a long distance from its edges:', 'a house in the depths of the forest', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34631, 'in the depth(s) of winter', 'in the middle of winter', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34632, 'in the depths of something', 'in the middle of a difficult or unpleasant time or situation:', 'At the time, America was in the depths of the Depression.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34633, 'in the depths of something', 'If you are in the depths of a negative feeling, you feel it very strongly:', 'He was in the depths of despair about losing his job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34634, 'in the doghouse', 'If you are in the doghouse, someone is annoyed with you and shows their disapproval:', 'I''m in the doghouse - I broke Sara''s favourite vase this morning.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34635, 'in the dumps', 'not successful:', 'The team has been in the dumps all season.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34636, 'in the end', 'after considering everything:', 'In the end, she chose to go to Oberlin College.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34637, 'in the event of something', 'if something should happen:', 'In the event of an actual emergency, you will be told what to do.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34638, 'in the face of something', 'despite having to deal with a difficult situation or problem:', 'She left home in the face of strong opposition from her parents.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34639, 'in the fast lane', 'in a way that is exciting and slightly dangerous:', 'He lived life in the fast lane when he was young.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34640, 'in the firing line', 'likely to be criticized, attacked, or got rid of:', 'He found himself in the firing line for his sexist remarks.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34641, 'in the first place', 'in the beginning:', 'We should never have agreed to let him borrow the money in the first place.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34642, 'in the first/second place', 'used to separate and emphasize reasons or opinions:', 'I don''t want to go yet - in the first place I''m not ready, and in the second place it''s raining.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34643, 'in the flesh', 'in real life, and not on TV, in a film, in a picture, etc.:', 'I''ve seen her perform on television, but never in the flesh.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34644, 'in the flower of someone''''s youth', 'the time when someone was young and in the best and most active period of life:', 'He died in the very flower of his youth.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34645, 'in the fullness of time', 'If you say something will happen in the fullness of time, you mean that it will happen if you wait long enough:', 'Everything will become clear in the fullness of time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34646, 'in the game', 'with a chance of being successful because you remain involved in something, and especially because you keep trying hard, even when there are problems:', 'They have to put blood, sweat, and tears into the task in order to stay in the game.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34647, 'in the hands of someone', 'controlled or owned by someone:', 'A large percentage of the nation''s wealth is in the hands of a very, very few people.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34648, 'in the heat of the moment', 'If you say or do something in the heat of the moment, you say or do it without thinking because you are very angry or excited:', 'He didn''t mean it - he said it in the heat of the moment.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34649, 'in the hole', 'owing money, rather than having extra money:', 'We’re still in the hole on our credit cards.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34650, 'in the hot seat', 'in a position where you are responsible for important or difficult things', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34651, 'in the lap of luxury', 'living in very comfortable conditions because you have a lot of money', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34652, 'in the lap of the gods', 'used to say that a situation that cannot be controlled and depends only on good luck:', 'The doctors have done everything possible for him, so his recovery now is in the lap of the gods.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34653, 'in the last/final analysis', 'something you say when you are talking about what is most important or true in a situation:', 'In the final analysis, the only people who will benefit are property owners.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34654, 'in the light of something', 'because of:', 'In the light of recent incidents, we are asking our customers to take particular care of their personal belongings.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34655, 'in the line of duty', 'Something that happens to you in the line of duty happens when you are doing your job:', 'This year alone eight police officers have been killed in the line of duty.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34656, 'in the long run', 'at a time that is far away in the future:', 'It seems a lot of effort but I''m sure it''s the best solution in the long run.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34657, 'in the making', 'If something was a period of time in the making, it took that amount of time to make:', 'The film was several years in the making.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34658, 'in the market for something', 'interested in buying something:', 'Thanks for the offer, but I’m not in the market for another car at the moment.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34659, 'in the middle of something', 'busy doing something:', 'When she called, I was in the middle of making dinner.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34660, 'in the mold of someone/something', 'sharing some important characteristics with someone or something:', 'Lewis was not an inventor in the mold of Edison.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34661, 'in the name of something', '(said or done) in order to help a particular thing succeed:', 'Much blood has been spilled in the name of religion.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34662, 'in the name of someone/something', 'representing someone or something:', 'In old movies the police shouted "Open up in the name of the law" before they broke the door down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34663, 'in the neighborhood of something', 'approximately:', 'We''re hoping to get somewhere in the neighborhood of $150,000 for our house.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34664, 'in the neighbourhood of something', 'approximately:', 'We''re hoping to get somewhere in the neighbourhood of £150,000 for our house.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34665, 'in the nick of time', 'at the last possible moment:', 'We got there just in the nick of time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34666, 'in the offing', 'going to happen soon:', 'With an election in the offing, the mayor is getting nervous.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34667, 'in the open', 'no longer secret:', 'Now that her feelings are out in the open, she says she feels relieved.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34668, 'in the palm of your hand', 'under your complete control:', 'The audience was fascinated by his performance – he had them in the palm of his hand.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34669, 'in the person of someone', 'in the form of someone:', 'The editorial board has an expert with a world-wide reputation in the person of Professor Jameson.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34670, 'in the pink', 'in very good health', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34671, 'in the pipeline', 'being planned:', 'The theatre company has several new productions in the pipeline for next season.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34672, 'in the process', 'If you are doing something, and you do something else in the process, the second thing happens as a result of doing the first thing:', 'I stood up to say hello and spilled my drink in the process.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34673, 'in the raw', 'naked:', 'They sunbathed in the raw.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34674, 'in the raw', 'in a plain and honest way, with nothing hidden:', 'The film really showed you prison life in the raw.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34675, 'in the red', 'spending more money than you earn:', 'The company has been in the red for the last three quarters.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34676, 'in the right place at the right time', 'in the best position or place to take advantage of an opportunity:', 'The key to success is to be in the right place at the right time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34677, 'in the running', 'having a chance of being successful, esp. in a competition or election:', 'She''s still in the running for Treasurer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34678, 'in the same boat', 'in the same difficult situation as someone else:', 'None of us has any money, so we’re all in the same boat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34679, 'in the same breath', 'If you say two things in the same breath, you say two things that are so different that if one is true, the other must be false:', 'You say he treats you badly but in the same breath you tell me how much you love him!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34680, 'in the same league (as someone/something)', 'having qualities or achievements that are similar to someone or something:', 'The new charity will be giving away $55 million a year, putting it in the same league as other well-known charities.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34681, 'in the shadow of someone', 'receiving little attention because someone else is better known or more skillful:', 'DeMarco plays a lawyer living in the shadow of a famous father.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34682, 'in the shape of something', 'in the form of something, or appearing as something:', 'Luckily, help arrived in the shape of a police officer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34683, 'in the short run', 'at a time that is near in the future:', 'It''s not a long term solution, but it will save money in the short run.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34684, 'in the strictest confidence', 'If you tell someone something in the strictest confidence, you expect them not to tell it to anyone else.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34685, 'in the teeth of something', 'If something happens or is done in the teeth of difficulties, the difficulties cause problems but do not stop it:', 'The road was built in the teeth of fierce opposition from the public.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34686, 'in the thick of something', 'in the most active or dangerous part of a particular situation or activity :', 'He was always right there, in the thick of it when the fighting started.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34687, 'in the tradition of someone/something', 'having characteristics similar to a particular person or thing:', 'His paintings are in the tradition of those of Bacon and Spencer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34688, 'in the twinkling of an eye', 'If something happens in the twinkling of an eye, it happens very quickly:', 'Microprocessors do the calculations in the twinkling of an eye.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34689, 'in the vicinity of', 'approximately:', 'The club is believed to have paid in the vicinity of €3 million for Domingo.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34690, 'in the wake of something', 'If something happens in the wake of something else, it happens after and often because of it:', 'Airport security was extra tight in the wake of yesterday''s bomb attacks.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34691, 'in the way', 'in a position that prevents something from happening or someone from moving:', 'Work often gets in the way of my social life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34692, 'in the weeds', 'with so many problems or so much work that you are finding it difficult to deal with something:', 'We''re down in the weeds here with customer service.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34693, 'in the weeds', 'concerned with small details, often when this prevents you from understanding what is important:', 'He''s one of those rare people who can get down in the weeds and work on the details, but still see the big picture.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34694, 'in the wilderness', 'If someone, such as a politician, is in the wilderness, they no longer have a position of authority, fame, or success and are not now in the news:', 'After five years in the political wilderness, she was recalled to be foreign minister.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34695, 'in the wind', 'If something is in the wind, people are talking about it and it may happen, but no one is sure:', 'Rumours of a takeover are in the wind.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34696, 'in the wind', 'If someone is in the wind, they are missing, especially after escaping:', 'The suspects are in the wind.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34697, 'in the works', 'in the process of being planned or done:', 'Changes to the system are already in the works.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34698, 'in the world', 'in any conditions; of all possible things:', 'What in the world are you doing in the closet?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34699, 'in the wrong', 'responsible for something bad:', 'We had a green light, so she was clearly in the wrong when she hit us.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34700, 'in the wrong place at the wrong time', 'in a situation where something bad happens to you because you are unlucky, not because you do anything wrong:', 'It wasn''t his fault. He was just in the wrong place at the wrong time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34701, 'in the zone', 'If you are in the zone, you are happy or excited because you are doing something very skilfully and easily.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34702, 'in theory', 'possibly:', 'They could, in theory, have been paid twice if someone hadn’t caught the error.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34703, 'in this day and age', 'at the present time:', 'You can''t afford to run businesses inefficiently in this day and age.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34704, 'in too deep', 'too involved in a difficult situation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34705, 'in touch (with someone)', 'seeing someone or communicating with someone regularly:', 'We kept in touch for a while after college.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34706, 'in touch (with something)', 'having recent knowledge of a subject:', 'I try to stay in touch with the modern music scene.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34707, 'in tow', 'If you go somewhere with a particular person in tow, they are with you:', 'She arrived at the party, with a tall, silver-haired man in tow.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34708, 'in triplicate', 'When a document is prepared or written in triplicate, two exact copies of it are made also:', 'The application has to be completed in triplicate, with the original being kept by the bank and the copies going to the customer and the tax office.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34709, 'in truth', 'actually:', 'We kept climbing but, in truth, we knew we could not reach the top of the mountain before sunset.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34710, 'in tune with someone/something', 'having a good understanding of someone or something:', 'He is more in tune with his players today, because he has asked them for their opinions.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34711, 'in turn', 'because of that:', 'Stress causes your body to release chemicals, which in turn boost blood pressure.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34712, 'in turn', 'one after the other, in order:', 'She spoke to each of the guests in turn.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34713, 'in two shakes (of a lamb''''s tail)', 'very soon:', 'I''ll be with you in two shakes.', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34714, 'in unison', 'together and at the same time:', 'The audience rose to its feet in unison, applauding and cheering.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34715, 'in use', 'being used:', 'Is the washing machine in use right now?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34716, 'in view of something', 'because of a particular thing, or considering a particular fact:', 'In view of what you''ve said, I think we should reconsider our proposed course of action.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34717, 'in words of one syllable', 'in simple language avoiding long, difficult, or specialized words:', 'Could you explain to me in words of one syllable how an electron microscope works?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34718, 'in writing', 'in the form of a document, printed or written on paper:', 'We need to have your offer in writing before we can respond to it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34719, 'in years', 'in a long period of time:', 'We haven’t seen Marie in years.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34720, 'in your backyard', 'in the area where you live, or in the area of interest or activity that you are involved in or responsible for:', 'How would you feel about them building a nuclear power station in your backyard?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34721, 'in your birthday suit', 'not wearing any clothes', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34722, 'in your bones', 'in a way that is felt strongly, usually based on feelings or instinct (= natural reactions) rather than information:', 'He knows in his bones that his best days are long gone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34723, 'in your dreams!', 'something you say to someone who has just told you about something they are hoping for, in order to show that you do not believe it will happen:', 'Dave, buy you a car? In your dreams!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34724, 'in your element', 'in a situation you know well and enjoy:', 'Gerard stood up to sing in front of his classmates, and you could see he was in his element.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34725, 'in your face', 'slang rudely annoying someone:', 'One of the managers is always in my face.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34726, 'in your heart of hearts', 'in your most secret and true thoughts:', 'I didn''t want to believe it, but in my heart of hearts I knew that it was true.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34727, 'in your mind''''s eye', 'in your imagination or memory:', 'In my mind''s eye, she is still a little girl of six, although she''s actually a grown woman.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34728, 'in your own right', 'If you have a position in your own right, you have earned it or got it by yourself and not because of anyone else:', 'She''s a millionaire in her own right.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34729, 'in your own words', 'If you say something in your own words, you speak without copying what someone else has said:', 'The court has heard accounts of that night''s events from several witnesses - now please tell us in your own words what you saw.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34730, 'in your salad days', 'during the period of time when you were a young person and had little experience:', 'I met her in my salad days.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34731, 'in your stocking(ed) feet', 'wearing only socks or stockings and not shoes:', 'Jerome stands 1 m 75 in his stocking feet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34732, 'in your tracks', 'in the exact place where you are standing:', 'He fell dead in his tracks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34733, 'in your/its prime', 'in the best, most successful, most productive stage:', 'The horse retired from racing while still in his prime.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34734, 'in/by fits and starts', 'If something happens in fits and starts, it often stops and then starts again:', 'Replies to the advertisement are arriving in fits and starts.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34735, 'in/out of keeping (with something)', 'suitable or not suitable for a particular situation:', 'In keeping with tradition, they always have turkey on Christmas Day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34736, 'in/out of the running', 'having/not having a reasonable chance of winning', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34737, 'in/through all the years', 'during the whole of a stated period of time:', 'I''ve never once seen her angry in all the years I''ve known her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34738, 'in/within spitting distance', 'If something is in or within spitting distance, it is very close:', 'The house is within spitting distance of the sea.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34739, 'inch by inch', 'in great detail and in many very small stages:', 'Detectives searched the area around the murder scene inch by inch.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34740, 'incline to/towards something', 'to think that a belief or opinion is probably correct:', 'I incline to the view that peace can be achieved.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34741, 'inform against/on someone', 'If you inform on/against someone, you give the police information, usually secretly, about that person, showing that he or she has done something wrong:', 'The terrorists said that anyone caught informing on them would be killed.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34742, 'infringe on/upon something', 'If something infringes on/upon someone''''s rights or freedom, it takes away some of their rights or limits their freedom:', 'These restrictions infringe upon basic human rights.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34743, 'inhere in something', 'to exist as a natural or basic part of something:', 'He believes that a power to alter things inheres in the human soul.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34744, 'ink sb/sth in', 'to decide when an action, meeting, etc. will happen, or when someone will do something:', 'The company has a 30 million pound investment inked in for next year.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34745, 'inquire after someone', 'to ask for information about someone, especially about their health, in order to be polite:', 'She inquired after his grandfather''s health.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34746, 'inquire into something', 'to try to discover the facts about something:', 'When the authorities inquired into his background, they found he had a criminal record.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34747, 'inquire within', 'written on a notice on a building, meaning that information can be found inside:', 'Saturday staff needed - Inquire within.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34748, 'inside out', 'with the inside part facing out:', 'She put her sweater on inside out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34749, 'inside out', 'If you know something inside out, you know it very well:', 'He''s the best person to tell you how to get there because he knows the city inside out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34750, 'insinuate yourself into something', 'to use clever, secret, and often unpleasant methods to gradually become part of something:', 'Over the years she insinuated herself into the great man''s life.', 'phrasal verb', NULL, NULL, 'formal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34751, 'insist on doing something', 'to keep doing something, even if it annoys other people, or people think it is not good for you:', 'I don''t know why you insist on talking about it.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34752, 'insure against something', 'to do something in order to prevent something unpleasant from happening or from affecting you:', 'We thought we''d insure against rain by putting a tent up where people could take shelter.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34753, 'interest someone in something', 'Someone might ask if they can interest you in something when that person is trying to persuade you to buy something or is offering you something:', 'Can I interest you in our new range of kitchen fittings, madam?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34754, 'interfere with something', 'to prevent something from working effectively or from developing successfully:', 'Even a low level of noise interferes with my concentration.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34755, 'interfere with something', 'If something interferes with radio or television signals, it stops you from getting good sound or pictures.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34756, 'interfere with someone', 'to touch a child in a sexual manner:', 'He was sent to prison for interfering with little boys.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34757, 'into the bargain', 'in addition to other facts previously mentioned:', 'He''s intelligent, funny, a loving husband, and an excellent cook into the bargain.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34758, 'into thin air', 'used to refer to someone or something disappearing suddenly and completely:', 'We couldn''t find the boy. He seemed to have disappeared into thin air.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34759, 'introduce someone to something', 'to help someone experience something for the first time:', 'When were you first introduced to sailing?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34760, 'inure someone to something', 'If you become inured to something unpleasant, you become familiar with it and able to accept and bear it:', 'After spending some time on the island they became inured to the hardships.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34761, 'invalid someone out', 'If you are invalided out of a job, especially a military job, you are forced to leave because of injury or illness:', 'She was invalided out of the service because of injuries she received in a fire.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34762, 'inveigh against someone/something', 'to strongly criticize something or someone:', 'There were politicians who inveighed against immigrants to get votes.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34763, 'invest in something', 'to buy something because you think it will be useful, even if you think it is expensive:', 'We''ve decided it''s time to invest in a new computer.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34764, 'invest someone with something', 'to give authority or power to someone:', 'Our government has invested the representative with all the necessary powers to resolve the dispute.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34765, 'invest someone/something with something', 'to make someone or something seem to have a particular characteristic:', 'In his poems everyday reality is invested with a sense of wonder and delight.', 'phrasal verb', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34766, 'invite someone in', 'to ask someone to come into your house:', 'The neighbours invited us in for coffee.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34767, 'invite someone over', 'to invite someone to come to your house:', 'Let''s invite some people over.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34768, 'iron something out', 'to remove problems or find solutions:', 'We''re still trying to iron out some problems with the computer system.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34769, 'is he/she for real?', 'used when you think someone is silly or very surprising', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34770, 'is it me, or...?', 'used to ask if anyone agrees with you about something :', 'Is it me or is it hot in here?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34771, 'is the Pope a Catholic?', 'used to say that the answer to a question you have just been asked is obviously ''''yes''''', NULL, 'idiom', NULL, NULL, 'saying, humorous, offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34772, 'is the game worth the candle?', 'said when you are not certain if it is really worth making a great effort to get something', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34773, 'isn''''t it/aren''''t they just?', 'used to strongly agree with what someone has said about someone or something:', '"This is very expensive." "Isn''t it just?"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34774, 'issue from something', 'If something issues from a place, it comes out of that place:', 'A terrible scream issued from the room.', 'phrasal verb', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34775, 'it all amounts/comes to the same thing', 'used to mean that any of several different possible actions will produce the same result:', 'It doesn''t matter whether you do it first or last - it all amounts to the same thing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34776, 'it beats me', 'said when you do not understand a situation or someone''''s behaviour:', 'It beats me how she got the job.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34777, 'it can''''t be helped', 'used to say that an unpleasant or painful situation, or an unwanted duty cannot be avoided and must be accepted:', 'I really didn''t want to go away this weekend but, oh well, it can''t be helped.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34778, 'it doesn''''t hurt/never hurts to do something', 'it is useful or helpful to do or have something:', 'It never hurts to check the flight departure time before you leave for the airport.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34779, 'it doesn''''t take a rocket scientist', 'used to say that you do not think that something is very difficult to do or to understand:', 'Drugs equals crime. It doesn''t take a rocket scientist to figure that one out.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34780, 'it doesn’t hurt to do something', 'it is an advantage to do or have something:', 'It doesn’t hurt to have money when you want to run for office.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34781, 'it doesn’t take a rocket scientist to do something', 'humorous it is easy to do or understand something:', 'It doesn''t take a rocket scientist to figure out that if you treat her well, she''ll be happier.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34782, 'it figures', 'used to say that you are not surprised by something unpleasant that has happened:', '"Dad, Sadie spilled her milk all over the floor." "It figures."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34783, 'it goes without saying', 'used to mean that something is obvious:', 'Of course, it goes without saying that you''ll be paid for the extra hours you work.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34784, 'it is what it is', 'used to say that a situation cannot be changed and must be accepted:', 'We''re all imperfect human beings in an imperfect world. It is what it is.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34785, 'it is/was nothing', 'used to tell someone not to worry about, or place special value on, what you are doing or have done:', '"You seem very upset." "No, no, it''s nothing - I''m OK."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34786, 'it isn''''t over until the fat lady sings', 'used for saying that it is still possible for a situation to change', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34787, 'it makes me (want to) puke', 'used to say that something makes you very upset or angry', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34788, 'it never rains but it pours', 'said when one bad thing happens, followed by a lot of other bad things that make a bad situation worse', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34789, 'it remains to be seen', 'it is not yet certain:', 'It remains to be seen who will win.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34790, 'it says a lot for someone/something', 'used to show how much of a particular quality someone or something has:', 'It says a lot for her determination that she practises her cello so often.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34791, 'it serves someone right', 'infmlsomeone deserves the punishment given:', 'People think this game is so important, and it would serve them right if it was rained out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34792, 'it stands to reason', 'said when something is obvious or clear from the facts:', 'If 20 percent of the earth''s population has 80 percent of its resources, then it stands to reason that 80 percent of the population has only 20 percent of the resources.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34793, 'it stands to reason (that)', 'something seems likely to be true:', 'It stands to reason that with all his experience, he would not make such a simple mistake.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34794, 'it takes a thief to catch a thief', 'used to mean that one dishonest person can guess what another dishonest person might do', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34795, 'it takes all sorts (to make a world)', 'said to emphasize that people have different characters, opinions, and abilities, and that you should accept this', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34796, 'it takes two to tango', 'said when you want to emphasize that both people involved in a difficult situation must accept the blame, or that an activity needs two people who are willing to take part for it to happen:', 'She may want to argue, but it takes two to tango and I won''t stoop to her level.', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34797, 'it will (all) come out in the wash', 'used to tell someone that problems will be solved in the end:', 'We''ve certainly had some problems but I think, in the end, it will all come out in the wash.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34798, 'it wouldn''''t hurt you to do something', 'something that you say when you think someone should do something because they do not often do it:', 'It wouldn''t hurt you to do the ironing for once.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34799, 'it''''ll (all) end in tears', 'something that you say that means something will end badly and the people involved will be upset:', 'She only met him in May and they were married by July. It''ll end in tears, you''ll see.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34800, 'it''''ll cost you', 'it will be very expensive:', 'It''ll cost you to have your roof repaired.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34801, 'it''''s a crying shame', 'something that you say when you think a situation is wrong:', 'It''s a crying shame that she''s paid so little for what she does.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34802, 'it''''s a date', 'used to say that a particular time is a good time to meet:', '"I can''t make it at seven o''clock. How about 9.30?" "Sure, it''s a date."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34803, 'it''''s a fair cop', 'something you say when someone has caught you doing something wrong and you agree that you were wrong', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34804, 'it''''s a funny old world', 'said when someone has told you something that is strange or surprising', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34805, 'it''''s a long story', 'something that you say when someone has asked you about something that has happened and you do not want to explain it to them because it would take too long:', '"So why was Carlo knocking on your door at midnight?" "It''s a long story."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34806, 'it''''s a pleasure', 'a polite way of replying to someone who has thanked you:', '"It was so kind of you to give us a lift." "Don''t mention it - it was a pleasure."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34807, 'it''''s a small world', 'said to show your surprise that people or events in different places are connected:', 'You know my old science teacher! Well, it''s a small world, isn''t it?', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34808, 'it''''s a wonder', 'it is surprising:', 'It''s a wonder (that) he ever reached Paris, because he set off with only £5 in his pocket.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34809, 'it''''s a wrap', 'a phrase used in film making to tell actors and crew that filming of a particular scene, film, etc. has finished', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34810, 'it''''s all Greek to me', 'a way of saying that you do not understand something that is said or written', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34811, 'it''''s an ill wind (that blows nobody any good)', 'said to show that even a very bad situation must have some good results', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34812, 'it''''s early days', 'said when you think it is too soon to make a judgment about the likely result of something because a lot might still happen or change:', 'Our progress has been fairly slow so far, but it''s early days.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34813, 'it''''s every man for himself', 'something that you say that means that everyone in a particular situation is trying to do what is best for themselves and no one is trying to help anyone else:', 'It might be a civilized place to shop at other times, but come the January sales, it''s every man for himself.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34814, 'it''''s just one of those things', 'said about an event or situation that you cannot explain, or do not like but cannot change', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34815, 'it''''s more than my job''''s worth', 'something that you say in order to tell someone that you cannot do what they want you to do because you would lose your job', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34816, 'it''''s no use (doing something)', 'the thing someone tries cannot be or was not successful:', 'People tried to stop her, but it was no use.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34817, 'it''''s not brain surgery', 'used to say that you do not think that something is very difficult to do or to understand:', 'Just keep calm and do it. It''s not brain surgery.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34818, 'it''''s not rocket science', 'used to say that you do not think that something is very difficult to do or to understand:', 'My coach always said, "Basketball is not rocket science. It''s about putting the ball in the basket."', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34819, 'it''''s now or never', 'said when you must do something immediately, especially because you will not get another chance', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34820, 'it''''s raining cats and dogs!', 'something that you say when it is raining heavily', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34821, 'it''''s safe to say (that)', 'used to say that you are confident about what you are going to say:', 'I think it''s safe to say that the crisis is now over.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34822, 'it''''s the least I can do', 'a polite answer to someone who thanks you, usually when you feel you should do more to help:', '"Thanks for cleaning up" "It''s the least I can do, seeing as I''m staying here rent-free."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34823, 'it''''s the same old story', 'said when talking about a bad situation that has happened many times before:', 'It''s the same old story - the rich get richer and the poor get poorer.', 'idiom', 'C1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34824, 'it''''s the thought that counts', 'used to say that good or kind intentions are the most important thing, even if what you do or give someone is not perfect:', 'Even when people do things for you and give you things that you don''t actually want, you must always remember that it''s the thought that counts.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34825, 'it''''s tough at the top', 'used to mean that people in important positions have a lot of advantages and get a lot of good things:', '"The CEO always flies first class." "It''s tough at the top, isn''t it?"', 'idiom', NULL, NULL, 'humorous, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34826, 'it''''s your own lookout', 'used to tell someone that they are responsible for their own problems:', 'It''s your own lookout if you''re not properly insured.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34827, 'it''''s/that''''s the story of my life', 'said when something bad happens to you that has happened to you many times before:', 'Honestly, it''s the story of my life - I meet a totally gorgeous guy and he''s leaving for Australia the next day!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34828, 'itch to do something', 'to want to do something very much and as soon as possible:', 'He was itching to hear the results.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34829, 'itching to do something', 'wanting to do something very much:', 'The kids are itching to go out and play.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34830, 'jack off', 'to masturbate', NULL, 'phrasal verb', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34831, 'jack something in', 'to stop doing something, often a job or something that you are not enjoying:', 'He''s jacked in his job.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34832, 'jack something up', 'to raise a heavy object such as a car off the ground with a jack', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34833, 'jack something up', 'to increase the price of something suddenly and by a large amount:', 'Once the tourists arrive, the restaurants jack up their prices.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34834, 'jack-of-all-trades, master of none', 'said about someone who is able to do many things, but is not an expert in any', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34835, 'jam on the brakes', 'to use the brakes of a road vehicle suddenly and forcefully:', 'A motorbike appeared from nowhere and I had to jam on the brakes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34836, 'jam tomorrow', 'something good that is promised but never happens:', 'As children we were always being promised jam tomorrow, if only we would be patient.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34837, 'jangle someone''''s nerves', 'to make someone feel annoyed or nervous:', 'The constant whine of the machinery jangled his nerves.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34838, 'jar on someone', 'If something, especially a noise, jars on you, it annoys you:', 'His superior manner jars on me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34839, 'jazz something up', 'to make something more attractive or interesting:', 'Jazz the dress up with some bright accessories.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34840, 'jerk off', '(of a man) to 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34841, 'jerk someone around', 'to intentionally cause difficulty for someone:', 'I don’t think she really likes Colten – she’s just jerking him around.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34842, 'jib at something', 'to be unwilling to do or continue with something:', '[ + -ing verb ] Although the tax is unpopular, the government has jibbed at abolishing it completely.', 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34843, 'jib at something', 'If a horse jibs at something, it stops suddenly in front of it and refuses to move forward.', NULL, 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34844, 'jibe with something', 'If one statement or opinion jibes with another, it is similar to it and matches it:', 'Her account of the accident jibes with mine.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34845, 'job done', 'something you say when someone has achieved something, especially when it seems easier or quicker than you expected:', 'I just changed the fuse in the plug and the lamp worked, job done.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34846, 'job sth out', 'to employ a person or organization to do particular work for you:', 'Several banks are bringing IT work back in house that would normally be jobbed out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34847, 'jobs for the boys', 'work that someone in an important position gives to their friends or relations', NULL, 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34848, 'jockey someone into something', 'to persuade someone to do what you want, often by deceiving them in a clever way:', '[ + -ing verb ] The bosses were eventually jockeyed into signing the union agreement.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34849, 'jog along', 'If something, such as your work, jogs along, it moves on at a slow but regular speed:', '"How''s your research going?" "Oh, it''s jogging along."', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34850, 'jog on', 'used to tell someone forcefully and rather rudely to go away:', 'He asked me for money but I told him to jog on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34851, 'jog someone''''s memory', 'to make someone remember something:', 'The police showed him a photo to try to jog his memory about what had happened on the night of the robbery.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34852, 'join battle', 'If armies join battle, they start to fight.', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34853, 'join duty', 'to return to work after a period of time away', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34854, 'join hands', 'If two or more people join hands, they hold each other''''s hands, especially in order to do something:', 'The teacher asked us to form a circle and join hands.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34855, 'join in (something)', 'to become involved in an activity with other people:', 'We only need one more player for this game - can you persuade your sister to join in?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34856, 'join the club!', 'said in answer to something that someone has said, meaning that you are in the same bad situation as they are:', '"I''ve got no money till the end of this week." "Join the club!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34857, 'join up', 'If you join up, you become a member of one of the armed forces:', '"Have you been in the army for a long time?" "I joined up as soon as I''d left school."', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34858, 'join up with sb/sth', 'to get together with another company, person, or group in order to do something together or form one company, group, etc.:', 'The design company is planning to join up with a shoe manufacturer and create a new range of footwear.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34859, 'join with sb/sth', 'to get together with another company, person, or group in order to do something together:', 'join with sth/sb in doing sth The department store has joined with other local stores in trying to prevent shoplifting.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34860, 'joker in the pack', 'the person or thing that could change the situation in an unexpected way', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34861, 'joking apart/aside', 'said when you want to start speaking seriously about something after making jokes and laughing about it:', 'Joking apart, will you be able to manage on your own?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34862, 'jolly good', 'used to express approval of something that someone has said or done, or to show that you have heard or understood what someone has said:', '"I''ve left all the papers you need on your desk." "Oh, jolly good."', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34863, 'jolly good show!', 'used to express admiration for what someone has said or done:', '"We won!" "Oh, jolly good show!"', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34864, 'jolly hockey sticks', 'used to describe a woman or girl of a high social class who is enthusiastic in a way that annoys most people', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34865, 'jolly something up', 'to make something brighter and more attractive:', 'I thought I''d jolly the room up with some colourful curtains.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34866, 'jostle for something', 'If people jostle for something, they compete with each other in order to get what they want:', 'Since the fall of the government, the two opposition parties have been jostling for position.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34867, 'jot something down', 'to write something quickly on a piece of paper so that you remember it:', 'I carry a notebook so that I can jot down any ideas.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34868, 'jump all over someone', 'to criticize someone suddenly and severely:', 'When I showed him my report card, Dad jumped all over me.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34869, 'jump at something', 'to accept something eagerly:', 'She jumped at the chance of a trip to Paris.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34870, 'jump down someone''''s throat', 'to react angrily to something that someone says or does:', 'I made the mildest of criticisms and he jumped down my throat.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34871, 'jump for joy', 'to be extremely happy:', '"So how did Robert take the news?" "He didn''t exactly jump for joy."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34872, 'jump in', 'to interrupt when someone else is speaking:', 'I wish you''d stop jumping in and finishing my sentences for me all the time.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34873, 'jump in at the deep end', 'If you jump or are thrown in at the deep end, you start doing something new and difficult without help or preparation.', NULL, 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34874, 'jump in with both feet', 'to become involved in a situation too quickly without thinking about it first:', 'That''s just like Julie - always jumping in with both feet before she knows the facts.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34875, 'jump into sth', 'to suddenly decide to do something, especially without thinking about it carefully:', 'Investors shouldn''t jump into moving their funds without carefully reviewing their financial situation.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34876, 'jump on someone', 'to criticize someone as soon as they have done something wrong or said something that you disagree with:', 'She jumps on her children instantly if they''re disobedient.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34877, 'jump on the bandwagon', 'to join an activity that has become very popular or to change your opinion to one that has become very popular so that you can share in its success:', 'After a couple of politicians won elections by promising to cut taxes, most of the others jumped on the bandwagon.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34878, 'jump out at someone', 'If something jumps out at you, you notice it immediately:', 'That''s a very effective advertisement - it really jumps out at you.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34879, 'jump the gun', 'to do something too soon, especially without thinking carefully about it:', 'They''ve only just met - isn''t it jumping the gun to be talking about marriage already?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34880, 'jump the queue', 'to move to the front of a line of people who are waiting for something, so that you are served or dealt with before them:', 'This pre-paid smart card allows you to jump the queue to 60 of the capital''s favourite attractions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34881, 'jump the queue', 'to be dealt with earlier than other people who are also waiting for something and who may have been waiting longer than you:', 'Under this plan the better-off will be able to jump the queue by paying for private health care.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34882, 'jump the shark', '(usually of television shows) to reach a point where something stops becoming more popular or starts to decrease in quality:', 'The show jumped the shark a few years ago.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34883, 'jump through hoops', 'to have to do a lot of things that seem difficult or unnecessary in order to achieve something:', 'We had to jump through hoops to get my Dad admitted to hospital.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34884, 'jump to conclusions', 'to guess the facts about a situation without having enough information:', 'Don''t jump to conclusions! Perhaps it was his daughter he was dancing with.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34885, 'jump to it', 'used to tell someone to do something quickly:', 'I told you to tidy this room - now jump to it!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34886, 'jump to someone''''s defence', 'to quickly defend someone:', 'Whenever anyone criticizes her husband, she immediately jumps to his defence.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34887, 'jump/climb/get on the bandwagon', 'to become involved in an activity that is successful so that you can get the advantages of it yourself:', 'The success of the product led many firms to try to jump on the bandwagon.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34888, 'jump/leap out of your skin', 'to be extremely surprised by something:', 'The loud noise made me jump out of my skin.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34889, 'just a minute/moment/second', 'used to ask someone to wait for a short period of time:', 'Just a second - I''ve nearly finished.', 'idiom', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34890, 'just a minute/moment/second', 'used to interrupt someone in order to ask them to explain something, to calm them, or to express disagreement:', 'Just a minute - can you tell me how to do that again?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34891, 'just a moment', 'wait a short period of time:', 'Just a minute – I''m almost done.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34892, 'just because I''''m paranoid doesn''''t mean they''''re not out to get me', 'said when you recognize that you generally worry too much about people trying to harm you, but believe that in this particular situation people really are trying to harm you', NULL, 'idiom', NULL, NULL, 'humorous, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34893, 'just gay enough', 'A heterosexual man who is just gay enough has some of the qualities typical of gay men that many women like, such as an interest in clothes or being able to talk about emotions.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34894, 'just in case', 'to protect against something bad that could happen:', 'I’ll take my umbrella too, just in case.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34895, 'just like that', 'suddenly and unexpectedly:', 'Their son went off and got married last week, just like that.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34896, 'just my luck!', 'something that you say when something bad happens to you:', 'They sold the last ticket five minutes before I got there - just my luck!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34897, 'just now', 'a very short time ago:', 'Who was that at the door just now?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34898, 'just the man/woman for the job', 'a man/woman who has all the skills for a particular piece of work:', 'We need someone who has experience in marketing and teaching, and I think Alex is just the woman for the job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34899, 'just the thing', 'exactly what is needed:', 'A week''s rest would be just the thing for her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34900, 'just the ticket', 'very suitable and exactly what is needed', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34901, 'just what the doctor ordered', 'exactly what is wanted or needed:', 'Thanks, a strong cup of coffee in the morning is just what the doctor ordered.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34902, 'keel over', 'to fall over suddenly:', 'He finished the bottle, stood up to leave, and keeled over.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34903, 'keel over', 'If a boat keels over, it turns upside down in the water:', 'The storm raged and they struggled to stop the boat from keeling over.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34904, 'keep to somewhere', 'to stay in one particular area:', 'Please keep to the footpaths.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34905, 'keep something to something', 'If you keep something to a particular number or amount, you make certain it does not become larger than that.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34906, 'keep something to yourself', 'to keep something secret:', 'I don''t want everyone to know, so if you could keep it to yourself I''d appreciate it.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34907, 'keep (yourself) to yourself', 'to not talk to other people very much:', 'He''s a very private person - he keeps (himself) to himself.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34908, 'keep to something', 'to do what you have promised or planned to do:', 'I think we should keep to our original plan.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34909, 'keep to something', 'If you keep to a particular subject, you only talk about that subject:', 'For heaven''s sake let''s keep to the point or we''ll never reach any decisions.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34910, 'keep (myself) to myself', 'to spend time alone, not talking to other people very much:', 'I don''t see friends very often. I prefer to keep myself to myself.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34911, 'keep (someone/something) away', 'to not go somewhere or near something, or to prevent someone from going somewhere or near something:', 'Keep away from the edge of the cliff.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34912, 'keep (someone/something) off something', 'to not go onto an area, or to stop someone or something going onto an area:', 'There was a notice saying "Keep off the grass".', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34913, 'keep something off (someone/something)', 'to stop something touching or harming someone or something:', 'Put a cloth over the salad to keep the flies off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34914, 'keep (someone) off something', 'to not eat, drink, or use something that can harm you, or to stop someone else from doing this:', 'The doctor told me to keep off fatty foods.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34915, 'keep off something', 'If you keep off a particular subject, you avoid talking about it.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34916, 'keep (someone/something) out', 'to not go in a place, or to stop someone or something from going into a place:', 'Building work in progress. Keep out!', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34917, 'keep (someone/something) out of something', 'to avoid becoming involved in something, or to stop someone or something becoming involved in something:', 'I prefer to keep out of arguments about money.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34918, 'keep (something/someone) back', 'to not go near something, or to prevent someone or something from going past a particular place:', 'Barriers were built to keep back the flood water.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34919, 'keep something back', 'to not use the whole amount of something so that there is a small amount remaining for later', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34920, 'keep something back', 'to not tell someone everything you know about a situation or an event that has happened:', 'I suspect she''s keeping something back.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34921, 'keep a civil tongue in your head', 'used to tell someone to stop being rude', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34922, 'keep a clean sheet', 'in football, to not allow the opposing team to score a goal:', 'Liverpool have kept a clean sheet in five of their last six home games.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34923, 'keep a cool head', 'to stay calm in a difficult situation:', 'I don''t know how you manage to keep such a cool head in such a hectic, stressful office!', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34924, 'keep a firm hand on something', 'to control something or someone carefully:', 'Susan keeps a firm hand on everything that goes on in the office.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34925, 'keep a low profile', 'to avoid attracting attention to yourself:', 'He''s been in a little trouble recently so he''s trying to keep a low profile.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34926, 'keep a straight face', 'to manage to stop yourself from smiling or laughing:', 'She tried to keep a straight face but, unable to contain herself, burst into laughter.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34927, 'keep a tight rein on someone/something', 'to have a lot of control over someone or something:', 'My father always kept us on a tight rein.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34928, 'keep a weather eye on something', 'to watch a particular situation closely to see what happens:', 'They are well accustomed to keeping a weather eye on currency movements.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34929, 'keep a weather eye open', 'to always be paying attention so that you notice if anything happens:', 'His bodyguard kept a weather eye open from across the room.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34930, 'keep a/the lid on something', 'to control the level of something in order to stop it increasing:', 'The administration has intervened to keep a lid on inflation.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34931, 'keep an eye out for something', 'to watch carefully for something:', 'Keep an eye out for spyware programs that install themselves on your computer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34932, 'keep at something', 'to continue to do or work on something:', 'I kept at it and finally finished at three this morning.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34933, 'keep body and soul together', 'to be able to pay for your food, clothing, and somewhere to live:', 'His wages are barely enough to keep body and soul together.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34934, 'keep count (of something)', 'to remember a total:', 'I’ve been keeping count of how many times he’s called this week.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34935, 'keep faith with something/someone', 'to continue to support something or someone, or to do what you promised to do in a particular thing:', 'Despite the continuing recession, the government has asked people to keep faith with its reforms.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34936, 'keep from doing something', 'to manage to prevent yourself from doing something:', 'I couldn''t keep from smiling when she told me what she''d done.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34937, 'keep in with someone', 'to continue to try to be friendly with someone, especially because they can help you:', 'I like to keep in with my ex-employer, you never know when you might need a reference.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34938, 'keep it down', 'to be quieter:', 'Hey you guys, keep it down in there – I’m on the phone!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34939, 'keep it up', 'used to encourage someone to continue doing something:', 'You''re doing very well everybody. Keep it up!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34940, 'keep on', 'to continue to talk in an annoying way about something:', 'Don''t keep on, I''ll sort it out in a minute.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34941, 'keep on doing something', 'to continue to do something, or to do something again and again:', 'She kept on asking me questions the whole time.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34942, 'keep on the right side of someone', 'to try to make certain that someone is pleased with you:', 'Paul kept on the right side of his teachers by working really hard.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34943, 'keep on trucking', 'to continue to do something that is ordinary and boring:', '"How''s work going?" "Oh, okay. I just keep on trucking."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34944, 'keep someone at arm''''s length', 'to not allow someone to become too friendly with you:', 'I always had the feeling she was keeping me at arm''s length.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34945, 'keep someone at bay', 'to prevent someone from moving closer:', 'He held the police at bay for several hours.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34946, 'keep something at bay', 'to control something and prevent it from causing you problems:', 'She fought to keep her unhappiness at bay.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34947, 'keep someone at it', 'to make someone continue to work hard:', 'We need to keep her at it if she''s going to pass the final exam.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34948, 'keep someone company', 'to stay with someone so the person is not alone:', 'I kept him company while he was waiting for the bus.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34949, 'keep someone guessing', 'to not tell someone what you are going to do next', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34950, 'keep someone in', 'to make a child stay inside as a punishment, or to make someone stay in hospital:', 'They kept her in overnight for observation.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34951, 'keep someone in the picture', 'to make sure someone knows all the facts about a changing situation:', 'I use the radio to keep me in the picture about what''s happening abroad.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34952, 'keep someone on the rails', 'to make sure someone continues to behave in a way that is generally acceptable, honest, and legal:', 'It can sometimes be hard trying to keep teenagers on the rails.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34953, 'keep something on the rails', 'to make sure something continues to be successful or effective:', 'It takes a lot out of you keeping a business on the rails.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34954, 'keep someone posted', 'to make sure someone knows what is happening, esp. in a situation that is quickly changing:', 'The doctors kept me posted about her condition.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34955, 'keep someone sweet', 'to try to keep someone satisfied and pleased with you so that you can continue to get what you want:', 'He made a few concessions to keep the shareholders sweet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34956, 'keep someone up', 'to prevent someone from going to bed or sleeping:', 'He keeps yawning - I hope we''re not keeping him up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34957, 'keep something up', 'to make something continue at its present level and not allow it to fall:', 'You must eat to keep your strength up.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34958, 'keep (something) up', 'to continue without stopping or changing, or to continue something without allowing it to stop or change:', 'Keep up the good work!', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34959, 'keep up', 'to be able to understand or deal with something that is happening or changing very fast:', 'I read the papers to keep up with what''s happening in the outside world.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34960, 'keep someone/something from something', 'to prevent someone or something from doing something:', '[ + -ing verb ] Try to keep the children from throwing food all over the floor.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34961, 'keep something from someone', 'to not tell someone about something:', 'He says it''s alright but I think he''s keeping something from me.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34962, 'keep something down', 'to be able to eat or drink something without vomiting:', 'On the day after her operation she couldn''t keep anything down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34963, 'keep something down', 'to control the size or number of something and prevent it from increasing:', 'We need to work hard to keep our prices down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34964, 'keep someone down', 'to prevent a person or group of people from having any power or freedom:', 'It''s all part of a conspiracy to keep women down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34965, 'keep something quiet', 'to say nothing about something:', 'She managed to keep the school’s problems quiet for a while.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34966, 'keep tabs on something/someone', 'to watch something or someone carefully:', 'I like to keep tabs on my bank account so that I don''t spend too much.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34967, 'keep the flag flying', 'to act or speak for the country or group that a flag represents', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34968, 'keep the lights on', 'to make sure that a business, system, etc. continues to operate, even if it does not make much progress:', 'Please don''t block those ads - they help keep the lights on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34969, 'keep the wolf from the door', 'to have just enough money to be able to eat and live:', 'As a student, he took an evening job to keep the wolf from the door.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34970, 'keep to yourself', 'to often avoid other people:', 'I was very shy and pretty much kept to myself in school.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34971, 'keep something to yourself', 'do not tell anyone about something:', 'The party’s a surprise, so keep it to yourself!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34972, 'keep track', 'to make certain that you know what is happening or has happened to someone or something:', 'My sister has had so many different jobs, it''s hard for me to keep track (of what she''s doing).', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34973, 'keep track (of someone/something)', 'to continue to be informed or know about someone or something:', 'My sister’s had so many jobs, I can’t keep track anymore.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34974, 'keep up (with someone/something)', 'to do whatever is necessary to stay level or equal with someone or something:', 'He started to walk faster and the children had to run to keep up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34975, 'keep up appearances', 'to pretend to be happier, less poor, etc. than you really are, because you do not want people to know how bad your situation is:', 'They were very unhappily married but kept up appearances for the sake of their children.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34976, 'keep up with the Joneses', 'to always want to own the same expensive objects and do the same things as your friends or neighbours, because you are worried about seeming less important socially than they are', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34977, 'keep your distance', 'to avoid going near someone or something, or to avoid getting too friendly with people:', 'I''ve tried being friendly but she keeps her distance.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34978, 'keep your eye in', 'to continue to be good at a sport or other activity by practising it:', 'I try to play regularly to keep my eye in.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34979, 'keep your eye on the ball', 'to give your attention to what you are doing at the time:', 'You have to keep your eye on the ball in business.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34980, 'keep your eyes open for someone/something', 'to watch carefully for someone or something, often while you are doing something else:', 'While you are checking the animals, keep your eyes open for any signs of disease .', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34981, 'keep your eyes peeled/skinned', 'to watch carefully for someone or something:', 'Keep your eyes peeled for Polly and Maisie.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34982, 'keep your fingers crossed', 'to hope strongly that something will happen:', 'We’re keeping our fingers crossed that he’ll be healthy again very soon.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34983, 'keep your hair on', 'said to tell someone to stop being so angry or upset:', 'Keep your hair on! Your car isn''t badly damaged!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34984, 'keep your hand in', 'to practise a skill often enough so that you do not lose the skill:', 'I do a bit of teaching now and then just to keep my hand in.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34985, 'keep your head', 'to stay calm despite great difficulties:', 'She kept her head under pressure and went on to win the race.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34986, 'keep your head above water', 'to just be able to manage, especially when you have financial difficulties:', 'The business is in trouble, but we are just about keeping our heads above water.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34987, 'keep your head down', 'to avoid trouble:', 'He''s in a bad mood today - I''m just keeping my head down.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34988, 'keep your mouth shut', 'to not talk about something:', 'I don''t know whether to tell him what I know or keep my mouth shut.', 'idiom', 'B2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34989, 'keep your nose clean', 'to avoid getting into trouble:', 'I''d only been out of prison three months, so I was trying to keep my nose clean.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34990, 'keep your nose out of something', 'to not become involved in other people''''s activities or relationships:', 'She can''t keep her nose out of other people''s business.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34991, 'keep your nose to the grindstone', 'to work very hard without resting:', 'After a year of keeping his nose to the grindstone, he finally got a vacation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34992, 'keep your options open', 'to wait before making a choice:', 'I haven’t signed a contract – I’m leaving my options open.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34993, 'keep your own counsel', 'to not say what your opinions are:', 'I''d love to know what Anna thinks, but she always keeps her own counsel.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34994, 'keep your powder dry', 'to wait before taking action, but be ready to take action if it is necessary:', 'I think some potential candidates are going to keep their powder dry and see how it''s playing out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34995, 'keep your shirt on', 'said to tell someone to stop being so angry or upset:', 'Keep your shirt on! Your car isn''t even scratched!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34996, 'keep your temper', 'not become angry:', 'It was hard to keep my temper with so many things going wrong.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34997, 'keep your/an eye on something/someone', 'to watch or take care of something or someone:', 'Will you keep your eye on my suitcase while I go to get the tickets?', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34998, 'keep your/an eye out for someone/something', 'to watch carefully for someone or something to appear:', 'Keep your eye out for signposts to Yosemite.', 'idiom', 'C1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (34999, 'keep/hold your cards close to your chest', 'to keep your intended actions secret:', 'You never quite know what Barry''s going to do next - he keeps his cards very close to his chest.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35000, 'keep/hold your end up', 'to continue to deal with difficulties bravely and successfully', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35001, 'keep/put your nose to the grindstone', 'to work very hard for a long time:', 'She kept her nose to the grindstone all year and got the exam results she wanted.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35002, 'key something in', 'to put information into a computer, phone, or other machine using a keyboard or touchscreen:', 'I keyed the number in, but nothing happened.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35003, 'kick (some) ass', 'to punish someone or to defeat someone with a lot of force:', 'We''re gonna go in there and kick ass.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35004, 'kick (some) ass', 'to do something extremely well:', 'It was her first attempt and she kicked ass!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35005, 'kick against something', 'to refuse to accept something and react strongly against it:', 'As a boy he always kicked against his father''s authority.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35006, 'kick against the pricks', 'to argue and fight against people in authority', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35007, 'kick around', 'If something is kicking around a place, it is somewhere in that place, not being used:', 'There must be a copy of it kicking around the office somewhere.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35008, 'kick something around', 'If you kick ideas around, you talk about them informally in a group:', 'We need to get everyone together and kick a few ideas around', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35009, 'kick back', 'to stop doing things and relax:', 'What good is life if a guy can’t kick back and watch a good movie?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35010, 'kick in', 'to start to have an effect or to happen:', 'It takes half an hour for the medication to kick in.', 'phrasal verb', 'C1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35011, 'kick in something', 'to give something, especially money or help:', 'Another plan would require employers to kick in $20 per worker to set up the fund.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35012, 'kick in the teeth', 'If you describe the way someone treats you as a kick in the teeth, you mean that that person treats you badly and unfairly, especially at a time when you need their support:', 'She was dismissed from her job, which was a real kick in the teeth after all the work she''d done.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35013, 'kick it', 'to relax somewhere, usually with other people, not doing anything in particular:', 'Most weekends I''ll just kick it with my friends.', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35014, 'kick off', 'If a game of football kicks off, it starts:', 'What time does the game kick off?', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35015, 'kick off', 'to begin:', 'Indonesia''s parliamentary election campaign kicked off at the weekend.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35016, 'kick off', 'to become full of action and excitement, sometimes including violence:', 'Chamonix''s bars and clubs - lively any night - really kick off at weekends.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35017, 'kick off', 'to start to get angry or complain in a noisy way:', 'The children started to kick off so I couldn''t stay.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35018, 'kick off', 'to die', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35019, 'kick (something) off', 'If you kick off a discussion or an activity, you start it:', 'I''d like to kick off the discussion with a few statistics.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35020, 'kick over the traces', 'to behave badly and show no respect for authority', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35021, 'kick sb''''s arse', 'to punish someone or to defeat someone with a lot of force:', 'If you hurt my brother, I''ll kick your arse.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35022, 'kick someone out', 'to force someone to leave a place or organization:', 'His wife kicked him out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35023, 'kick someone upstairs', 'to give someone a new job that seems more powerful but is really less powerful, usually in order to stop them causing trouble for you', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35024, 'kick something into the long grass', 'to delay dealing with something, especially because you want people to forget about it:', 'It is disgraceful that the Treasury had kicked the task force''s report into the long grass.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35025, 'kick something into touch', 'to decide not to do what you had planned to do:', 'Our plans to buy a new car have had to be kicked into touch now Kev''s lost his job.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35026, 'kick something off (with something)', 'to begin an event or period of time, esp. with an activity:', 'We like to kick off the summer with a barbecue.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35027, 'kick the bucket', 'to die', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35028, 'kick the can down the road', 'to avoid or delay dealing with a problem:', 'I don''t think we should kick the can down the road and let our grandkids solve that problem.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35029, 'kick the habit', 'to give up something harmful that you have done for a long time:', 'She used to be a heavy smoker but she kicked the habit last year.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35030, 'kick the tires', 'to try something or examine it carefully before you buy it:', 'Come and kick the tires on this latest version of the software.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35031, 'kick up', 'to become more active or noticeable:', 'As the storm moves into the desert, the wind and rain start to kick up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35032, 'kick up a fuss/row/stink', 'to show great anger about something, especially when this does not seem necessary:', 'He kicked up a tremendous fuss about having to wait.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35033, 'kick up your heels', 'to do things that you enjoy:', 'After final exams we kicked up our heels and had a really good party.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35034, 'kick your heels', 'to be forced to wait for a period of time', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35035, 'kick/hit someone when he/she is down', 'to criticize or take unfair advantage of someone when they are in a weak position:', 'It''s typical of the boss to kick someone when they''re down.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35036, 'kid around', 'to be silly or not serious:', 'Stop kidding around and listen to me!', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35037, 'kill it', 'to do something extremely well:', 'Chris kills it on drums.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35038, 'kill or cure', 'a way of solving a problem that will either fail completely or be very successful:', 'Having a baby can be kill or cure for a troubled marriage.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35039, 'kill someone with kindness', 'to be too kind to someone, harming that person because you are helping or giving them too much', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35040, 'kill something off', 'to destroy something completely, usually over a period of time:', 'The use of pesticides is killing off birds and fish.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35041, 'kill something stone-dead', 'to cause something to be completely unsuccessful or to stop completely:', 'One bad review can kill a film stone-dead.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35042, 'kill the fatted calf', 'to have a special celebration for someone who has been away for a long time', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35043, 'kill the goose that lays the golden egg', 'to destroy something that makes a lot of money for you', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35044, 'kill time, an hour, etc.', 'to do something that keeps you busy while you are waiting for something else to happen:', 'My friend was late, so I killed an hour window-shopping.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35045, 'kill two birds with one stone', 'to succeed in achieving two things in a single action:', 'I killed two birds with one stone and picked the kids up on the way to the supermarket.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35046, 'kind of', 'used when you are trying to explain or describe something, but you cannot be exact:', 'It was kind of strange to see him again.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35047, 'kiss ass', 'to be very nice to people in authority because you want them to help you', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35048, 'kiss my arse!', 'used to tell someone that you will not do what they want you to do', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35049, 'kiss my ass!', 'used to tell someone that you will not do what they want you to do', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35050, 'kiss of death', 'If you describe something as the kiss of death, you mean that it is certain to cause something else to fail:', 'Rain is the kiss of death for a barbecue.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35051, 'kiss someone''''s arse', 'to be very nice to someone in order to get an advantage', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35052, 'kiss something goodbye', 'to accept that you have lost something or that you will not be able to have something:', 'If France lose this game, they can kiss their chances of winning the cup goodbye.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35053, 'kiss something off', 'to accept that you have lost something or failed at something:', 'I guess we can kiss off the deal.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35054, 'kiss someone/something off', 'to make it clear that you do not want or need someone or something:', 'You''re not in a position to kiss off any job you''re offered.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35055, 'kit someone/something out', 'to supply someone or something with the clothes or equipment that are needed for a particular purpose:', 'They went shopping to get kitted out for the trip.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35056, 'knit your brow/brows', 'to frown (= move your eyebrows down and together) because you are thinking carefully, or because you are angry or worried:', 'He knitted his brow in concentration.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35057, 'knock ''''em dead!', 'used to tell someone to perform or play as well as possible', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35058, 'knock (some) sense into someone', 'to forcefully teach someone not to be silly:', 'A couple of years in the army will knock some sense into him.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35059, 'knock around', 'to spend time relaxing and doing very little:', 'I spent the weekend just knocking around the house.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35060, 'knock around', 'to spend a lot of time with someone:', 'I used to knock around with him at school.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35061, 'knock around (something)', 'to be in a place that is not exactly known or in various places especially over a long period of time:', 'I''m sure I''ve got a copy of "Lolita" knocking around somewhere.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35062, 'knock someone around', 'to behave violently towards someone and hit them:', 'Her husband used to knock her around.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35063, 'knock it off', 'used to tell someone to stop doing something that annoys you:', 'Oh, knock it off Alex, I''m really not in the mood for your jokes.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35064, 'knock off (something)', 'to stop working, usually at the end of the day:', 'I don''t knock off until six.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35065, 'knock something off (something)', 'to take a particular amount away from a price:', 'The manager knocked $5 off because it was damaged.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35066, 'knock something off', 'to steal something:', 'He has a stack of computer equipment he''s knocked off from various shops.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35067, 'knock something off', 'to produce something quickly and easily:', 'She can knock off (= write) a novel in a couple of weeks.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35068, 'knock someone off', 'to murder someone:', 'He hired a hitman to knock off a business rival.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35069, 'knock someone off', 'to have sex with someone', NULL, 'phrasal verb', NULL, NULL, 'offensive, old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35070, 'knock on wood', 'said in order to avoid bad luck, either when you mention good luck that you have had in the past or when you mention hopes you have for the future:', 'The deal will be agreed on Wednesday, knock on wood.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35071, 'knock sb/sth out of the park', 'to do something much better than someone else, or to be much better than someone or something else:', 'Hotel Ferrero knocks everyone out of the park with their breakfast.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35072, 'knock sth out of the park', 'to do something extremely well:', 'I feel like I can write anything for this actor, and she''ll knock it out of the park.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35073, 'knock someone back (something)', 'to cost someone a large amount of money:', 'I bet that computer knocked you back several hundred.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35074, 'knock back (something)', 'to quickly drink something, especially a lot of alcohol:', 'She was knocking back the champagne at Maria''s party.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35075, 'knock someone down', 'to hit someone with a vehicle and injure or kill them:', 'She was knocked down by a bus.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35076, 'knock someone/something down', 'to cause someone or something to fall to the ground by hitting him, her, or it', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35077, 'knock someone/something down', 'to reduce a price, or to persuade someone to reduce the price of something they are selling:', 'She wanted $200 but I knocked her down to $175.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35078, 'knock something down', 'to destroy a building or part of a building:', 'There are plans to knock the library down and replace it with a hotel complex.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35079, 'knock something down', 'to show that what someone has said is not true :', 'She easily knocked down every argument he put up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35080, 'knock someone off their pedestal', 'to show people that someone is not as perfect as they seem to be:', 'This recent scandal has really knocked the president off his pedestal.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35081, 'knock someone out', 'to hit someone so that they become unconscious:', 'His opponent knocked him out with one punch.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35082, 'knock someone out', 'If a drug or alcohol knocks you out, it makes you go to sleep:', 'The sleeping tablets knocked him out for 18 hours.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35083, 'knock someone out', 'to defeat a person or a team in a competition so that they can no longer take part in it:', 'The champion was unexpectedly knocked out (of the tournament) in the first round.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35084, 'knock someone out', 'to cause enjoyment or admiration in someone:', 'We were all really knocked out by the film.', 'phrasal verb', NULL, NULL, 'old-fashioned, slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35085, 'knock yourself out', 'to make yourself unconscious, usually by hitting your head:', 'She hit her head on the ceiling and knocked herself out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35086, 'knock yourself out', 'to make yourself ill with tiredness:', 'If you carry on working like this, you''ll knock yourself out.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35087, 'knock something out', 'to produce something quickly without spending time thinking about the details:', 'I''ve knocked out a first draft of the report that we can amend at a later date.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35088, 'knock something out', 'If something such as a piece of equipment is knocked out by something else, it stops working or is damaged or destroyed:', 'The surge in the power supply knocked out all the computers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35089, 'knock someone over', 'to hit someone with a vehicle and injure or kill them:', 'She got knocked over by a taxi as she ran for the bus.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35090, 'knock something over', 'to steal something', NULL, 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35091, 'knock someone sideways/for six', 'to shock or upset someone very much, or to make someone very ill:', 'That flu really knocked me sideways.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35092, 'knock someone''''s block off', 'If you say that you will knock someone''''s block off, you are threatening to hit them very hard, especially on the head:', 'I''ll knock his block off if he tries anything with me!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35093, 'knock something into a cocked hat', 'to be much better than something else:', 'a show that knocks all the others into a cocked hat', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35094, 'knock something on the head', 'to prevent something from happening, or to finally finish something:', 'It''s nearly done - another couple of hours should knock it on the head.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35095, 'knock something out of someone', 'If a quality is knocked out of someone, they lose that quality because the situation they are in does not allow it to exist:', 'Any creativity I had was soon knocked out of me at school.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35096, 'knock something together/up', 'to make something quickly and without much care:', 'I could knock together a quick lunch if you like.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35097, 'knock spots off something', 'to be much better than something or someone else:', 'It knocks spots off that restaurant in Cotswold Street.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35098, 'knock sth from sth', 'to make the value of something go down by a particular amount:', 'A warning of significant losses knocked 10p from the group''s shares.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35099, 'knock the bottom out of something', 'to damage something severely, especially by destroying its support:', 'The rise in mortgage rates really knocked the bottom out of the housing market.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35100, 'knock up', 'Players knock up before beginning a game of tennis or similar sport by hitting the ball to each other:', 'The players have a couple of minutes to knock up before the match starts.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35101, 'knock someone up', 'to wake someone up by knocking on the door of their house or bedroom:', 'I''m sorry to have to knock you up in the middle of the night.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35102, 'knock someone up', 'to make a woman pregnant:', 'You don''t want to get knocked up by some guy you hardly know.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35103, 'knock, knock!', 'a way of describing the sound made when you hit a door. It is sometimes used as the first line of a joke.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35104, 'knock/lick something/someone into shape', 'to take action to get something or someone into the good condition that you would like:', 'to knock the economy into shape
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35105, 'knock/take the stuffing out of someone/something', 'to make someone or something become very weak:', 'Her illness has really knocked the stuffing out of her.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35106, 'knock/throw someone for a loop', 'If something that happens knocks you for a loop, it upsets or confuses you because you do not expect it:', 'He knocked me for a loop when he said he was quitting his job.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35107, 'know a hawk from a handsaw', 'to understand important differences or facts relating to a subject:', 'The referee clearly doesn''t know a hawk from a handsaw.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35108, 'know all the answers', 'If someone knows all the answers, they think they know much more than other people.', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35109, 'know all there is to know about something', 'to know a lot about a subject or activity, or be very good at it', NULL, 'idiom', NULL, NULL, 'approving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35110, 'know best', 'to be the most suitable person to have responsibility and make important decisions:', 'When it comes to dealing with my own son, I think I know best.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35111, 'know better (than someone)', 'to know more than someone else because you have more experience and more skill:', 'They thought the painting was a fake, but Shackleton knew better.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35112, 'know better (than to do something)', 'to be wise or moral enough not to do something:', 'Sure, she''s only six, but she''s old enough to know better than to run off without us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35113, 'know full well', 'to know something without a doubt:', 'You know full well that you’re not supposed to take the car without asking me!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35114, 'know of someone/something', 'to have heard of someone or something and be able to give a small amount of information about him, her, or it:', 'Do you know of a good doctor?', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35115, 'know something back to front', 'to have very good and detailed knowledge of something:', 'She knows her part in the play back to front.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35116, 'know something from something', 'to know the difference between two things and therefore be able to recognize either, used especially to mean that you have a good knowledge and understanding of a particular subject:', 'Computer expert? He doesn''t know a mouse from a modem! (= He knows nothing about computers.)', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35117, 'know something inside out', 'to know everything about a subject:', 'He knows the system inside out.', 'idiom', 'C1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35118, 'know something like the back of your hand', 'to have very good and detailed knowledge of something:', 'I know this area like the back of my hand.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35119, 'know something like the back of your hand', 'to know a place very well:', 'She’ll give you the name of a place to stay – she knows the area like the back of her hand.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35120, 'know the score', 'to know all the important facts in a situation, especially the unpleasant ones:', 'You know the score - no payment till after the article is published.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35121, 'know what it is (like) to', 'to be familiar with how it feels to be or do something:', 'She knows what it''s like to go bankrupt - it happened to her 20 years ago.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35122, 'know what you are doing', 'to have the skills and knowledge to do something effectively:', 'You don''t need to tell me - I know what I''m doing!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35123, 'know what you are talking about', 'to understand a subject because of your experience:', 'He doesn''t know what he''s talking about - he''s never even been to Africa.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35124, 'know what''''s what', 'If you know what''''s what, you have a lot of experience and can judge people and situations well:', 'Linda''s been in the business for 30 years - she knows what''s what.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35125, 'know when you are well off', 'If you do not know when you are well off, you do not understand that your present situation is good compared with other people''''s or with what it might be like:', 'She''s always complaining about her car - she doesn''t know when she''s well off (= she''s lucky to have a car even if it''s bad)!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35126, 'know where you stand', 'to know what your opinion or situation is:', 'I know where I stand on this issue - I''m against the war.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35127, 'know which side your bread is buttered (on)', 'to know who to be nice to and what to do in order to get an advantage for yourself', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35128, 'know your own mind', 'to be certain about what you believe or want', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35129, 'know your place', 'to accept your position within society, an organization, your family, etc. and to not want to improve it:', 'I just get on with my job and do as I''m told - I know my place.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35130, 'know your stuff', 'to have good practical skills and knowledge in a particular activity or subject', NULL, 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35131, 'know your way around something', 'to be familiar with a place or organization and able to act effectively within it', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35132, 'know/see where someone is coming from', 'If you say to someone you know or see where they are coming from, you mean you understand why that person has a particular opinion, often although you do not have that opinion:', 'I would''ve taken the dog to the vet, but I could see where they were coming from.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35133, 'knuckle down', 'to start working or studying hard:', 'You''re going to have to really knuckle down (to your work) if you want to pass your final exams.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35134, 'knuckle under', 'to accept someone''''s power over you and do what they tell you to do', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35135, 'labor of love', 'a piece of hard work that you do because you enjoy it and not because you will receive money or praise for it, or because you need to do it:', 'He''s always working on his car - it''s a labor of love.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35136, 'labor the point', 'to try too hard to express an idea, feeling, or opinion, repeating it when this is not necessary:', 'Look, there''s no need to labor the point - I made a mistake - I admit it!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35137, 'labor under the delusion, illusion, misapprehension, etc.', 'to wrongly believe that something is true:', 'At the time I was still laboring under the delusion that the project might be a success.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35138, 'labour of love', 'a piece of hard work that you do because you enjoy it and not because you will receive money or praise for it, or because you need to do it:', 'He''s always working on his car - it''s a labour of love.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35139, 'labour the point', 'to try too hard to express an idea, feeling, or opinion, repeating it when this is not necessary:', 'Look, there''s no need to labour the point - I made a mistake - I admit it!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35140, 'labour under the delusion, illusion, misapprehension, etc.', 'to wrongly believe that something is true:', 'At the time I was still labouring under the delusion that the project might be a success.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35141, 'lace something up', 'to fasten shoes, boots, or a piece of clothing by tying the laces:', 'She can lace up her shoes and she''s only five!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35142, 'lack direction', 'to not know what you really want to do:', 'She seems to lack direction in her life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35143, 'ladle something out', 'to give money or goods in a (too) generous way to a lot of people:', 'In those days doctors ladled out antibiotics to patients.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35144, 'land of milk and honey', 'a country where living conditions are good and people have the opportunity to make a lot of money:', 'Many Mexicans regard the United States as a land of milk and honey.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35145, 'land on your feet', 'to be successful or lucky, especially after a period of not having success or luck:', 'Don''t worry - she always lands on her feet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35146, 'land someone in something', 'to cause someone to be in a difficult situation:', 'Revealing confidential information to a rival company could land you in serious trouble with your boss.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35147, 'land someone with something', 'If someone or something lands you with something, he, she, or it causes problems for you:', 'I hope you don''t mind me landing you with the kids at such short notice.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35148, 'land up', 'to finally be in a particular place, state, or situation, especially without having planned it:', 'When we accepted that ride in Paris, we never expected to land up in Athens.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35149, 'lap something up', 'to enjoy something very much:', 'We walked around the city, lapping up the atmosphere.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35150, 'lapse into something', 'to start speaking or behaving in a less active or acceptable way:', 'No one could think of anything more to say, and the meeting lapsed into silence.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35151, 'lapse into something', 'to gradually get into a worse state or condition:', 'He lapsed into a coma and died four days later.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35152, 'lard something with something', 'If speech or a piece of writing is larded with a particular type of language, it has a lot of that type of language:', 'Her speech was larded with literary quotations.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35153, 'large/small-scale', 'A large/small-scale event or activity is large/small in size:', 'a large-scale investigation', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35154, 'larger than life', 'If someone is larger than life, that person attracts a lot of attention because they are more exciting or interesting than most people:', 'Most characters in his movies are somewhat larger than life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35155, 'lark around', 'to behave in a silly way because you think it is funny:', 'I was woken up by a couple of drunks larking around in the street.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35156, 'lash out (something)', 'to spend a large amount of money in a way that is unnecessary or that wastes it:', 'He lashed out £5,000 on his daughter''s wedding.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35157, 'lash out', 'to suddenly attack someone or something physically or criticize him, her, or it in an angry way:', 'I was only teasing him and suddenly he lashed out (at me) and hit me in the face.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35158, 'last but not least', 'importantly, despite being mentioned after everyone else:', 'I would like to thank my publisher, my editor, and, last but not least, my husband.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35159, 'last out', 'to manage to stay alive:', 'How long can they last out without food?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35160, 'last resort', 'the only choice that remains after all others have been tried:', 'As a last resort, we could ask your mother to help.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35161, 'latch on', 'to begin to understand something:', 'It took me ages to latch on to what she was talking about.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35162, 'latch onto something', 'to become connected to something:', 'The antibodies work by latching onto proteins on the surfaces of the viruses and bacteria.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35163, 'latch onto something', 'to become interested in an idea, story, or activity, and to start to use it:', 'Unfortunately the press have already latched onto the story.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35164, 'latch onto someone', 'to stay close to someone or spend a lot of time with someone, usually when they do not want you near:', 'She latched onto me as soon as she arrived, and I had to spend the rest of the evening talking to her.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35165, 'late in the day', 'too late to be useful:', 'It''s too late in the day to start studying - your final exams are next week.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35166, 'laugh at someone/something', 'to show that you think someone or something is stupid:', 'I can''t go into work looking like this - everyone will laugh at me.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35167, 'laugh at someone/something', 'to treat someone or something as if he, she, or it is not important or does not deserve serious attention:', 'If you say that, people will just laugh at you.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35168, 'laugh in someone''''s face', 'to make it obvious to someone that you do not respect them:', 'They''d laugh in your face if you suggested me for the post.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35169, 'laugh like a drain', 'to laugh a lot, very loudly', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35170, 'laugh out of the other side of your mouth', 'used to tell someone that, despite being pleased now, they will not be pleased later when things do not happen as expected or planned:', 'She''s pleased with her promotion but she''ll laugh out of the other side of her mouth when she sees the extra work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35171, 'laugh something off', 'to make yourself laugh about something unpleasant in order to make it seem less important or serious:', 'She tried to laugh off their remarks, but I could see she was hurt.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35172, 'laugh up your sleeve', 'to secretly find something funny:', 'They''re very polite in your presence, but you get the feeling they''re laughing up their sleeves.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35173, 'laugh your head off', 'to laugh a lot, loudly:', 'You laughed your head off when I fell!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35174, 'laugh, shout, scream, etc. your head off', 'to laugh, shout, scream, etc. very noisily and for a long time:', 'There I was lying face down on the pavement and you two were laughing your heads off!', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35175, 'laughter is the best medicine', 'said to mean that trying to be happy is a good way to stop worrying', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35176, 'launch into something', 'to start saying something or criticizing something with a lot of energy or anger:', 'He launched into a verbal attack on her handling of the finances.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35177, 'lavish something on someone/something', 'to give someone a lot, or too much, of something such as money, presents, or attention:', 'She lavishes money on her grandchildren.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35178, 'lawyer up', 'to employ a lawyer to help you when you are in a situation that may involve you being charged with (= officially accused of) a crime:', 'He hasn''t even lawyered up, and thinks he can represent himself in court and take custody of the kids.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35179, 'lay a finger on someone', 'to harm someone even slightly:', 'Don''t you dare lay a finger on me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35180, 'lay a hand on someone', 'to harm someone:', 'I never laid a hand on her!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35181, 'lay bare something', 'to make something known:', 'It''s been promoted as the biography that lays bare the truth behind the legend.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35182, 'lay down the law', 'to forcefully make known what you think should happen:', 'She can''t just come into this office and start laying down the law.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35183, 'lay down your life', 'to die:', 'I hope you will never be asked to lay down your lives for your principles.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35184, 'lay down your life for something', 'to die for something you believe in strongly:', 'Today we remember those who laid down their lives for their country.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35185, 'lay into someone', 'to attack someone physically, or to criticize someone in an angry way:', 'In the middle of the meeting she suddenly laid into him for no apparent reason.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35186, 'lay it on a bit thick', 'to praise someone too much:', 'She went on and on about how she admired his work - laid it on a bit thick, if you ask me.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35187, 'lay out (sth) for/on sth', 'to spend money, especially a large amount:', 'It''s not every day you lay out so much for a new computer system.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35188, 'lay someone low', 'to cause someone to be unable to do what they usually do:', 'A kidney infection laid her low for a couple of months.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35189, 'lay someone off', 'to stop employing someone, usually because there is no work for them to do:', 'Because of falling orders, the company has been forced to lay off several hundred workers.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35190, 'lay off (something/someone)', 'to stop using or doing something:', 'You''d better lay off alcohol for a while.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35191, 'lay something off', 'in football , to kick the ball gently into a space so that another player from your team can run forward into the space, then move forward with the ball or shoot towards the goal without slowing down or stopping:', 'Quinn laid off the ball for Kinsella to score.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35192, 'lay someone open', 'to put someone in a position where there is risk or danger, esp. of criticism:', 'The Senator''s remarks were unkind and laid him open to criticism.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35193, 'lay someone to rest', 'to bury a dead person:', 'She was laid to rest next to her husband.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35194, 'lay something to rest', 'to end a worry or fear:', 'I hope what he said has laid your fears to rest.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35195, 'lay someone up', 'to force someone to stay in bed:', 'She''s been laid up with the flu for over a week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35196, 'lay something (to) waste', 'to completely destroy something:', 'The bomb laid the city centre to waste.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35197, 'lay something aside', 'to stop doing or thinking about something, usually for a short period of time:', 'He''s temporarily laid aside some quite interesting projects to write the script.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35198, 'lay something aside', 'to keep something, usually money, for use in the future:', 'She''s trying to lay something aside (= save some money) for her retirement.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35199, 'lay something at someone''''s door', 'to blame someone for something:', 'Blame for the accident has been laid at the government''s door.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35200, 'lay something down', 'to store wine for drinking in the future', NULL, 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35201, 'lay something down', 'If you lay down your weapons, you stop fighting:', 'They laid down their weapons and surrendered.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35202, 'lay something down', 'to officially establish a rule, or to officially say how something should be done:', 'This is in line with the policy laid down by the management.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35203, 'lay something in', 'to get a supply of something because you will probably need it in the future:', 'We''d better lay in plenty of food in case we''re cut off when it snows.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35204, 'lay something on', 'to provide something for a group of people:', 'They lay on free entertainment at the club every day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35205, 'lay something on', 'to tell someone something they did not know:', 'I hate to be the one to lay this on you, but your girlfriend has just left with another guy.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35206, 'lay something on the line', 'to risk harm to something:', 'I''d be laying my career/life on the line by giving you that information.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35207, 'lay something on the line', 'to say very clearly that something is the case:', 'You''re just going to have to lay it on the line and tell her that her work''s not good enough.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35208, 'lay something out', 'to arrange something on a flat surface:', 'Most of Manhattan is laid out in/on a grid pattern.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35209, 'lay something out', 'to spend money, especially a large amount:', 'It''s not every day you lay out $500 on a dress.', 'phrasal verb', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35210, 'lay something out', 'to explain something clearly, usually in writing:', 'The code of practice lays out very clearly what the duties of the registrar are.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35211, 'lay someone out', 'to prepare a dead person''''s body to be buried', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35212, 'lay someone out', 'to hit someone so hard that they fall down and become unconscious:', 'Harrison was laid out for several minutes by a blow to the head.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35213, 'lay the basis/foundations for something', 'to prepare for or start an activity or task:', 'The initial negotiations are seen as laying the basis for more detailed talks.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35214, 'lay the foundation(s) of/for', 'to produce the basic ideas or structures from which something much larger develops:', 'The two leaders have laid the foundations of a new era in cooperation between their countries.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35215, 'lay the ghost of something (to rest)', 'to finally stop being worried or upset about something that has worried or upset you for a long time:', 'With one stunning performance, he has laid to rest the ghost of all his defeats last season.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35216, 'lay up trouble for yourself', 'to do something that will cause you trouble in the future:', 'You''re laying up trouble for yourself if you ignore health problems now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35217, 'lay your cards on the table', 'to be honest and not hide what you are thinking or doing:', 'I''m going to lay my cards on the table here, and say that I don''t know what to do.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35218, 'lay yourself open to attack, criticism, ridicule, etc.', 'to make it easy for people to attack you, etc.:', 'She lays herself open to criticism with such unashamedly extreme views.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35219, 'lay yourself open to ridicule', 'to make it easy for people to laugh unkindly at you:', 'You lay yourself open to ridicule wearing clothes like that.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35220, 'lead off', 'to begin to speak, usually as the first person to speak:', 'I want to lead off by thanking everyone for coming.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35221, 'lead someone a (merry) dance', 'to cause someone a lot of trouble, especially by getting them to do a lot of things that are not necessary', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35222, 'lead someone by the nose', 'to control someone and make them do exactly what you want', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35223, 'lead someone on', 'to persuade someone to believe something that is untrue:', 'All that time she''d been leading him on (= pretending she liked him), but she was only interested in his money.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35224, 'lead someone up the garden path', 'to deceive someone:', 'It seems as if we''ve been led up the garden path about the position of our hotel - it''s miles from the beach!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35225, 'lead the field/pack/world', 'to be better than all other people or things:', 'Their scientists lead the world in nutrition research.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35226, 'lead the way', 'to be the best:', 'The company leads the way in developing new software.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35227, 'lead the way (somewhere)', 'to go first to show someone how to go somewhere:', 'We all walked down toward the beach with the kids leading the way.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35228, 'lead to something', 'If an action or event leads to something, it causes that thing to happen or exist:', 'Reducing speed limits should lead to fewer deaths on the roads.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35229, 'lead up to something', 'If a period of time or series of events leads up to an event or activity, it happens until that event or activity begins:', 'The pilot had no recollection of the events leading up to the crash.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35230, 'lead up to something', 'to prepare to talk about something by gradually mentioning the subject you want to talk about:', 'He started telling me about a wonderful new restaurant he''d been to and I wondered what he was leading up to.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35231, 'lead with something', 'to put a particular story first or in the most important position in a news report or newspaper:', 'The Times leads with the coming mayoral elections.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35232, 'lead/live the life of Riley', 'to live an easy and comfortable life, without any need to work hard', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35233, 'leaf through something', 'to quickly turn the pages of a book or a magazine, reading only a little of it:', 'The waiting room was full of people leafing through magazines.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35234, 'leak like a sieve', 'to leak a lot', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35235, 'lean (something) against/on something', 'to sit or stand with part of your body touching something as a support:', 'He leaned against the wall.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35236, 'lean something against/on something', 'to put something against a wall or other surface so that it is supported:', 'She leaned the brush against the wall.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35237, 'lean and hungry', 'showing a very strong and determined wish to get something:', 'He''s got that lean and hungry look.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35238, 'lean on someone/something', 'to use someone or something to help you, especially in a difficult situation:', 'He''s always had his big brother to lean on.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35239, 'lean on someone', 'to try to make someone do what you want by threatening or persuading them:', 'We may have to lean on them a little if we want our money.', 'phrasal verb', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35240, 'lean toward sth', 'to be interested in something and be likely to do a particular activity:', 'He said he was leaning toward entering the race for governor.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35241, 'lean towards sth', 'to be interested in something and be likely to do a particular activity:', 'She''s not sure what she wants to do, but she''s leaning towards medicine.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35242, 'leap at something', 'to eagerly accept the chance to do or have something:', 'When I offered her the job, she leapt at it.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35243, 'leap out at someone', 'If something leaps out at you, you notice it immediately:', 'As I turned the page his picture leapt out at me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35244, 'learn a/your lesson', 'to suffer a bad experience and know not to do it again:', 'I got horribly drunk once at college and that was enough - I learned my lesson.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35245, 'learn something by rote', 'to learn something in order to be able to repeat it from memory, rather than in order to understand it:', 'She learned the equations by rote.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35246, 'learn something the hard way', 'to discover what you need to know through experience or by making mistakes:', 'He doesn’t want to take my advice, so I guess he''ll have to learn the hard way.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35247, 'learn to live with something', 'to accept a new but unpleasant situation that you cannot change:', 'It''s hard not having him around but I''ve learned to live with it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35248, 'learn/know the ropes', 'to learn/know how to do a job or activity', NULL, 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35249, 'lease sth back (to sb)', 'to sell property or an asset, but continue to use it by paying rent to the new owner:', 'The company may try to raise cash by selling and leasing back its buildings in London and Hong Kong.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35250, 'lease sth back (to sb)', 'to buy property or an asset, and allow the seller to continue to use it by paying you rent:', 'The fund aims to buy the ground''s freehold and lease it back to the club for a pound a year.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35251, 'least of all', 'especially not:', 'No one believed her, least of all me .', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35252, 'least said soonest mended', 'used to say that a bad situation can be quickly forgotten if people stop talking about it', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35253, 'leave a bad taste in someone''''s mouth', 'If an experience leaves a bad taste in your mouth, you have an unpleasant memory of it:', 'I think we all felt he''d been treated very unfairly and it left a bad taste in our mouths.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35254, 'leave a lot to be desired', 'to be much worse than you would like:', 'Apparently, Meg''s cooking leaves a lot to be desired.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35255, 'leave behind sth; leave sth behind', 'to cause a situation to exist, especially a bad one, after you have gone:', 'The army left a trail of destruction behind them.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35256, 'leave behind sth; leave sth behind', 'to be more succesful than someone you are competing with:', 'Three years later, the company had left all its close rivals far behind.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35257, 'leave go/hold of something', 'to stop holding on to something:', 'Leave go of my arm!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35258, 'leave it at that', 'to agree that there has been enough discussion, study, etc. and that it is time to stop:', 'Let''s leave it at that for today and meet again tomorrow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35259, 'leave it out!', 'stop doing or saying that:', 'Hey, leave it out! That hurt!', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35260, 'leave it out!', 'I do not believe you:', '"I tell you, he was driving a sports car." "Leave it out!"', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35261, 'leave no stone unturned', 'to do everything you can to achieve a good result, especially when looking for something:', 'He left no stone unturned in his search for his natural mother.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35262, 'leave someone be', 'to not worry someone, or to allow someone to continue what they are doing:', 'She''s only playing - leave her be.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35263, 'leave someone cold', 'to not make you feel interested or excited:', 'I''m afraid opera leaves me cold.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35264, 'leave someone hanging', 'to keep someone waiting for your decision or answer:', 'I was left hanging, not knowing whether I''d got the job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35265, 'leave someone high and dry', 'to do something that is not at all convenient for someone and puts them in a very difficult situation:', 'They pulled out of the deal at the last minute leaving us high and dry.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35266, 'leave someone in the lurch', 'to leave someone at a time when they need you to stay and help', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35267, 'leave someone out in the cold', 'to not allow someone to become part of a group or an activity', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35268, 'leave someone standing', 'to be much better than other people or things of the same type:', 'Her voice is excellent - it leaves the others standing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35269, 'leave someone to their own devices', 'to allow someone to make their own decisions about what to do:', 'He seemed to be a responsible person, so I left him to his own devices.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35270, 'leave someone/something alone', 'to not annoy, change, or touch someone or something:', 'The Federal Reserve is leaving interest rates alone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35271, 'leave someone/something in the dust', 'to easily defeat or be much better than someone or something:', 'She could leave every other runner in the dust.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35272, 'leave someone/something in the dust', 'to leave someone alone without helping or caring for them:', 'He left another woman in the dust and he''ll do the same to you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35273, 'leave someone/something out', 'to not include someone or something:', 'You can leave the butter out of this recipe if you''re on a low-fat diet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35274, 'leave something aside', 'to not discuss one subject so that you can discuss a different subject:', 'Leaving aside the question of cost, how many people do we need on the job?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35275, 'leave something at the door', 'to intentionally not allow something to influence you or to be expressed in a particular situation:', 'His reports were all reviewed by a committee; he had to leave his ego at the door.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35276, 'leave something for/to someone', 'to give someone responsibility for dealing with something:', 'I''ve left the paperwork for you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35277, 'leave something in your wake', 'to go somewhere new, leaving problems, confusion, etc. behind you, that you have caused:', 'Soldiers rampaged through the town, leaving chaos in their wake.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35278, 'leave something/someone behind', 'to leave a place without taking someone or something with you:', 'We left in a hurry and I must have left my keys behind.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35279, 'leave something behind', 'to cause a situation to exist after you have left a place:', 'The army left a trail of destruction behind it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35280, 'leave something/someone off something', 'to not include something or someone on a list:', 'He left three people off the list by mistake.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35281, 'leave off (something/doing something)', 'to stop, or to stop doing something:', 'This novel begins where the other one leaves off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35282, 'leave off!', 'used to tell someone to stop being annoying:', 'Hey, leave off! I hate people touching my hair.', 'phrasal verb', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35283, 'leave the field open for someone', 'to stop competing with someone, making it possible for them to succeed:', 'John decided not to apply for the job, which left the field open for Emma.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35284, 'leave well alone', 'to allow something to stay as it is because doing more might make things worse:', 'It''s going to get in a muddle if you carry on. I should just leave well alone if I were you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35285, 'leave well enough alone', 'to allow something to stay as it is because doing more might make things worse:', 'I could rewrite it, but I decided to leave well enough alone.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35286, 'leave your mark', 'to have an effect that changes someone or something:', 'The heart attack left its mark on him, and he was never quite the same after it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35287, 'leave your/its mark on someone/something', 'to have an effect that changes someone or something, usually in a bad way:', 'The experience had left its mark on her.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35288, 'leave, go off, etc. with your tail between your legs', 'to leave, feeling ashamed and embarrassed because you have failed or made a mistake:', 'The losing team went off with their tails between their legs.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35289, 'lech after someone', 'to show too much sexual interest in someone:', 'He''s always leching after younger women.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35290, 'leg before wicket', 'in the game of cricket, the situation in which your time as the person trying to hit the ball is ended because the ball has hit your leg when it should not have', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35291, 'lend an ear', 'to listen to someone with sympathy:', 'Claire''s always one to lend a sympathetic ear if you have problems.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35292, 'lend itself to something', 'fmlto be good for a particular use:', 'The book really lends itself to being turned into a film.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35293, 'lend your name to something', 'to give something your support:', 'Some of the world''s top dancers have lent their names to the project.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35294, 'less and less', 'gradually less or smaller:', 'I seem to see her less and less.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35295, 'let alone do something', 'and to an even greater degree do something:', 'Brian would never even read a newspaper, let alone a book.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35296, 'let someone/something alone', 'to not annoy or interrupt someone:', 'Just let her alone – she’s not bothering you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35297, 'let go', 'to stop holding something:', 'Hold on tight and don''t let go!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35298, 'let go', 'to stop thinking about or being angry about the past or something that happened in the past:', 'She finds it hard to let go of a grudge.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35299, 'let someone go', 'to allow someone to be free:', 'He pleaded with them to let him go.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35300, 'let someone go', 'to make someone leave their job:', 'The firm hired the staff to sell the stocks, then let most of them go only a few months after the crash.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35301, 'let yourself go', 'to allow yourself to become less attractive or healthy:', 'It''s easy to let yourself go when you''ve got small kids.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35302, 'let yourself go', 'to relax completely and enjoy yourself:', 'It''s a party - let yourself go!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35303, 'let something go', 'to stop taking care of something such as a house or garden:', 'The house was beautiful, but the new owners have just let it go.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35304, 'let go (of something/someone)', 'to stop holding something or someone:', 'Brandon let go of her hand and ran across the street.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35305, 'let it all hang out', 'to behave freely without being shy or feeling worried about what other people will think of you', NULL, 'idiom', NULL, NULL, 'old-fashioned, slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35306, 'let it be known', 'to make certain that people know something:', 'I let it be known that I was not happy about the decision that had been made.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35307, 'let it lie', 'to take no action about something:', 'Instead of going to the police they let things lie for a couple of months.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35308, 'let me see/let''''s see', 'used when you want to think for a moment about something:', '"Is there a shop that sells sports clothes?" "Let me see - I think there''s one near here."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35309, 'let nature take its course', 'to allow someone or something to live or die naturally:', 'He could be kept alive artificially, but I think it would be kinder to let nature take its course.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35310, 'let off steam', 'to do or say something that helps you to get rid of strong feelings or energy:', 'She jogs after work to let off steam.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35311, 'let on', 'to tell other people about something that you know, especially when it is a secret:', 'I suspect he knows more than he''s letting on.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35312, 'let rip/fly', 'to behave in an angry and emotional way:', 'She let rip about the state of the kitchen.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35313, 'let sleeping dogs lie', 'said to warn someone that they should not talk about a bad situation that most people have forgotten about', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35314, 'let someone be', 'to stop criticizing or annoying someone:', 'Just let her alone – she’s not bothering you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35315, 'let someone down', 'to disappoint someone by failing to do what you agreed to do or were expected to do:', 'You will be there tomorrow - you won''t let me down, will you?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35316, 'let something down', 'If you let down a piece of clothing, you make it longer:', 'My trousers shrank in the wash so I let them down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35317, 'let something down', 'If you let down something filled with air, you cause the air to go out of it:', 'Someone let my tyres down while I was at the gym.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35318, 'let someone have both barrels', 'to attack, criticize, or punish someone very forcefully:', 'He arrived late to meet his girlfriend at the airport. She gave him both barrels.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35319, 'let someone have it', 'to attack someone with words or physically', NULL, 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35320, 'let someone in on a secret', 'to allow someone to know something that you have not told anyone else:', 'Can I let you in on a little secret?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35321, 'let someone in on something', 'to tell someone about something that is secret, or to allow someone to become involved in something that only very few people are involved in:', 'Debbie agreed to let me in on her plans.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35322, 'let someone know', 'to tell someone something:', 'Let us know when you get there.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35323, 'let someone loose', 'to allow someone to do what they want in a place:', 'You don''t want to let Oliver loose in the kitchen.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35324, 'let loose something', 'If you let loose something such as bullets or bombs, you release a lot of them all together:', 'The allies let loose an intensive artillery bombardment over the border.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35325, 'let loose something', 'to suddenly make a sound or speak in an uncontrolled way:', 'He turned around and let loose a torrent of abuse.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35326, 'let someone off', 'to not punish someone who has committed a crime or done something wrong, or to not punish them severely:', 'Instead of a prison sentence they were let off with a fine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35327, 'let something off', 'to fire a gun, or to make something such as a bomb or fireworks explode:', 'Don''t let off fireworks near the house.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35328, 'let someone/something in', 'to allow someone or something to enter:', 'She opened the door and let me in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35329, 'let someone/something out', 'to allow someone or something to leave a place, especially by opening a closed or locked door:', 'I heard a voice from the cupboard shouting "Let me out!"', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35330, 'let something out', 'to cause something to come out:', 'He let the air out of the balloon.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35331, 'let something out', 'to make a piece of clothing wider by removing the sewing from the sides and sewing closer to the edge of the material:', 'These trousers are too tight - I''m going to have to let them out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35332, 'let out', 'When something that people go to, such as school or a show, lets out, it ends and everyone leaves:', 'When does school let out for the summer?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35333, 'let something be known', 'to make certain that people are aware of a fact:', 'She let it be known that she did not want to run again for Congress.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35334, 'let something go/pass', 'to not correct or argue with something that a person says or does that is wrong:', 'I know what he said wasn''t strictly accurate but I let it pass anyway.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35335, 'let something into something', 'to put something into a flat surface so that it does not stick out:', 'A skylight had been let into the roof.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35336, 'let something rest', 'to not talk about or mention a particular subject:', 'After he had told his friends he was writing a novel, they wouldn''t let the subject rest.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35337, 'let something ride', 'to not take any action to stop something wrong or unpleasant, thinking that action may not be necessary or is not yet necessary:', 'Don''t panic about the low sales - let it ride for a while and see if business picks up.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35338, 'let something slip', 'to tell people about something without intending to:', 'He let it slip that he hadn''t actually read the report.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35339, 'let something/someone slide', 'to not do anything about something or someone when you should try to change or correct that thing or person:', 'I knew he wasn’t telling me everything, but I decided to let it slide.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35340, 'let the cat out of the bag', 'to allow a secret to be known, usually without intending to:', 'I was trying to keep the party a secret, but Mel went and let the cat out of the bag.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35341, 'let the genie out of the bottle', 'to allow something to happen that cannot then be stopped:', 'When I told her the secret, I let the genie out of the bottle.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35342, 'let the side down', 'to behave in a way that embarrasses or disappoints a group of people that you are part of', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35343, 'let up', 'If bad weather or an unpleasant situation lets up, it stops or improves:', 'When the rain lets up we''ll go for a walk.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35344, 'let up', 'to stop doing something that you have been doing continuously or in a determined way:', 'Neil spent the entire evening moaning about his job - he just wouldn''t let up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35345, 'let up on someone/something', 'to stop treating someone severely, or to stop doing something so forcefully:', 'He advised her to let up on the relentless criticism.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35346, 'let your hair down', 'to allow yourself to behave much more freely than usual and enjoy yourself:', 'Oh let your hair down for once!', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35347, 'let yourself in for something', 'to become involved in a difficult or unpleasant situation without intending to:', 'Do you realize how much extra work you''re letting yourself in for?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35348, 'let''''s face it', 'something that you say before you say something that is unpleasant but true:', 'Let''s face it, we both know why I stopped working there.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35349, 'let''''s face it', 'said before stating something that is unpleasant but true:', 'Let''s face it, we''re not going to win.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35350, 'let''''s get this bread', 'used to encourage someone to try hard and be successful:', 'Wake up everyone - let''s get this bread!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35351, 'let''''s see', 'used when you want to think carefully about something or are trying to remember:', 'Next Saturday, let''s see, that''s when we''re going to the theatre.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35352, 'let/blow off steam', 'to do or say something that helps you to get rid of strong feelings or energy:', 'He lifts weights after work to let off steam.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35353, 'let/set something loose', 'to allow an animal to run around freely after it has been tied up:', 'She let her horse loose in the field.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35354, 'level (sth) down', 'to become worse or less, or to make something worse or less, so that it is the same as something else:', 'Many schools are being levelled down, rather than improved.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35355, 'level off', 'If a rate or amount levels off, it stops rising or falling and stays at the same level:', 'House prices now seem to be levelling off after the steep rises of the last few years.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35356, 'level off/out', 'If an aircraft levels off/out, it starts to travel horizontally rather than going up or down:', 'The jet levelled off at 10, 000 feet.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35357, 'level pegging', 'in an equal position in a competition or game:', 'Both teams are level pegging.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35358, 'level something against/at someone', 'to accuse someone in public of doing something wrong:', 'Criticism has been levelled at senior figures in the industry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35359, 'level something at someone', 'to aim something such as a weapon at someone:', 'She picked up the gun and levelled it at me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35360, 'level sth against sb', 'to accuse someone in public of doing something wrong:', 'Criticism has been levelled at senior figures in the industry.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35361, 'level up', 'to gain enough points in a computer game to enable a player or character to go up to a higher level, gaining more skills or strength', NULL, 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35362, 'level up', 'to go to a higher level or standard:', 'Why not level up to our premium version?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35363, 'level something up', 'to increase or improve something so that it is as good as something else:', 'This approach has levelled standards up across the sector.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35364, 'level something up', '(in computer games) to get more skills, etc. for a character in a game by winning points :', 'Here are all the tips and tricks you need to know on how to level up your characters quickly.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35365, 'level with someone', 'to tell someone the truth about something:', 'I''ll level with you - the salary''s not particularly good, and there''s little chance of promotion.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35366, 'leverage (sth) up', 'to increase the amount of money borrowed:', 'He wanted them to leverage up the company and buy back some stock.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35367, 'lick someone''''s boots', 'to try very hard to please someone in authority, usually in order to get an advantage:', 'He needn''t expect me to go licking his boots!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35368, 'lick your lips', 'to move your tongue along your lips:', 'She took a bite of doughnut and licked her lips.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35369, 'lick your lips', 'to feel pleasure at the thought of something:', 'He licked his lips at the thought of all that money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35370, 'lick your wounds', 'to spend time getting back your strength or happiness after a defeat or bad experience', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35371, 'lie ahead (of someone)', 'to be in the future:', 'We don''t know what lies ahead.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35372, 'lie around', 'If things are lying around, they are left in places where they should not be:', 'Has anyone seen my keys lying around?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35373, 'lie around', 'to spend time lying down and doing very little:', 'I spent a week in Spain, lying around on the beach.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35374, 'lie back', 'to move the top half of your body from a sitting to a lying position:', 'She lay back in the dentist''s chair and tried to relax.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35375, 'lie behind something', 'If something lies behind something else, it is the hidden cause of it:', 'Do you know what lies behind their decision?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35376, 'lie doggo', 'to keep still and hide so that you cannot be found', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35377, 'lie down', 'to move into a position in which your body is flat, usually in order to sleep or rest:', 'He lay down on the bed and tried to relax.', 'phrasal verb', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35378, 'lie down on the job', 'to fail to work as hard or as well as you should', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35379, 'lie in', 'to stay in bed later than usual in the morning:', 'It was a Sunday, so she could lie in till almost lunch time.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35380, 'lie in something', 'to exist or be found in something:', 'His skill lies in his ability to communicate quite complex ideas very simply.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35381, 'lie in wait', 'to hide, ready to attack:', 'The gunmen were lying in wait when Mr Predit came out of the hotel.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35382, 'lie low', 'to try not to be noticed:', 'I''d lie low if I were you till the trouble passes.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35383, 'lie through your teeth', 'to tell someone something that you know is completely false:', 'He asked me how old I was and, lying through my teeth, I said "29".', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35384, 'lie up', 'to hide from police officers, soldiers, etc. who are looking for you:', 'The escaped prisoners lay up in a barn for a few weeks, until the search had been called off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35385, 'life in the fast lane', 'a way of living that is full of excitement, activity, and often danger:', 'Parties and women - he was living life in the fast lane.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35386, 'life is just a bowl of cherries', 'something that you say that means that life is very pleasant. This phrase is often used humorously to mean the opposite.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35387, 'life''''s a bitch (and then you die)', 'said when you find a situation difficult or have had a bad experience', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35388, 'light (something) up', 'If your face or eyes light up, or if a smile lights up your face, you suddenly look happy:', 'Rosie''s whole face lit up with excitement when she saw the presents.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35389, 'light (something) up', 'to light a cigarette:', 'I was lighting up when I noticed a "no smoking" sign.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35390, 'light a fire under someone', 'to make someone act quickly or forcefully, especially someone who has not been doing enough before:', 'The coach tried to light a fire under the team in his halftime speech.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35391, 'light and shade', 'different parts of the character of a person or the quality of a thing:', 'The orchestra''s playing brought out the light and shade in the music.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35392, 'light at the end of the tunnel', 'signs of improvement in a situation that has been bad for a long time, or signs that a long and difficult piece of work is almost finished:', 'As finals approached, she felt that at last she could see the light at the end of the tunnel.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35393, 'light on/upon something', 'to find or think of something unexpectedly:', 'We lighted upon the solution entirely by accident.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35394, 'light the touchpaper', 'to make a bad or extreme situation start happening or to make someone react in an angry or extreme way:', 'The president was fearful of lighting a touchpaper that could spark greater unrest.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35395, 'light years away', 'an extremely long time from now in the past or future:', 'It all happened when I was at college, which seems light years away now that I''m over 50.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35396, 'lighten something up', 'to make a speech or piece of writing less serious:', 'I thought I''d slip in a few jokes to lighten up the talk.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35397, 'lighten up', 'to become more relaxed and less serious:', 'Oh, lighten up! I was only joking!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35398, 'lightning never strikes twice', 'said to show that it is unlikely that something bad or unusual will happen to the same person twice', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35399, 'like a boss', 'used to say that someone does something very well:', 'I''m going to teach you to draw like a boss.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35400, 'like a bull in a china shop', 'If someone is like a bull in a china shop, they are very careless in the way that they move or behave:', 'We told her it was a delicate situation but she went into the meeting like a bull in a china shop.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35401, 'like a cat on a hot tin roof', 'used to describe someone who is in a state of extreme nervous worry', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35402, 'like a dog with two tails', 'used to say that someone is very happy about something:', 'Lucy will be like a dog with two tails if she gets into the team.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35403, 'like a dose of salts', 'very quickly:', 'The medicine went through me like a dose of salts.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35404, 'like a lamb to the slaughter', 'If someone does something or goes somewhere like a lamb to the slaughter, they do it without knowing that something bad is going to happen and therefore act calmly and without fighting against the situation.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35405, 'like a man/woman possessed', 'in a wild and uncontrolled way:', 'He''s been running around the office this morning like a man possessed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35406, 'like a maniac', 'If someone works like a maniac, they work extremely hard.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35407, 'like a shag on a rock', 'completely alone', NULL, 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35408, 'like a shot', 'When someone does something like a shot, they do it extremely quickly and enthusiastically:', 'The moment I let go of the dog, she''s off like a shot.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35409, 'like a steel trap', '(of someone''''s mind or memory) very sharp and quick to understand or remember things:', 'She is an incredible investigative researcher who has a mind like a steel trap.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35410, 'like a streak of lightning', 'extremely quickly:', 'She grabbed the money and ran out of the shop like a streak of lightning.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35411, 'like a thief in the night', 'secretly or unexpectedly and without being seen', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35412, 'like a ton of bricks', 'very strongly or forcefully:', 'If Dad finds out what you''ve been doing, he''ll come down on (= punish) you like a ton of bricks!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35413, 'like blazes', 'very much or very hard:', 'The wind blew and it was raining like blazes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35414, 'like clockwork', 'very regularly, or at exactly the planned times:', 'Since the recent improvements to the service, the buses are running like clockwork.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35415, 'like crazy', 'If you do something like crazy, you do a lot of it or do it very quickly:', 'They were working like crazy to get the job done on time.', 'idiom', 'B2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35416, 'like dishwater', 'used to describe a drink or liquid that is unpleasant because it contains too much water and has very little flavour:', 'This soup/tea tastes like dishwater.', 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35417, 'like fury', 'with great energy and determination:', 'I''ve been working like fury these past few days to catch up.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35418, 'like gold dust', 'said about something that is very difficult to get because a lot of people want it:', 'Tickets for the concert are like gold dust.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35419, 'like greased lightning', 'very fast:', 'As soon as I mentioned work, he was out of the door like greased lightning!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35420, 'like hell', 'very much:', 'We ran like hell.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35421, 'like hell', 'certainly not:', '"Try to be polite to him." "Like hell I will!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35422, 'like herding cats', 'used to describe something that is extremely difficult to do:', 'He says managing lawyers is like herding cats.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35423, 'like it or lump it', 'If you tell someone to like it or lump it, you mean that person must accept a situation they do not like, because it cannot be changed:', 'Like it or lump it, romantic fiction is read regularly by thousands.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35424, 'like lemmings', 'in a silly way, without thinking, and in large numbers:', 'People rushed like lemmings to invest in the company.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35425, 'like lightning', 'extremely quickly', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35426, 'like mad', 'If you do something like mad, you do it very enthusiastically, quickly, or a lot:', 'She''s been saving like mad because she wants to buy a car.', 'idiom', 'B2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35427, 'like nobody''''s business', 'very quickly or very much:', 'He was scribbling away like nobody''s business.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35428, 'like nothing (else) on earth', 'very strange, unusual, or unpleasant:', 'With his make-up and strange clothes, he looked like nothing on earth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35429, 'like nothing on earth', 'very strange, unusual, or unpleasant in appearance, sound, or taste:', 'It looked nice, but it tasted like nothing on earth.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35430, 'like pulling teeth', 'If you say that making someone do something was like pulling teeth, you mean it was very difficult and they did not want to do it:', 'Getting her to tell me about her childhood was like pulling teeth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35431, 'like rats leaving a sinking ship', 'used to refer to people leaving a place, organization, activity, etc. very quickly and in large numbers, because it is failing in some way:', 'Former friends have deserted the couple like rats leaving a sinking ship.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35432, 'like ships that pass in the night', 'If two people are like ships that pass in the night, they meet once or twice by chance for a short time then do not see each other again.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35433, 'like stink', 'If someone works like stink, they work extremely hard.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35434, 'like the cat that ate the canary', 'extremely happy or satisfied, or in a very happy or satisfied way:', 'When he asked her on a date she was like the cat that ate the canary.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35435, 'like the cat that got the cream', 'extremely happy or satisfied, or in a very happy or satisfied way:', 'She looks like the cat that got the cream.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35436, 'like the clappers', 'extremely fast:', 'You''ll have to run like the clappers if you want to catch your train.', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35437, 'like the sound of something', 'to feel happy or satisfied about a piece of information you have just heard:', '"The radio says there’ll be rain turning into snow." "Ooh, I don’t like the sound of that."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35438, 'like there is/was no tomorrow', 'If someone does something like there is/was no tomorrow, they do it very fast, in large amounts and without thinking carefully:', 'After he won the lottery, he began spending money like there was no tomorrow.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35439, 'like there’s no tomorrow', 'as much or as fast as possible, without planning or thinking first:', 'The minute he got paid, he started spending money like there’s no tomorrow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35440, 'like two peas in a pod', 'very similar, especially in appearance:', 'The twins are like two peas in a pod.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35441, 'like wildfire', 'quickly in a way that cannot be controlled:', 'News of the layoffs spread like wildfire through the company.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35442, 'like you care!/like you''''d know!/like he''''d ask!', 'used to emphasize that something that has been suggested is not true or would never happen:', '"Are you OK?" "Like you care!" (= I don''t believe you care whether I''m OK.)
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35443, 'like you owned the place', 'in a way that is too confident:', 'He walked into the office like he owned the place.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35444, 'liken someone/something to someone/something', 'to say that someone is similar to or has the same qualities as someone else:', 'She''s been likened to a young Elizabeth Taylor.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35445, 'limber up', 'to do gentle exercises to stretch the muscles in order to prepare the body for more active physical exercise:', 'The substitutes are beginning to limber up on the sidelines.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35446, 'line (someone) up', 'to arrange people or things in a row or to stand in a row:', 'A fight broke out behind me as we lined up to receive our food rations.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35447, 'line something up', 'to prepare, organize, or arrange something:', 'Do you have anything exciting lined up for the weekend?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35448, 'line of sight', 'the direction in which a person must look in order to see a particular object:', 'The cannon can be linked to the line of sight of the gunner so that it points in the same direction that he is looking in.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35449, 'line your pocket(s)', 'to earn money using dishonest or illegal methods:', 'Staff at the bank have apparently been lining their pockets with money from investors'' accounts.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35450, 'link (something) up', 'to form a connection, especially in order to work or operate together:', 'The organization''s aim is to link up people from all over the country who are suffering from the disease.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35451, 'listen in on something/someone', 'If you listen in on a conversation or on someone talking, you listen, especially secretly, without saying anything:', 'I wish Dad would stop listening in on my phone conversations.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35452, 'listen out for something', 'to make an effort to hear a noise that you are expecting:', 'Would you listen out for the phone while I''m in the garden?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35453, 'listen to reason', 'to listen to good advice and be influenced by it:', 'Friends tried to persuade them to change their minds, but neither man would listen to reason.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35454, 'listen up', 'something you say to make people listen to you:', 'Okay everyone—listen up! I have an announcement to make.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35455, 'little/small wonder', 'it is not really surprising:', 'Her car isn''t working, so it''s little wonder (that) she hasn''t come to visit you recently.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35456, 'live (from) hand to mouth', 'to have just enough money to live on and nothing extra:', 'My father earned very little and there were four kids, so we lived from hand to mouth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35457, 'live (on) in the memory', 'If something lives (on) in the memory, it has such an effect that it is remembered for a long time.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35458, 'live a lie', 'to live in a way that is dishonest because you are pretending to be something that you are not, to yourself or to other people:', 'She doesn''t know you''re married? You have to stop living a lie and tell her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35459, 'live and breathe something', 'When a person lives and breathes something, it is extremely important to them:', 'He lives and breathes music.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35460, 'live and let live', 'said to mean that people should accept the way other people live and behave, especially if they do things in a different way', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35461, 'live by your wits', 'to make money in a clever and usually dishonest way', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35462, 'live down something', 'to make people forget that you made a big mistake or did something very embarrassing in the past:', 'If you show up with green hair, your parents will never let you live it down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35463, 'live for something/someone', 'to have something or someone as the most important thing in your life:', 'She just lives for music.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35464, 'live high on/off the hog', 'to live in great comfort with a lot of money', NULL, 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35465, 'live in', 'to live at the place where you work or study:', 'The university guarantees accommodation in halls of residence for every first year who wants to live in.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35466, 'live in sin', 'to live with someone that you are having a sexual relationship with but are not married to:', 'Last I heard, they''d moved in together and were living in sin.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35467, 'live it up', 'to have an exciting and very enjoyable time with parties, good food and drink, etc.:', 'He''s alive and well and living it up in the Bahamas.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35468, 'live like a king/lord', 'to have a luxurious (= spending a lot of money) way of life', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35469, 'live off someone/something', 'to use someone or something to provide the money or food that you need to live:', 'All his life he had lived off his father.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35470, 'live off the fat of the land', 'to be rich enough to live well without having to do very much', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35471, 'live on borrowed time', 'to continue living after a point at which you might easily have died:', 'Since his cancer was diagnosed, he feels as if he''s living on borrowed time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35472, 'live on borrowed time', 'to continue to exist longer than expected:', 'It is unlikely that serious decisions will be made by a CEO living on borrowed time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35473, 'live on something', 'If you live on an amount of money, that is the money that you use to buy the things that you need:', 'We lived on very little when we first got married.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35474, 'live on something', 'to only eat a particular type of food:', 'I more or less live on pasta.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35475, 'live out', 'to not live at the place where you work or study:', 'We have a nanny, but she lives out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35476, 'live out something', 'to spend your life or the last period of your life in a particular way:', 'She retired and lived out the rest of her days quietly in the country.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35477, 'live out your dreams/fantasies', 'to do something that you really wanted but did not think was possible:', 'They are living out their show-biz dreams.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35478, 'live through something', 'to experience a difficult situation or event:', 'He could never know the pain and fear this child had lived through.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35479, 'live to fight another day', 'to have another chance to fight in a competition; to be able to continue with your life although you have had a bad experience:', 'We didn''t win this time, but we live to fight another day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35480, 'live to tell the tale', 'to successfully deal with or continue to live despite a difficult situation or experience:', 'We had a horrific journey, but we lived to tell the tale.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35481, 'live together', 'If two people live together, they share a house and have a sexual relationship but are not married:', 'Nowadays many young people live together before they get married.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35482, 'live up to something', 'to be as good as something:', 'The concert was brilliant - it lived up to all our expectations.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35483, 'live with someone', 'to share a home with someone and have a sexual relationship with them although you are not married', NULL, 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35484, 'live with something', 'to accept a difficult or unpleasant situation:', 'I can''t change the situation so I''m going to have to learn to live with it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35485, 'live your own life', 'to spend your life doing what you want, usually because something is no longer stopping you from doing so:', 'Now that the children have left home, I can live my own life again.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35486, 'live/be in clover', 'to enjoy a life of money and comfort:', 'With the income from the family estate, she''s in clover.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35487, 'lived in', 'regularly used and comfortable:', 'I like a room to look lived in.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35488, 'liven (something) up', 'to become more interesting and exciting, or to make something become like this:', 'A new coat of paint would liven the kitchen up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35489, 'liven (someone) up', 'to become more energetic or in a better mood, or to make someone feel this way:', 'She was subdued to start with, but after a while she livened up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35490, 'lo and behold', 'something that you say when you tell someone about something surprising that happened:', 'I was in Vienna sitting quietly in a café when, lo and behold, my cousin walked in.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35491, 'load (sth) up with sth', 'to get a lot of money, assets, or debt, or to make someone else get them:', 'Private-equity buyouts aim to load companies up with lots of debt.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35492, 'load (sth) up with sth', 'to put a large amount of goods, materials, etc. onto a vehicle to transport them:', 'Fleets of small ships were loading up with oil in the Gulf.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35493, 'load up on something', 'to gather or buy a large amount of something:', 'The tourists started loading up on perfume and cosmetics.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35494, 'load up something', 'to put things in or on a vehicle:', 'Let’s load up the car and then we can go.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35495, 'loaded down with things', 'carrying or trying to carry a lot of things:', 'She had three children and was loaded down with two heavy suitcases.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35496, 'loads of something', 'infml much or many:', 'There were loads of people standing around a TV set in the store.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35497, 'lock (something) up', 'to lock all the doors and windows of a building when you leave it:', 'Sandra, will you lock up tonight when you go?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35498, 'lock someone up', 'to put someone in a prison or a hospital for people who are mentally ill:', 'Murderers should be locked up for life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35499, 'lock horns', 'to begin to argue or fight:', 'The mayor and her deputy locked horns over plans for the new road.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35500, 'lock someone into something', 'to prevent a person or organization from ending or changing an agreement or financial arrangement:', 'The gas company is locked into long-term supply contracts.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35501, 'lock someone out', 'to prevent someone from entering a building or room by locking the door:', 'He had to break into the house because his girlfriend had locked him out.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35502, 'lock someone out', 'to prevent workers from entering their place of work until they agree to particular conditions given by the employer:', 'Management has threatened to lock out the workforce if they do not accept the proposed changes in working methods.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35503, 'lock someone out', 'to make it impossible for someone to use a computer system, electronic device, etc.:', 'When someone is fired they are immediately locked out of the network.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35504, 'lock someone out of something', 'to prevent a person or organization from having or being able to take part in something:', 'The company risks being locked out of China''s booming car market.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35505, 'lock something away', 'to put something in a safe place and lock the door in order that someone else cannot get it:', 'If you keep valuables in your house, lock them away somewhere safe.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35506, 'lock something in', 'to get and keep an advantage such as a low price:', 'People are jumping to purchase homes and lock in affordable mortgage rates before they increase.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35507, 'lock something in', 'to choose or decide something finally and definitely, for example by pressing a key on a computer keyboard:', 'Press SET again to lock in your choice.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35508, 'lock someone in', 'to prevent someone from leaving a room or building by locking the door:', 'She stormed off to her bedroom and locked herself in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35509, 'lock someone in', 'to prevent someone from ending or changing a financial arrangement:', 'Most cell phone contracts lock you in for a fixed period.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35510, 'lock, stock, and barrel', 'including all or every part of something:', 'We had to move our things lock, stock, and barrel to the other side of the country.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35511, 'log in', 'to connect to a computer system by putting in a particular set of letters or numbers:', 'What is the user name and password that you use to log on?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35512, 'log in/on', 'to connect a computer to a computer system by typing your name, so that you can start working:', 'Log on using your name and password.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35513, 'log off', 'to stop using a computer system or program by giving a particular instruction:', 'The program lets you shut down, restart, or log off Windows at specific times and dates.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35514, 'log off/out', 'to stop a computer being connected to a computer system, usually when you want to stop working:', 'Could you all log off for a few minutes, please?', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35515, 'log on', 'to start using a computer system or program by giving a password (= a secret word by which the system recognizes an approved user):', 'About 40,000 gamers have been logging on every day since the website appeared last month.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35516, 'log out', 'to end a connection to a computer system by clicking on a spot on the computer screen:', 'To log off, simply turn off the machine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35517, 'lonely hearts', 'a place or part of a magazine, etc. for people who would like to make new friends or meet a sexual partner', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35518, 'long live someone/something!', 'said to show support for the person or thing mentioned:', 'Long live the president!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35519, 'long on something and short on something', 'having too much of one quality and not enough of another:', 'I''ve always found his movies long on style and short on content.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35520, 'long story short', 'used when you do not tell all the details:', 'Long story short, I got fired.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35521, 'long time no see', 'said when you meet someone who you haven''''t seen for a long period of time', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35522, 'look a fright', 'to look ugly or untidy:', 'Didn''t she look a fright in that dress?', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35523, 'look after someone/something', 'to take care of or be in charge of someone or something:', 'We look after the neighbours'' cat while they''re away.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35524, 'look ahead', 'to think about what will happen in the future and plan for these events:', 'We are trying to look ahead and see what our options are.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35525, 'look around (somewhere/something)', 'to visit a place and look at the things in it:', 'She spent the afternoon looking around the town.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35526, 'look at something', 'to think about a subject carefully so that you can make a decision about it:', 'Management is looking at ways of cutting costs.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35527, 'look at something', 'to consider something in a particular way:', 'If I''d had children I might have looked at things differently.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35528, 'look at something', 'to read something in order to check it or form an opinion about it:', 'Can you look at my essay sometime?', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35529, 'look at something', 'If someone, usually an expert, looks at something, they examine it:', 'Did you get the doctor to look at your knee?', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35530, 'look at/see something through rose-colored/rose-tinted glasses', 'to see only the pleasant things about a situation and not notice the things that are unpleasant:', 'She''s always looked at life through rose-tinted glasses.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35531, 'look at/see something through rose-coloured/rose-tinted glasses', 'to see only the pleasant things about a situation and not notice the things that are unpleasant:', 'She''s always looked at life through rose-tinted glasses.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35532, 'look back', 'to think about something that happened in the past:', 'When I look back I can see where we went wrong.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35533, 'look before you leap', 'to check that something is not going to cause problems or have a bad result before you do it:', 'The general advice with a job offer is to do your research and look before you leap.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35534, 'look daggers at someone', 'to look angrily at someone', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35535, 'look down on someone', 'to think that you are better than someone:', 'She thinks they look down on her because she doesn''t have a job.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35536, 'look forward to something', 'to feel pleased and excited about something that is going to happen:', 'I''m really looking forward to my holiday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35537, 'look forward to something', 'used at the end of a formal letter to say you hope to hear from or see someone soon, or that you expect something from them:', 'I look forward to hearing from you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35538, 'look in', 'to visit a person for a short time, usually when you are on your way somewhere else:', 'I thought I might look in on Bob on my way to the shops.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35539, 'look in on someone/something', 'to visit someone or something for a short time:', 'It helps if older people have a nearby relative who will look in on them.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35540, 'look into something', 'to examine the facts about a problem or situation:', 'We''re looking into the possibility of merging the two departments.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35541, 'look kindly on someone/something', 'to have a good opinion of someone or something:', 'She had hoped the critics would look kindly on her first novel.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35542, 'look like a drowned rat', 'to be very wet, especially because you have been in heavy rain', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35543, 'look like someone/something', 'to be similar in appearance to someone or something:', 'The twins look like their mother.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35544, 'look like something', 'to appear likely to happen:', 'It sure looks like snow today.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35545, 'look like something the cat brought/dragged in', 'to look very untidy and dirty', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35546, 'look like the back end of a bus', 'to look very unattractive:', 'She may object if she is photographed looking like the back end of a bus.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35547, 'look like/as if you''''ve been dragged through a hedge backwards', 'to look very untidy:', 'I looked as if I''d been dragged through a hedge backwards when I woke up this morning.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35548, 'look like/as though you''''ve seen a ghost', 'to look very shocked:', 'What''s the matter? You look like you''ve seen a ghost!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35549, 'look lively/sharp!', 'used to tell someone to do something quickly:', 'Look lively - we haven''t got all day!', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35550, 'look no further', 'used to say that something is exactly what someone wants or needs:', 'If you want the perfect solution to family transport, look no further, because even children can''t break this thing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35551, 'look on', 'to watch something happen but not become involved in it:', 'A large crowd looked on as the band played.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35552, 'look on the bright side', 'to find good things in a bad situation:', 'Look on the bright side - no one was badly hurt.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35553, 'look on/upon someone/something', 'to consider or think of someone or something in a stated way:', 'We looked on her as a daughter.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35554, 'look on/upon someone/something as something', 'to consider or think of someone or something as something:', 'We looked on her as a daughter.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35555, 'look out', 'to watch what is happening and be careful:', 'The police have warned shopkeepers to look out for forged notes.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35556, 'look out', 'said or shouted in order to tell someone that they are in danger:', 'Look out! There''s a car coming!', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35557, 'look something out', 'to search for and find something:', 'I''ll look out that recipe I told you about and send it to you.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35558, 'look out for number one', 'to do what you think is best for yourself and not care about other people', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35559, 'look out for someone/something', 'to try to notice someone or something:', 'Look out for Anna while you''re there.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35560, 'look over something', 'to quickly examine something:', 'I had a few minutes before the meeting to look over what he''d written.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35561, 'look right through someone', 'to pretend not to see someone even while your eyes are directed toward that person:', 'I smiled at him, but he looked right through me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35562, 'look round (somewhere/something)', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35563, 'look someone in the eye', 'to talk to someone in an honest way that shows no doubts:', 'I wanted to look people in the eye and tell them I made a mistake.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35564, 'look someone in the eye/face', 'to talk to someone in a direct and confident way that shows you are honest or not ashamed:', 'I wanted to look people in the eye and tell them I made a mistake.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35565, 'look straight/right through someone', 'to look at someone as if you cannot see them, either intentionally or because you are thinking about something else:', 'I said hello but she looked straight through me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35566, 'look through something', 'to read something quickly:', 'I''ve looked through some catalogues.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35567, 'look to someone for something', 'to hope that someone will provide something for you:', 'They looked to the government for additional support.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35568, 'look to someone to do something', 'to hope that someone will do something for you:', 'We''re looking to you to advise us on how to proceed.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35569, 'look to your laurels', 'to make an extra effort to succeed because there is more competition:', 'Nowadays there are a number of similar products on the market and the older, established companies are having to look to their laurels.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35570, 'look up', 'to become better:', 'I hope things will start to look up in the new year.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35571, 'look something up', 'to try to find a piece of information by looking in a book or on a computer:', 'If you don''t know what the word means, look it up in a dictionary.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35572, 'look someone up', 'to visit someone you have not seen for a long time when you are visiting the place where they live:', 'Look me up next time you''re in Los Angeles.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35573, 'look up to someone', 'to admire and respect someone:', 'He''d always looked up to his uncle.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35574, 'look who''''s talking!', 'something you say when someone criticizes you for something that that person does himself or herself:', 'I''m lazy? Look who''s talking!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35575, 'look/feel like a million dollars', 'to look or feel extremely good, often because you are wearing something that costs a lot of money:', '"You look like a million dollars in that dress, honey!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35576, 'look/feel like death warmed over', 'to look or feel very sick:', 'He shouldn''t be working when he''s so sick - he looks like death warmed over!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35577, 'look/feel like death warmed up', 'to look or feel very ill:', 'He shouldn''t be working when he''s so ill - he looks like death warmed up!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35578, 'looking for trouble', 'behaving in a way that is likely to cause problems for you:', 'Parking illegally in front of the police station is looking for trouble.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35579, 'loom large', 'If something looms large, it becomes very important and often causes worry:', 'The issue of pay will loom large at this year''s conference.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35580, 'loop the loop', 'to fly in the shape of a loop in the sky', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35581, 'loose your hold/grip', 'to decide to control a person or situation less:', 'Sooner or later Isambard would have to loose his hold of him.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35582, 'loosen (something) up', 'to prepare your muscles for a physical activity by stretching and doing simple exercises:', 'I do a few stretches to loosen up before I run.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35583, 'loosen (someone) up', 'to start to feel less embarrassed and to become more relaxed when you are with other people, or to make someone feel like this:', 'He seemed quite nervous at the beginning, but he soon loosened up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35584, 'loosen someone''''s tongue', 'to make someone speak more freely:', 'A couple of glasses of champagne had loosened my tongue and I said things that perhaps I shouldn''t have.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35585, 'loosen your grip', 'If you loosen your grip on an object, or your grip loosens, you hold something less tightly:', 'He held my hand very tightly at first but gradually his grip loosened.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35586, 'loosen your grip/hold', 'If you loosen your grip/hold on a situation, or your grip/hold loosens, you decide to control it less:', 'The dictator''s grip on the country has not loosened.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35587, 'lop something off', 'to cut something off in one quick movement:', 'I''ll need to lop off the lower branches of the tree.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35588, 'lop something off', 'to reduce a price or the amount of time taken to do something by a particular amount:', 'He lopped eight seconds off the record.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35589, 'lord it over someone', 'to behave as if you are more important than someone and have a right to tell that person what to do:', 'He likes to lord it over his little sister.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35590, 'lord/master/mistress/king/queen of all you survey', 'If you are lord, master, mistress, king, or queen of all you survey, you own or control the place in which you live or work.', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35591, 'lose count of something', 'to not be able to remember a total:', 'I’ve lost count of how many times she’s been late for work this month.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35592, 'lose face', 'to become less respected by others:', 'She had to accept defeat without losing face.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35593, 'lose ground', 'to become less popular or to be given less support:', 'Do you agree that left-wing politics are losing ground among the working classes?', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35594, 'lose heart', 'to stop believing that you can succeed:', 'Don''t lose heart, there''ll be plenty more chances for promotion.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35595, 'lose it', 'to stop being able to control your emotions and suddenly start to shout, cry, or laugh:', 'I''d been trying so hard to stay calm but in the end I just lost it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35596, 'lose out', 'to not have an advantage that other people have:', 'The new tax means that the vast majority of working people will lose out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35597, 'lose sight of something', 'to forget about an important idea or fact because you are thinking too much about other things:', 'I''m worried that we''re losing sight of our original objectives.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35598, 'lose sleep (over something)', 'to worry about something so much that you cannot sleep:', 'I know you made a mistake, but I wouldn''t lose sleep over it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35599, 'lose sleep over/about something', 'to worry about something:', 'I wouldn''t lose any sleep over what happened.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35600, 'lose the dressing room', 'If a football manager loses the dressing room, the players no longer respect him or follow his instructions:', 'If the owner believes he has lost the dressing room, it could spell the end for the manager.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35601, 'lose the plot', 'to no longer be able to act normally or understand what is happening:', 'I can''t believe Stuart did that - he must be losing the plot.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35602, 'lose touch (with someone)', 'to no longer communicate with someone:', 'I lost touch with Katie after she moved to Canada.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35603, 'lose touch (with something/someone)', 'to no longer have recent knowledge of something or someone, so that you do not understand that thing or person well:', 'Politicians can easily lose touch with the real people if they spend too much time in Washington D.C.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35604, 'lose track', 'to no longer know what is happening, or not to remember something:', 'What he was saying was so complicated that I lost track after the first couple of sentences.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35605, 'lose your head', 'to lose control and not act in a calm way:', 'He usually stays quite calm in meetings but this time he just lost his head.', 'idiom', 'C1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35606, 'lose your heart to someone', 'to fall in love with someone', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35607, 'lose your life', 'to die suddenly because of an accident or violent event:', 'Many people lost their lives in the floods.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35608, 'lose your mind', 'to become mentally ill, or to start behaving in a silly or strange way:', 'You just spent all that money on a pair of shoes? Have you completely lost your mind?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35609, 'lose your rag', 'to suddenly become very angry:', 'He said one too many stupid things and I just lost my rag.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35610, 'lose your shirt', 'to lose a lot of money, especially as a result of a bet (= money risked when you guess the result of something)', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35611, 'lose your temper', 'to become very angry:', 'Michelle wanted everybody to like her so much that she just lost it if someone got mad at her.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35612, 'lose your touch', 'If you lose your touch, you can no longer do something as well as you could before:', 'It''s good to see their goalkeeper''s not losing his touch.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35613, 'lose your way', 'to become lost', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35614, 'lost in the shuffle', 'If something or someone gets lost in the shuffle, that thing or person does not get the attention they deserve:', 'Refugee children in the big camps just get lost in the shuffle and are sometimes left without food.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35615, 'loud and clear', 'very clear and easy to understand:', 'I can hear you loud and clear.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35616, 'lounge around (something)', 'to spend your time in a relaxed way, sitting or lying somewhere and doing very little:', 'We spent our days lounging around the pool.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35617, 'louse (something) up', 'to spoil something or cause it to fail:', 'This is a great opportunity, so don''t louse it up.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35618, 'love me, love my dog', 'said to warn someone that if they want to be in a relationship with you, they must be willing to accept everything about you', NULL, 'idiom', NULL, NULL, 'humorous, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35619, 'love someone to bits', 'to love someone very much:', 'He''s my old man and I love him to bits but I can''t spend too much time with him.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35620, 'lower your sights', 'to accept that you will only be able to get something less than you hoped for:', 'He had hoped to become a doctor, but he had to lower his sights after his disappointing exam results.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35621, 'luck into something', 'to get something that you want by chance:', 'We lucked into tickets for the World Cup finals.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35622, 'luck out', 'to be very lucky:', 'The Giants really lucked out in last night''s game.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35623, 'lull someone into something', 'to make someone feel safe in order to trick them:', 'Most exercise classes start gently, lulling you into thinking that you''re in good shape.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35624, 'lumber someone with something', 'If you are/get lumbered with something, you have to deal with something or someone that you do not want to:', 'I always seem to get lumbered with the job of clearing up after a party.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35625, 'lump someone/something together', 'to put different groups together and think about them or deal with them in the same way:', 'All the children are lumped together in one class, regardless of their ability.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35626, 'lust after someone', 'to feel sexual desire for someone you are not having a sexual relationship with:', 'She''s been lusting after Dave for months.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35627, 'lust after/for something', 'to want something very much:', 'I''ve been lusting after one of their silk shirts for ages.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35628, 'luxuriate in something', 'to get great pleasure from something, especially because it provides physical comfort:', 'There''s nothing better after a hard day''s work than to luxuriate in a hot bath.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35629, 'made for each other', 'perfectly matched:', 'The long cool drinks and the hot spicy food were made for each other.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35630, 'made of sterner stuff', 'If someone is described as being made of sterner stuff, they are very strong and determined:', 'I was ready to give up the fight, but Nicky was made of sterner stuff and wanted us to finish.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35631, 'mail sth out', 'to send something by mail:', 'In March we mailed out three million catalogues.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35632, 'major in something', 'to study something as your main subject in college or a university:', 'She majored in earth sciences at Arizona State.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35633, 'make (a) nonsense of something', 'to make something appear stupid or wrong, or to spoil something:', 'His repeated lack of promotion makes nonsense of the theory that if you work hard you''ll be successful.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35634, 'make (all) the right, correct, etc. noises', 'to say the things you are expected to say, sometimes when you do not mean them:', 'He made all the right noises about my audition but I couldn''t tell if he was genuinely impressed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35635, 'make (all) the running', 'to do the best and most work:', 'British companies have often made all the running in developing new ideas, but have then failed to market them.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35636, 'make (someone''''s) hackles rise', 'to annoy someone:', 'The president''s speech has raised hackles among members of the opposing party.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35637, 'make a (big) difference', 'to improve a situation or condition in an important way:', 'He''s much happier now – his new school seems to have made a big difference.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35638, 'make a beeline for something', 'to move quickly and directly toward something:', 'When he saw me in the kitchen, he made a beeline for the door.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35639, 'make a big thing (out) of something', 'to give something too much importance:', 'I want a party, but I don''t want to make a big thing of it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35640, 'make a bundle', 'to earn a lot of money:', 'They made a bundle selling their business.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35641, 'make a case for something', 'to argue that something is the best thing to do, giving your reasons:', 'We will only publish a new edition if you can make a convincing case for it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35642, 'make a clean breast of it', 'to tell the truth about something:', 'Julia finally made a clean breast of it and admitted that she had stolen the money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35643, 'make a day/night/evening/weekend of it', 'to make an activity longer or combine a series of activities so that they last for the whole of that particular period of time:', 'We wanted to drive up the coast, so we decided to make a weekend of it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35644, 'make a dent in something', 'to reduce an amount of something, esp. money or work:', 'Buying a new car put a big dent in our savings.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35645, 'make a difference', 'to improve a situation:', 'Exercise can make a big difference to your state of health.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35646, 'make a difference', 'If a person makes a difference, they make a situation better because of their good actions:', 'What she showed is that one person can make a difference.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35647, 'make a face (at someone/something)', 'to move your mouth, nose, and eyes in strange ways to show emotion or make people laugh:', 'She stepped in something, made a face, and looked down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35648, 'make a fool (out) of someone', 'to do something that makes someone, esp. yourself, seem ridiculous:', 'I almost stood up and sang, but I decided I didn''t want to make a fool out of myself.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35649, 'make a habit of something', 'to begin to do something regularly, often without thinking about it:', 'He made a habit of ignoring me whenever his friends were around.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35650, 'make a hole in something', 'to reduce an amount of money by a lot:', 'The trip made a big hole in our savings but I''m glad we went.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35651, 'make a joke of something', 'to laugh at something although it is serious or important:', 'He tried to make a joke of the fact that he hadn''t passed the test.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35652, 'make a killing', 'to earn a lot of money in a short time and with little effort:', 'They made a killing with the sale of their London house.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35653, 'make a man (out) of someone', 'to cause a young man or boy to act like an adult and take responsibility:', 'A couple of years in the army should make a man of him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35654, 'make a meal (out) of something', 'to spend more time or energy doing something than is necessary:', 'I only asked for a summary of the main points but she''s making a real meal out of it.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35655, 'make a mockery of something', 'to make something seem stupid or without value:', 'Behaviour like this makes a mockery of professional sport.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35656, 'make a monkey out of someone', 'to make someone appear stupid', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35657, 'make a mountain out of a molehill', 'to make a slight difficulty seem like a serious problem:', 'You''re making a mountain out of a molehill. You wrote one bad essay - it doesn''t mean you''re going to fail.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35658, 'make a move', 'to leave a place:', 'It''s late - I think it''s time we made a move.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35659, 'make a move', 'to try to start a romantic or sexual relationship with someone:', 'He accused the man of making a move on his girlfriend.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35660, 'make a muck of something', 'to spoil something or do something very badly:', 'I''ve made a muck of it - I''ll have to do it again.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35661, 'make a name for yourself', 'to become famous or respected by a lot of people:', 'He''s made a name for himself as a talented journalist.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35662, 'make a noise about something', 'to talk about or complain about something a lot:', 'She''s been making a lot of noise about moving to a new house.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35663, 'make a pig of yourself', 'to eat too much:', 'They made complete pigs of themselves at the dinner.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35664, 'make a pig''''s ear of something', 'to do something badly, wrongly, or awkwardly:', 'He''s made a real pig''s ear of that bookcase he was supposed to be making.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35665, 'make a pile', 'to earn a large amount of money:', 'He made a pile selling computers and retired by the time he was 40.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35666, 'make a play for something/someone', 'to try to get something, or start a relationship with someone, sometimes by using a plan:', 'I wouldn''t have made a play for him if I''d known he was married.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35667, 'make a point of doing something', 'to always do something or to take particular care to do something:', 'She makes a point of keeping all her shopping receipts.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35668, 'make a production (out) of something', 'to make something seem more difficult or complicated to do than it is:', 'If you ask Tom to do anything, he always makes such a production of it that you wish you''d just done it yourself.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35669, 'make a rod for your own back', 'If you make a rod for your own back, you act in a way that creates more problems for yourself in the future:', 'By giving in to the terrorists'' demands, the government will simply be making a rod for its own back.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35670, 'make a run for it', 'to suddenly start running in order to escape from somewhere:', 'One of the prisoners tried to make a run for it.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35671, 'make a scene', 'to behave in a loud, angry way in public :', 'Please don''t make a scene.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35672, 'make a song and dance about something', 'to make something seem more important than it really is so that everyone notices it:', 'I only asked her to move her car but she made such a song and dance about it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35673, 'make a spectacle of yourself', 'to do something that makes you look stupid and attracts other people''''s attention:', 'I wasn''t going to make a spectacle of myself just to give you a laugh!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35674, 'make a splash', 'to become suddenly very successful or very well known:', 'Jodie Foster made quite a splash in the film "Taxi Driver".', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35675, 'make a virtue (out) of something', 'to use something, especially a bad situation, to your advantage:', 'I had a couple of months to spare between jobs so I thought I''d make a virtue of necessity by acquiring a few new skills.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35676, 'make a world of difference', 'If something makes a world of difference, it improves something very much:', 'A little sympathy makes a world of difference to someone who''s been badly treated.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35677, 'make a/your mark (on something)', 'to have an important effect on something:', 'Daniel didn''t work here for very long, but he definitely made his mark on the place.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35678, 'make an ass of yourself', 'a rude phrase meaning to behave stupidly and look silly:', 'Simon always makes a complete ass of himself when he''s had too much to drink.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35679, 'make an exhibition of yourself', 'to do something stupid in public:', 'I hope I didn''t make an exhibition of myself last night.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35680, 'make an honest living', 'to earn money by working hard at a job', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35681, 'make an honest woman (out) of someone', 'to marry a woman you are having a sexual relationship with', NULL, 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35682, 'make an impression on someone', 'to cause someone to notice and admire you:', 'He made quite an impression on the girls at the tennis club.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35683, 'make as if to do something', 'If you make as if to do something, you seem as if that is what you are going to do:', 'He made as if to speak.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35684, 'make capital out of something', 'to use a situation to get an advantage for yourself:', 'The Opposition is making a lot of political capital out of the government''s failure to invest in education.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35685, 'make conversation', 'to say things to someone who you do not know well, in order to be polite:', 'I was just trying to make conversation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35686, 'make do', 'to manage to live without things that you would like to have or with things of a worse quality than you would like:', 'We didn''t have cupboards so we made do with boxes.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35687, 'make do (with something)', 'to use what is available although it is not enough or what you wanted:', 'Can you make do with $5 for now and I’ll give you the rest tomorrow?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35688, 'make ends meet', 'to have just enough money to pay for the things that you need', NULL, 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35689, 'make eyes at someone', 'to look at someone with sexual interest:', 'She was making eyes at him all evening.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35690, 'make for somewhere/something', 'to go in the direction of a place or thing:', 'They made for the centre of town.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35691, 'make for something', 'to result in or make possible:', 'Having faster computers would make for a more efficient system.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35692, 'make fun of someone', 'to be unkind to someone and laugh at or cause others to laugh at the person:', 'You’re always making fun of me!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35693, 'make good', 'to succeed and become rich:', 'a working-class boy made good', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35694, 'make good', 'When someone makes good something, they either pay for it, or make it happen:', 'My uncle owed thousands, but eventually he made good on all of his debts.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35695, 'make good on something', 'to do what you have said you would do:', 'My grandfather said he would pay for me to go to college, and he made good on that promise.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35696, 'make good time', 'to complete a journey quickly', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35697, 'make haste', 'hurry up:', 'Make haste!', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35698, 'make hay while the sun shines', 'to make good use of an opportunity while it lasts', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35699, 'make headway', 'to begin to succeed:', 'Has the city made any headway in attracting new businesses?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35700, 'make heavy weather of something', 'to find something hard to do and spend a lot of time on it, although it is not difficult:', 'She''s making such heavy weather of that report she''s writing.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35701, 'make history', 'to do something important that has not been done before and will be recorded publicly and remembered for a long time:', 'Margaret Thatcher made history when she became the first female British prime minister.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35702, 'make it', 'to continue to live or exist, especially after coming close to dying or being destroyed or after being in a difficult or threatening situation:', 'Given his injuries, we didn''t expect him to make it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35703, 'make it', 'to be very successful:', 'She paid tribute to the hit sitcom for helping her make it in Hollywood.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35704, 'make it a rule', 'to act according to a principle:', 'I make it a rule not to eat fatty foods.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35705, 'make it big', 'to become famous or successful', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35706, 'make it quick/fast', 'used to tell someone to do something quickly or to hurry up:', 'Take him to the hospital - and make it quick!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35707, 'make it snappy', 'used to tell someone that you want them to do something immediately and to do it quickly:', 'Get your shoes on, and make it snappy.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35708, 'make it up to someone', 'to do something good for someone you have upset, in order to become friends with them again:', 'I''m sorry we can''t take you with us, but I promise I''ll make it up to you somehow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35709, 'make it with someone', 'to have sex with someone', NULL, 'idiom', NULL, NULL, 'old-fashioned informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35710, 'make legal history', 'If you make legal history, the case you win in court or take to court is the first of its type and changes the way future cases will be dealt with.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35711, 'make light of something', 'to act as if something is not serious, esp. when it is serious:', 'They''ve both had knee injuries, but the two friends make light of their weaknesses.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35712, 'make like', 'to pretend:', 'She made like she was about to leave, but then stayed for hours.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35713, 'make little of something', 'to not consider something to be very important:', 'He made little of his ordeal.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35714, 'make love', 'to have sex:', 'That night they made love for the first time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35715, 'make love to someone', 'to speak romantically and give attention to someone, especially in order to make them love you:', 'Mr Jackson, I do believe you are making love to me.', 'idiom', NULL, NULL, 'old use', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35716, 'make matters worse', 'to make the situation even more unpleasant or difficult:', 'Don''t say anything - you''ll only make matters worse.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35717, 'make mincemeat of someone', 'to defeat someone very easily in an argument, competition, or fight:', 'A decent lawyer would have made mincemeat of them in court.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35718, 'make mischief', 'to intentionally say or do something that causes other people to be upset or annoyed with each other:', 'My children often try to make mischief between me and my new husband.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35719, 'make much of something', 'to give a lot of importance to something:', 'Don''t make too much of the test results.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35720, 'make much/a lot of someone', 'to treat someone very well:', 'His mother used to make much of him when he went back home.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35721, 'make nice', 'to behave in a kind, friendly, or polite way towards someone, especially when you are not being sincere:', 'They need to make nice with each other and get to work.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35722, 'make no apologies', 'to believe that what you have done is right or acceptable:', 'The network makes no apologies for broadcasting the controversial film.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35723, 'make no bones about something', 'not to try to hide your feelings:', 'He made no bones about his dissatisfaction with the service.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35724, 'make no claim to be something', 'to not be trying to make people believe that you are a particular thing:', 'I make no claim to be a brilliant pianist, but I can play a few tunes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35725, 'make no difference', 'to not change or improve a situation:', 'It doesn’t make any difference now what he says – it’s too late for apologies.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35726, 'make no mistake (about it)', 'used to show that you are certain about something:', 'Make no mistake, this decision is going to cause you a lot of problems.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35727, 'make no odds', 'to not be important, or to not change a situation or result:', 'I don''t mind whether you come or not - it makes no odds to me.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35728, 'make noises', 'to show what you think or feel by what you say, without stating it directly:', 'He''s been making noises about taking us all to Rio, but we haven''t heard anything definite.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35729, 'make noises', 'to complain or make trouble:', 'If things start going badly again, our members are sure to make noises.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35730, 'make off', 'to leave quickly, usually in order to escape:', 'The burglars made off before the police arrived.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35731, 'make off with something', 'to steal something:', 'Somebody broke into the shop and made off with several TVs.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35732, 'make peace (with someone)', 'to stop fighting or disagreeing with someone and start living and working happily together:', 'Will they make peace, or fight each other?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35733, 'make peace with something', 'to start to accept something that was previously worrying or annoying you:', 'It''s time to make peace with your body image.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35734, 'make representations/a representation to someone/something', 'to complain officially to a person or organization:', 'We made representations to the boss about the long working hours.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35735, 'make sense', 'to be clear and easy to understand:', 'This last paragraph doesn’t make any sense.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35736, 'make sense', 'Someone who makes sense is reasonable or shows good judgment:', 'Everything he said made sense – I''d definitely vote for him.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35737, 'make short shrift of something', 'to deal with or get rid of something quickly:', 'Williams made short shrift of her opponent, letting her win only two games in the match.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35738, 'make short work of something', 'to finish or deal with something quickly:', 'Well, you certainly made short work of the chocolate cake! There''s none left for your dad.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35739, 'make someone look small', 'to show that someone is wrong in a way that makes them appear stupid', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35740, 'make someone sweat', 'to make someone wait nervously:', 'It seemed that the authorities had delayed the news just to make us sweat.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35741, 'make someone''''s acquaintance', 'fml to meet someone:', 'I’m very pleased to make your acquaintance.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35742, 'make someone''''s blood boil', 'to make someone extremely angry:', 'The way they have treated those people makes my blood boil.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35743, 'make someone''''s blood curdle', 'to fill someone with fear:', 'The strange sound made his blood curdle.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35744, 'make someone''''s blood run cold', 'A sound, sight, or thought that makes your blood run cold frightens you very much:', 'I heard a tapping on the window which made my blood run cold.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35745, 'make someone''''s day', 'to make someone happy:', 'Seeing Adrian again after such a long time really made my day.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35746, 'make someone''''s hair stand on end', 'to make someone very frightened:', 'The thought of jumping out of a plane makes my hair stand on end.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35747, 'make someone''''s heart flutter', 'If someone makes your heart flutter, you find that person very physically attractive and you feel excited when you see or talk to them:', 'James has been making hearts flutter ever since he joined the company.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35748, 'make someone''''s mouth water', 'If the smell or sight of food makes your mouth water, it makes you want to eat it:', 'The smell of that bacon cooking is making my mouth water.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35749, 'make someone''''s skin crawl', 'If someone or something makes your skin crawl, you think they are very unpleasant or frightening:', 'The filthy house made my skin crawl.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35750, 'make someone/something over', 'to improve something or someone by working on or changing various parts:', 'Ed Carey has been chosen to make over the losing football team.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35751, 'make something (all) your own', 'If you make a piece of music, etc. (all) your own, you make it famous by the way you perform it.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35752, 'make something into something', 'to change something into something else:', 'They''ve made the spare room into an office.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35753, 'make something of something/someone', 'to have an impression or an understanding about something:', 'Can you make anything of this information?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35754, 'make something of something', 'to give a particular level of value or importance to something:', 'You should make more of your computer skills on the application form.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35755, 'make something over to someone', 'to give something, such as money or land, to someone so that they legally own it:', 'Just before her death, she had made over $100,000 to her new husband.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35756, 'make something stick', 'to show something bad that has been said about someone is true:', 'They''ve arrested him for fraud but they''ll never make the charges stick.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35757, 'make something up', 'to invent something, such as an excuse or a story, often in order to deceive:', 'I made up an excuse about having to look after the kids.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35758, 'make something up', 'to prepare or arrange something by putting different things together:', 'Could you make up a list of all the things that need to be done?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35759, 'make something up', 'to produce or prepare something from cloth:', 'We could use the rest of the material to make up some curtains.', 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35760, 'make something up', 'If you make up a page, book, or newspaper, you arrange the text and pictures in the form in which they will be printed.', NULL, 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35761, 'make something up', 'If you make up a bed for someone, you put sheets and covers on a bed so that they have a place to sleep in your home.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35762, 'make something up', 'If you make up a fire, you prepare it or put more wood or coal on it when it is burning.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35763, 'make something up', 'to make an amount of something complete or correct:', 'I have £20,000 and I need £25,000 but my parents have promised to make up the difference.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35764, 'make something up', 'to reduce or replace something, usually an amount of time or work, that has been lost:', 'We''re hoping to make up time on the return journey by not stopping at night.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35765, 'make someone/something up', 'to put make-up on someone''''s face, to improve or change its appearance:', 'For the movie, they made him up as an Indian.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35766, 'make up something', 'to form a particular thing, amount, or number as a whole:', 'Car accident victims make up almost a quarter of the hospital''s patients.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35767, 'make up', 'to forgive someone and be friendly with them again after an argument or disagreement:', 'They kissed and made up, as usual.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35768, 'make something up as you go along', 'to invent a story or a tune without thinking before about how it will end', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35769, 'make something/it worth your while', 'to pay someone money to do something:', 'If you can get me the list of names I want, I''ll make it worth your while.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35770, 'make something/someone out', 'to see, hear, or understand something or someone with difficulty:', 'The numbers are too small - I can''t make them out at all.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35771, 'make something out', 'to write all the necessary information on an official document:', 'I made a cheque out for £20 to "Henry''s Stores".', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35772, 'make out something', 'to say, usually falsely, that something is true:', '[ + to infinitive ] He made himself out to be a millionaire.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35773, 'make out', 'to deal with a situation, usually in a successful way:', 'How is Frances making out in her new job?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35774, 'make out', 'to kiss and touch in a sexual way, or to succeed in having sex with someone:', 'Boys at that age are only interested in making out with girls.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35775, 'make sure', 'to take special care to do something:', 'Make sure you’re home by midnight.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35776, 'make sure', 'To make sure also means to find out whether something is really true or real:', 'Make sure he''s honest before you lend him any money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35777, 'make that something', 'infml I want to change what I just said to something else:', 'I’ll have a steak – no, make that an omelet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35778, 'make the first move', 'to be the first to take action:', 'Neither side seems prepared to make the first move towards reaching a peace agreement.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35779, 'make the first move', 'to show that you want to start a romantic or sexual relationship with someone:', 'She''s liked him for a long time, but doesn''t want to make the first move.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35780, 'make the fur fly', 'to cause a bad argument:', 'He set the fur flying by demanding to see proof.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35781, 'make the grade', 'to perform well enough to succeed in something:', 'Marvin wanted to be an actor, but he didn''t make the grade.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35782, 'make the grade (as something)', 'to be good enough to be successful at something:', 'Do you think I will make the grade as a chef?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35783, 'make the most of something', 'to use or enjoy something as much as possible:', 'We’re only in Paris for a day, so let’s make the most of it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35784, 'make the ultimate/supreme sacrifice', 'to die while fighting for a principle', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35785, 'make the world go around/round', 'to be extremely important, so that many ordinary events could not happen without it:', 'Love/Money makes the world go round.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35786, 'make time', 'to make certain you have some time when you are not busy in order to do something you think you should do:', 'It''s important to make time to read to your children.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35787, 'make to do something', 'If you make to do something, you are just going to do it when something interrupts you:', 'I made to leave but she called me back.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35788, 'make toward something/someone', 'to go in the direction of something or someone:', 'He made toward the door, but stopped and turned to face me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35789, 'make towards something/someone', 'to go in the direction of something or someone:', 'He made towards the door, but stopped and turned to face me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35790, 'make tracks', 'to leave somewhere to go home:', 'It''s getting late, Jim - I think we should make tracks.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35791, 'make up for lost time', 'to enjoy an experience as much as possible because you did not have the opportunity to do it earlier in life:', 'I didn''t travel much in my twenties but I''m certainly making up for lost time now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35792, 'make up for something', 'to take the place of something lost or damaged or to compensate for something bad with something good:', 'No amount of money can make up for the death of a child.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35793, 'make up to someone', 'to be too friendly to someone or to praise them in order to get advantages for yourself:', 'Have you seen the disgusting way she makes up to the boss?', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35794, 'make up your mind', 'to decide:', 'I haven''t made up my mind where to go yet.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35795, 'make waves', 'to be very active so that other people notice you, often in a way that intentionally causes trouble:', 'It''s probably not a good idea to start making waves in your first week in a new job.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35796, 'make way for something', 'to provide a space or an opportunity for something else:', 'Some beautiful old buildings were torn down to make way for the new parking garage.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35797, 'make whoopee', 'to have sex', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35798, 'make with something', 'to give, bring, or do something:', 'He pointed a gun and said "Make with the money bags, baby!"', 'phrasal verb', NULL, NULL, 'old-fashioned, slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35799, 'make your flesh crawl/creep', 'to make someone very worried or frightened:', 'I don''t mind spiders but worms make my flesh crawl.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35800, 'make your presence felt', 'to have a strong effect on other people or on a situation:', 'The new police chief has really made his presence felt.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35801, 'make your way', 'to be successful and make progress in your life and work:', 'He will teach you how to build a career and make your way in the world.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35802, 'make yourself at home', 'to relax and make yourself comfortable in someone else''''s home', NULL, 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35803, 'make yourself known', 'to tell someone who you are:', 'Just go to the hotel reception and make yourself known (to the receptionist).', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35804, 'make yourself respectable', 'to put on clothes so that you are in a suitable state to meet someone:', 'Could you wait a minute while I make myself respectable?', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35805, 'make yourself scarce', 'to go away from a difficult situation in order to avoid trouble:', 'Dad''s really angry with you, so you''d better make yourself scarce.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35806, 'make yourself understood', 'to communicate effectively:', 'Since they spoke only Swahili, we used signs and gestures to make ourselves understood.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35807, 'make yourself useful', 'a way of telling someone to start being helpful:', 'Now you''re here, you might as well make yourself useful - there''s a lot of cleaning up to do.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35808, 'make/do the rounds', 'to talk to a lot of people:', 'I''ve made/done the rounds of all the agents, but nobody has any tickets left.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35809, 'make/put a dent in something', 'to reduce an amount of money:', 'The holiday made a big dent in our savings.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35810, 'make/take a note', 'to write something down or remember it carefully:', 'I''ll just take a note of your name and address.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35811, 'make/take soundings', 'to ask questions in order to collect information or opinions:', 'Can you take some discreet soundings to see what her future plans are?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35812, 'man and boy', 'all a man''''s life:', 'From 1910 to 1970 he worked in that factory, man and boy.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35813, 'man cannot live by bread alone', 'used to say that people need not just food, but also poetry, art, music, etc. to live happily', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35814, 'man for man', 'used to compare the strength, abilities, etc. of the people in two groups or teams:', 'Man for man, they were one of the most effective military units in the war.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35815, 'man for man', 'in team sports, used to describe a system in which defending players mark a particular player from the opposing team (= stay close to them to try to stop them getting control of the ball):', 'He cannot be marked man for man because their frontline is switching constantly.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35816, 'man of his word', 'people who do what they say they will do:', 'He is obviously a man of his word, a man of integrity.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35817, 'man of the world', 'someone who has a lot of experience of life and can deal with most situations:', 'They would grow up to be true women of the world, educated and experienced in magnificent ways.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35818, 'man on!', 'a warning shouted to a football player who has the ball to make him realize that an opposing player is behind him', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35819, 'man up', 'used to tell someone that they should deal with something more bravely:', 'You need to man up and admit you were wrong.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35820, 'man''''s best friend', 'a dog', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35821, 'man''''s inhumanity to man', 'the cruel behaviour that people show to each other:', 'Man''s inhumanity to man never fails to shock me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35822, 'man/woman of the people', 'a person, usually involved in politics, who is liked by a lot of ordinary people and seems to understand and like them', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35823, 'manage up', 'to work in a way that makes your manager able to do their work effectively:', 'I''m terrible at managing up. At worst, I''ve seen my bosses as a distraction from getting my job done.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35824, 'manna from heaven', 'help that you get when you need it but are not expecting it', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35825, 'many a time', 'many times:', 'I''ve told you many a time not to ride your bike on the pavement.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35826, 'many a true word is spoken in jest', 'said about humorous remarks that contain serious or true statements', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35827, 'many happy returns (of the day)', 'said to mean "Happy birthday"', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35828, 'many moons ago', 'a long time ago', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35829, 'many''''s the', 'used to show something has happened many times or for long periods of time:', 'Many''s the hour I''ve spent by the phone just waiting in case he called.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35830, 'map something out', 'to plan something in detail:', 'The department has issued a new document mapping out its policies on education.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35831, 'mark someone down as something', 'to consider someone as a particular type of person:', 'I''d marked her down as a Labour Party supporter, but I was completely wrong.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35832, 'mark something down', 'to reduce the price of something, usually in order to encourage people to buy it:', 'Low consumer demand has forced us to mark down a wide range of goods, sometimes by as much as 30 percent.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35833, 'mark something down', 'to write something on a piece of paper in order to make a record of it:', 'I''ve marked down the number of each item sold.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35834, 'mark something out', 'to show the shape or position of something by drawing a line around it:', 'He''d marked out a volleyball court on the beach with a stick.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35835, 'mark something up', 'to increase the price of something:', 'They buy paintings at auctions, mark them up, and then resell them at a vast profit to collectors.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35836, 'mark something up', 'to write notes on something:', 'Someone had marked up the book before I got it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35837, 'mark something/someone off', 'If you mark off things or people that are on a list, you record that you have dealt with them:', 'As I complete each task I mark it off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35838, 'mark something off', 'to separate an area by putting something around it:', 'Police had marked off the area where the body was found.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35839, 'mark time', 'to march in one place without moving forward', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35840, 'mark time', 'to do little while waiting for something that is going to happen:', 'She''s just marking time until she goes off to university.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35841, 'marry beneath you', 'to marry someone people think is not good enough for you because he or she is from a lower social class', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35842, 'marry in haste, repent at leisure', 'This means that if you marry someone without knowing him or her very well, you will later feel sorry that you got married.', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35843, 'marry money', 'to marry a rich person:', 'One way to get rich is to marry money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35844, 'marry someone off', 'to make certain that someone, especially a female member of your family, gets married, or that she marries the person you have chosen:', 'She was married off to the local doctor by the age of 16.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35845, 'marry up (something)', 'If two things marry up or if you marry them up, they match or join together:', 'We need to marry up the names on your list with those on my list and see what the overlap is.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35846, 'mash up something', 'to crush something, especially food:', 'He always mashes up his peas before he eats them.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35847, 'mask up', 'to put on a mask:', 'I mask up to protect myself and others at risk.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35848, 'masquerade as someone/something', 'to pretend or appear to be someone or something:', 'Hooligans masquerading as protesters have once again caused disturbances.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35849, 'massage someone''''s ego', 'to praise someone in order to make that person think they are better than they are', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35850, 'match someone against someone', 'If one team or player is matched against another team or player, they are made to compete against each other:', 'Williams has been matched against Makarova in the semifinal.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35851, 'match something pound for pound', 'to give one pound for every pound given by someone else:', 'The government has promised to match the money raised by the charity pound for pound.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35852, 'match up', 'If two pieces of information match up, they are the same:', 'Their accounts of what happened that evening don''t match up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35853, 'match up', 'If two things match up, they are similar and are designed to connect or to work together:', 'If the teeth on the cogs don''t match up correctly (= if they are not in the correct place), the mechanism will jam.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35854, 'match up', 'to be as good as another thing, person, or experience:', 'There was so much hype beforehand that it would have been difficult for the film to match up to/with our expectations of it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35855, 'match something up', 'If you match up a design or material, you look for something that would look good with it and be similar to it:', 'I''m trying to match up this wallpaper with some suitable curtain material.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35856, 'match something/someone up', 'to find a similarity or connection between two things or people:', 'Can you match up these songs with the bands who sang them?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35857, 'match up to something', 'to be as good as something else:', 'The sequel didn’t match up to the original movie.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35858, 'mate for life', 'If animals mate for life, they keep the same sexual partner for their whole life.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35859, 'max out', 'to do or have as much as possible of something, or too much of something:', 'The air conditioner was maxed out, but it still felt hot in the car.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35860, 'max something out', 'to reach the limit of something, so that nothing more is possible:', 'We maxed out all our credit cards.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35861, 'may I ask', 'used in questions to show disapproval:', 'What, may I ask, was the point of repeating the tests?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35862, 'may the best man/person win!', 'said before a race or competition, meaning that you want the person who is the fastest, strongest, or most skilled to win or succeed', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35863, 'may well', 'If you say that something may well happen, you mean that it is likely to happen:', 'She may well not want to travel alone.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35864, 'may/might as well', 'used to suggest doing something, often when there is nothing better to do:', 'We might as well walk there.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35865, 'mean business', 'to want very much to achieve something', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35866, 'mean the world to someone', 'to be extremely important to someone:', 'Her children mean the world to her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35867, 'mean well', 'to do what you think will be helpful, although by doing it you might cause problems without intending to:', 'I know he means well, but he just gets in the way.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35868, 'measure someone/something against someone/something', 'to judge someone or something by him, her, or it against someone or something else:', 'She measured the shoe against the footprint, but it was smaller.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35869, 'measure something out', 'to weigh or measure a small amount of something from a larger amount of something:', 'Measure out 250 grams of flour and sift it into a large mixing bowl.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35870, 'measure up', 'to be good enough, or as good as someone or something else:', 'She could never measure up to her mother''s expectations.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35871, 'measure someone/something up', 'to discover what size someone or something is by measuring him, her, or it', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35872, 'meat and two veg', 'a traditional British meal of cooked, hot meat with two types of vegetables', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35873, 'meet someone halfway', 'to do some of the things that someone wants you to do, in order to show that you want to reach an agreement or improve your relationship with them', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35874, 'meet someone''''s eye', 'to look at someone directly while they are looking at you:', 'I tried to avoid meeting his eye.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35875, 'meet up', 'to meet another person in order to do something together:', 'They suggested we meet up at Mustafa''s.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35876, 'meet up', 'If roads or paths meet up, they join at a particular place.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35877, 'meet up (with someone)', 'to see and talk to someone after making an arrangement to do so:', 'I''m meeting up with some friends after work.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35878, 'meet with something', 'to experience something, usually something unpleasant:', 'I heard she''d met with an accident.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35879, 'meet with something', 'to cause a particular reaction or result:', 'At the time, the decision was met with a barrage of criticism.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35880, 'meet your Waterloo', 'to be defeated by someone who is too strong for you or by a problem that is too difficult for you', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35881, 'meet your maker', 'to die', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35882, 'meet your match', 'to compete unsuccessfully with someone:', 'He was a good player, but he met his match in Peter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35883, 'mellow out', 'to become more relaxed:', 'My dad has definitely mellowed out as he''s gotten older.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35884, 'melt (away) into something', 'to look so similar to something else all around you, or to be so much a part of it, that people do not see or notice you:', 'The security men just melted into the background until they were needed.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35885, 'melt away', 'to disappear slowly:', 'As the police sirens were heard, the crowd started to melt away.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35886, 'melt away', 'If a strong feeling melts away, you feel it less strongly and it disappears:', 'Her anger melted away when she read the letter.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35887, 'melt in your mouth', '(of food) to be prepared well and taste good:', 'The pie crust just melts in your mouth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35888, 'melt something down', 'to heat a metal object until it turns to liquid, because you want to use the metal rather than the object:', 'They melted down the gold rings and bracelets.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35889, 'memory/mind like a sieve', 'If you have a memory or mind like a sieve, you forget things very easily.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35890, 'men in white coats', 'used to refer to people who come to take someone to a psychiatric hospital:', 'He was in and out of psychiatric hospitals for 10 years, escorted by men in white coats.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35891, 'mend your fences', 'to try to be friendly again with someone after an argument', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35892, 'mend your ways', 'to begin to behave well, having until now behaved badly', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35893, 'merchant of doom/gloom', 'someone who is always saying that bad things are going to happen:', 'With exports rising and unemployment falling, the merchants of gloom are having to revise their opinions of the economy.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35894, 'merry Christmas!', 'said at Christmas to wish people a pleasant Christmas period:', 'Hello, Phoebe. Merry Christmas!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35895, 'mess around', 'to spend time doing various things that are not important, without any particular purpose or plan:', 'They spend their weekends messing around on their boat.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35896, 'mess around', 'to behave in a stupid or annoying way:', 'Stop messing around and listen to me!', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35897, 'mess around with something', 'to use or treat something in a careless or harmful way:', 'I don''t want him coming in here and messing around with our computers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35898, 'mess around (with someone)', 'If a married man or woman messes around with someone, they have a sexual relationship with someone who is not their wife or husband:', 'She found out that her husband was messing around with his secretary.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35899, 'mess someone about/around', 'to treat someone badly:', 'I''m tired of being messed around by my bank.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35900, 'mess something up', 'to make something dirty or untidy:', 'Who''s messed up the bookshelf?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35901, 'mess (something) up', 'to spoil or damage something, or to do something wrong or badly:', 'I messed up my chances of becoming a great singer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35902, 'mess someone up', 'to cause someone to suffer emotional and mental problems:', 'Drugs can really mess you up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35903, 'mess someone up', 'to hit someone repeatedly so that they are badly injured', NULL, 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35904, 'mess with something/someone', 'to use or become involved with something or someone dangerous:', 'You shouldn''t mess with drugs.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35905, 'mess with something', 'to make small changes to something, or to move it to a different place, especially not carefully:', 'He was messing with his bike and then he couldn''t fit the parts back together.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35906, 'mess with someone', 'to treat someone in a bad, rude, or annoying way, or to start an argument with someone:', 'I''ve warned you already, don''t mess with me!', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35907, 'mete something out', 'to give or order a punishment or make someone receive cruel or unfair treatment:', 'In the past, schoolteachers regularly meted out physical punishment to their pupils.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35908, 'might I ask/inquire/know', 'used in questions to show disapproval by being more polite than is expected:', 'And what are you doing in there, might I ask?', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35909, 'might just as well', 'If you might just as well do something, there are no reasons not to do it:', 'For the little extra it''ll cost, we might just as well stay for another night.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35910, 'mike someone up', 'to give someone a microphone to use or to attach a microphone to someone''''s clothing, for example before they appear on television', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35911, 'miles', 'used to say something is much greater or better than something else:', 'Restaurant food is better by miles/miles better than it used to be 20 years ago.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35912, 'miles from anywhere/nowhere', 'a long distance from other houses or a town:', 'They live miles from nowhere, in the middle of the countryside.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35913, 'miles too big, small, expensive, etc.', 'very much bigger, smaller, more expensive, etc. than you would like:', 'This drink is miles too sweet!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35914, 'militate against something', 'to make something less likely to happen or succeed:', 'The complexity and costliness of the judicial system militate against justice for the individual.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35915, 'mill around', 'If a group of people mill around, they move around with no particular purpose or in no particular direction, sometimes while waiting for someone:', 'In the square, people were milling around in the sunshine.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35916, 'mill around/about', '(of a group of people) to move around with no obvious purpose:', 'There were people milling around the entrance to the stadium.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35917, 'mind (you)', 'used when you want to make what you have just said sound less strong:', 'He''s very untidy about the house; mind you, I''m not much better.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35918, 'mind over matter', 'the power of the mind to control and influence the body and the physical world generally:', 'He announced what he called "the ultimate test of mind over matter" - a woman walking over hot coals.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35919, 'mind the store', 'to be responsible for making sure that nothing bad happens, especially during a time of change or when the person who is normally responsible is absent:', 'In the short term, the agreement is intended to reassure consumers that someone is minding the store.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35920, 'mind your own business', 'used to tell someone in a rude way that you do not want them to ask about something private:', '"Where have you been?" "Mind your own business!"', 'idiom', 'C2', NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35921, 'mind your p''''s and q''''s', 'to make an effort to be especially polite in a particular situation:', 'I have to mind my p''s and q''s when I''m with my grandmother.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35922, 'mind/watch your manners', 'to make a special effort to be polite:', 'His mother taught him to always mind his manners with his elders.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35923, 'mine a rich seam of something', 'to take advantage of a strong feeling or quality in a particular situation:', 'Polidori, the right-wing politician, is mining a rich seam of fear and prejudice.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35924, 'minister to someone', 'to give help to or care for someone, for example someone who is ill:', 'formal The priest ministers to his flock (= the people who go to his church).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35925, 'minor in something', 'to study something as your second most important subject in college or a university:', 'I minored in Spanish in college.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35926, 'misery loves company', 'people who are unhappy like to share their troubles with others:', 'We''d both just broken up with our boyfriends, so we decided to go see a movie together – misery loves company.', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35927, 'miss a chance/opportunity', 'to not use an opportunity to do something:', 'She missed the chance of promotion when she turned down the job of assistant manager.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35928, 'miss someone/something out', 'to fail to include someone or something that should be included:', 'You''ve missed out your address on the form.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35929, 'miss out', 'to fail to use an opportunity to enjoy or get an advantage from something:', 'Don''t miss out on the fantastic bargains in our summer sale.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35930, 'miss the boat', 'to lose an opportunity to do something by being slow to act:', 'There were tickets available last week, but he missed the boat by waiting till today to try to buy some.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35931, 'miss the mark', 'to fail to achieve the result that was intended:', 'Her speech missed the mark and failed to generate the public support she had been hoping for.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35932, 'miss the point', 'to not understand something correctly or what is important about it:', 'What you say is true, but you''ve missed the point of my argument.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35933, 'mist (something) over/up', 'If something that you can see through mists over/up, it becomes covered with a thin layer of liquid so that it is more difficult to see through:', 'Open the window when you have a shower to stop the mirror misting over.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35934, 'mist (something) over/up', 'If your eyes mist over/up, they fill with tears.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35935, 'mistake someone/something for someone/something', 'to confuse someone or something with a different person or thing:', 'I often mistake her for her mother on the phone.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35936, 'mix it', 'to fight or argue with people:', 'Don''t take any notice of Sally - she just likes to mix it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35937, 'mix it up', 'to fight or argue with people:', 'She''s ready to mix it up with the other candidates during the debate.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35938, 'mix someone/something up', 'to fail to recognize two people or things correctly by thinking that one person or thing is the other person or thing:', 'People often mix us up because we look so similar.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35939, 'mix someone up', 'to confuse, worry, or upset someone:', 'The directions he gave me mixed me up and I went the wrong way.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35940, 'mix something up', 'to make a group of things untidy or badly organized, or to move them into the wrong order:', 'Don''t mix up the bottles - you''ll have to repeat the experiment if you do.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35941, 'mix your metaphors', 'to combine two or more metaphors, often producing a silly or humorous effect:', 'Mixing his metaphors, he described the problem by saying "We''ve opened up a can of worms here, and now we have to get the genie back in the bottle".', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35942, 'mock something up', 'to make a model of something in order to show people what it will look like or how it will work', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35943, 'model yourself on someone', 'to try to make yourself very similar to someone else:', 'Lots of young singers modelled themselves on Beyoncé.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35944, 'moderation in all things', 'said to advise someone that it is best not to have or do too much or too little of anything', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35945, 'money doesn''''t grow on trees', 'said to warn someone to be careful how much money they spend, because there is only a limited amount:', '"Mum, I''d like a new bike." "I''ll have to think about it - money doesn''t grow on trees, you know!"', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35946, 'money for old rope', 'money you get for doing something very easy:', 'Babysitting is money for old rope if the children don''t wake up.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35947, 'money talks', 'said about people or organizations that are rich, and can therefore get or do what they want', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35948, 'monkey around', 'to behave in a silly and annoying way:', 'The children were bored and started monkeying around.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35949, 'monkey around with sth', 'to touch, change, or treat something in a careless or harmful way:', 'They shouldn''t start monkeying around with the Constitution.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35950, 'moon around', 'to move around or spend time without any clear purpose, especially because you are slightly sad or in love:', 'She was mooning around the house all weekend.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35951, 'moon over someone/something', 'to spend time thinking about someone or something that you love, in a silly way that does not achieve anything:', 'He spends all his time mooning over a girl at school.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35952, 'mop something up', 'to use a piece of cloth or a mop to remove liquid from the surface of something:', 'There''s milk on the floor over there - could you get a cloth and mop it up?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35953, 'mop something up', 'to finish dealing with something:', 'It took a week to mop up the last of the enemy soldiers (= defeat them).', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35954, 'mope around (somewhere)', 'to move from one place to another without any particular purpose or energy, because you are unhappy or disappointed:', 'He was driving me crazy, moping around the house all day.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35955, 'more (...) than you can shake a stick at', 'a lot of:', 'There are more whisky distilleries in this part of Scotland than you can shake a stick at.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35956, 'more and more', 'increasingly, or an increasing number of:', 'It gets more and more difficult to understand what is going on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35957, 'more bang for your buck(s)', 'If you get more bang for your buck(s), you get a better result for the amount of effort or money that you have put into something.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35958, 'more by accident than design', 'because of luck and not because of skill or organization:', 'The play was a success more by accident than design.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35959, 'more by luck than judgment', 'by chance and not because of any special skill:', '"You did amazingly well to get the ball in." "Oh, it was more by luck than judgment."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35960, 'more cowbell', 'an extra quality that will make something or someone better:', 'It was a fairly average show - it needed more cowbell.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35961, 'more haste, less speed', 'said to mean that if you try to do things too quickly, it will take you longer in the end', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35962, 'more like it', 'infmlmore accurate or true:', 'I think he likes her – or maybe he''s madly in love with her is more like it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35963, 'more money than sense', 'used to talk about people spending a lot of money on something that you think is unnecessary:', 'He''s just a man who''s got more money than sense and no idea what to do with his life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35964, 'more often than not', 'usually:', 'More often than not when I make the effort to visit her, I wonder why I even bothered.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35965, 'more or less', 'mostly:', 'The project was more or less a success.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35966, 'more or less', 'approximately:', 'It''s 500 kilos, more or less.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35967, 'more or less', 'almost:', 'He more or less admitted he''d done it.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35968, 'more power to you!', 'an expression of praise or admiration for someone''''s success or brave actions:', '"I''ve decided to quit my job and set up my own business." "Well, good for you. More power to you!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35969, 'more power to your elbow!', 'an expression of praise or admiration for someone''''s success or brave actions:', '"I''ve decided to quit my job and set up my own business." "Well, good for you. More power to your elbow!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35970, 'more than', 'very:', 'It''s more than likely that there''s oil here under the ground.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35971, 'more trouble than it''''s worth', 'If something is more trouble than it''''s worth or is not worth the trouble, it is not important or useful enough to make an effort doing it:', 'It''s more trouble than it''s worth to take it back to the shop and ask for a replacement.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35972, 'more/greater/bigger etc. than the sum of its parts', 'used to say that a particular thing, when considered as a whole, is more important, better, etc. than you would expect from looking at the individual parts that make it up:', 'He has built a global operation that is clearly bigger than the sum of its parts.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35973, 'morning, noon, and night', 'all the time:', 'Our neighbour''s baby cries morning, noon, and night.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35974, 'mortification of the flesh', 'punishment of yourself, especially by hitting your body with a whip, usually done for religious reasons', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35975, 'motherhood and apple pie', 'used to represent things that most Americans consider to be very good and important:', 'For some Americans, low taxes and small government are as sacred as motherhood and apple pie.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35976, 'mount up', 'to gradually increase in number or amount:', 'It isn''t a good idea to let bills mount up.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35977, 'mouse over something', 'to use a computer mouse to move the cursor over a particular part of the screen:', 'The pictures become bigger when you mouse over them.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35978, 'mouth off', 'to express your opinions or complain, esp. loudly and in a way that shows no consideration or respect:', 'Clark was mouthing off in the locker room after we lost, and he started a fight.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35979, 'mouth off (about something)', 'to express your opinions too loudly and publicly:', 'I had to listen to Michael mouthing off about the government all through lunch.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35980, 'mouth off (to/at someone)', 'to speak in a rude or offensive way to someone:', 'She''s a typical teenager, coming home late at night and mouthing off to her parents.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35981, 'move heaven and earth', 'to do everything you can to achieve something:', 'He''ll move heaven and earth to get it done on time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35982, 'move in on something/someone', 'If you move in on a person or place, you come close or closer to them in order to attack or take control of them:', 'Government troops are moving in on the rebel stronghold.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35983, 'move it!', 'used to tell someone to hurry:', 'Come on, Phil, move it!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35984, 'move off something/on (to something)', 'to change from one subject to another when talking or writing:', 'Let''s move off this subject now, all right?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35985, 'move on', 'to leave the place where you are staying and go somewhere else:', 'I''ve lived in this town long enough - it''s time to move on.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35986, 'move on', 'to start a new activity:', 'I''d done the same job for years and felt it was time to move on.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35987, 'move on', 'to accept that a situation has changed and be ready to deal with new experiences:', 'Since he and his girlfriend broke up, he''s been finding it difficult to move on.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35988, 'move on to bigger/better things', 'to get a better job or improve your life in some way:', 'I hear you''re leaving and moving on to better things.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35989, 'move out', 'to stop living in a particular home:', 'Her landlord has given her a week to move out.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35990, 'move someone/something in', 'If the police, army, or any group of people in authority move in, or if someone moves them in, they take control or attack, in order to deal with a difficult or dangerous situation:', 'When a company goes out of business, officials usually move in to take control.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35991, 'move the chains', 'to achieve a first down (= the first of four chances that a team on offence is given to advance the ball toward the opponent''''s goal) in American football :', '"He is the kind of running back who can move the chains and pick up a lot of yards when we need them," the coach said.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35992, 'move the chains', 'to advance to the next stage of a project or situation:', 'Once we have approved the design of the new library, we can move the chains and start seeking bids from contractors.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35993, 'move the goalposts', 'to change the rules while someone is trying to do something in order to make it more difficult for them:', 'We''d almost signed the contract when the other guys moved the goalposts and said they wanted more money.', 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35994, 'move to/towards sth', 'to change from a particular system, activity, etc. to another:', 'Businesses, consumers, and governments will have to make big changes in order to move to a low-carbon economy.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35995, 'move up', 'to increase in value, number, or amount:', 'Share prices move up and down depending on market conditions.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35996, 'move up', 'to get a more important job in a company or organization:', 'move up to sth He gave his first interview since moving up to the role of chairman.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35997, 'move with the times', 'to change and become more modern, because attitudes or fashions are changing:', 'We have to move with the times and market our products more aggressively.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35998, 'move/go in for the kill', 'to prepare to defeat someone in an argument or competition when that person is already in a weak position:', 'He asked her a couple of difficult questions and then went in for the kill.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (35999, 'move/shift your arse!', 'a rude phrase used to tell someone to hurry up or to get out of your way', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36000, 'mow someone down', 'to kill people, usually in large numbers, by shooting them or driving a vehicle into them:', 'Three shoppers were mown down this afternoon when a drunken driver lost control of his car.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36001, 'much as', 'although:', 'Much as I would like to help you, I''m simply too busy at the moment.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36002, 'much less', 'and certainly not:', 'Tony can barely boil an egg, much less cook dinner.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36003, 'much to someone''''s delight, dismay, disappointment, surprise, etc.', 'used to say that someone is very surprised, happy, unhappy, etc. about something:', 'Much to her surprise, there were two police cars parked down the street.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36004, 'much/still less', 'used to make a negative statement stronger:', 'At the age of 14 I had never even been on a train, much less an aircraft.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36005, 'muck (something) out', 'to clean a place where a large animal lives, especially a stable, by removing the waste products and old straw:', 'She''d spent all morning mucking out the horses.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36006, 'muck in', 'to share the work that needs to be done:', 'She doesn''t mind mucking in with the rest of us when there''s work to be done.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36007, 'muck someone/something about/around', 'to behave in a silly way, or to treat someone or something in a careless way:', 'Stop mucking about with those ornaments, you''ll break something!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36008, 'muck something up', 'to spoil something completely, or do something very badly:', 'I really prepared for the interview because I didn''t want to muck it up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36009, 'mud sticks', 'said to mean that people are likely to believe something bad that is said about someone, even if it is not true', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36010, 'muddle along', 'to continue doing something with no clear purpose or plan:', 'Decide what you want in life - don''t just muddle along.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36011, 'muddle something up', 'to arrange things in the wrong order:', 'I''ve arranged the books alphabetically so don''t muddle them up.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36012, 'muddle someone/something up', 'to think that a person or thing is someone or something else because the two people or things are very similar:', 'I often muddle up Richard with his brother.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36013, 'muddle through', 'to manage to do something although you are not organized and do not know how to do it:', 'Sorry, but I can''t help you - you''ll just have to muddle through on your own.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36014, 'muddy the waters', 'to make a situation more confused and less easy to understand or deal with', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36015, 'mug (something) up', 'to study a subject quickly before taking an exam:', 'I need to mug up (on) my history before tomorrow''s exam.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36016, 'mug someone off', 'to make someone appear stupid, especially by deceiving them or treating them badly in a relationship:', 'Rebecca slammed Luke for mugging her off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36017, 'mull something over', 'to think carefully about something for a long time:', 'I need a few days to mull things over before I decide if I''m taking the job.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36018, 'mum''''s the word', 'said when you tell someone, or agree with someone, to keep something a secret:', '"I''m not telling people generally yet." "OK, mum''s the word!"', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36019, 'murky/uncharted waters', 'a situation that is not well known and may be dangerous:', 'In the last two chapters of the book, she enters the murky waters of male sexuality.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36020, 'muscle in', 'to force your way into a situation and make certain you are included, although you are not wanted:', 'I hear Mark is muscling in on our meeting.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36021, 'music to your ears', 'something you are pleased to hear about:', 'When she said they would make a profit, it was music to Richard’s ears.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36022, 'muster something up', 'If you muster up a feeling of courage or energy, you try hard to find that quality in yourself because you need it in order to do something:', '[ + to infinitive ] She finally mustered up the courage to ask him for more money.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36023, 'muster your forces', 'to make great arrangements and efforts, usually to prepare for an attack or event:', 'The Welsh National Opera has mustered its forces to mount its second production of Tristan in only 14 years.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36024, 'mustn''''t grumble', 'something you say to mean that your life is not bad and that you should not complain about it:', '"How''s it going then, Mike?" "Oh, not too bad. Mustn''t grumble."', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36025, 'mutton dressed as lamb', 'a way of describing an older woman who is dressed in a style that is more suitable for a younger woman:', 'Do you think this dress is too young-looking for me? - I don''t want to look like mutton dressed as lamb.', 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36026, 'my (dear) boy', 'a friendly way of talking to a man:', 'Look here, my boy, this simply won''t do.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36027, 'my arse!', 'a rude phrase used to emphasize that you do not believe what someone has just said:', '"She said she had food poisoning." "Food poisoning, my arse! She just drank too much last night."', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36028, 'my ass!', 'a rude phrase used to emphasize that you do not believe or accept what someone has said:', '"Public holiday" my ass! I still have to work like any other day.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36029, 'my bad', 'used for saying that you accept that you are wrong or that something is your fault:', '"You brought the wrong book." "Okay, my bad. I''ll go get it."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36030, 'my foot', 'used to mean that you do not believe what another person has just told you:', '"He says his car isn''t working." "Not working my foot. He''s just too lazy to come."', 'idiom', NULL, NULL, 'informal, old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36031, 'my heart bleeds for someone', 'used to say that you feel great sadness for someone. This phrase is often used humorously to mean the opposite:', 'humorous John complains he only has two cars - my heart bleeds for him (= I certainly do not feel sadness about that)!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36032, 'my lips are sealed', 'said when you are promising to keep a secret:', '"Oh and please don''t tell him you saw me here." "Don''t worry. My lips are sealed."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36033, 'my point exactly', 'said in answer to something that someone has just said when you believe it yourself, or when you have said it yourself earlier:', '"So even if we got the funding, we still couldn''t get the project started." "My point exactly."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36034, 'my sweet', 'a way of talking to someone you love', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36035, 'my, (oh, my)', 'used to express surprise or pleasure:', 'My, this food is wonderful.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36036, 'naff off', 'used to rudely tell someone to go away because they are annoying you', NULL, 'phrasal verb', NULL, NULL, 'slang, old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36037, 'nag (away) at someone', 'If doubts or worries nag (away) at you, you think about them all the time:', 'The same thought has been nagging away at me since last week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36038, 'nail a lie', 'to prove that something really is a lie', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36039, 'nail someone down', 'to make someone give you exact details or a firm decision about something:', 'They nailed him down to a specific time and place.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36040, 'nail something down', 'If you nail down an arrangement or decision, you decide and agree to the details of it:', 'After a five-hour meeting, we finally nailed down a deal.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36041, 'nail something down', 'to understand something completely, or to describe something correctly:', 'We haven''t been able to nail down the cause of the fire yet.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36042, 'nail something on', 'to make something very certain or definite:', 'Australia seem likely to get to the semis, and a win today would nail it on.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36043, 'nail your colours to the mast', 'to make it obvious what your opinions or plans are', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36044, 'nailing Jell-O to the wall', 'trying to give exact details for something that it is not possible to know about exactly:', 'Writing the history of this period is like nailing Jell-O to the wall.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36045, 'nailing jelly to the wall', 'trying to give exact details for something that it is not possible to know about exactly:', 'Writing the history of this period is like nailing jelly to the wall.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36046, 'name and shame', 'to publicly say that a person, group, or business has done something wrong:', 'The report names and shames companies that are not doing enough to fight industrial pollution.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36047, 'name names', 'to tell someone the names of people involved in something, especially an unpleasant, secret, or illegal activity:', 'If people are going to accuse their colleagues of racist acts, they should name names.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36048, 'name someone/something after someone/something', 'to give someone or something the same name as another person or thing:', 'Paul was named after his grandfather.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36049, 'name the day', 'to decide the date on which you are going to get married:', 'When are you going to name the day?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36050, 'name your poison', 'used to ask what type of alcoholic drink someone would like', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36051, 'narrow something down', 'to make a number or list of things smaller, by removing the things that are least important, necessary, or suitable:', 'We narrowed the list of candidates down from ten to three.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36052, 'near at hand', 'If something is near at hand, it is near enough to you for you to reach it:', 'I like to have my books near at hand when I''m working.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36053, 'near the knuckle', 'about sex and therefore likely to offend people:', 'Some of his jokes were a bit near the knuckle.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36054, 'nearly/almost fall off your chair', 'to be extremely surprised:', 'She nearly fell off her chair when she heard the news.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36055, 'nearly/almost have a heart attack', 'to be extremely surprised or shocked:', 'I almost had a heart attack when I found out how much the meal cost.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36056, 'necessity is the mother of invention', 'an expression that means that if you really need to do something, you will think of a way of doing it', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36057, 'neck and neck', 'If two competitors are neck and neck, they are level with each other and have an equal chance of winning.', NULL, 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36058, 'need I say', 'obviously:', 'Need I say, I''m extremely sorry to hear the news about your father.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36059, 'need I say more?', 'said after a statement when you expect that someone can guess the result of what you have just said:', 'Tom was doing the cooking - need I say more?', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36060, 'need something like you need a hole in the head', 'to not need or want something at all:', 'Extra work? I need that like I need a hole in the head.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36061, 'need you ask!', 'used to say that the person asking you something already knows the answer, because it is expected:', '"Did he upset a lot of people at the meeting?" "Need you ask!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36062, 'need your head examined', 'If you tell someone they need their head examined, you think that that person is crazy because they have done something stupid or strange:', 'You need your head examined if you''re willing to spend that much on a pair of jeans.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36063, 'needless to say', 'as you would expect; added to, or used to introduce, a remark giving information that is expected and not surprising:', 'Needless to say, he''ll be off work for a while.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36064, 'neither here nor there', 'not important, or not connected with the subject being discussed:', 'Her age is neither here nor there – the real question is, can she do the job?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36065, 'net out', 'to be or produce a particular amount of money after tax and other costs have been paid:', 'The facility showed a gross loss of $2.8m, which, when set against investors'' deposits of £1.5m, netted out at $1.36m.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36066, 'net out', 'to be or have a particular amount at the end of a process:', 'We will net out with several hundred additional jobs over two years.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36067, 'net sth out', 'to subtract a cost, etc. from an amount of money:', 'The company has suffered pressure from higher raw material costs and changes in a number of its markets. When these are netted out, earnings will stabilise.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36068, 'net sth down', 'to reduce an amount by subtracting tax and other costs:', 'In most cases, the interest rate paid will be the tax-free rate netted down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36069, 'never fear', 'do not worry:', 'Never fear, I''ll take good care of him.', 'idiom', NULL, NULL, 'old use, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36070, 'never hear the end of it', 'to have to listen for a long time to embarrassing or annoying talk:', 'If Mary gets that promotion, we’ll never hear the end of it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36071, 'never live something down', 'to be unable to stop feeling embarrassed about something you have done:', 'I wish I''d never opened my mouth in the meeting - I''m never going to live it down!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36072, 'never look a gift horse in the mouth', 'said to advise someone not to refuse something good that is being offered', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36073, 'never look back', 'to continue to be successful after doing something with a good result:', 'She never looked back after that first exhibition.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36074, 'never mind', 'used to tell someone not to worry about something because it is not important:', '"I''m sorry I lost that wallet you gave me." "Never mind, I can easily buy you another one."', 'idiom', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36075, 'never mind', 'used as a way of emphasizing that, although a particular thing is true, the one you have just mentioned is more important or interesting:', 'This is one of the best restaurants in the Northeast, never mind Boston.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36076, 'never mind that', 'despite the fact that:', 'He''s going on holiday for the third time this year, never mind that he has hardly any money left.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36077, 'never put off until tomorrow what you can do today', 'said to emphasize that you should not delay doing something if you can do it immediately', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36078, 'never say die', 'said to encourage people to keep trying', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36079, 'never the twain shall meet', 'said when two things or people are completely different, unsuitable for each other, or are unable to agree', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36080, 'new/fresh blood', 'people who join an organization and who can provide new ideas and energy:', 'The company has brought in some new blood in an effort to revive its fortunes.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36081, 'news to someone', 'to be very surprising to someone:', 'She’s expecting a baby? That’s news to me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36082, 'next door but one', 'not in the closest house, building, room, or place but in the one that is next to it:', 'Her sister lives next door but one to a famous singer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36083, 'nibble (away) at something', 'to slowly reduce something:', 'Even when inflation is low, it nibbles away at people''s savings, reducing their value considerably over several years.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36084, 'nice one!', 'something that you say when you have just heard that someone has done something you think is good:', '"Graham''s brought some champagne along to mark the occasion." "Oh, nice one, Graham!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36085, 'nice work if you can get it', 'something you say about an easy way of earning money that you would like to do if you could:', 'She got one million dollars for appearing on television for five minutes - (that''s) nice work if you can get it!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36086, 'night after night', 'every night:', 'The howling of wild animals kept him awake night after night.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36087, 'night after night', 'every evening:', 'She stayed in night after night, waiting for him to call.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36088, 'night and day', 'all the time:', 'They''ve worked night and day to publicize their campaign.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36089, 'nine times out of ten', 'almost always:', 'Nine times out of ten, you can fix it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36090, 'nineteen/ten to the dozen', 'If you are talking nineteen/ten to the dozen, you are talking very quickly and without stopping.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36091, 'ninety-nine times out of a hundred', 'almost always:', 'Ninety-nine times out of a hundred everything''s fine, but sometimes we have problems.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36092, 'nip something in the bud', 'to stop something before it has an opportunity to become established:', 'Many serious illnesses can be nipped in the bud if they are detected early enough.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36093, 'no big deal', 'infmlnot important:', 'I’d like to work out today, but if I can’t it’s no big deal.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36094, 'no biggie', 'used to say that something is not a serious problem:', 'Because the sunglasses are cheap, losing a pair is no biggie.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36095, 'no dice', 'something that people say when you may not or cannot do something:', 'I asked if we could go to the party, but Mom said no dice.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36096, 'no doubt', 'certainly:', 'He will no doubt tell you all about his vacation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36097, 'no end', 'very much:', 'It would please Granny no end if you wrote to her occasionally.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36098, 'no end of something', 'a lot of:', 'If you don''t want the job, there''s no end of people willing to take your place.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36099, 'no expense is spared', 'If no expense is spared in arranging something, a lot of money is spent to make it extremely good:', 'No expense was spared in making the guests feel comfortable.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36100, 'no fear!', 'certainly not:', '"Are you coming to the concert?" "No fear!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36101, 'no fewer than', 'used to show that you consider a number to be surprisingly large:', 'No fewer than five hundred delegates attended the conference.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36102, 'no flies on someone', 'If you say there are no flies on someone, you mean that they cannot easily be deceived.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36103, 'no go', 'not allowed or not acceptable:', 'Shorts are no go here – you have to wear long pants and shoes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36104, 'no great shakes', 'not very good:', 'I''m afraid I am no great shakes as a cook/at cooking!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36105, 'no hard feelings', 'no feeling of being upset:', '"I''m really sorry." "Don''t worry – No hard feelings."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36106, 'no harm no foul', 'used for saying that no damage has been done by someone''''s mistake :', 'It was a joke, the joke went wrong, he apologized, so no harm no foul.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36107, 'no ifs or buts', 'something that you say to a child to stop them arguing with you when you want them to do something:', 'I want no ifs or buts - just get on and tidy your room now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36108, 'no ifs, ands, or buts', 'something that you say to a child to stop any argument when you want him or her to do something:', 'I want no ifs, ands, or buts - just finish eating your food now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36109, 'no kidding', 'really or honestly:', 'No kidding, there were about 200 people at the party.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36110, 'no laughing matter', 'very serious:', 'Being late for a job interview is no laughing matter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36111, 'no less', 'used to show the importance of someone or something:', 'Who should arrive at the party but the prime minister, no less!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36112, 'no less than', 'used to show your surprise at a large number:', 'There were no less than a thousand people there buying tickets.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36113, 'no longer', 'in the past but not now:', 'This building is no longer used.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36114, 'no matter', 'it is not a problem:', '"I don''t have that form with me." "No matter - here''s another."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36115, 'no matter what, when, why, etc.', 'used to emphasize that something is always true, or that someone must do something:', 'I never seem to lose any weight, no matter how hard I try.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36116, 'no mean achievement/feat', 'a great achievement:', 'Getting the job finished on time was no mean achievement.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36117, 'no mean something', 'used to say a person is very good at a certain activity:', 'He''s no mean cook.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36118, 'no more Mr Nice Guy', 'something that is said when someone has decided to stop thinking about the wishes and feelings of other people:', 'I''ve had enough of people taking advantage of me. From now on it''s no more Mr Nice Guy.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36119, 'no news is good news', 'said to make someone feel less worried when they have not received information about someone or something, because if something bad had happened, they would have been told about it:', 'We haven''t heard anything from the hospital today, but I suppose no news is good news.', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36120, 'no prizes for guessing something', 'something you say when it is very easy to guess something:', 'No prizes for guessing where Daniel is.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36121, 'no problem', 'said to show that you will or can do what someone has asked you to:', '"Can you get me to the station by 11.30?" "No problem."', 'idiom', 'A2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36122, 'no problem', 'used as a friendly answer when someone thanks you for something you have done:', '"Thanks for the lift." "No problem."', 'idiom', 'A2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36123, 'no room for something', 'If you say there is no room for a feeling or type of behaviour, you mean it is not acceptable:', 'In a small company like this, there is no room for laziness.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36124, 'no shit!', 'an expression of surprise, often used as a joke when someone has told you something that is very obvious:', '"This is hard work!" "No shit!"', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36125, 'no sir', 'certainly not:', 'I''m not going to ride the subway, no sir!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36126, 'no something to speak of', 'not enough of something to make it worth talking about:', 'There was no snow to speak of this winter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36127, 'no sooner ... than', 'used to show that one thing happens immediately after another thing:', 'No sooner had I started mowing the lawn than it started raining.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36128, 'no sooner said than done', 'used to say that you will do something immediately', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36129, 'no such luck', 'used when you are disappointed that something that you hoped for did not happen :', 'I was rather hoping it would rain today and I wouldn''t have to go for a walk, but no such luck.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36130, 'no sweat', 'If you say that something is no sweat, you mean that it will not be difficult or cause problems:', '"Can you fix my car for me?" "No sweat!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36131, 'no thanks to someone', 'despite:', 'It''s no thanks to you that I got there on time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36132, 'no way', 'used to tell someone that something is impossible:', 'I''m sorry but there''s no way we can help you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36133, 'no way', 'used to say no in a forceful way:', '"Come on, let me borrow your bike." "No way!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36134, 'no way', 'used to express surprise:', 'When someone tells him something interesting, he says, "No way!" as if he is a teen.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36135, 'no wonder', 'it is not surprising:', 'No wonder the children are excited - this is the first time they''ve been abroad.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36136, 'no/not enough room to swing a cat', 'said about a place or space that is very small', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36137, 'nod off', 'to begin sleeping, especially not intentionally:', 'After our busy day, we both sat and nodded off in front of the TV.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36138, 'none but', 'only:', 'None but a dedicated scientist would want to read such a detailed report.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36139, 'none other than someone/something', 'said when you want to show that someone or something is a surprising or exciting choice or example:', 'The first speech was given by none other than Clint Eastwood.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36140, 'none the wiser', 'to not understand something:', 'I read the computer manual, but I’m still none the wiser.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36141, 'none the wiser', 'To be none the wiser also means to not be aware of something:', 'The health department gave the restaurant a warning, but the customers were none the wiser.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36142, 'none the worse (for something)', 'not damaged or harmed despite something:', 'It was cold and windy during the parade but we were none the worse for the weather.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36143, 'none the worse, better, richer, etc.', 'not any worse, better, richer, etc. than before:', 'Luckily, the horse seemed none the worse for his fall.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36144, 'none to speak of', 'very little of something:', '"Did you get much rain while you were in Singapore?" "None to speak of."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36145, 'none too', 'not very:', 'He seemed none too happy/pleased at the prospect of meeting the family.', 'idiom', 'C2', NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36146, 'nooks and crannies', 'small spaces in something or parts of something that are difficult to reach:', 'These fish like to hang out under coral heads, ledges, or in other nooks and crannies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36147, 'nooks and crannies', 'the parts of something that are hidden or difficult to find:', 'There''s lots of great information hidden in the nooks and crannies of our site.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36148, 'north of something', 'used to say that an amount is more than the stated amount:', 'The share price is expected to rise north of $20.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36149, 'nose ahead', 'to get into a position that is slightly in front of someone or something else:', 'The company has nosed ahead of its closest rivals, claiming 33% market share.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36150, 'nose in the air', 'used to describe the way someone behaves when they think they are better than other people and do not want to speak to them:', 'She walked past me with her nose in the air.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36151, 'nose something out', 'to discover something by searching carefully:', 'He soon nosed out the details of the accident by talking to people and making some phone calls.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36152, 'nose up', 'to increase slowly or by a small amount:', 'Savings rates have been nosing up during the past few months.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36153, 'not (do something) for anything (in the world)', 'infml to not do something under any conditions:', 'It was a fantastic party – I wouldn’t have missed it for anything.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36154, 'not (too) bad', 'fairly good or satisfactory:', '"How are things?" "Not too bad, thanks."', 'idiom', 'A2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36155, 'not a bit of it', 'said when a situation or event is very different from what you expected:', 'I thought he would be sorry, but not a bit of it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36156, 'not a chance', 'there is no possibility:', '"Do you think I could pass for a 21-year-old?" "Not a chance!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36157, 'not a dicky bird', 'nothing at all:', 'We haven''t heard a dicky bird from (= spoken to or received a letter from) Riza recently.', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36158, 'not a dry eye in the house', 'used to mean that all the people at a particular place felt very emotional about what they had seen or heard and many of them were crying', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36159, 'not a hair out of place', 'If someone does not have a hair out of place, their appearance is very neat:', 'She was as immaculate as ever - not a hair out of place.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36160, 'not a happy camper', 'infmlvery annoyed or upset:', 'The dog is sick, Jessie sprained her ankle, and the car won’t start – I am not a happy camper!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36161, 'not a hundred percent', 'not feeling completely well:', 'I''m better than I was, but I''m still not a hundred percent.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36162, 'not a moment too soon', 'used to say that something happened when it was almost too late:', 'Help arrived - and not a moment too soon.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36163, 'not a red cent', 'no money at all:', 'It turns out his paintings aren''t worth a red cent.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36164, 'not a sausage', 'nothing:', '"Did you find anything out?" "No, not a sausage."', 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36165, 'not add up', 'If a situation does not add up, there is no reasonable or likely explanation for it:', 'Why would she disappear the day before her holiday? It just doesn''t add up.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36166, 'not agree with someone', 'If a type of food or drink does not agree with you, it makes you feel slightly ill:', 'Those onions I ate didn''t agree with me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36167, 'not all it''''s cracked up to be', 'to not be as good as people have said:', 'This software isn’t all it''s cracked up to be.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36168, 'not all roses', 'If a situation is not all roses, there are unpleasant things to deal with as well as the pleasant ones:', 'Being in a relationship is not all roses, you know.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36169, 'not all that', 'not very:', 'I''m not all that excited about going camping.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36170, 'not amount to much', 'to not become successful or important:', 'He’s lazy, and he’ll never amount to anything.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36171, 'not anywhere near', 'very much less:', 'He isn''t anywhere near as popular as he used to be.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36172, 'not anywhere to be found', 'impossible to see or find:', 'We searched the house, but it wasn''t anywhere to be found.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36173, 'not at all', 'used as a polite reply after someone has thanked you:', '"Thanks for helping." "Not at all."', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36174, 'not at all', 'used to say "no" or "not" strongly:', '"I hope it wasn''t too much hassle for you." "No, not at all."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36175, 'not at any price', 'used to say that you would never do something:', 'I wouldn''t invite her again at any price.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36176, 'not bad', 'very good:', 'He was best in his age group - not bad, eh?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36177, 'not bat an eye/eyelash', 'to show no sign of surprise or worry when something unexpected happens:', 'She told him she''d spent all her savings but he didn''t bat an eye.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36178, 'not bat an eyelid', 'to show no sign of surprise or worry when something unexpected happens:', 'She told him she''d spent all her savings but he didn''t bat an eyelid.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36179, 'not be a happy camper', 'to be annoyed about a situation:', 'Her computer crashed an hour ago and she''s lost a morning''s work - she''s not a happy camper at the moment.', 'idiom', NULL, NULL, 'informal humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36180, 'not be a patch on something', 'to be much less good than something:', 'This new washing machine isn''t a patch on our old one.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36181, 'not be a pretty sight', 'to be ugly or unpleasant to look at:', 'I can tell you, first thing in the morning he''s not a pretty sight.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36182, 'not be all fun and games', 'If an activity is not all fun and games, parts of it are difficult or unpleasant:', 'It''s not all fun and games being a tour guide.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36183, 'not be as black as you are painted', 'an old-fashioned phrase used to say that you are not as bad as people say you are, which may be considered offensive because it suggests that it is bad to have dark skin', NULL, 'idiom', NULL, NULL, 'old-fashioned, offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36184, 'not be beyond the wit of man/someone', 'to be possible to achieve:', 'It shouldn''t be beyond the wit of man to arrange for them both to be there at the same time.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36185, 'not be born yesterday', 'to not be stupid or easy to deceive:', 'You don''t fool me - I wasn''t born yesterday.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36186, 'not be carved/etched in stone', 'to not be fixed and able to be changed:', 'These are just a few ideas - nothing is carved in stone yet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36187, 'not be cut out for something', 'to not be the right type of person for something:', 'I''m not cut out for an office job.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36188, 'not be in someone''''s vocabulary', 'You say that a particular quality is not in your vocabulary if you never show it or experience it:', 'Did you say "tact"? The word isn''t in his vocabulary!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36189, 'not be in the business of something', 'If a person or organization is not in the business of doing something considered wrong, they do not normally do it:', 'The intelligence agency is not in the business of routinely monitoring the activities of law-abiding citizens.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36190, 'not be in the same league', 'to be not as good as someone or something else:', 'Her latest movie is quite watchable but it''s not in the same league as her first two epics.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36191, 'not be just a pretty face', 'If someone is not just a pretty face, they are not only attractive but also intelligent:', '"How did you know that?" "Well, I''m not just a pretty face, you know."', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36192, 'not be on speaking terms', 'If you are not on speaking terms with someone, you refuse to speak to them because you are angry with them:', 'They had an argument last night and now they''re not on speaking terms (with each other).', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36193, 'not be set/carved in stone', 'to be able to be changed:', 'These are just a few ideas - nothing is set in stone yet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36194, 'not be short of a bob or two', 'to be rich:', 'Did you see his car? He''s not short of a bob or two!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36195, 'not be someone''''s cup of tea', 'If something is not your cup of tea, it is not the type of thing that you like:', 'Thanks for inviting me, but ballet isn''t really my cup of tea.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36196, 'not be someone''''s day', 'If it is not your day, you are having a difficult or unpleasant day:', 'This really isn''t my day - my wallet was stolen and now I''ve lost my car keys.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36197, 'not be the end of the world', 'If something is not the end of the world, it will not cause very serious problems:', 'I''m really hoping to win, but it won''t be the end of the world if I don''t.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36198, 'not be the marrying kind', 'If a man is not the marrying kind, he does not want to be married. People sometimes use this phrase to mean that the man is gay.', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36199, 'not be thinking straight', 'to not be thinking clearly or using good judgment:', 'I''m sorry, that was a stupid thing to do - I wasn''t thinking straight.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36200, 'not be up to much', 'to not be of good quality:', 'The food wasn''t up to much.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36201, 'not believe your eyes', 'to be very surprised:', 'I could not believe my eyes when I saw the garden in full bloom.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36202, 'not believe your eyes/ears', 'to be so surprised by what you see or hear that you think you are imagining it:', 'I couldn''t believe my ears when she said they were getting divorced.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36203, 'not believe your luck', 'to be very surprised and very pleased', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36204, 'not blink', 'to not show any shock or surprise:', 'When he was told I was expecting twins, Harry didn''t even blink.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36205, 'not break your stride', 'to not stop walking or running at the same speed:', 'Without pausing for breath or breaking her stride, she pushed open the door of his private office.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36206, 'not bring yourself to do something', 'to not be able to force yourself to do something that you think is unpleasant:', 'I just couldn''t bring myself to talk to him about it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36207, 'not by a long shot', 'not in any way:', 'It wasn''t as good as his first book - not by a long shot.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36208, 'not by any manner of means', 'not in any way:', 'I''m not satisfied with his excuse - not by any manner of means.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36209, 'not by any stretch of the imagination', 'even if you try, it is still difficult to accept:', 'By no stretch of the imagination could you think of her as a real artist.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36210, 'not care for someone/something', 'to not like something or someone:', 'I have to say I don''t much care for modern music.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36211, 'not care/give a fig', 'to not be at all worried by or interested in something:', 'They can say what they like. I don''t give a fig.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36212, 'not care/give a sod', 'to not be worried about other people''''s opinions or actions:', 'I''m leaving and I don''t give a sod (about) what Margaret thinks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36213, 'not care/give tuppence', 'to not care about something or someone in any way', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36214, 'not care/give two hoots', 'to not care about something or someone:', 'I don''t give two hoots what she thinks.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36215, 'not come cheap', 'If you say that something does not come cheap, you mean that it is of good quality and is therefore expensive:', 'If you want a qualified accountant, their services don''t come cheap.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36216, 'not content with something/doing something', 'in addition to something wrong or unpleasant you have done:', 'Not content with having upset my parents, he then insulted my sister!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36217, 'not cricket', 'If behaviour is not cricket, it is not fair, honest or moral:', 'It''s just not cricket to lie to a friend.', 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36218, 'not cut it', 'to not be able to deal with problems or difficulties satisfactorily:', 'We were playing against a more experienced team, and we just couldn''t cut it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36219, 'not darken someone''''s door', 'used to tell someone to never come back to a place:', 'Never darken my door again!', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36220, 'not do someone any favors', 'to do something that is likely to have a bad effect on you or on another person:', 'You''re not well, and you''re not doing yourself any favors by taking on extra work.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36221, 'not do someone any favours', 'to do something that is likely to have a bad effect on you or on another person:', 'You''re not well, and you''re not doing yourself any favours by taking on extra work.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36222, 'not do things by halves', 'If someone does not do things by halves, they put a lot of effort and enthusiasm into doing things, often more than is necessary:', '"I didn''t realize you were decorating the whole house." "Oh, we don''t do things by halves round here."', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36223, 'not for a moment', 'used to say that you do not think or do something at all:', 'I don''t believe that story for a moment.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36224, 'not for one minute', 'certainly not:', 'I''m not suggesting for one minute that she meant to cause any trouble.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36225, 'not for the squeamish', 'used to say that something is unpleasant, and will upset people who are squeamish:', '"The Silence of the Lambs" is an entertaining movie but is not for the squeamish.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36226, 'not for the world', 'never; not in any situation:', 'If I took that job I''d have to leave the kids and I wouldn''t do that for the world.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36227, 'not get a word in edgeways', 'to not be able to say anything because someone else is talking all the time:', 'Rosa was talking so much that nobody else could get a word in edgeways!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36228, 'not get a word in edgewise', 'to not be able to say anything because someone else is talking all the time:', 'Roz was talking so much that nobody else could get a word in edgewise!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36229, 'not get anywhere', 'to not make progress toward a goal:', 'His parents tried to talk him out of joining the army, but they didn’t get anywhere.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36230, 'not get over something', 'When you say that you can''''t get over something, you mean that you are very surprised by it:', 'I can''t get over the way he behaved at your party - it was appalling!', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36231, 'not get to first base', 'to not be able to start doing what you intend to do:', 'We need financing for this project, but we can’t get to first base with the banks.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36232, 'not get/go anywhere', 'If you are not getting/going anywhere, you are not improving or advancing a particular situation:', 'I''ve been sorting out my study all day, but it''s such a mess I don''t feel I''m getting anywhere.', 'idiom', 'B2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36233, 'not give a monkey''''s', 'If you don''''t/couldn''''t give a monkey''''s about something, you are not at all worried by it:', '"Chrissie won''t like it." "I don''t give a monkey''s."', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36234, 'not give a shit', 'to not be interested in or worried about something or someone:', 'I don''t give a shit what he thinks.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36235, 'not give a tinker''''s cuss', 'to not be interested in or worried about something or someone:', 'I couldn''t give a tinker''s cuss about what they think.', 'idiom', NULL, NULL, 'old-fashioned informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36236, 'not give a tinker''''s damn', 'to not be interested in or worried about something or someone:', 'I don''t give a tinker''s damn about what they think.', 'idiom', NULL, NULL, 'old-fashioned informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36237, 'not give much for someone''''s chances', 'to not believe someone will succeed:', 'I wouldn''t give much for his chances in the next race.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36238, 'not give someone the time of day', 'to not be friendly to someone and not speak to or help that person:', 'He kept pestering me to go out with him, but I wouldn’t give him the time of day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36239, 'not give tuppence for something', 'to think that something will not succeed:', 'I wouldn''t give tuppence for their chances of winning the match.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36240, 'not give/budge/move an inch', 'to not change your opinion:', 'She''s definite that she wants to do it, and she''ll not give an inch, however hard you try to persuade her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36241, 'not give/care a damn', 'used as a way of saying you do not care about something, especially the annoying things that someone else is doing or saying:', 'I don''t give a damn what he thinks of me!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36242, 'not give/care a toss', 'to not be worried at all by something:', 'I don''t give a toss what he thinks.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36243, 'not go much on something', 'to dislike something:', 'I don''t go much on white wine.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36244, 'not go there', 'to not start to think about or discuss a subject:', '"Then there''s the guilt I feel about leaving her for seven hours every day." "Don''t even go there!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36245, 'not half', 'used in spoken English to express a positive statement more strongly:', 'It wasn''t half crowded in the club last night (= it was very crowded).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36246, 'not half as', 'not nearly as:', 'It wasn''t half as good as that other restaurant we went to.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36247, 'not have a bad/dishonest/racist, etc. bone in your body', 'to not be bad, dishonest, racist, etc. in any way:', 'Jimmy did not have a bad bone in his body.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36248, 'not have a bar of something', 'to refuse to accept or have anything to do with something:', 'Karen called her mother and asked her to come and stay, but Mum wouldn''t have a bar of it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36249, 'not have a bean', 'to have no money', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36250, 'not have a cat in hell''''s chance', 'to be completely unable to achieve something:', 'They haven''t a cat in hell''s chance of getting over the mountain in weather like this.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36251, 'not have a civil word to say about someone', 'to not be able to think of anything good to say about someone', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36252, 'not have a clue', 'to have no knowledge about something, or to be unable to remember something:', 'I don’t have a clue what I did with my baseball glove.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36253, 'not have a clue/have no clue', 'to be completely unable to guess, understand, or deal with something:', '"Who invented algebra?" "I don''t have a clue."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36254, 'not have a hope in hell', 'to have no possibility of doing or achieving something:', 'We were so outclassed - we didn''t have a hope in hell of winning.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36255, 'not have a leg to stand on', 'to be in a situation in which you cannot prove something:', 'If you have no witnesses, you don''t have a leg to stand on.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36256, 'not have a penny to your name', 'to be very poor', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36257, 'not have a pot to piss in', 'to be very poor:', 'Any help we can offer them will be appreciated. They don''t have a pot to piss in.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36258, 'not have a prayer', 'to have no chance of succeeding:', 'She hasn''t a prayer of winning the competition.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36259, 'not have a snowball''''s chance in hell', 'to have no chance of succeeding:', 'If he can''t afford a good lawyer, he doesn''t have a snowball''s chance in hell of winning the case.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36260, 'not have a/the ghost of a chance', 'to have no chance at all:', 'They don''t have a ghost of a chance of winning.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36261, 'not have any of it', 'to be completely unwilling or to refuse:', 'I asked him to help out, but he wasn''t having any of it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36262, 'not have much upstairs', 'to not be very intelligent:', 'People think he hasn''t got much upstairs but in fact he is very intelligent when it comes to computers.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36263, 'not have the foggiest (idea)', 'to not know or understand something at all:', 'I didn''t have the foggiest idea what he was talking about.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36264, 'not have the heart to do something', 'to feel unable to do something because you feel it would be unkind:', 'She asked me to go with her and I didn''t have the heart to refuse.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36265, 'not have the remotest idea', 'to not know at all:', '"Who''s that?" "I haven''t the remotest idea."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36266, 'not have the stomach for something', 'to not feel brave or determined enough to do something unpleasant:', 'I didn''t have the stomach for another fight.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36267, 'not hear of something', 'If you say you will not hear of something, you mean you will not allow it, usually when you want to do something good for someone:', 'I wanted to pay but she wouldn''t hear of it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36268, 'not hear the end/last of something', 'to be told repeatedly about something:', 'We''ll never hear the last of it if they win that competition.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36269, 'not hold a candle to someone/something', 'to not be as good as someone or something else:', 'Her latest book can’t hold a candle to her earlier works.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36270, 'not hold with something', 'to not approve of an idea or activity', NULL, 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36271, 'not in a month of Sundays', 'If you say that something will not happen in a month of Sundays, you mean that it is very unlikely to happen:', 'He''s never going to get that finished in a month of Sundays!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36272, 'not in the biblical sense', 'If you say you know someone but not in the biblical sense, you mean you have not had sex with them:', '"Did you know her?" "Yes - not in the biblical sense, of course."', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36273, 'not in the least', 'not in any way:', '"Are you dissatisfied with the results?" "Not in the least."', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36274, 'not in the same league', 'not nearly as good as something or someone else:', 'She''s a brilliant golfer - I''m not in the same league.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36275, 'not know someone from Adam', 'to have never met someone and not know anything about them:', 'Why should she lend me money? She doesn''t know me from Adam.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36276, 'not know the first thing about something', 'to know nothing about a subject:', 'I''m afraid I don''t know the first thing about car engines.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36277, 'not know the half of it', 'If someone does not know the half of it, they know that a situation is bad but do not know how serious it is:', '"I hear things aren''t going too well at work." "You don''t know the half of it!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36278, 'not know the meaning of the word', 'If you are talking about a quality or an activity and you say that someone doesn''''t know the meaning of the word, you mean they do not have that quality or have no experience of that activity:', 'Work? He doesn''t know the meaning of the word!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36279, 'not know what has hit you', 'to be shocked and surprised because something unpleasant suddenly and unexpectedly happens to you:', 'You wait till he starts working for Michael - he won''t know what''s hit him!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36280, 'not know what hit you', 'to be suddenly shocked and confused by something:', 'When he said I was fired, I didn’t know what hit me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36281, 'not know what hit you', 'to feel shocked or confused because something bad has happened to you suddenly when you were not expecting it', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36282, 'not know what someone sees in someone/something', 'to not understand why someone likes a particular person or thing:', 'He''s so boring - I don''t know what she sees in him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36283, 'not know where to put yourself', 'to feel very embarrassed:', 'And then he started to sing. Well, I didn''t know where to put myself.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36284, 'not know where/which way to turn', 'to not know what to do or who to ask for help:', 'When both her parents died, she didn''t know which way to turn.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36285, 'not know whether to laugh or cry', 'to not know how to react in a particular situation:', 'When she told me they were getting married I didn''t know whether to laugh or cry.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36286, 'not know whether you are coming or going', 'to be in a very confused state:', 'I''m so busy, I don''t know whether I''m coming or going.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36287, 'not know your arse from your elbow', 'an offensive phrase meaning to be stupid and unable to understand very simple things', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36288, 'not know your ass from your elbow', 'a rude phrase meaning to be stupid and unable to understand very simple things:', 'My boss has proven time and again that he doesn''t know his ass from his elbow.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36289, 'not last long', 'to fail or be unsuccessful very soon:', 'You won''t last long in your job if you carry on being so rude to the customers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36290, 'not lift a finger', 'to not make any effort:', 'He just watches TV and never lifts a finger to help with the dishes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36291, 'not lift/raise a finger', 'to not make any effort to help:', 'He never lifts a finger to help with the housework.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36292, 'not long for this world', 'If someone is not long for this world, they will die soon.', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36293, 'not make any difference', 'to not change a situation in any way:', 'You can ask him again if you want, but it won''t make any difference - he''ll still say no.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36294, 'not matter tuppence', 'to not be important:', 'It doesn''t matter tuppence what you think.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36295, 'not mince (your) words', 'to say what you mean clearly and directly, even if you upset people by doing this:', 'The report does not mince words, describing the situation as "ludicrous".', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36296, 'not miss a beat', 'to not pause or show any uncertainty, usually when this is surprising:', '"That''s what I thought," replied Olivia, without missing a beat.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36297, 'not miss a beat', 'to do something without any mistakes or failures:', 'The player hasn''t missed a beat this year, scoring three touchdowns in his first three games.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36298, 'not miss a trick', 'said about someone who never fails to notice and take advantage of a good opportunity:', 'Jonathan doesn''t miss a trick! If there''s a bargain to be had, he''ll find it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36299, 'not miss much', 'said when something you failed to see or experience was not important or special:', '"I didn''t manage to see that programme." "Don''t worry, you didn''t miss much."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36300, 'not miss/skip a beat', 'to not pause or show any uncertainty, usually when this is surprising:', '"That''s what I thought," replied Olivia, without missing a beat.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36301, 'not miss/skip a beat', 'to do something without any mistakes or failures:', 'The player hasn''t missed a beat this year, scoring three touchdowns in his first three games.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36302, 'not move a muscle', 'to stay completely still:', 'She sat without moving a muscle as the nurse put the needle in.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36303, 'not much cop', 'not very good:', 'His last book wasn''t much cop.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36304, 'not on your life!', 'said as a way of strongly refusing someone''''s suggestion or request:', '"So you''re going to bring Kev, are you?" "Not on your life!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36305, 'not pull any/your punches', 'to speak in an honest way without trying to be kind:', 'Her image is that of an investigative reporter who doesn''t pull any punches.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36306, 'not put a foot wrong', 'to not make any mistakes', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36307, 'not put it past someone (to do something)', 'to not be surprised if someone does something bad, because it is a typical thing for that person to do:', 'Perhaps Helena told him - I wouldn''t put it past her.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36308, 'not put something down', 'If you cannot put a book down, you are unable to stop reading it until you reach the end:', 'It was so exciting from the first page I couldn''t put it down.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36309, 'not say boo', 'to say nothing:', 'You didn''t say boo to me about going to your mother''s this weekend.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36310, 'not say boo', 'to be very nervous and easily frightened', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36311, 'not see beyond something', 'to have all your attention on something and therefore be unable to consider other things:', 'The government cannot see beyond next year''s election.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36312, 'not see hide nor hair of someone', 'to not see someone at all over a period of time:', 'I haven''t seen hide nor hair of her since last Friday.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36313, 'not see someone for dust', 'used to describe someone leaving quickly in order to avoid something:', 'If you let him know that Margaret''s coming, you won''t see him for dust.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36314, 'not see the forest for the trees', 'to be unable to get a general understanding of a situation because you are too worried about the details', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36315, 'not see the wood for the trees', 'to be unable to get a general understanding of a situation because you are too worried about the details', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36316, 'not see/look, etc. beyond/past the end of your nose', 'to only consider what is very close to you, what is very obvious, or what is happening in the near future:', 'In financial planning you need to look beyond the end of your nose.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36317, 'not set the world on fire', 'to not be very exciting or successful:', 'He has a nice enough voice but he''s not going to set the world on fire.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36318, 'not sit well with someone', 'to be difficult for someone to agree with or accept:', 'The principal''s decision did not sit well with many parents.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36319, 'not sleep a wink', 'to not sleep at all:', 'I didn''t sleep a wink last night with all that noise.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36320, 'not so much', 'used to refer back to something that has been mentioned, saying that it is less true for someone or something else :', 'If you like it, fine, but for me, not so much.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36321, 'not so much something as something', 'If you say that something is not so much one thing as something else, you mean it is more the second thing:', 'They''re not so much lovers as friends.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36322, 'not so shabby/not too shabby', 'used for saying that something is good:', 'It was a not so shabby week for the team, who had three wins.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36323, 'not soil your hands', 'to not become involved in something unpleasant or bad:', 'These were top lawyers, the kind who wouldn''t normally soil their hands with police work or criminal law.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36324, 'not stand any nonsense', 'to refuse to accept bad or silly behaviour:', 'The new teacher won''t stand any nonsense.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36325, 'not suffer fools gladly', 'to have very little patience with people who you think are stupid or have stupid ideas', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36326, 'not take a blind bit of notice', 'to pay no attention to something:', 'He didn''t take a blind bit of notice of what I said.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36327, 'not take kindly to something', 'to not like something:', 'After years of being looked after by his mother, he didn''t take kindly to being told to cook for himself.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36328, 'not take something lying down', 'to refuse to be treated badly by someone:', 'He can''t treat you like that! Surely you''re not going to take that lying down!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36329, 'not take your eyes off someone/something', 'to not stop looking at someone or something:', 'He was so handsome - I couldn''t take my eyes off him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36330, 'not that', 'used to say you are not suggesting something:', 'She wouldn''t tell me how much it cost - not that I was really interested.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36331, 'not that', 'used to say you do not think something is important:', 'Not that I mind, but why didn''t you call yesterday?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36332, 'not that I know of', 'used when answering a question to mean that, judging from the information you have, the answer is no:', '"Is she especially unhappy at school?" "Not that I know of."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36333, 'not the done thing', 'not socially acceptable:', 'Smoking during a meal is not the done thing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36334, 'not the end of the world', 'not the worst thing that could happen:', 'We’re hoping to win, but if we finish second it won’t be the end of the world.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36335, 'not the least', 'used for emphasis with nouns:', 'I haven''t the least idea (= I do not know) who he was.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36336, 'not the same', 'not as good:', 'You can make shortbread with margarine instead of butter, but it isn''t the same.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36337, 'not the thing to do', 'not socially acceptable:', 'Smoking during a meal is not the thing to do.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36338, 'not think much of someone/something', 'to have a low opinion of someone or something:', 'I don’t think much of this techno music.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36339, 'not think straight', 'to be unable to use your mind in an effective way:', 'I was so tired, I couldn''t think straight.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36340, 'not think twice', 'to do something immediately, without considering if it is a good idea:', 'They didn''t think twice about laying off hundreds of employees.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36341, 'not to be outdone', 'not wanting someone else to do something better than you:', 'Pat was wearing an outrageous purple dress, so, not to be outdone, I put on my new gold suit.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36342, 'not to be sneezed at', 'If you say that something, especially an amount of money, is not to be sneezed at, you mean that it is a large enough amount to be worth having:', 'Well, a five percent pay increase means an extra $700 a year, which is not to be sneezed at!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36343, 'not to be sniffed at', 'valuable or worth having:', 'A £2 million profit is not to be sniffed at.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36344, 'not to mention', 'used when you want to emphasize something that you are adding to a list:', 'He''s one of the kindest and most intelligent, not to mention handsome, men I know.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36345, 'not to put too fine a point on', 'to be completely direct and honest:', 'I think she''s wrong - not to put too fine a point on it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36346, 'not to say', 'and possibly even:', 'It would be unwise, not to say stupid, to leave your first job after only six months.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36347, 'not to worry', 'said to show that you are not worried or upset because something has gone wrong or something unexpected has happened:', 'Not to worry - maybe you''ll be able to come next week instead.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36348, 'not trust someone an/one inch', 'to not trust someone at all:', 'Make sure you tell him as little as possible about what happened. And don''t trust him an inch.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36349, 'not turn a hair', 'to not show any emotion when you are told something bad or when something bad happens:', 'I was expecting him to be horrified when he heard the cost but he didn''t turn a hair.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36350, 'not until', 'not before a stated time or event:', 'Don’t move until I tell you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36351, 'not waste words', 'If someone does not waste words, they talk only about what is important using as few words as possible:', 'He explained the whole system in about 30 seconds - he doesn''t waste words, does he?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36352, 'not worth the paper something is printed/written on', 'If a document or agreement is not worth the paper it is written/printed on, it is of very little value.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36353, 'not your day', 'a bad day when things do not happen as you would like them to:', 'I missed my bus and forgot my glasses – I guess it’s just not my day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36354, 'not yourself', 'not feeling well or not acting in your usual way:', 'I''m sorry for crying – I''m not myself today.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36355, 'not/never in your wildest dreams', 'used to say that something is better than anything you could imagine or hope for:', 'Never in my wildest dreams did I imagine that one day I would run a marathon.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36356, 'not/never want for anything', 'to have all the basic things you need to lead a satisfactory life:', 'As children we never wanted for anything.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36357, 'not/no more than', 'used to emphasize how small an amount is:', 'There are beautiful mountains not more than ten minutes'' drive away.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36358, 'not/nothing much', 'very little, or nothing that is important or interesting:', 'I had nothing much to do that day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36359, 'notch something up', 'to achieve something:', 'She has recently notched up her third win at a major ski event.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36360, 'note something down', 'to write something so that you do not forget it:', 'I noted down his phone number.', 'phrasal verb', 'B2', NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36361, 'nothing could be further from the truth', 'used to say that what has been suggested is completely untrue:', 'People say we''re splitting up, but nothing could be further from the truth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36362, 'nothing could have been further from my mind/thoughts', 'used to say that you certainly did not intend something:', 'I certainly wasn''t trying to get money from him - nothing could have been further from my mind!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36363, 'nothing daunted', 'still confident and enthusiastic despite a failure or problem:', 'She was rejected the first time she applied to the university, but, nothing daunted, reapplied the following year and was accepted.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36364, 'nothing doing', 'used to mean "no", especially when said in answer to a request:', 'We asked if she''d come over and help us, but she said, "Nothing doing".', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36365, 'nothing less than something', 'only a particular quality in something, and not worse:', 'The chef will accept nothing less than perfection from his kitchen staff.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36366, 'nothing less than something', 'Nothing less than something is also used to show something is very important or serious:', 'The president proposed nothing less than a complete overhaul of the tax system.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36367, 'nothing like someone/something', 'not at all similar to someone or something:', 'Instant coffee is nothing like the real thing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36368, 'nothing more than', 'only:', 'He dismissed Bryan as nothing more than an amateur.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36369, 'nothing much', 'very little:', '"What’s up?" "Nothing much."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36370, 'nothing of the kind', 'used to emphasize a negative statement:', 'I told him nothing of the kind (= I did not tell him anything like that).', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36371, 'nothing special', 'neither very good nor very bad:', 'Dinner was nothing special.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36372, 'nothing to sneeze at', 'something that deserves serious attention, esp. an amount of money:', 'An extra two thousand bucks a year is nothing to sneeze at.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36373, 'nothing to write home about', 'not exciting or special:', 'Their performance was nothing to write home about.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36374, 'nothing ventured, nothing gained', 'You have to take a risk in order to get something good.', NULL, 'idiom', 'C2', NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36375, 'now then', 'said to attract attention to what you are going to ask or suggest:', 'Now then, what''s all this noise about?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36376, 'now you''''re talking', 'said when someone makes a suggestion or offer that is better than one that they have already made', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36377, 'now, now', 'said when you want to make someone feel better or give someone a gentle warning:', 'Now, now, don''t cry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36378, 'nowhere near', 'not in any way:', 'The operation had already been going on for eight hours, and it was nowhere near finished.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36379, 'nowhere to be found', 'impossible to see or find:', 'We looked for her everywhere, but she was nowhere to be found.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36380, 'nudge nudge (wink wink)', 'something you say when you want to suggest that there is a sexual meaning in something that has just been said', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36381, 'number someone/something among someone/something', 'If you are numbered among a particular group, you belong to that group:', 'At one time, the club numbered an archbishop among its members.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36382, 'oblige someone with something', 'to help someone by giving them something:', 'Could you oblige me with a pen and a piece of paper, please?', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36383, 'occur to someone', 'If a thought or idea occurs to you, it comes into your mind:', 'The thought did occur to me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36384, 'oceans of something', 'a lot of something:', 'We have oceans of time.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36385, 'of a kind', 'used to describe something that exists but is not very good:', 'The school had a swimming pool of a kind, but it was too small for most classes to use.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36386, 'of all people', 'used to show that you are especially surprised at a particular person''''s behaviour because it does not seem typical of them:', 'I thought that you, of all people, would believe me!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36387, 'of all people/things/places', 'used to express the idea that a particular person/thing/place is unlikely or surprising:', 'Donna, of all people, is the last one I''d expect to see at the gym.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36388, 'of choice', 'Your thing or person of choice is the one that you usually choose in a particular situation:', 'Botox is now the drug of choice in Hollywood.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36389, 'of course', 'used to say yes or to give someone permission to do something:', '"Can you help me?" "Of course."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36390, 'of course', 'used to show that what you are saying is obvious or already known:', 'The Second World War ended, of course, in 1945.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36391, 'of course', 'used to show that a situation or a piece of information is not surprising:', 'We arrived at the restaurant 30 minutes late so, of course, our reservation had been cancelled.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36392, 'of course not', 'used to emphasize that you disagree or that something is not true:', '"Where did you get the money? Did you steal it?" "Of course not. I borrowed it from Carol."', 'idiom', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36393, 'of every stripe/of all stripes', 'of all types:', 'Governments of every stripe (= of all political opinions) have a bad habit of interfering in state broadcasting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36394, 'of late', 'recently:', 'We haven''t spoken of late.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36395, 'of old', 'in or from the past:', 'in days of old', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36396, 'of old', 'for a very long time:', 'I know him of old.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36397, 'of sorts', 'used to describe something that is not a typical or good example of something:', 'He managed to make a curtain of sorts out of an old sheet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36398, 'of the kind', 'like or similar to what has been said:', '"You said I was fat." "I didn''t say anything of the kind!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36399, 'of the moment', 'the person or thing that is the most important and successful at a particular time:', 'Jack was man of the moment during the crisis.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36400, 'of the old school', 'traditional and old-fashioned', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36401, 'of the week', 'A thing or person of the week is one that has been chosen as the best in a particular week:', 'Book of the Week: Dog Breeds by Andrew and Helen Barker.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36402, 'of the year', 'A thing or person of the year is one that has been chosen as the best in a particular year, especially in a competition:', 'Young Musician of the Year', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36403, 'of two minds (about something)', 'unable to make a decision:', 'I was of two minds about whether to invite him to the wedding.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36404, 'of your own making', 'your own fault:', 'Any problems she has with that child are of her own making.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36405, 'off his line', 'If a goalkeeper is off his or her line, he or she is not standing along the goal line:', 'Neymar caught the keeper off his line with a brilliant 45-yard lob.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36406, 'off someone''''s radar', 'If someone or something is off your radar, you are not aware of, or have not thought about, them or it:', 'At that time, boyfriends were completely off my radar.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36407, 'off the bat', 'immediately:', 'You can''t expect to be accepted in a new town right off the bat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36408, 'off the beaten path', 'not known or popular with many people:', 'We wanted to find a camping site that was a little bit off the beaten path.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36409, 'off the beaten track', 'in a place where few people go, far from any main roads and towns:', 'The farmhouse we stayed in was completely off the beaten track.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36410, 'off the books', 'in a way that is not officially written down in a person''''s or company''''s financial records:', 'These workers are getting paid in cash off the books.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36411, 'off the books', 'removed from an official record, especially as a law:', 'Civil rights groups worry that, once enacted, tough new laws may be difficult to get off the books.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36412, 'off the chain', 'extremely good:', 'I made it with extra cheese and it was off the chain.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36413, 'off the charts', 'at a very high level:', 'His blood pressure was off the charts', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36414, 'off the charts', 'extremely popular or successful:', 'The new restaurant is totally off the charts.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36415, 'off the cuff', 'If you speak off the cuff, you say something without having prepared or thought about your words first:', 'I hadn''t prepared a speech so I just said a few words off the cuff.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36416, 'off the hook', 'If you leave the phone off the hook, you do not put it back correctly and it will not ring.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36417, 'off the hook', 'If you are off the hook, you have escaped from a difficult situation:', 'John''s agreed to go to the meeting in my place so that gets/lets me off the hook.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36418, 'off the hook', 'extremely good:', 'That party was off the hook!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36419, 'off the record', 'If someone says something off the record, they do not want it to be publicly reported:', 'She made it clear that her comments were strictly off the record.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36420, 'off the scale', 'extremely large in amount or degree :', 'Revenues are off the scale and global domination is on the agenda.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36421, 'off the top of your head', 'from the knowledge you have in your memory:', '"What''s the capital of Mauritania?" "I don''t know off the top of my head, but I could go and look it up."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36422, 'off the wall', 'surprising and unusual:', 'an off-the-wall joke
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36423, 'off with something', 'used as a way of ordering someone to remove something:', 'Off with his head!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36424, 'off your rocker', 'If you say that someone is off their rocker, you mean that that person is behaving in a very strange or silly way.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36425, 'off your trolley', 'behaving in an extremely unusual way or doing something very silly:', 'Anyone who saw us doing this would think we were off our trolleys.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36426, 'offend against something', 'to break a rule or principle or not fit well with something that people consider to be correct:', 'Would it be offending against good taste to wear a patterned tie with my striped shirt?', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36427, 'oh yes', 'used when you have just remembered something that you were saying:', 'What was I talking about - oh yes, I was telling you what happened at the party.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36428, 'oil the wheels', 'to make it easier for something to happen:', 'An aid programme was established to oil the wheels of economic reform in the region.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36429, 'old chestnut', 'a subject, idea, or joke that has been discussed or repeated so often that it is not funny any more:', 'I wondered whether there might, after all, be some truth in the old chestnut that one''s school days are the happiest of one''s life.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36430, 'on (a) par with someone/something', 'equal or similar to someone or something:', 'In my opinion, none of the new jazz trumpeters are on a par with Miles Davis.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36431, 'on (your) guard', 'careful and aware because a situation might be dangerous:', 'Passengers on public transportation were warned to be on their guard against pickpockets.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36432, 'on a collision course', 'having very different aims or opinions and therefore likely to strongly disagree or fight:', 'The governor put himself on a collision course with state lawmakers over energy policy.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36433, 'on a dime', 'If a vehicle, etc. can turn, stop, etc. on a dime, it can turn, etc. in a very small space:', 'The high-tech steering means that even huge tractors can turn on a dime.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36434, 'on a first-name basis', 'knowing someone well enough that you call each other by your first names:', 'I''ve met her, but I''m not on a first-name basis with her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36435, 'on a full stomach', 'soon after you have eaten:', 'You might get sick if you go jogging on a full stomach.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36436, 'on a need-to-know basis', 'If you tell people something on a need-to-know basis, you only tell them the facts they need to know at the time they need to know them, and nothing more.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36437, 'on a razor edge', 'in a very uncertain and dangerous situation:', 'Allegations of fraud have put the politician''s career on a razor edge.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36438, 'on a roll', 'infml experiencing a period of success or good luck:', 'They’ve won nine games in a row, so they’re obviously on a roll.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36439, 'on a shoestring', 'If you do something on a shoestring, you do it with a very small amount of money:', 'The film was made on a shoestring.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36440, 'on a wing and a prayer', 'If you do something on a wing and a prayer, you do it hoping that you will succeed, although you are not prepared enough for it:', 'With hardly any funding and a staff of six, they were operating on a wing and a prayer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36441, 'on all fours', 'with your hands and knees on the ground:', 'You''ll have to get down on all fours to clean behind the toilet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36442, 'on an empty stomach', 'without eating anything:', 'You should never go to work on an empty stomach.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36443, 'on an even keel', 'regular and well-balanced and not likely to change suddenly:', 'The new manager succeeded in putting the business back on an even keel.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36444, 'on and off', 'If something happens on and off during a period of time, it happens sometimes:', 'I''ve had toothache on and off for a couple of months.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36445, 'on assignment', 'doing a job, especially a job in which you are reporting news for a newspaper, television station, etc.:', 'The two journalists met while on assignment in Colombia.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36446, 'on autopilot', 'doing something without thinking about it or without making an effort:', 'I worked the last hour of my shift on autopilot.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36447, 'on average', 'usually:', 'On average, a person’s income is highest when they are in their mid-50s.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36448, 'on balance', 'after considering the power or influence of both sides of a question:', 'The job offer had some advantages, but on balance he thought he was better off where he was.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36449, 'on behalf of someone', 'done for another person’s benefit or support, or because you are representing the interests of that person:', 'I’d like to say on behalf of the whole group that we wish you well in your new job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36450, 'on deposit', 'Money that is on deposit is saved in a bank or something similar:', 'I''ve got £5,000 on deposit in the bank.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36451, 'on earth', 'infml in any conditions; of all possible things:', 'How on earth did this happen?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36452, 'on easy street', 'rich', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36453, 'on end', 'continuously:', 'She practices the violin for hours on end.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36454, 'on everyone''''s lips', 'being talked about by a lot of people:', 'The question now on everyone''s lips is "Will he resign?"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36455, 'on hand', 'near to someone or something, and ready to help or be used if necessary:', 'A 1,200-strong military force will be on hand to monitor the ceasefire.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36456, 'on high', 'in heaven:', 'God looked down from on high.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36457, 'on high', 'If an order comes from on high, it comes from someone in a position of authority:', 'Instructions came from on high to reduce our travel expenses.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36458, 'on ice', '(of drink or food) in a container of ice to get cold:', 'I''ve put a couple of bottles of champagne on ice .
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36459, 'on ice', 'If a plan is on ice, a decision has been made to delay it for a period of time:', 'Both projects are on ice until the question of funding is resolved.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36460, 'on it', 'doing something that needs to be done, or trying to solve a problem:', '"We need help with web design." "Don''t worry, I''m on it."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36461, 'on its (own) merits', 'based only on a person''''s or thing''''s qualities and not on what other people say about that person or thing:', 'Judge the product on its own merits, and not on what the ads say.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36462, 'on its last legs', 'Something that is on its last legs is in such bad condition that it will soon be unable to work as it should:', 'I''ve had this laptop for five years now, and it''s really on its last legs.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36463, 'on its way', 'happening or arriving soon:', 'They have three kids, and another on the way.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36464, 'on its way', 'If you are on your way you are leaving:', 'Give me a kiss and I''ll be on my way.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36465, 'on no account', 'If something must on no account/not on any account be done, it must not be done at any time or for any reason:', 'Employees must on no account make personal phone calls from the office.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36466, 'on occasion', 'sometimes but not often:', 'He has, on occasion, told a small lie.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36467, 'on one level...on another level', 'something that you say when you are speaking about two opposite ways of thinking about or reacting to a situation:', 'On one level I quite like the attention but on another level, I suppose I find it a little disturbing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36468, 'on paper', 'judging something by how it has been planned rather than how it really works in practice:', 'The design certainly looks good on paper.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36469, 'on pins and needles', 'worried or excited about something that is going to happen:', 'Don’t keep Margaret on pins and needles – give her a call.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36470, 'on point', 'as good as it could be; perfect:', 'My hair was on point.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36471, 'on shaky ground', 'likely to fail:', 'At least one factory is on shaky ground, and the town expects more to shut down.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36472, 'on short notice', 'only a short time before something happens:', 'I can''t cancel my plans on such short notice.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36473, 'on skid row', 'poor, without a job or a place to live, and often drinking too much alcohol', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36474, 'on someone''''s account', 'If something is said to be on someone''''s or something''''s account, it is because of that person or thing:', 'I''m not very hungry, so please don''t cook on my account (= don''t cook just for me).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36475, 'on someone''''s deathbed', 'just before someone''''s death:', 'He told her he loved her on his deathbed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36476, 'on someone''''s doorstep', 'very close to where someone is or lives:', 'There''s a lovely park right on our doorstep.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36477, 'on someone''''s radar', 'If someone or something is on your radar, you are aware of, or have thought about, them or it. :', 'She has been on my radar since her first novel came out, but I haven''t read any of her books yet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36478, 'on speaking terms', 'friendly enough to talk:', 'We had an argument, but we’re back on speaking terms now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36479, 'on standby', 'ready to work or be used if necessary:', 'Hospitals are on standby to care for casualties of the crash.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36480, 'on standby', 'ready to work or be used if necessary:', 'Hospitals are on standby to care for casualties of the crash.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36481, 'on steroids', 'used for saying that something is an extreme example or version of something:', 'He described the new edifices as "architecture on steroids".
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36482, 'on stream', 'Something in industry or business that is on stream is being produced or is available for use:', 'The company''s increased sales were primarily a result of new stores coming on stream.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36483, 'on tap', 'available:', 'There are several new movies on tap this weekend.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36484, 'on target', 'If you are on target with a piece of work, you are making good progress and likely to achieve what you planned.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36485, 'on the attack', 'to act in a strong, determined way to defeat someone or something, often in a game or competition:', 'In the second half, the Panthers went on the attack and they scored after two minutes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36486, 'on the back burner', 'If something is on the back burner, it is temporarily not being dealt with or considered, especially because it is not urgent or important:', 'We''ve all had to put our plans on the back burner for a while.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36487, 'on the back of an envelope', 'in a hurried way, without much detail:', 'The prices were very roughly calculated - it looked as though he''d done them on the back of an envelope.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36488, 'on the back of something', 'soon after an earlier success, and as a result of it:', 'The advertising agency secured the contract on the back of its previous successful campaigns.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36489, 'on the back of someone/something', 'by using or taking advantage of someone or something else:', 'They have carried on their business operations by riding on the back of established firms.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36490, 'on the ball', 'aware of any changes or developments and quick to react to them:', 'We need someone who’s really on the ball to answer questions from the press.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36491, 'on the blink', 'When a machine is on the blink, it is not working correctly.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36492, 'on the books', 'officially employed by a company, or an official member of an organization, society, sports team, etc.:', 'There are 256 people on the books at the cement works.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36493, 'on the books', 'officially recorded, especially as a law:', 'A ban on texting while driving is on the books in most states.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36494, 'on the booze', 'drinking a lot of alcohol:', 'Every Friday night Rick would go out on the booze.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36495, 'on the bounce', 'one after another with nothing else between:', 'The team has had five wins on the bounce.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36496, 'on the bubble', 'not certain to get a place in a team, keep your job, win an election, etc.:', 'Those who had not gained their paramedic certification were "on the bubble" with regard to keeping their jobs.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36497, 'on the contrary', 'fml actually the opposite is true:', 'The crime problem has not disappeared. On the contrary, it seems to be becoming worse again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36498, 'on the count of something', 'after counting to a particular number:', 'On the count of three, run.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36499, 'on the defensive', 'protecting yourself from criticism instead of attacking or criticizing others:', 'The speech produced a firestorm of protest, putting him on the defensive.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36500, 'on the dot', 'exactly at the stated or expected time:', 'The plane landed at two o''clock on the dot.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36501, 'on the edge of your seat', 'very excited, and giving all your attention to something, because you want to know what is going to happen:', 'He could no longer keep his eyes open to watch any of the videos which, until quite recently, would have kept him on the edge of his seat.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36502, 'on the face of it', 'used when you are describing how a situation seems on the surface:', 'On the face of it, it seems like a bargain, but I bet there are hidden costs.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36503, 'on the factory floor', 'involving ordinary workers rather than managers:', 'That sort of decision should be taken on the factory floor.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36504, 'on the fence', 'not able to decide something:', 'Many consumers are still on the fence, waiting for a less expensive computer to come along.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36505, 'on the firing line', 'in a situation that attracts criticism:', 'The judge found himself in the firing line after his remarks about women staying home with their children.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36506, 'on the fly', 'If you do something on the fly, you do it quickly, often while you are doing something else, without preparing and without thinking too much about how it should be done:', 'This new rule seems to have been created on the fly.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36507, 'on the fly', 'without interrupting a computer program that is already running:', 'He had written a program that could translate from Japanese on the fly.', 'idiom', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36508, 'on the front burner', 'getting or needing immediate attention:', 'A few important members of Congress are making an effort to keep human rights on the front burner.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36509, 'on the go', 'very busy:', 'I''ve been on the go all day, and I''m really tired.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36510, 'on the go', 'in the process of being produced:', 'Did you know that she''s got a new book on the go (= being written)?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36511, 'on the ground', 'among the general public:', 'Their political ideas have a lot of support on the ground.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36512, 'on the hoof', 'If you do something on the hoof, you do it while you are moving about or doing something else, often without giving it the attention it deserves:', 'I''ve got a meeting downtown in 20 minutes so I''ll have lunch on the hoof.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36513, 'on the horizon', 'likely to happen or exist soon:', 'There is no new drug on the horizon that will make this disease easier to treat.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36514, 'on the house', 'If you have something on the house, it is given to you free by a business:', 'All the drinks were on the house.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36515, 'on the inside', 'If someone is on the inside, they have a job or position in which they have special or secret information:', 'Who do we know on the inside who can help us?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36516, 'on the large, small, etc. side', 'too large, small, etc. for a particular purpose:', 'This dress is on the large side for me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36517, 'on the level', 'being honest or speaking truthfully:', 'I know he’s lied to you before, but I really think he’s on the level this time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36518, 'on the line', 'at risk of failing or being harmed:', 'His job is on the line.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36519, 'on the line', 'On the line also means speaking on the telephone:', 'My mom was on the line, but I could hear my dad talking in the background.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36520, 'on the loose', 'If a dangerous person or animal is on the loose, that person or animal is free to move around a place and harm people:', 'Brewer escaped from prison last year and has been on the loose ever since.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36521, 'on the make', 'trying hard to succeed, esp. in a way that is dishonest:', 'The movie is about a businessman on the make, who steals company funds.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36522, 'on the market', 'available for sale:', 'We put our house on the market last spring.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36523, 'on the mend', 'becoming healthy after an illness:', 'She''s still in the hospital, but she''s definitely on the mend.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36524, 'on the nod', 'If a suggestion is approved on the nod, it is accepted without discussion:', 'The new proposal went through on the nod.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36525, 'on the nose', 'exactly right, often an exact amount of money or time:', 'Her description of the play was right on the nose.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36526, 'on the one hand ... on the other hand', 'used when you are comparing two different facts or two opposite ways of thinking about a situation:', 'On the one hand I''d like a job that pays more, but on the other hand I enjoy the work I''m doing at the moment.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36527, 'on the other hand', 'in a way that is different from the first thing you mentioned:', 'My husband likes classical music – I, on the other hand, like all kinds.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36528, 'on the outs', 'in a state of disagreement or unfriendliness:', 'Dick is on the outs with his father.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36529, 'on the part of someone/on someone''''s part', 'done or experienced by someone:', 'This was a misjudgment on the part of the government.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36530, 'on the prowl', 'moving around an area and looking for something or someone:', 'On the way home I saw a raccoon on the prowl.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36531, 'on the quiet', 'secretly:', 'His wife found out he''d been seeing someone on the quiet.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36532, 'on the rebound', 'unhappy and confused because a close, romantic relationship of yours has recently finished:', 'Five months after Nick had left her, she married another man on the rebound.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36533, 'on the receiving end of something', 'suffering from something unpleasant when you have done nothing to deserve it:', 'She was on the receiving end of a lawsuit.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36534, 'on the record', 'If you say something on the record, you state it publicly:', 'None of the company directors were prepared to comment on the record yesterday.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36535, 'on the right track', 'doing something correctly or well:', 'You haven''t quite got the answer yet, but you''re on the right track.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36536, 'on the right/wrong side of 40, 50, etc.', 'looking younger/older than a particular age:', 'She looks to me as if she''s on the wrong side of 50.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36537, 'on the right/wrong side of the law', 'obeying/not obeying the law:', 'After coming out of prison, he tried to stay on the right side of the law.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36538, 'on the road', 'traveling to different places:', 'The band spends three months a year on the road.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36539, 'on the road to something', 'likely to achieve something:', 'The doctors say she’s on the road to recovery.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36540, 'on the rocks', 'likely to fail soon:', 'I think their marriage is on the rocks.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36541, 'on the rocks', 'If you have an alcoholic drink on the rocks, you have it with pieces of ice:', 'I''ll have a whisky on the rocks, please.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36542, 'on the ropes', 'doing badly and likely to fail:', 'I think the business is finally on the ropes.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36543, 'on the run', 'while hurrying to go somewhere:', 'I eat breakfast on the run if I''m late for work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36544, 'on the same wavelength', 'thinking in the same way as someone else:', 'Luckily, my husband and I are on the same wavelength about how to raise our kids.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36545, 'on the scent', 'close to discovering:', '"We''re on the scent of something big," said the police chief.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36546, 'on the shelf', 'not noticed or not used:', 'It''s important to apply research in a practical way and not leave it on the shelf.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36547, 'on the shelf', 'If someone, usually a woman, is on the shelf, she is not married and is considered too old for anyone to want to marry her:', 'In those days, if you hadn''t married by the time you were 30, you were definitely on the shelf.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36548, 'on the side', 'in addition to your main job:', 'He makes a little money on the side by cleaning windows in his spare time.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36549, 'on the side', 'secretly:', 'I think he has another woman on the side (= a relationship with a woman who is not his wife).', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36550, 'on the side', '(of food in a restaurant) served on another plate, or on the side of the plate :', 'I''d like a salad with the dressing on the side (= with the dressing served separately from the salad), please.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36551, 'on the sidelines', 'not taking part in an activity:', 'Several countries chose to remain on the sidelines during the war.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36552, 'on the skids', 'failing:', 'Both of the government programs were on the skids.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36553, 'on the slate', '(of the price of food or drink that a regular customer buys) recorded so that they can pay for it at another time:', 'Could you put these drinks on the slate?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36554, 'on the sly', 'secretly:', 'On the sly, Dave was adding chilies to the desserts he made.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36555, 'on the spectrum', 'affected by autism (= a brain condition that affects the development of social and communication skills in ways that can be severe or slight, and that can make someone''''s behaviour and interests different from people without the condition ) to some degree:', 'The article describes a mother''s experience of living with a child on the spectrum.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36556, 'on the spot', 'at that moment or place:', 'He was arrested on the spot.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36557, 'on the spot', 'Someone who is put on the spot is forced to do or say something the person would rather not do or say:', 'I’m not trying to put you on the spot, but could you explain why you did that?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36558, 'on the spur of the moment', 'used to say that a decision, action, etc. is sudden and done without any planning:', 'We hadn''t planned to go away - it was one of those spur-of-the-moment decisions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36559, 'on the streets', 'without a home:', 'Some of these people have been living on the streets for years.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36560, 'on the strength of something', 'If you do something on the strength of something such as advice, you do it because you have been influenced by it or believe it:', 'I invested in the company on the strength of my brother''s advice.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36561, 'on the stump', '(of a politician) travelling around an area giving speeches and trying to get political support:', 'On the stump, he was a master at turning his simple speaking style into a political virtue.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36562, 'on the table', 'If a plan or suggestion has been put/laid on the table, it has been made available for people to hear, read, or discuss.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36563, 'on the take', 'trying to profit in a personal and usually financial way from a situation:', 'He''s obviously on the take - where else did all that money come from?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36564, 'on the threshold of something', 'at the start of a new and important time or development:', 'We are on the threshold of a new era in global relations.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36565, 'on the tip of your tongue', 'about to be said if you can remember it:', 'I know her - her name is on the tip of my tongue, but it won''t come to me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36566, 'on the town', 'enjoying yourself by going to places of entertainment in a town or city:', 'I was out on the town/I had a night on the town last night, and I''m exhausted!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36567, 'on the trot', 'If you do things on the trot, you do them directly after each other without pausing:', 'They won three games on the trot.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36568, 'on the understanding', 'according to someone''''s promise or statement:', 'We purchased the computer on the understanding that it could be returned within ten days.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36569, 'on the up (and up)', 'Someone who is on the up (and up) is honest and can be trusted.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36570, 'on the up (and up)', 'improving all the time:', 'Her career has been on the up and up since she moved into sales.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36571, 'on the verge (of)', 'If you are on the verge of something or come to the verge of something, you are very close to experiencing it:', 'on the verge of collapse/success/tears/death/disaster/war
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36572, 'on the wagon', 'If you are on the wagon, you have decided not to drink any alcohol:', 'He was on the wagon for ten years, when he was living in Connecticut.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36573, 'on the warpath', 'angry and ready to argue or fight:', 'I told my friends to watch out because my mother was on the warpath.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36574, 'on the whole', 'generally:', 'We have our bad times but on the whole we''re fairly happy.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36575, 'on the wrong track', 'not correct about something:', 'If you suspect my son was involved, you are on the wrong track.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36576, 'on top', 'in the best or most successful position:', 'She came out on top in every race.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36577, 'on top of something', 'in addition to something, especially something unpleasant:', 'We missed our flight, and on top of that we had to wait seven hours for the next one.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36578, 'on top of the world', 'extremely happy:', 'She was feeling on top of the world.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36579, 'on track', 'making progress and likely to succeed:', 'They''re on track to make record profits.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36580, 'on view', 'placed where the public can see it:', 'Plans for the new design of the park are on view in the library this week.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36581, 'on your bike!', 'a rude way of telling someone to go away:', '"Can you lend me some money?" "On your bike, mate!"', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36582, 'on your last legs', 'A person who is on their last legs is very tired or near to death:', 'We''d been out walking all day and I was on my last legs when we reached the hotel.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36583, 'on your marks, get set, go!', 'something called out to competitors at the beginning of a running race', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36584, 'on your mettle', 'ready to do something as well as you can in a difficult situation:', 'Both players were on their mettle in the final round.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36585, 'on your own', 'alone:', 'I don’t mind going to the movies on my own.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36586, 'on your own', 'If you do something on your own, you do it without help from anyone else:', 'Bridget learned to tie her shoes on her own when she was three.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36587, 'on your own head be it', 'used to tell someone that they will have to take full responsibility for what they plan to do', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36588, 'on your rounds', 'to be out on a regular visit:', 'The doctor''s out on his rounds.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36589, 'on your toes', 'Someone or something that keeps you on your toes forces you to continue directing all your attention and energy to what you are doing:', 'I work with people who are half my age so that keeps me on my toes.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36590, 'on/about your person', 'in a pocket, bag, or something else that you are holding:', 'Do you have about your person such a thing as a lighter?', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36591, 'on/at every corner', 'in many places along the streets of a town or city:', 'After the game, police were stationed on every corner.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36592, 'on/from the sidelines', 'If you are on the sidelines or do something from the sidelines, you are not actively involved in something:', 'Women have been on the political sidelines for too long - we must now work towards getting into power.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36593, 'on/under pain of death', 'If you have to do something on/under pain of death, you will be killed if you do not do it.', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36594, 'once and for all', 'completely and finally:', 'We have to decide, once and for all, whether we want to ask Dad for money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36595, 'once bitten, twice shy', 'said when you are frightened to do something again because you had an unpleasant experience doing it the first time', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36596, 'once in a blue moon', 'not very often:', 'My sister lives in Alaska, so I only see her once in a blue moon.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36597, 'once more', 'another time:', 'I’ll explain it once more, but listen this time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36598, 'once upon a time', 'used at the beginning of children''''s stories to mean "a long time ago":', 'Once upon a time there was an ugly duckling.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36599, 'once upon a time', 'used when referring to something that happened in the past, especially when showing that you feel sorry that it no longer happens:', 'Once upon a time people knew the difference between right and wrong, but nowadays nobody seems to care.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36600, 'one after another', 'many, in a series:', 'I''ll eat chocolates one after the other until the box is finished.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36601, 'one and all', 'everyone:', 'The news of his resignation came as a surprise to one and all.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36602, 'one and done', 'done, or doing something, only once and never again:', 'This is not a one and done process.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36603, 'one and only', 'only:', 'This may be your one and only opportunity to meet her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36604, 'the one and only', 'the only person or thing of this type:', 'And now I''d like to introduce, the one and only Stevie Wonder!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36605, 'one and the same', 'the same thing or person:', 'I was amazed to discover that Mary''s husband and Jane''s son are one and the same (person).', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36606, 'one by one', 'separately, one after the other:', 'One by one the old buildings in the city have been demolished and replaced with new high rises.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36607, 'one day', 'at some time in the future:', 'I''d like to go to Berlin again one day.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36608, 'one for the books', 'a surprising or unexpected event:', 'Well, that''s one for the books - I never thought he''d get the job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36609, 'one for the road', 'an alcoholic drink just before leaving:', 'Before I went home, she persuaded me to have one for the road.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36610, 'one good turn deserves another', 'said when you do a helpful or kind act for someone who has done something good for you', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36611, 'one in a million', 'extremely unlikely:', 'Don''t worry - the chances of anything going wrong are one in a million.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36612, 'one in a million', 'a very special person:', 'Thanks again - you''re one in a million!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36613, 'one man''''s loss is another man''''s gain', 'said when someone gets an advantage from someone else''''s bad luck', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36614, 'one man''''s meat is another man''''s poison', 'said to emphasize that people like different things', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36615, 'one of a kind', 'the only person or thing of a particular type:', 'In the world of ballet, she was one of a kind.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36616, 'one of these days', 'some time in the near future:', 'You''re going to get into serious trouble one of these days.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36617, 'one of those days', 'a bad day, full of problems:', 'It''s just been one of those days.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36618, 'one or two', 'a few:', 'I''d like to make one or two suggestions.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36619, 'one step at a time', 'slowly and carefully, doing just a little at a time:', 'He wanted to rush through the job, but I encouraged him to take it one step at a time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36620, 'one step forward, two steps back', 'If you take one step forward, two steps back, you make progress but then experience events that cause you to be further behind than you were when you made the progress.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36621, 'one swallow doesn''''t make a summer', 'used to say that because one good thing has happened, it is not therefore certain that a situation is going to improve', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36622, 'one thing leads to another', 'If one thing leads to another, there is a series of events in which each event was caused by the previous one:', 'At first, we were just talking a little, but one thing led to another, and he asked me out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36623, 'one too many', 'If you have had one too many, you have drunk too much alcohol.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36624, 'one way or another', 'in some way that is not stated:', 'Everyone at the party was related (in) one way or another.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36625, 'one way or another', 'in any way that is possible:', 'These bills have to be paid one way or another.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36626, 'one way or the other', 'which of two possibilities will be chosen:', 'They''ve had two weeks to think about it, and now they have to decide one way or the other.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36627, 'one way or the other', 'whatever method is used:', 'One way or the other, this project has to be finished by Tuesday.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36628, 'one, two, etc. down, one, two etc. to go.', 'an expression that is used to mean that you have done or dealt with the first, second, etc. of a series of things and have yet to do or deal with the rest:', '"How are your finals going?" "Two down, three to go."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36629, 'one/some day', 'at some time in the future:', 'I''d love to go to China some/one day.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36630, 'only have eyes for someone', 'to be interested in or attracted to only one person:', 'You''ve no need to be jealous. I only have eyes for you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36631, 'only joking!', 'said when you mean that something you said was not intended to be serious:', 'Think I''ll leave you with the kids while I go for a beer - only joking!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36632, 'only so much/many', 'used to say that there are limits to something:', 'There are only so many hours in your working day - you cannot possibly do all the work.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36633, 'only to do something', 'used to show that something is surprising or unexpected:', 'He spent months negotiating for a pay increase, only to resign from his job soon after he''d received it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36634, 'onward and upward', 'becoming more and more successful:', 'Her publishing career started as an editorial assistant on a women''s magazine and it was onward and upward from there.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36635, 'onwards and upwards', 'becoming more and more successful:', 'Her publishing career started as an editorial assistant on a women''s magazine and it was onwards and upwards from there.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36636, 'ooh and aah', 'to express admiration:', 'We watched the fireworks, oohing and aahing with everyone else.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36637, 'open (something) up', 'to open the lock on the door of a building:', 'The caretaker opens up the school every morning at seven.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36638, 'open something up', 'to improve a situation by making it less limited:', 'The government has announced plans to open up access to higher education.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36639, 'open something up', 'to show something that was hidden or not previously known:', 'The debate could open up sharp differences between the countries.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36640, 'open someone up', 'to do a medical operation on someone to see inside their body:', 'When they opened her up, they couldn''t find anything wrong with her.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36641, 'open up', 'to start to talk more about yourself and your feelings:', 'I''ve never opened up to anyone like I do to you.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36642, 'open carry', 'the act of carrying a gun in public in a way that people can see:', 'We live in a state where open carry is still legal.', 'idiom', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36643, 'open someone''''s eyes', 'to make someone realize something surprising or shocking that they had not known about or understood before:', 'She really opened my eyes to how stupid I''d been.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36644, 'open something out/up', 'to make a space larger or less closed in:', 'We''re going to open up our kitchen by taking out a couple of walls.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36645, 'open the door to something', 'to allow something new to start:', 'The ceasefire has opened the door to talks between the two sides.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36646, 'open the floodgates', 'If an action or a decision opens the floodgates, it allows something to happen a lot or allows many people to do something that was not previously allowed:', 'Officials are worried that allowing these refugees into the country will open the floodgates to thousands more.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36647, 'open your heart to someone', 'to tell someone about your problems and secrets:', 'She''s very understanding - you feel you can really open your heart to her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36648, 'open your mouth', 'to speak or start to speak:', 'I don''t know how she heard about it - I never opened my mouth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36649, 'opt in', 'to choose to be part of an activity, arrangement, etc.:', 'Company policy is to leave new workers out of the pension scheme, unless they choose to opt in.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36650, 'opt out', 'to choose not to be part of an activity or to stop being involved in it:', 'Within any society, there will usually be people who decide to opt out (= choose not to live the way most people do).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36651, 'or die in the attempt', 'said when someone would do anything to achieve what they want to achieve:', 'She''ll finish the race or die in the attempt.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36652, 'or else', 'used to say what will happen if another thing does not happen:', 'We must be there by six, or else we''ll miss the beginning.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36653, 'or else', 'used to compare two different things or situations:', 'She''s either really talkative and you can''t shut her up or else she''s silent.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36654, 'or else', 'used as a threat, sometimes humorously:', 'He''d better find it quickly, or else (= or I will punish him in some way)!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36655, 'or no', 'used to emphasize that the stated thing will not make any difference:', 'Extra pay or no extra pay, I''m not going to work late again tonight.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36656, 'or otherwise', 'used to refer to the opposite of the word that comes before it:', 'Hand in your test papers, finished or otherwise (= or not finished).', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36657, 'or so', 'approximately:', 'They raised two hundred dollars or so for charity.', 'idiom', 'B1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36658, 'or something (like that)', 'used to show that what you have just said is only an example or you are not certain about it:', 'She works for a bank or something.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36659, 'or two', 'approximately or a little more than:', 'I''ll be with you in a minute or two.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36660, 'or what?', 'used at the end of a phrase for emphasis:', 'Are you stupid or what?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36661, 'order out (for something)', 'to order food that is ready to eat to be brought to your home or to the place where you work:', 'We stayed home, ordered out for pizza, and watched a movie on demand.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36662, 'order someone around', 'to tell someone what they should do in an unpleasant or forceful way, especially repeatedly:', 'You can''t just come in here and start ordering people around.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36663, 'order something in', 'to order food that is ready to eat to be brought to your home or to the place where you work:', 'I think I''ll stay home tonight, order in a pizza, and watch my new box set.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36664, 'order sth up', 'to ask a company, store, manufacturer, etc. to supply goods or services:', 'Universities have ordered up thousands of copies of the new software.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36665, 'order your thoughts', 'to plan what you want to say or do:', 'Just give me a moment to order my thoughts, and then I''ll explain the system to you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36666, 'orders are orders', 'said when you have to do something because someone in authority has told you to, and usually when you do not really approve of it:', 'Nobody wants to do it, but orders are orders, so let''s start.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36667, 'other than', 'except:', 'The form cannot be signed by anyone other than you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36668, 'out and about', 'active; doing the things you usually do:', 'The doctor says she''s making a good recovery, and she should be out and about in a few days'' time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36669, 'out and away', 'used with superlatives to mean by a great amount:', 'She is out and away the best student I have ever taught.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36670, 'out front', 'In a theatre, if you say that someone is out front, you mean they are one of the people watching the performance:', 'Don''t worry about your parents being out front tonight.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36671, 'out loud', 'If you say or read something out loud, you say or read it so that other people can hear you:', 'I had to read the essay out loud in front of the whole school.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36672, 'out of action', 'If a machine or vehicle is out of action, it is not working or cannot be used:', 'I''m afraid the TV''s out of action.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36673, 'out of action', 'If a person is out of action, they are injured or ill and cannot do things they usually do:', 'Jackson''s torn ligaments will keep him out of action for the rest of the season.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36674, 'out of bounds', 'If an area is out of bounds, people are not allowed to go there.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36675, 'out of bounds', 'If the ball is out of bounds, it is not within the playing area.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36676, 'out of commission', 'If something, such as a machine or a military ship, is out of commission it is broken or not available to be used.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36677, 'out of hand', 'out of control:', 'Things got a little out of hand at the party and three windows were broken.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36678, 'out of hand', 'If you refuse something out of hand, you refuse it completely without thinking about or discussing it:', 'Moving to London is certainly a possibility - I wouldn''t dismiss it out of hand.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36679, 'out of harm''''s way', 'in a position that is safe from harm or from which harm cannot be done:', 'The children will be here soon - you''d better put that plate out of harm''s way.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36680, 'out of hours', 'If you drink in a bar out of hours, you drink alcohol at a time when it is not allowed by law:', 'The police are trying to stop out-of-hours drinking.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36681, 'out of it', 'not conscious of where you are or what condition you are in as a result of taking alcohol or drugs:', 'She was lying on the sofa, totally out of it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36682, 'out of it', 'unhappy because you are not included in what is happening:', 'I didn''t know anyone at the party, and I felt really out of it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36683, 'out of line', 'beyond what is considered acceptable behavior:', 'You can disagree with her, but calling her dishonest was out of line.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36684, 'out of luck', 'not having the success or good opportunities you wanted:', 'The bike only comes in large sizes, so if you''re a short person you''re out of luck.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36685, 'out of order', 'If something someone says or does is out of order, it is unpleasant or not suitable and it is likely to upset or offend people:', 'His behaviour in the meeting was out of order.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36686, 'out of place', 'not comfortable in or not suitable for a situation:', 'The picture looks out of place here.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36687, 'out of shape', 'not physically healthy enough for difficult exercise because you have not been involved in physical activities:', 'I''m so out of shape that I get out of breath climbing the stairs.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36688, 'out of sight', 'extremely expensive and more than you are able to spend:', 'The price of the house we like is out of sight.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36689, 'out of sight', 'excellent:', 'The group''s new record is out of sight!', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36690, 'out of sight, out of mind', 'said to emphasize that when something or someone cannot be seen, it is easy to forget it, him, or her', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36691, 'out of sorts', 'in an unhappy mood:', 'Peter overslept this morning and has been out of sorts all day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36692, 'out of station', 'away; not present in a place:', 'I am at present out of station and will reply on my return.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36693, 'out of step with someone/something', 'not having the same ideas or beliefs as other people, or not being aware of other people''''s beliefs:', 'The governor''s remarks show that she is seriously out of step with the voters.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36694, 'out of the blue', 'If something happens out of the blue, it is completely unexpected:', 'One day, out of the blue, she announced that she was leaving.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36695, 'out of the corner of your eye', 'without looking at something directly:', 'I was watching TV when I saw something move out of the corner of my eye.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36696, 'out of the frying pan into the fire', 'said when you move from a bad or difficult situation to one that is worse', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36697, 'out of the mouths of babes (and sucklings)', 'said when a child says something that surprises you because it seems very wise', NULL, 'idiom', NULL, NULL, 'literary, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36698, 'out of the picture', 'not important to or not involved in a situation:', 'He used to be an important member of the team, but he''s gradually drifted out of the picture.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36699, 'out of the picture', 'unnecessary in a particular situation:', 'The new systems cut humans out of the picture altogether.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36700, 'out of the question', 'not possible or not allowed:', 'The class ends at 2, and leaving before then is out of the question.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36701, 'out of the running', 'having no chance of being successful in a competition or election:', 'He wasn''t able to raise enough money for his campaign and declared himself out of the running.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36702, 'out of the woods', 'not having a problem or difficulty any longer:', 'It''s too soon to say if either airline is out of the woods yet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36703, 'out of thin air', 'from nothing:', 'I can''t come up with €10,000 out of thin air.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36704, 'out of this world', 'extremely good:', 'What a restaurant - the food was out of this world!', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36705, 'out of touch', 'not informed or not having the same ideas as most people about something, so that you make mistakes:', 'A few of the older teachers are completely out of touch with their students.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36706, 'out of your depth', 'not having the knowledge, experience, or skills to deal with a particular subject or situation:', 'I was out of my depth in the advanced class, so I moved to the intermediate class.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36707, 'out of your depth', 'in water that is so deep that it goes over your head when you are standing:', 'I''m not a strong swimmer, so I prefer not to go out of my depth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36708, 'out of your league', 'doing something that you are not skilled enough to do, esp. compared to other people doing the same thing:', 'She has been working very hard on the project, but I think she''s a little out of her league.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36709, 'out of your mind', 'unable to behave or deal with things normally because something has made you very worried, unhappy, or angry:', 'She was out of her mind with grief.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36710, 'out of your mind', 'extremely stupid or mentally ill:', 'You must be out of your mind paying £500 for one night in a hotel!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36711, 'out of your mind/head', 'extremely silly:', 'He must be out of his mind to have spent that much money on an old car!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36712, 'out of/from the corner of your eye', 'If you see something out of/from the corner of your eye, you see it but not clearly because it happens to the side of you:', 'I saw something move out of the corner of my eye.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36713, 'out on a limb', 'having an opinion that is different from most people''''s and is unpopular:', 'She''s going out on a limb in criticizing her own party leadership.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36714, 'out on your arse', 'a rude phrase meaning having been forced to leave a job or place, especially because you have done something wrong:', 'He''s doing well in the company now, but there was a time he was almost out on his arse.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36715, 'out on your ass', 'a rude phrase meaning having been forced to leave a job or place, especially because you have done something wrong:', 'You have one month to improve, or you''ll be out on your ass.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36716, 'out to lunch', 'infmlslightly crazy or not thinking clearly:', 'You must have thought I was completely out to lunch when I forgot about meeting you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36717, 'out with it!', 'said to someone when you want that person to tell you something that they do not want you to know:', 'What did he do then? Come on, out with it!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36718, 'out/up the wazoo', 'in large quantities:', 'We have tourists here out the wazoo.', 'idiom', NULL, NULL, 'very informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36719, 'outlive your usefulness', 'to no longer be useful:', 'This old system has outlived its usefulness.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36720, 'over and over (again)', 'happening or done many times:', 'I read the article over and over till it made sense.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36721, 'over my dead body', 'If you say something will happen over your dead body, you mean that you will do everything you can to prevent it:', '"Joe says he''s going to buy a motorbike." "Over my dead body!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36722, 'over the hill', 'used for describing someone who is old and no longer useful or attractive', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36723, 'over the odds', 'more than something is really worth:', 'It''s a nice enough car but I''m sure she paid over the odds for it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36724, 'over the top', 'too extreme and not suitable, or demanding too much attention or effort, especially in an uncontrolled way:', 'I thought the decorations were way (= very) over the top.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36725, 'over your head', 'too difficult or strange for you to understand:', 'I tried to take in what he was saying about nuclear fusion, but most of it went over my head.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36726, 'over-egg the pudding', 'to make something seem larger, more important, better, or worse than it really is:', 'We all know insurance claimants who have over-egged the pudding to increase their payouts.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36727, 'over-egg the pudding', 'to spoil something by trying too hard to improve it:', 'There are some great moments, but the writer tends to over-egg the pudding with metaphors and similes when all she''s describing is a group of women getting through the day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36728, 'overfocus on someone/something', 'to give too much attention to one particular person, subject, or thing:', 'We don''t believe you can over-focus on this problem.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36729, 'overplay your hand', 'to spoil your chance of success by saying or doing too much', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36730, 'overstep the mark', 'to behave in a completely unacceptable way:', 'You''ve overstepped the mark this time, Simpson - you''re fired!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36731, 'owe a debt of gratitude/thanks', 'to have a reason to thank or feel grateful to another person for something good that they have done:', 'There are no words that can express the debt of gratitude that future generations will owe them for their sacrifices.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36732, 'owe it to someone to do something', 'to have a duty to do something for someone:', 'We owe it to our students to prepare them well for college.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36733, 'you owe it to yourself to do something', 'you deserve to do something:', 'You owe it to yourself to take a long vacation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36734, 'owe it to yourself', 'to deserve and need to do something that will be good for you:', 'Take a few days off work - you owe it to yourself.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36735, 'owe someone a living', 'If you say that someone thinks that people owe him or her a living, you mean that that person thinks that he or she deserves to be paid without having to work hard for it:', 'He seems to think the world owes him a living.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36736, 'own up', 'to admit that you have done something wrong:', 'No one has owned up to stealing the money.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36737, 'pace something off/out', 'to measure a distance by taking steps of equal size across it and counting them:', 'You can get a rough idea of the size of the room by pacing it out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36738, 'pack a punch', 'to have a lot of force or a great effect:', 'His speech packed quite a punch.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36739, 'pack it in', 'infml to stop doing something:', 'When it started to rain again, we decided to pack it in and go home.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36740, 'pack someone off', 'to send someone to another place:', 'We''ve packed the kids off for the weekend.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36741, 'pack something away', 'to put something into a bag or container, or to put something in the place where it is usually kept:', 'Come on, children, it''s time to pack away your toys.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36742, 'pack something away', 'to eat a lot of food:', 'She''s tiny but she can really pack away the biscuits.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36743, 'pack something in', 'to stop doing something:', 'This course is really tough - sometimes I feeling like packing it all in.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36744, 'pack something in', 'said to rudely tell someone to stop doing something that is annoying you:', 'Pack it in, Julie - I''m trying to read.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36745, 'pack someone in', 'to end your relationship with someone, or to stop meeting or spending time with them:', '"Is Emma still seeing Joe?" "No, she''s packed him in."', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36746, 'pack someone in', 'If an entertainment or exhibition packs people in, a large number of people come to see it:', 'Spielberg''s new film is packing in the crowds.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36747, 'pack something/someone in', 'to manage to include a large number of things, activities, or people:', 'We were only there four days but we packed a lot in.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36748, 'pack something into something', 'to manage to do a lot of activities in a limited period of time:', 'We packed a lot of sightseeing into our weekend in New York.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36749, 'pack something/somewhere out', 'to make a place very full:', 'Around 100,000 football fans packed out the stadium to see the game.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36750, 'pack sth with sth/sb', 'to fill something with things or people of a particular type:', 'We have packed the conference with an exciting line-up of interesting speakers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36751, 'pack up', 'If a machine packs up, it stops operating:', 'My camera has packed up.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36752, 'pack up (something)', 'to stop working or doing another regular activity:', 'She packed up her job, and went off to Australia.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36753, 'pack (something) up', 'to collect all your things together when you have finished doing something:', 'I''m about to pack up my things and go home.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36754, 'packed/squashed like sardines', 'If people are packed or squashed like sardines, they are positioned very close together so that they cannot move:', 'We were squashed like sardines in the rush-hour train.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36755, 'pad something out', 'If you pad out a speech or piece of writing, you add unnecessary words or information to make it longer or to hide the fact that you are not saying anything very important.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36756, 'paddle your own canoe', 'If you describe a person as paddling their own canoe, you mean that they are independent and do not need help from anyone else.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36757, 'page through sth', 'to go from one page to the next in a book or newspaper, or on a computer screen:', 'The presenter paged through her slides with a remote control.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36758, 'paint a black picture of something/someone', 'to describe a situation or person as extremely bad', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36759, 'paint a picture (of something)', 'to describe something in a particular way:', 'The statistics do not paint an optimistic picture.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36760, 'paint a picture (of something)', 'to describe or show something in a particular way:', 'The statistics do not paint an optimistic picture.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36761, 'paint the town red', 'to go out and enjoy yourself by drinking alcohol, dancing, laughing with friends, etc.:', 'I''m ready to paint the town red with a few of my closest friends.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36762, 'painting by numbers', 'a simple way of painting a picture by filling in a printed drawing that has numbered sections for the different colours of paint:', 'The grid evokes childhood memories of painting by numbers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36763, 'painting by numbers', 'something that is very easy to do and does not need skill:', 'Business is not that simple; it is not a matter of painting by numbers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36764, 'pair off', 'to begin a romantic or sexual relationship with someone:', 'All my friends seem to be pairing off and getting married.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36765, 'pair someone off', 'to introduce two people to each other so that they will start a romantic relationship:', 'I managed to pair my best friend Sue off with Mike.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36766, 'pair (someone) off', 'If a group of people pair off, they divide into pairs in order to do something, and if you pair them off, you divide them into pairs:', 'The students paired off to practise their conversational skills.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36767, 'pair up', 'to join together temporarily with another person in order to do something:', 'Everyone should pair up for the next dance.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36768, 'pal around', 'to spend time with someone that you are very friendly with:', 'He used to pal around with one of the president''s sons.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36769, 'pal up', 'to become friends with someone:', 'I''ve palled up with some people from work and we''re going on holiday together.', 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36770, 'pale in comparison', 'to seem much less serious or important when compared with someone or something else:', 'I thought I was badly treated but my experiences pale in comparison with yours.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36771, 'pale in comparison (with something/someone)', 'to be not nearly as good as something or someone else:', 'The paintings he made later pale in comparison with his earlier work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36772, 'pale into insignificance', 'to seem not important when compared with something else:', 'Everything else that happened in my life pales into insignificance beside that one event.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36773, 'palm someone off with something', 'to give someone an untrue or unsatisfactory answer, or to give someone something that has no value in order to try to satisfy them and make them go away:', 'You''re not going to palm me off with that feeble excuse.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36774, 'palm something off', 'to give away something, or persuade someone to accept something, because you do not want it and you know it has no value:', 'She tried to palm her old car off on me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36775, 'pan out', 'to develop in a particular way or in a successful way:', 'We''ll have to see how things pan out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36776, 'pander to someone/something', 'to do or provide exactly what a person or group wants, especially when it is not acceptable, reasonable, or approved of, usually in order to get some personal advantage:', 'It''s not good the way she panders to his every whim.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36777, 'pant for/after someone/something', 'to want someone or something very much:', 'The newspapers are panting for details of the scandal.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36778, 'paper over something', 'to hide an unpleasant situation, especially a problem or disagreement, in order to make people believe that it does not exist or is not serious:', 'He tried to paper over the country''s deep-seated problems.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36779, 'paper over the cracks', 'to hide problems, especially arguments between people, in order to make a situation seem better than it really is:', 'She tried to paper over the cracks, but I could see that the relationship was failing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36780, 'par for the course', 'what should be expected because of past experience:', 'The school budget is going to be cut again this year, but then that’s par for the course.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36781, 'parcel something out', 'to divide something and give the separate parts to different people:', 'The bigger farms were parcelled out after the revolution in 1973.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36782, 'parcel something up', 'to wrap something and make it into a parcel:', 'Parcel up the books and we''ll send them off tomorrow.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36783, 'parcel sth off', 'to get rid of something:', 'parcel sth off to sb Human Resources administrators were considering plans to parcel health services off to a private provider.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36784, 'pardon (me)', 'used to say that you are sorry for doing something wrong or for being rude', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36785, 'pardon me for breathing/existing/living!', 'used to tell someone that you think they have just answered or spoken to you in an unreasonably critical or rude way:', '"If you''re going to get in my way, James, could you just leave the kitchen?" "Oh, pardon me for breathing!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36786, 'pare something (down) to the bone', 'to reduce something to a level at which only what is absolutely necessary is left', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36787, 'park the bus', 'If a football team parks the bus, it defends without trying to attack, with almost all of the players on the team staying deep inside their own half of the pitch.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36788, 'park up', 'to put a vehicle in a place where it can stay for some time:', 'We decided to park up for the night and sleep in the car.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36789, 'parlay sth into sth', 'to achieve success by using a small advantage or opportunity in an effective way:', 'They parlayed some modest investments into massive profits for the company.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36790, 'part company', 'If two people part company, they end their relationship:', 'The world''s number one tennis player and his coach parted company earlier this month.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36791, 'part of the furniture', 'something or someone so familiar that you no longer notice it, him, or her', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36792, 'part with something', 'to give something to someone else, especially when you do not want to:', 'I was going to give away her old baby clothes, but I couldn''t bring myself to part with them.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36793, 'partner up', 'to marry or form a long and serious relationship with another person:', 'All his friends were partnering up and settling down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36794, 'partner up', 'to act as someone''''s partner in a sport, game, dance, or activity:', 'They partner up and throw weighted medicine balls at each other.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36795, 'partner up', 'to join with another person or organization in a business activity:', 'Businesses partner up with local schools to offer work experience to students.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36796, 'pass (all) belief', 'to be (extremely) difficult to believe:', 'It passes all belief that he could have been so selfish.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36797, 'pass as someone/something', 'to be accepted as something:', 'She had to go out in the world and try to pass as a boy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36798, 'pass as/for sth/sb', 'to appear to be something or someone else, or try to make others believe that they are:', 'These watches are good-quality fakes, and would pass for the genuine article in a store.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36799, 'pass away', 'polite expression for
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36800, 'pass for sb/sth', 'to be accepted as something:', 'I really want to go and see the film, but I don''t think I''d pass for 18.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36801, 'pass judgment on someone/something', 'to express a strong opinion about someone or something:', 'Don’t pass judgment on Lori until you hear what happened.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36802, 'pass muster', 'to reach an acceptable standard:', 'New teams won''t be admitted to the league if their stadiums don''t pass muster.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36803, 'pass off', 'to happen:', 'The pop festival passed off peacefully, despite the fears of local residents.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36804, 'pass on', 'polite expression for
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36805, 'pass on something', 'to refuse an opportunity or decide not to take part in something:', 'He passed on the chance to be head coach and took a job in Florida.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36806, 'pass something on', 'to tell someone something that another person has told you:', 'If he provided us with any information, no one passed it on to me.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36807, 'pass something on', 'to give someone something that another person has given you:', 'Could you pass it on to Laura when you''ve finished reading it?', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36808, 'pass something on', 'to give a disease to another person:', 'It''s possible to pass on the virus to others through physical contact.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36809, 'pass out', 'to become unconscious for a short time, for example when ill, badly hurt, or drunk:', 'I was hit on the head and passed out.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36810, 'pass out', 'to leave a military college after successfully finishing the course:', 'The new officers passed out from Britannia Royal Naval College on Thursday 1 August .', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36811, 'pass something out', 'to give something to each person in a group of people:', 'The teacher passed out the test booklets.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36812, 'pass someone by', 'If an event or opportunity passes you by, you do not notice it, or get any pleasure or advantage from it:', 'Do you ever feel that life is passing you by?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36813, 'pass someone/something over', 'to ignore or not give attention to someone or something:', 'The woman alleges that her employers passed her over for promotion because she was pregnant.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36814, 'pass something around', 'to offer something to each person in a group of people:', 'Could you do me a favour and pass these sandwiches around?', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
