INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36835, 'patch into something', 'to connect to a device or network:', 'The team has the ability to patch into the Cleveland Clinic health care system for instant access to X-rays, MRIs, and other test results.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
