  (36836, 'patch something into something', 'to connect one device to another or to a network:', 'The cameras are patched into a computer that sees the video in real time and analyzes it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36837, 'patch someone through', 'to connect someone to a phone number or network:', 'I patched her through to customer service.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36838, 'patch something together', 'to arrange something very quickly but not very carefully:', 'There is much disagreement, but the group of countries is trying to patch together a treaty on defence.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36839, 'patch something up', 'to try to improve a relationship after there have been problems:', 'Jackie and Bill are still trying to patch up their marriage.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36840, 'patch something up', 'to repair something, especially in a simple and temporary way', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36841, 'patch someone/something up', 'to give basic medical care to someone that helps them temporarily:', 'If you''ve cut your hand, the first-aider will patch you up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36842, 'paths cross', 'If two people''''s paths cross, the people meet:', 'It was a pleasure meeting you - I hope our paths cross again.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
