INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36844, 'pave the way', 'If something paves the way for/to something else, it makes the other thing possible:', 'Scientists hope that data from the probe will pave the way for a more detailed exploration of Mars.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36845, 'pave the way (for something/someone)', 'to make it possible or easier for something or someone to follow:', 'Data from the space flight should pave the way for a more detailed exploration of Mars.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36846, 'paved with gold', 'used about a city to mean that it is easy to make money there:', 'Unemployed youngsters still come to London thinking that the streets are paved with gold.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
