INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36850, 'pay down something', 'to pay part of an amount that you owe, so that the debt is reduced:', 'She plans to live at home with her mother while she pays down her student loan.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
