INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36856, 'pay someone off', 'If your employer pays you off, they pay you for the last time and then end your job, because you are not needed or there is not enough money to pay you in the future.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36857, 'pay someone off', 'to give someone money so that they will not do or say something, or so that they will go away:', 'There were rumours that key witnesses had been paid off to keep quiet.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
