INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36883, 'pencil something/someone in', 'to arrange for something to happen or for someone to do something on a particular date or occasion, knowing that the arrangement might be changed later:', 'We''ll pencil in the dates for the next two meetings and confirm them later.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36884, 'pension someone off', 'to make someone leave a job and give them a pension:', 'Workers in the company are being pensioned off at 50.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36885, 'pension something off', 'to stop using something, usually a machine, because it is old and has been used too much:', 'After flying for 38 years, their Wessex helicopter is about to be pensioned off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36886, 'people something/somewhere by/with someone', 'If something or somewhere is peopled by/with a particular type of person, it is filled with them:', 'Her novels are peopled with the rich and beautiful.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36887, 'people who live in glass houses shouldn''''t throw stones', 'This means that you should not criticize other people for bad qualities in their character that you have yourself.', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36888, 'pep someone/something up', 'to make someone or something more energetic or interesting:', 'A good night''s sleep will pep you up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36889, 'pepper something with something', 'to hit something repeatedly with small objects:', 'The city''s walls were peppered with bullets.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36890, 'pepper something with something', 'If you pepper a speech or piece of writing with something, you include a lot of that particular thing:', 'The letter was peppered with exclamation marks.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36891, 'perform/work miracles/a miracle', 'to be extremely effective in improving a situation:', 'You''ve performed a miracle in this kitchen - I''ve never seen it so clean!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36892, 'perish the thought', 'said to show that you hope that something that has been suggested will never happen:', 'Me, get married? Perish the thought!', 'idiom', NULL, NULL, 'humorous, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36893, 'perk (someone) up', 'to become or cause someone to become happier, more energetic, or more active:', 'She perked up as soon as I mentioned that Charles was coming to dinner.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36894, 'perk up', 'to improve or become more exciting:', 'Prices perked up slightly before the close of trading.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36895, 'pertain to something', 'to be connected with a particular subject, event, or situation:', 'We are only interested in the parts of the proposals that pertain to local issues.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36896, 'peter out', 'to gradually stop or disappear:', 'The fighting which started in the night had petered out by morning.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36897, 'phase something in', 'to introduce something gradually or in stages:', 'They will phase the new healthcare system in over a period of five years.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36898, 'phase something out', 'to remove or stop using something gradually or in stages', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36899, 'phase sth down', 'to remove or stop using something gradually or in stages:', 'We are working to phase down the use of this dangerous gas.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36900, 'phone in', 'to phone the place where you work in order to tell your employer something:', 'She phoned in sick (= saying that she was ill) this morning.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36901, 'phone in', 'to phone a television or radio programme in order to express your opinion on a matter:', 'Over 300 people phoned in to complain.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36902, 'phone something in', 'If someone phones in a performance, they do it without any effort:', 'The actor phoned in his performance without a hint of personality.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36903, 'phone up', 'to call someone on the phone:', 'I''ll phone up and see if they have any tickets left.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36904, 'pick ''''n'''' mix', 'a system in a shop where you can choose a few of several different small things, especially sweets', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36905, 'pick a fight', 'to intentionally start a fight:', 'Some kids were teasing him, trying to pick a fight.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36906, 'pick a fight/quarrel/argument', 'to start a fight/quarrel/argument with someone:', 'He''d had too much to drink and tried to pick a fight with the bartender.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36907, 'pick and choose', 'to take only the things you want from a group:', 'You can''t pick and choose which rules you want to follow and which ones you don''t.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36908, 'pick at something', 'to eat only a small amount of your food, showing no interest or enjoyment while you eat it:', 'Charles picked at his food in a bored fashion.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36909, 'pick holes in something', 'to find mistakes in something someone has done or said, to show that it is not good or not correct', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36910, 'pick on someone', 'to criticize, punish, or be unkind to the same person often and unfairly:', 'He gets picked on by the other boys because he''s so small.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36911, 'pick on someone your own size', 'said to someone who wants to fight a person who is smaller than they are:', 'Just leave me alone, will you? Why don''t you go and pick on someone your own size?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36912, 'pick over something', 'to look carefully at a group of things, choosing the ones you want or getting rid of the ones you do not want:', 'All the clothes at the sale had been thoroughly picked over and there was nothing nice left.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36913, 'pick someone up on something', 'to criticize someone about something they have said:', '"I want to pick you up on the point you made a few minutes ago about personal morality, Archbishop."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36914, 'pick up on something', 'to start talking again about something that someone said previously:', 'Can I just pick up on your first point again, please?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36915, 'pick up on something', 'to notice something that other people have not noticed:', 'Only one newspaper picked up on the contradictions in the statement.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36916, 'pick someone''''s brain', 'to ask someone who knows a lot about a subject for information or their opinion:', 'Can I pick your brain about how you got rid of those weeds?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36917, 'pick someone''''s brains', 'to ask someone who knows a lot about a subject for information or their opinion:', 'I was picking Simon''s brains about which computer to buy.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36918, 'pick someone''''s pocket', 'to steal small objects, especially money, from someone''''s pockets or bag', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36919, 'pick someone/something off', 'to shoot at one particular person, animal, or vehicle that you have chosen from a group:', 'The snipers picked the soldiers off one by one as they ran for cover.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36920, 'pick someone/something off', 'to take the best person or thing from a group:', 'It is relatively easy for newcomers to pick off the most lucrative business and ignore the rest.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36921, 'pick someone/something out', 'to recognize, find, or make a choice among different people or things in a group:', 'Can you pick out the three deliberate mistakes in this paragraph?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36922, 'pick someone/something out', 'to choose and emphasize, make clearer, or highlight someone or something:', 'The ship''s name was picked out in bright gold letters along her stern.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36923, 'pick something out', 'If you pick out a tune, you play it slowly or with difficulty, note by note:', 'I can pick out a simple tune on the piano, but that''s about it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36924, 'pick someone/something up', 'to lift someone or something using your hands:', 'If she starts to cry, pick her up and give her a cuddle.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36925, 'pick someone/something up', 'to collect, or to go and get, someone or something:', 'When you''re in town could you pick up the books I ordered?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36926, 'pick something up', 'to learn a new skill or language by practising it rather than being taught it:', 'Don''t bother with the computer manual - you''ll pick it up as you go along.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36927, 'pick something up', 'to learn interesting or useful information from someone or something:', 'The nurse had picked up the information from a conversation she overheard.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36928, 'pick something up', 'to buy something cheaply:', 'She picked up some real bargains in the sale.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36929, 'pick something up', 'to win or get a prize or something that gives you an advantage, such as votes or support:', 'The People''s Front expect to pick up a lot more votes in this year''s elections.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36930, 'pick something up', '(of a piece of electrical equipment) to receive a signal:', 'Can you pick up (= receive broadcasts from) Moscow on your radio?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36931, 'pick something up', 'to notice and react to something:', 'Police dogs picked up the scent of the two men from clothes they had left behind.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36932, 'pick something up', 'to catch an illness from someone or something, caused by bacteria or a virus:', 'He picked up malaria when he was visiting the country on business.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36933, 'pick (something) up', 'to start something again after an interruption:', 'The author picks the same theme up again on page ten.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36934, 'pick someone up', '(of the police) to stop someone and take them to a police station in order to be questioned or arrested:', 'He was picked up by the police for drug dealing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36935, 'pick someone up', 'to start a sexual or romantic relationship with someone you do not know, by talking to that person and giving them a lot of attention:', 'He said he''d picked the woman up in a bar.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36936, 'pick up', 'to increase or improve:', 'The truck picked up speed slowly.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36937, 'pick up', 'to answer the phone:', 'I tried his home number but he didn''t pick up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36938, 'pick through something', 'to look at the things in a group and take only what you want:', 'I had to pick through the rubbish to find my electricity bill.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36939, 'pick up steam', 'to start working or producing at a faster rate or more effectively:', 'After a slow start, the project began to pick up steam.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36940, 'pick up the bill/tab', 'to pay for what has been bought, especially a meal in a restaurant', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36941, 'pick up the phone', 'to make a phone call to someone:', 'If you need me, you just have to pick up the phone.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36942, 'pick up the pieces', 'to try to return to a satisfactory situation:', 'The fire was a blow, but we were determined to pick up the pieces and get the business back on its feet.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36943, 'pick up the slack', 'to improve a situation by doing something that someone else has not done or not completed:', 'With our best player injured, other players have to pick up the slack.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36944, 'pick up the tab (for something)', 'to pay for something, esp. for what someone else has bought or used:', 'The company will pick up the tab for this trip.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36945, 'pick up the thread(s)', 'to start again after an interruption:', 'Picking up the threads of our discussion, let''s return to the topic of factory farming.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36946, 'pick up/take the ball and run with it', 'to continue an activity or process that someone else has started, often when that person could not finish it or make it work:', 'We had a very vague idea of what we wanted, but the marketing team just took the ball and ran with it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36947, 'pick up/take up the slack', 'to do the work that someone else has stopped doing but still needs to be done:', 'If Sue gets a job, Mike will have to take up the slack at home.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36948, 'pick your way somewhere', 'to walk carefully and slowly:', 'Charlie picked his way through the muddy field.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36949, 'pick yourself up off the floor', 'to make improvements to your life after a bad period', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36950, 'pick/pull someone/something to pieces', 'to criticize someone or something severely:', 'The moment she left, the rest of the family started to pull her to pieces.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36951, 'pie in the sky', 'something that you hope will happen but is very unlikely to happen:', 'Their plans to set up their own business are just pie in the sky.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36952, 'piece something together', 'to create something by joining the separate parts of it together or by joining different things together:', 'The ancient skull has been pieced together from fragments.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36953, 'pig out', 'to eat a lot or too much:', 'We pigged out on all the delicious cakes and pastries.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36954, 'pigs can fly', 'said when you think that there is no chance at all of something happening:', '"I''ll have finished it by tomorrow." "And pigs can fly!"', 'idiom', NULL, NULL, 'humorous, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36955, 'pigs might fly', 'said when you think that there is no chance at all of something happening:', '"I''ll have finished it by tomorrow." "And pigs might fly!"', 'idiom', NULL, NULL, 'humorous, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36956, 'pile (something) up', 'to form a pile, or to put a lot of things into a pile', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36957, 'pile (something) up', '(of something bad) to increase:', 'Unpaid bills began to pile up alarmingly.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36958, 'pile it high and sell it cheap', 'to sell large amounts of a product at cheap prices', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36959, 'pile it on', 'to say too much, especially giving too much emphasis:', 'You''re really piling it on with the compliments tonight, Gareth, aren''t you!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36960, 'pile on', 'to increase quickly:', 'After she had the heart attack, the pounds piled on, and her weight rose to 15 stone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36961, 'pile something on', 'to make something increase quickly:', 'I''d given up smoking, but I piled on weight as a result, which was a bad thing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36962, 'pile on the agony', 'to enjoy emphasizing how bad a situation is:', 'Okay, I''ll give you some money - just stop piling on the agony.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36963, 'pile on the pounds', '(of a person) to gradually get heavier and fatter:', 'She did slim down a couple of years ago but has piled on the pounds again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36964, 'pile something onto someone', 'to give someone a lot, or too much, of something:', 'Management was strict but fair and the hardest part of the job was probably keeping up with everything they piled onto me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36965, 'pin back your ears', 'to listen carefully', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36966, 'pin someone down', 'to stop someone from escaping by surrounding and shooting at them if they try to escape:', '[ often passive ] Government forces were pinned down by resistance fighters 30 miles north of the capital.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36967, 'pin someone down', 'to make someone provide details about something or make a decision about something:', 'I''ve tried asking Stephanie, but she''s proving difficult to pin down to a particular date.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36968, 'pin something down', 'to discover exact details about something:', 'We can''t pin down where the leak came from.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36969, 'pin something on someone', 'to blame someone for something, especially for something they did not do:', 'You can''t pin the blame on her - she wasn''t even there when the accident happened.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36970, 'pin your hopes on something/someone', 'to hope very much that something or someone will help you to achieve what you want', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36971, 'pinch pennies', 'to spend as little money as possible:', 'When we were first married we had to pinch pennies just to get by.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36972, 'pine for something/someone', 'to want or miss something or someone very much:', 'He''s still pining for his ex-girlfriend.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36973, 'pipe down', 'to stop talking or making unnecessary noise:', 'Will you please pipe down, you two? I''m trying to read!', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36974, 'pipe up', 'to suddenly start to speak or make a noise:', 'In the silence that followed, a lone voice piped up from the back of the room.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36975, 'pique someone''''s curiosity, interest, etc.', 'to make someone interested in something and want to know more about it:', 'The noise continued, piquing her curiosity.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36976, 'piss (someone) about/around', 'to behave in a stupid way or to treat someone badly:', 'Look, we don''t have much time, so stop pissing about.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36977, 'piss down', 'to rain heavily:', 'It''s really pissing (it) down here at the moment.', 'phrasal verb', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36978, 'piss off', 'to leave or go away; used especially as a rude way of telling someone to go away:', 'Everyone just pissed off and left me to clean up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36979, 'piss someone off', 'to annoy someone:', 'He never helps with the housework and it''s starting to piss me off.', 'phrasal verb', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36980, 'piss something away', 'to waste an opportunity:', 'This is your last chance to win the league so don''t piss it away.', 'phrasal verb', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36981, 'piss yourself (laughing)', 'to laugh very much:', 'There I was writhing in agony on the floor and you were all pissing yourselves laughing!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36982, 'piss/shit your pants', 'to suddenly feel very frightened:', 'I shit my pants when all the lights went out.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36983, 'pissed as a newt/fart', 'very drunk', NULL, 'idiom', NULL, NULL, 'UK', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36984, 'pit of your stomach', 'the part of the body in which people say they feel fear or nervousness:', 'I got a sick feeling/a knot in the pit of my stomach when the news of the attack was announced.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36985, 'pit someone/something against someone/something', 'to cause one person, group, or thing to fight against or be in competition with another:', 'It was a bitter civil war, that pitted neighbour against neighbour.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36986, 'pit your wits against someone/something', 'to see if you can be cleverer than someone or something:', 'Would you like to pit your wits against our quiz champion?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36987, 'pitch in', 'to start to do something as part of a group, especially something helpful:', 'If we all pitch in together, it shouldn''t take too long.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36988, 'pitch into someone/something', 'to criticize or attack someone or something forcefully:', 'He pitched into me as soon as I arrived, asking where the work was.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36989, 'pitch up', 'to arrive in a place:', 'Gerald finally pitched up two hours late.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36990, 'pitchfork someone into something', 'to cause someone suddenly to be in a particular situation, usually a difficult one, especially when they are not ready:', 'Her father died when she was 22, and she was pitchforked into the running of the estate.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36991, 'plan on doing something', 'to intend to do something:', 'We were planning on just having a snack and catching the early train.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36992, 'plan on someone/something doing something', 'to realize that someone might do something or that something might happen and to make arrangements to deal with the situation:', 'They hadn''t planned on the whole family coming.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36993, 'plan something out', 'to think about and decide what you are going to do or how you are going to do something:', 'I''ve planned out the day - some shopping, then a meal and a show.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36994, 'plant something out', 'to put a plant into the ground outside to continue growing:', 'Plant out the geraniums in early June.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36995, 'plate something up', 'to put food onto plates, so that one plate of food can be served to each person in a group:', 'Will you collect the soup bowls while I plate up the main course?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36996, 'play (it) safe', 'to be careful and not take risks:', 'To play safe, I''d allow an extra ten minutes, just in case.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36997, 'play (merry) hell with something', 'to seriously damage or confuse something:', 'The power cuts played hell with our computers.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36998, 'play (something) by ear', 'to play a piece of music by remembering the notes:', 'He did not need sheet music. He could play the piece by ear.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (36999, 'play God', 'to act as if you are in total control of something:', 'Genetic engineers should not be allowed to play God, interfering with the basic patterns of Nature.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37000, 'play a joke/trick on someone', 'to confuse someone or cause problem for them:', 'I thought I heard something - my ears must have been playing tricks on me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37001, 'play along', 'to do what someone asks you to do, for a limited period of time:', 'I know you don''t like Jack''s idea, but just play along with him for a while.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37002, 'play around', 'to behave in a silly way:', 'Stop playing around and get on with your homework!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37003, 'play around', 'If someone who is married or has a serious relationship plays around, they have sex with another person or people:', 'If she finds out he''s been playing around with his secretary, there''ll be trouble.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37004, 'play around with something', 'to try out different methods or different things, before deciding which one to choose:', 'We''ve been playing around with ideas for a new TV show.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37005, 'play at something', 'to pretend to be a particular person or to do a particular thing, usually as a game:', 'The children were playing at Batman and Robin.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37006, 'play at something', 'to do something for enjoyment or interest, or without much care and effort, rather than in a serious way or as a job:', 'She''s only playing at being an actress - she''s going off to law school next year.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37007, 'play ball', 'to agree to work with or help someone in the way they have suggested:', 'The family wanted him to be taken care of at home, but the insurance company refused to play ball.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37008, 'play big', 'to take risks and not allow problems and unpleasant feelings to stop you from achieving what you want to achieve :', 'I have always played big in my career.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37009, 'play big', '(in sport) to play very well:', 'Zidane always played big when it counted.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37010, 'play big', 'to be given a lot of attention or importance:', 'The two reports played big on television.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37011, 'play both ends against the middle', 'to try to get opposing people or groups to fight or disagree so that you will get an advantage from the situation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37012, 'play cat and mouse', 'to try to defeat someone by tricking that person into making a mistake so that you have an advantage over them:', 'The 32-year-old singer spent a large proportion of the week playing cat and mouse with the press.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37013, 'play chicken', 'to play dangerous games in order to discover who is the bravest', NULL, 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37014, 'play dirty', 'to behave dishonestly, especially by cheating in a game:', 'Don likes hockey, but he plays dirty.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37015, 'play fair', 'to act in a fair and honest way:', 'It wasn''t really playing fair not to tell her the job was already filled.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37016, 'play fast and loose with something/someone', 'to treat something or someone without enough care:', 'Like many movie-makers, he plays fast and loose with the facts to tell his own version of the story.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37017, 'play footsie', 'to touch someone''''s feet with your own under the table, usually in order to show sexual interest in the person:', 'She kicked off her shoes and started playing footsie with him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37018, 'play for time', 'to delay until you are ready:', 'We can''t sign the agreement yet - we''ll have to play for time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37019, 'play games', 'to try to deceive someone:', 'Don''t play games with me!', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37020, 'play gooseberry', 'to be an unwanted third person who is present when two other people, especially two people having a romantic relationship, want to be alone', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37021, 'play hard to get', 'to pretend that you are less interested in someone than you really are as a way of making them more interested in you, especially at the start of a romantic relationship:', 'Why won''t you call him back? Are you playing hard to get?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37022, 'play hardball', 'to be firm and determined in order to get what you want:', 'He''s a nice guy, but he can play hardball when he needs to.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37023, 'play havoc with', 'to make a situation much more difficult or confusing:', 'The snowstorm is really playing havoc with rush-hour traffic.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37024, 'play havoc with', 'to damage something:', 'The acid rain plays havoc with marine life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37025, 'play hooky', 'to stay away from school without permission:', 'They played hooky and went fishing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37026, 'play in the hole', 'in football, to play in the central area of the playing field, immediately in front of the defenders and behind the other midfielders and forwards:', 'Although Mulumbu plays most of the game in the hole, he pushes into the box to support the strikers whenever possible.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37027, 'play it by ear', 'to decide how to deal with a situation as it develops, rather than acting according to plans made earlier:', 'We can''t make a decision yet. Let''s just play it by ear.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37028, 'play it cool', 'to behave in a calm, controlled way, often intentionally appearing not to be interested in the thing that you very much want to get:', 'Play it cool - don''t let them know how much you need the money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37029, 'play it straight', 'to do something seriously, without making jokes or demanding too much attention :', 'It would be easy enough to make fun of much of this, but Barber wisely plays it straight.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37030, 'play it straight', 'to do something honestly:', 'I hope for your sake you''re playing it straight.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37031, 'play off', 'to play a game, in a team sport, to decide which side will win:', 'United and Rangers are playing off for the championship.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37032, 'play on words', 'a humorous use of a word with more than one meaning or that sounds like another word:', 'The name of the shop - "Strata Various" - is a play on words, because it sounds like Stradivarius, the famous violin maker.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37033, 'play on/upon something', 'If you play on/upon someone''''s feelings, you encourage and make unfair use of these feelings in order to give yourself an advantage:', 'I hate marketing strategies that play on people''s fears and prejudices.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37034, 'play politics', 'to use a situation or the relationships between people for your own advantage:', 'He accused councillors of playing politics with children''s education.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37035, 'play possum', 'to pretend to be dead or sleeping so that someone will not annoy or attack you:', 'I don''t think he''s really asleep. He''s playing possum.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37036, 'play second fiddle', 'to be less important or in a weaker position than someone else:', 'I''m not prepared to play second fiddle to Christina any more - I''m looking for another job!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37037, 'play silly buggers', 'to behave in a silly, stupid, or annoying way:', 'There''ll be a serious accident sooner or later if people don''t stop playing silly buggers.', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37038, 'play small', 'to avoid risks and actions that might cause problems or make you feel uncomfortable, with the result that you might not achieve what you want to achieve :', 'Playing small means our actions are motivated by our fears, insecurities, and low self-worth.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37039, 'play someone at their own game', 'to try to get an advantage over someone by using the same methods as they use:', 'If women want to succeed in business, they have to play men at their own game.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37040, 'play someone/something off against someone/something', 'to encourage one person or group to compete or argue with another, hoping to gain some advantage from this situation:', 'Management policy seemed to be to play one department off against another.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37041, 'play something back', 'If you play back something that has been recorded, you put it through a machine so that you can listen to it or watch it:', 'The message I recorded for the answering machine sounded terrible when I played it back.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37042, 'play something down', 'to make something seem less important or less bad than it really is:', 'Military spokespeople tried to play down the seriousness of the disaster.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37043, 'play something out', 'to pretend that an imaginary situation or event is really happening:', 'In the psychotherapy group, patients were free to play out their fantasies.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37044, 'play itself out', 'If a situation plays itself out, it develops until nothing more can happen, and it is no longer very important:', 'We were forced to stand back and let the crisis play itself out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37045, 'play out', 'When a situation plays out, it happens and develops:', 'The debate will play out in the media over the next week or two.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37046, 'play something up', 'to emphasize a particular quality or part of something, or make it seem more important than it really is, usually for your own advantage:', 'The official report plays up the likely benefits of the plan, but glosses over the costs.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37047, 'play (someone) up', 'to cause someone pain:', 'His knee''s been playing him up again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37048, 'play up', 'When children play up, they behave badly:', 'The boys have been playing up at school again.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37049, 'play up', 'If a machine plays up, it does not work as it should:', 'The starter motor was playing up again.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37050, 'play the field', 'to hold an interest in a number of people or things, especially to become romantically or sexually involved with a number of partners:', 'Becky''s not ready to settle down with one man - she enjoys playing the field too much.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37051, 'play the game', 'to behave fairly:', 'You should have told them - it wasn''t playing the game to keep it secret.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37052, 'play the race card', 'If someone accuses someone else of playing the race card, they think that person is trying to gain special treatment because of their race.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37053, 'play the race, gender, etc. card', 'to claim that you have been treated unfairly because of your race, sex, etc., in order to get an advantage:', 'His critics say he played the race card by accusing his opponents of conspiring to bring down an uppity black man.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37054, 'play the system', 'to use the rules of a system to get an advantage for yourself, in a way that is wrong or dishonest:', 'There are some really powerful people who are in it for self-interest, who kind of play the system for personal and institutional gain.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37055, 'play to the gallery', 'to behave in a way intended to make people admire or support you:', 'Politicians these days are more interested in playing to the gallery than exercising real influence on world events.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37056, 'play to the whistle', 'used to say that a football player should continue playing until the referee blows the whistle, rather than stop playing because he or she thinks the referee will award a foul, throw-in, etc.:', 'You always have to play to the whistle.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37057, 'play up to someone', 'to try to make someone like you and treat you well by behaving in a way you think will please them:', 'Julia knows how to play up to the supervisors - she can always get time off work when she wants it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37058, 'play with fire', 'to act in a way that is very dangerous and to take risks', NULL, 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37059, 'play with something', 'to consider an idea or plan:', 'Patricia and I were playing (around) with the idea/possibility of moving to Glasgow.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37060, 'play with something', 'to keep touching and moving something around with no purpose or interest:', 'Stop playing with your hair!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37061, 'play with yourself', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37062, 'play your cards right', 'to behave in a way that gives you an advantage or allows you to succeed at something:', 'If you play your cards right, you could make quite a lot of money out of this.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37063, 'please God', 'used to express a strong hope:', 'It''ll be finished by Christmas, please God.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37064, 'please yourself', 'to do whatever you choose to do, often used in a slightly rude way by someone who does not agree with or care about what you do:', '"I can''t stand this place - I''m going home." "Please yourself."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37065, 'pleased with yourself', 'happy and satisfied about something good that you have done or that has happened to you:', 'Simon''s looking very pleased with himself today.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37066, 'plough into something/someone', 'If a vehicle ploughs into something or someone, it hits the object or person with great force:', 'Many people were injured when the train came off the rails and ploughed into the bank.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37067, 'plough something into something', 'to invest money (= give money hoping to get more back) in a business, especially to help make it successful or to make more money:', 'They ploughed all their savings into their daughter''s business.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37068, 'plough on', 'to continue doing something although it is difficult or boring:', 'He could see that she didn''t like what he was saying, but he ploughed on (= continued talking) regardless.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37069, 'plough something back', 'to spend the money that a business has earned on improving that business:', 'All the profits are being ploughed back into the company.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37070, 'plough something back/in', 'to dig the roots and other remaining parts of a crop into the soil to make the soil more healthy', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37071, 'plough sth back in/plough sth back into sth', 'to spend the money that a business has earned on improving that business:', 'Profits are being ploughed back into the company to allow expansion.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37072, 'plough through something', 'to go through a substance or an area of something with difficulty:', 'We ploughed through the mud.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37073, 'plough through something', 'to finish reading, eating, or dealing with something with difficulty:', 'I''ve got an enormous pile of papers to plough through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37074, 'plow into something/someone', 'If a vehicle plows into something or someone, it hits the object or person with great force:', 'Many people were injured when the train came off the rails and plowed into the bank.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37075, 'plow on', 'to continue doing something although it is difficult or boring:', 'He could see that she didn''t like what he was saying, but he plowed on (= continued talking) regardless.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37076, 'plow something back', 'to spend the money that a business has earned on improving that business:', 'All the profits are being plowed back into the company.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37077, 'plow something back/in', 'to dig the roots and other remaining parts of a crop into the soil to make the soil more healthy', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37078, 'plow through something', 'to go through a substance or an area of something with difficulty:', 'We plowed through the mud.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37079, 'plow through something', 'to finish reading, eating, or dealing with something with difficulty:', 'I have an enormous pile of papers to plow through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37080, 'pluck at something', 'to pull something with your fingers again and again, using quick, small movements:', 'I felt a small hand plucking at my jacket.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37081, 'pluck something out of the air', 'to say something quickly, usually because a reply is expected, without having thought about it or made certain it is correct:', '"Where did you get those figures from?" "Oh, I just plucked them out of the air."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37082, 'pluck up your courage', 'to force yourself to be brave enough to do something, although you are frightened or worried about it:', 'He finally plucked up courage to ask her to marry him.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37083, 'plug (something) in/plug (something) into something', 'to connect an electrical device to an electrical system or device so that it can be used, by pushing its plug into a socket:', 'Of course the radio isn''t working - you haven''t plugged it in!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37084, 'plug (something/someone) into something', 'to make something or someone fit well or have good connections with something:', 'This new product line should be able to plug into our existing distribution network.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37085, 'plug into something', 'to get to know and receive information about something, or to start using or being involved in it:', 'Andy is really plugged into the popular music scene.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37086, 'plug away', 'to work hard and in a determined way, especially at something that you find difficult:', 'Katie has been plugging away at her homework for hours.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37087, 'plumb the depths', 'to reach the lowest point:', 'Roy plumbed the depths of despair when his wife left him.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37088, 'plump (someone/something) down', 'to sit down suddenly and heavily, or to put an object or child down suddenly and without taking care:', 'She plumped down next to me on the sofa.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37089, 'plump for something/someone', 'to choose something or someone, especially after taking time for careful thought:', 'I''m going to plump for the vegetable curry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37090, 'plump something up', 'to make something fuller or fatter:', 'She went round plumping up the cushions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37091, 'plunge (someone/something) into something', 'to suddenly experience a bad situation or unhappiness, or to make someone or something suddenly experience a bad situation or unhappiness:', 'The country was plunged into recession.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37092, 'plunge in/plunge into something', 'to suddenly start doing something actively or enthusiastically:', 'Two months before his exams, he suddenly plunged into his studies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37093, 'ply someone with something', 'to keep giving a person something, usually food or drink:', 'John''s been plying me with drinks all evening.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37094, 'ply someone with something', 'to keep giving someone work or forms to complete, or asking them questions:', 'We plied Charlie with questions about his trip round the world.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37095, 'poacher turned gamekeeper', 'someone whose behaviour is now the same as that he or she previously opposed:', 'He is the epitome of a poacher turned gamekeeper. Once commander of the whaling station, he now devotes his energy to saving the whale and other marine life of the area.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37096, 'point (something/someone) out', 'to make a person notice someone or something, sometimes by holding up one of your fingers towards him, her, or it:', 'If you see her, please point her out to me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37097, 'point something out', 'to tell someone about some information, often because you believe they do not know it or have forgotten it:', '[ + that ] He was planning to book a rock-climbing holiday, till I pointed out that Denis is afraid of heights.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37098, 'point someone towards/in the direction of something', 'to suggest that someone should do or buy a particular thing:', 'The salesman was trying to point us in the direction of the most expensive furniture in the showroom.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37099, 'point something up', 'to emphasize a problem or fact, so that people notice it more:', 'It was a badly researched documentary that glossed over important questions while pointing up trivial ones.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37100, 'point taken', 'used to say you accept what someone has said', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37101, 'point the finger at someone', 'to accuse someone of being responsible for something bad that has happened:', 'Unhappy tourists have pointed the finger at unhelpful travel agents.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37102, 'point the way', 'to show how something can be done better in the future:', 'Recent medical discoveries are already pointing the way to more efficient vaccines.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37103, 'point the way (to something)', 'to be among the first to show how something can be done:', 'The new research points the way to the development of better vaccines.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37104, 'point to/towards something', 'to make it seem likely that a particular fact is true or that a particular event will happen:', 'All the evidence points to suicide.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37105, 'poison someone''''s mind', 'to make someone believe unpleasant things about another person that are not true:', 'Don''t listen to her lies - she''s just trying to poison your mind against me.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37106, 'poke around', 'to search for something by moving things around, usually not in a very careful or organized way:', 'I was poking around in the drawer, looking for the key, when I found this!', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37107, 'poke around/about', 'to search through something, esp. without permission or without any particular idea of what you might find:', 'He loves going to auctions and poking around antique shops.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37108, 'poke fun at someone', 'to make someone seem stupid by making jokes about them or laughing unkindly', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37109, 'poke the bear', 'to intentionally make or try to make someone angry or offended, especially someone more powerful than you:', 'He attacked his colleagues for not wanting to poke the bear, referring to them not wanting to confront the president.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37110, 'poke/dig someone in the ribs', 'to push your finger quickly into someone''''s chest, usually to make them notice something or to stop them from doing or saying something', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37111, 'poles apart', 'completely opposite:', 'My sister and I are poles apart in personality.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37112, 'polish something off', 'to finish som ething quickly and easily, especially a lot of food or work:', 'He polished off the whole pie.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37113, 'polish something/someone off', 'to defeat a competitor easily:', 'Arsenal polished off Chelsea 5–0 in Saturday''s match.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37114, 'polish someone off', 'to kill someone:', 'He was accused of polishing off his former partner.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37115, 'polish something up', 'to rub or brush an object to make it shine, especially a metal or wooden object:', 'Robert was polishing up some old silver candlesticks.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37116, 'polish something up', 'to improve a skill, especially when you have allowed it to become less good over a period of time:', 'I really must polish up my Japanese before we visit Japan next year.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37117, 'ponce about/around', 'If a man ponces about/around, he behaves or dresses more like a woman than like a man:', 'He was poncing around in a pair of fluffy slippers.', 'phrasal verb', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37118, 'ponce about/around', 'to waste time doing silly things that do not achieve anything or help anyone:', 'There''s no time for poncing around - we need to get these boxes packed by this evening.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37119, 'pony up (something)', 'to pay (a particular amount of money) for something :', 'As well as putting up his own cash, he persuaded others to pony up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37120, 'poodle around (something)', 'to spend time doing things without any particular purpose or plan:', 'We spent the day poodling around town.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37121, 'poop out', 'to become too tired to continue what you are doing:', 'I just poop out if I stay up too late.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37122, 'poop out', 'to stop working or operating:', 'The engine pooped out before we reached our destination.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37123, 'poop someone out', 'to make someone very tired:', 'All that dancing has really pooped me out.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37124, 'poor man''''s...', 'used to refer to something that is a worse or cheaper version of something else that is mentioned:', 'Rugby union was turned into a poor man''s rugby league.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37125, 'poor relation', 'something or someone similar to but less important than another thing or person, and that people do not consider equally valuable:', 'The air force and navy were modernized but the army, very much the poor relation, was not.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37126, 'pop (something) in/into something', 'to put something quickly into something else:', 'Pop the CD-ROM into a personal computer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37127, 'pop (something) in/into something', 'Something that pops into your head/mind is an idea that you suddenly have:', 'He jotted down story ideas that popped into his head.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37128, 'pop in/into (somewhere)', 'to visit briefly:', 'Why don’t you pop in and see us this afternoon?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37129, 'pop in/into (somewhere)', 'If you pop into a place, you visit there briefly, usually for some purpose:', 'All I have to do on the way home is pop into the drugstore.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37130, 'pop off', 'to die:', 'You''re all just waiting till I pop off so you can get your hands on my money.', 'phrasal verb', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37131, 'pop someone off', 'to kill someone', NULL, 'phrasal verb', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37132, 'pop the question', 'to ask someone to marry you:', 'So did he pop the question, then?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37133, 'pop up', 'to move quickly and suddenly from a closed or flat position to a vertical one:', 'This tent pops up fully formed in a couple of seconds.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37134, 'pop up', 'to appear or happen, especially suddenly or unexpectedly:', 'She''s one of those movie stars who pops up everywhere, on TV, in magazines, on Broadway.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37135, 'pop your clogs', 'to die:', 'I think I''ll leave all my money to charity when I pop my clogs.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37136, 'pore over something', 'to look at and study something, usually a book or document, carefully:', 'She spends her evenings poring over textbooks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37137, 'portion something out', 'to share something:', 'We''ll have to portion the money out among/between the six of us.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37138, 'pose as someone', 'If you pose as a particular person, you pretend to be that person in order to deceive people:', 'He''s posing as her date, but he''s really her bodyguard.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37139, 'pot something off', 'to move a very young plant from a tray (= a container for several young plants), etc. and plant it in a pot:', 'As soon as it is possible to handle the seedlings, pot them off into small individual pots.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37140, 'pot something on', 'to plant a plant in a larger pot than the one it is in already:', 'Once two leaves appear, pot them on into 3.5-inch pots.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37141, 'pot something up', 'to put a plant into a container to grow:', 'The shoots from the shrub can be potted up and put in a warm place until they develop a good root system.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37142, 'pot something up', 'to plant a plant in a larger pot than the one it is in already:', 'The plants will probably need to be potted up after a few years.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37143, 'pot something up', 'to move a very young plant from a tray (= a container for several young plants), etc. and plant it in a pot:', 'Pot up the seedlings into 3 inch pots and keep them in a warm place.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37144, 'pounce on something', 'to immediately criticize a mistake:', 'He knows that his critics are waiting to pounce on any slip that he makes.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37145, 'pounce on something', 'to accept something quickly and with enthusiasm:', 'I think if she were given the opportunity to work here, she''d pounce on it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37146, 'pound away at something/someone', 'to criticize something or try to get someone to do something:', 'The campaigners have promised to keep pounding away at the council until the decision to build the road is reversed.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37147, 'pound of flesh', 'something that you have the right to receive but is unreasonable to demand from someone', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37148, 'pour oil on troubled waters', 'to do or say something in order to make people stop arguing and become calmer:', 'My husband''s always arguing with my father, and I''m the one who has to pour oil on troubled waters.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37149, 'pour scorn on someone/something', 'to say a person or thing is stupid and not worth anything:', 'Critics of the president have been pouring scorn on the plan ever since it was first proposed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37150, 'pour something into something', 'to give a lot of money or effort to something with the idea of making it successful:', 'Most of the money raised by the new taxes will be poured into the arena project.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37151, 'pour something out', 'to tell all your problems or feelings to someone, especially privately or secretly:', 'He spends every lunchtime pouring out his emotional problems to me and expects me to find a solution.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37152, 'pour your heart out', 'to tell someone your secret feelings and things that worry you, usually because you feel a strong need to talk about them:', 'I poured my heart out to him and then he told all his friends what I''d said.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37153, 'pour/throw cold water on something', 'to criticize someone''''s opinions or ideas and stop people believing them or being excited about them', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37154, 'powder your nose', 'a polite or humorous way of saying that you are going to go to the toilet:', 'Would you get me another drink while I go and powder my nose?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37155, 'power (something) down', 'If something that needs power or energy powers down, or if someone powers it down, it is turned off:', 'Power down your phone and remove the SIM.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37156, 'power (something) up', 'If something that needs power or energy powers up, or if someone powers it up, it is turned on or prepared so that it is ready for use or action:', 'The computer takes a few seconds to power up after it''s been switched on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37157, 'power through (something)', 'to continue in a strong and determined way until the end of something, even when this is difficult:', 'resilient companies that have powered through the economic downturn
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37158, 'practice makes perfect', 'said to encourage someone to continue to do something many times, so that they will learn to do it very well', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37159, 'practice what you preach', 'to do the things that you advise other people to do:', 'He''s such a hypocrite! He never practices what he preaches.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37160, 'practise what you preach', 'to do the things that you advise other people to do:', 'He''s such a hypocrite! He never practises what he preaches.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37161, 'prat about/around', 'to behave stupidly, especially when you should be behaving in a responsible way:', 'Stop pratting around and get on with your work!', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37162, 'preach to the choir', 'to try to persuade people who already agree with you:', 'The men who really need to hear the message don''t come to the meetings, so I''m just preaching to the choir.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37163, 'preach to the converted', 'to try to persuade people to believe things that they already believe:', 'You needn''t bother telling us how recycling helps the environment, because you''re preaching to the converted.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37164, 'predispose someone to/towards something', 'to make someone more likely to behave in a particular way or to suffer from a particular illness or condition:', 'Smoking predisposes you to lung cancer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37165, 'prepare the ground', 'If you prepare the ground for an activity or a situation, you do something that will help it to happen:', 'The leaders of both countries are preparing the ground for negotiations which may lead to peace.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37166, 'present company excepted', 'used to show that a criticism or a rude remark does not refer to the people you are talking to:', 'People here just don''t know how to dress, present company excepted.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37167, 'preside over something', 'to be in charge of a situation or place :', 'This government has presided over some of the most significant changes in education this century.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37168, 'press ahead (with something)', 'to continue to do something although there is opposition to it:', 'The company pressed ahead with plans to build the skyscraper.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37169, 'press ahead/on', 'to start or continue doing something in a determined way, although it is difficult:', 'press ahead/on with sth Most of the delegates said they wanted to press ahead with the talks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37170, 'press for something', 'to work hard to win support for a plan so that it will succeed:', 'He will press for stricter pollution controls.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37171, 'press home your advantage', 'to use an advantage that you already have in order to succeed', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37172, 'press on/ahead', 'to start or continue doing something in a determined way, often despite problems:', 'It was pouring with rain, but we pressed on regardless.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37173, 'press sb about/on sth', 'to try hard to persuade someone to tell you something:', 'Although he was pressed on the matter by journalists, the minister refused to disclose any further details.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37174, 'press something on someone', 'to give something to someone and not allow them to refuse to accept it:', 'All the children had sweets and presents pressed on them by the visitors.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37175, 'press something/someone into service', 'to use something or someone that is not completely suitable because nothing or no one more suitable is available:', 'The car''s broken down so I''ve had to press my old bike back into service.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37176, 'press the flesh', 'to shake hands with a lot of people:', 'Politicians have to get out and about and press the flesh.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37177, 'press/push someone''''s buttons', 'to cause a strong reaction or emotion in someone:', 'My brother knows exactly how to push my buttons (= annoy me).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37178, 'press/push the right button(s)', 'to do exactly what is necessary to get the result that you want:', 'You have to know how to push all the right buttons if you want to be a successful diplomat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37179, 'press/push/hit (all) the right buttons', 'to successfully cause a reaction or emotion in someone, especially when this makes them do what you want :', 'The coach has pushed the right buttons with his players this season.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37180, 'pretty much', 'almost completely:', 'I’ve pretty much finished packing now.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37181, 'pretty please', 'used for asking someone for something or persuading them to do something by trying to make yourself sound friendly:', 'Can we have one, too? Please! Pretty please!', 'idiom', NULL, NULL, 'spoken, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37182, 'prevail on/upon someone', 'to persuade someone to do something that they do not want to do:', 'He was eventually prevailed upon to accept the appointment.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37183, 'prevail on/upon someone to do something', 'to persuade someone to do something:', 'My father prevailed on some friends to let us stay with them.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37184, 'prevail upon/on sb', 'to persuade someone to do something that they do not want to do:', 'They finally prevailed on him to hand in his resignation.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37185, 'prevention is better than cure', 'It is better to stop something bad from happening than it is to deal with it after it has happened.', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37186, 'prey on sb''''s mind', 'If a problem preys on your mind, you think about it and worry about it a lot:', 'I lost my temper with her the other day and it''s been preying on my mind ever since.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37187, 'prey on something', 'If an animal preys on another animal, it catches and eats it:', 'The spider preys on small flies and other insects.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37188, 'prey on someone', 'to hurt or deceive a group of people, especially people who are weak or can easily be hurt or deceived:', 'He would attack at night, preying on lone women in their twenties or thirties.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37189, 'prey on/upon sb/sth', 'to harm somebody who is weaker than you are:', 'It is regrettable that such companies prey upon homeowners who are already experiencing financial difficulties.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37190, 'price someone out', 'to make someone unable to buy or pay for something because the price is too high:', 'Individuals earning the median hourly wage of $15.20 would qualify for a mortgage of $104,532 - effectively pricing them out of most homes in the area.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37191, 'price sth in', 'to include something in the total price of a product, etc.:', 'I''ve priced in the arrangement fees in the total cost of the mortgage.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37192, 'price yourself out of the market', 'If a company prices itself out of the market, it charges so much for a product or service that no one wants to buy it.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37193, 'prick (something) up', 'When an animal pricks its ears up, or when its ears prick up, it puts its ears up straight because it is listening carefully to a small sound or one that is far away.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37194, 'prick (something) up', 'If you prick up your ears, or if your ears prick up, you suddenly begin to listen very carefully because you have heard something interesting:', 'I overheard them mentioning my name and pricked up my ears.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37195, 'prick someone''''s conscience', 'to make someone do something because they feel guilty:', 'Dan''s mentioning Julia pricked my conscience and I gave her a call.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37196, 'prick the bubble (of something)', 'to make someone suddenly understand the unpleasant truth of a situation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37197, 'prick up your ears', 'to listen carefully:', 'The children pricked up their ears when they heard the word “candy.”', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37198, 'pride comes/goes before a fall', 'said to emphasize that if you are too confident about your abilities, something bad will happen that shows that you are not as good as you think', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37199, 'pride yourself on something', 'to value a skill or good quality that you have:', 'He prides himself on his loyalty to his friends.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37200, 'print something out', 'to produce a printed copy of a document that has been written on a computer:', 'Could you print out a copy of that letter for me?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37201, 'print sth out/off', 'to produce a printed copy of a document that has been written on a computer:', 'Could you print out a copy of that letter for me?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37202, 'prize something out of someone', 'to get something from someone with difficulty, especially information or money:', 'He''s so secretive - you''ll have a hard time prizing any information out of him.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37203, 'proceed against someone', 'to start to take legal action against someone:', 'Lack of evidence meant that the Council could not proceed against Mr Naylor.', 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37204, 'proceed to sth', 'to move forward to the next stage:', 'If the evidence stands, the case will proceed to trial.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37205, 'profit from something', 'to earn money from something:', 'Many companies will profit from the fall in interest rates.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37206, 'profit from something', 'to achieve an advantage from something:', 'I profited enormously from working with her.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37207, 'project an image', 'to represent yourself in a particular way through your speech, behavior, and appearance:', 'He’s trying to project a more confident image by dressing better.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37208, 'project an image', 'to represent yourself in a particular way through your speech, behavior, and appearance:', 'He’s trying to project a more confident image by dressing better.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37209, 'promise someone the earth/moon', 'to say that you will do much greater things than you will ever be able to achieve:', 'Like most governments in their first term of office, they promised the earth.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37210, 'promises, promises!', 'something that you say when someone says they will do something and you do not believe it:', '"When I''ve got some time I''ll show you everything." "Promises, promises!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37211, 'pronounce on/upon something', 'to give a judgment or opinion about something:', 'I''d rather not go pronouncing on a subject that I know so little about.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37212, 'prop something up', 'to lift and give support to something by putting something under it:', 'He was sitting upright in his hospital bed, propped up by pillows.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37213, 'prop something up', 'to give support to something, especially a country or organization, so that it can continue to exist in a difficult situation:', 'How long is the government likely to survive without the US military force there to prop it up?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37214, 'properly speaking', 'really:', 'It''s not, properly speaking, champagne but it is very similar.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37215, 'prophet of doom', 'someone who always expects bad things to happen:', 'The prophets of doom have been predicting the end of European cinema for the last ten years.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37216, 'protest too much', 'to express an opinion or fact so strongly or so often that people start to doubt that you are telling the truth:', 'She keeps trying to impress on me how she doesn''t like him but does she protest too much?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37217, 'provide against something', 'to make plans in order to prevent or deal with a bad situation:', 'Beach operators do not have a legal obligation to provide against injury or drowning.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37218, 'provide for someone', 'to give someone the things they need, such as money, food, or clothes:', 'He has a wife and two young children to provide for.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37219, 'provide for something', 'to make plans in order to deal with a possible event in the future:', 'We must provide for depreciation when calculating the costs.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37220, 'provide for something', 'If a law or agreement provides for something, it allows it to happen or exist:', 'Current legislation provides for the detention of those suspected of terrorism.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37221, 'psych someone out', 'to behave in a very confident or forceful way in order to make a competitor, especially in a sports event, feel less confident:', 'Both athletes were trying to psych each other out before the race.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37222, 'psych yourself up', 'to try to make yourself feel confident and ready to do something difficult:', 'I have to spend a little time on my own before I give a speech, psyching myself up.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37223, 'public enemy number one/no. 1', 'someone or something that many people do not like or approve of', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37224, 'puff something out', 'to make your chest or your face become bigger by filling it with air:', 'He puffed out his cheeks and sat back in his chair.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37225, 'puff up', 'If part of your body puffs up, it becomes bigger because it is infected or injured:', 'My leg puffed up all around the insect bite.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37226, 'puff someone/something up', 'to talk a lot about how excellent or important someone or something is, sometimes praising them or it more than is deserved:', 'The report puffs him up until he sounds like the chairman.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37227, 'puff something up', 'to become larger or full of air, or to make something become larger in this way:', 'When the crust is golden and puffed up, take the pie out of the oven.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37228, 'pull a fast one', 'to successfully deceive someone:', 'You paid too much - I think he pulled a fast one on you.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37229, 'pull a gun, knife, etc. on someone', 'to suddenly take out a weapon and threaten someone with it', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37230, 'pull a stunt', 'to do something silly and dangerous:', 'What did you want to pull a stupid stunt like that for?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37231, 'pull ahead', 'to start to do well or to do better than someone else:', 'It was slow at first, but we''re starting to pull ahead.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37232, 'pull at something', 'to pull something quickly and usually repeatedly:', 'The child pulled at his sleeve to get his attention.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37233, 'pull away', 'If a vehicle pulls away, it starts moving:', 'There was a roar and a cloud of smoke as the car pulled away from the traffic lights.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37234, 'pull away', 'If you pull away from someone who is holding you, you suddenly move your body backwards, away from them:', 'She pulled away just as he was about to kiss her.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37235, 'pull back', 'to move backwards or away from someone:', 'He leaned forward to kiss her but she pulled back.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37236, 'pull back', 'to decide not to do or involve yourself with something when you were previously going to:', 'The news is that the company intends to pull back from petrochemicals.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37237, 'pull back', '(of a military force) to move back from an attacking position:', 'After pulling back, the tanks waited for fighter planes and helicopter gunships to attack the building.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37238, 'pull back', '(of prices, rates, etc.) to become lower or less :', 'Stock prices pulled back within minutes of the Fed''s announcement, before resuming their rise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37239, 'pull back', 'If a person or team that is losing pulls back, they score a goal or win a point or some points. :', 'The Vikings pulled back to within 10 points at the break.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37240, 'pull someone back', 'to move soldiers, etc. back from an attacking position:', 'The regime has been pulling back its forces.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37241, 'pull something back', 'If a person or team that is losing pulls a goal back or pulls a point or points back, they score a goal or win a point or some points:', 'Martin Butler pulled back a goal on the stroke of halftime.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37242, 'pull in/pull into somewhere', 'If a vehicle pulls in or pulls into somewhere, it moves in that direction and stops there:', 'He pulled in at the side of the road.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37243, 'pull out', 'If a vehicle pulls out, it starts moving onto a road or onto a different part of the road:', 'A car pulled right out in front of me.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37244, 'pull (someone/something) out', 'If soldiers or military forces pull out or are pulled out, they move out of an area because they have been ordered to.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37245, 'pull (someone/something) out', 'to stop being involved in an activity or agreement:', 'He pulled out of the deal at the last moment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37246, 'pull out all the stops', 'to do everything you can to make something successful:', 'They pulled out all the stops for their daughter''s wedding.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37247, 'pull over', 'If a vehicle pulls over, it moves to the side of the road and stops:', 'Just pull over here, and I''ll get out and walk the rest of the way.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37248, 'pull rank', 'to use the power that your position gives you over someone in order to make them do what you want:', 'He doesn''t have the authority to pull rank on me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37249, 'pull someone in', 'If the police pull you in, they arrest you:', 'The police pulled in dozens of protesters during the demonstration.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37250, 'pull someone up', 'to tell someone that they have done something wrong:', 'She''s always pulling me up for/on/over my bad spelling.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37251, 'pull something up', 'to get information to show on a computer screen:', 'Click on a square to pull up an overview of the site with name, description, location, and domain.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37252, 'pull up', 'When a car or someone driving a car pulls up, the driver stops the car, often for a short time:', 'A car pulled up outside my house.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37253, 'pull someone up short', 'to surprise someone, often so that that person stops what they are doing:', 'Seeing her picture in the paper pulled me up short.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37254, 'pull up short', 'to stop suddenly in a vehicle:', 'A dog suddenly ran across the road and I had to pull up short.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37255, 'pull someone''''s leg', 'to try to persuade someone to believe something that is not true, as a joke:', 'Is it really your car or are you pulling my leg?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37256, 'pull something down', 'to destroy a building:', 'They pulled down the warehouse to build a new supermarket.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37257, 'pull someone down', 'If an illness or a difficult situation or experience pulls you down, it makes you feel unhappy or physically weak:', 'That virus she had two months ago really pulled her down - she still hasn''t fully recovered.', 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37258, 'pull down something', 'to earn a stated amount of money:', 'Between them they must be pulling down over $100,000 a year.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37259, 'pull something off', 'to succeed in doing something difficult or unexpected:', 'The central bank has pulled off one of the biggest financial rescues of recent years.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37260, 'pull off', 'If a vehicle pulls off, it starts moving:', 'The car pulled off and sped up the road.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37261, 'pull something on', 'to put on clothes quickly:', 'I pulled on my jeans and ran downstairs.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37262, 'pull on', 'to manage or deal with a situation:', 'Few of us can ever pull on with such meagre salaries.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37263, 'pull on', 'to have a friendly relationship with someone:', 'Radha and Rema come from different backgrounds but they pull on very well in office.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37264, 'pull something out of a/your hat', 'to do something unexpected that suddenly improves a bad situation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37265, 'pull something out of the bag/hat', 'to do something unexpected that suddenly improves a bad situation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37266, 'pull something/someone apart', 'to separate two things or people:', 'They went for each other with their fists and had to be pulled apart.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37267, 'pull something apart', 'to destroy something by tearing it into pieces', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37268, 'pull something apart', 'to say that something, usually a piece of work, is very bad:', 'The last essay I gave him he completely pulled apart.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37269, 'pull strings', 'to secretly use the influence you have over important people in order to get something or to help someone:', 'I may be able to pull a few strings if you need the document urgently.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37270, 'pull the other leg/one (it''''s got bells on)!', 'used when you do not believe what someone has just said:', 'Helen, mountain climbing? Pull the other one - she can''t even climb a ladder without feeling sick!', 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37271, 'pull the plug', 'to do something that prevents an activity from continuing, especially by no longer giving money to support it:', 'If the viewing figures drop much more, the TV network will probably pull the plug on the whole series.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37272, 'pull the rug out (from under someone)', 'to suddenly take away important support from someone:', 'The school pulled the rug out from under the city soccer league when they asked them to pay for using their field.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37273, 'pull the rug/carpet from under someone''''s feet', 'to suddenly take away help or support from someone, or to suddenly do something that causes many problems for them:', 'Do you sometimes just have the feeling that someone is trying to pull the rug from under your feet?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37274, 'pull the strings', 'to be in control of an organization, often secretly:', 'I want to know who''s pulling the strings around here.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37275, 'pull the wool over someone''''s eyes', 'to deceive someone in order to prevent them from discovering something', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37276, 'pull through (something)', 'to become well again after a serious illness, especially when you might have died:', 'They said the operation had been successful and they expected his wife to pull through.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37277, 'pull (someone) through (something)', 'to succeed in dealing with a difficult period, or to help someone do this:', 'He''d never have managed on his own, but his colleagues have pulled him through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37278, 'pull together', 'to work hard as a group in order to achieve something:', 'We don''t have much time but if we all pull together we should get the job done.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37279, 'pull something together', 'to manage with difficulty to collect enough money, information, etc. to produce a result:', 'If you can pull together sufficient funding, we are prepared to approve the project.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37280, 'pull yourself together', 'to become calm and behave normally again after being angry or upset:', 'Just pull yourself together. There''s no point crying about it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37281, 'pull up stakes', 'to take all the things that you own and go and live in a different place:', 'This is the fourth time in five years that we''ve had to pull up stakes.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37282, 'pull your socks up', 'to make an effort to improve your work or behaviour because it is not good enough:', 'He''s going to have to pull his socks up if he wants to stay in the team.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37283, 'pull your weight', 'to work as hard as other people in a group:', 'The others had complained that Sarah wasn''t pulling her weight.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37284, 'pull/get your finger out', 'to start working hard, especially after a period of low activity:', 'She''s really going to have to pull her finger out if she wants to finish before Friday.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37285, 'pull/haul yourself up by the/your (own) bootstraps', 'to improve your situation without any help from other people:', 'He left school at 15 and pulled himself up by his bootstraps to ultimately head up a company.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37286, 'pump iron', 'to lift heavy weights for exercise:', 'These days both men and women pump iron for fitness.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37287, 'pump someone up', 'to make someone feel more confident or excited:', 'He was offering them advice and trying to pump them up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37288, 'pump something up', 'to fill something with air using a pump:', 'Have you pumped up the balloons yet?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37289, 'pump something up', 'to increase something by a large amount:', 'The US was able to pump up exports.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37290, 'pump someone''''s hand', 'to shake someone''''s hand (= hold it and move it up and down, especially in order to greet that person)', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37291, 'pump something into something', 'to spend a lot of money trying to make something operate successfully:', 'They had been pumping money into the business for some years without seeing any results.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37292, 'pump something out', 'to remove water or other liquid from something using a pump:', 'We took turns pumping out the boat.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37293, 'pump something out', 'to produce words or loud music in a way that is repeated, forceful, and continuous:', 'The government keeps pumping out the same old propaganda.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37294, 'pump out something', 'If someone''''s stomach is pumped out, a poisonous substance is removed from it by being sucked through a tube:', 'She had to go to hospital to have her stomach pumped out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37295, 'pump sth in', 'to invest a lot of money in something:', 'We are not prepared to pump in extra funds without some form of guarantee.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37296, 'punch above your weight', 'If a country or business punches above its weight, it becomes involved in, or succeeds in, an activity that needs more power, money, etc. than it seems to have:', 'Singapore punches above its weight in the world economy.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37297, 'punch in', 'to use a special clock to record the time you start working:', 'I punched in at 8:00 a.m.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37298, 'punch something in', 'to enter information into a computer or other device, using keys or buttons:', 'Think before you punch in your credit card number.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37299, 'punch out', 'to use a special clock to record the time you leave work', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37300, 'punch someone''''s lights out', 'to hit someone repeatedly very hard', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37301, 'punch the clock', 'to put a card into a special machine to record the times you arrive at and leave work', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37302, 'punch the clock', 'to go to work every day:', 'After 17 years of punching the clock, he just disappeared one morning and was never heard from again.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37303, 'punt on something', 'to risk money by buying or supporting something, in the hope of making or winning more money:', 'Investors are punting on a big move in the stock market next week.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37304, 'punt on something', 'If you punt on something, you decide not to do or include it:', 'We punted on a motion that makes no sense.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37305, 'push (someone) toward(s) something', 'to try to do or achieve something, or to make someone more likely to do or achieve something:', 'It is hoped that these measures will push the nation towards recovery.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37306, 'push (something) forward', 'to continue doing something or making progress in something, with effort or enthusiasm:', 'Their research has pushed forward the frontiers of knowledge.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37307, 'push yourself forward', 'to try to make other people notice and pay attention to you:', 'She always seemed to be pushing herself forward and not giving anyone else a chance.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37308, 'push ahead', 'to continue with an activity in a determined or enthusiastic way, especially when it is difficult or makes you feel tired:', 'They have decided to push ahead with the legal action.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37309, 'push along', 'to leave:', 'Anyway, I''d better be pushing along now.', 'phrasal verb', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37310, 'push for something', 'to demand something repeatedly, or to take strong action to try to make it happen:', 'Local residents are pushing for the road to be made safer.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37311, 'push in', 'to rudely join a line of people who are waiting for something, by moving in front of some of the people who are already there:', 'I was about to get on the bus when two men pushed in in front of me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37312, 'push off', 'used to rudely tell someone to go away:', 'He told me to push off.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37313, 'push off', 'to push against the side of a pool, lake, or river in order to move your body or a boat away from the side:', 'He pushed off from the side of the pool and swam slowly to the other side.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37314, 'push on', 'to continue doing something, especially when this is difficult:', 'They are pushing on with their campaign for improved childcare facilities.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37315, 'push on', 'to continue travelling somewhere:', '"You''ve been driving for a long time - do you want to stop for a rest?" "No, we''re nearly there - let''s push on."', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37316, 'push someone around', 'to tell someone what to do in a rude or threatening way:', 'If you think you can push me around like that, you''re mistaken.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37317, 'push someone out', 'to make someone leave a job or stop being involved in an activity by being unpleasant or unfair to them:', 'I felt I was being pushed out of the job.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37318, 'push someone/something aside', 'to decide to forget about or ignore someone or something:', 'He claimed that he had been pushed aside (= not given a job) in favour of a younger person.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37319, 'push someone/something over', 'to push someone or something so that they fall to the ground:', 'Daddy, Matthew pushed me over.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37320, 'push something back', 'to delay something so that it happens later than planned:', 'The target date for construction has been pushed back.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37321, 'push something through', 'to cause a plan or suggestion to be officially accepted or put into use:', 'We are trying to push this deal through as quickly as possible.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37322, 'push something up/down', 'to cause the amount, number, or value of something to increase or be reduced:', 'Rising demand tends to push prices up, and falling demand pushes them down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37323, 'push sth down', 'to make something lower in level or amount:', 'Increased competition will push down prices.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37324, 'push the boat out', 'to spend a lot of money on celebrating something:', 'They really pushed the boat out for Annie''s wedding.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37325, 'push the envelope', 'to behave in more extreme ways, or to try new things that have not been acceptable or tried before:', 'Just like every other kid, I pushed the envelope. If I got away with being ten minutes late one night, I might be twenty minutes late the next night.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37326, 'push your luck', 'to try too hard to get a particular result and risk losing what you have achieved:', 'She''s agreed to help on Saturday, but I think I''d be pushing my luck if I asked her to be here the whole weekend.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37327, 'put (your) money on someone/something', 'to risk money on someone or something winning a race or competition:', 'He put some money on a horse in the five o''clock race.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37328, 'put (your) money on someone/something', 'to strongly believe that someone will do something or that something will happen:', 'Chris will be promoted - I''d put money on it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37329, 'put a bow on something', 'to make something complete or perfect:', 'This final victory puts a bow on his success story.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37330, 'put a damper on something', 'to make something less enjoyable:', 'The bad weather put a damper on this year''s New Year celebrations.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37331, 'put a figure on it', 'to say exactly how much something is or costs:', 'I''m sure we''ll make a good profit, but I couldn''t put a figure on it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37332, 'put a gloss on something', 'to emphasize the good parts of something that has been done, especially those that are to your advantage, and to avoid the bad parts:', 'Politics is all about putting a good gloss on unpleasant or difficult situations.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37333, 'put a lid on something', 'to keep something under control and stop it from increasing:', 'We’ve got to keep a lid on our credit-card purchases.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37334, 'put a sock in it!', 'used to tell someone to be quiet or stop making so much noise:', 'Hey, put a sock in it, will you? I''m trying to work here.', 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37335, 'put a spoke in someone''''s wheel', 'to make it difficult for someone to achieve something they had planned to do:', 'His letter really put a spoke in our wheel.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37336, 'put all your eggs in one basket', 'to depend for your success on a single person or plan of action:', 'I''m applying for several jobs because I don''t really want to put all my eggs in one basket.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37337, 'put an end to something', 'to make something stop happening or existing:', 'How can we put an end to the fighting?', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37338, 'put down roots', 'If you put down roots in a place where you have moved to live, you make new friends and join in new activities there so that you feel it is your home.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37339, 'put flesh on (the bones of) something', 'to add more details to a plan, idea, argument, etc. to make it better or more complete', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37340, 'put forward/forth something', 'to suggest an idea for consideration:', 'None of the ideas that I put forward have been accepted.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37341, 'put ideas into someone''''s head', 'to make someone want to do something they had not thought about before, especially something stupid:', 'Don''t go putting ideas into his head. We can''t afford a new car.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37342, 'put in a good word for someone', 'to say positive things about someone:', 'I really need a job and I was hoping you might put in a good word for me with your boss.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37343, 'put in for something', 'to make an official request to have or do something:', 'I''m putting in for a job at the hospital.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37344, 'put in/make an appearance', 'to go to an event, but only for a short time because you do not really want to be there:', 'I felt like I had to put in an appearance at the staff party, but I only stayed for an hour.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37345, 'put it about', 'to have sex with a lot of different people:', 'Have you been putting it about recently, then?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37346, 'put it down to experience', 'to decide that instead of being upset about something bad that has happened or that you have done, you will learn from it:', 'Okay, so you made a mistake - you just have to put it down to experience and carry on with your life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37347, 'put it there!', 'something that you say when you want someone to shake your hand to show that you have just made an agreement:', '"So, do we have a deal?" "Sure, put it there."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37348, 'put on a brave face', 'to behave as if a problem is not important or does not worry you:', 'She seems all right but I think she''s just putting on a brave face.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37349, 'put on an act', 'to behave or speak in a false or artificial way:', 'He''s just putting on an act for the boss''s benefit.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37350, 'put on the dog', 'to act as if you are more important than you are', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37351, 'put one over on someone', 'to trick someone:', 'He''d tried to put one over on the tax office and got found out.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37352, 'put out feelers', 'to make informal suggestions as a way of testing other people''''s opinions on something before any decisions are made', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37353, 'put out fires', 'to spend time on problems that need to be dealt with quickly, instead of working in a calm, planned way:', 'She spends much of her time putting out fires and navigating red tape.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37354, 'put paid to something', 'to finish or destroy something:', 'A knee injury has put paid to her chances of getting into the final.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37355, 'put someone down as something', 'to think that someone is a particular type of person, especially when you do not know them very well:', 'I''d hate them to put me down as a snob.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37356, 'put someone down for something', 'to make a record that someone has promised to pay a particular amount of money as part of a collection to help people in need:', 'Put me down for a £10 donation.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37357, 'put someone in mind of something', 'to cause someone to remember something:', 'The mention of skiing holidays put me in mind of a documentary that I saw last week.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37358, 'put someone in the picture', 'to tell someone the facts about a situation:', 'His lawyer put him in the picture about what had happened since his arrest.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37359, 'put someone in their place', 'to tell or show someone that they are less important than they thought:', 'When he tried to take charge, she soon put him in his place.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37360, 'put someone off their stride', 'to take someone''''s attention away from what they are doing, so that they stop doing it or do it wrong:', 'He interrupted mid-speech and it put me off my stride.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37361, 'put someone off their stride/stroke', 'to take someone''''s attention away from something they are doing for a short time, making it more difficult to do:', 'The slightest noise puts him off his stride when he''s performing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37362, 'put someone on a pedestal', 'to believe that someone is perfect', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37363, 'put someone on the spot', 'If you put someone on the spot, you cause them embarrassment or difficulty by forcing them at that moment to answer a difficult question or make an important decision:', 'Mira rather put the boss on the spot by asking him when he was going to give us a pay rise.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37364, 'put someone onto something', 'to introduce a person to something or someone that could bring them an advantage:', 'David put me onto a wonderful vegetarian cookery book.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37365, 'put someone out to grass', 'to make someone stop work permanently because they are too old', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37366, 'put someone out to pasture', 'to stop someone working in a job because they are too old to be useful', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37367, 'put someone through something', 'to make someone experience something unpleasant or difficult:', 'I''m sorry to put you through this ordeal.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37368, 'put someone through something', 'to pay for someone to study at school, college, or university:', 'It''s costing them a lot of money to put their children through school.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37369, 'put someone through', 'to connect a person using a phone to the person they want to speak to:', 'Could you put me through to customer services, please?', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37370, 'put someone through the mill', 'to cause someone to have a difficult and unpleasant experience, especially by asking them a lot of difficult questions:', 'I had the interview this morning - they really put me through the mill.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37371, 'put someone through the wringer', 'to ask someone difficult or unpleasant questions, often to find out if they are doing their job in a satisfactory way:', 'Outside investigators will put the company''s accounting practices through the wringer.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37372, 'put something to someone', 'to suggest an idea or plan to someone so that they can consider it or discuss it:', '"Shall we all go out for a pizza tonight?" "I don''t know. I''ll put it to Jim and see what he says."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37373, 'put something to someone', 'to ask someone a question:', 'I have a question I want to put to you.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37374, 'put someone to the sword', 'to kill someone:', 'Thousands of innocents were put to the sword.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37375, 'put someone up to something', 'to encourage someone to do something, usually something wrong:', 'I think he was put up to it by his friends.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37376, 'put someone''''s nose out of joint', 'to offend or upset someone, especially by getting something that that person wanted for himself or herself:', 'John''s nose was really put out of joint when Jane was promoted and he wasn''t.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37377, 'put someone/something first', 'to treat someone or something as being more important than anyone or anything else:', 'She all too often puts others first and never stops to think of herself.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37378, 'put someone/something through their/its paces', 'to make someone show their skills or knowledge, or to make something show its good qualities:', 'All the candidates were put through their paces during the television debate.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37379, 'put something about/around', 'to tell a lot of people something that is not true:', '[ + that ] I''d like to know who put the rumour around that I''m pregnant.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37380, 'put something across', 'to express your ideas and opinions clearly so that people understand them easily:', 'It''s an interesting idea and I thought he put it across well.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37381, 'put yourself across', 'to express your ideas and opinions clearly so that people understand them and realize what you are like as a person:', 'I don''t think I managed to put myself across very well in my interview.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37382, 'put something across/over someone', 'to cause a piece of false information to be believed by one or more people:', 'You didn''t manage to put that story over on the tax people, did you?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37383, 'put something aside', 'to save something, usually time or money, for a special purpose:', 'I put aside a little every month for a deposit on a house.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37384, 'put something aside', 'If you put a disagreement or problem aside, you ignore it temporarily so that it does not prevent you doing what you want to do:', 'Let''s put our differences aside and make a fresh start.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37385, 'put something at something', 'to guess or roughly calculate that something will cost a particular amount, or that something is a particular size, number, or amount:', 'The value of the painting has been put at £1 million.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37386, 'put something away', 'to put something in the place or container where it is usually kept:', 'Put your toys away now.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37387, 'put something away', 'to eat a large amount of food:', 'He put away a whole box of chocolates in one evening.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37388, 'put someone away', 'to move someone into a place where people live and are cared for together, such as a mental hospital or old people''''s home:', 'In the past, people who suffered from schizophrenia were often put away.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37389, 'put someone away', 'to send someone to prison:', 'After what he did, he deserves to be put away for life.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37390, 'put something back', 'to return an object to where it was before it was moved:', 'Will you put the books back when you''ve finished with them?', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37391, 'put something back', 'to delay a planned event:', 'We had to put the meeting back a week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37392, 'put something back', 'to drink something quickly, especially a large amount of alcohol:', 'He regularly puts back six pints a night - I don''t know how he does it.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37393, 'put something back', 'to change a clock or watch to make it show an earlier time, for example because you are now in a part of the world where the time is different', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37394, 'put something before someone', 'to give more attention to one thing than another because you think it is more important:', 'I''d never put my work before my family.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37395, 'put something before someone', 'to formally tell or explain facts or ideas to a group of people in authority:', 'We have to put our proposal before the committee.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37396, 'put something behind you', 'If you put an unpleasant experience behind you, you stop thinking about it, so that it does not affect your life:', 'Like any divorce, it was a painful business but I''ve put it all behind me now.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37397, 'put something by', 'to save an amount of money to use later:', 'I try to put by a few pounds every week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37398, 'put something down to something', 'to think that a problem or situation is caused by a particular thing:', 'I put the children''s bad behaviour down to the fact that they were tired.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37399, 'put something in', 'to fix a large piece of equipment or system into a room or building, ready to be used:', 'I''ve just had central heating/a new kitchen put in.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37400, 'put something in', 'to formally offer a particular thing to be considered:', 'I''ve put in an application to the college.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37401, 'put (something) in', 'to say something that adds to or interrupts what is already being said:', '[ + speech ] "But she''s too inexperienced for the job," put in Jane.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37402, 'put something in/put something into something', 'to spend a lot of time or effort doing something:', 'You''ve obviously put a lot of work in on your garden.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37403, 'put something into something', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37404, 'put something off', 'to decide or arrange to delay an event or activity until a later time or date:', 'The meeting has been put off for a week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37405, 'put someone off', 'to tell someone that you cannot see them or do something for them, or to stop someone from doing something, until a later time:', 'I really don''t want to go out with Helen and Greg tonight - can''t we put them off ?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37406, 'put someone off (something)', 'to take someone''''s attention away from what they want to be doing or should be doing:', 'Once she''s made up her mind to do something, nothing will put her off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37407, 'put someone off (something/someone)', 'to make someone dislike something or someone, or to discourage someone from doing something:', 'The smell of hospitals always puts me off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37408, 'put something on', 'to make a device operate, or to cause a device to play something, such as a CD or DVD, by pressing a switch:', 'Could you put the light on?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37409, 'put something on', 'to cover part of the body with clothes, shoes, make-up, or something similar:', 'Put your shoes on - we''re going out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37410, 'put something on', 'to pretend to have a particular feeling or way of behaving that is not real or natural to you:', 'Why are you putting on that silly voice?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37411, 'put something on', 'to produce or provide something, especially for the good of other people or for a special purpose:', 'She put on a wonderful meal for us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37412, 'put something on', 'If people or animals put weight on, they become heavier:', 'I''d expected to put weight on when I gave up smoking, but I didn''t.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37413, 'put someone on', 'to try to persuade someone that something is true when it is not, usually as a joke:', 'She said she was planning to give her house to a charity for the homeless but I thought she was putting me on.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37414, 'put someone on something', 'to tell someone to start taking a particular medicine or eating particular foods:', 'Doctors put her on antibiotics after discovering an infection.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37415, 'put something out', 'to make a light stop shining by pressing or moving a switch:', 'Did you put the lights out downstairs?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37416, 'put something out', 'to make something such as a fire or cigarette stop burning:', 'Firefighters have been called to put out the fire in the city centre.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37417, 'put someone out', 'to cause trouble or extra work for someone:', 'Would it put you out if we came tomorrow instead of today?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37418, 'put someone out', 'to annoy or upset someone, often by what you do or say to them:', 'She was very put out when they turned up two hours late for dinner.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37419, 'put yourself out', 'to make an effort to do something to help someone, even if it is not convenient:', 'Ethan is always willing to put himself out for other people.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37420, 'put something out', 'to move forward part of your body, such as your hand or your tongue, from your body:', 'She put out her hand to shake mine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37421, 'put something out', 'to injure part of your body by causing it to be moved out of its correct position:', 'He put his knee out playing tennis.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37422, 'put something out', 'to produce something in large quantities, so that it can be sold:', 'They put out millions of pairs of shoes a year.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37423, 'put something out', 'to produce information and make it available for everyone to read or hear:', 'Police have put out a warning to people living in the area.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37424, 'put something out', 'If a mistake puts out a set of mathematical calculations, it causes them to be wrong:', 'That one error put the figures out by several thousand pounds.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37425, 'put something out', 'If you put work out, you employ someone outside your organization to do it:', 'The council has put the job of street-cleaning out to a private firm.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37426, 'put out', '(especially of a woman) to agree to have sex:', 'I wasn''t going to put out just because he''d paid for dinner.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37427, 'put something out of its misery', 'to kill an animal because it is in great pain, so that it does not have to suffer any more', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37428, 'put someone out of their misery', 'to stop someone worrying, usually by giving that person information that they have been waiting for:', 'We try to put our students out of their misery and give them their exam results as early as possible.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37429, 'put something out of joint', 'to prevent a plan from working correctly:', 'Our whole schedule was put out of joint by the designs arriving a week late.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37430, 'put something out of your mind', 'to force yourself not to think about something:', 'It''s over, put it out of your mind.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37431, 'put something over on someone', 'to persuade someone to believe something that is not true:', 'My dad’s really smart – you can never put anything over on him.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37432, 'put something over/across', 'to express an idea clearly so that people understand it:', 'Did you feel that you managed to put over your point of view?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37433, 'put something to bed', 'to successfully deal with something or solve a problem:', 'We thought we''d put the issue to bed, but it was brought up again at the next meeting.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37434, 'put something to bed', 'to start printing something', NULL, 'idiom', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37435, 'put something to sleep', 'to kill an animal that is very ill or very old so that it does not suffer any more', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37436, 'put something to the test', 'to find out how good something is:', 'Her constant questions put the teacher''s patience to the test.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37437, 'put something together', 'to put the parts of something in the correct places and join them to each other:', 'It took several hours to put the puzzle together.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37438, 'put something together', 'to prepare a piece of work by collecting several ideas and suggestions and organizing them:', 'The management are putting together a plan/proposal/package to rescue the company.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37439, 'put something together', 'said after a phrase that refers to a group of people or things to show that you are thinking of them as a group rather than separately:', 'She earns more than all the rest of us put together.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37440, 'put something toward something', 'to use an amount of money to pay part of the cost of something:', 'My grandma gave me some money to put toward a new coat.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37441, 'put something towards something', 'to use an amount of money to pay part of the cost of something:', 'My grandma gave me some money to put towards a new coat.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37442, 'put something under the microscope', 'to examine or think about a situation very carefully:', 'The investigation put the company''s financial accounts under the microscope.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37443, 'put something up', 'to raise something, or to fix something in a raised position:', 'Why don''t you put up your hood/umbrella?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37444, 'put something up', 'to build something:', 'They''re planning to put a hotel up where the museum used to be.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37445, 'put something up', 'to fix an object to a vertical surface:', 'We''ve put up some new curtains in the living room.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37446, 'put something up', 'to increase the price or value of something:', 'I see they''ve put up the price of fuel again.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37447, 'put something up', 'to provide or lend an amount of money for a particular purpose:', 'The money for the new hospital was put up by an anonymous donor.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37448, 'put something up', 'to preserve food in glass or metal containers :', 'There is a period of young motherhood when you wash and iron, garden, and put up preserves.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37449, 'put up something', 'to show or express a particular type of opposition to something:', 'The villagers were unable to put up any resistance to the invading troops.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37450, 'put something/someone up', 'to suggest an idea, or to make a person available, to be considered:', 'It was Bob who originally put up the idea of the exhibition.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37451, 'put someone up', 'to provide someone with a place to stay temporarily:', 'Sally is putting me up for the weekend.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37452, 'put up', 'to stay somewhere for the night:', 'We put up at a small hotel for the night.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37453, 'put something/someone down', 'to put an object that you are holding onto the floor or onto another surface, or to stop carrying someone:', 'I put my bags down while we spoke.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37454, 'put something/someone down', 'to write someone''''s name on a list or document, usually in order to include that person in an event or activity:', 'Do you want me to put you down for the trip to London?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37455, 'put something down', 'If you put the phone down, you place it or the receiver back in the position you keep it in when it is not being used.', NULL, 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37456, 'put something down', 'to pay part of the cost and promise to pay the rest later:', 'I''ve put a deposit down on a new car.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37457, 'put someone down', 'to make someone feel silly or not important by criticizing them:', 'Why did you have to put me down in front of everybody like that?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37458, 'put someone down', 'to place and make a baby comfortable in the place where it sleeps:', 'I''d just put Jack down for his nap.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37459, 'put something down', 'to kill an animal that is old, sick, or injured, to prevent it from suffering:', 'If a horse breaks its leg, it usually has to be put down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37460, 'put something down', 'to stop or limit an opposing political event or group:', 'Police used tear gas to put the riot down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37461, 'put something down', 'to reduce a price or a charge:', 'Shops are being forced to put their prices down in order to attract customers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37462, 'put (something) down (somewhere)', 'When an aircraft puts down, it lands, and when pilots put down their aircraft, they land:', 'She put down safely in the corner of the airfield.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37463, 'put someone down somewhere', 'to stop a vehicle and allow someone to get out of it or off it:', 'Ask the taxi driver to put you down outside the church.', 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37464, 'put something/someone forward', 'to state an idea or opinion, or to suggest a plan or person, for other people to consider:', 'The proposals that you have put forward deserve serious consideration.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37465, 'put something forward', 'to change a clock or watch to make it show a later time, especially an hour later:', 'Most European countries put the clocks forward in the spring.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37466, 'put something/someone in a pigeonhole', 'to form a very fixed, often wrong, opinion about what type of person or thing someone or something is', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37467, 'put something/someone on the map', 'to make a thing, person, or place famous:', 'The governor has managed to put this sleepy state on the map.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37468, 'put sth in/into sth', 'to spend a lot of time or effort doing something:', 'If I put in some extra hours today, I can have some time off tomorrow.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37469, 'put sth in/into sth', 'to invest money in something', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37470, 'put sth over', 'to express an idea clearly so that people understand it:', 'Did you feel that you managed to put over your point of view?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37471, 'put stock in something', 'If you put stock in something that someone says or does, you have a high opinion of it:', 'He''s been wrong before, so I don''t put much stock in what he says any more.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37472, 'put the boot in', 'to kick someone when they are already on the ground', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37473, 'put the boot in', 'to make a bad situation worse, by criticizing or being unkind:', 'After he lost his job, his wife put the boot in by announcing she was leaving him.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37474, 'put the brakes on', 'to slow down or stop an activity:', 'The city has put the brakes on further spending.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37475, 'put the cart before the horse', 'to do things in the wrong order:', 'Aren''t you putting the cart before the horse by deciding what to wear for the wedding before you''ve even been invited to it?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37476, 'put the fear of God into you', 'to frighten you a lot', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37477, 'put the finishing touches on', 'to add the final improvements to something so that you are satisfied with it or certain that it is complete', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37478, 'put the finishing touches to', 'to add the final improvements to something so that you are satisfied with it or certain that it is complete', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37479, 'put the flags out!', 'something that you say when you are pleased and surprised that something has happened:', 'Josh has cleaned the bathroom - put the flags out!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37480, 'put the heat on someone', 'to try to persuade or force someone to do something', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37481, 'put the lid on something', 'If something that happens puts the lid on a plan, it causes the plan to fail:', 'Well, James'' resignation just about puts the lid on it/the project.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37482, 'put the roses (back) into someone''''s cheeks', 'If something puts the roses back into your cheeks, it makes you look healthy, especially after an illness:', 'A brisk walk will put the roses back into your cheeks.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37483, 'put the shot', 'to throw a heavy metal ball as far as possible in a sports competition:', 'He won the gold medal for putting the shot.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37484, 'put the skids under something', 'to cause something such as a plan to fail:', 'Local residents have put the skids under plans to build a new shopping centre.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37485, 'put the squeeze on someone', 'to ask someone to give you money:', 'She put the squeeze on her mother for a hundred bucks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37486, 'put the word out', 'to tell people a new piece of news:', 'So, the new manager has been appointed - should we put the word out?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37487, 'put the world to rights', 'to have a conversation in which you talk about many different things, for example how to solve society''''s problems :', 'When we were students we used to stay up late putting the world to rights.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37488, 'put their heads together', 'If two or more people put their heads together, they plan something together:', 'If we put our heads together, we can think of a solution.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37489, 'put two and two together', 'to guess the truth about a situation from what you have seen or heard:', '"How did you know they were having an affair?" "I''d seen them out together a couple of times, so I just put two and two together."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37490, 'put two and two together and make five', 'to understand a particular situation wrongly, often in a way that is more shocking or exciting than the truth:', '"Why in the world did she think you were pregnant?" "I was sick a couple of times, and I guess she just put two and two together and made five."', 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37491, 'put up or shut up', 'If you say someone should put up or shut up, you mean that they should either take action in order to do what they have been talking about, or stop talking about it:', 'You keep saying you''re going to ask her out. Well, put up or shut up.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37492, 'put up with something/someone', 'to accept or continue to accept an unpleasant situation or experience, or someone who behaves unpleasantly:', 'I can put up with the house being messy, but I hate it if it''s not clean.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37493, 'put words in someone’s mouth', 'to say that someone means one thing when the person really meant something else:', 'I never said you should leave – don''t put words in my mouth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37494, 'put words in/into someone''''s mouth', 'to suggest that someone meant one thing when really they meant another:', 'Stop putting words in my mouth - I didn''t say you looked fat in the red dress - I merely said you looked very slim in the black!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37495, 'put years on someone', 'If something puts years on a person, it makes them appear much older:', 'Being tired and unhappy puts years on you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37496, 'put your back into something', 'to use a lot of physical effort to try to do something:', 'You could dig this plot in an afternoon if you really put your back into it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37497, 'put your best foot forward', 'to try as hard as you can', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37498, 'put your feet up', 'to relax and do very little:', 'After working all week, you deserve to put your feet up.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37499, 'put your feet up', 'to relax, especially by sitting with your feet supported above the ground:', 'You go home and put your feet up.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37500, 'put your finger on something', 'to discover the exact reason why a situation is the way it is, especially when something is wrong:', 'There''s something odd about him, but I can''t quite put my finger on it.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37501, 'put your foot down', 'to use your authority to stop something happening:', 'When she started borrowing my clothes without asking, I had to put my foot down.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37502, 'put your foot down', 'to increase your speed when you are driving:', 'The road ahead was clear, so I put my foot down.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37503, 'put your foot in it', 'to say something by accident that embarrasses or upsets someone:', 'I really put my foot in my mouth – I asked her if Jane was her mother, but she said Jane is her sister.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37504, 'put your foot in your mouth', 'to say or do something that you should not have, esp. something that embarrasses someone else:', 'I really put my foot in my mouth – I asked her if Jane was her mother, but she said Jane is her sister.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37505, 'put your foot in your mouth', 'to say something by accident that embarrasses or upsets someone:', 'I really put my foot in my mouth with Eva. I had no idea she was divorced.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37506, 'put your hand in your pocket', 'to give money to someone or to charity (= organizations that collect money to give to poor people, ill people, etc.):', 'People are more inclined to put their hands in their pockets to help children.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37507, 'put your head over/above the parapet', 'to be brave enough to state an opinion that might upset someone', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37508, 'put your heart and soul into something', 'to make a lot of effort to do something:', 'She puts her heart and soul into her work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37509, 'put your money where your mouth is', 'to show by your actions and not just your words that you support or believe in something', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37510, 'put your neck on the line', 'to do something that you know might fail and spoil other people''''s opinion of you or cause you to lose money:', 'There''s a lot of money at stake here and none of the partners wants to put his neck on the line.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37511, 'put your shirt on something', 'to feel very certain that something will happen:', 'I''d put my shirt on the president being re-elected.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37512, 'put your thinking cap on', 'to think seriously about something:', 'I need some interesting suggestions so if you can put your thinking cap on I''d be grateful.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37513, 'put yourself across', 'to express ideas and opinions in a way that people can understand them and know what type of person you are:', 'I don''t think I managed to put myself across very well in my interview.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37514, 'put yourself in someone''''s place/position/shoes', 'to imagine how someone else feels in a difficult situation:', 'Put yourself in my place - what else could I have done?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37515, 'put/get someone''''s back up', 'to annoy someone:', 'Just ignore him - he''s only trying to put your back up.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37516, 'put/get the wind up someone', 'to make someone feel worried about their situation:', 'Tell them your father''s a policeman - that''ll put the wind up them!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37517, 'put/lay something on the line', 'to risk something:', 'Firefighters put their lives on the line every working day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37518, 'put/lay something on/to one side', 'to not use something, especially an amount of money, in order to keep it for later use:', 'We have put some money on one side for next year''s summer holiday.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37519, 'put/lay your cards on the table', 'to be honest about your feelings and intentions:', 'I thought it was time I laid my cards on the table, so I told him that I had no intention of marrying him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37520, 'put/leave someone in the shade', 'to be so good that another person or thing does not seem important or worth very much:', 'Although I thought I''d done well, my sister''s exam results put mine in the shade.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37521, 'put/leave something on/to one side', 'to stop talking about a particular subject:', 'Can we leave the issue of pay on one side for the moment?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37522, 'put/place your faith in something/someone', 'to make a decision to trust something or someone:', 'Some people put their faith in strong leaders rather than sound policies.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37523, 'put/set pen to paper', 'to start to write:', 'It''s time you put pen to paper and replied to that letter from your mother.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37524, 'put/set pencil to paper', 'to write:', 'Everyone should put pencil to paper and complain about the proposal.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37525, 'put/set someone right', 'to stop someone believing something that is not true, or to correct someone by telling them the truth:', 'She thought she wouldn''t have to work hard, but we soon put her right on that.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37526, 'put/set someone right', 'to make someone feel better:', 'A good night''s sleep will soon put you right.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37527, 'put/set someone straight', 'to make certain that someone knows the real facts about a situation:', 'Don''t worry, I set him straight (on this matter).', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37528, 'put/set something in motion', 'to start a machine or process:', 'Once the printing processes have been put in motion, they''re not so easy to stop.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37529, 'put/set something in train', 'to start a process:', 'The reform process was put in train in 1985.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37530, 'put/set the cat among the pigeons', 'to say or do something that causes trouble or makes a lot of people very angry', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37531, 'put/stick that in your pipe and smoke it!', 'a rude way of telling someone that they must accept what you have just said, even if they do not like it', NULL, 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37532, 'put/stick the knife into someone', 'to be unpleasant about someone, or try to harm someone:', 'The reviewer in the magazine that I read really put the knife in.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37533, 'put/stick your oar in', 'to say or do something that annoys other people because they have not asked you to join their conversation or activity:', 'No one asked him to help - he''s always sticking his oar in.', 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37534, 'put/throw a spanner in the works', 'to do something that prevents a plan or activity from succeeding:', 'The funding for the project was withdrawn so that really threw a spanner in the works.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37535, 'put/tighten the screws on someone', 'to use force or threats to make someone do what you want:', 'They put the screws on him until he paid up.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37536, 'put/turn the clock back', 'to make things the same as they were at an earlier time:', 'The court''s decision on this case will turn the clock back 50 years.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37537, 'puzzle something out', 'to discover or understand something by thinking hard about it:', '[ + question word ] I still can''t puzzle out how I managed to spend so much money last month.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37538, 'quarrel with something', 'to think that something is wrong:', 'No one can quarrel with the improvements that have been made.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37539, 'quick march!', 'an order given to soldiers to make them start marching', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37540, 'quit on someone', 'to stop supporting or being friends with someone, especially when they need your support:', 'I will never quit on my teammates and they will never quit on me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37541, 'quote... unquote', 'said to show that you are repeating someone else''''s words, especially if you do not agree:', 'She says they''re quote "just good friends" unquote.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37542, 'rabbit on', 'to continue talking about something that is not interesting to the person you are talking to:', 'He''s always rabbiting on about his stamp collection.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37543, 'rack off', 'to leave or go away, used especially as a rude way of telling someone to go away:', 'If you don''t like Sydney, rack off. All you are doing is whinging.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37544, 'rack something up', 'to gradually get more points, profits, etc.:', 'He has racked up 450 points in three months.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37545, 'rack something up', 'to increase something such as a rent or price, especially by an amount that is considered to be too much:', 'Our landlord racked up the rent by 15 percent this year.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37546, 'rack your brain', 'to think very hard:', 'I''ve been racking my brain all day but I can''t remember her name.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37547, 'rack your brains', 'to think very hard:', 'I''ve been racking my brains all day but I can''t remember her name.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37548, 'raffle off something', 'to sell chances to win something:', 'Players signed footballs, which were raffled off along with a mink coat.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37549, 'rag on someone', 'to continually laugh at someone or say unkind things about them, either because you are joking or because you want to upset that person:', 'They''ve been ragging on me, but it''s just in fun.', 'phrasal verb', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37550, 'ragtag and bobtail', 'all types of person or thing, including those that are ordinary and not special in any way:', 'a ragtag and bobtail bunch of amateurs', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37551, 'rail something off', 'to close something, especially using railings:', 'Part of the playing field had been railed off for use as a car park.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37552, 'rain (something) down', 'to fall in large amounts, or to direct something in large amounts, usually forcefully or violently:', 'Bombs rained down on the besieged city.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37553, 'rain cats and dogs', 'to rain very heavily:', 'Don''t forget to take your umbrella - it''s raining cats and dogs out there.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37554, 'rain on someone''''s parade', 'to do something that spoils someone''''s plans:', 'I''m sorry to rain on your parade but you''re not allowed to have alcohol on the premises.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37555, 'rain something off', 'If an event is rained off, it cannot start or continue because it is raining:', 'His hockey match was rained off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37556, 'rain something out', 'If an event is rained out, it cannot start or continue because it is raining:', 'His hockey game was rained out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37557, 'raise (a few) eyebrows', 'to cause surprise or shock:', 'Jemma''s miniskirt raised a few eyebrows at the board meeting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37558, 'raise a rumpus', 'to make a forceful complaint:', 'You should raise a rumpus about the lack of safety routines here.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37559, 'raise hell', 'to behave in a way that is not controlled and that causes trouble', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37560, 'raise hell', 'to protest about something in a loud and angry way', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37561, 'raise someone from the dead', 'to make a dead person start living again:', 'Christians believe that, at Easter, Christ was raised from the dead.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37562, 'raise the alarm', 'to make people understand the danger of something:', 'A local doctor was the first to raise the alarm about this latest virus.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37563, 'raise the roof', 'to play/sing very loudly and enthusiastically:', 'With their last, triumphant piece, the musicians raised the roof.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37564, 'raise your eyebrows', 'to show surprise by moving your eyebrows upwards', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37565, 'raise your game', 'to make an effort to improve the way that you do something:', 'They''re going to have to raise their game if they want to stay in the Premiership this season.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37566, 'raise your hand to/against someone', 'to hit someone:', 'Never raise your hand to a child.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37567, 'rake over something', 'to keep talking or thinking about an unpleasant event or experience:', 'He keeps on raking over his divorce, when really he should be getting on with his life.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37568, 'rake something in', 'to earn or get a large amount of money:', 'He rakes in over $200,000 a year.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37569, 'rake something out', 'to look for something and find it, usually among various things you have stored:', 'I raked this old blanket out for camping.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37570, 'rake something up', 'to talk again about a past event or experience that should be forgotten, because it upsets or annoys someone else:', 'She''s always raking up the past/that old quarrel.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37571, 'rake something/someone up', 'to get the things or people you need, with difficulty or by looking in various places:', 'I''m trying to rake up some people to play football on Saturday - do you want to come along?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37572, 'rally around (someone)', 'to help or support someone:', 'When I''m ill, my friends always rally around.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37573, 'rally round (someone)', 'to help or support someone:', 'When I''m ill, my friends always rally round.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37574, 'ram something down someone''''s throat', 'to force someone who disagrees with you to listen to your opinions:', 'For years I''ve had his political views rammed down my throat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37575, 'ram something home', 'to emphasize the importance of what you are saying in order to make certain people understand it:', 'He thumped the desk as he rammed his point home.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37576, 'ram something into someone', 'to force someone to accept an idea, opinion, or principle:', 'It''s time someone rammed a bit of sense into you.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37577, 'ramp something up', 'If a business ramps up its activity, it increases it:', 'The company announced plans to ramp up production to 10,000 units per month.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37578, 'ramp something up', 'to increase the speed, power, or cost of something:', 'Announcement of the merger is expected to ramp up share prices over the next few days.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37579, 'rank as', 'to fit or be given a particular description:', 'rank as sth The storms rank as one of the worst insurance disasters ever to hit Europe.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37580, 'rap someone over the knuckles', 'to speak officially to someone in a severe or angry way because you disapprove of their actions:', 'He was rapped over the knuckles by the management.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37581, 'rat on someone/something', 'to not be loyal to someone, especially by giving away secret information about them, or to fail to do something that you said you would do:', 'He ratted on us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37582, 'ratchet something up/down', 'to increase/reduce something over a period of time:', 'The debate should ratchet up awareness of the problem among members of the general public.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37583, 'ratchet sth down', 'to reduce something in controlled stages over a period of time:', 'The state plans to ratchet down greenhouse gas emissions by 25% within the next 10 years.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37584, 'ratchet sth up', 'to increase something in controlled stages over a period of time:', 'The constant ratcheting up of rewards for executives means they are expanding out of all proportion to those of other staff.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37585, 'rather you than me', 'said by someone who does not want to do the thing that someone else is doing:', '"I''m having two teeth out next week." "Rather you than me."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37586, 'ration something out', 'to divide something between a group of people so that each person gets a small amount:', 'Ann rationed out the cake between the children.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37587, 'rattle on/away', 'to talk for a long time, especially about things that are not important:', 'She was on the phone for hours last night, just rattling on to her friends.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37588, 'rattle something off', 'to say or read aloud very quickly a list of names or things, or something you have learned:', 'She rattled off the names of the people who were coming to the party.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37589, 'rattle through something', 'to do or say something very quickly:', 'I''m going to rattle through my work today so that I can go home early.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37590, 'ray of sunshine', 'a happy person who makes others feel happy, especially in a difficult situation:', 'We love looking after our grandchild. He''s a ray of sunshine!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37591, 'reach for the stars', 'to want or try to get something that is difficult or impossible to get', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37592, 'reach out (to someone)', 'to try to communicate with a person or a group of people, usually in order to help or involve them:', 'The new mayor is reaching out to inner city communities to involve them in his plans for the city.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37593, 'reach out (to someone)', 'to communicate with someone, especially by using a phone, sending them an email, etc.:', 'The Washington Post reached out to Turner for comment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37594, 'reach out (to someone)', 'to offer help and support to someone:', 'She set up her charity to reach out to the thousands of homeless on the streets.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37595, 'react against something', 'to intentionally do the opposite of what someone wants you to do because you do not like their rules or ideas:', 'He reacted against everything he had been taught.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37596, 'read (someone) the riot act', 'to speak angrily to someone about something they have done and warn that person that they will be punished if it happens again :', 'He''d put up with a lot of bad behaviour from his son and thought it was time to read him the riot act.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37597, 'read between the lines', 'to try to understand someone''''s real feelings or intentions from what they say or write:', 'Reading between the lines, I''d say he isn''t happy with the situation.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37598, 'read my lips', 'a slightly rude way of telling someone to listen carefully to what you are saying:', 'Read my lips. No new taxes.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37599, 'read someone''''s lips', 'to follow the movements of someone''''s lips in order to understand what is being said, especially if you are unable to hear them speak:', 'She read his lips across the busy conference hall - "Time to go."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37600, 'read someone''''s mind', 'to know what someone is thinking without them telling you:', 'humorous "How about a drink, then?" "Ah, you read my mind!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37601, 'read someone''''s palm', 'to look at the lines on a person''''s hand as a way of trying to find out what will happen to that person in the future:', 'In a tent an old gypsy woman was reading palms.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37602, 'read something into something', 'to believe that an action, remark, or situation has a particular importance or meaning, often when this is not true:', 'Don''t read too much into her leaving so suddenly - she probably just had a train to catch.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37603, 'read something out', 'to read something and say the words aloud so that other people can hear:', 'He read out the names of all the winners.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37604, 'read something over/through', 'to read something quickly from the beginning to the end, especially to find mistakes:', 'I read your proposal through last night and I think we''ll agree to it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37605, 'read the room', 'to be or become aware of the opinions and attitudes of a group of people that you are talking to :', 'You have to read the room when you''re performing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37606, 'read the runes', 'to understand what will happen in the future, by looking at what is happening now:', 'He was the first of the Eastern leaders to read the runes and make political changes to stay in power.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37607, 'read up (on/about) something', 'to spend time reading in order to find out information about something:', 'It''s a good idea to read up on a company before going for an interview.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37608, 'read up on something', 'to learn about something by reading:', 'I don''t know much about Malawi – I''ll go home and read up on it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37609, 'ready to hand', 'close to you and therefore available for use when necessary:', 'The sheriff slept with his gun ready to hand under his pillow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37610, 'ready, steady, go!', 'said at the start of a race, especially one for children', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37611, 'ream someone (out)', 'to tell someone off severely because you strongly disapprove of their behaviour:', 'The boss reamed them out for sleeping on the job.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37612, 'reap the benefit, reward, etc.', 'to get something good as a result of your own actions:', 'She studied every evening and reaped the benefit at exam time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37613, 'reap what you have sown', 'to win or lose as a result of something you did in the past', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37614, 'rear above/over something/someone', 'to appear very tall and big in comparison with another thing or person:', 'The mountain reared above the village.', 'phrasal verb', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37615, 'rear its (ugly) head', '(of something unpleasant) to appear:', 'The familiar spectre of drought and famine has reared its ugly head again.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37616, 'reason with someone', 'to try to persuade someone to act in a wise way or to change their behaviour or a decision, by explaining why it is a good idea:', '[ + to infinitive ] The police reasoned with the hijackers to at least let the children go free.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37617, 'recharge your batteries', 'to rest and relax for a period of time so that you feel energetic again:', 'She took a trip to the South of France to recharge her batteries.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37618, 'reckon on something', 'to feel that something is likely to happen and to make plans that depend upon it happening:', '[ + -ing verb ] We''re reckoning on selling 2,000 cars a month.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37619, 'reckon something in', 'to include an amount in your calculations:', 'When you reckon in all my overtime, my total pay is quite good.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37620, 'reckon something up', 'to calculate the total amount of something:', 'She can reckon up a bill faster than any calculator.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37621, 'reckon with someone/something', 'to deal with a difficult or powerful person or thing:', 'If you harm her, you''re going to have the police to reckon with.', 'phrasal verb', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37622, 'reckon without something', 'to fail to think about something when you are making plans and therefore not be prepared to deal with it:', 'We''d expected a two-hour drive but had reckoned without the rain.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37623, 'reconcile yourself to something', 'to accept a situation or fact although you do not like it:', 'She must reconcile herself to the fact that she must do some work if she wants to pass her exams.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37624, 'reduce someone to something', 'to make someone unhappy or cause someone to be in a bad state or situation:', 'His comments reduced her to tears (= made her cry).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37625, 'reduce someone to something', 'If you are reduced to doing something, you are forced to do it because you have no other choice:', 'He was out of cigarettes and was reduced to smoking the butts left in the ashtrays.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37626, 'reduce something to something', 'to cause something, especially a large structure, to be destroyed and broken into pieces:', 'Allied bombing reduced the city to ruins/rubble.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37627, 'reduce, reuse, recycle', 'said to encourage people to waste less, by using less and using things again, in order to protect the environment', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37628, 'reek of something', 'If an event or situation reeks of an unpleasant quality, it seems to be caused by or connected to that quality:', 'His promotion reeks of favouritism.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37629, 'reel someone/something in', 'to get control of something or someone, sometimes by offering something in exchange:', 'The article offers tips on how computer users can avoid being reeled in by internet scams.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37630, 'reel something in/out', 'to pull in a rope or an object on the end of a rope by turning a wheel round and round, or to release something in the same way:', 'Slowly the fisherman reeled in his line, bringing the fish ashore.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37631, 'reel something off', 'to say a long list of things quickly and without stopping:', 'The old man reeled off the names of his 22 grandchildren.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37632, 'reel something off', 'to win several games or points one after the other in a sports competition', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37633, 'refer to someone/something', 'to talk or write about someone or something, especially in only a few words:', 'In her autobiography she occasionally refers to her unhappy schooldays.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37634, 'refer to someone/something', 'If writing or information refers to someone or something, it relates to that person or thing:', 'The new salary scale only refers to company managers and directors.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37635, 'refer someone to something/someone', 'to direct someone or something to a different place or person for information, help, or action, often to a person or group with more knowledge or power:', 'My doctor referred me to a hospital specialist.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37636, 'refer (someone) to something', 'to look at, or tell someone else to look at, a book or similar record in order to find information and help:', 'She spoke for an hour without once referring to her notes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37637, 'reflect on someone/something', 'to affect other people''''s opinion of someone or something, especially in a bad way:', 'When one player behaves disgracefully, it reflects (badly) on the whole team.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37638, 'refresh someone''''s memory', 'to help someone remember something:', 'I looked the word up in the dictionary to refresh my memory of its exact meaning.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37639, 'regale someone with something', 'to entertain someone with stories, jokes, etc.:', 'The sailor regaled us all night with stories of his adventures.', 'phrasal verb', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37640, 'regardless of something', 'without being influenced by any other events or conditions:', 'I tell them the truth, regardless of what they want to hear.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37641, 'rein something in', 'to make a horse go more slowly or stop by pulling on its reins', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37642, 'rein something in', 'to control an emotion, activity, or situation to prevent it from becoming too powerful:', 'We tried to rein in our excitement and curiosity.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37643, 'rein sth in/back', 'to control something and stop it increasing:', 'Consumers tend to rein in their spending in a recession.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37644, 'reinvent the wheel', 'to waste time trying to create something that someone else has already created', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37645, 'relate to someone/something', 'to be connected to, or to be about someone or something:', 'Chapter 9 relates to the effects of inflation on consumers.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37646, 'relate to someone/something', 'connected with something:', 'Anything relating to maths is a complete mystery to me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37647, 'relate to someone', 'to understand someone and be able to have a friendly relationship with them:', 'Many parents find it hard to relate to their children when they are teenagers.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37648, 'relate to something', 'to understand a situation or someone''''s feelings because you have experienced a similar situation or similar feelings:', 'The culture that he describes is so different from mine that I sometimes find it hard to relate to.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37649, 'relax your grip/hold', 'to start to hold something less tightly:', 'She relaxed her grip on my arm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37650, 'relax your grip/hold', 'to start to control something less:', 'The Mafia has relaxed its grip on local businesses.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37651, 'relieve someone of something', 'to take from a person something that they are carrying, in a helpful or polite way:', 'May I relieve you of that heavy bag?', 'phrasal verb', 'C2', NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37652, 'relieve someone of something', 'to steal something from someone:', 'The pickpocket delicately relieved him of his wallet.', 'phrasal verb', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37653, 'relieve someone of something', 'to remove someone from their job or position because they have done something wrong:', 'Following the scandal, he was relieved of his post as deputy finance minister.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37654, 'rely on/upon someone/something', 'to need a particular thing or the help and support of someone or something in order to continue, to work correctly, or to succeed:', '[ + -ing verb ] The success of this project relies on everyone making an effort.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37655, 'rely on/upon someone/something', 'to trust someone or something or to expect him, her, or it to behave in a particular way:', 'British weather can never be relied on - it''s always changing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37656, 'remark on something', 'to notice something and make a remark about it:', 'All his friends remarked on the change in him since his marriage.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37657, 'remember someone to someone', 'to ask someone to say hello to another person for you:', 'Please remember me to your parents.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37658, 'remind someone of something/someone', 'to be similar to, and make someone think of, something or someone else:', 'Your hair and eyes remind me of your mother.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37659, 'render something down', 'to melt fat in order to make it purer', NULL, 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37660, 'render something down', 'to prepare or treat the bodies of dead animals in order to take out the fat and other substances that can be used in other products:', 'to render down animal carcasses', 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37661, 'repair to somewhere', 'to go to another place, usually in a group of people:', 'After dinner, we repaired to the lounge for coffee.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37662, 'repay someone''''s effort, time, attention, etc.', 'If an activity, book, etc. repays your effort, time, attention, etc., it is worth the effort or time, etc. that you spend on it:', 'You should read this article - it would repay your time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37663, 'repeat on someone', 'When food repeats on you, the taste of it comes up again into your mouth:', 'Cucumber always repeats on me.', 'phrasal verb', NULL, NULL, 'UK', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37664, 'report back', 'to bring information to someone in authority:', 'Find out their names and report back to me tomorrow.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37665, 'report to someone', 'Someone you report to at work is the person in authority over you who gives you tasks and checks that you do them:', 'You will report directly to the boss.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37666, 'repose trust/confidence/hope in someone/something', 'to place your trust or hopes in someone or something:', 'We repose a lot of hope in this project.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37667, 'reside in something/someone', 'If a power or quality resides in someone or something, the person or thing has that power or quality:', 'The power to sack employees resides in the Board of Directors.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37668, 'resign yourself to something', 'to make yourself accept something that you do not like because you cannot change it:', '[ + -ing verb ] He resigned himself to living alone.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37669, 'resolve something into something', 'to separate something into different parts:', 'There was a blur of sound, which slowly resolved itself into different words.', 'phrasal verb', NULL, NULL, 'formal, specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37670, 'resort to something', 'to do something that you do not want to do because you cannot find any other way of achieving something:', 'I had to resort to violence/threats to get my money.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37671, 'rest assured', 'to be certain that something will happen:', 'You can rest assured that you’re going to get a good deal.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37672, 'rest easy', 'used to tell someone not to worry and that you are in control of the situation:', '"Rest assured, Mrs Cooper," said the police officer. "We will find your son for you."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37673, 'rest in peace', 'said to express the hope that someone''''s spirit has found peace after death:', 'She was a decent and compassionate woman: may she rest in peace.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37674, 'rest in peace', 'often written on a gravestone', NULL, 'idiom', NULL, NULL, 'abbreviation', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37675, 'rest on someone/something', 'If your eyes rest on something or someone when you are looking around an area, you start looking only at that particular object or person:', 'Her eyes rested on a small wooden box at the back of the shop.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37676, 'rest on your laurels', 'to be satisfied with your achievements and not to make an effort to do anything else:', 'Just because you''ve got your degree doesn''t mean you can rest on your laurels.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37677, 'rest on/upon something', 'If something rests on a particular idea, belief, or fact, it is based on it or needs it in order for it to be true:', 'Christianity rests on the belief that Jesus was the son of God.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37678, 'rest on/upon someone/something', 'to depend on someone or something:', 'Our success rests on an increase in sales.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37679, 'rest up', 'to relax in order to have strength for something:', 'Why don''t you take a nap to rest up for the party?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37680, 'rest with someone', 'If a responsibility or decision rests with someone, they are responsible for it:', 'The authority to call an emergency meeting rests with the president.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37681, 'rest with someone/something', 'to depend on someone or something:', 'Our hopes rest with you.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37682, 'restrict yourself to something', 'to limit yourself to one particular thing or activity:', 'If I''m driving, I restrict myself to one glass of wine.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37683, 'restrict yourself to sth', 'to limit yourself to one particular thing or activity:', 'The company is restricting itself to non-living cargoes at first.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37684, 'result from something', 'If a situation or problem results from a particular event or activity, it is caused by it:', 'His difficulty in walking results from a childhood illness.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37685, 'result in something', 'to cause a particular situation to happen:', 'The fire resulted in damage to their property.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37686, 'retire a number', 'If a sports team retires a number, it stops using the shirt number worn by a particular player when they stop playing, as a way of honouring them.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37687, 'retrace your steps', 'to go back to a place in the same way that you came:', 'She walked straight past her office and then had to retrace her steps.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37688, 'rev up (someone/something)', 'to become more active, or to make someone or something become more active:', 'The hotel is revving up for the busy summer season.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37689, 'revel in something', 'to get great pleasure from a situation or an activity:', 'She''s revelling in her newly found freedom.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37690, 'revenge is sweet', 'said when you feel satisfaction from harming someone who has harmed you', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37691, 'revert to something', 'to return to doing, using, being, or referring to something, usually something bad or less satisfactory:', 'Why does the conversation have to revert to money every five minutes?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37692, 'revert to someone', 'to become the property of a particular person again:', 'When I die, the house will revert to my sister.', 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37693, 'revolve around someone/something', 'to have someone or something as the main or most important interest or subject:', 'The conversation revolved around childcare problems.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37694, 'rewind the clock', 'to go back to an earlier time:', 'I''m sure she wishes she could rewind the clock now.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37695, 'rice and peas', 'a Jamaican dish consisting of rice and kidney beans (= small, dark red beans with a curved shape), cooked in coconut milk :', 'We ate curried goat and rice and peas.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37696, 'rid someone/something of something/someone', 'to cause someone or something to be free of an unpleasant or harmful thing or person:', 'Our aim is to rid this government of corruption.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37697, 'ride (on) a wave of something', 'If you ride (on) a wave of a feeling, you get an advantage from it:', 'The new president is riding (on) a wave of popularity.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37698, 'ride (out) the storm', 'to manage not to be destroyed, harmed, or permanently affected by the difficult situation you experience:', 'The government seems confident that it will ride out the storm.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37699, 'ride a wave of something', 'to be helped by being connected to something attractive or interesting:', 'The president was riding a wave of good feeling about the economy, but it didn''t last long.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37700, 'ride herd on someone/something', 'to be responsible for controlling a group of people and their actions:', 'The new editor will ride herd on the staff, checking on the overall policy and tone of the paper.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37701, 'ride on something/someone', 'When something important, such as your reputation or money, rides on a particular person or thing, it will be won or achieved if that person or thing is successful:', 'The future of the company now rides on the new managing director.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37702, 'ride something out', 'to continue to exist during a difficult situation and until it ends, without serious harm:', 'Many companies did not manage to ride out the recession.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37703, 'ride something out', 'If a ship rides out a period of bad weather, it continues to float during it, without serious damage:', 'The ship managed to ride out the storm.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37704, 'ride tandem', 'If two people ride tandem, they ride together on a tandem (= a bicycle made for two people):', 'When she rode tandem with me, our pedalling rate was 80–90 RPM.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37705, 'ride up', 'If a piece of clothing rides up, it moves up out of position:', 'Your skirt has ridden up at the back.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37706, 'ride, drive, walk, etc. (off) into the sunset', 'to begin a new, happy life at the end of a story:', 'At the end of the film, the two of them ride off into the sunset.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37707, 'riding high', 'doing very well:', 'The soccer team was riding high after winning four straight games.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37708, 'rig someone out', 'to put a particular type of clothing on someone:', 'We rigged ourselves out in tracksuits and running shoes for the race.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37709, 'rig something up', 'to quickly make a piece of equipment from any materials you can find:', 'I rigged up a temporary radio aerial from a coat hanger.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37710, 'rig the market', 'to make the price of shares go up or down in order to make a profit', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37711, 'right away', 'immediately:', 'I need someone to help me right away.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37712, 'right behind someone', 'If you are right behind someone, you give them your complete support:', 'My whole family are right behind me in this crisis.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37713, 'right on the button', 'exactly correct:', 'She was right on the button when she said I''d regret moving out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37714, 'right you are!', 'said to show that you understand and agree:', '"Give me a shout when you''re ready." "Right you are."', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37715, 'right, left, and center', 'all the time or everywhere:', 'He spends money right, left, and center.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37716, 'right, left, and centre', 'all the time or everywhere:', 'He spends money right, left, and centre.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37717, 'right/wrong way round', 'facing the right/wrong way:', 'He put the wheel on the right/wrong way round.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37718, 'ring (someone) back', 'to call someone who called you earlier, or to call someone for a second time:', 'I''m a bit busy - can I ring you back in a few minutes?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37719, 'ring a bell', 'to sound familiar:', 'The name rang a bell but I couldn''t remember where I had heard it before.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37720, 'ring around (sb/sth)', 'to call several people on the phone in order to find out information or organize something:', 'The first thing they did was to ring around all their competitors'' stores undercover to find out their prices.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37721, 'ring off', 'to end a phone conversation intentionally:', 'She said "No, thank you" and rang off hurriedly.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37722, 'ring out', 'When a sound rings out, it is loud and clear:', 'A cry of warning rang out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37723, 'ring someone/something up', 'to make a phone call to someone:', 'She rang me up to say she couldn''t come.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37724, 'ring something up', 'to record the money that has been paid by a customer by pressing buttons on a cash register:', 'I''m sorry, I rang up the wrong amount.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37725, 'ring the changes (on)', 'to do something in a different way in order to make it more interesting:', 'Ring the changes on packed lunches using different types of bread and spicy fillings.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37726, 'ring true', 'If something someone says or writes rings true, it seems to be true:', 'Something about his explanation didn''t quite ring true.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37727, 'ring true/false', 'to seem true/false:', 'Her explanations didn''t ring true.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37728, 'ring with something', 'If a place rings with a sound, it is full of it:', 'The room rang with his screams.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37729, 'ring/sound hollow', 'If something someone says rings hollow, it does not sound true or sincere.', NULL, 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37730, 'rinse something out', 'to quickly wash the inside of something with clean water:', 'I''ll just rinse these glasses out and leave them to dry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37731, 'rip into sb/sth', 'to attack or criticize someone or something with great force:', 'She ripped into her opponent''s proposals, calling them "completely unworkable".', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37732, 'rip someone off', 'to cheat someone by making them pay too much money for something:', 'Bob''s tickets cost much less than ours - I think we''ve been ripped off.', 'phrasal verb', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37733, 'rip something off', 'to remove something very quickly and carelessly:', 'They ripped off their clothes and ran into the sea.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37734, 'rip something off', 'to steal something:', 'He rips stuff off from supermarkets to pay for his heroin.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37735, 'rip something up', 'to tear something into small pieces:', 'She ripped up his letters and burned the pieces.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37736, 'rip through something', 'to move very powerfully through a place or building, destroying it quickly:', 'The explosion ripped through the hotel.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37737, 'rip/tear up the rulebook', 'to do something in a way that is very different to the way in which it is usually done or has been done in the past:', 'The book reveals the story of how the couple tore up the rulebook and created completely new methods of brewing beer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37738, 'ripe for something', 'developed to a suitable condition for something to happen:', 'The company is ripe for takeover.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37739, 'rise above something', 'to not allow something bad to affect your behaviour or upset you:', 'He rose above his pain/bad luck/difficulties.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37740, 'rise and shine!', 'said to tell someone to wake up and get out of bed:', 'Wakey wakey, rise and shine!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37741, 'rise from the dead/grave', 'to become alive again after having died', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37742, 'rise to fame', 'to become famous:', 'He rose to fame in the 90s as a TV presenter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37743, 'rise to something', 'to react to a difficult situation by working hard to succeed:', 'There were some other very good competitors, but Megan rose to the challenge and sang beautifully.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37744, 'rise to the bait', 'to accept an offer or suggestion that seems good but is really a trick:', 'They offered a good salary, but I didn''t rise to the bait.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37745, 'rise to the occasion/challenge', 'to show that you can deal with a difficult situation successfully:', 'In the exam she rose to the occasion and wrote a brilliant essay.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37746, 'rivers of something', 'a large amount of a liquid:', 'Rivers of sweat ran down his back.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37747, 'road to Damascus', 'Your road to Damascus is an experience you have that you consider to be very important and that changes your life.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37748, 'roar ahead', 'to increase or move quickly or suddenly:', 'Property prices continue to roar ahead.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37749, 'roar with something', 'to express an emotion, such as laughter or anger, noisily:', 'She roared with laughter when she saw what he was wearing.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37750, 'roaring drunk', 'very drunk and noisy:', 'They came back from the bars roaring drunk.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37751, 'rob Peter to pay Paul', 'to borrow money from one person to pay back money you borrowed from someone else', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37752, 'rock out', 'to perform rock music loudly and enthusiastically:', 'The singer and his E Street Band played their longest ever concert in Helsinki, Finland, in 2012, when they rocked out for four hours and six minutes.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37753, 'rock out', 'to listen to and enjoy rock music, for example by dancing:', 'Audience members were transported back to the days of roller skates, disco lights, and smoke machines as they rocked out to the music of the Bee Gees.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37754, 'rock the boat', 'If you rock the boat, you do or say something that will upset people or cause problems:', 'Don''t rock the boat until the negotiations are finished.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37755, 'rock up', 'to arrive somewhere:', 'They rocked up two hours late, dressed in ball gowns.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37756, 'rocky road', 'If you are on a rocky road, you are experiencing a difficult period and have a lot of problems:', 'Analysts predict a rocky road ahead for the economy.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37757, 'roll (something) out', 'to make a new product, service, or system available for the first time:', 'The government plans to roll out a series of tax cuts over the next few years.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37758, 'roll around', '(of a time or event) to happen:', 'She wondered if he would still be there when spring rolled around.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37759, 'roll back something', 'to limit or reduce the effects of a particular arrangement:', 'He wants to roll back laws designed to clean up the air, water, and land.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37760, 'roll something back', 'to reduce the cost or price of something:', 'The furniture dealer is rolling back the prices on all beds for this week only.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37761, 'roll by', 'If an amount of time rolls by, it passes:', 'The years rolled by, and I didn''t see her again until she was married with two children.', 'phrasal verb', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37762, 'roll in', 'to arrive in great numbers or amounts:', 'Once our business gets started, the money will be rolling in.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37763, 'roll on the weekend, five o''''clock, etc.', 'said when you want time to go quickly because you are looking forward to something:', 'I can''t wait to be finished with this project - roll on October!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37764, 'roll out the red carpet', 'to welcome someone as a very important person or guest:', 'We''ll roll out the red carpet for the senator.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37765, 'roll out the red carpet', 'to be very pleased about something, and encourage and support it:', 'All three cities rolled out the red carpet for the aerospace giant.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37766, 'roll out the red carpet (for someone)', 'to give a guest special treatment:', 'New York rolled out the red carpet for the astronauts.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37767, 'roll over', 'to agree to what someone wants, especially because you are under pressure or under someone''''s control:', '"If the bill passes, we''re certainly not going to roll over and say that''s fine," he said.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37768, 'roll (something) over something', 'If you roll over something on a computer screen, you move the mouse over an active place so that you can see information that is hidden under it:', 'If you roll your mouse over a word, its definition will appear.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37769, 'roll up your sleeves', 'to prepare for hard work:', 'There''s a lot of work to do, so roll up your sleeves and get busy.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37770, 'roll something up', 'to fold something around itself to make the shape of a ball, or to fold cloth around itself to make a piece of clothing shorter:', 'Could you roll up that string for me?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37771, 'roll up', 'to arrive at a particular place or event, usually late:', 'They rolled up at the party two hours late and rather drunk.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37772, 'roll with the punches', 'to be able to deal with a series of difficult situations', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37773, 'roll your eyes', 'to move your eyes around in a circle because someone has said or done something stupid or strange:', '"Don''t pay any attention to what he says," Carrie said rolling her eyes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37774, 'roll your eyes', 'to move your eyes upwards as a way of showing that you are annoyed or bored after someone has done or said something', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37775, 'rolled into one', 'If someone or something has several qualities rolled into one, the person or thing has all of those qualities:', 'He is a father, sales manager, and athlete all rolled into one.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37776, 'rolling in the aisles', 'infml laughing very hard:', 'The comedian had the audience rolling in the aisles.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37777, 'romp home/in', 'to win easily:', 'She is riding the fastest horse and is certain to romp home.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37778, 'romp through something', 'to successfully do something, quickly and easily:', 'Rory expected to romp through the test and interviews.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37779, 'roof something in/over', 'to put a roof over a place or area:', 'The council has decided to roof over the open-air swimming pool.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37780, 'room for doubt', 'a possibility of something being true:', 'There is little room for doubt about what happened.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37781, 'room for improvement', 'a possibility or hope that someone or something will improve:', 'Her writing is better but there is still room for improvement.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37782, 'room for maneuver', 'the opportunity to change your plans or choose between different ways of doing something:', 'The law in this area is very strict and doesn''t allow us much room for maneuver.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37783, 'room for manoeuvre', 'the opportunity to change your plans or choose between different ways of doing something:', 'The law in this area is very strict and doesn''t allow us much room for manoeuvre.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37784, 'root and branch', 'completely:', 'Racism must be eliminated, root and branch.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37785, 'root around (somewhere)', 'to search for something, especially by looking through other things:', 'She was rooting around in her drawer for a pencil.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37786, 'root for someone', 'to show support for someone who is doing something difficult:', 'Good luck! We''re all rooting for you.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37787, 'root for someone', 'to support a sports team or a sports player and want them to win:', 'Who do you root for in the Super Bowl?', 'phrasal verb', 'B1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37788, 'root something out/up', 'to remove a whole plant, including the roots, from the ground:', 'I suggest you root out those weeds before they take hold.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37789, 'root something/someone out', 'to search and find something or someone that is difficult to find:', 'I''ve rooted out an old pair of shoes that might fit you.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37790, 'root something/someone out', 'to find and remove a person or thing that is causing a problem:', 'Ms Campbell has been appointed to root out inefficiency in this company.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37791, 'rooted to the spot', 'unable to move:', 'She was rooted to the spot with fear/amazement.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37792, 'roots and all', 'completely:', 'Racism must be eliminated, roots and all.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37793, 'rope someone in', 'to persuade someone to do something for you:', 'At the last minute, we roped in a couple of spectators to complete the team.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37794, 'rope someone in', 'to force or persuade someone to join a group or become involved in something:', 'The National Guard roped him in for another two years of service.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37795, 'rope someone into something', 'to persuade a person or group to do something:', 'I was roped into playing softball last night.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37796, 'rope something/somewhere off', 'to surround an area or place with ropes in order to keep people out:', 'The police roped off the scene of the crime.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37797, 'rot in jail, prison, etc.', 'to stay in prison for a very long time:', 'Ruben Carter was left to rot in jail for most of his life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37798, 'rough and ready', 'produced quickly, with little preparation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37799, 'rough and ready', 'simple but good enough:', 'rough and ready accommodation', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37800, 'rough and tumble', 'fighting between children that is not serious:', 'It was just a bit of rough and tumble.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37801, 'rough and tumble', 'a busy activity that people do in a very forceful way:', 'She enjoys the rough and tumble of politics.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37802, 'rough edges', 'If something such as a product, a piece of work or a performance has rough edges, some parts of it could be improved:', 'He''s a great player, but his game still has a few rough edges.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37803, 'rough edges', 'If a person has rough edges, they do not always behave well and politely:', 'Age and experience have softened his rough edges (= have made him a more polite or gentle person).', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37804, 'rough it', 'to live without comforts, esp. running water, heat, etc.:', 'We roughed it until our house was repaired.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37805, 'rough justice/luck', 'something that happens to you that is severe or unfair:', 'It seems like rough justice that he should lose his house as well as his wife.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37806, 'rough someone up', 'to hit and kick someone, usually to frighten or threaten them', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37807, 'rough something in', 'If you rough a drawing in, you draw the basic lines, without the detail.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37808, 'rough something out', 'If you rough out a drawing, idea, or plan, you draw or write the main parts of it without giving its details.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37809, 'round about', 'approximately:', 'We''ll be at your house at round about nine o''clock, okay?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37810, 'round and round', 'moving in circles:', 'The skater twirled round and round.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37811, 'round of applause', 'a period of time during which people are clapping:', 'The singer got a big round of applause.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37812, 'round on someone/something', 'to suddenly turn and attack someone or something:', 'The fox rounded on its pursuers.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37813, 'round on someone/something', 'to criticize someone who has criticized you:', 'The mayor rounded on his critics with a very forceful speech.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37814, 'round something down', 'to reduce a number to the nearest whole or simple number', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37815, 'round something off', 'to make something that is pointed or sharp into a smooth, curved shape by rubbing it:', 'He used a special machine to round off the corners of the old table.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37816, 'round something off', 'to complete an event or activity in a pleasant or satisfactory way:', 'To round off her education, her father sent her to a Swiss finishing school.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37817, 'round something out', 'to complete something:', 'More research is needed to round out the article.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37818, 'round something/someone up', 'to find and bring together a group of animals or people:', 'The cowboys rounded the cattle up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37819, 'round something up', 'to increase a number to the nearest whole or simple number', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37820, 'round sth down/up', 'to reduce or increase a number to the nearest 1, 10, 100, etc.:', 'The figures were rounded down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37821, 'round the corner', 'very near here:', 'There''s a great restaurant just round the corner.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37822, 'round/around the clock', 'all day and all night:', 'Doctors and nurses worked round the clock to help those injured in the train crash.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37823, 'rout someone out', 'to make someone come out of the place where they are:', 'His wife had to rout him out of the crowd.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37824, 'row back', 'to change a previous decision, opinion, or statement:', 'The management rowed back on the decision the very next day.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37825, 'rub along', 'If two people rub along, they work or live together in a satisfactory way:', 'My flatmate and I rub along okay together.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37826, 'rub it in', 'to make someone feel worse about something the person already feels embarrassed about:', 'I know I shouldn’t have paid that much for the poster – don’t rub it in, OK?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37827, 'rub off', 'If a quality or characteristic that someone has rubs off, other people begin to have it because they have been with that person and learned it from them:', 'His enthusiasm is starting to rub off on the rest of us.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37828, 'rub off on someone', 'to become part of someone because that person has been in a place where it was present:', 'I like to think that our love of reading will rub off on our children.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37829, 'rub salt in/into the wound', 'to make a difficult situation even worse for someone:', 'Losing was bad enough. Watching them receiving the trophy just rubbed salt into the wound.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37830, 'rub shoulders (with)', 'to meet and spend time with someone:', 'She claims that she rubs shoulders with royalty all the time.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37831, 'rub someone the wrong way', 'to annoy someone without intending to:', 'As soon as they met they started to rub each other the wrong way.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37832, 'rub someone up the wrong way', 'to annoy someone without intending to:', 'As soon as they met they started to rub each other up the wrong way.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37833, 'rub someone''''s nose in it', 'to say or do things that make someone remember that they failed or got something wrong:', 'Sue failed her exam, so just to rub her nose in it, I put my certificate up on the wall.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37834, 'rub something down', 'to rub something with a rough cloth, brush, or paper until its surface is smooth, or clean and shiny:', 'Rub the wood down with fine sandpaper until it is smooth.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37835, 'rub something/someone down', 'to use a cloth to dry an animal or person:', 'I used a towel to rub the dog down after his bath.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37836, 'rub something in', 'to talk to someone about something that you know they want to forget because they feel bad about it:', 'OK, I made a mistake - you don''t have to rub it in.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37837, 'rub something out', 'to remove writing or a mark from something by rubbing it with a piece of rubber or a cloth:', 'It''s in pencil, so you can rub it out if you need to.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37838, 'rub someone out', 'to murder someone:', 'He was rubbed out by the Mafia.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37839, 'ruck (something) up', 'If material rucks up, it forms a lump (= mass) or folds, and if something rucks it up, it pushes the material into a lump or folds:', 'The blankets had rucked up around his feet.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37840, 'rue the day', 'to feel very sorry about an event:', 'She''ll rue the day (that) she bought that house.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37841, 'ruffle someone''''s feathers', 'to upset or annoy someone:', 'She knows how to ruffle his feathers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37842, 'rule OK', 'is the best:', 'The graffiti on the wall said "Liverpool rules OK".', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37843, 'rule of thumb', 'a practical and approximate way of doing or measuring something:', 'A good rule of thumb is that a portion of rice is two handfuls.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37844, 'rule something or someone in', 'to decide or say officially that something is possible or will definitely happen, or that something or someone is suitable:', 'Are we prepared to negotiate? We haven''t ruled it in or out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37845, 'rule something or someone out', 'to decide or say officially that something is impossible or will not happen, or that something or someone is not suitable:', 'The police haven''t yet ruled out murder.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37846, 'rule something out', 'to prevent something from happening:', 'This recent wave of terrorism has ruled out any chance of peace talks.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37847, 'rule something with an iron hand/fist', 'to control a group of people very firmly, having complete power over everything they do', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37848, 'rule the roost', 'to be the person who makes all the decisions in a group:', 'In that family it is the grandma who rules the roost.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37849, 'rules are made to be broken', 'used to say that it is good and acceptable to not obey a rule', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37850, 'rumble on', 'If something such as a disagreement rumbles on, it continues for a long time without being resolved:', 'The dispute rumbled on for months.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37851, 'run (something) into something/someone', 'to drive a vehicle into an object or a person in another vehicle by accident:', 'I had to brake suddenly, and the car behind ran into me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37852, 'run into someone', 'to meet someone you know when you are not expecting to:', 'Graham ran into someone he used to know at school the other day.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37853, 'run into something', 'If you run into problems, you begin to experience them:', 'We ran into bad weather/debt/trouble.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37854, 'run into something', 'to reach a particular cost or amount, as a total:', 'The repairs will probably run into thousands of dollars.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37855, 'run a mile', 'to be extremely unwilling to be involved:', 'He''d run a mile if I asked him to marry me.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37856, 'run across someone', 'to meet someone you know when you are not expecting to:', 'I ran across several old friends when I went back to my hometown.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37857, 'run across something', 'to experience a problem when you are not expecting to:', 'We''ve run across a slight problem with the instruction manual.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37858, 'run afoul of something', 'to do something you are not allowed to do, esp. breaking a rule or law:', 'Foreigners who run afoul of the law are punished severely.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37859, 'run after someone/something', 'to chase someone or something that is moving away from you:', 'Why do dogs run after cats?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37860, 'run after something', 'to try very hard to get or achieve something:', 'She has spent her life running after fame and fortune.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37861, 'run after someone', 'to try to start a sexual relationship with someone:', 'He''s always running after women.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37862, 'run against someone/something', 'to oppose or have an effect that is not helpful towards someone or something:', 'Luck is really running against you tonight!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37863, 'run aground/ashore', 'If a ship or boat runs aground/ashore, it hits the coast, sometimes becoming stuck there.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37864, 'run along!', 'said to children to tell them to go away:', 'Run along now, children!', 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37865, 'run amok', 'to behave without control in a wild or dangerous manner:', 'There were 50 little kids running amok at the snack bar.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37866, 'run and run', 'to be performed successfully for a long period of time:', 'This show will run and run.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37867, 'run around', 'to be very busy doing a lot of different things:', 'I''m exhausted - I''ve been running around all morning.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37868, 'run around after someone', 'to do a lot of things for someone else, especially when that person should be able to do more for himself or herself:', 'I seem to spend most of my time running around after those kids.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37869, 'run around in circles', 'to be very active but with few results:', 'We''ve been running around in circles trying to get the information we need, but no-one will tell us anything.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37870, 'run around with someone', 'to spend a lot of time with someone:', 'She''s running around with Micky and his friends these days.', 'phrasal verb', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37871, 'run away', 'to leave a place or person secretly and suddenly:', 'He ran away from home when he was only twelve.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37872, 'run away', 'to avoid dealing with a problem or difficult situation:', 'She accused him of running away from his responsibilities.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37873, 'run away to sea', '(especially of a boy or young man) to leave your family and become a sailor:', 'My grandfather ran away to sea when he was twelve.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37874, 'run away with someone', 'If an animal or machine that you are riding runs away with you, you lose control of it and it carries you away:', 'Her horse ran away with her.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37875, 'run away with someone', 'If a feeling or idea runs away with you, you cannot control it and it makes you behave stupidly:', 'Sometimes my imagination runs away with me and I convince myself that they are having an affair.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37876, 'run away with something', 'to win a competition or prize very easily:', 'She ran away with four first prizes.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37877, 'run errands', 'to go out to buy or do something:', 'After school he runs errands for his father.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37878, 'run high', 'If feelings are running high, people are angry or excited.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37879, 'run in the family', 'If a quality, ability, disease, etc. runs in the family, many members of the family have it:', 'Intelligence seems to run in that family.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37880, 'run interference', 'to deal with problems for someone as they happen:', 'His no-nonsense assistant runs interference for him on just about everything, from work to social life.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37881, 'run interference', 'in American football, to protect the player who has the ball by physically preventing the opposing team from coming near him', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37882, 'run its course', 'to develop and finish naturally:', 'The doctor''s advice is to let the fever run its course.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37883, 'run off', 'to leave somewhere or someone suddenly:', 'You can''t run off (home) now, just when I need you!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37884, 'run something off', 'If you run off copies of something, you print them:', '[ + two objects ] Could you run me off five copies of this, please?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37885, 'run something off', 'to quickly and easily write something that is usually slow or difficult to write, such as a piece of poetry or music:', 'Kate can run off a sonnet in half an hour on any subject you like.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37886, 'run something off', 'to win points easily in a competition:', 'Iowa ran off 12 straight points to take the lead.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37887, 'run off with something', 'to leave a place or person suddenly after having stolen something:', 'He ran off with $10,000 of the company''s money.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37888, 'run on', 'If an event runs on, it continues for longer than expected:', 'The game/speech/discussion ran on for hours.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37889, 'run on', 'If time runs on, it seems to pass quickly:', 'Time''s running on - let''s get this job finished soon!', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37890, 'run on something', 'If a machine runs on a particular type or supply of power, it uses that power to work:', 'Some calculators run on solar power.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37891, 'run out', 'to finish, use, or sell all of something, so that there is none left:', 'I''ve run out of milk/money/ideas/patience.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37892, 'run out', 'If a supply of something runs out, all of it has been used or it is completely finished:', 'The milk has run out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37893, 'run out', 'If a document or official agreement runs out, the period of time for which it lasts finishes:', 'My passport runs out next month - I must get it renewed.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37894, 'run out', 'used to say that there is not much time left in which to achieve something:', 'Time is running out for the men trapped under the rubble.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37895, 'run someone out', 'If you are run out in cricket, a player on the opposing team throws the ball at the wicket you are running towards and hits it before you can reach it, and your turn as batsman ends:', 'Their best batsman was run out for (= having scored) 99.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37896, 'run out of steam', 'to suddenly lose the energy or interest to continue doing what you are doing:', 'The peace talks seem to have run out of steam.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37897, 'run out on someone/something', 'to leave someone you are having a relationship with or something you are responsible for, without warning and usually causing problems:', 'She ran out on him two months ago, leaving him to take care of their two children.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37898, 'run out the clock', 'to use all the time that is still available:', 'He was supposed to fall on the ball, allowing San Jose to run out the clock.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37899, 'run over/through something', 'to quickly say or practise something:', 'I''ll just run over what''s been said so far, for latecomers who missed the first speakers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37900, 'run over/through something', 'to examine a document or subject with someone in order to explain it or to get their help or opinion on it:', 'I''d like to run over the main points of the article with you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37901, 'run rings around someone', 'If someone runs rings around you, they are very much better, faster, or more successful at something than you are:', 'Our girls'' hockey team have run rings around all their opponents this year.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37902, 'run rings round someone', 'If someone runs rings round you, they are very much better, faster, or more successful at something than you are:', 'Our girls'' hockey team have run rings round all their opponents this year.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37903, 'run riot', 'If people run riot, they behave in a way that is not controlled, running in all directions or being noisy or violent:', 'I dread them coming here because they let their kids run riot.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37904, 'run riot', 'If your imagination runs riot, you have a lot of strange, exciting, or surprising thoughts:', 'My imagination was running riot, thinking of all the ways that I could spend the money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37905, 'run roughshod over someone', 'to act without caring how you will affect someone or something:', 'He ran roughshod over his employees when he thought they weren''t working hard enough.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37906, 'run round', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37907, 'run round in circles', 'to be very active but with few results:', 'We''ve been running round in circles trying to get the information we need, but no-one will tell us anything.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37908, 'run round like a headless chicken', 'to be very busy doing a lot of things, but in a way that is not very effective', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37909, 'run someone close', 'to be nearly as good, fast, etc. as someone else:', 'She got 90 percent, but Fred ran her close with 87 percent.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37910, 'run someone out of town (on a rail)', 'to force someone to leave a town:', 'The sheriff and his men ran the horse thieves out of town.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37911, 'run someone ragged', 'If you run someone ragged, you make them very tired, usually by giving them too much work or work that is too demanding:', 'The kids have run me ragged this week - I''m glad they''re going back to school tomorrow.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37912, 'run someone/something down', 'to criticize someone or something, often unfairly:', 'He''s always running himself down.', 'phrasal verb', 'C1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37913, 'run someone/something down', 'to hit and injure a person or animal with a vehicle, especially intentionally:', 'Two masked men on motorbikes tried to run me down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37914, 'run someone/something down', 'to find someone or something after following or searching for him, her, or it for a long time:', 'I finally ran Mr Green down in/to a house in the country.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37915, 'run (something) down', 'to reduce a business or organization in size or importance, or to become reduced in this way:', 'The government is secretly running down the troop levels.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37916, 'run (something) down', 'If a machine or device such as a clock or battery runs down, it loses power, or if you run it down, you cause this to happen:', 'These batteries can be recharged when they run down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37917, 'run something down', 'If a large ship runs down a smaller one, it hits it.', NULL, 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37918, 'run yourself down', 'to make yourself tired and ill:', 'Since he took that extra job, he''s really run himself down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37919, 'run someone/something over', 'If a vehicle or its driver runs over someone or something, the vehicle hits and drives over him, her, or it:', 'I think we''ve just run a rabbit over.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37920, 'run over', 'If liquid runs over, it flows over the edges of something, because there is too much of it:', 'The water/The bath is running over - quick, turn the taps off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37921, 'run over (something)', 'to continue after the expected finishing time:', 'We''re starting to run over time, so could you keep your speeches short, please.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37922, 'run someone/something to ground', 'to find someone or something after a lot of searching and problems:', 'Detectives finally ran the terrorists to ground in an apartment building in Chicago.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37923, 'run something by someone', 'to tell someone about something so that that person can give their opinion about it:', 'Would you run your idea by me one more time?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37924, 'run something in', 'If you run in a vehicle, you use it carefully and slowly for a short time when it is new, so that you do not damage its engine.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37925, 'run someone in', 'If the police run someone in, they find that person and take them to a police station.', NULL, 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37926, 'run something up', 'If you run up a debt, you do things that cause you to owe a large amount of money:', 'She stayed two weeks at the hotel and ran up a bill that she couldn''t pay.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37927, 'run something up', 'to quickly make something such as a piece of clothing from material:', '[ + two objects ] I can run you up some curtains in a few hours, if you want.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37928, 'run something up', 'to make the price or value of something increase:', 'Heavy buying ran the price of stocks up higher than expected.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37929, 'run something up', 'to raise a flag into the air on a pole or mast:', 'They''ve run up a British flag on the roof.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37930, 'run sth by/past sb', 'to tell someone about something, to make sure they understand or approve:', 'I would like to run some ideas by you before we agree to the deal.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37931, 'run the gamut', 'to include the whole range of possible things within a group or type:', 'Their projects run the gamut from mobile homes to luxury condos.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37932, 'run the gauntlet', 'to have to deal with a lot of people who are criticizing or attacking you:', 'Every day they had to run the gauntlet of hostile journalists on their way to school.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37933, 'run the risk of doing something', 'to make a particular result possible:', 'When doctors do not follow government guidelines, they run the risk of being sued.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37934, 'run the risk of doing something', 'to do something although something bad might happen because of it:', 'If you tell him the truth, you run the risk of hurting his feelings.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37935, 'run the show', 'to be the leader, who is in control of a group of people doing something:', 'If you need help, ask Mark - he''s running the show.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37936, 'run through someone''''s head/mind', 'If something is running through your head/mind, you cannot stop thinking about it or singing it silently:', 'I''ve had that tune running through my head all day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37937, 'run through someone''''s mind/head', 'to suddenly think of something:', 'It ran through my mind that I was being tricked by Charlie.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37938, 'run through something', 'to look at, examine, or deal with a set of things, especially quickly:', 'We ran through the list, but none of the machines seemed any good.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37939, 'run through something', 'If a quality runs through something, it is in all parts of it:', 'Melancholy runs through all her stories.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37940, 'run through something', 'to use up an amount of something quickly:', 'It took him just a few months to run through all the money his father left him.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37941, 'run someone/something through', 'to push a sword or similar pointed weapon right into a person or animal:', 'He drew his sword and ran the villain through.', 'phrasal verb', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37942, 'run to something', 'to reach a particular amount, level, or size:', 'The new encyclopedia runs to several thousand pages.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37943, 'run to something', 'to have enough money to buy something or (of an income, etc.) to be enough to buy something:', 'I can lend you €1,000, but I can''t run to more than that.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37944, 'run to something', 'If your taste or skill runs to something, that is the type of thing that you enjoy or can manage to do:', 'I doubt if his musical taste runs to opera.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37945, 'run up against something', 'to experience an unexpected difficulty:', 'The plans for the new bridge ran up against strong local opposition.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37946, 'run wild', 'If someone, often a child, runs wild, that person behaves as they want to without being controlled by anyone.', NULL, 'idiom', 'C2', NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37947, 'run with it', 'infml to work independently to achieve something:', 'The Japanese took that technology and ran with it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37948, 'run with something', 'to accept something, start to use it, and develop it further:', 'The Japanese took that technology and ran with it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37949, 'run your eye over something', 'to look quickly at the whole of something:', 'Can I have a copy of the article to run my eye over, before it''s printed?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37950, 'run yourself into the ground', 'to make yourself very tired by working too much:', 'We ran ourselves into the ground to meet the July deadline.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37951, 'run/go deep', 'If a feeling or problem runs deep, it is strong or serious and has existed for a long time:', 'The anger runs deep on both sides.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37952, 'run/go like clockwork', 'to happen exactly as planned, without any trouble:', 'The party went like clockwork.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37953, 'runners and riders', 'all the horses and jockeys (= riders) that are competing against each other in a race:', 'Here are the main runners and riders in the race.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37954, 'runners and riders', 'the people who are competing to get a job or be elected:', 'The speculation about the runners and riders to succeed her was unmatched.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37955, 'running battle', 'an argument that lasts over several different occasions:', 'I''ve had a running battle with the neighbours over whose responsibility that fence is.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37956, 'running on empty', '(of an engine or vehicle) having almost no fuel left:', 'His diesel engine was running on empty.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37957, 'running on empty', 'having almost reached a point where you are unable to continue, because you have almost no energy, money, etc. left:', 'His campaign treasury is running on empty.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37958, 'running with blood', 'If a place is running with blood, a lot of fighting is happening and many people are being hurt or killed there:', 'During the revolution the streets were running with blood.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37959, 'rush into something', 'If you rush into something such as a job, you start doing it without having really decided if it is the right thing to do or having considered the best way to do it.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37960, 'rush someone into (doing) something', 'to forcefully persuade someone to do something without giving them time to decide if they really want to do it', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37961, 'rush something out', 'to very quickly produce something and make it available to sell:', 'When the war started, several publishers rushed out books on the conflict.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37962, 'rush sth through', 'to cause something to happen or be produced too quickly:', 'The bill was rushed through parliament.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37963, 'rush/run someone off their feet', 'to cause someone to be very busy:', 'I''ve been rushed off my feet all morning.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37964, 'rustle something up', 'to make something quickly, usually a meal from the food that is available:', 'Give me a minute and I''ll rustle something up for supper.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37965, 'sack out', 'to go to bed:', 'It''s late - I''m going to sack out.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37966, 'sad to say', 'it is sad, regrettable, or embarrassing that this fact is true:', 'Sad to say, the violin was never found.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37967, 'sadder but wiser', 'If someone is sadder but wiser after a bad experience, they have suffered but they have also learned something from it.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37968, 'saddle someone with something', 'to give someone a responsibility or problem that they do not want and that will cause them a lot of work or difficulty:', 'The company is saddled with debt.', 'phrasal verb', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37969, 'saddle up something', 'to fasten a seat on the back of a horse, or to ride a horse:', 'Fred saddled up a horse and set out for Kingston to pick up the mail.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37970, 'safe and sound', 'not hurt or damaged:', 'Three days later, the hikers were found safe and sound.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37971, 'safeguard against something', 'to do things that you hope will stop something unpleasant from happening:', 'A good diet will safeguard against disease.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37972, 'safety first', 'said to mean that it is best to avoid any unnecessary risks and to act so that you stay safe', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37973, 'sail against the wind', 'to be trying to achieve something that is unlikely to succeed because most people would oppose it:', 'He''s sailing against the wind in his attempt to stop women joining the club.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37974, 'sail close to the wind', 'to do something that is dangerous or only just legal or acceptable:', 'You were sailing a little close to the wind there when you made those remarks about his wife.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37975, 'sail in', 'to start an activity enthusiastically:', 'The children sailed into the pile of cakes and in minutes the cakes were gone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37976, 'sail in', 'to attack someone using words:', 'The president sailed into her opponents with an angry speech.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37977, 'sail through (something)', 'to succeed very easily in something, especially a test:', 'Rachel sailed through her finals and got A''s in everything.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37978, 'sally forth', 'to leave a safe place in a brave or confident way in order to do something difficult:', 'The minister opened the door and sallied forth to face the angry crowd.', 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37979, 'salt of the earth', 'very good, honest, and reasonable, and not thinking you are special in any way:', 'They were such a lovely couple. They really were the salt of the earth.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37980, 'salt something away', 'to save something, often money, secretly:', 'He salted away a fortune over the years and no one ever knew!', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37981, 'same again', 'said when you want another drink of the same type as you have just had:', '"What are you having, David?" "Same again, please."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37982, 'same difference', 'said when you agree that what you said was not exactly correct, but you think the difference is not important:', '"He was driving a red car." "Actually, it was maroon." "Same difference."', 'idiom', NULL, NULL, 'not standard', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37983, 'same here', 'used when you agree with what someone has said or you have experienced the same thing as they have:', '"I thought that film was awful!" "Same here!"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37984, 'same old same old', 'used to say that a situation or someone''''s behaviour remains the same, especially when it is boring or annoying:', 'Most people just keep on doing the same old same old every day.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37985, 'same to you', 'used as an answer to someone who has greeted or insulted you in order to wish the same thing to them:', '"Have a good holiday!" "Same to you!" (= I hope you have a good holiday too.)', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37986, 'sandwich someone/something between someone/something', 'If you are sandwiched between two people or things, you are in a small space between them:', 'On the train I was sandwiched between two very large men.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37987, 'sandwich something together', 'to put a layer of something between two things that sticks them together:', 'I sandwiched the cakes together with chocolate butter cream.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37988, 'sarcasm is the lowest form of wit', 'said to mean that sarcasm is unkind and not very funny', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37989, 'save (something) up', 'to keep money so that you can buy something with it in the future:', 'It took me months to save up enough money to go travelling.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37990, 'save face', 'to keep your reputation and avoid others losing respect for you:', 'We said he left "to pursue other interests" to let him save face, but actually we fired him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37991, 'save on something', 'to avoid using something so that you do not have to pay for it:', 'It was a warm winter, so we saved on electricity.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37992, 'save someone''''s bacon/neck', 'to help someone avoid getting into trouble', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37993, 'save the day', 'to do something that prevents a likely defeat or failure:', 'The team seemed to be heading for disaster until a late goal saved the day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37994, 'save your breath', 'used to say that it is not worth talking to someone because they will not listen to you:', 'I don''t know why I even try to talk to him - I might as well save my breath.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37995, 'save your own skin/hide', 'to protect yourself from danger or difficulty, without trying to help other people', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37996, 'save/keep money for a rainy day', 'to save money for a time when it might be needed unexpectedly:', 'Luckily she had saved some money for a rainy day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37997, 'saved by the bell', 'something that you say when a difficult situation ends suddenly before you have to do or say something that you do not want to:', 'Luckily my bus arrived before I had time to reply. Saved by the bell.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37998, 'savour of something', 'to have particular characteristics or qualities that make people think of something, especially something unpleasant:', 'His behaviour does rather savour of hypocrisy.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (37999, 'saw something down', 'to make something fall to the ground by cutting it with a saw', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38000, 'saw something off', 'to remove something by cutting it with a saw:', 'She sawed off the dead branches of the tree.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38001, 'saw something up', 'to cut something into smaller pieces using a saw:', 'I''ll saw the logs up into smaller pieces.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38002, 'say a lot about something/someone', 'to clearly show or express something about someone or something:', 'It says a lot about her that she''s willing to help people she doesn''t even know.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38003, 'say cheese', 'something that someone who is taking a photograph of you tells you to say so that your mouth makes the shape of a smile', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38004, 'say goodbye to something', 'to accept that you will not have something any more or that you will not get it:', 'Once you have kids, you can say goodbye to going out every weekend.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38005, 'say no more', 'said to show that you understand exactly what the other person is suggesting:', '"I saw him coming out of her flat." "Say no more!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38006, 'say something to yourself', 'to think something:', 'I said to myself, I’d better take care of that now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38007, 'say the word', 'used to tell someone that you will do what they want at the time they ask you:', 'You only have to/Just say the word, and I''ll come and help.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38008, 'say this/that much for someone/something', 'to say something good about someone or something considered to be bad:', 'I''ll say this much for Kay, she always agrees to help whenever we ask her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38009, 'say uncle', 'to admit failure', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38010, 'say when', 'said when you are pouring a drink for someone and you want them to tell you when to stop pouring', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38011, 'say your piece', 'to say what you are obviously wanting to say:', 'Just say your piece and then go.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38012, 'says something about someone/something', 'to show what a particular person or thing is like:', 'The way he drives says a lot about his character.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38013, 'says who?', 'used when you are arguing with someone, to show that you do not accept or agree with what they say:', 'You''re the best? Says who?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38014, 'sb wouldn''''t touch something/someone with a bargepole/barge pole', 'someone does not want a particular thing or person at all, or does not want to have anything at all to do with it or them:', 'Don''t tell granny we made the cake or she''s not going to touch it with a bargepole.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38015, 'sb wouldn''''t touch something/someone with a ten-foot pole', 'someone does not want a particular thing or person at all, or does not want to have anything at all to do with it or them:', 'If you''re not successful, they won''t touch you with a ten-foot pole.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38016, 'sb''''s way or the highway', 'used for saying that someone will only accept their own way of doing something:', 'Some coaches say, "it''s my way or the highway".
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38017, 'scale back/down (something)', 'to reduce something in size, amount, or production:', 'Sid will have to scale back his plans.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38018, 'scale something down', 'to make something smaller than it was or smaller than it was planned to be:', 'A shortage of money has forced them to scale down the project.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38019, 'scale something up', 'to increase the size, amount, or importance of something, usually an organization or process:', 'My company is scaling up its operations in Western Asia.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38020, 'scale the heights', 'If you scale the heights of a type of work, you are very successful in it:', 'At the age of 35, she had already scaled the heights of the acting profession.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38021, 'scare someone into doing something', 'to persuade someone to do something by frightening them:', 'The two boys scared the old man into handing over his wallet.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38022, 'scare someone shitless', 'to make someone extremely frightened', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38023, 'scare someone to death', 'to frighten someone very much:', 'Thunderstorms scare her to death.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38024, 'scare someone/something away/off', 'to make a person or an animal so frightened that he, she, or it goes away:', 'Don''t make too much noise or you''ll scare away the birds.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38025, 'scare someone away/off', 'to make someone so worried about doing something that they decide not to do it:', 'If you charge as much as that, you''ll scare customers off.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38026, 'scare something up', 'to find or get something despite difficulties or limited supplies:', 'There''s hardly any food in the house, but I''ll scare something up from these leftovers.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38027, 'scare the (living) daylights out of someone', 'to frighten someone very much:', 'You scared the daylights out of me, yelling like that.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38028, 'scare the bejabbers out of someone', 'to frighten, annoy, bore, etc. someone very much:', 'It''s the fact that this is happening to good kids from good families that scares the bejabbers out of us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38029, 'scare the bejesus out of someone', 'to frighten, annoy, bore, etc. someone very much:', 'I was in the middle of a typhoon in 2012 and it scared the bejesus out of me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38030, 'scare, frighten, etc. the (living) daylights out of someone', 'to frighten someone very much:', 'Don''t jump out on me like that! You scared the living daylights out of me!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38031, 'scare/frighten the life out of someone', 'to frighten someone very much', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38032, 'scent blood', 'to believe that someone you are competing against is having difficulties and to use this to get an advantage for yourself:', 'The manager has already made some serious errors of judgment and it is clear that other employees scent blood.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38033, 'school of hard knocks', 'If you learn something in the school of hard knocks, you learn it as a result of difficult or unpleasant experiences.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38034, 'scissors and paste', 'If something such as a piece of writing is a scissors and paste job, it is not original, but is made up from parts of other people''''s work.', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38035, 'scoop something out', 'to remove something that is inside something else with a spoon:', 'Cut the tomato in half and scoop out the seeds.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38036, 'scoop something/someone up', 'to lift something or someone with your hands or arms in a quick movement:', 'She scooped the children up and ran with them to safety.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38037, 'scoop the pool', 'to win all the prizes that are available:', 'Cuba scooped the pool in the boxing at this year''s Olympics.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38038, 'scope something/someone out', 'to look carefully to see if something or someone is interesting or attractive:', 'We scoped out the local area to see if it would be a good place to rent a flat.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38039, 'score points (with sb)', 'to do something that will make someone like you:', 'He tried really hard to be funny and cool to try to score points with Amanda.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38040, 'score points off someone', 'to say things that make someone else seem silly or wrong:', 'He''s always trying to score points off people and it''s really irritating.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38041, 'score something out/through', 'to draw a line through a piece of writing:', 'He scored out two names on the list.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38042, 'scour something out', 'to make a hole by a movement that is repeated continuously over a long period of time:', 'The fast-moving water had scoured out a channel in the rock.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38043, 'scrape a living', 'to only just earn enough money to provide yourself with food, clothing, and a place to live:', 'He settled in Paris, where he scraped a living writing short stories and magazine articles.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38044, 'scrape by', 'to have only enough money to pay for the basic things you need:', 'Even with both of us working, we earn just enough to scrape by.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38045, 'scrape by/along', 'to manage to live when you do not have enough money and other necessary things:', 'He lost his job, so the family had to scrape by on one small salary.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38046, 'scrape by/along', 'to manage with difficulty to get a successful result or to reach an acceptable standard:', 'I only studied Spanish for a year but I can scrape by in most situations.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38047, 'scrape home', 'to win by a very small amount in a competition:', 'The reigning champion scraped home just 2.9 seconds ahead of his nearest rival.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38048, 'scrape something/someone together/up', 'to manage with great difficulty to collect enough of something, especially money, or to find the things or people that you need:', 'I finally scraped together enough money for a flight home.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38049, 'scrape the bottom of the barrel', 'to use the worst people or things because that is all that is available:', 'Richard''s in the team? You really are scraping the bottom of the barrel!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38050, 'scrape through (something)', 'to succeed in something but with a lot of difficulty:', 'He managed to scrape through his final exams.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38051, 'scratch around for something', 'to look for something that is very difficult to find because it is rare:', 'The editor of the local paper says he''s really scratching around for stories this week.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38052, 'scratch beneath the surface', 'to look further than what is obvious:', 'If you scratch beneath the surface you''ll find she''s really a very nice person.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38053, 'scratch the surface', 'to deal with only a small part of a subject or a problem:', 'All the payments we’ve made have hardly scratched the surface of the amount we borrowed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38054, 'scratch your head', 'to think hard about something:', 'A lot of people must be scratching their heads about which way to vote.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38055, 'scratch/scrape the surface', 'to deal with only a very small part of a subject or a problem:', 'There''s far more to be said - I''ve only had time to scratch the surface in this talk.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38056, 'scream (out) for something', 'to need something very much:', 'This matter is screaming out for attention.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38057, 'scream your head off', 'to scream very loudly:', 'I screamed my head off on the roller coaster.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38058, 'scream/shout blue murder', 'to show your anger about something, especially by shouting or complaining very loudly:', 'He''ll scream blue murder if he doesn''t get his way.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38059, 'screen out something/someone', 'to prevent something or someone undesirable from coming in:', 'Home water filtration systems are supposed to screen out toxins and other contaminants.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38060, 'screen something off', 'to separate one area from another using a wall or other vertical structure:', 'We can screen off part of the room and use it as a temporary office.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38061, 'screw (something) up', 'to make a mistake, or to spoil something:', 'I totally screwed up the chemistry exam.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38062, 'screw someone up', 'When bad experiences or people screw you up, they make you worried and unhappy or damage your personality:', 'It really screwed him up when he saw his friend get killed.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38063, 'screw around', 'to have sex with a lot of people or with people other than your husband or wife', NULL, 'phrasal verb', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38064, 'screw it', 'slang I do not care what happens:', 'It takes a lot of work to be successful, but most people are lazy and say screw it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38065, 'screw it/you/them!', 'used when expressing extreme anger:', '"Screw it!" he said. "If they won''t give us the money, we''ll just take it."', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38066, 'screw something out of someone', 'to get something from someone by using force or threats:', 'We''ll screw every last penny out of him.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38067, 'screw up your courage', 'to force yourself to be brave:', 'I screwed up my courage and went in to see the director.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38068, 'scrounge around', 'to look in different places or in a particular place where you might find something that you need:', 'She scrounged around in the tool box for a tack or nail to hang the sign up with.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38069, 'scrub up', 'When a doctor scrubs up or scrubs in, he or she washes his or her hands and arms very carefully before performing a medical operation.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38070, 'scrub up well', 'said about someone when they have made an effort to look nice:', 'Mary scrubs up well.', 'idiom', NULL, NULL, 'informal, approving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38071, 'sea of something', 'a lot of something:', 'She looked out at the sea of faces in the audience.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38072, 'seal of approval', 'a statement or sign that someone in an important position approves of something:', 'The mayor has given the proposal her seal of approval.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38073, 'seal someone''''s fate', 'If an action, event, or situation seals your fate, nothing can stop some unpleasant thing happening to you:', 'From the moment she stepped into the busy road her fate was sealed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38074, 'seal something in', 'to prevent a substance or quality from being lost from something during a process such as cooking:', 'Fry the meat quickly in hot oil to seal in the flavour/juices.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38075, 'seal something off', 'to prevent people from entering an area or building, often because it is dangerous:', 'Two more bombs have been discovered since the police sealed off the area.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38076, 'search me!', 'something that you say when you do not know the answer to a question:', '"Where''s Jack?" "Search me!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38077, 'search something/someone out', 'to find something or someone after searching:', 'Despite the warm weather, we searched out some snow and went skiing.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38078, 'seat of learning', 'a place where people are educated:', 'The Sorbonne is a world-famous seat of learning.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38079, 'second best', 'not as good as the best and therefore not wanted as much:', 'She refuses to settle for second best - she strives for perfection.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38080, 'second to none', 'as good as or better than all others:', 'The conditions that these prisoners are kept in are second to none.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38081, 'section something off', 'to separate one part of an area from the rest of the area:', 'Security agents sectioned off the area where she shopped.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38082, 'see a man about a dog', 'You might say you have to see a man about a dog when you do not want to say what you are really doing, especially when going to the toilet:', 'I''ve just got to see a man about a dog. I''ll be back in a minute.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38083, 'see about something', 'to prepare for or deal with an action or event, or to arrange for something to be done:', 'It''s getting late - I''d better see about lunch.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38084, 'see eye to eye', 'If two people see eye to eye, they agree with each other:', 'My sisters don''t see eye to eye with me about the arrangements.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38085, 'see fit', 'If you see fit to do something, you think it is good or necessary to do it:', 'She saw fit to pull her son out of the school.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38086, 'see fit (to do something)', 'to think it is good or necessary to do something:', 'You can leave it here or take it home with you, whichever you see fit.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38087, 'see in the New Year', 'to not go to bed on 31 December until after twelve o''''clock at night in order to celebrate the start of a new year', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38088, 'see life', 'to experience many different and often unexpected things:', 'As a volunteer on the childcare project, I really saw life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38089, 'see past something', 'to not be influenced or have your opinion changed by something :', 'He has been able to see past stereotypes and photographed the Cherokee as a dynamic presence in today''s world.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38090, 'see red', 'to become very angry:', 'People who don''t finish a job really make me see red.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38091, 'see sense/reason', 'to be reasonable and have good judgment:', 'We talked to her for an hour, but we couldn''t make her see sense.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38092, 'see someone in hell before ...', 'If you would see someone in hell before you would do something they have suggested, you are very determined not to do it:', 'I''d see her in hell before I''d agree to an arrangement like that.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38093, 'see someone off', 'to go to the place that someone is leaving from in order to say goodbye to them:', 'My parents saw me off at the airport.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38094, 'see someone off', 'to send away someone who is attacking you or who is not wanted, usually forcefully:', 'The caretaker ran out and saw off the boys who had been damaging the fence.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38095, 'see someone/something off', 'to defeat someone or something, or to deal with him, her, or it effectively so that that person or thing can no longer cause harm:', 'The company believes it has now seen off this unwelcome bid.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38096, 'see someone right', 'to make certain that someone is helped or treated well:', 'Ask Mrs Martin at the desk over there about the invoices - she''ll see you right.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38097, 'see someone through something', 'to support someone during a difficult time:', 'He was a real friend to see me through my long illness.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38098, 'see someone through something', 'to help or support someone during a difficult period in their life:', 'He was a prisoner of war for five years, but his courage saw him through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38099, 'see something through', 'to continue doing a job or activity until it is finished, especially when it is difficult:', 'The degree would take me three years to complete, but I was determined to see it through.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38100, 'see through someone/something', 'to realize that someone is trying to deceive you to get an advantage, or that someone''''s behaviour is intended to deceive you, and to understand the truth about the situation:', 'They were very friendly, but it didn''t take long to see through them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38101, 'see someone''''s true colors', 'to see someone''''s real character for the first time, especially when it is unpleasant:', 'It was only when they started to work together that she began to see his true colors.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38102, 'see someone''''s true colours', 'to see someone''''s real character for the first time, especially when it is unpleasant:', 'It was only when they started to work together that she began to see his true colours.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38103, 'see something at a glance', 'know and understand almost immediately:', 'She could see at a glance that something was seriously wrong.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38104, 'see something coming', 'to expect something to happen:', 'No one else had expected the factory to close, but we saw it coming.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38105, 'see something in someone/something', 'to believe that someone or something has a particular quality:', 'Her teachers saw something special in her.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38106, 'see something out', 'to wait or last until the end of a difficult event or situation:', 'The besieged town doesn''t have enough food to see the month out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38107, 'see someone out', 'to go to the door of a building or room with someone who does not live or work there, when they are leaving:', 'My secretary will see you out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38108, 'see yourself out', 'to leave a building or room by yourself after visiting someone there:', 'It''s ok - I''ll see myself out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38109, 'see something with your own eyes', 'to see something yourself, especially when it is something that you would not believe to exist or be true if you did not see it:', 'They took all the money and left. I saw it with my own eyes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38110, 'see stars', 'If you see stars, you are partly unconscious because you have been hit on the head.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38111, 'see the back of someone/something', 'If you are pleased to see the back of someone or something, you are pleased that you no longer have to be involved with him, her, or it:', 'The hotel staff were glad to see the back of such a difficult guest.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38112, 'see the colour of someone''''s money', 'To see the colour of someone''''s money is to make certain that a person is going to pay for something:', '"I''ll have one of those." "Let''s see the colour of your money first!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38113, 'see the joke', 'to understand something funny and find it funny yourself:', 'Everyone else laughed loudly, but I didn''t see the joke.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38114, 'see the last of something/someone', 'to not see something or someone again because that thing or person has gone away or has ended', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38115, 'see the light', 'If you see the light, you suddenly understand something you didn''''t understand before.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38116, 'see the light of day', 'When something sees the light of day, it appears for the first time.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38117, 'see the point of something', 'to understand the importance of or the reason for something:', 'They couldn''t see the point of more training.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38118, 'see things in black and white', 'to have a simple view of what is right and wrong, or good and bad', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38119, 'see to something/someone', 'to deal with a person or task that needs to be dealt with or is waiting to be dealt with:', '"These letters need posting." "I''ll see to them later."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38120, 'see you (later)', 'goodbye', NULL, 'idiom', 'A1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38121, 'see you soon', 'used for saying goodbye to someone you are going to meet again soon:', 'I''ll see you soon!', 'idiom', 'A1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38122, 'see your way (clear) to doing something', 'to agree to do or allow something:', 'Could you see your way to letting us borrow the machine on Wednesday?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38123, 'see/catch you later!', 'a way of saying goodbye:', '"Bye." "See you later."', 'idiom', 'B1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38124, 'seeing is believing', 'said to mean that if you see something yourself, you will believe it to exist or be true, despite the fact that it is extremely unusual or unexpected:', 'I never thought Mark would get out of bed before lunchtime on a Saturday, but seeing is believing!', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38125, 'seeing things', 'If you are seeing things, you are imagining that things are happening when they are not:', 'I could have sworn I saw Marie come in just now. I must have been seeing things.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38126, 'seek someone/something out', 'to look for someone or something, especially for a long time until you find him, her, or it:', 'While he was at the library, Steve decided to seek out some information on the history of the area.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38127, 'seize on/upon something', 'to use, accept, or take advantage of something quickly or enthusiastically:', 'The story was seized on by the tabloid press, who printed it under huge headlines.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38128, 'seize up', 'to stop being able to move or work in the normal way:', 'The washing machine totally seized up on Thursday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38129, 'sell into sth', 'to sell shares or bonds in a particular situation:', 'The Bank''s usual policy is to sell into a rising or stable market.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38130, 'sell out', 'to sell all of the supply that you have of something:', 'We sold out of the T-shirts in the first couple of hours.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38131, 'sell out', 'If a supply of something sells out, there is no more of that thing to buy:', 'The first issue of the magazine sold out within two days.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38132, 'sell out', 'When a film, concert, etc. is sold out, all of the tickets for it have been sold:', 'We couldn''t get seats - the concert was sold out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38133, 'sell out', 'to sell your business or part of your business:', 'They decided to sell out to their competitors.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38134, 'sell (someone) out', 'to not do what you have promised someone you will do or what you should do because you will get more advantages for yourself if you do something else:', 'French farmers feel they''ve been sold out by their government in the negotiations.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38135, 'sell someone a bill of goods', 'to deceive someone into buying or believing something that has no value', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38136, 'sell someone down the river', 'to put someone in a difficult or dangerous situation by not acting as you had promised to act, usually in order to win an advantage for yourself', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38137, 'sell someone on something', 'to persuade someone that something is good, valuable, or useful:', 'The filmmakers sold me on the idea that my book would work on the screen.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38138, 'sell someone/yourself/something short', 'to not consider someone or something to be as valuable or good as he, she, or it deserves:', 'Don''t sell yourself short - you''ve got the skills and the experience.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38139, 'sell something off', 'to charge a low price for something to encourage people to buy it:', 'They''re selling off last year''s stock at half price.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38140, 'sell something off', 'to sell all or part of a business:', 'The company announced that it would be selling off its hotel business.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38141, 'sell sth back to sb/sth', 'to sell something to the person you bought it from:', 'You can cash in your shares by selling them back to the mutual fund.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38142, 'sell sth forward', 'to make an arrangement to sell a commodity in the future at a fixed price:', 'The group sold forward a mammoth 3.5 million ounces of gold.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38143, 'sell through', 'to be sold to customers:', 'Even with best-sellers, you can''t just sit back and assume the run will sell through.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38144, 'sell up', 'to sell your house or company in order to go somewhere else or do something else:', 'They sold up and retired to the West Country.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38145, 'sell your soul (to the devil)', 'to be persuaded to do something, especially something bad, because of the money or other reward you will receive for doing it', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38146, 'send (off/away) for/to something', 'to write to an organization to ask them to send you something:', 'I''ve sent off for a catalogue.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38147, 'send a message', 'to make someone understand that a particular thing is right or true, or to make someone understand what your attitude is:', 'By taking this action, we are sending a message that bullying will not be tolerated.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38148, 'send a signal (to sb) that', 'to show or warn that something is true:', 'The change should send a signal to financial institutions that we are serious about tackling fraud.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38149, 'send away for something', 'to request something by mail:', 'Carson sent away for a magic kit.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38150, 'send chills down/up someone''''s spine', 'to make someone feel very frightened:', 'His words sent a chill down her spine.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38151, 'send for someone', 'to send someone a message asking them to come to see you:', 'Do you think we should send for a doctor?', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38152, 'send out for something', 'to ask for something to be brought to you from another place, by using the phone or sending a message:', 'There''s not much to eat in the fridge. Should I send out for a pizza?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38153, 'send shivers down your spine', 'to feel very frightened or excited:', 'The thought of what might have happened to us sent shivers down my spine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38154, 'send shivers down/up someone''''s spine', 'to make someone feel very frightened or excited:', 'The way he looked at me sent shivers down my spine.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38155, 'send shudders/a shudder down your spine', 'to cause you to feel extremely worried or frightened:', 'When I think of what might have happened in the accident, it sends shudders down my spine.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38156, 'send someone away with a flea in their ear', 'to angrily tell someone to go away:', 'A young kid came asking for money but I sent him away with a flea in his ear.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38157, 'send someone down', 'to send someone to prison:', 'He was sent down for armed robbery.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38158, 'send someone down', 'to ask someone to leave a college or university before the end of the course because they have done something wrong:', 'She was sent down from Oxford for taking drugs.', 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38159, 'send someone packing', 'to ask someone to leave immediately:', 'There were some kids at the door asking for money but I sent them packing.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38160, 'send someone to Coventry', 'If a group of people send someone to Coventry, they refuse to speak to that person, usually as a punishment for having done something to upset the group.', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38161, 'send someone to eternity', 'to kill someone', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38162, 'send someone up', 'to send someone to prison:', 'He was sent up for armed robbery.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38163, 'send someone/something up', 'to make someone or something seem stupid by copying him, her, or it in a funny way:', 'The show was very funny - they were sending up sports commentators.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38164, 'send someone’s love (to someone)', 'to express someone''''s good feelings to someone else:', 'Maggie sends her love to you and the kids.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38165, 'send something back', 'to return something to the person who sent it to you, especially because it is damaged or not suitable:', 'I had to send the shirt back because it didn''t fit me.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38166, 'send something in', 'to send something to an organization:', 'The magazine asked its readers to send in their comments about the new style of presentation.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38167, 'send someone in', 'to send soldiers, police, etc. to a place in order to deal with a dangerous situation:', 'UN troops were sent in as the situation got worse.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38168, 'send something off', 'to send a letter, document, or parcel by post:', 'Have you sent off your application form yet?', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38169, 'send someone off', 'to order a sports player to leave the playing area during a game because they have done something wrong:', 'He was sent off for swearing at the referee.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38170, 'send someone off', 'to express good wishes and say goodbye to someone who is leaving a place:', 'A buffet lunch was organized to send her off in style.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38171, 'send someone off', 'to show your respect and say goodbye to someone who has died, especially at a funeral:', 'The people there are famous for sending their dead off in style.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38172, 'send something on', 'to send something from someone''''s old address to their new one:', 'Paul moved back to New York and he asked me to send on his letters.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38173, 'send something out', 'to produce something in a way that causes it to spread out from a central point:', 'The equipment sent out a regular high-pitched signal.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38174, 'send something out', 'to send something to a lot of different people, usually by post or email:', 'We sent out the wedding invitations about three weeks ago.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38175, 'send word', 'to send someone to give another person a message:', 'She sent word with her secretary that she would be unable to attend the meeting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38176, 'send/give out (all) the wrong signals', 'to make people believe or think something that is not correct:', 'If the government refuses to provide aid, it would send out all the wrong signals to the rest of the world.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38177, 'separate the sheep from the goats', 'to make clear which people in a particular group are of a higher ability than the others:', 'The uphill stages of the race will really separate the sheep from the goats.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38178, 'separate the wheat from the chaff', 'to separate things or people that are of high quality or ability from those that are not:', 'The first round of interviews really separates the wheat from the chaff.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38179, 'serve out', 'in tennis, to serve in the last game of a set or match and win it:', 'Williams served out, taking the first set in 26 minutes.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38180, 'serve something out', 'to share an amount of food or drink between people by giving some to each:', 'We began serving out food at 12 and it was all gone by 12:20.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38181, 'serve something out', 'to continue to work, hold a position, or stay somewhere for a period of time that has been decided:', 'Should Mr. Murphy simply serve out the rest of his contract?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38182, 'serve something out', 'in tennis, to serve in the last game of a set or match and win it:', 'Federer served out the second set at 5-4.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38183, 'serve someone right', 'If you say that something bad serves someone right, you mean that that person deserves it:', '"He hit me!" "It serves you right. You shouldn''t have been so mean to him."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38184, 'serve something up', 'to provide something or make something available to people :', 'We were served up with a list of titles that best matched what we were looking for.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38185, 'serve (something) up', 'to put food on plates for people to eat:', 'Come on everyone, I''m ready to serve up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38186, 'set about something', 'to start to do or deal with something:', '[ + -ing verb ] I have no idea how to set about changing a tyre on a car.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38187, 'set about someone', 'to attack someone:', 'Her attacker set about her with a knife.', 'phrasal verb', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38188, 'set an example', 'to behave in a way that other people should copy:', 'You should be setting a good example to your younger brother.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38189, 'set fire to something/someone', 'to cause something or someone to start burning:', 'The protesters set fire to several vehicles.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38190, 'set foot in somewhere', 'to go to a place:', 'He refuses to set foot in an art gallery.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38191, 'set great, little, etc. store by something', 'to consider something to be of great, little, etc. importance or value:', 'She''s setting a lot of store by this job interview - I only hope she gets it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38192, 'set in', 'When something unpleasant sets in, it begins and seems likely to continue in a serious way:', 'This rain looks as if it has set in for the rest of the day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38193, 'set in stone', 'to be very difficult or impossible to change:', 'The schedule isn’t set in stone, but we’d like to stick to it pretty closely.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38194, 'set in your ways', 'not liking change in your life:', 'They’re very set in their ways – they always eat dinner exactly at 6:00.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38195, 'set off/out', 'to start a journey:', 'What time will we have to set off for Grandma''s house tomorrow?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38196, 'set on/upon someone', 'to attack someone:', 'He was set upon by a vicious dog.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38197, 'set on/upon someone', 'to surround or catch someone and prevent them from escaping:', 'As he left the theatre, the singer was set upon by fans desperate for autographs.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38198, 'set out', 'to start an activity with a particular aim:', 'She set out with the aim of becoming the youngest ever winner of the championship.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38199, 'set out', 'to start a journey', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38200, 'set something out', 'to give the details of something or to explain it, especially in writing, in a clear, organized way:', 'The board has set out its goals/plans/proposals for the coming year.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38201, 'set something out', 'to arrange something, usually a number of things, in an attractive or organized way:', 'The farmers'' market was full of brightly coloured vegetables set out on stalls.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38202, 'set sail', 'to begin a trip on a ship or boat:', 'The ship set sail on January 2, 1589.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38203, 'set someone against someone', 'to cause one person to argue or fight with another person:', 'This war has set neighbour against neighbour.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38204, 'set something against something', 'to consider something in relation to another thing and compare their different qualities or effects:', 'You have to set the advantages of the plan against the disadvantages.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38205, 'set something against something', 'to use or record one thing, especially the cost of something, in order to reduce or remove the effect of another:', 'The cost of business travel and entertainment can be set against tax.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38206, 'set someone back (something)', 'to cost someone a large amount of money:', 'Buying that suit must have set you back.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38207, 'set something/someone back', 'to delay an event, process, or person:', 'The opening of the new swimming pool has been set back by a few weeks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38208, 'set something back', 'to reduce something to a weaker or less advanced state:', 'This defeat has set back their chances of winning the competition.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38209, 'set someone straight', 'to tell someone the true facts about a situation that the person had not understood:', 'I had to set him straight about what really happened.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38210, 'set someone''''s pulse racing', 'to make someone excited:', 'This is a movie that will set your pulse racing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38211, 'set someone''''s teeth on edge', 'If something, especially a noise, sets your teeth on edge, it annoys you very much:', 'That DJ''s voice really sets my teeth on edge.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38212, 'set someone/something on someone', 'to make an animal or person attack someone:', 'The security guards set their dogs on the intruders.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38213, 'set something aside', 'to save something, usually money or time, for a special purpose:', 'He had some money in an account that he''d set aside for his kids.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38214, 'set something aside', 'If a judge or court sets aside a previous decision or judgment, they state that it does not now have any legal effect, usually because they consider it to have been wrong:', 'The Court of Appeal set aside his conviction.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38215, 'set something aside', 'to decide that you will not be influenced by your own feelings or opinions because they are not important at a particular time:', 'In times of war people tend to set aside political differences.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38216, 'set something aside', 'to ignore or not think about a particular fact or situation while considering a matter:', 'Setting aside the question of cost, what do you think of the idea in principle?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38217, 'set something down', 'to write or print something, especially to record it in a formal document:', 'The rules of the club are set down in the members'' handbook.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38218, 'set something down', 'to land an aircraft', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38219, 'set someone down', 'If a vehicle sets down a passenger, it stops so that the passenger can get out:', 'The cab set us down a long way from our hotel, and we had to walk.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38220, 'set something forth', 'formal for
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38221, 'set something in motion', 'to begin something:', 'Newly discovered evidence set a second investigation in motion.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38222, 'set something off', 'to cause an activity or event, often a series of events, to begin or happen:', 'The court''s initial verdict in the police officers'' trial set off serious riots.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38223, 'set something off', 'to cause a loud noise or explosion, such as that made by a bomb or an alarm (= a warning sound) to begin or happen:', 'Terrorists set off a bomb in the city centre.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38224, 'set something off', 'to make something look attractive by providing a contrast (= attractive difference) to it:', 'The new yellow cushions nicely set off the pale green of the chair covers.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38225, 'set someone off', 'to cause someone to start doing something:', '[ + -ing verb ] Every time I think about it, it sets me off laughing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38226, 'set something to music', 'to write or provide music for a poem, story, or other words so that it can be performed:', 'The poem was set to music in 1888.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38227, 'set something up', 'to formally establish a new company, organization, system, way of working, etc.:', 'A committee has been set up to organize social events for the students.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38228, 'set something up', 'to arrange for an event or activity to happen:', 'We need to set up a meeting to discuss the proposals.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38229, 'set someone up', 'to establish someone or yourself in a business or position:', 'After he left college, his father set him up in the family business.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38230, 'set someone up', 'to provide the money that someone needs for an important task or activity that is expected to last a long time:', 'Winning the lottery has set them up for life.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38231, 'set someone up', 'to provide someone with the energy or health that you need for a particular period of time:', 'A good breakfast really sets you up for the day.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38232, 'set someone up', 'to trick someone in order to make them do something, or in order to make someone seem guilty of something that they have not done:', 'They claimed that they weren''t selling drugs, but that they''d been set up by the police.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38233, 'set something/someone up', 'to provide someone or something with all the necessary things for a particular activity or period of time:', 'I think we''re set up with everything we need for the journey.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38234, 'set (something) up', 'to prepare something for use, especially by putting the different parts of it together:', 'We only had a couple of hours to set up before the exhibition opened.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38235, 'set something/someone apart', 'If a quality or characteristic sets someone or something apart, it shows him, her, or it to be different from, and usually better than, others of the same type:', 'What set her apart from the other candidates for the job was that she had a lot of original ideas.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38236, 'set something/someone on fire', 'to cause something or someone to start burning:', 'A peace activist had set herself on fire in protest over the government''s involvement in the war.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38237, 'set sth (off) against sth', 'to use or record one thing, especially the cost of something, in order to reduce or remove the effect of another:', 'Costs of new equipment or machinery, such as a computer, can also be set against tax.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38238, 'set sth (off) against sth', 'to say that an amount of money should be considered a cost of your business and that therefore you should not pay tax on it:', 'You can set off anything you spend on computer equipment against tax.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38239, 'set the Thames on fire', 'to cause a lot of excitement or strong feelings:', 'His books sell fairly well, but they don''t exactly set the Thames on fire.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38240, 'set the agenda', 'to decide what subjects other people should discuss and deal with', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38241, 'set the bar high/low', 'to set a high/low standard for something:', 'They''ve set the bar high in terms of what people expect from them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38242, 'set the heather on fire', 'to cause a lot of excitement or strong feelings:', 'The controversy, which sparked in Scotland, set the heather on fire and quickly spread to the House of Lords.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38243, 'set the scene', 'to describe a situation where something is about to happen:', 'First, let''s set the scene - it was a dark, wet night with a strong wind blowing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38244, 'set the scene', 'to make something possible or likely to happen:', 'His resignation set the scene for a company crisis.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38245, 'set the scene/stage', 'used to mean that conditions have been made right for something to happen, or that something is likely to happen:', 'This weekend''s talks between the two leaders have set the scene for a peace agreement to be reached.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38246, 'set the stage (for something)', 'to make it possible for something else to happen:', 'The new evidence sets the stage for a long and interesting trial.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38247, 'set the tone (for something)', 'to establish a particular mood or character for something:', 'The governor''s speech set the tone for the whole conference.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38248, 'set the wheels in motion', 'to do something that will cause a series of actions to start:', 'I thought a phone call to the right person might set the wheels in motion.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38249, 'set to', 'to start working or dealing with something in an energetic and determined way:', 'If we all set to, we should be able to finish the job in a week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38250, 'set to', 'to begin to fight', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38251, 'set up shop', 'to start your own business:', 'She set up shop back in 1965 with a very small restaurant in the Kings Road.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38252, 'set your heart on something/doing something', 'to want to get or achieve something very much:', 'She''s set her heart on having a pony.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38253, 'set your mind to something', 'to be determined to do or have something:', 'You can lose weight if you set your mind to it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38254, 'set your sights on something', 'to decide to achieve something:', 'Jenny has set her sights on winning the competition.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38255, 'set yourself up as something', 'to say that you are a particular type of person:', 'He sets himself up as an expert on vegetable growing, but he doesn''t seem to me to know much about it.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38256, 'set/put someone''''s mind at rest/ease', 'to stop someone from worrying about something:', 'Chris phoned to say they''d arrived safely, so that really put my mind at rest.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38257, 'set/put the record straight', 'to write or say something in order to make the true facts known:', 'She''s decided to write her memoirs to set the record straight once and for all.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38258, 'set/put the seal on something', 'to make the result of something certain:', 'The meeting set the seal on the negotiations.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38259, 'set/put your mind to something', 'to decide you are going to do something and to put a lot of effort into doing it:', 'If you''d just put your mind to it, I''m sure you could do it.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38260, 'settle a score', 'to punish someone for something wrong that they did to you in the past and that you cannot forgive:', 'Police believe the killer was a gang member settling a score with a rival gang.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38261, 'settle an (old) score', 'to harm someone because they have harmed you in the past:', 'The president used his speech to settle some old scores with his opponents.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38262, 'settle an account', 'to harm someone because they have harmed you in the past:', 'Police think that the killings may be a result of accounts being settled between local gangs.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38263, 'settle down', 'to become familiar with a place and to feel happy and confident in it:', 'She quickly settled down in her new house/job/school.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38264, 'settle down', 'to start living in a place where you intend to stay for a long time, usually with your partner:', 'Eventually I''d like to settle down and have a family, but not yet.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38265, 'settle (someone) down', 'to become quiet and calm, or to make someone become quiet and calm:', 'Come on all of you, stop talking and settle down please!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38266, 'settle down to something', 'to give all of your attention to something you are doing:', 'When the work was done, we settled down to a home-cooked meal.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38267, 'settle for something', 'to accept or agree to something, or to decide to have something, although it is not exactly what you want or it is not the best:', 'They were hoping to sell their car for £2,000, but settled for £1,500.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38268, 'settle in', 'to become familiar with somewhere new, such as a new house, job, or school, and to feel comfortable and happy there:', 'Once we''ve settled in, we''ll have you over for dinner.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38269, 'settle someone in', 'to help someone to become familiar with a new job or a new place where they will be living, working, or staying:', 'The nurse will be with you soon - she''s settling a new patient in at the moment.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38270, 'settle into somewhere/something', 'to become comfortable in a place or doing an activity:', 'Students settled into their desks and took out their notebooks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38271, 'settle on something', 'to agree on a decision:', 'Have you settled on a name for the baby?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38272, 'settle something on someone', 'to formally give money or property to someone:', 'When he died, he settled his money on his children.', 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38273, 'settle on/upon sth', 'to choose something or decide to do something after considering it carefully:', 'The committee have yet to settle on a site for the new premises.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38274, 'settle the score', 'do something to someone because that person did something harmful or insulting to you in the past:', 'After being embarrassed in front of the class, Dan was determined to settle the score.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38275, 'settle up', 'to pay someone the money that you owe them:', 'Would you like to settle up now, sir?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38276, 'settle your affairs', 'to decide what will happen to your possessions after your death, usually by making a legal document', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38277, 'settle your nerves', 'to make yourself feel calmer:', 'After the accident, he went for a walk to try to settle his nerves.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38278, 'settle your stomach', 'to make you feel less sick:', 'Drink this tea, it''ll help to settle your stomach.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38279, 'sew something up', 'to close or repair something by sewing the edges together:', 'Let me sew up that hole in your jeans.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38280, 'sew something up', 'If you have a competition or game sewn up, you are certain to win it or get control of it:', 'The Democratic candidate appears to have the election sewn up.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38281, 'sew something up', 'to complete all the arrangements for a successful business agreement:', 'It''s going to take another week or two to sew up this deal.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38282, 'sex something up', 'to make something seem more exciting or interesting:', 'How can we sex up science writing?', 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38283, 'shack up', 'to start living in the same house as sexual partners, without being married:', 'I hear Tony and Helen have shacked up together.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38284, 'shade something in', 'to make part of a picture darker', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38285, 'shades of gray', 'the fact of it not being clear in a situation what is right and wrong:', 'The movie presents a straightforward choice between good and evil, with no shades of gray.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38286, 'shades of grey', 'the fact of it not being clear in a situation what is right and wrong:', 'The film presents a straightforward choice between good and evil, with no shades of grey.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38287, 'shake a leg', 'used to tell someone to hurry or act more quickly:', 'Come on, Nick, shake a leg or we''ll never be ready in time.', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38288, 'shake like a leaf', 'to shake in a way that you cannot control because you are very nervous or frightened:', 'He had gone completely white and was shaking like a leaf.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38289, 'shake out', 'to change over a period of time before a final result is known:', 'We have to wait and see how it all shakes out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38290, 'shake something out', 'to hold something such as a piece of cloth at one end and shake it up and down to get rid of dirt or folds:', 'I was on the back doorstep shaking out a rug.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38291, 'shake something out', 'to shake your head to allow your hair to fall freely, after removing objects such as pins that were holding it in place:', 'She took off her hat and shook out her long curls.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38292, 'shake someone down', 'to get money from someone by using threats or tricks', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38293, 'shake someone/somewhere down', 'to search a person or place carefully, usually in order to find things that are stolen or illegal:', 'We can''t shake down the whole building - only the suspect''s apartment.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38294, 'shake down', 'to become organized or established after a period of change:', 'Give the new arrangements time to shake down - I''m sure they''ll be OK.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38295, 'shake someone out of something', 'to stop someone from feeling a particular way by shocking them, frightening them, or making them suddenly understand something:', 'A sudden noise shook him out of his daydream.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38296, 'shake someone up', 'If an unpleasant experience shakes someone up, it makes them feel shocked and upset:', 'I think she was pretty shaken up by the accident.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38297, 'shake something up', 'to cause large changes in something such as an organization, usually in order to make improvements:', 'Technological changes have shaken up many industries.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38298, 'shake something off', 'to get rid of an illness:', 'I hope I can shake off this cold before the weekend.', 'phrasal verb', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38299, 'shake someone/something off', 'to get away from someone or something that will not stop following you:', 'He drove through the red lights in an attempt to shake off the police car that was chasing him.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38300, 'shake someone/something off', 'to beat an opponent, or to free yourself from someone or something that is limiting you:', 'I have no doubt that we will be able to shake off the challenge from our rivals.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38301, 'shake/rock something to its foundations', 'to seriously damage, upset, or change an organization or someone''''s beliefs:', 'The scandal has shaken the Democratic Party to its foundations.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38302, 'shame on you', 'you should feel ashamed of what you have done:', 'I can''t believe you lied to her - shame on you!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38303, 'shape up', 'to develop:', 'How are your plans shaping up?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38304, 'shape up', 'to improve your behaviour or performance:', 'I''ve been told that if I don''t shape up, I''ll lose my job.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38305, 'shape up or ship out!', 'said to tell someone that they must improve their performance or behaviour or they will have to leave', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38306, 'share a platform', 'to give speeches or to perform at the same public event:', 'It was the first time the opposing candidates had shared a platform.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38307, 'share and share alike', 'used to encourage everyone to have an equal amount of something:', 'Don''t keep all those chocolates to yourself - share and share alike.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38308, 'sharing is caring', 'used for saying that it is good or important to share things:', 'Sharing is caring: Eating pizza should be a communal experience, no matter what the menu says.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38309, 'sharpen (something) up', 'to perform better, or to improve the performance of something:', 'If the company doesn''t sharpen up soon, it will go out of business.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38310, 'sharpen up your act', 'to improve your behaviour or performance:', 'He really needs to sharpen up his act, or he''ll never get to university.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38311, 'shave something off something', 'to reduce something by the stated amount:', 'The new high speed trains will shave 25 minutes off the journey time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38312, 'shave something off/from something', 'to cut a very thin piece from an object or surface:', 'She shaved a few millimetres off the bottom of the door, so that it would open more easily.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38313, 'shed light on sth', 'to provide information about something or to make something easier to understand:', 'Tracking technologies have shed light on the birds'' social nature.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38314, 'shell (something) out', 'to pay or give money for something, usually unwillingly:', 'Having shelled out €150 for the tickets, I wasn''t going to miss the show.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38315, 'shift (your) ground', 'to change your opinion:', 'He''s annoying to argue with because he keeps shifting his ground.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38316, 'shift for yourself', 'to earn your own income or buy and cook your own food, etc.:', 'He left home at 18 and had to shift for himself.', 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38317, 'shift gears', 'to suddenly change what you are doing:', 'The first half is a comedy, but then the movie shifts gears.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38318, 'shifting/rearranging the deckchairs on the Titanic', 'used for saying that someone is wasting time dealing with things that are not important, and is ignoring a much more serious problem', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38319, 'shine out', 'If a quality shines out, it is strong and easy to see:', 'Her honesty and sincerity positively shine out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38320, 'shine through', 'If a quality shines through, it is strong and easy to see, usually in a particular situation:', 'Take off your make-up and let your natural beauty shine through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38321, 'ship out', 'to leave a situation:', 'The company sold up and shipped out of its Dublin base.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38322, 'ship sth out', 'to send something away from somewhere to somewhere else:', 'The timber is shipped out of the stockyard by truck.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38323, 'ship someone off', 'to send someone away somewhere:', 'The children were shipped off to their grandparents'' house for the holidays.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38324, 'shit a brick', 'to become very frightened:', 'We were all shitting bricks as the truck missed the car by inches.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38325, 'shit on someone', 'to treat someone very badly and unkindly:', 'He made his money by shitting on other people.', 'phrasal verb', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38326, 'shiver (up and) down your spine', 'a frightened or excited feeling:', 'At its most terrifying, his writing sends shivers up and down my spine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38327, 'shock, horror!', 'an expression used when you are pretending to feel very shocked by a piece of news:', 'Shock, horror! Carl James was seen talking to a woman and it wasn''t his wife.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38328, 'shoot a glance at someone', 'to look at someone quickly:', 'She shot him a glance as he entered the room.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38329, 'shoot for something', 'to try to do something:', 'It''s worth taking chances when you''re shooting for a chance of fame and wealth.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38330, 'shoot for the moon', 'to ask for the best or the most you could hope for:', 'You might as well shoot for the moon and ask for a promotion as well as a raise.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38331, 'shoot from the hip', 'to speak in a very direct and honest way:', 'Jeff is a straight talker who always shoots from the hip.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38332, 'shoot from the hip', 'to react quickly, without thinking carefully about something:', 'We''re not going to shoot from the hip - we''re going to think things through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38333, 'shoot it out', 'If opposing groups or people armed with guns shoot it out, they shoot at each other until one of the groups or people is dead or defeated.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38334, 'shoot questions at someone', 'to ask someone a lot of questions very quickly, one after the other:', 'He shot questions at me so quickly that I didn''t even have time to answer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38335, 'shoot something down', 'to destroy an aircraft or make an aircraft, bird, etc. fall to the ground by shooting at it:', 'He was killed during the war when his plane was shot down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38336, 'shoot someone down', 'to shoot and usually kill someone, showing no sympathy:', 'I saw Leonforte shoot him down like a dog in the street.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38337, 'shoot something off', 'to write and send a message quickly:', 'She immediately shot off an email in reply.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38338, 'shoot something/someone down (in flames)', 'to refuse to accept someone''''s suggestion or idea and not consider it at all', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38339, 'shoot the breeze', 'to spend time talking about things that are not important:', 'We sat out on the porch, just shooting the breeze.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38340, 'shoot the works', 'to use all your money or make the greatest effort you can:', 'I emptied my bank account and shot the works on a trip to Mauritius.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38341, 'shoot through', 'to leave a place very quickly, especially in order to avoid having to do something', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38342, 'shoot up', 'to grow in size, or increase in number or level, very quickly:', 'David has really shot up since I saw him last.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38343, 'shoot up', 'to put illegal drugs into your blood using a special needle:', 'She saw a girl shooting up in the toilets.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38344, 'shoot something up', 'to fire guns in a place, causing a lot of damage', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38345, 'shoot your mouth off', 'to talk too much in a loud and uncontrolled way:', 'It''s just like Richard to go shooting his mouth off about other people''s business.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38346, 'shoot yourself in the foot', 'to do something without intending to which spoils a situation for yourself', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38347, 'shop around', 'to compare the price and quality of the same or a similar object in different shops before you decide which one to buy:', 'When you''re buying a flight, you should always shop around for the best deal.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38348, 'shore something up', 'to stop a wall or a building from falling down by supporting it with building materials such as wood or metal:', 'Boundary walls have had to be shored up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38349, 'shore something up', 'to support or improve an organization, agreement, or system that is not working effectively or that is likely to fail:', 'The new public relations manager has the difficult task of shoring up the company''s troubled image.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38350, 'short and sweet', 'surprisingly short in a way that is pleasing:', 'This morning''s meeting was short and sweet.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38351, 'short for something', 'as a less long form of a word or name:', 'Their baby’s name is Libby, short for Elizabeth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38352, 'short of something', 'not having enough of something:', 'I’m a little short of cash right now, so I can’t lend you anything.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38353, 'short of something', 'Short of something also means not including something:', 'There must be some punishment you can give him short of expelling him from school.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38354, 'short sharp shock', '(describing or relating to) punishment that is quick and effective:', 'He''s in favour of the short sharp shock treatment for young offenders.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38355, 'shorthand for something', 'a short, simple phrase that is used instead of a longer and more complicated phrase', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38356, 'shoulder to shoulder', 'If people are shoulder to shoulder, they are close together and next to each other:', 'The refugees were packed shoulder to shoulder on the boat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38357, 'shout on someone', 'to get someone''''s attention by shouting, especially when you want them to come to you or to do something:', 'Dinner''s ready - will you go and shout on her?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38358, 'shout someone down', 'to prevent someone who is speaking at a meeting from being heard, by shouting:', 'She was shouted down when she tried to speak on the issue of abortion.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38359, 'shout/proclaim something from the rooftops', 'to say something publicly:', 'I''m so in love I want to shout your name from the rooftops.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38360, 'shove it', 'a rude expression showing that you are angry about something that you have been offered or asked to do:', 'If they want me to do the same job for less money, they can shove it.', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38361, 'shove off!', 'used to tell someone angrily to go away:', 'Just shove off, will you?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38362, 'shove off', 'to leave land in a boat, usually by pushing against the land with your foot or an oar:', 'She jumped into the dinghy and shoved off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38363, 'shove someone around', 'to push someone forcefully, in an unpleasant and threatening way:', 'The older boys at school are always shoving him around.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38364, 'shove someone around', 'to tell someone what to do, in a rude or threatening way:', 'Don''t let them shove you around. You''ve got to stand up for your rights.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38365, 'shove something down someone’s throat', 'to force someone to accept something unpleasant:', 'I’m tired of Dave shoving his opinions down our throats.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38366, 'shove/stick something up your ass!', 'a rude phrase used to tell someone angrily that you do not want or need something that they are offering you or telling you to do:', 'If she asks me to work over the weekend, I''ll tell her to shove it up her ass!', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38367, 'shovel something into your mouth', 'to put large quantities of food into your mouth very quickly:', 'He was sitting in front of the TV shovelling down a pizza.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38368, 'show (someone) the way', 'to do something original that others are likely to copy:', 'Sweden has shown the way forward on energy efficiency.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38369, 'show off', 'to behave in a way that is intended to attract attention or admiration, and that other people often find annoying:', 'She only bought that sports car to show off and prove she could afford one.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38370, 'show something/someone off', 'to show something or someone you are proud of to other people, so that they will admire it, him, or her:', 'She likes to wear short skirts to show off her legs.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38371, 'show someone around (something)', 'to go with someone to all parts, or the main parts, of a place that they have not visited before, so that they can see what it is like or learn about it:', 'Let me know when you''re coming to Cambridge and I''ll show you around.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38372, 'show someone in a bad light', 'to make someone seem to be a bad person:', 'He was concerned that the article had shown him in a bad light.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38373, 'show someone in their true colors', 'to show what someone''''s real character is, especially when it is unpleasant', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38374, 'show someone in their true colours', 'to show what someone''''s real character is, especially when it is unpleasant', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38375, 'show someone out', 'to go to the door of the building with someone who does not live or work there, when they are leaving:', 'If you come this way, I''ll show you out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38376, 'show yourself out', 'to leave a building in which you do not live or work, without anyone going to the door with you:', 'Don''t get up - I''ll show myself out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38377, 'show someone over something', 'to lead someone around a place that they are visiting in a formal or official way, while telling them about it:', 'After lunch the VIPs will be shown over the new Arts Centre.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38378, 'show someone round (something)', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38379, 'show someone the door', 'to make it obvious that you do not want someone to be present and that they should leave:', 'When I told my bank that I wanted to borrow $100,000 they showed me the door.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38380, 'show up', 'to arrive somewhere in order to join a group of people, especially late or unexpectedly:', 'I invited him for eight o''clock, but he didn''t show up until 9.30.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38381, 'show someone up', 'to behave in a way that makes someone you are with feel ashamed or embarrassed:', 'I wish you wouldn''t show me up in front of my parents by getting so drunk.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38382, 'show your face', 'to appear somewhere when you are not expected to because you have done something bad:', 'How dare you show your face in here after saying all those awful things!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38383, 'show your hand', 'to allow people to know about intentions that you had previously kept secret:', 'Keep the names of the team secret - don''t show your hand until the day of the game.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38384, 'show/teach someone the ropes', 'to show someone how to do a job or activity:', 'Lynn spent an afternoon showing the new girl the ropes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38385, 'shower someone with something', 'to give someone a lot of presents or praise:', 'She only sees her niece occasionally, so she showers her with presents when she does.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38386, 'shrink from something', 'to avoid doing something that is unpleasant or difficult:', 'We must not shrink from our responsibilities.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38387, 'shrug something off', 'to treat something as if it is not important or not a problem:', 'The stock market shrugged off the economic gloom and rose by 1.5 percent.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38388, 'shrug something off', 'to get rid of something unpleasant that you do not want:', 'I hope I can shrug off this cold before I go on holiday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38389, 'shuck something off', 'to remove a piece of clothing, especially one that limits you:', 'The lifeguard shucked off his sweatshirt.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38390, 'shuck something off', 'to get rid of something that limits you or causes you problems:', 'They seem to be able to just shuck off guilt.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38391, 'shudder to a halt', 'If a system shudders to a halt, it suddenly stops working:', 'The economy has shuddered to a halt because of the civil war.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38392, 'shuffle off this mortal coil', 'to die:', 'My children can''t wait for me to shuffle off this mortal coil so they can get their hands on their inheritance.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38393, 'shuffle something off', 'to get rid of something unwanted, usually by giving it to someone else:', 'Not until this turbulent region can shuffle off the burdens of the past will it be able to settle peacefully into the community of nations.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38394, 'shut (someone) up', 'to stop talking or making a noise, or to make someone do this:', 'I wish you''d shut up for a moment and listen to what the rest of us have to say.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38395, 'shut (someone) up', 'to stop someone from talking about a particular subject or from complaining or asking for things:', 'The kids kept saying how hungry they were, so their father gave them some biscuits to shut them up.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38396, 'shut someone/something up', 'to keep a person or animal in a closed place:', 'She can''t spend her whole life shut up in her office.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38397, 'shut (something) up', 'to close a shop or other business for a period of time, usually when business is finished for the day:', 'By the time we got there, all the market traders were shutting up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38398, 'shut (something) down', 'If a business or a large piece of equipment shuts down or someone shuts it down, it stops operating:', 'The company plans to shut down four factories and cut 10,000 jobs.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38399, 'shut (something) off', 'If a machine or system shuts off, or if someone or something shuts it off, it stops operating:', 'The engine shuts off automatically when the desired speed is reached.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38400, 'shut something off', 'to stop the supply of something:', 'Did you remember to shut off the water and gas before you left the house?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38401, 'shut something off', 'to prevent something from being reached or seen:', 'The music room is shut off from the rest of the house by a soundproof wall.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38402, 'shut yourself off', 'to stop speaking to other people or stop being involved with them:', 'When her husband died she seemed to shut herself off from her friends and family.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38403, 'shut someone away', 'to put a person in a place that they are not allowed or able to leave:', 'He was ten years old when he was shut away for stealing an apple.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38404, 'shut something away', 'to put something in a place where other people cannot see it or get it:', 'The diamonds are shut away in a bank vault somewhere.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38405, 'shut yourself away', 'to go into a place that you are unwilling to leave and where you do not want to be interrupted by other people:', 'Andy shuts himself away in his studio for hours on end when he''s recording a song.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38406, 'shut someone/something in (something)', 'to prevent someone or something from leaving a place, usually by closing or fastening a door or gate:', 'The cat was shut in the garage all night.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38407, 'shut something in something', 'to catch part of your body or an object inside a device or container when it closes:', 'Steve was off work for a week after he shut his hand in the car door.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38408, 'shut someone/something out', 'to stop someone or something from entering or getting back inside a house or other building:', 'The wind blew the door closed behind me and now I''m shut out (of the house).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38409, 'shut someone/something out', 'to not include a person or organization in an activity:', 'Anna felt shut out of the conversation.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38410, 'shut something out', 'to stop yourself thinking about something that upsets you or feeling something that hurts you:', 'She finds it impossible to shut out the memory of the accident.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38411, 'shut something out', 'to prevent a sound or light from being heard or seen:', 'The double glazing shuts out most of the traffic noise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38412, 'shut someone out', 'to prevent your opponent in a sports competition from scoring any points:', 'She had shut out two of her first four opponents.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38413, 'shut the front door!', 'used to show surprise:', '"She kissed Curtis." "Shut the front door!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38414, 'shut up shop', 'to end an activity, usually a business activity, either temporarily or permanently:', 'Many companies are considering shutting up shop in this country and transferring production to low wage economies.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38415, 'shut your eyes to something', 'to ignore something:', 'Until now the prime minister has shut his eyes to the homelessness problem.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38416, 'shut your mouth', '(infml)to stop talking:', 'Just shut your mouth and stop whining!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38417, 'shut your mouth/face', 'a rude and angry way of telling someone to stop talking:', 'He told me to shut my mouth or there''d be trouble.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38418, 'shut/close the stable/barn door after the horse has bolted', 'to be so late in taking action to prevent something bad happening that the bad event has already happened', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38419, 'shy away from something', 'to avoid something that you dislike, fear, or do not feel confident about:', 'I''ve never shied away from hard work.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38420, 'shy of something', 'to lack something:', 'The bill was four votes shy of a majority.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38421, 'sic sth on sb', 'to order an animal, especially a dog, to attack someone:', 'The police will sic their dogs on you if they have to.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38422, 'sick (and tired) of someone/something', 'to have experienced too much of someone or something with the result that you are annoyed:', 'I’m sick of him whining about money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38423, 'sick as a dog', 'vomiting a lot:', 'I was sick as a dog after last night''s meal.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38424, 'sick as a parrot', 'very disappointed:', 'He was sick as a parrot when his team lost the match.', 'idiom', NULL, NULL, 'humorous, slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38425, 'sick at heart', 'very unhappy:', 'David was sick at heart about having to leave his family behind.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38426, 'sick something up', 'to vomit something:', 'The baby sicked up some milk on his aunt''s shoulder.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38427, 'sick to your stomach', 'likely to vomit:', 'I''m (feeling) sick to my stomach.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38428, 'sick to your stomach', 'feeling very upset, worried, or angry:', 'It makes me (feel) sick to my stomach when I remember my car accident.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38429, 'side by side', 'next to each other:', 'The children sat side by side .', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38430, 'side with someone', 'to support one person or group in an argument:', 'If ever there was any sort of argument, she''d always side with my father against me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38431, 'sight unseen', 'without seeing or examining something:', 'I never buy anything sight unseen.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38432, 'sign (something) off', 'to give a final message at the end of a letter or when communicating by radio, or at the end of a television or radio programme:', 'She signed off (her show) by wishing her listeners a Happy New Year.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38433, 'sign off', 'to stop doing your work or a similar activity for a period of time:', 'As it''s Friday, I think I''ll sign off early today.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38434, 'sign off', 'to report to a government employment office that you now have a job and do not need to receive benefit (= money paid by the government)', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38435, 'sign for something', 'to sign a form to show that you have received something:', 'I had to sign for the parcel when I went to get it at the post office.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38436, 'sign for/with someone', '(in sport) to sign a formal agreement saying that you will play for a particular team', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38437, 'sign in', 'to sign your name in a book in order to be allowed to enter a building such as an office or hotel:', 'Students must sign in when they visit other dorms.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38438, 'sign in', 'to enter your personal details into a website, etc. so that you can use it:', 'You will need your username and password to sign in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38439, 'sign someone in', 'to sign your name in a book next to the name of someone who is visiting you, in order for them to be allowed to enter a building such as an office or hotel:', 'He''s signed you in and is waiting for you inside.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38440, 'sign of the times', 'something that is typical of the (bad) way things are now:', 'These riots are a sign of the times.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38441, 'sign off (on something)', 'to approve something officially:', 'Both sides signed off on a legally binding agreement last month.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38442, 'sign on', 'to sign a form at a government office to say that you do not have a job and that you want to receive benefit (= money paid by the government)', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38443, 'sign on', 'to agree to become involved in an organized activity:', '[ + to infinitive ] mainly US I''ve signed on to help at the school fair.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38444, 'sign on', 'to sign a document saying that you will work for someone or do a particular job or activity:', 'She''s signed on with a temp agency.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38445, 'sign on the dotted line', 'to agree to do something, especially by signing an agreement:', 'If you want to join the gym, all you have to do is sign on the dotted line.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38446, 'sign out', 'to sign your name in a book when you leave a building such as an office or factory:', 'Don''t forget to sign out before you leave.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38447, 'sign out', 'to leave a website, etc. so that you have to enter your personal details again the next time you want to use it:', 'If you are using a public computer, sign out of email rather than just clicking out of the screen.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38448, 'sign someone out', 'to sign your name next to the name of someone who is leaving a building such as an office or factory:', 'Someone has to come down and sign you out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38449, 'sign something out', 'to record when you take something away, usually by signing your name in a book:', 'You have to sign books out when you borrow them from the library.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38450, 'sign something away', 'to give up your rights to something by signing a legal document:', 'Under the treaty, both sides will sign away a third of their nuclear weapons.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38451, 'sign something over', 'to give the legal rights to own or do something to someone else by formally signing a document:', 'Two years before her death she signed her property over to her children.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38452, 'sign something over (to someone)', 'to give up something by signing a formal document that gives it to someone else:', 'He signed the land over to the city before he died.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38453, 'sign up', 'to agree to become involved in an organized activity:', '[ + to infinitive ] I''ve signed up to make the sandwiches for the party.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38454, 'sign with someone', 'to start working for an organization or become a member of a sports team:', 'Some teams have let players sign with other teams because they could not afford to keep them.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38455, 'sign your own death warrant', 'to do something that is harmful to your own position:', 'She signed her own death warrant by refusing to do what the boss demanded.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38456, 'signed and sealed', 'finished and official because all the necessary documents have been signed', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38457, 'silence is golden', 'said to mean it is often better to say nothing', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38458, 'silly billy', 'a silly person, especially a child:', 'You''re being a silly billy, now stop it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38459, 'silt (something) up', 'to become blocked with silt, or to cause something to become blocked with silt:', 'The harbour silted up many years ago.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38460, 'simmer down', 'to become less angry or excited about something:', 'Come on kids! Simmer down and get on with your work!', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38461, 'since when', 'used angrily in speech to ask someone why they believe a situation to be different from how it really is:', 'Since when do you have the right to tell me what to do?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38462, 'sinews of war', 'the money needed for weapons and supplies during a war', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38463, 'sing along', 'to sing a piece of music while someone else is singing or playing it:', 'The radio station played a Billy Joel song, and I found myself singing along to it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38464, 'sing for your supper', 'to do something for someone else in order to receive something in return, especially food:', 'Dan''s upstairs fixing my computer - I''m making him sing for his supper.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38465, 'sing like a canary', 'to give someone, usually the authorities, a lot of secret information, especially about illegal activities:', 'He plays a mafia boss who''s about to sing like a canary and enter the witness relocation program.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38466, 'sing someone’s/something''''s praises', 'to praise someone or something with enthusiasm:', 'The review in the paper sings the movie''s praises.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38467, 'sing the praises of someone/something', 'to praise someone or something:', 'The newspapers have been singing the praises of Italy''s new star player.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38468, 'single someone/something out', 'to choose one person or thing from a group for special attention, especially criticism or praise:', 'It''s not fair the way my sister is always singled out for special treatment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38469, 'sink back', 'to move into a relaxed, comfortable position:', 'He sank back in his chair and closed his eyes.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38470, 'sink in', 'If an unpleasant or surprising fact or idea sinks in, you gradually start to believe it, understand it, or realize the effect it will have on you:', 'How many times do I have to tell you something before it sinks in?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38471, 'sink in/sink into something', 'If a liquid or soft substance sinks into something solid, it gradually passes into it through its surface:', 'You''d better wipe up that coffee you spilled on the carpet before it sinks in.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38472, 'sink into something', 'to slowly move your body into a sitting or lying position, in a relaxed or tired way:', 'I was so tired when I got home that all I wanted to do was sink into bed/an armchair/a hot bath.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38473, 'sink something into something', 'to spend a large amount of money on a business or other piece of work:', 'We sank all our money into my brother''s business.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38474, 'sink like a stone', 'to attract no support, attention, or interest:', 'My suggestion that we all play tennis sank like a stone.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38475, 'sink or swim', 'If you are left to sink or swim, you are given no help so that you succeed or fail completely by your own efforts:', 'My employer gave me no help when I started my new job - I was just left to sink or swim.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38476, 'sink to a whisper', 'to become very quiet:', 'The child''s voice sank to a whisper as she admitted that she had broken the window.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38477, 'sink to such a level/such depths', 'to do something so bad:', 'I can''t believe you would sink so low as to snitch on your best friends.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38478, 'sink without (a) trace', 'to be forgotten about completely, or to not attract any attention or interest:', 'Since his last book five years ago, he seems to have sunk without trace.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38479, 'sink your differences', 'to forget your disagreements:', 'Paul and Mark agreed to sink their differences and be friends.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38480, 'sink your teeth into something', 'to become completely involved in something:', 'It was a story you could really sink your teeth into.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38481, 'sinking fast', '(of a person''''s health) getting much worse quickly so that death is likely:', 'Mrs Jones is sinking fast, and the doctor doesn''t think she''ll live much longer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38482, 'sinking feeling', 'a feeling that something bad is going to happen:', 'I had a sinking feeling when I picked up the bill.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38483, 'sinking ship', 'a company or other organization that is failing:', 'He''d seen the accounts, realized he was on a sinking ship, and decided to get off.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38484, 'siphon something off', 'to dishonestly take money from an organization or other supply, and use it for a purpose for which it was not intended:', 'He lost his job when it was discovered that he had been siphoning off money from the company for his own use.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38485, 'sister from another mister', 'a female friend that you know very well and have a very good relationship with:', 'I call her “my sister from another mister” because I''ve never had a sister and Emma is like one to me.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38486, 'sister under the skin', 'a man who supports women''''s action to improve their rights:', 'John is a true sister under the skin.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38487, 'sit (around) on your backside', 'to do nothing:', 'I do all the work, while all you do is sit around on your backside all day.', 'idiom', NULL, NULL, 'slang, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38488, 'sit (someone) up', 'to move into a sitting position after you have been lying down, or to help someone else to do this:', 'Let me sit you up in the bed so you''ll be more comfortable.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38489, 'sit up', 'to sit with a straight back:', 'How many times do I have to tell you to sit up straight?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38490, 'sit up', 'to stay awake and not go to bed although it is late:', '[ + -ing verb ] The book was so interesting that I sat up all night reading it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38491, 'sit up', 'to show interest or surprise:', 'The news that he was getting married really made her sit up.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38492, 'sit around', 'to spend time sitting down and doing very little:', 'We sat around most of the evening, waiting for Jake and drinking beer.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38493, 'sit at the feet of someone', 'to be a very admiring student of someone important', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38494, 'sit back', 'to sit comfortably with your back against the back of a chair', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38495, 'sit back', 'to wait for something to happen without making any effort to do anything yourself:', 'You can''t just sit back and wait for job offers to come to you.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38496, 'sit by', 'to fail to take action to stop something wrong from happening:', 'I can''t just sit by and watch you waste all our money.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38497, 'sit down', 'to move your body so that the lower part of it is resting on a seat or on the ground:', 'I sat down on the sofa next to Barbara.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38498, 'sit down and do something', 'to spend time discussing a problem in order to solve it or make a decision:', 'I think we should sit down and talk about this.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38499, 'sit in', 'to go as a group into a public building and refuse to leave or to allow normal activities to continue there until a situation that you are complaining about is changed', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38500, 'sit in', 'to be present in a meeting or class, watching it but not taking part in it:', 'There will be a school inspector sitting in on your class this morning.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38501, 'sit in for someone', 'to take the place of someone who would normally do a particular job or go to a particular meeting:', 'Mr Baker is ill today, so Miss Dixon is sitting in for him (as your teacher).', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38502, 'sit in judgment on/over someone', 'to make a judgment on someone especially when you have no right to do so:', 'I don''t know why he thinks he can sit in judgment over us like that.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38503, 'sit on someone''''s stomach', 'Food that sits on your stomach makes you feel uncomfortably full.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38504, 'sit on something', 'to delay taking action about something:', 'The company has been sitting on my letter for weeks without dealing with my complaint.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38505, 'sit on something', 'to prevent people from knowing a piece of information:', 'The city council will presumably sit on the report until after the election.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38506, 'sit on someone', 'to force someone to be silent or not to do something:', 'The boss is going to sit on him to make sure he says nothing.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38507, 'sit on the fence', 'to delay making a decision:', 'You can''t sit on the fence any longer - you have to decide whose side you''re on.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
