INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38517, 'sit tight', 'to refuse to change your mind:', 'My parents tried to persuade me not to go alone, but I sat tight.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38518, 'sit under someone', 'to receive teaching from someone:', 'He sat under the most influential teacher in his field.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38519, 'sit up and take notice', 'to show interest or surprise:', 'She sat up and took notice when she heard he was getting married.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38520, 'sit with someone', 'to be considered by someone:', 'When someone calls you "a woman of letters," how does that sit with you?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38521, 'sitting pretty', 'in a good situation:', 'Our apartment isn’t expensive, so we’re sitting pretty.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38522, 'six of one and half a dozen of the other', 'said when you think that neither of two choices is better than the other:', '"Shall we give her chocolates or flowers?" "I don''t know, it''s six of one and half a dozen of the other."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38523, 'six of the best', 'a beating, usually of six hits with a stick', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38524, 'size something/someone up', 'to examine something or someone carefully and decide what you think about it, him, or her:', 'Voters are still sizing up the candidates.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38525, 'skate over/around something', 'to avoid dealing completely with something or to fail to pay enough attention to it:', 'Providing homeless people with somewhere to stay when the weather is cold only skates around the problem, it doesn''t solve it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
