INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38534, 'skin to skin', 'with people''''s bodies or parts of bodies touching directly, without clothing between them:', 'Healthy full-term babies carried skin to skin by their moms reap the same benefits as premature babies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38535, 'skip out on someone/something', 'to avoid doing something that you should do; to leave someone when they need your help:', 'He explained why he skipped out on a live radio appearance.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38536, 'skip over something', 'to avoid reading or looking at something:', 'I usually skip over the boring stuff.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38537, 'skive off sth', 'to not go to work, school, etc. when you should:', 'skive off work/school It''s easy to exaggerate an illness in order to skive off work.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38538, 'slack off', 'to work less hard or to be less than is usual or necessary:', 'Workers tend to slack off on Mondays and Fridays.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38539, 'slag someone off', 'to criticize someone:', 'I hate the way Dan is always slagging people off behind their backs.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38540, 'slap and tickle', 'sexual activity, especially when it involves playing or joking:', 'I think there''s a bit of slap and tickle going on in the back of that car over there.', 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38541, 'slap someone around', 'to hit someone repeatedly or often:', 'Her husband has been slapping her around, but she''s afraid to go to the police.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38542, 'slap someone down', 'to stop someone from talking or making suggestions, often in an unpleasant way:', 'I tried to suggest ways in which the plans could be improved, but he slapped me down.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38543, 'slap someone/something down', 'to criticize someone or something severely, usually in public:', 'This claim was slapped down by the chairman.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38544, 'slap something on', 'to put or spread a substance over a surface very quickly or roughly:', 'We want to sell our house, so we''ve slapped some paint on the outside to make it look better.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38545, 'slap something on/onto (something/someone)', 'to force a rule, tax, punishment, etc. to be obeyed or received:', 'The government has slapped more tax on cigarettes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38546, 'sleek back/down', 'to make something such as hair smooth, shiny, and flat:', 'Before going to the party, he sleeked back his hair with hair gel.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38547, 'sleep around', 'to have sex with a lot of different people without having a close or long relationship with any of them', NULL, 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38548, 'sleep in', 'to sleep until later in the morning than you usually do:', 'I usually sleep in on Saturdays.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38549, 'sleep it off', 'to stop the bad effects of having too much of something by sleeping for as long as it takes to end those effects', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38550, 'sleep like a log', 'infml to sleep very well, without being woken by any noises:', 'I slept like a log – I didn''t even hear the thunderstorm.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38551, 'sleep on it', 'to wait before making a decision:', 'Don’t give me an answer now – sleep on it and tell me whenever you’re ready.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38552, 'sleep over', 'to sleep in someone else''''s home for a night:', 'My niece is sleeping over on Friday night.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38553, 'sleep something off', 'If you sleep off something, especially a hangover, you go to sleep so that you will feel better when you wake up.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38554, 'sleep through something', 'If you sleep through a lot of noise or an activity, it does not wake you or keep you awake:', 'I never heard the storm last night - I must have slept through it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38555, 'sleep together', 'If two people sleep together, they have sex:', 'I don''t think they sleep together any more.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38556, 'sleep with someone', 'to have sex with someone:', 'He found out that his wife had been sleeping with his best friend.', 'phrasal verb', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38557, 'slice of the cake', 'If you want a slice of the cake, you want a share of any money that is being made from an activity.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38558, 'slice something off', 'to remove an amount of something by cutting it:', 'She sliced off a piece of sausage.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38559, 'slim down', 'to become thinner:', 'He''s really slimmed down over the last few months.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38560, 'slim something down', 'to reduce the size of something:', 'It is not our intention to slim down the workforce.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38561, 'sling someone out', 'to make someone leave a place because they have behaved badly:', 'She was slung out of college because she never did any work.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38562, 'sling something out', 'to get rid of something unwanted:', 'What about these old magazines? Shall I just sling them out?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38563, 'sling your hook', 'to leave:', 'She told him to sling his hook.', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38564, 'slip away', 'to leave secretly:', 'He slipped away while we were all sleeping.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38565, 'slip away', 'If a period of time slips away, it passes quickly:', 'Time was slipping away and she had to make a decision soon.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38566, 'slip away', 'If someone''''s power or the possibility of someone winning or achieving something slips away, it disappears:', 'Political power was really in their hands and they let it slip away.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38567, 'slip into something', 'to quickly put on a piece of clothing:', 'If you could wait two minutes, I''m just going to slip into a nicer dress.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38568, 'slip of the tongue', 'something that you say by accident when you intended to say something else:', 'I called her new boyfriend by her previous boyfriend''s name - it was just a slip of the tongue.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38569, 'slip off something', 'to remove clothing quickly and easily:', 'She slipped off her gloves.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38570, 'slip out', 'If a remark slips out, you say it without intending to.', NULL, 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38571, 'slip out of something', 'to quickly take off a piece of clothing:', 'Slip your shirt off and I''ll listen to your heart.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38572, 'slip someone''''s memory/mind', 'to be forgotten:', 'I forgot I''d arranged to meet Richard last night - it completely slipped my mind.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38573, 'slip through', 'to fail to be noticed, resulting in problems:', 'It is too easy for problems to slip through because there is no clear regulator at the top.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38574, 'slip through someone''''s fingers', 'If you allow an opportunity or a person to slip through your fingers, you lose it, him, or her through not taking care or making an effort:', 'You shouldn''t let a job/man like that slip through your fingers!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38575, 'slip through the cracks', 'to escape a punishment or be missed by a system that should deal with or protect you:', 'Once again terrorists have slipped through the police net.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38576, 'slip through the net', 'to escape a punishment or be missed by a system that should deal with or protect you:', 'Once again terrorists have slipped through the police net.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38577, 'slip up', 'to make a mistake:', 'These figures don''t make sense - have we slipped up somewhere?', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38578, 'slob around (something)', 'to behave in a very lazy way, doing very little:', 'He won''t get a job and just slobs around the house all day.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38579, 'slobber over someone', 'to show how much you admire and like someone, in a way that shows little control:', 'Ted was slobbering over the pretty new assistant in marketing.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38580, 'slop around (something)', 'to relax and do very little:', 'Jeans are all right just for slopping around the house, but I don''t wear them for work.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38581, 'slop out', 'When prisoners slop out, they empty the containers they use as toilets during the night in the rooms where they sleep.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38582, 'slope off', 'to leave somewhere quietly so that you are not noticed, usually to avoid work:', 'I saw you sloping off just after lunch yesterday!', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38583, 'slot someone/something in', 'to find time to see someone or do something between various other arrangements that have already been made:', 'Doctor Meredith is busy this morning, but she might be able to slot you in around one o''clock.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38584, 'slough something off', 'to get rid of something or someone unwanted:', 'He seemed to want to slough off all his old acquaintances.', 'phrasal verb', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38585, 'slough something off', 'When snakes and other reptiles slough off their skin, they get rid of an old, dead layer of skin.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38586, 'slow (someone/something) down/up', 'to become slower, or to make someone or something become slower:', 'Slow down, you two, you''re walking too fast!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38587, 'slow down', 'to be less active and relax more:', 'The doctor has told him to slow down or he''ll have a heart attack.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38588, 'slug it out', 'If two people slug it out, they fight or argue violently until one of them wins.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38589, 'sluice something down/out', 'to wash something with a large amount of running water:', 'We had to sluice out the garage to get rid of the smell of petrol.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38590, 'smack of something', 'If something smacks of an unpleasant quality, it seems to have that quality:', 'The whole situation smacks of mismanagement and incompetence.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38591, 'smack your lips', 'to close and open your mouth loudly to express a strong wish to eat something you like a lot:', '"I love chocolate cake," said Susannah, smacking her lips.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38592, 'small wonder', 'used to mean that something is not surprising:', 'After five years with the company she hadn''t been promoted - small wonder that she decided to quit her job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38593, 'smarten (someone/something) up', 'to (cause to) become more clean, tidy, and stylish:', 'She''s really smartened herself up since she finished college.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38594, 'smarten up your act', 'to make more effort:', 'Why are you always so late? You''ll have to smarten up your act if you want to keep your job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38595, 'smash it', 'to succeed or do something extremely well:', 'I''m so proud of my team - they totally smashed it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38596, 'smash something up', 'to damage something in a violent way:', 'In the 60s he was famous for taking drugs and smashing up hotel rooms.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38597, 'smell a rat', 'to recognize that something is not as it appears to be or that something dishonest is happening:', 'He''s been working late with her every night this week - I smell a rat!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38598, 'smell blood', 'to recognize an opportunity to take advantage of someone who is in a difficult situation:', 'When she smells blood, you don''t get a second chance.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38599, 'smell fishy', 'If a situation or an explanation smells fishy, it causes you to think that someone is being dishonest.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38600, 'smell somewhere out', 'to fill a place with a smell, in an unpleasant way:', 'That aftershave of yours is smelling out the whole house.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38601, 'smell something/someone out', 'to discover where something or someone is by smelling:', 'At customs, dogs are used to smell out drugs in passengers'' luggage.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38602, 'smell somewhere up', 'to fill a place with a smell, in an unpleasant way:', 'That aftershave of yours is smelling up the whole house.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38603, 'smile on something/someone', 'to feel positive about something or someone, or to treat it, him, or her in a very positive way:', 'The government began to smile on small businesses when it realized that they were the key to economic growth.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38604, 'smoke someone/something out', 'If you smoke out an animal or person that is hiding, you force them to leave the place where they are by filling it with smoke:', 'figurative There will be a tougher approach to smoking out (= finding) tax dodgers.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38605, 'smooth down something', 'to make something flat:', 'He straightened his tie nervously and smoothed down his hair.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38606, 'smooth something away', 'to remove the difficulties from something:', 'My mother was always there to smooth away my fears.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38607, 'smooth something out', 'to reduce the difficulties or changes in a process or situation:', 'By investing small amounts regularly, you can smooth out the effects of sudden rises and falls in the stock market.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38608, 'smooth something over', 'to make problems, difficulties, or disagreements less serious or easier to solve, usually by talking to the people involved:', 'Would you like me to try to smooth things over between you and your parents?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38609, 'smother something in/with something', 'to cover something completely with a substance or objects:', 'She took a slice of chocolate cake and smothered it in cream.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38610, 'snake its way', 'Something that snakes its way moves or is arranged in a twisting way:', 'A long queue had formed, snaking its way downstairs and out into the street.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38611, 'snap at someone''''s heels', 'If an animal is snapping at your heels, it is running behind you and trying to bite you.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38612, 'snap at someone''''s heels', 'to compete strongly with someone and have a chance of soon defeating or replacing them:', 'With so many younger women snapping at her heels, this year may be her last chance to win the championship.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38613, 'snap back', 'to quickly return to a previous condition:', 'snap back from sth The market snapped back last week from its free-fall.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38614, 'snap out of it', 'to stop experiencing something unpleasant or stop behaving in a negative way:', 'I was depressed, and I couldn''t snap out of it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38615, 'snap out of something', 'to force yourself to stop feeling sad and upset:', 'He just can''t snap out of the depression he''s had since his wife died.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38616, 'snap someone''''s head off', 'to answer someone in an unreasonably angry way:', 'There''s no point trying to discuss anything with him if all he''s going to do is snap your head off.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38617, 'snap something up', 'to buy or get something quickly and enthusiastically because it is cheap or exactly what you want:', 'The tickets for the concert were snapped up within three hours of going on sale.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38618, 'snap someone up', 'to immediately offer someone a job or position because you want them very much:', 'She was snapped up by a large law firm.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38619, 'snap to it', 'used to tell someone to do something more quickly:', 'We''re leaving in five minutes so you''d better snap to it and finish your breakfast.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38620, 'snap your fingers', 'to make a noise by pushing your second finger hard against your thumb and then releasing it suddenly so that it hits the base of your thumb:', 'He was snapping his fingers in time with the music.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38621, 'snatch at something', 'to try to take hold of something:', 'A man snatched at my bag, but he didn''t get it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38622, 'snatch at something', 'to try to use an opportunity quickly before it disappears:', 'I was desperate to find a way out of teaching so when this job came along I snatched at it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38623, 'snatch victory (from the jaws of defeat)', 'to win at the last moment possible, when it had previously seemed certain that you were going to lose', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38624, 'sneak up (on someone)', 'to approach someone quietly and surprise that person:', 'Overton sneaked up behind Brown and knocked the ball out of bounds.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38625, 'sneak up (on someone)', 'If an event or day sneaks up on you, it arrives before you are ready for it.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38626, 'sniff at something', 'to show disapproval or a low opinion of something:', 'Art experts sniffed at his work.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38627, 'sniff at something', 'to show that you are interested in something:', 'A few computer firms are sniffing at the project already.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38628, 'sniff something/someone out', 'to discover where something or someone is by smelling:', 'At customs, dogs are used to sniff out drugs in passengers'' luggage.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38629, 'sniff something out', 'to search for and discover something:', 'Her job is to go round the big fashion shows sniffing out talent for a modelling agency.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38630, 'snowed under', 'having too much to do:', 'I am totally snowed under at school', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38631, 'snuff it', 'to die', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38632, 'snuff something out', 'to cause something to end suddenly:', 'The country has been able to celebrate the return of its independence so brutally snuffed out in 1940.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38633, 'snuff something out', 'to put out a flame, especially from a candle:', 'One by one she snuffed out the candles.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38634, 'snuff someone out', 'to kill someone', NULL, 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38635, 'so ... it''''s not true', 'used to emphasize an adjective:', 'Julie''s brother''s so handsome it''s not true.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38636, 'so be it', 'used to say that it is necessary to accept the situation as it exists:', 'If she wants to spend all her money on clothes, so be it!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38637, 'so far', 'at this particular time:', 'So far, only two Democrats have entered the race for governor.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38638, 'so far, so good', 'satisfactory up to this particular time:', '"How’s your new job?" "So far, so good."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38639, 'so help me', 'this is true:', 'So help me, they were having so much fun they didn’t hear me come in.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38640, 'so help me (God)', 'used to make a promise in a very formal and serious way:', 'Everything I have said is true, so help me God.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38641, 'so long', 'goodbye', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38642, 'so long as', 'only if:', 'I’ll lend you the money so long as you’ll pay me back.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38643, 'so much', 'an amount that you do not know or state exactly:', 'By the time you''ve paid so much for the ferry and so much for the train fare, it would be cheaper to go by plane.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38644, 'so much as', 'but rather:', 'I didn’t listen so much as survive the conversation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38645, 'so much for something', 'used to express disappointment at the fact that a situation is not as you thought it was:', 'The car won''t start. So much for our trip to the beach.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38646, 'so much so', 'to such a great degree:', 'It was a great project, so much so that it won first prize.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38647, 'so much the better', 'used to say that a particular action or situation would be even more successful:', 'If you can go there this afternoon, so much the better.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38648, 'so there', 'used for emphasis, or to show that something is being done against someone else''''s wishes:', 'Mine''s bigger than yours, so there!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38649, 'so to speak', 'used to explain that what you are saying is not to be understood exactly as stated:', 'In that relationship it''s very much Lorna who wears the trousers, so to speak (= Lorna makes all the important decisions).', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38650, 'so what?', 'used to mean "it''''s not important" and "I don''''t care":', 'So what if I''m 35 and I''m not married - I lead a perfectly fulfilling life!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38651, 'soak something up', 'If a dry material or substance soaks up a liquid, it absorbs the liquid through its surface:', 'I tried to soak up most of the spilled milk with a dishcloth.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38652, 'soak something up', 'to enjoy the effects or experience of something as much as possible:', 'I love to lie on the beach and soak up the sun.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38653, 'soak something up', 'to understand and remember information well:', 'Given the right environment, children are like sponges and will soak up information.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38654, 'soak something up', 'to use up all or most of a supply of something, especially a supply of money:', 'The repairs on our house soaked up all our savings.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38655, 'sob your heart out', 'to cry very much', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38656, 'sober (someone) up', 'to become less drunk, or to make someone become less drunk:', 'I went for a walk to try to sober up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38657, 'sock in something/somewhere', 'to stop all travel or movement of vehicles in an area because of fog:', 'The entire coast was socked in all week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38658, 'sock something away', 'to save money by putting it in a bank or by investing it (= giving it to companies hoping to get more back):', 'He''s socked away hundreds of dollars in a savings account.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38659, 'sock something/someone in (with sb)', 'to stop all travel or movement of vehicles in an area because of bad weather:', 'The entire coast was socked in all week with fog.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38660, 'sod off', 'to go away:', 'Oh sod off, you stupid git!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38661, 'soft Brexit', 'a Brexit in which the United Kingdom''''s relationship with the European Union is a close as possible to what it was before Brexit:', 'In a "soft Brexit", Britain would be out of the EU but would retain strong economic ties, make budgetary contributions, and allow free movement of people.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38662, 'soft in the head', 'crazy or stupid:', 'Is the boss going soft in the head?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38663, 'soften someone up', 'to do things that will please someone so that they will do what you want:', 'You''re trying to soften me up so I''ll drive you to Jodie''s house, aren''t you?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38664, 'soften the blow', 'to make a bad situation less serious:', 'He lost his job, but he has enough money in the bank to soften the blow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38665, 'soften the blow', 'to make a difficult experience less unpleasant:', 'I put my arm around her before I gave her the bad news to try to soften the blow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38666, 'soldier on', 'to continue doing something although it is difficult:', 'I admired the way she soldiered on when her business ran into trouble.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38667, 'some ... or other', 'used to refer to one of several possibilities when the exact one is not known or not stated:', 'They found the painting in some antique shop or other.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38668, 'somehow or other', 'in a way that you do not know or understand:', 'I''m afraid that somehow or other we spoiled the kids.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38669, 'someone can dish it out but he or she can’t take it', 'someone easily criticizes other people but does not like it when other people criticize him or her:', 'He’s mad at me for teasing him – he can dish it out, but he can’t take it!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38670, 'someone can''''t win', 'used to say that nothing someone does in a situation will succeed or please people:', 'Whatever I do seems to annoy her - I can''t win.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38671, 'someone could do something with one arm/hand tied behind his/her back', 'If someone could do something with one arm/hand tied behind their back, they can do it very easily:', 'Her part wasn''t very demanding - she could have played it with one hand tied behind her back.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38672, 'someone couldn''''t act, argue, fight, etc. their way out of a paper bag', 'said about someone you think has no energy or ability', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38673, 'someone deserves a medal', 'said when you admire someone for dealing with a difficult person or situation for a long time:', 'She deserves a medal for putting up with that husband of hers.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38674, 'someone had better do something', 'someone should do something:', 'You’d better get moving if you want to catch your train.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38675, 'someone has bought it', 'used to say that someone has been killed:', '"Marvin''s bought it!" screamed the sergeant.', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38676, 'someone is full of it', 'slangsomeone is wrong or not telling the truth:', 'He''s always saying he''ll buy me things, but he''s full of it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38677, 'someone is going places', 'someone will be successful:', 'Maria’s a talented writer – she’s definitely going places.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38678, 'someone is no fool', 'someone is not easily deceived:', 'The teacher won''t believe your little brother took your homework – he’s no fool.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38679, 'someone is no stranger to something', 'someone is familiar with something, esp. something difficult or unpleasant:', 'She’s no stranger to hard work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38680, 'someone may as well do something', 'there is no reason you should not do something:', 'I may as well go with you – I don''t have anything else to do.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38681, 'someone should be shot', 'said when you think that someone''''s actions are extremely unreasonable:', 'They should be shot for selling drinks at that price!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38682, 'someone was had', 'someone was tricked or made to look foolish:', 'If you paid more than $20 for that picture, you were had.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38683, 'someone would give anything for something', 'to want something very much:', 'I’d give anything to see the pyramids of Egypt.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38684, 'someone would give someone the shirt off his or her back', 'someone would be willing to do anything to help another person:', 'Charlie is the nicest guy – he’d give you the shirt off his back if you were in trouble.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38685, 'someone would not dream of doing something', 'someone would never do something, esp. because it would be wrong to do it:', 'When I was your age, my parents wouldn''t have dreamed of letting me stay out until 10:00 at night.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38686, 'someone wouldn’t be caught dead', 'someone dislikes something very much:', 'I wouldn''t be caught dead wearing a dress like that – it''s like something my grandmother would wear!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38687, 'someone''''s (own) flesh and blood', 'someone''''s relation:', 'I couldn''t send him away - he''s my own flesh and blood.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38688, 'your own flesh and blood', 'your family or relations:', 'It''s hard to believe that he could treat his own flesh and blood so badly.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38689, 'answer to someone', 'to take orders from, obey, and explain your actions to someone:', 'The great thing about working for yourself is that you don''t have to answer to anyone.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38690, 'someone''''s back is turned', 'someone is not facing you or looking at you', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38691, 'someone''''s bark is worse than his or her bite', 'although someone says things that sound frightening, the person''''s actions will not be as severe as the things that were said:', 'The boss seems mean, but his bark is worse than his bite.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38692, 'someone''''s bark is worse than his/her bite', 'If someone''''s bark is worse than their bite, they are not as unpleasant or frightening as they seem:', 'Don''t let her frighten you - her bark is worse than her bite.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38693, 'someone''''s biological clock is ticking', 'When a woman says her biological clock is ticking, she means that she is worried that she is getting too old to have a baby.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38694, 'someone''''s blood is up', 'If your blood is up, you feel very angry.', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38695, 'someone''''s declining years', 'the last years of someone''''s life:', 'He became very forgetful in his declining years.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38696, 'someone''''s eyes are bigger than their belly/stomach', 'something that you say when someone has taken more food than they can eat', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38697, 'someone''''s face doesn''''t fit', 'If someone''''s face doesn''''t fit, their appearance or personality is not suitable for a job or other activity.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38698, 'someone''''s face falls', 'If someone''''s face falls, they suddenly look very disappointed:', 'Her face fell when she heard he wasn''t coming.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38699, 'someone''''s face is a picture', 'If someone''''s face is a picture, they look very surprised or angry:', 'Her face was a picture when I told her the price.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38700, 'someone''''s field of vision', 'the whole area that someone can see', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38701, 'someone''''s hands are tied', 'If your hands are tied, you are not free to behave in the way that you would like:', 'I''d like to raise people''s salaries but my hands are tied.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38702, 'someone''''s heart is in his/her boots', 'If someone''''s heart is in their boots, they feel very sad, disappointed, worried, etc.:', 'Their hearts were in their boots when they realized that they would have to do the work all over again.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38703, 'someone''''s heart is in his/her mouth', 'If someone''''s heart is in their mouth, they are feeling extremely nervous:', 'My heart was in my mouth when I opened the letter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38704, 'someone''''s heart sinks', 'to feel disappointed or to lose hope:', 'My heart sank when I realized we couldn''t afford the new house.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38705, 'someone''''s heart''''s desire', 'something that you want very much', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38706, 'your heart''''s desire', 'the thing or person you most want', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38707, 'someone''''s heart/mind/pulse races', 'If your heart/mind/pulse races it works extremely fast because of excitement, drugs, illness, etc.:', 'She was hot and sweaty and had a racing heart.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38708, 'someone''''s idea of something', 'what you consider something to be:', 'Playing card games is not my idea of fun.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38709, 'someone''''s jaw drops (open)', 'If someone''''s jaw drops (open), they look very surprised:', 'My jaw dropped open when she told me how old she was.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38710, 'someone''''s mask slips', 'If someone''''s mask slips, they do something that suddenly shows their real character, when they have been pretending to be a different, usually nicer, type of person.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38711, 'someone''''s number is up', 'infmlsomeone is going to die:', 'When the plane started to shake, Charles thought his number was up.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38712, 'someone''''s path recrosses/paths recross', 'used to say that people meet again, for a second, third, etc. time, especially by chance:', 'She met many people travelling, and only occasionally paths recrossed.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38713, 'someone''''s pride and joy', 'a person or thing that gives someone great joy and satisfaction:', 'Those flowers are her pride and joy.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38714, 'someone''''s ruling passion', 'a person''''s most important interest:', 'His ruling passion is music.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38715, 'someone''''s state/frame of mind', 'the way someone feels about their life or situation at the moment:', 'He''s in a much more positive state/frame of mind these days.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38716, 'someone''''s true colors', 'the kind of person someone really is rather than what the person seems to be:', 'I thought he was a really sweet guy, but then he got mad and showed his true colors.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38717, 'someone''''s two cents', 'someone''''s opinion about something, esp. when it was not asked for or wanted:', 'If the changes are going to affect me, then I want to put my two cents in.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38718, 'someone''''s/something''''s claim to fame', 'a reason why someone or something is famous:', 'This little town''s only claim to fame is that the president was born here.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38719, 'someone''''s/something''''s days are numbered', 'If someone or something''''s days are numbered, they will not exist for much longer:', 'The latest opinion polls suggest that his days as leader are numbered.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38720, 'someone/something does things to you', 'Something or someone that does things to you has a strong, usually enjoyable, effect on you:', 'That music really does things to me.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38721, 'someone/something is out of someone''''s league', 'someone or something is too good or expensive for someone to have:', 'She was the most beautiful girl in school, and I knew she was out of my league.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38722, 'someone/something rocks', 'used to show that you like or approve of someone or something a lot:', '"Do you like him?" "Yeah, he rocks!"', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38723, 'someone/something won''''t bite', 'used to say that someone does not need to be frightened of a particular person or thing:', 'Just go and ask her - she won''t bite.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38724, 'someone’s jaw drops', 'someone is very surprised:', 'When I saw him make that amazing shot, my jaw dropped.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38725, 'something a little stronger', 'a drink containing alcohol:', 'We have fruit juice but maybe you''d like something a little stronger?', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38726, 'something comes to your attention', 'fml you see or learn about something:', 'The matter first came to my attention when I was working at the college.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38727, 'something else', 'unusual, especially extremely good or extremely bad:', 'This game is really something else!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38728, 'something fierce', 'very much:', 'I need a cold drink something fierce.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38729, 'something for nothing', 'If you get something for nothing, you get something you want, such as money, without having to work or make any effort.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38730, 'something goes for someone/something else', 'something is also true for someone or something else:', 'What Mary just said goes for me too (= I agree with what she said).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38731, 'something goes without saying', 'something is obviously true:', 'If you got an "A" in the class, it goes without saying that you did well on the final exam.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38732, 'something gone mad', 'a particular type of thing that has gone out of control:', 'He described the new regulations as bureaucracy gone mad.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38733, 'something hangs in the balance', 'the result of a situation has not yet been decided yet:', 'The game hung in the balance until the last seconds.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38734, 'something hangs over your head', 'something makes you unable to relax or enjoy yourself:', 'I’ve got those darn credit card bills hanging over my head.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38735, 'something hits the spot', 'infml this is exactly what I needed or wanted:', 'That ice-cream sandwich really hit the spot!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38736, 'something is (just) a matter of doing something', 'solving a problem or performing a job has a simple solution:', 'Cooking lasagna isn’t difficult – it’s just a matter of following a recipe.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38737, 'something is anyone''''s guess', 'it is not possible for anyone to really know something:', 'He has a plan, but whether it will work or not is anyone’s guess.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38738, 'something is calling you', 'If something is calling you, you have a strong feeling that you must do it, have it, go there, etc.:', 'That last piece of chocolate cake is calling me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38739, 'something is like looking for a needle in a haystack', 'something is extremely difficult to find:', 'With 500 channels on TV, finding quality children''s shows is like looking for a needle in a haystack.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38740, 'something is no joke', 'something is a difficult or serious matter:', 'It’s no joke when a virus gets into your computer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38741, 'something is no object', 'something is not a difficulty that will prevent something from happening:', 'When he really wanted something, money was no object.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38742, 'something knows no bounds', 'If someone has a quality that knows no bounds, it is extreme:', 'Her generosity knows no bounds.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38743, 'something like', 'similar to:', 'He cursed himself for not having foreseen that something like this might happen.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38744, 'something like 96 percent, half, etc.', 'approximately, when talking about an amount or number:', 'Something like 60 percent of all married men will have an affair at some point in their marriage.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38745, 'something or other', 'something whose exact nature you do not know or have forgotten:', 'He''s a professor of something or other, and now he''s living in China.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38746, 'something rears its (ugly) head', 'something unpleasant appears:', 'Racism once again reared its ugly head in our town.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38747, 'something remains to be seen', 'something is still unknown or unclear:', 'Whether the Republican candidate can still win the election remains to be seen.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38748, 'something rings a bell', 'something, esp. a name, is familiar to you:', 'His name rang a bell, but I don’t know where I met him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38749, 'something runs in someone’s family', 'a skill or quality is present in many of your relatives:', 'I guess a love of music runs in the family.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38750, 'something slips through your fingers', 'an opportunity to achieve or have something is wasted:', 'This is the best thing that''s happened to my career - I can''t let it slip through my fingers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38751, 'someone slips through your fingers', 'someone escapes from you:', 'The police let the prisoners slip through their fingers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38752, 'something slips your mind', 'to forget something:', 'I was supposed to go to basketball practice, but it completely slipped my mind.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38753, 'something sticks in your mind', 'you remember something:', 'Her angry remarks stuck in my mind for a long time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38754, 'something takes the cake', 'infml something is the most extreme example:', 'I’ve had some pretty bad injuries, but this one takes the cake.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38755, 'something/nothing to shout about', 'something that makes/does not make you feel excited or pleased:', 'At last, a 5–0 victory gives the team''s fans something to shout about.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38756, 'somewhere along the line', 'at some moment during a relationship or process:', 'I don''t know what went wrong with our relationship, but somewhere along the line we just stopped loving each other.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38757, 'somewhere between', 'with the qualities of each of two things:', 'He made a sound somewhere between a gurgle and a cough.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38758, 'song and dance', 'a long and complicated statement or story, sometimes one that is not true:', 'She gave me some song and dance about how busy she is.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38759, 'sooner or later', 'used to say that you do not know exactly when something will happen, but you are certain that it will happen:', 'Sooner or later she''s going to realize what a mistake she''s made.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38760, 'sop something up', 'to absorb liquid into a piece of something solid:', 'It''s surprising how much milk the bread sops up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38761, 'sorry for your loss', 'used when you are telling someone that you feel sympathy for them because someone close to them has recently died:', 'I''m so sorry for your loss; you have my deepest sympathy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38762, 'sort something out', 'to separate one type of things from a group of things:', 'Sort out any clothes you want to throw away and give them to me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38763, 'sort something/someone out', 'to deal successfully with a problem, a situation, or a person who is having difficulties:', 'We''ve sorted out the computer system''s initial problems.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38764, 'sort someone out', 'to punish or attack someone, usually to make the person understand that they have behaved badly:', 'Has he been bothering you again - do you want me to sort him out?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38765, 'sound off', 'to express your opinions forcefully, especially without being asked for them:', 'He''s always sounding off about how he thinks the country should be run.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38766, 'sound someone out', 'to discover informally what someone thinks or intends to do about a particular thing, so that you can be prepared or take suitable action:', 'Perhaps you could sound the chairwoman out before the meeting, to see which way she''s going to vote?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38767, 'soup something up', 'to make something more powerful or more attractive by making changes to it, especially when it is old:', 'New circuit boards can be used to soup up existing machines.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38768, 'sour grapes', 'If you describe someone''''s behaviour or opinion as sour grapes, you mean that that person is angry because they have not got or achieved something that they wanted:', 'I don''t think it''s such a great job - and that''s not just sour grapes because I didn''t get it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38769, 'south of the border', 'Mexico and the other countries south of the US border with Mexico', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38770, 'sow the seeds of something', 'to do something that will cause something to happen in the future:', 'He''s sowing the seeds of his own downfall.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38771, 'sow your wild oats', 'If a young man sows his wild oats, he has a period of his life when he does a lot of exciting things and has a lot of sexual relationships.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38772, 'spare no effort', 'to achieve something by working as hard as possible or spending as much money as is necessary:', 'She spared no expense in decorating her office.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38773, 'spare someone''''s blushes', 'to avoid making someone feel embarrassed', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38774, 'spare the rod and spoil the child', 'said to mean that if you do not punish a child when they do something wrong, they will not learn what is right', NULL, 'idiom', NULL, NULL, 'old-fashioned, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38775, 'sparks fly', 'If sparks fly between two or more people, they argue angrily:', 'When they get together in a meeting the sparks really fly.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38776, 'sparrow fart', 'very early in the morning:', 'We left at sparrow''s fart.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38777, 'speak for someone', 'to express the opinions or wishes of someone:', 'I can’t speak for the others.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38778, 'speak for yourself', 'something you say to someone to say that the opinion that they have just expressed is not the same as your opinion:', '"We had a really boring trip." "Speak for yourself! I had a wonderful time!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38779, 'speak in someone''''s favor', 'to state your support for someone', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38780, 'speak in someone''''s favour', 'to state your support for someone', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38781, 'speak out', 'to say in public what you think about something such as a law or an official plan or action:', 'He spoke out against the school’s admissions policy.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38782, 'speak out/up', 'to give your opinion about something in public, especially on a subject that you have strong feelings about:', 'If no one has the courage to speak out against the system, things will never improve.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38783, 'speak to something', 'to talk about something:', 'He could not speak to the details of the new plan.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38784, 'speak too soon', 'to say something that is quickly shown not to be true:', 'He won''t be home for hours yet ... Oh, I spoke too soon - here he is now!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38785, 'speak up', 'to speak in a louder voice so that people can hear you:', 'Could you speak up? We can''t hear at the back.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38786, 'speak up for someone/something', 'to support someone or something, especially by saying good things about him, her, or it:', 'She has often spoken up for the rights of working mothers.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38787, 'speak volumes', 'If something speaks volumes, it makes an opinion, characteristic, or situation very clear without the use of words:', 'She said very little but her face spoke volumes.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38788, 'speak when you''''re spoken to!', 'said to a child to tell the child not to speak if no one speaks to them first', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38789, 'speak your mind', 'to say what you think about something very directly:', 'He''s certainly not afraid to speak his mind.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38790, 'speak/talk of the devil', 'something you say when the person you were talking about appears unexpectedly:', 'Did you hear what happened to Anna yesterday - oh, speak of the devil, here she is.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38791, 'speak/talk out of turn', 'to say something that you should not have said:', 'I''m sorry if I spoke out of turn, but I thought you already knew.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38792, 'speak/talk the same language', 'to have similar ideas and similar ways of expressing them:', 'We come from similar backgrounds, so we speak the same language.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38793, 'speaking as someone', 'with the experience of being this type of person:', 'Speaking as a mother of four, I can tell you that children are exhausting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38794, 'speaking of someone/something', 'related to the subject being discussed:', 'Casey is at a birthday party – speaking of birthdays, Abe’s is Friday.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38795, 'speaks for itself', 'If something speaks for itself, it is clear and needs no further explanation:', 'The school''s excellent record speaks for itself.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38796, 'speed (something) up', 'to happen or move faster, or to make something happen or move faster:', 'This drug may have the effect of speeding up your heart rate.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38797, 'spell something out', 'to explain something in a very clear way with details:', 'The government has so far refused to spell out its plans/policies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38798, 'spell trouble', 'to suggest that there may be problems in the future:', 'The latest opinion polls spell trouble for the Republicans.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38799, 'spend a penny', 'polite phrase for to urinate:', 'If you''ll excuse me, I need to spend a penny.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38800, 'spend the night together', 'polite phrase for to have sex with someone:', 'Did you spend the night together?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38801, 'spew (something) up', 'to vomit:', 'I was spewing up all night after those mussels.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38802, 'spice something up', 'to add excitement or interest to a speech, story, or performance:', 'He''d spiced up his speech with a few rude jokes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38803, 'spiff someone/something up', 'to make someone or something look more stylish, or cleaner and tidier:', 'He''s really spiffed up his wardrobe since he started his new job.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38804, 'spike someone''''s guns', 'to spoil someone''''s plans:', 'We wanted to build an extra room onto the side of our house, but our neighbours spiked our guns.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38805, 'spill blood', 'to kill or hurt people', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38806, 'spill out', 'to flow or fall out of a container:', 'All the shopping had spilled out of my bag.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38807, 'spill out', 'If people spill out of a place, large numbers of them come out of it:', 'People were spilling out of the wine bar onto the street.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38808, 'spill (something) out', 'to talk about or express an emotion freely:', 'All his resentment spilled out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38809, 'spill over', 'If an activity or situation spills over, it begins to affect another situation or group of people, especially in an unpleasant or unwanted way:', 'I try not to let my work spill over into my life outside the office.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38810, 'spill over', 'to continue for a longer time than expected:', 'The talks between the two leaders look likely to spill over into the weekend.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38811, 'spill the beans', 'to tell people secret information:', 'So who spilled the beans about her affair with David?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38812, 'spill your guts', 'to tell someone all about yourself, especially your problems:', 'Why do people take part in these shows and spill their guts on camera in front of a studio audience?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38813, 'spin (someone) around', 'to quickly turn your own or someone else''''s body to face the opposite direction:', 'She spun around to see what had happened.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38814, 'spin a coin', 'to make a coin turn around and around on its edge so that someone can guess that side will land facing upwards:', 'Let''s spin a coin to decide who''ll have the first turn.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38815, 'spin out of control', 'If activities or events spin out of control, they change very quickly and in an uncontrolled way:', 'The country''s economy seemed to be spinning out of control.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38816, 'spin something off', 'to produce a useful and unexpected result in addition to the intended result:', 'The American space program has spun off new commercial technologies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38817, 'spin something off', 'to form a separate company from part of an existing company:', 'The company is trying to spin off part of its business.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38818, 'spin something out', 'to make something such as an activity or story last longer than usual or necessary, or as long as possible:', 'Can we spin our holiday out for a few more days?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38819, 'spin your wheels', 'to waste time doing things that achieve nothing:', 'If we''re just spinning our wheels, let us know and we''ll quit.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38820, 'spit (something) up', 'to bring food up from the stomach out of the mouth, or cough something up out of the mouth:', 'A lot of babies spit up after feeding.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38821, 'spit and polish', 'careful cleaning and shining:', 'The car needs some spit and polish.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38822, 'spit blood/venom', 'to speak in an angry way, or to show anger:', 'I thought he was going to spit blood when he saw what had happened.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38823, 'spit it out!', 'used to tell someone to start speaking or to speak more quickly, when they are unwilling to speak or are speaking slowly:', 'Come on, spit it out, who told you about this?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38824, 'spit something out', 'to say something quickly and angrily:', 'He spat out an insult and marched out of the room.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38825, 'splash out (something)', 'to spend a lot of money on buying things, especially things that are pleasant to have but that you do not need:', 'They splashed out £3,000 on a holiday.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38826, 'spliff up', 'to make and light a cannabis cigarette', NULL, 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38827, 'split hairs', 'to argue about small details of something', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38828, 'split the difference', 'to accept only part of what you originally wanted when making an agreement with someone, esp. an agreement involving money:', 'You want $50 for the bike and I say it’s worth $30 – let’s split the difference and I’ll pay you $40.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38829, 'split up', 'If two people split up, they end their relationship or marriage:', 'She split up with her boyfriend last week.', 'phrasal verb', 'B1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38830, 'split your sides', 'to laugh a lot at something:', 'We practically split our sides laughing/with laughter watching Paul trying to get the dog into the bicycle basket.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38831, 'spoil someone rotten', 'to do whatever someone wants you to do or to give someone anything they want:', 'The children are spoiled rotten by their grandparents.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38832, 'spoil someone''''s party', 'to cause trouble for someone at a moment when they are enjoying a success', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38833, 'spread like wildfire', 'If disease or news spreads like wildfire, it quickly affects or becomes known by more and more people:', 'Once one child in the school has the infection, it spreads like wildfire.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38834, 'spread out', 'If people spread out, they move from being close together in a group to being in different places across a larger area:', 'They spread out to search the whole area.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38835, 'spread something out (over something)', 'to cause something to happen over a period of time, usually in stages:', 'You can spread the payments out over six months if you want to.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38836, 'spread something over something', 'to arrange for something to happen in stages during a period of time:', 'The course is spread over two years.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38837, 'spread the word', 'to communicate a message to a lot of people:', 'We''ve arranged a meeting for next Thursday so if you see anyone do spread the word.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38838, 'spread your wings', 'to use your abilities for the first time in your life to do new and exciting things:', 'She''d been working for the same company for 15 years and it was time to leave and spread her wings.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38839, 'spread yourself too thin', 'to try to do too many things at the same time, so that you cannot give enough time or attention to any of them:', 'I realized I''d been spreading myself too thin so I resigned as secretary of the golf club.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38840, 'spring for something', 'to pay for or buy something, often for someone else:', 'They offered to spring for the tickets.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38841, 'spring from something', 'to come from or be a result of something:', 'His need to be liked obviously springs from a deep-rooted insecurity.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38842, 'spring something on someone', 'to suddenly tell or ask someone something when they do not expect it:', 'I hope he''s not going to spring any nasty surprises on us at the meeting this morning.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38843, 'spring to life', 'to suddenly become very active or busy:', 'After about eight o''clock the city springs to life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38844, 'spring to mind', 'to come quickly into your mind:', 'Say the word "Australia" and a vision of beaches and blue seas immediately springs to mind.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38845, 'spring up', 'to start to exist suddenly:', 'Thousands of new businesses have sprung up in the past couple of years.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38846, 'spruce someone/something up', 'to make someone or something cleaner and tidier or to improve his, her, or its appearance generally:', 'I thought I''d have a shave and generally spruce myself up for the interview.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38847, 'spur someone on', 'to encourage someone:', 'Ambition spurred him on.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38848, 'spy on someone/something', 'to watch someone or something secretly, often in order to discover information about him, her, or it:', 'He was spying on her through the keyhole.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38849, 'spy out the land', 'If you spy out the land, you try to get knowledge of something before you do something:', 'We drove around the area where our new house is to spy out the land.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38850, 'square (something) with something', 'to match or agree with something, or to think that one thing is acceptable together with another thing:', 'Her story doesn''t quite square with the evidence.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38851, 'square off', 'to prepare to fight, compete, or argue with someone:', 'The two giants in the fast-food industry are squaring off this month with the most aggressive advertising campaigns yet.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38852, 'square peg (in a round hole)', 'a person whose character makes them unsuitable for the job or other position they are in:', 'He never quite fitted in when he was working here - he was always a bit of a square peg.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38853, 'square something/someone away', 'to complete all the necessary arrangements for something or someone:', 'I’ve got my tickets and hotel squared away.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38854, 'square the accounts/books', 'to make certain that you have paid and received all the money that you owed or that others owed you', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38855, 'square the circle', 'If you try to square the circle, you try to do something that is very difficult or impossible.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38856, 'square up', 'to prepare to fight, compete, or argue with someone:', 'The players squared up to each other and started shouting.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38857, 'square up', 'to pay someone the money that you owe them:', 'If you pay for both tickets now, I''ll square up with you later.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38858, 'square up to someone/something', 'to deal with a problem or difficult person bravely and with determination:', 'I thought she squared up to the situation admirably.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38859, 'squeeze (someone/something) in/squeeze (someone/something) into something', 'to succeed in getting someone or something into a small space or object, often by pushing or forcing:', 'The car''s quite full, but we could manage to squeeze another couple of people in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38860, 'squeeze sb/sth out', 'to make it impossible for a person or company to continue to do business or be successful:', 'Some investors found themselves squeezed out because their bids were too low.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38861, 'squeeze someone dry', 'If you squeeze someone dry, you get as much from them as possible:', 'When they got divorced, his wife squeezed him dry and took everything.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38862, 'squeeze someone/something in', 'to manage to do something or see someone in a short period of time or when you are very busy:', 'While we''re in Australia, we''re hoping to squeeze in a trip to the Barrier Reef.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38863, 'squeeze something out of someone', 'to persuade or force someone to give you money or information:', 'During the negotiations, the union managed to squeeze several concessions from the management.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38864, 'squeeze sth out of/from sth/sb', 'to get as much as you can from something or someone, especially in a way that makes problems for them:', 'The Treasury is continuing its efforts to squeeze more income from the corporate sector.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38865, 'squirrel something away', 'to hide or store something, especially money, in order to use it in the future:', 'As soon as I get paid, I squirrel some money away so I won''t be tempted to spend it.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38866, 'stab someone in the back', 'to do something harmful to someone who trusted you:', 'He had been lied to and stabbed in the back by people that he thought were his friends.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38867, 'stack the cards', 'to arrange something in a dishonest way in order to achieve the result you want', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38868, 'stack the deck', 'to arrange something in a dishonest way in order to achieve the result you want', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38869, 'stack the deck (against someone/something)', 'to arrange something so that the results are unfair:', 'Critics say that having so many businessmen on the panel stacks the deck against the environment.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38870, 'stack up', 'to compare with another thing of a similar type:', 'The new model of this car just doesn''t stack up against previous models (= is not as good as previous models).', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38871, 'stack up', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38872, 'stake a claim', 'If you stake a claim to something, you say or show that you have a right to it and that it should belong to you:', 'He marked the spot on his map where he had seen the gold and returned later that month to stake his claim.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38873, 'stake a claim (to something)', 'to announce that something belongs to you:', 'Stacy staked her claim to to her uncle’s fortune.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38874, 'stake someone to something', 'to provide someone with a particular thing or with what is needed to get it:', 'The governor has promised to stake the city''s homeless to what they need for a fresh start.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38875, 'stake something on something', 'to risk harming or losing something important if an action, decision, or situation does not have the result you want or expect:', 'I think she''ll be head of this company in five year''s time - I''d stake my reputation on it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38876, 'stake something out', 'to watch a place continuously in order to catch criminals or to see a famous person:', 'The police staked out the hotel where the two terrorists were reported to be staying.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38877, 'stake something out', 'to establish or make clear your opinion or position on something:', 'Two of the president''s chief advisers have staked out opposite positions on this issue.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38878, 'stake somewhere/something out', 'to mark the limits of an area or a piece of land with wooden sticks in order to claim that you own it', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38879, 'stake somewhere/something out', 'to show clearly that you claim the right to own, control, or use a particular area, for example by putting personal things there:', 'Each gang in the city has staked out its territory and defends it from other gangs.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38880, 'stamp on something', 'to use force to stop or prevent something that you consider to be wrong or harmful:', 'Any opposition to the new government was immediately stamped on by the army.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38881, 'stamp something out', 'to get rid of something that is wrong or harmful:', 'The new legislation is intended to stamp out child prostitution.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38882, 'stamped on someone''''s memory', 'If a particular event, etc. is stamped on someone''''s memory, the person will always remember it:', 'The awful sound of the crash will be stamped on her memory forever.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38883, 'stand (out) in relief', 'to appear or show very clearly and obviously:', 'The mountain stood out in sharp relief against the evening sky.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38884, 'stand (up) and be counted', 'to make your opinions known even if doing so might cause you harm or difficulty:', 'Those who did have the courage to stand up and be counted were arrested and imprisoned.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38885, 'stand a chance', 'to have a chance of success:', 'He doesn’t stand much of a chance in the election.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38886, 'stand and deliver!', 'said in the past by highwaymen when they stopped a carriage (= a vehicle pulled by horses) on a road to demand objects of value from the travellers', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38887, 'stand around', 'to spend time standing somewhere and doing very little:', 'We stood around in the cold for about an hour, waiting for the demo to start.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38888, 'stand aside', 'to leave a job or position so that someone else can have it instead:', 'It''s time he stood aside and let a more qualified person do the job.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38889, 'stand aside', 'to step sideways to make a space for someone else:', 'Stand aside, please, so the doctor can get through.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38890, 'stand back', 'to move a short distance away from something or someone:', 'Please stand back - then all of you will be able to see what I''m doing.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38891, 'stand bail', 'to pay money temporarily to a court so that someone can be released from prison until the date of their trial:', 'She can''t be released from police custody until someone stands bail for her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38892, 'stand by someone', 'to continue to support or help someone who is in a difficult situation:', 'She has vowed to stand by her husband during his trial.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38893, 'stand by', 'to be waiting and ready to do something or to help:', 'Cabin crew, please stand by for take-off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38894, 'stand by', 'to allow something unpleasant to happen without doing anything to stop it:', 'We can''t stand by while millions of people starve.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38895, 'stand by something', 'to continue doing what you said you would when you made a decision, agreement, or promise:', 'Despite its financial problems, the company is standing by the no-redundancy agreement.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38896, 'stand by something', 'to continue to believe that something you have said before is still true:', 'I stand by the statement I made earlier - there is no reason for the minister to resign.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38897, 'stand clear', 'to move a short distance away from something so that you are safe:', '"Stand clear!" shouted the policewoman, "It might fall any minute."', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38898, 'stand down', 'to give up your official job or position:', 'He''s decided to stand down after 15 years as managing director.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38899, 'stand fast/firm', 'to be determined:', 'Stand firm on your decision and you''re more likely to get the result you want.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38900, 'stand for something', 'If you will not stand for something, you will not accept a situation or a particular type of behaviour:', 'I wouldn''t stand for that sort of behaviour from him, if I were you.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38901, 'stand for something', 'to support or represent a particular idea or set of ideas:', 'This party stands for low taxes and individual freedom.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38902, 'stand for something', 'If one or more letters stand for a word or name, they are the first letter or letters of that word or name and they represent it:', 'GMT stands for Greenwich Mean Time.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38903, 'stand guard', 'to guard someone or something:', 'Soldiers stood guard over the prisoner.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38904, 'stand in', 'to do the job that another person was going to do or usually does, or to take that person''''s place at an event, because they cannot be there:', 'Paula stood in for Jane, while Jane was on holiday.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38905, 'stand in the way of something/someone', 'to try to stop or prevent something or someone:', 'You know I won''t stand in your way if you want to apply for a job abroad.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38906, 'stand on ceremony', 'to behave in a formal way:', 'Please sit down and make yourself comfortable, we don''t stand on ceremony here.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38907, 'stand on your dignity', 'to demand to be shown the respect that you think you deserve:', 'The Director didn''t stand on her dignity; she helped clear up after the party.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38908, 'stand on your hands/head', 'to support yourself only on your hands, or only on your head and hands, with your feet up as high as possible', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38909, 'stand on your own (two) feet', 'to be able to provide all of the things you need for living without help from anyone else:', 'She''ll have to get a job and learn to stand on her own two feet sooner or later.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38910, 'stand or fall by something', 'to depend completely on something for success', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38911, 'stand out', 'to be very noticeable:', 'The black lettering really stands out on that orange background.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38912, 'stand out', 'to be much better than other similar things or people:', 'We had lots of good applicants for the job, but one stood out from the rest.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38913, 'stand out against something/someone', 'to publicly oppose something or someone:', 'More and more people are standing out against what is a very unpopular piece of legislation.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38914, 'stand over someone', 'to stand close to someone and watch what they are doing:', 'Don''t stand over me all the time - it makes me nervous.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38915, 'stand round', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38916, 'stand shoulder to shoulder with someone', 'to give someone or a group of people complete support during a difficult time', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38917, 'stand someone in good stead', 'If an experience stands a person in good stead, it is or will be of great use to them:', 'Getting some work experience now will stand you in good stead (for) when you apply for a permanent job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38918, 'stand something on its head', 'to cause something such as an established belief to be doubted, especially because of new information or discoveries:', 'New data has stood the traditional explanation of the island''s origin on its head.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38919, 'stand the test of time', 'If something stands the test of time, it is still popular, strong, etc. after a long time:', 'Which songs from the last year will stand the test of time?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38920, 'stand together', 'If a group of people stand together on a particular matter, they agree strongly about it and take action together about it.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38921, 'stand up', 'to be in an upright position on your feet; to get yourself into an upright position on your feet:', 'I''ve been standing up all day and I''m really tired.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38922, 'stand up', 'If an idea or some information stands up, it is proved to be true or correct:', 'Their evidence will never stand up in court.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38923, 'stand someone up', 'to intentionally fail to meet someone when you said you would, especially someone you were starting to have a romantic relationship with:', 'I don''t know if I''ve been stood up or if she''s just late - I''ll wait another half hour.', 'phrasal verb', 'B2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38924, 'stand up for something/someone', 'to defend or support a particular idea or a person who is being criticized or attacked:', 'It''s high time we all stood up for our rights around here.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38925, 'stand up to someone/something', 'to defend yourself against a powerful person or organization when they treat you unfairly:', 'He wasn''t afraid to stand up to bullies.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38926, 'stand up to something', 'to not be changed or damaged by something:', 'Will the lorries stand up to the journey over rough roads?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38927, 'stand your ground', 'to refuse to be pushed backwards, or to continue in your beliefs in an argument:', 'The battalion stood its ground in the face of repeated attacks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38928, 'stand/stick out a mile', 'to be very obvious or easy to see:', 'His lack of experience sticks out a mile.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38929, 'stand/stick out like a sore thumb', 'If someone or something stands/sticks out like a sore thumb, everyone notices them because they are very different from the people or things around them:', 'Everyone else was in jeans and T-shirts and I had my office clothes on - I stuck out like a sore thumb.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38930, 'stand/walk tall', 'to act in a proud and confident way:', 'As she walked up to the podium to speak, she reminded herself to stand tall.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38931, 'standing on your head', 'If you can do something standing on your head, you can do it very easily:', 'It''s the sort of program Andrew could write standing on his head.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38932, 'stare someone in the face', 'If something stares someone in the face, it is very easy to see or obvious:', 'The answer has been staring us in the face all along!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38933, 'stare someone in the face', 'to be certain or almost certain to happen:', 'A rise in interest rates is staring us in the face.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38934, 'stare sth in the face', 'to be close to having sth unpleasant happening to you:', 'At this point they were staring death in the face.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38935, 'start (something) off', 'to begin by doing something, or to make something begin by doing something:', 'She started off the meeting with the monthly sales report.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38936, 'start someone off', 'to help someone to start an activity, especially a piece of work:', 'I''ll start her off on some fairly basic stuff and see how she gets on.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38937, 'start someone off', 'to make someone start to laugh, cry, or talk about something that they talk about often:', 'I could see Emma trying not to laugh and of course that started me off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38938, 'start (something) up', 'If a business or other organization starts up, or if someone starts one up, it is created and starts to operate:', 'Many small businesses started up in the 1980s to cater to this growing market.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38939, 'start (something) up', 'If a vehicle or engine starts up, or someone starts it up, it starts to work:', 'The car wouldn''t start up this morning.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38940, 'start on at someone', 'to start complaining angrily to someone about something they have done:', 'She started on at him about the way he''s always looking at other women.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38941, 'start on something', 'to start to deal with something, or to start to use something:', 'I''m just about to start on the cleaning.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38942, 'start out', 'to begin your life, or the part of your life when you work, in a particular way:', 'My dad started out as a salesperson in a shop.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38943, 'start over', 'to begin to do something again, sometimes in a different way:', 'We decided to abandon the first draft of the report and start over.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38944, 'start something', 'infml to begin an argument or fight:', 'You could tell the guy wanted to start something, so we just walked away.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38945, 'start/set/get the ball rolling', 'to do something that starts an activity, or to start doing something in order to encourage other people to do the same:', 'I decided to set the ball rolling and got up to dance.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38946, 'starve someone/something of something', 'to not provide enough of something that is needed, or to prevent someone or something from getting enough of what is needed :', 'Schools have been starved of funds for years.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38947, 'stave something in', 'to push or hit something such as a door or other surface so that it breaks and falls towards the inside:', 'A couple of teenagers were trying to stave in our shed door.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38948, 'stave something/someone off', 'to stop something bad from happening, or to keep an unwanted situation or person away, usually temporarily:', 'We were hoping to stave off these difficult decisions until September.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38949, 'stay away from someone/something', 'to not go near or become involved with someone; to avoid something that will have a bad effect on you:', 'My parents told me to stay away from her.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38950, 'stay behind', 'to not leave a place when other people leave:', 'I stayed behind after class.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38951, 'stay in', 'to stay in your home:', 'Let''s stay in tonight and watch a movie.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38952, 'stay on', 'to continue to be in a place, job, or school after the other people who were with you have left:', 'Gill decided to stay on at university to do further research.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38953, 'stay on the rails', 'to continue to behave in a way that is generally acceptable, honest, and legal:', 'I hope he manages to stay on the rails.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38954, 'stay on the sidelines', 'If you stay on the sidelines, you are not an important part of what is happening.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38955, 'stay out', 'to not come home at night, or to go home late:', 'Our cat usually stays out at night.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38956, 'stay out of something', 'to not become involved in an argument or discussion:', 'It''s better to stay out of their arguments.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38957, 'stay over', 'to sleep at someone''''s house for one night:', 'Why don''t you stay over and drive back in the morning?', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38958, 'stay put', 'to remain in the same place or position:', 'Just stay put with the suitcases, while I go and find a cab.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38959, 'stay the course', 'to continue doing something until it is finished or until you achieve something you have planned to do:', 'She interviewed dieters who had failed to stay the course to find out why they had given up.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38960, 'stay up', 'to go to bed later than usual:', 'We stayed up (late) to watch a film.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38961, 'stay up', 'If a football team stays up, it remains in a division and is not relegated (= moved down to a lower division):', 'I think all the newly-promoted clubs have a great chance of staying up this season.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38962, 'steady on!', 'used to tell someone that what they are saying is too extreme:', 'Steady on, Chris - she''s nice but she''s not that nice!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38963, 'steal a march on someone', 'If you steal a march on someone, you get an advantage over that person by acting before they do:', 'Our rival company managed to steal a march on us by bringing out their software ahead of ours.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38964, 'steal someone''''s thunder', 'to do what someone else was going to do before they do it, especially if this takes success or praise away from them:', 'Sandy stole my thunder when she announced that she was pregnant two days before I''d planned to tell people about my pregnancy.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38965, 'steal the limelight', 'to get more attention than anyone or anything else in a situation:', 'The experimental car certainly stole the limelight at the motor show.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38966, 'steal the show/scene', 'to be the most popular or the best part of an event or situation:', 'The child with the dog stole the show.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38967, 'steam (something) up', 'If glass or something with a glass or similar surface steams up, it becomes covered with a thin layer of water caused by steam touching it, and if you steam it up, you cause this to happen:', 'The bathroom mirror steamed up during my shower.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38968, 'steamed up', 'angry, especially about something that other people do not think is important:', 'She got all steamed up about the books being left on the tables.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38969, 'steep something/someone in something', 'If something or someone is steeped in something, they are completely surrounded by or involved in it, or know a lot about it:', 'The college is steeped in history/tradition.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38970, 'steeped in blood', 'used to describe a place where many people have died in a violent way, or a person responsible for the deaths of many people:', 'The castle''s history is steeped in blood.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38971, 'steer a course/path', 'to take a series of actions, usually of a particular type, carefully and intentionally:', 'It will be difficult to steer a middle course between the competing claims of the two sides in the conflict.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38972, 'steer clear of someone/something', 'to avoid someone or something that seems unpleasant, dangerous, or likely to cause problems:', 'Her speech steered clear of controversial issues.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38973, 'stem from something', 'to start or develop as the result of something:', 'Her problems stem from her difficult childhood.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38974, 'step aside', 'to step sideways to make a space for someone else:', 'Step aside, please - this lady needs a doctor.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38975, 'step aside/down', 'to leave an important job or position, especially to allow someone else to take your place:', 'He has decided to step down as captain of the team.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38976, 'step away', 'to stop being involved in something:', 'He is not going to step away from the battle just yet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38977, 'step back', 'to temporarily stop being involved in an activity or situation in order to think about it in a new way:', 'Let''s just step back from the problem and think about what we could do.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38978, 'step back (in time)', 'to go back into the past:', 'Visiting her house was like stepping back in time/stepping back 50 years.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38979, 'step in', 'to become involved in a difficult situation or argument in order to help find a solution:', '[ + to infinitive ] An outside buyer has stepped in to save the company from going out of business.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38980, 'step into someone''''s shoes', 'to take someone''''s place, often by doing the job they have just left:', 'Who do you think will step into Sarah''s shoes when she goes?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38981, 'step into something', 'If you step into a job, you get it very easily:', 'He just stepped straight into a job as soon as he left college.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38982, 'step into the breach', 'If you step into the breach, you do someone else''''s work when they are unable to do it:', 'Gail''s sudden illness meant that Kathy had to step into the breach.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38983, 'step on it', 'used to tell someone to drive faster or to hurry:', 'Could you step on it? I''m late.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38984, 'step on someone', 'to treat someone unfairly or unkindly', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38985, 'step on someone’s toes', 'to upset someone, esp. by getting involved in something that is that person’s responsibility:', 'It’s a very competitive business – you can’t afford to step on too many toes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38986, 'step on the gas', 'to drive faster:', 'I have a fear of being rear-ended if I slow down, because the guy behind me is stepping on the gas.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38987, 'step on the gas', 'to do something more quickly or with more effort and determination:', 'We need to step on the gas in terms of how we''re performing in the market.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38988, 'step out', 'to leave a place, esp. for a short time:', 'Mr. Taylor just stepped out of the office to get the mail.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38989, 'step out of line', 'to behave in a way that is unacceptable or not expected:', 'Step out of line one more time, Peters, and you''re fired!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38990, 'step out on someone', 'If you step out on your husband, wife, or usual sexual partner, you have sexual relationships with people other than them.', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38991, 'step something down', 'to reduce the amount, supply, or rate of something:', 'The doctor has said that I can start stepping down my medication in a few days'' time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38992, 'step up', 'to take action when there is a need or opportunity for it:', 'Investors have to step up and assume more responsibility for their assets.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38993, 'step something up', 'to increase the size, amount, or speed of a process that is intended to achieve something:', 'The police are stepping up their efforts to fight crime.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38994, 'step up to the plate', 'to take action when something needs to be done, even though this is difficult:', 'He took over the team when it became obvious no one else was going to step up to the plate.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38995, 'step/be out of line', 'to behave in an unsuitable way:', 'It was made quite clear to me that if I stepped out of line again I''d be out of a job.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38996, 'step/move up a gear', 'to start to do something better, especially in sports, in a way that is easy to see:', 'After a disappointing first half, United moved up a gear and took control of the game.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38997, 'step/tread on someone''''s toes', 'If you step/tread on someone''''s toes, you say or do something that upsets or annoys that person, especially by involving yourself in matters that are not your responsibility.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38998, 'stew (in your own juice)', 'to think about or suffer the results of your own actions, without anyone giving you any help', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (38999, 'stew (in your own juices)', 'to think about or suffer the results of your own actions, without anyone giving you any help', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39000, 'sth has to be seen to be believed', 'to be so extreme that it is difficult to believe:', 'The prices in that place have to be seen to be believed!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39001, 'sth is the new black', 'used to say that a particular colour has replaced black as the most popular or fashionable colour at the moment:', 'Designers say that brown is the new black.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39002, 'sth is the new black', 'used to say that something is extremely popular or fashionable at the moment:', 'Being environmentally aware is so fashionable these days that you could say green is the new black.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39003, 'stick around', 'to stay somewhere for a period of time:', 'You go - I''ll stick around here a bitlonger.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39004, 'stick at something', 'to continue trying hard to do something difficult:', 'You''ll never learn to play the piano if you''re not going to stick at it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39005, 'stick by something/someone', 'to continue to support something or someone, especially in a difficult situation:', 'We must stick by our decision.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39006, 'stick in someone''''s craw', 'to make you angry', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39007, 'stick in someone''''s mind/head/memory', 'to remember something', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39008, 'stick in someone''''s throat', 'to be unable to say the words you want to say, usually because of a strong emotion:', 'She looked at him, but her voice stuck in her throat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39009, 'stick in someone''''s throat', 'to make you angry:', 'It really sticks in my throat that I did all the work, and she''s getting all the credit.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39010, 'stick it out', 'to continue to the end of a difficult or unpleasant situation:', 'I know things are difficult right now, but if we just stick it out, I''m sure everything will be OK in the end.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39011, 'stick out', 'to go past the surface or edge of something:', 'Paul''s ears stick out a little.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39012, 'stick out', 'to be very easy to notice:', 'She certainly sticks out in a crowd.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39013, 'stick (something) out', 'to come forward from the rest of your body, or to make part of your body do this:', 'Mum, Lewis stuck out his tongue at me!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39014, 'stick out for something', 'to continue to demand or try to get something:', 'The unions have said that they are going to stick out for a ten percent rise.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39015, 'stick someone with something', 'to force someone to have or do something that is not very good:', 'Big power companies grab cheap supplies and stick everyone else with more expensive ones.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39016, 'stick with something/someone', 'to continue doing something or using someone to do work for you, and not stop or change to something or someone else:', 'He said that he was going to stick with the traditions established by his grandfather.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39017, 'stick to someone like glue', 'to stay very close to someone:', 'Ellie stuck to her mother like glue.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39018, 'stick to someone''''s ribs', 'If you describe food as sticking to your ribs, you mean that it makes you feel like you have eaten a lot.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39019, 'stick to something', 'to limit yourself to doing or using one particular thing and not change to anything else:', 'Could you stick to the point, please?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39020, 'stick to something', 'If you stick to a law, rule, or promise, you obey it or do what it states:', 'If you make a promise, you should stick to it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39021, 'stick to something', 'to continue trying hard to do something difficult:', 'You''ll never learn to play the piano if you''re not prepared to stick to it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39022, 'stick to your guns', 'to continue to have your beliefs or continue with a plan of action, even if other people disagree with you:', 'Despite harsh criticism, she''s sticking to her guns on this issue.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39023, 'stick together', 'If people stick together, they support and help each other:', 'The country''s foreign minister said that it was important for small nations to stick together.', 'phrasal verb', 'B2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39024, 'stick together', 'If people stick together, they stay close to each other:', 'The two brothers always stick together at school.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39025, 'stick up', 'to point up above the surface of something and not lie flat:', 'When I get up in the morning, my hair is always sticking up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39026, 'stick something/someone up', 'to steal from a place or person, using a gun as a threat:', 'Did you hear that someone stuck up the post office last night?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39027, 'stick up for something/someone', 'to support or defend someone or something, especially when that person or thing is being criticized:', 'I can stick up for myself.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39028, 'stick with it', 'to continue doing something although it is difficult:', 'Things are hard at the moment, but if we stick with it, they are bound to get better.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39029, 'stick your neck out', 'to take a risk', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39030, 'stick your nose into something', 'to try to discover things that are not really related to you:', 'I wish he''d stop sticking his nose into my personal life!', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39031, 'stick your snoot in/into (something)', 'to try to discover things or influence events that are not really your affair:', 'Stop sticking your snoot into other people''s business!', 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39032, 'stick/put your tongue out', 'to make a rude sign by putting the tongue outside the mouth:', 'An old man was staring at her, so she stuck her tongue out at him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39033, 'sticks and stones may break my bones, (but words can never hurt me)', 'said in order to show that people cannot be hurt by unpleasant things that are said to them', NULL, 'idiom', NULL, NULL, 'child''s expression', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39034, 'still waters run deep', 'said about a person who says little, but who might in fact know a lot', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39035, 'stink up something', 'to make a place smell unpleasant:', 'That perfume stunk up the whole store.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39036, 'stir something up', 'to cause an unpleasant emotion or problem to begin or grow:', 'The teacher told him to stop stirring up trouble.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39037, 'stir something up', 'to cause a substance such as soil or dust to move and rise up:', 'The helicopter stirred up clouds of dust.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39038, 'stir the blood', 'If something stirs the blood, it makes you feel excited:', 'tales to stir the blood', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39039, 'stitch something together', 'to create or form something quickly or roughly:', 'Britain is likely to stitch together some sort of political deal to avoid a confrontation.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39040, 'stitch something/someone up', 'to join the two sides of something with stitches, for example torn clothing or a deep cut, or to treat someone who has a deep cut by doing this:', 'I''ve ripped my trousers - can you stitch them up for me?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39041, 'stitch someone up', 'to deliberately make someone look guilty of doing something that they did not do:', 'He claims he was stitched up by the police.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39042, 'stock up', 'to buy a large quantity of something:', 'During the emergency, people stocked up on essential items.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39043, 'stock up (on something)', 'to buy a large amount of something so that you will have enough for the future:', 'I hadn’t stocked up on food, so I wasn’t ready to feed Kate and her friends.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39044, 'stoke up on/with something', 'to eat a lot of a particular food in order to avoid feeling hungry or weak later:', 'As it was a cold morning, she stoked up on bacon, eggs, and beans on toast.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39045, 'stomp on someone/something', 'to step down hard on someone or something:', 'I stomped on his toes and ran away.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39046, 'stomp on someone/something', 'to treat someone or something badly, or to defeat him, her, or it:', 'This is another example of the big companies joining together to stomp on small businesses.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39047, 'stone the crows!', 'used as an expression of surprise:', 'Well, stone the crows - it''s five o''clock already!', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39048, 'stoop to something', 'to lower your moral standards by doing something that is unpleasant, dishonest, or unfair:', 'I don''t believe she would ever stoop to bribery or blackmail.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39049, 'stop (dead) in your tracks', 'to suddenly stop moving or doing something:', 'I stopped dead in my tracks when I heard the scream.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39050, 'stop at nothing', 'If you stop at nothing to achieve something, you are willing to do anything in order to achieve it, even if it involves danger, great effort, or harming other people:', 'She''ll stop at nothing to get her revenge.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39051, 'stop by (somewhere)', 'to visit someone for a short time, usually on the way to another place:', 'I was passing your house, so I thought I''d stop by for a chat.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39052, 'stop by/in/off', 'to visit a place or a person for a short time, esp. when you are on the way to somewhere else:', 'A group of friends stopped by to say hello.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39053, 'stop in', 'to visit a person or place for a short time, usually when you are going somewhere else:', 'I stopped in at work on the way home to check my mail.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39054, 'stop in', 'to stay at home, especially in the evening:', 'I''ve had my tea and I''m stopping in now.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39055, 'stop off somewhere', 'to visit or stay at a place for a short time when you are going somewhere else:', 'I''ll stop off at the shops on my way home and get some wine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39056, 'stop on a dime', 'to be able to stop almost immediately, even when moving very quickly:', 'He runs up the field and stops on a dime to catch the ball.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39057, 'stop over', 'to stay at a place for one night or a few nights on the way to somewhere else or before returning home:', 'They''re stopping over in Malaysia for a couple of nights on the way to Australia.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39058, 'stop short of something', 'If you stop short of doing or saying something, you decide not to do or say it although you almost do:', 'I stopped short of telling him the brutal truth.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39059, 'stop the rot', 'to take action against something bad, before it spreads and becomes worse:', 'We must try to stop the rot before the whole school is corrupted.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39060, 'store something up', 'to keep a lot of something in one place, to be used in the future:', 'We believe that he has been training an army and storing up arms.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39061, 'store something up', 'to remember things, usually so that you can tell people about them later:', 'I listen in to their conversations and store it all up to tell you later.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39062, 'store up trouble/problems', 'to act in a way that will make your problems much worse in the future:', 'If you don''t deal with the problem now, you''ll be storing up trouble for yourself in the future.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39063, 'storm in a teacup', 'a lot of unnecessary anger and worry about a matter that is not important', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39064, 'stow away', 'to hide on a ship, aircraft, or other vehicle in order to escape from a place or to travel without paying', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39065, 'stow (something) away', 'to put something in a safe place so that it can be used in the future:', 'I think I''ll stow the camping equipment away in the loft until next summer.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39066, 'straight arrow', 'someone who is very honest and careful to behave in a socially acceptable way:', 'Friends described Menendez as a straight arrow who rarely drank and was close to his family.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39067, 'straight up', 'used to show that you are telling the truth:', 'You''re a really attractive woman, straight up!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39068, 'straighten someone out', 'to improve someone''''s behaviour:', 'I thought that once he got a girlfriend that would straighten him out.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39069, 'straighten something out', 'to solve a problem or to deal successfully with a confusing situation:', 'Once we get these problems straightened out, we should be all right.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39070, 'straighten something out', 'to make something tidy or organized:', 'Could you straighten out these cupboards, please?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39071, 'straighten up', 'to stand straight after bending at the waist', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39072, 'straighten up', 'to behave well after behaving badly:', 'You''d better straighten up or else!', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39073, 'straighten something up', 'to make a place tidy:', 'Mark and I managed to straighten up the house before our parents got home.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39074, 'strain after/for effect', 'to try so hard to entertain that it seems false:', 'I find his style of writing so artificial - he always seems to be straining for effect.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39075, 'strain every nerve', 'to make the greatest possible effort:', 'She''s straining every nerve to get the work finished on time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39076, 'strangely enough', 'used to remark that something is surprising but true:', 'Strangely enough, when it came to the test I actually felt pretty relaxed.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39077, 'stranger things have happened', 'used to say that although a suggested event or idea seems very strange or surprising, it is possible:', '"You don''t think Katie and Darryl are falling in love, do you?" "Well, stranger things have happened."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39078, 'strangle something at birth', 'to stop something at an early stage of its development:', 'The plan should have been strangled at birth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39079, 'strap someone in', 'to fasten a seat belt around someone in a car, aircraft, or other vehicle, for safety purposes:', 'Are you kids strapped in back there?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39080, 'strap something up', 'to wrap a leg, arm, or other part of the body in a bandage (= strip of material for wrapping around injuries):', 'He injured himself playing football and his arm was strapped up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39081, 'strapped for something', 'lacking something:', 'Busy executives are strapped for time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39082, 'straw in the wind', 'something that suggests what might happen:', 'She described the theatre''s closure as "a straw in the wind" as companies faced up to the realities of life after the lottery.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39083, 'streak ahead', 'to be much more successful than your competitors:', 'The study revealed that Asian youngsters are streaking ahead in the race to get into university.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39084, 'strengthen someone''''s hand', 'to give someone more power:', 'The police want tougher laws to strengthen their hand against drug traffickers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39085, 'stress someone out', 'to make someone feel very nervous and worried:', 'Interviews always stress me out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39086, 'stretch (yourself) out', 'to lie with your legs and arms spread out in a relaxed way:', 'I just want to get home and stretch out on the sofa.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39087, 'stretch a/the point', 'to make a claim that is not completely true, or to do something that goes further than what is considered to be reasonable:', 'They claim to be the biggest company in the world, which is stretching a point.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39088, 'stretch the length of something', 'to be the same length as something, usually something very long:', 'The underground chambers stretch the length of a football pitch.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39089, 'stretch the truth', 'to say something that is not completely honest in order to make someone or something seem better than it really is:', 'He was accused of stretching the truth about how much he had helped in the project.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39090, 'stretch to something', 'to manage to give or pay a particular amount, often a larger amount than you might expect:', '"How much money do you want to borrow?" "Could you stretch to £50?"', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39091, 'stretch your legs', 'to go for a walk, especially after sitting in the same position for a long time:', 'The car journey took three hours, including a couple of stops to stretch our legs.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39092, 'stretcher someone off', 'to carry a player off a sports field on a stretcher because they are injured:', 'Caldow had been stretchered off with a broken leg.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39093, 'strictly speaking', 'being completely accurate:', 'Strictly speaking, Great Britain consists of Scotland, Wales, and England, and the United Kingdom consists of Great Britain and Northern Ireland.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39094, 'strike a balance', 'If you strike a balance between two things, you accept parts of both things in order to satisfy some of the demands of both sides in an argument, rather than all the demands of just one side:', 'It''s a question of striking the right balance between quality and productivity.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39095, 'strike a blow against/at something', 'to do something that harms something severely:', 'Her resignation has struck a blow against the company''s plans for expansion.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39096, 'strike a blow for something', 'to do something that supports or defends something:', 'The judge''s ruling has struck a blow for racial equality.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39097, 'strike a chord', 'If something strikes a chord, it causes people to approve of it or agree with it:', 'Their policy on childcare has struck a responsive chord with women voters.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39098, 'strike a chord', 'If something strikes a chord, it causes people to remember something else because it is similar to it.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39099, 'strike a chord (with someone)', 'to cause you to remember that something is connected to you in some way:', 'The healthcare reforms struck a chord with voters.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39100, 'strike a note', 'to express and communicate a particular opinion or feeling about something:', 'I find it really difficult to strike the right note when I''m writing job applications.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39101, 'strike an attitude', 'to hold your body in a way that suggests a particular quality or feeling:', 'He struck an attitude of offended dignity and marched out of the room.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39102, 'strike an attitude/attitudes', 'to speak or act in a particular way to try and make other people believe particular things about you, although this may not be sincere:', 'Some politicians prefer to strike attitudes on the world stage rather than deal with problems in their own countries.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39103, 'strike at the heart of something', 'to damage something severely by attacking the most important part of it:', 'By its nature, terrorism is designed to strike at the heart of our democratic values.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39104, 'strike back', 'to attack someone who has attacked you', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39105, 'strike fear/terror into someone', 'to make someone extremely frightened:', 'The brutal military regime has struck terror into the whole population.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39106, 'strike gold', 'to win a gold medal in a sports competition:', 'She is the favourite to strike gold in the 400 metres hurdles.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39107, 'strike gold', 'to make large profits or to become rich:', 'A few lucky people have struck gold by investing in this company.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39108, 'strike home', 'to hit the intended place or have the intended effect:', 'The laser guidance system dramatically increases the likelihood that the missile will strike home.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39109, 'strike it lucky', 'to suddenly have a lot of unexpected luck:', 'What would you do if you struck it lucky in the national lottery?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39110, 'strike it rich', 'to become rich suddenly and unexpectedly:', 'His father struck it rich in the diamond business.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39111, 'strike on/upon something', 'to discover or think of something:', 'She struck on the idea for her novel while she was travelling in Russia.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39112, 'strike out (at someone/something)', 'to hit, or try to hit, someone:', 'He turned around and struck out at the man behind him.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39113, 'strike out (at someone/something)', 'to criticize someone or something in a public way:', 'She struck out at her husband''s family in her famous TV interview.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39114, 'strike out (somewhere)', 'to start on a long or difficult journey in a determined way:', 'In heavy rain, we struck out across the valley.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39115, 'strike out', 'to start doing something new, independently of other people:', 'After working for her father for ten years, she felt it was time to strike out on her own.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39116, 'strike out', 'to be unsuccessful:', 'I really struck out with her - she wouldn''t even kiss me good night.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39117, 'strike (someone) out', 'to fail three times to hit the ball successfully in baseball and therefore to lose one of your team''''s chances to score, or to cause someone to do this:', 'The pitcher struck out all three batters in the ninth inning and saved the game.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39118, 'strike someone down', 'If someone is struck down, they die suddenly or start to suffer from a serious illness:', 'It''s a tragedy that these young people were struck down in their prime.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39119, 'strike something down', 'to rule that a law is illegal and should not be obeyed:', 'The courts struck down local segregation laws because they violated the federal constitution.', 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39120, 'strike someone off (something)', 'If someone with a responsible job such as a doctor or lawyer is struck off, they are officially not allowed to continue in that work because of having done something seriously wrong:', 'A solicitor who insulted two officials from the Law Society was struck off for abusive behaviour.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39121, 'strike something out/through', 'to draw a line through text in a document to show that it does not relate to you or is not correct:', 'Please strike out whichever option does not apply to you.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39122, 'strike up (something)', 'to start to play or sing something:', 'When the applause had died down, a band struck up the national anthem.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39123, 'strike up something', 'to start a relationship or conversation with someone:', 'He gets really jealous if his girlfriend strikes up a friendship with another man.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39124, 'strike while the iron is hot', 'to take advantage of an opportunity as soon as it exists, in case the opportunity goes away and does not return:', 'He doesn''t often make such offers - I''d strike while the iron is hot if I were you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39125, 'strike your fancy', 'to seem interesting or pleasing to someone:', 'She has enough money to buy anything that strikes her fancy.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39126, 'string someone along', 'to deceive someone for a long time about what you are really intending to do:', 'She''s been promising to pay back the money for six months, but I think she''s just stringing me along.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39127, 'string someone up', 'to kill someone by hanging them by the neck from a rope, usually as a punishment for a crime:', 'He''s one of those old-fashioned types who thinks criminals ought to be strung up.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39128, 'string someone up', 'to punish someone severely:', 'He ought to be strung up for what he said about his mother.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39129, 'string something up', 'to tie or fix the ends of a long, thin object to two points that are high up, allowing the rest of it to hang freely:', 'Let''s string up a banner at the front of the house to welcome him home.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39130, 'string something out', 'If a group of similar things or people are strung out, they are in a long line with spaces between each one:', 'Most of Canada''s population is strung out along its 5,525-mile border with the US
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39131, 'string something out', 'to make an activity last longer than necessary:', 'I think the lawyer''s just stringing out the case so that he''ll earn more money.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39132, 'string something together', 'If you string words or sentences together, you manage to say something that other people can understand:', 'People tend to be very impressed if you can string together a couple of sentences in Japanese.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39133, 'strings attached', 'If something such as an agreement has strings attached, it involves special demands or limits:', 'Most of these so-called special offers come with strings attached.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39134, 'strip (down) to something', 'to remove everything except for a particular piece of clothing or above a particular part of the body:', 'I had to strip down to my underwear for my medical examination.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39135, 'strip (sth) down', 'to remove the unnecessary parts of a system or process in order to make it more simple or efficient:', 'Pensions can be made simple by stripping them down to the basic elements with no fancy add-ons.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39136, 'strip sth down', 'to separate a machine or piece of equipment into separate parts in order to clean or repair it:', 'They stripped the car down and repainted all the bodywork.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39137, 'strip sb/sth of sth', 'to take something away from someone, sometimes in a way that seems unfair or dishonest:', 'be stripped of sth About 40,000 people may be stripped of their pensions because their employers have gone into administration.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39138, 'strip something away', 'to gradually reduce something important or something that has existed for a long time:', 'If you strip away all the rhetoric, you''re left with an opinion that isn''t backed up by facts.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39139, 'strip something off', 'to remove a piece of clothing:', 'It was so hot that we stripped off our shirts.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39140, 'strip something out', 'to ignore particular numbers or facts in a situation in order to understand what is really important:', 'After stripping out property sales, the firm''s operating profits rose ten percent.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39141, 'strip sth from sb/sth', 'to take something away from someone or something, especially something that is considered to be important:', 'The Commons vote tonight is to reinstate proposals stripped from the Bill in the House of Lords.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39142, 'strong nerves', 'an ability to not be upset by unpleasant things:', 'You need a strong stomach to work in Accident and Emergency.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39143, 'struggle on', 'to continue dealing with a difficult situation or to continue doing something difficult:', 'When Bobbie leaves, we''ll have to struggle on by ourselves until we find a replacement.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39144, 'strut your stuff', 'to dance in a confident and usually sexually exciting way, especially trying to be noticed by other people:', 'Hey baby, why don''t you get out on the floor and strut your stuff?', 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39145, 'strut your stuff', 'to show your abilities:', 'Wimbledon is the opportunity for all the world''s best tennis players to strut their stuff.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39146, 'stub something out', 'to stop a cigarette from burning by pressing the burning end against a hard surface', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39147, 'stuck on someone', 'infml strongly attracted to someone:', 'Mark’s wife was stuck on him from the day they met.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39148, 'stuck up your own arse', 'a offensive phrase meaning behaving as if you think that you are better or more important than other people:', 'I prefer people who are respectful of others and not stuck up their own arses.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39149, 'studded with something', 'having a lot of something:', 'a hillside studded with trees', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39150, 'study under someone', 'to be taught by someone:', 'As a young painter, he studied under Picasso.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39151, 'stuff and nonsense', 'an expression used to show that you think something is not true and/or is silly', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39152, 'stuff it, them, you, etc.', 'used to show anger or disapproval about a situation or person, or that you refuse to obey someone:', 'He''s expecting us to work late. Well, stuff that/him!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39153, 'stuff your face', 'to eat a lot:', 'I''ve been stuffing my face all morning.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39154, 'stumble across/on something/someone', 'to discover or find something or someone by chance:', 'Look at what I stumbled across at the flea market!', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39155, 'stumble across/on/upon something/someone', 'to discover something by chance, or to meet someone by chance:', 'Workmen stumbled upon the mosaic while digging foundations for a new building.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39156, 'stumble into something', 'to start doing something by chance, without having intended to do it:', 'He had stumbled into teaching English after he finished college.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39157, 'stump up (something)', 'to pay an amount or type of money for something, especially unwillingly:', 'It can be cheaper to stump up for a new washing machine than to get your old one repaired.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39158, 'style it out', 'to behave confidently in an embarrassing situation so that people do not notice it:', 'I fell over during my last song but I managed to style it out to look like a dance move.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39159, 'sub out something', 'to use one thing instead of another:', 'The original recipe called for sesame oil instead of olive oil but sesame oil is expensive so I subbed out olive oil.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39160, 'sub out something', 'to not use one thing and use something else instead:', 'You can sub out the pecans for walnuts or almonds.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39161, 'sub out something', 'to pay someone else to do a job or part of a job that you have agreed to do:', 'In a super efficient model, you would sub out all work except for book keeping, inventory management and strategic management.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39162, 'sub someone out', 'to remove someone from a team and let someone else play in their place:', 'You play as long as you can and then you get subbed out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39163, 'sub someone out', 'to remove someone from a job and give it to someone else instead:', 'When I was in seventh grade, our math teacher was subbed out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39164, 'subject someone/something to something', 'to make someone or something experience an unpleasant or worrying thing:', 'The investigation found that they had been subjected to unfair treatment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39165, 'submerge yourself in something', 'to put all your effort into doing a particular activity:', 'She is an actress who always tries to submerge herself completely in a role.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39166, 'subscribe to something', 'to agree with or support an opinion, belief, or theory:', 'Frank subscribed firmly to the belief that human kindness would overcome evil.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39167, 'such as it is', 'used to suggest that something you have referred to is of low quality or not enough:', 'You''re welcome to borrow my tennis racket, such as it is.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39168, 'such is life', 'used to refer to an event that has happened and that you must accept, because you know that this is the way life is:', 'So here I am, without a girlfriend again. Oh well, such is life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39169, 'suck it and see', 'to try something to find out if it will be successful:', 'I''m not sure whether this paint is the right colour for the bedroom - we''ll just have to suck it and see.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39170, 'suck someone off', 'to use the tongue, lips, and mouth on someone''''s sexual organs to give them pleasure', NULL, 'phrasal verb', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39171, 'suck someone/something dry', 'to remove all useful, valuable qualities or possessions from a person, thing, or place:', 'That firm sucks its new programmers dry after five years and then fires them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39172, 'suck someone/something in/suck someone/something into something', 'to cause someone or something to gradually become involved in an unpleasant situation or harmful activity:', 'I really don''t to get involved in this argument, but I can feel myself being sucked into it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39173, 'suck something in', 'to pull the muscles of your stomach or cheeks inwards, especially to try to make yourself appear thinner:', 'I walked past them in my swimming costume, sucking my tummy in as hard as I could.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39174, 'suck up to someone', 'to try to make someone in authority approve of you by doing and saying things that will please them:', '"Why do you think he offered to take all that work home?" "Oh, he''s just sucking up to the boss."', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39175, 'sucker someone into something', 'to persuade someone to do something by deceiving them:', '[ + -ing verb ] We were suckered into doing the job for free.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39176, 'sucking diesel', 'feeling good:', '"How are you this morning?" "Sucking diesel, mate, sucking diesel."', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39177, 'suffice (it) to say', 'it is enough to say:', 'Suffice (it) to say, Mike won''t be going to Tina''s birthday party after what he said about her to her boss.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39178, 'sugar and spice', 'If you describe someone, especially a woman or a girl, as being sugar and spice, you mean that that person is behaving in a kind and friendly way:', 'She could be all sugar and spice when she wanted to be.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39179, 'sugar the pill', 'to make something bad seem less unpleasant:', 'Plans to improve public services are a way of sugaring the pill of increased taxation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39180, 'suit someone (right) down to the ground', 'If something suits you down to the ground, it suits you perfectly, usually because it is convenient for you:', 'Part-time work would suit me right down to the ground.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39181, 'suit up', 'to prepare to take part in something, especially a sport, by putting on a uniform:', 'Anderson suited up only in games 3 and 4 because of an injured right shoulder.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39182, 'suited and booted', 'dressed in formal clothes:', 'Tom showed up for his interview suited and booted.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39183, 'sum (something/someone) up', 'to describe or express the important facts or characteristics about something or someone:', 'The best way of summing up the situation in our office is to say that it is "absolute chaos".
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39184, 'sum something/someone up', 'An action or object that sums something or someone up represents the most typical qualities of that person or thing:', 'For me, her paintings sum up the restless spirit of America.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39185, 'sum something/someone up', 'to quickly form an opinion about someone or something:', 'She summed up the situation quickly and took charge.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39186, 'sum up', 'When a judge sums up towards the end of a trial, he or she makes a speech to the jury telling them again of the main matters they should consider in the case.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39187, 'sunk in thought', 'thinking deeply:', 'Rodin''s sculpture "The Thinker" is of a man sitting with his head in his hand, sunk in thought.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39188, 'sunny side up', 'If an egg is fried sunny side up, it is fried on one side only:', 'I pulled in to a diner and ordered some fried ham and a couple of eggs sunny side up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39189, 'supply and demand', 'the idea that the price of goods and services depends on how much of something is being sold and how many people want to buy it', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39190, 'sure enough', 'as expected:', 'He said he''d left the book on the desk, and sure enough, there it was.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39191, 'surprise, surprise', 'said when someone has done something or when something has happened in a way that you expected and that you do not approve of:', '"I''ve forgotten my keys again." "Surprise, surprise!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39192, 'surprise, surprise', 'said when you are telling someone about a situation in which something unexpected and pleasant has happened:', 'I asked him if he wanted to come to dinner, and surprise, surprise, he said yes!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39193, 'suss something out', 'to realize, understand, or discover something:', '[ + that ] He never sussed out that they''d tricked him.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39194, 'suss something out', 'to know or understand everything about something:', 'I''ll visit the college and suss it out before I decide whether to apply or not.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39195, 'suss someone out', 'to understand what someone wants to do or what they are like:', 'I can''t suss him out at all.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39196, 'suss someone out', 'to try to find out what someone is like:', 'In those early days we were really cool, just sussing each other out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39197, 'swallow the bait', 'If you swallow the bait, you completely accept something, especially an offer that is a trick or way of getting something from you.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39198, 'swallow up something/someone', 'to take someone or something in so that it is destroyed or no longer independent:', 'The company was swallowed up by a competitor.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39199, 'swallow your pride', 'to decide to do something although it will make you feel embarrassed or ashamed:', 'He was forced to swallow his pride and ask if he could have his old job back.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39200, 'swallow your words', 'to be forced to admit that something you have said has been shown to be wrong:', 'I had to swallow my words when the project turned out to be a great success.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39201, 'swarm with something', 'If a place is swarming with people or things, there are large numbers of them moving around it:', 'The garden is swarming with wasps.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39202, 'swear by something', 'to believe strongly that something is effective or useful:', 'My dad swears by these vitamin pills.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39203, 'swear like a trooper', 'to use a lot of offensive language:', 'He was extremely drunk and swearing like a trooper.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39204, 'swear off something', 'to make a decision to stop doing, using, or being involved with something harmful, such as drugs or alcohol, or something that is not good or helpful:', 'After years of addiction, he swore off drugs completely.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39205, 'swear someone in', 'When someone is sworn in, they make a formal promise to be honest or loyal, either in a law court or when starting a new official job:', 'The next witness was sworn in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39206, 'sweat blood', 'to make a great effort:', 'We sweated blood to get the work finished on time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39207, 'sweat buckets', 'to sweat a lot:', 'It was my first interview and I was sweating buckets.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39208, 'sweat bullets', 'to be extremely nervous and worried about something:', 'I was sweating bullets over this interview.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39209, 'sweat it out', 'to wait nervously for an unpleasant situation to end or improve:', 'I had the blood test last Tuesday, and I''ve been sweating it out ever since, waiting for the results.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39210, 'sweat it out', 'to do hard physical exercise:', 'I like to sweat it out in the gym for a couple of hours every day.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39211, 'sweat over something', 'to work very hard using or doing something:', 'She''s been sweating over that essay all afternoon.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39212, 'sweat sth out', 'to wait nervously for an unpleasant situation to end or improve:', 'Longterm investors are used to sweating out economic downturns.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39213, 'sweep someone along', 'If a feeling or someone''''s behaviour sweeps you along, it makes you feel very enthusiastic about an activity and very involved in it:', 'We were swept along by her eloquence.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39214, 'sweep someone off their feet', 'to make someone become suddenly and completely in love with you:', 'The first time he met her, he was completely swept off his feet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39215, 'sweep something aside', 'to refuse to consider something or to treat it as important:', 'They swept his doubts and objections aside.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39216, 'sweep something under the carpet', 'to hide a problem or try to keep it secret instead of dealing with it:', 'The committee is being accused of sweeping financial problems under the carpet to avoid embarrassment.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39217, 'sweep something under the rug', 'to hide a problem or try to keep it secret instead of dealing with it:', 'The committee is being accused of sweeping financial problems under the rug to avoid embarrassment.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39218, 'sweep the board', 'to win everything that is available:', 'Australia swept the board in the swimming, with gold medals in every race.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39219, 'sweet fanny adams', 'nothing:', 'And what does she know about it? Sweet Fanny Adams!', 'idiom', NULL, NULL, 'old-fashioned, slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39220, 'sweeten the pill', 'to make something bad seem less unpleasant:', 'Plans to improve public services are a way of sweetening the pill of increased taxation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39221, 'swing (something/someone) around', 'to turn around quickly, or to turn something or someone around quickly:', 'She heard a sudden noise behind her and swung around to see who was there.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39222, 'swing at someone', 'to try to hit someone', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39223, 'swing both ways', 'to be sexually attracted to both men and women:', 'I''ve seen her out with men as well. She swings both ways, you know.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39224, 'swing by/past (something)', 'to visit a place quickly, especially on your way to another place :', 'I told Paul we’d swing by his place around 7.30.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39225, 'swing for it', 'to be punished severely for something that has happened:', 'If there''s an error in the calculations, you know who''ll swing for it!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39226, 'swing for someone', 'to hit someone', NULL, 'phrasal verb', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39227, 'swing into action', 'to quickly start working:', 'The emergency services swung into action as soon as the news of the explosion reached them.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39228, 'swing the balance', 'If something swings the balance, it is the thing that causes a particular situation to happen or a particular decision to be made instead of other situations or decisions that are possible:', 'This latest election promise might just swing the balance in the candidate''s favour.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39229, 'switch gears', 'to suddenly change what you are doing esp. the way you think about a particular activity:', 'First they threatened us, then they switched gears and started acting nice.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39230, 'switch off', 'to stop giving your attention to someone or something:', 'If he gets bored, he just switches off and looks out the window.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39231, 'switch on/off something', 'to start or stop a device powered by electricity:', 'She switched the light off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39232, 'switch out something', 'to exchange something for something else:', 'The gallery switches out artwork every three months.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39233, 'switch over', 'to stop doing or using one thing and start another:', 'The system switched over to the backup generator when the power went out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39234, 'switch something on', 'If someone switches on a particular emotion or behaviour, they suddenly start to feel or behave in that way, but usually not sincerely:', 'When a customer walks in, she switches on the charm.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39235, 'switch sth off/on', 'to make a machine or piece of equipment stop or start working by pressing a switch:', 'Mobiles must remain switched off throughout the flight.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39236, 'switch up', 'to change, usually in a way that brings an improvement:', 'This type of company switches up and forms a new business strategy in order to compete.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39237, 'switch up', 'to start doing something more effectively or with more energy:', 'The match went to a tie-break in which Adebisi was able to switch up a gear and win.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39238, 'switch something up', 'to change something, usually in a way that improves it:', 'You might want to switch up a recipe you''ve made several times by trying other flavours.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39239, 'sword of Damocles', 'If you have a sword of Damocles hanging over you/your head, something bad seems very likely to happen to you:', 'The threat of a cut in funding is hanging over the Opera House like a sword of Damocles.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39240, 'swot up (something)', 'to learn as much as you can about a subject, especially before an exam:', 'She''s at home, swotting up on her maths.', 'phrasal verb', NULL, NULL, 'informal, child''s', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39241, 'tack something on', 'to add something that you had not planned to add, often without much preparation or thought:', 'At the last minute they tacked on a couple of extra visits to my schedule.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39242, 'tag along', 'to go somewhere with a person or group, usually when they have not asked you to go with them:', 'I don''t know her, she just tagged along with us.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39243, 'tag something on', 'to add something to what you have said or written at a later time:', 'Tag on a couple of paragraphs about recent events.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39244, 'tail back', 'If traffic tails back, it forms a long line and moves very slowly or stops:', 'There is traffic tailing back along the motorway for ten miles because of road repairs.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39245, 'tail off', 'to reduce in amount or become lower in level:', 'His voice tailed off as he drifted into sleep.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39246, 'take (great) pains to do something', 'to try very hard to so something:', 'He took great pains to dress well for the occasion.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39247, 'take (something) over', 'to start doing a job or being responsible for something that another person did or had responsibility for before:', 'He took over from the previous headmaster in February.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39248, 'take (something) over', 'to get control of a company by buying enough of the shares in it:', 'The company he works for has recently been taken over.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39249, 'take (something) over', 'to become more successful or powerful than something or someone else that is involved in the same type of activity:', 'It''s only a matter of time before they take over completely.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39250, 'take a back seat', 'to choose not to be in a position of responsibility in an organization or activity', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39251, 'take a battering', 'to be defeated heavily:', 'Once again, our team took a battering on Saturday.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39252, 'take a deep breath', 'to pause:', 'I think we all need to stop the arguments, take a deep breath, and remember why we came here .', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39253, 'take a dim view of something', 'to disapprove of something:', 'I take a dim view of this kind of behaviour.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39254, 'take a hard line on someone/something', 'to be very severe in the way that you deal with someone or something', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39255, 'take a hike!', 'a rude way of telling someone to leave', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39256, 'take a hint', 'to understand or do something that is communicated indirectly:', 'I’ve tried to get him to leave, but he can’t take a hint.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39257, 'take a joke', 'to laugh when someone says something funny about you and not be offended:', 'What''s the matter? Can''t you take a joke?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39258, 'take a knee', '(in American football, of a quarterback) to go down on one knee after receiving the ball, stopping the game temporarily:', 'Quarterback Vinny Testaverde took a knee on the final play of the game, symbolically closing out his 21-year career in the place it began.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39259, 'take a knee', '(especially of players in sport) to go down on one knee, usually on a sports pitch before a game, as a protest against racism (= unfair treatment, violence, or hatred directed against people because of their race):', 'Several players on Thursday took a knee, raised a fist or did not take to the field while the anthem was played.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39260, 'take a leaf out of someone''''s book', 'to copy something that someone else does because it will bring you advantages:', 'Maybe I should take a leaf out of Rick''s book and start coming in early every morning.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39261, 'take a leak/have a leak', 'to urinate', NULL, 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39262, 'take a long, hard look at something', 'to examine something very carefully in order to improve it in the future:', 'We need to take a long, hard look at the way we control gun ownership.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39263, 'take a page from someone/something', 'to copy something that someone else does because it will bring you advantages:', 'Taking a page from the Wrights, tests of the engine at Delphi were shrouded in secrecy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39264, 'take a pew!', 'sit down!', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39265, 'take a rain check (on something)', 'used to tell someone that you cannot accept an invitation now, but would like to do so at a later time:', 'Mind if I take a rain check on that drink? I have to work late tonight.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39266, 'take a shine to someone', 'to like someone immediately:', 'I think he''s taken a bit of a shine to you.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39267, 'take a spill', 'to fall off something, usually a bicycle or a horse', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39268, 'take a stroll/trip/walk down memory lane', 'to remember happy times in the past', NULL, 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39269, 'take a tumble', 'to fall suddenly to a lower level:', 'Company profits took a tumble last year.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39270, 'take a turn for the worse', 'to become worse:', 'Her health took a turn for the worse last year.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39271, 'take a walk!', 'a rude way of telling someone to go away:', 'The guy kept pestering her, and finally she told him to take a walk.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39272, 'take a/the fall for someone', 'to accept the blame for something another person did:', 'I wasn''t going to take the fall for him.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39273, 'take after someone', 'to be similar to an older member of your family in appearance or character:', 'He takes after his mother/his mother''s side of the family.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39274, 'take against someone', 'to begin to dislike someone:', 'I think she took against me when I got the promotion she wanted.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39275, 'take care (of yourself)', 'used when saying goodbye to someone:', '"Bye, Melissa." "Goodbye Rozzie, take care."', 'idiom', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39276, 'take care of someone/something', 'to be responsible for someone or something:', 'I have to take care of my little sister this afternoon.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39277, 'take care of someone/something', 'Take care of something also means to do whatever needs to be done in a situation:', 'I was hoping a little money would take care of the problem.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39278, 'take centre stage', 'to be at the centre of attention:', 'She always likes to take centre stage in whatever she does.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39279, 'take charge (of something)', 'to accept responsibility for something and have control over it:', 'She took charge of the project and made sure it was finished on time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39280, 'take first/second place', 'to be the most important thing/a less important thing:', 'Work takes second place.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39281, 'take five', 'used to tell someone to stop working and relax for a short period of time', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39282, 'take heart', 'to feel encouraged:', 'Take heart. You''ll be done soon, and you won''t have to think about this paper ever again.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39283, 'take heed', 'to pay attention to something and be careful about it:', 'It is advisable to take heed of the following misconceptions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39284, 'take hold', 'to become strong; to be established:', 'The economic recovery is just beginning to take hold now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39285, 'take issue with someone/something', 'to disagree strongly with someone or something:', 'I take issue with parents who push their children too hard.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39286, 'take it easy', 'rest, relax, or be calm:', 'You’d better take it easy until you feel better.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39287, 'take it easy', 'You can say take it easy to someone when you say goodbye:', 'Ok, take it easy, you guys. I''ll see you soon.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39288, 'take it from me', 'accept that what I say is true, because I know or have experienced it:', 'It won''t work - take it from me.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39289, 'take it into your head to do something', 'to suddenly decide to do something, often something silly or surprising:', 'Anyway, they took it into their heads to get married.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39290, 'take it on the chin', 'to accept unpleasant events bravely and without complaining', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39291, 'take it one day at a time/take each day as it comes', 'to deal with things as they happen, and not to make plans or to worry about the future:', 'I''ve lived through a lot of changes recently, but I''ve learned to take it one day at a time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39292, 'take it or leave it', 'either accept something without any change or refuse it:', 'I''ll give you $40 for the bike - take it or leave it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39293, 'take it out of someone', 'to make someone very tired:', 'Running around after 25 preschoolers takes it out of me by the end of the week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39294, 'take it upon yourself to do something', 'to accept responsibility for something without being asked to:', 'He took it upon himself to personally thank each person at the meeting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39295, 'take it upon yourself to do sth', 'to accept responsibility for doing something without being asked to:', 'He took it upon himself to personally thank each person at the meeting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39296, 'take it/things easy', 'to relax and not use too much energy:', 'I wasn''t feeling too good, so I thought I''d take it easy for a couple of days.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39297, 'take its toll', 'to cause harm or suffering:', 'The constant stress takes its toll on emergency room workers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39298, 'take its/a toll', 'If something takes its/a toll, it causes suffering, deaths, or damage:', 'The problems of the past few months have taken their toll on her health and there are shadows under her eyes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39299, 'take leave of your senses', 'to lose your good judgment:', 'You can''t take the children out sailing in this weather! Have you completely taken leave of your senses?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39300, 'take matters into your own hands', 'to deal with a problem yourself because the people who should have dealt with it have failed to do so:', 'When the police failed to catch her son''s murderer, she decided to take matters into her own hands.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39301, 'take no prisoners', 'to be very determined and not care about other people''''s feelings when trying to achieve something:', 'When Eric''s anger is aroused, he takes no prisoners.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39302, 'take note of something', 'to give attention to something, especially because it is important:', 'You should take careful note of what she tells you because she knows their strategy well.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39303, 'take notice (of something)', 'to give something your attention:', 'Voters are beginning to take notice of him as a serious candidate.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39304, 'take one (thing) at a time', 'to do or deal with one thing before starting to do or deal with another:', 'There are a few problems, but let''s take one thing at a time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39305, 'take one for the team', 'to do or experience something unpleasant, or accept blame or punishment for something, so that other members of a group do not have to:', 'If somebody has to do it, I''ll be glad to take one for the team.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39306, 'take over/up the reins', 'to take control of something, especially an organization or a country:', 'He took up the reins of government immediately after the coup.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39307, 'take part in something', 'to be actively involved in something with other people:', 'All the children took part in the Thanksgiving play.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39308, 'take place', 'to happen:', 'The story takes place in the 18th century.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39309, 'take root', 'If an idea, belief, or system takes root somewhere, it starts to be accepted there:', 'Communism has never really taken root in England.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39310, 'take shape', 'to start to develop a more clear or certain form:', 'We watched the vase begin to take shape in the potter''s hands.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39311, 'take sides', 'to support one person or opinion over another:', 'My mother never took sides when my brother and I argued.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39312, 'take silk', 'to become a QC', NULL, 'idiom', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39313, 'take some beating', 'If something takes some beating, it is so good that it is hard to improve on it:', 'His new world record will take some beating.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39314, 'take someone aback', 'to surprise or shock someone so much that they do not know how to behave for a short time:', 'I was a little taken aback at the directness of the question.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39315, 'take someone around (something/somewhere)', 'to walk through a building or visit a place with someone, showing them the most interesting or important parts:', 'You will be taken around the museum by one of the guides.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39316, 'take someone down', 'to defeat or kill someone, or to stop someone from causing harm:', 'The Indiana Pacers took down Cleveland, 80–74.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39317, 'take something down', 'to remove something that is on a wall or something that is temporary, or to remove a structure by separating its different parts:', 'I took the pictures down.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39318, 'take something down', 'to write something that another person has just said:', 'He took down my address and phone number and said he''d call me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39319, 'take someone for a ride', 'to deceive or cheat someone:', 'I think we''ve been taken for a ride.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39320, 'take someone out of himself/herself', 'to change someone''''s mood and stop them from thinking negative thoughts', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39321, 'take someone round (something/somewhere)', 'to walk through a building or visit a place with someone, showing them the most interesting or important parts:', 'You will be taken round the museum by one of the guides.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39322, 'take someone through something', 'to explain something to someone:', 'I''ll take you through it one more time, then you can try it yourself.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39323, 'take someone to task for something', 'to criticize someone:', 'My professor took me to task for not citing my sources correctly.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39324, 'take someone to the cleaner''''s', 'to get a lot of money from someone, usually by cheating them:', 'Paul was really taken to the cleaner''s on that deal.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39325, 'take someone to the cleaner''''s', 'to defeat someone by a very large amount:', 'In the second half, United were really taken to the cleaner''s, and they finally lost the match 6–1.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39326, 'take someone under your wing', 'If you take someone under your wing, you start to protect and take care of them:', 'I was a little bit lonely at the time and she took me under her wing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39327, 'take someone up on something', 'to accept an offer that someone has made:', 'Could I take you up on that offer of a lift, Rob?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39328, 'take someone''''s breath away', 'to be extremely beautiful or surprising:', 'The beauty of the Taj Mahal took my breath away.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39329, 'take someone''''s life', 'to kill someone', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39330, 'take someone''''s mind off something', 'to stop you from worrying or thinking about a problem or pain, often by forcing you to think about other things:', 'The good thing about running is that it takes my mind off any problems I have.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39331, 'take someone''''s name in vain', 'to criticize someone or talk about someone without respect, especially when they are not there', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39332, 'take someone''''s part', 'to support someone:', 'For once, my brother took my part in the argument.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39333, 'take someone''''s word for it', 'to believe that what someone says is true:', 'He said he''d give me a job and I just took him at his word.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39334, 'take someone/something in hand', 'to start to be in charge of someone or something, especially in order to improve a situation or someone''''s behaviour:', 'The matter was taken in hand by the director himself.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39335, 'take someone/somewhere by storm', 'to be suddenly extremely successful in a place or popular with someone:', 'As everyone knows, the Beatles took the US by storm.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39336, 'take something apart', 'to separate something into its different parts:', 'We took the engine apart to see what the problem was.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39337, 'take someone apart', 'to defeat someone very easily in a sport:', 'He took their defence apart, scoring three goals in the first 20 minutes.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39338, 'take something as it comes', 'to deal with something as it happens, without planning for it:', 'Just take each day as it comes and do what you feel is right.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39339, 'take something as read', 'to accept that something is true without making sure that it is:', 'I just took it as read that anyone who applied for the course would have the necessary qualifications.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39340, 'take something at face value', 'to accept something as it appears to be rather than studying it more closely:', 'I took the offer at face value. I didn''t think they might be trying to trick me.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39341, 'take something away', 'to remove something:', 'Take these chairs away - we don''t need them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39342, 'take something away', 'to subtract a number (= remove it from another number):', 'Four take away two is two.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39343, 'take something away', 'to get a particular message or piece of information from something you read or are told :', 'What I took away from his talk is that going to university is definitely worth it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39344, 'take something away', 'to buy food in a restaurant and eat it somewhere else:', 'Is that to eat in or take away?', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39345, 'take something back', 'to return something you have bought to a shop:', 'Is it too small? Take it back and get a refund.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39346, 'take something back', 'to admit that something you said was wrong:', 'All right, I take it all back. It wasn''t your fault.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39347, 'take someone back', 'to allow a partner who previously left your home because of a disagreement or another relationship to come back to live with you:', 'His wife said she would never take him back.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39348, 'take someone back', 'If something takes you back, it makes you remember a period or an event:', 'That piece of music really took me back (to my schooldays).', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39349, 'take something for granted', 'to never think about something because you believe it will always be available or stay exactly the same:', 'I took it for granted that I would find the perfect job.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39350, 'take something from someone', 'If you take words, information, or ideas from another person or piece of work, you use or develop them in some way:', 'The plot is taken from Shakespeare.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39351, 'take something in', 'to understand completely the meaning or importance of something:', 'I had to read the letter twice before I could take it all in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39352, 'take something in', 'to include something:', 'The new town takes in three former villages.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39353, 'take something in', 'to receive money from sales or as payment for entrance to an event:', 'The show took in an astonishing $100,000 in its first week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39354, 'take something in', 'to go to watch a film or performance, or to visit a place such as a museum:', 'I thought we could get something to eat and then take in a movie.', 'phrasal verb', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39355, 'take something in', 'to make a piece of clothing narrower, by changing the position of some of the stitches joining it together:', 'I''ll have to take this dress in at the waist - it''s too big.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39356, 'take something in', 'to do paid work for other people, such as washing or sewing, in your home:', 'She supported her family by taking in laundry.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39357, 'take someone in', 'to take care of someone and provide a place in your home for them:', 'Several families took in foreign students.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39358, 'take someone in', 'to cause someone to believe something that is not true, or to trick or deceive someone:', 'I can''t believe she was taken in by him.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39359, 'take someone in', 'If the police take you in, they take you to the police station:', 'Detectives on the murder inquiry have taken in a new suspect for questioning.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39360, 'take something in your stride', 'to deal with a problem or difficulty calmly and not to allow it to influence what you are doing:', 'When you become a politician, you soon learn to take criticism in your stride.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39361, 'take something into account', 'to consider or remember something when judging a situation:', 'I hope my teacher will take into account the fact that I was ill just before the exams when she marks my paper.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39362, 'take something off', 'to remove something, especially clothes:', 'He took off his clothes and got into the shower.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39363, 'take something off', 'to spend time away from your work:', 'He took two weeks off in September.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39364, 'take off', 'If an aircraft, bird, or insect takes off, it leaves the ground and begins to fly:', 'The plane took off at 8.30 a.m.', 'phrasal verb', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39365, 'take off', 'to suddenly start to be successful or popular:', 'Her singing career had just begun to take off.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39366, 'take off', 'to suddenly leave somewhere, usually without telling anyone that you are going:', 'When he saw me, he took off in the other direction.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39367, 'take someone off', 'to copy the way a particular person speaks or behaves, or the way something is done, usually in order to entertain other people:', 'She''s really good at taking people off.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39368, 'take something on', 'to accept a particular job or responsibility:', 'She took too much on and made herself ill.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39369, 'take on something', 'to begin to have a particular quality:', 'Her voice took on a troubled tone.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39370, 'take someone on', 'to employ someone:', 'She was taken on as a laboratory assistant.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39371, 'take someone on', 'to compete against or fight someone:', 'The government took on the unions and won.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39372, 'take something on board', 'to understand or accept an idea or a piece of information:', 'Banks need to take on board the views of their customers.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39373, 'take something out', 'to remove something from somewhere:', 'They had to take out two of his teeth.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39374, 'take something out', 'to get money from a bank account:', 'I took out some money for the weekend.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39375, 'take something out', 'to arrange to get something from a company, bank, etc.:', 'I’m going to take out a life insurance policy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39376, 'take something out', 'to buy food in a restaurant and eat it somewhere else:', 'Is that to eat in or take out?', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39377, 'take someone out', 'to go somewhere and do something with someone, usually something you plan and pay for:', 'Dad''s taking the whole family out to the cinema.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39378, 'take someone/something out', 'to kill someone or destroy something:', 'The soldiers said that they were trying to take out the snipers.', 'phrasal verb', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39379, 'take something out on someone', 'to treat someone badly because you are upset or angry, even if they have done nothing wrong:', 'I know you''ve had a bad day, but you don''t have to take it out on me!', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39380, 'take something to heart', 'If you take criticism or advice to heart, you think about it seriously, often because it upsets you:', 'Don''t take it to heart - he was only joking about your hair.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39381, 'take something to pieces', 'to separate something into smaller parts:', 'If you take the bookcase to pieces, it will fit in the back of your car.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39382, 'take something up', 'to fill an amount of space or time:', 'This desk takes up too much room.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39383, 'take something up', 'to start doing a particular job or activity:', 'He''s taken up the position of supervisor.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39384, 'take something up', 'to start an official job:', 'The minister took up office in December.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39385, 'take something up', 'to discuss something or deal with something:', 'The school took the matter up with the police.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39386, 'take something up', 'to make a piece of clothing, such as a skirt or trousers, shorter', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39387, 'take something with a grain of salt', 'to not completely believe something that you are told, because you think it is unlikely to be true:', 'You have to take everything she says with a grain of salt, because she tends to exaggerate.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39388, 'take something with a pinch of salt', 'to not completely believe something that you are told, because you think it is unlikely to be true:', 'You have to take everything she says with a pinch of salt, because she tends to exaggerate.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39389, 'take sth forward', 'to deal with something and make it successful in the future:', 'You need to find the best manager to take the idea forward.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39390, 'take stock', 'To take stock (of something) is to think carefully about a situation or event and form an opinion about it, so that you can decide what to do:', 'After two years spent teaching overseas, she returned home for a month to take stock of her life.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39391, 'take stock (of something)', 'to examine a situation carefully:', 'After the storm homeowners came out to take stock of the damage.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39392, 'take that!', 'said as someone hits someone else, especially in humorous films or cartoons', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39393, 'take the bad with the good', 'to accept all the features or parts of something, good and bad:', 'You have to take the bad with the good in any career.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39394, 'take the ball and run with it', 'to continue an activity or process that someone else has started, often when that person could not finish it or make it work:', 'We had a very vague idea of what we wanted, but the marketing team just took the ball and ran with it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39395, 'take the biscuit', 'to be especially annoying, surprising, etc. or to be the worst or best of its kind:', 'And you say she''s opening your letters now? Oh, that really takes the biscuit!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39396, 'take the bull by the horns', 'to do something difficult in a brave and determined way:', 'Why don''t you take the bull by the horns and tell him to leave?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39397, 'take the cake', 'to be especially annoying, surprising, etc. or to be the worst or best of its kind:', 'And you say she''s opening your letters now? Oh, that takes the cake!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39398, 'take the chill off something', 'to make something slightly less cold:', 'We lit the fire to take the chill off the room.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39399, 'take the edge off something', 'to make something unpleasant have less of an effect on someone:', 'Have an apple - it''ll take the edge off your hunger.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39400, 'take the gilt off the gingerbread', 'to spoil something that is in every other way enjoyable:', 'We had a great trip, but our flight home was badly delayed, which took the gilt off the gingerbread.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39401, 'take the gloss off something', 'to make an event or occasion less special and enjoyable:', 'The bad weather really took the gloss off our trip to the zoo.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39402, 'take the heat off someone', 'If someone or something takes the heat off you, he, she, or it reduces the amount of criticism you have to deal with:', 'The deputy''s resignation over the scandal has taken some of the heat off his superior.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39403, 'take the high road', 'to behave in a moral way when other people are not behaving morally:', 'He decided to take the high road and say he was sorry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39404, 'take the initiative', 'to be the first one to do something, esp. to solve a problem:', 'Don''t be afraid to take the initiative and say what you think.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39405, 'take the law into your own hands', 'to do something illegal and often violent in order to punish someone because you know the law will not punish that person:', 'One day, after years of violent abuse from her husband, she took the law into her own hands.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39406, 'take the liberty of doing something', 'to do something that will have an effect on someone else, without asking their permission:', 'I took the liberty of booking theatre seats for us.', 'idiom', 'C1', NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39407, 'take the long view', 'to think about the effects that something will have in the future instead of in the present:', 'If you take the long view, of course, you can regard staff training as an investment for the company.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39408, 'take the piss', 'to be very annoying and unfair:', '£10 for a burger - that''s taking the piss!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39409, 'take the piss (out of someone or something)', 'to make a joke about someone or make someone look silly:', 'They''re always taking the piss out of him because he''s a Barry Manilow fan.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39410, 'take the plunge', 'to make a decision to do something, especially after thinking about it for a long time:', 'They''re finally taking the plunge and getting married.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39411, 'take the rough with the smooth', 'to accept the unpleasant parts of a situation as well as the pleasant parts:', 'That''s relationships for you - you have to take the rough with the smooth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39412, 'take the salute', 'When a person of high rank takes the salute, they stand and watch while soldiers march past saluting them.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39413, 'take the shine off (something)', 'to make something seem less perfect or less good; to partly spoil something:', 'He got back to find his car had been towed, which certainly took the shine off a great day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39414, 'take the sting out of something', 'If something takes the sting out of an unpleasant situation, it makes it less unpleasant:', 'The new policy of shorter working hours will serve to take the sting out of the pay cut.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39415, 'take the time', 'to make the effort to do something:', 'She didn''t even take the time to wish me good morning.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39416, 'take the time to do something', 'to spend enough time to do something well or carefully:', 'She didn’t even take the time to say goodbye.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39417, 'take the weight off your feet/legs', 'If you take the weight off your feet/legs, you sit down, especially after standing or walking for a long time:', 'You must be exhausted after all that shopping - sit down and take the weight off your feet!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39418, 'take the wind out of someone''''s sails', 'to make someone feel less confident or less determined to do something, usually by saying or doing something that they are not expecting:', 'I was all ready to tell him that the relationship was over when he greeted me with a big bunch of flowers - that took the wind out of my sails.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39419, 'take the words out of someone''''s mouth', 'to say something that another person was just about to say or was thinking:', '"What a rude and obnoxious man!" "You took the words right out of my mouth!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39420, 'take the wraps off something', 'to allow people to know about something', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39421, 'take things easy', 'to relax and not work too hard:', 'My doctor told me to take things easy for a while.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39422, 'take to drink', 'to start drinking alcohol often, sometimes because of a personal problem:', 'He took to drink after his wife left him.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39423, 'take to someone/something', 'to start to like someone or something:', 'The two dogs took to each other immediately and started to play.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39424, 'take to something', 'to start doing something often:', 'She was so depressed she took to drink.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39425, 'take to somewhere', 'to go somewhere, usually because you are in a difficult or dangerous situation:', 'The refugees took to the hills for safety.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39426, 'take to something like a duck to water', 'to discover when you start to do something for the first time that you have a natural ability to do it:', 'He took to fatherhood like a duck to water.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39427, 'take to the road', 'to start travelling:', 'After a short visit, they took to the road again.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39428, 'take to your bed', 'to go to bed, especially because you feel ill or unable to deal with things:', 'She took to her bed right after Alice was born and did not want to see anyone.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39429, 'take to your heels', 'to quickly run away:', 'When they saw the soldiers coming, they took to their heels.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39430, 'take up the cudgels for/against someone/something', 'to argue strongly in support of, or against, someone or something:', 'Relatives have taken up the cudgels for two British women accused of murder.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39431, 'take up with someone', 'to become friendly or start a relationship with someone, especially someone who might have a bad influence on you:', 'She''s taken up with a strange crowd of people.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39432, 'take years off someone', 'If something takes years off a person, it makes them appear or feel much younger:', '"Have you seen James without his beard?" "I know - it takes years off him!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39433, 'take your (own) life', 'to kill yourself', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39434, 'take your cue from something/someone', 'to be strongly influenced by something or someone:', 'The architects took their cue for the design of the new hotel from the nearby banks.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39435, 'take your eye off the ball', 'to not give your attention to what you are doing at the time:', 'If you''re a manager, you can''t afford to take your eye off the ball for one minute.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39436, 'take your foot off the gas', 'to do something with less effort and determination:', 'Usually we take our foot off the gas if we''re comfortably ahead.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39437, 'take your hat off to someone', 'If you say that you take your hat off to someone, you mean that you admire them for an achievement:', 'So Emma actually manages to juggle two small children and a full-time job, does she? Well, I take my hat off to her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39438, 'take your life in your hands', 'to do something that is very dangerous, especially where you risk death:', 'Every time you go parachuting you''re taking your life in your hands.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39439, 'take your lumps', 'to be criticized or beaten as a punishment', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39440, 'take your pick', 'choose any one you want:', 'You can take your pick of any dessert on the cart.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39441, 'take your time', 'said to mean that you can spend as much time as you need in doing something, or that you should slow down', NULL, 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39442, 'take your time', 'to do something too slowly:', 'The builders are really taking their time.', 'idiom', 'C1', NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39443, 'take/get a pounding', 'to receive a lot of criticism:', 'The movie took quite a pounding from the critics.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39444, 'take/have a knock', 'to be damaged because of a bad experience:', 'Her confidence took a hard knock when her application was rejected.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39445, 'take/lead someone on/to one side', 'to have a private talk with someone:', 'Bill''s father took him to one side and told him to stop misbehaving.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39446, 'take/need a cold shower', 'an expression used when someone needs to calm down when something has made them feel sexually excited:', 'Did you see the dress she was wearing? I think I''d better go and take a cold shower!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39447, 'take/pick up the gauntlet', 'to agree to fight or compete with someone', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39448, 'take/sign the pledge', 'to make a formal promise to stop drinking alcohol:', 'What''s this then, you''re only drinking orange juice - have you signed the pledge or something?', 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39449, 'tale of woe', 'a report of the bad things that have happened:', 'I asked how he was and he started telling me this big tale of woe.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39450, 'talk a blue streak', 'to talk quickly and without stopping:', 'He talked a blue streak all through breakfast.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39451, 'talk about ...', 'used to emphasize that something is very noticeable in the stated way:', 'I read the whole book, but talk about boring!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39452, 'talk about something/doing something', 'to think about or make plans to do something in the future:', 'They''re always talking about selling the house and moving away.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39453, 'talk around something', 'to avoid speaking directly about something:', 'He just kept talking around the subject and didn''t tackle the main issues.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39454, 'talk at someone', 'to speak to someone without listening to that person or allowing them to speak:', 'What discussion? You weren''t talking to me, you were talking at me!', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39455, 'talk back', 'If a child talks back, he or she replies rudely to someone:', 'Children who talk back are regarded as disrespectful.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39456, 'talk dirty', 'to describe sexual acts to another person using rude words', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39457, 'talk down to someone', 'to talk to someone as if they are less intelligent than you or not important:', 'I wish politicians wouldn''t talk down to us as if we were idiots.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39458, 'talk nonsense', 'to say things that are not reasonable or have no meaning:', 'Is it just me or was she talking nonsense in the meeting?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39459, 'talk sense', 'to speak in a reasonable way:', 'It''s good to hear someone finally talking sense on this issue.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39460, 'talk shop', 'to talk about your job with those you work with when not at work:', 'Even at a party they have to talk shop!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39461, 'talk smack', 'to make critical or insulting comments to someone, especially an opponent:', 'We argue and fight and talk smack to each other.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39462, 'talk some sense into sb', 'to help someone to think about a situation in a reasonable way:', 'She won''t listen to me - can you try to talk some sense into her?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39463, 'talk someone into something', 'to persuade someone to do something:', 'He''s against the idea, but I think I can talk him into it.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39464, 'talk someone out of something', 'to persuade someone not to do something:', '[ + -ing verb ] Her parents tried to talk her out of getting engaged.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39465, 'talk someone round', 'to persuade someone to agree with you or to do what you want them to do:', 'She''s not keen on the idea but we think we can talk her round.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39466, 'talk someone''''s ass off', 'a rude phrase meaning to talk to someone too much', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39467, 'talk someone''''s ear off', 'to talk to someone for a long time, usually loudly:', 'She talked my ear off.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39468, 'talk someone''''s head off', 'to talk to someone for a long time, usually loudly:', 'She talked my head off.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39469, 'talk something down', 'to talk about something in a way that makes it seem less important or less serious than it really is:', 'He began his lecture by talking down the initiatives of a rival company.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39470, 'talk someone down', 'to speak loudly or without stopping to prevent someone else from speaking:', 'I tried to explain, but he just talked me down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39471, 'talk someone down', 'to persuade someone that he or she is wrong or should not act:', 'Just as soon as the President voiced his dissent, his advisors talked him down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39472, 'talk someone down', 'to persuade someone who is threatening to kill himself or herself not to jump from a high place:', 'The policeman talked the girl down after she had been on the roof for two hours.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39473, 'talk something out', 'to discuss something such as a problem or plan completely in order to find a solution or an agreement:', 'If you two don''t talk out the differences between you, it''ll be hardtalk for you to continue working together.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39474, 'talk something over', 'to discuss a problem or situation with someone, often to find out their opinion or to get advice before making a decision about it:', 'I''d like to talk it over with my wife first.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39475, 'talk something through', 'to discuss all the details of something, often before making a decision:', 'It is very important to try and talk all the issues through so that they can be dealt with in an appropriate manner.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39476, 'talk something up', 'to speak with enthusiasm about something:', 'If we talk up the event, people will come.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39477, 'talk the hind leg(s) off a donkey', 'to talk without stopping for a long time', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39478, 'talk the talk', 'to talk or act in a confident way so that you seem to be very good at what you do:', 'She''s only been a lawyer for three years, but she sure can talk the talk.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39479, 'talk the talk ... walk the walk', 'If you say that someone talks the talk but does not walk the walk, you mean that they do not act in a way that agrees with the things they say:', 'When it comes to recycling he talks the talk but he doesn''t walk the walk.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39480, 'talk through your hat', 'to talk about something without understanding what you are talking about:', 'Nothing of what he said made sense - he was talking through his hat.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39481, 'talk tough', 'to speak in a way that makes other people fear you:', 'He likes to talk tough, but he''s really a sweetheart inside.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39482, 'talk trash', 'to say things that do not have a lot of meaning:', 'There are too many radio shows featuring idiots who call in and talk trash all day.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39483, 'talk trash', 'to criticize other people, especially unfairly or cruelly', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39484, 'talk turkey', 'to discuss something honestly and directly:', 'OK, let''s talk turkey - you''re broke and you don''t have work. What are you going to do?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39485, 'talk your way into/out of something', 'to persuade people that you should do something/not do something by the reasons you give:', 'He talked his way into the job.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39486, 'talk your way out of something', 'to avoid doing something or to get out of a difficult situation by giving someone good reasons why you should not do it:', 'He was known for talking his way out of speeding tickets.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39487, 'talk/speak in riddles', 'to say things in a confusing way', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39488, 'talking of someone/something', 'while we are talking about a particular person or thing:', 'Talking of John, I saw a friend of his last week.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39489, 'tall/great oaks from little acorns grow', 'said about organizations or plans that start off very small or simple and become extremely large or successful', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39490, 'tally (something) up', 'to calculate the total of something:', 'If the game''s over I''ll tally up.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39491, 'tamp down', 'to reduce the amount, level, size, or importance of something:', 'As the price of gasoline rose above $3 a gallon, consumers cut their spending elsewhere, tamping down profits in retail, travel and other industries.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39492, 'tan someone''''s hide', 'to beat someone:', 'I''ll tan his hide if I catch him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39493, 'tangle with someone', 'to become involved with someone, usually by arguing or fighting with them:', 'He was a self-opinionated, overbearing tyrant, and he was the last man she should want to tangle with.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39494, 'tangled up in something', 'involved in something bad:', 'I was not about to get tangled up in their argument.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39495, 'tank up', 'to fill a vehicle with fuel:', 'Make sure you tank up before you go. Gas is expensive on the highway.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39496, 'tap into something', 'to manage to use something in a way that brings good results:', 'If only we could tap into all that energy and creativity.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39497, 'tap out', 'in mixed martial arts and similar sports, to tap the floor to show that you accept that your competitor has beaten you:', 'Suddenly he dropped to his knees and tapped out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39498, 'tap something out', 'to produce the rhythm of a piece of music by hitting a surface gently :', 'He sat at the drums and tapped out the beat.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39499, 'tap something out', 'to write something using a keyboard, mobile phone, etc.:', 'She quickly tapped out a message on her phone.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39500, 'tap someone for something', 'to get money from someone:', 'I might be able to tap my father for a loan.', 'phrasal verb', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39501, 'tape something up', 'to wrap a leg, arm, or other part of the body in a bandage (= strip of material for wrapping around injuries):', 'He got hurt playing football and his arm was taped up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39502, 'taper off', 'to become gradually narrower at one end:', 'Then you''ll come to a place where the pavement tapers off and the dirt road begins.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39503, 'taper off', 'to become gradually smaller or weaker, or happen less often:', 'Her voice tapered off as she realized everyone was listening.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39504, 'tar and feather someone', 'to cover someone in tar and feathers as a punishment', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39505, 'tar someone with the same brush', 'to think that someone has the same bad qualities as another person:', 'Because they worked so closely in the same department, John was tarred with the same brush as Tim.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39506, 'tart yourself up', 'to try to make yourself look more attractive by putting on make-up, jewellery, and fashionable clothes:', 'She''s still in the bathroom, tarting herself up.', 'phrasal verb', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39507, 'tart something up', 'to make something look more attractive or decorative, usually by making very quick or very obvious changes:', 'He made his money by tarting up slum houses and selling them at a huge profit.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39508, 'tea and sympathy', 'kindness and sympathy that you show to someone who is upset:', 'It''s time for action, not just tea and sympathy.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39509, 'teach someone a lesson', 'A person or experience that teaches you a lesson improves your future behaviour by making you experience the bad effects of your actions:', 'Having my car stolen really taught me a lesson - I''ll never leave it unlocked again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39510, 'teach your grandmother to suck eggs', 'to give advice to someone about a subject that they already know more about than you', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39511, 'team up', 'to join another person, or form a group with other people, in order to do something together:', 'They teamed up for a charity performance.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39512, 'tear a strip off someone', 'to criticize someone in a forceful way', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39513, 'tear into something', 'to start doing something with energy and enthusiasm:', 'He tore into his new role as CEO.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39514, 'tear into someone/something', 'to criticize someone or something very strongly:', 'Unfortunately, if he doesn''t agree with you, he tends to tear into you.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39515, 'tear someone away', 'to make someone stop doing something enjoyable, usually because they have to go somewhere or do something else:', 'I''ll bring Tim, if I can tear him away from the TV.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39516, 'tear someone''''s heart out', 'to make someone very sad:', 'The thought of those poor, hungry children is tearing my heart out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39517, 'tear something apart', 'to pull something so violently that it breaks into two or more pieces:', 'A dog can tear a rabbit apart in seconds.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39518, 'tear something apart', 'to make a group of people that was united, such as a country, family, or political party, argue, or fight with each other by dividing it into two or more parts:', 'Ethnic rivalries threaten to tear this country apart.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39519, 'tear something apart', 'to destroy a building or room:', 'The blast had torn the building apart.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39520, 'tear someone/something apart', 'to criticize something or someone severely:', 'The speaker was applauded as he tore apart the prime minister''s policies.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39521, 'tear someone apart', 'to make someone very unhappy:', 'Seeing the children suffer really tears me apart.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39522, 'tear something down', 'to intentionally destroy a building or other structure because it is not being used or it is not wanted any more:', 'They''re going to tear down the old hospital and build a new one.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39523, 'tear something off', 'to remove your clothes quickly and carelessly:', 'I tore my sweaty clothes off and jumped into the shower.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39524, 'tear off', 'to leave very quickly:', 'He got in his car and tore off down the road.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39525, 'tear something up', 'to tear paper into a lot of small pieces:', 'He tore the letter up and threw it away.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39526, 'tear something up', 'If you tear up an agreement, you refuse to accept it or be controlled by it any more:', 'She tore up the contract and walked out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39527, 'tear up', 'to get tears in your eyes, so that you almost start to cry, because you are experiencing strong emotion:', 'She teared up as the award was presented to her.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39528, 'tear your hair out', 'If you tear your hair out over a problem, you are worrying a lot about it:', 'She''s been tearing her hair out over the final chapter of her novel for the last month.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39529, 'tear/rip someone/something to shreds', 'to strongly criticize a person or something they do, think, or say:', 'The critics tore his performance to shreds.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39530, 'tear/rip someone/something to shreds', 'to damage someone or something badly:', 'My trousers were torn to shreds when I fell off my bike.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39531, 'tease something out', 'to try to get information or understand a meaning that is hidden or not clear:', 'It took me a while to tease the truth out of him.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39532, 'tease something out', 'to use your fingers to gradually separate hairs or threads that are stuck or twisted together:', 'While it was still wet, I gently teased out the tangled knots in Rosie''s hair.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39533, 'tee (something) up', 'to put a golf ball on the tee in preparation for playing', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39534, 'tee someone off', 'to make someone angry:', 'It really tees me off when she doesn''t listen to me.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39535, 'tee off', 'to hit a golf ball off the tee, or to begin a game of golf by doing this:', 'We''ll tee off at ten o''clock.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39536, 'teem with something', 'to contain large numbers of animals or people:', 'There are acres of rolling grassland, teeming with elk and antelope.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39537, 'teeter on the brink/edge of something', 'If something is teetering on the brink/edge of a bad situation, it is likely that the situation will happen soon:', 'What we are seeing now is a country teetering on the brink of civil war.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39538, 'tell (someone) the truth', 'to speak honestly:', 'Ok, tell me the truth, did you take her purse?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39539, 'tell against someone/something', 'to make someone or something more likely to fail:', 'His reputation as a troublemaker told against him when he tried to change his job.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39540, 'tell it like it is', 'to describe a situation honestly without avoiding any unpleasant details:', 'I want a newspaper that tells it like it is, without any opinion or political bias.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39541, 'tell me about it!', 'used to say that you feel the same way or have had the same experience:', '"He''s driving me crazy with his stupid jokes." "Tell me about it!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39542, 'tell me another one!', 'used to say that you do not believe what someone has told you:', '"I worked all day yesterday." "Oh yeah, tell me another one!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39543, 'tell on someone', 'to give information about someone, usually something bad that they have said or done, especially to a person in authority', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39544, 'tell on someone', 'to have a bad effect on someone''''s health or behaviour:', 'A succession of late nights had begun to tell on him and his work was suffering.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39545, 'tell someone off', 'to speak angrily to someone because they have done something wrong:', 'The teacher told me off for swearing.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39546, 'tell something/someone apart', 'to be able to see the difference between two very similar things or people:', 'As babies, the twins looked so much alike that I just couldn''t tell them apart.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39547, 'tell that/it to the Marines!', 'said when you do not believe something', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39548, 'tell time', 'to be able to read the time from a clock:', 'Has Adam learned to tell time yet?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39549, 'tempers get frayed', 'If you say that tempers are getting frayed, you mean that people are getting angry with each other.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39550, 'tempest in a teapot', 'a lot of unnecessary anger and worry about a matter that is not important', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39551, 'tempt fate', 'to take a foolish risk because you depend too much on luck:', 'Leaving your door unlocked is just tempting fate.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39552, 'tempt fate/providence', 'If you tempt fate or providence by doing something, you take a silly risk by doing it and depend too much on your good luck:', 'You''re tempting fate by riding your bike without wearing a helmet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39553, 'ten to one', 'If you say ten to one something will or will not happen, you mean it is very likely that it will or will not happen:', 'Ten to one he won''t be there tonight.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39554, 'tend to someone/something', 'to deal with the problems or needs of a person or thing:', 'Nurses tended to the injured.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39555, 'test something out', 'to test something, especially a theory or an idea, to find out how it works in a practical situation or how people react to it:', 'The students tested out their cost-cutting ideas in several companies.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39556, 'test the keeper', 'in football, to kick a ball that a goalkeeper has to save:', 'He tested the goalkeeper again just before half time with a powerful free kick.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39557, 'test the water(s)', 'to find out what people''''s opinions of something are before you ask them to do something', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39558, 'testify to sth', 'to show or prove that something exists or is true:', 'This excellent set of results testifies to the company''s strength in the market.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39559, 'thank God', 'something you say when you are happy because something bad did not happen:', 'Thank God nobody was hurt in the accident.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39560, 'thank God, goodness, heaven(s), etc.', 'said to express happiness that something bad has been avoided or has finished:', 'Thank God you found the key.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39561, 'thank someone for something', 'If you thank someone for something, you mean that they are responsible or to blame for it:', 'You can thank John for the mess we''re in.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39562, 'thank your lucky stars', 'to be very grateful for something:', 'I thank my lucky stars every day for my wonderful husband.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39563, 'thanks a million', 'thank you very much:', '"I''ve done what you asked." "Thanks a million!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39564, 'thanks but no thanks', 'used to say that you are grateful to someone for offering something but that you do not want to accept the offer; sometimes used humorously when you are not really grateful:', 'Former Vice President Al Gore said thanks but no thanks to another run for the presidency.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39565, 'thanks for nothing', 'used to show you are annoyed when someone has done something you are unhappy about or has failed to help you in some way:', '"I told Dad you''d love to wash his car." "Thanks a lot."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39566, 'thanks to someone/something', 'because of someone or something:', 'It''s thanks to Sandy that I heard about the job.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39567, 'that beats everything', 'used to express great surprise:', 'You mean she just left her job without telling anyone she was going? Well, that beats everything!', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39568, 'that did it!', 'said when someone or something has caused damage or a difficulty:', '"That did it!" said Anna as she looked at the damage. "Now I really will have to get a new car."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39569, 'that does it!', 'said when someone or something goes further than the limit of what is acceptable:', 'That does it! I will not tolerate that kind of behaviour in this class.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39570, 'that is to say ...', 'or more exactly:', 'Our friends, that is to say our son''s friends, will meet us at the airport.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39571, 'that is (to say)', 'said when you want to give further details or be more exact about something:', 'I''ll meet you in the city, that is, I will if the trains are running.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39572, 'that makes two of us', 'something that you say to tell someone that you are in the same unpleasant situation, or have the same negative feelings as them:', '"I have no idea what''s going on." "That makes two of us!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39573, 'that was a game, meal, walk, etc. and a half!', 'something that you say about something that was very surprising, very good, or took a lot of time', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39574, 'that was close!', 'used when something bad almost happened, but you managed to avoid it:', 'When we packed up the tent in the morning, he showed me bear tracks, saying " That was a close one!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39575, 'that will do', 'said to mean that you do not want any more of something:', '"Do you need more potatoes peeled?" "No, that''ll do, thanks."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39576, 'that will never do', 'said when you think that something is unacceptable:', '"He promised to pay me back last week, but he didn''t." "Dear me, that will never do!"', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39577, 'that will show someone', 'said of an action that you intend as a punishment for someone who has done something wrong:', 'The next time she''s late home, I''ll throw her dinner away. That''ll show her!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39578, 'that''''ll be the day', 'something you say in order to show you think that something is unlikely to happen:', '"Mike says he''s going to give up smoking." "That''ll be the day!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39579, 'that''''ll do nicely', 'used to say that something is satisfactory:', 'That''ll do nicely, thank you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39580, 'that''''ll do!', 'used to tell someone to stop behaving badly:', 'That''ll do, Timothy! Please just sit down and keep quiet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39581, 'that''''ll put hairs on your chest!', 'something that is said to someone who is going to drink something that contains strong alcohol or eat something satisfying that will make their stomach feel full', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39582, 'that''''ll teach someone', 'used to say that a person should avoid doing something bad in the future thanks to the experience of the effects of their actions:', 'So Roger spent the night in a freezing garage, did he? That''ll teach him to (= show him that he should not) go out without his house keys!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39583, 'that''''s (about) it', 'infmlthere is no more to be said or done:', 'OK everybody, I think that''s it. You can all go home.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39584, 'that''''s a matter of opinion', 'said to show that you do not agree with something that has just been said:', '"Anyway, she''s a wonderful mother." "That''s a matter of opinion."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39585, 'that''''s a new one on me.', 'said when someone has just told you a surprising fact that you did not know before:', '"Sian and Richard are getting married." "Really! That''s a new one on me!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39586, 'that''''s a thought', 'that''''s a good idea:', '"Shall we go on Thursday instead of Friday?" "That''s a thought."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39587, 'that''''s about the size of it', 'used to show your agreement with someone who has said something correct:', '"So you mean you won''t come to the party with me?" "Yes, that''s about the size of it."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39588, 'that''''s all I/you/we need!', 'used when something bad has happened to make a situation that is already difficult worse:', 'And now it''s raining - that''s all I need!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39589, 'that''''s done it!', 'said when someone or something has caused damage or a difficulty:', '"That''s done it!" said Anna as she looked at the damage. "Now I really will have to get a new car."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39590, 'that''''s it', 'used to say that something has ended:', 'Well, that''s it, we''re done - we can go home now.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39591, 'that''''s it', 'used to say that something is correct:', 'You switch the computer on at the back. That''s it.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39592, 'that''''s life!', 'said after something bad or unlucky has happened, to express your feeling that such events will sometimes happen and have to be accepted:', 'No, I didn''t get the job but that''s life, isn''t it?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39593, 'that''''s more like it!', 'used to show that you think something or someone has improved', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39594, 'that''''s my story and I''''m sticking to it', 'used after you have given an explanation that you know is not really true:', 'Anyway, I''m not overweight - my bones are just heavier than most people''s - that''s my story and I''m sticking to it!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39595, 'that''''s that', 'an expression that shows that something has ended:', 'I won''t agree to it and that''s that (= I won''t discuss it any longer).', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39596, 'that''''s the way the cookie crumbles', 'said when something slightly unlucky has happened that could not have been prevented and so must be accepted', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39597, 'that''''s/it''''s your funeral!', 'something that you say that means that if someone suffers bad results from their actions, it will be that person''''s fault, not yours', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39598, 'that/there''''s ... for you', 'used to say that you think something is a typical example of something bad:', 'You spend two hours cooking a meal and they say "it''s disgusting" - that''s children for you!', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39599, 'that’s all right', 'do not worry; everything is OK:', '"Excuse me, I''m sorry." "That''s all right."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39600, 'thaw out', 'If you thaw out, you gradually get warm again after being very cold:', 'I''m just starting to thaw out after taking the dogs out this morning.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39601, 'the (latest) thing', 'something that is very new and fashionable:', 'Retina scanning is the latest thing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39602, 'the Augean Stables', 'in Greek mythology (= ancient stories), the stables (= buildings for keeping horses or cows) of King Augeas, which had never been cleaned until Hercules was given the task of cleaning them:', 'Hercules'' fifth labour was to clean the Augean Stables in a limited time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39603, 'the Augean Stables', 'a place or situation where there is a lot of bad or dishonest behaviour that will be difficult to get rid of:', 'A campaigning US attorney decided that Wall Street was an Augean Stables that he was destined to muck out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39604, 'the Fates', 'three goddesses who the ancient Greeks believed controlled people''''s lives and decided when people must die', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39605, 'the Land of the Rising Sun', 'Japan', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39606, 'the Rolls-Royce of something', 'the best type of a particular type of thing:', 'This model is the Rolls-Royce of lawnmowers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39607, 'the air is blue', 'a person or people is swearing a lot (= using rude words):', '"I used some very strong words." "I imagine you did. I imagine the air was blue."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39608, 'the apple doesn''''t fall far from the tree', 'a child usually has a similar character or similar qualities to his or her parents:', 'Her daughter soon showed her own musical talent, proving that the apple doesn''t fall far from the tree.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39609, 'the apple of someone''''s eye', 'the person who someone loves most and is very proud of:', 'His youngest daughter was the apple of his eye.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39610, 'the awkward gang', 'in the UK , the group of MPs (= people elected to the government) in a party who often disagree with their leader', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39611, 'the back of beyond', 'a place far away from any big town:', 'They live in some village in the back of beyond.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39612, 'the ball is in someone''''s court', 'If the ball is in someone''''s court, they have to do something before any progress can be made in a situation:', 'It''s up to you what to do - the ball is in your court now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39613, 'the ball''''s in someone''''s court', 'it is time for someone to deal with a problem or make a decision, because other people have already done as much as they can:', 'I''ve helped him in every way I can – the ball''s in his court now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39614, 'the balloon goes up', 'If the balloon goes up, a situation suddenly becomes very serious or unpleasant:', 'The balloon went up last Friday when the scandal became public.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39615, 'the beautiful game', 'football', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39616, 'the beautiful people', 'fashionable, rich people:', 'This café is a favourite haunt of the beautiful people.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39617, 'the beauty of something', 'a quality of something that makes it good, easy, or worth doing:', 'One of the beauties of soccer is that you don’t have to be big to play the game.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39618, 'the beginning of the end', 'the point where something starts to get gradually worse, until it fails or ends completely:', 'It was the beginning of the end for their marriage when he started drinking.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39619, 'the best of British (luck)', 'used to wish someone luck, especially when you do not think they have much chance of success or happiness:', 'You''re going to ask her father for money? Best of British, mate!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39620, 'the best of a bad bunch/lot', 'the person or thing of a group that is not as bad as the others, although none of the group is good', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39621, 'the best of both worlds', 'a situation in which you can enjoy the advantages of two very different things at the same time:', 'She works in the city and lives in the country, so she gets the best of both worlds.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39622, 'the best/better part of', 'most of:', 'I spent the better part of a day cleaning that kitchen!', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39623, 'the best/happiest days of your life', 'the most pleasant time you will ever have:', 'Adults like to tell children that their schooldays are the happiest days of their life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39624, 'the better part of', 'most of:', 'We waited there for the better part of an hour.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39625, 'the betting is', 'used to say that it is very likely that something is true or will happen:', 'The betting is Dan will forget to bring the tickets.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39626, 'the big I am', 'If someone is acting the big I am, or giving it the big I am, they are behaving as if they are very important:', 'He was always giving it the big I am with his little gang.', 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39627, 'the big enchilada', 'the most important person or thing:', 'Clinton was the big enchilada, so everyone wanted to know what she thought.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39628, 'the big/bigger picture', 'the most important facts about a situation and the effects of that situation on other things:', 'In my political work I try to concentrate on the big picture and not be distracted by details.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39629, 'the bigger the better', 'how much you value or want something is decided by how big it is:', 'He likes getting big presents - the bigger the better as far as he''s concerned.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39630, 'the bigger they are, the harder they fall', 'said to emphasize that the more important or powerful a person is, the more difficult it is for them when they lose their power or importance', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39631, 'the bird has flown', 'said when the person you are looking for has gone away or escaped', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39632, 'the birds and the bees', 'the basic facts about sex and how babies are produced:', 'She''s only six, but she already knows about the birds and the bees.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39633, 'the bitter fruits of something', 'the unpleasant result of something:', 'The unemployed are tasting the bitter fruits of the market economy.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39634, 'the blind leading the blind', 'used to describe a situation where a person who knows nothing is getting advice and help from another person who knows almost nothing', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39635, 'the boot/shoe is on the other foot', 'the situation is now the opposite of what it was, especially because someone who was weak now has power', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39636, 'the bottom drops/falls out of the market', 'If the bottom drops out of the market of a product, people stop buying it:', 'The bottom has fallen out of the fur coat market.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39637, 'the bottom of the heap', 'People who are at the bottom of the heap are poor and unsuccessful and have the lowest position in society.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39638, 'the bowels of something', 'the parts of something that are furthest away from the outside:', 'The fire started deep in the bowels of the ship.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39639, 'the boy/girl next door', 'used to describe someone who is completely ordinary, not rich, famous, etc.:', 'We couldn''t believe it when he got a record deal. To us, he was just the boy next door.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39640, 'the boys in blue', 'a humorous name for the police', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39641, 'the brunt of something', 'the worst problems caused by something:', 'He claimed that the middle class would bear the brunt of the tax increase.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39642, 'the buck stops here', 'said by someone who is responsible for making decisions and who will be blamed if things go wrong', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39643, 'the burden of proof', 'the responsibility for proving something', NULL, 'idiom', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39644, 'the calm before the storm', 'a quiet or peaceful period before a period during which there is great activity, argument, or difficulty:', 'I like to get everything done before the guests arrive and relax for a moment in the calm before the storm.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39645, 'the cards are stacked against someone', 'someone is not likely to succeed, esp. because the person is not being given a fair chance:', 'We tried hard to win, but the cards were stacked against us.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39646, 'the center of attention', 'someone whom everyone else notices or watches:', 'He likes being the center of attention.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39647, 'the change (of life)', 'old-fashioned for the 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39648, 'the cherry on (top of) the cake', 'something that makes something that is already good even better, or perfect:', 'For his career, the Olympic Games would be the cherry on the cake.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39649, 'the chill wind of something', 'the problems caused by something:', 'Many more businesses are feeling the chill wind of the recession.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39650, 'the chosen few', 'a small group of people who are treated better than other people, often when they do not deserve it:', 'There''s a staff canteen for everyone and there''s a smarter restaurant for the chosen few.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39651, 'the coast is clear', 'it is safe to do something or go somewhere because no one is watching or listening who would prevent you or catch you:', 'You can come out now, the coast is clear.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39652, 'the common man', 'ordinary people:', 'How can anyone so privileged have any understanding of the common man?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39653, 'the common touch', 'the ability of an important or rich person to communicate well with and understand ordinary people:', 'It was always said of the Princess that she had the common touch and that was why she was so well loved by the people.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39654, 'the company someone keeps', 'the influence of the people that someone spends time with:', '"Where does he pick up words like that?" "It''s the company he keeps."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39655, 'the corridors of power', 'the higher levels of government where the most important decisions are made', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39656, 'the cradle of something', 'the place where something started:', 'Fossil records indicate that Africa was the cradle of early human evolution.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39657, 'the cream of something', 'the best of a particular group of things or people:', 'The cream of this year''s graduates have gone abroad for jobs.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39658, 'the cream of the crop', 'the best of a group of similar things or people:', 'The medical school''s graduates are considered to be the cream of the crop and can get jobs wherever they want to.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39659, 'the cupboard is bare', 'used to say that there is no food in a house or that there is no money, etc. available:', 'I''d like to help you out, Paul, but I''m afraid the cupboard is bare.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39660, 'the curtain falls on something', 'When the curtain falls on a period of time, it ends:', 'Although the curtain has now fallen on the 20th century, many of its values still remain.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39661, 'the customer is always right', 'said to emphasize that in business, it is very important not to disagree with a customer or make them angry', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39662, 'the cut of someone''''s jib', 'the typical way that someone behaves:', 'If they like the cut of your jib, they will forgive you the odd lapse.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39663, 'the daily round', 'the tasks you have to do every day:', 'I get exhausted just by the daily round.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39664, 'the damage is done', 'said to mean that it is too late to improve a bad situation:', 'I didn''t even know I''d offended her until Colin told me and then it was too late - the damage was done.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39665, 'the darkest hour is just before the dawn', 'things often seem at their worst just before they get better', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39666, 'the darnedest thing', 'used to refer to something that is very surprising:', 'It''s the darnedest thing I ever heard.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39667, 'the days/week(s)/year(s) to come', 'the following or next days/week(s)/year(s):', 'What are your plans for the year to come (= next year)?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39668, 'the demon alcohol', 'alcohol and its unpleasant effects', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39669, 'the demon drink', 'alcohol and its unpleasant effects', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39670, 'the deserving poor', 'people who are poor but have good qualities and are not responsible for having little money', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39671, 'the devil finds work for idle hands', 'said to show that you believe people who have nothing to do are more likely to get into trouble or commit a crime', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39672, 'the devil to pay', 'a lot of trouble, difficulty, punishment, anger, etc.:', 'If he catches you going through his drawers there''ll be the devil to pay!', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39673, 'the devil''''s own', 'extremely difficult or bad:', 'We had the devil''s own job/time finding the place!', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39674, 'the die is cast', 'said when a situation is certain to develop in a particular way because decisions have been taken that cannot be changed:', 'From the moment the negotiations failed, the die was cast and war was inevitable.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39675, 'the dim and distant past', 'a time in the past that is not clearly remembered:', 'I used to enjoy dancing, back in the dim and distant past.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39676, 'the dizzy heights of something', 'a very important position:', 'Do you think Tess will reach the dizzy heights of Senior Editor before she''s 30?', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39677, 'the dog''''s bollocks', 'something or someone that you think is extremely good', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39678, 'the done thing', 'what you are expected to do in a social situation:', 'Don''t forget to shake hands - it''s the done thing, you know.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39679, 'the dregs of society/humanity', 'a group of people in society who you consider to be immoral and of no value:', 'People tend to regard drug addicts as the dregs of society.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39680, 'the dust settles', 'If the dust settles after an argument or big change, the situation becomes calmer:', 'We thought we''d let the dust settle before discussing the other matter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39681, 'the early bird catches the worm', 'said to advise someone that they will have an advantage if they do something immediately or before anyone else does it', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39682, 'the early bird catches the worm', 'a saying that means someone will have an advantage if they do something immediately, or before other people do it:', 'This is still a nation that believes the early bird catches the worm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39683, 'the early bird gets the worm', 'the person who arrives first is the one who is successful:', 'We’ll want to be at the theater early for the best seats – the early bird gets the worm!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39684, 'the earth moved', 'If someone says the earth moved, they are joking about how good a sexual experience was.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39685, 'the earth/ground/floor opens', 'You say that you wish the earth/floor/ground would open (up) if you are so embarrassed that you want suddenly to disappear:', 'At that moment the boss walked in, and I just wanted the ground to open up and swallow me.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39686, 'the easiest thing in the world', 'extremely easy:', 'Making bread is the easiest thing in the world.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39687, 'the easy way out', 'what is easiest in a difficult situation:', 'As soon as things got difficult he took the easy way out.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39688, 'the eleventh hour', 'the last moment or almost too late:', 'We only received the signatures at the eleventh hour.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39689, 'the end justifies the means', 'said about a situation in which the final aim is so important that any way of achieving it is acceptable', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39690, 'the end of the line/road', 'the point at which it is no longer possible to continue with a process or activity:', 'We''ve struggled on for as long as we could, but now we''re at the end of the line.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39691, 'the evil eye', 'a look that someone gives other people that is believed to have the power to injure or harm them', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39692, 'the exception that proves the rule', 'something that emphasizes the general truth of a statement by disagreeing with it:', 'Most company directors are middle-aged men, but this 28-year-old woman is an exception that proves the rule.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39693, 'the face of something', 'what you can see of something or what shows:', 'Poor quality is the unacceptable face of increased productivity.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39694, 'the fact remains', 'it is still true:', 'I know you''re sorry now, but the fact remains that you hit your sister.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39695, 'the fag end of something', 'the last, and often worst, part of something:', 'We always used to go on holiday at the fag end of the holiday season.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39696, 'the fat is in the fire', 'said when something has been said or done that will cause a lot of trouble', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39697, 'the father of something', 'the man who began something or first made something important:', 'Freud was the father of psychiatry.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39698, 'the final/last straw', 'the last in a series of unpleasant events that finally makes you feel that you cannot continue to accept a bad situation:', 'Losing my job was bad enough, but being evicted was the final straw.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39699, 'the flower of something', 'the best of a particular group or type:', 'The flower of the nation''s youth were killed in the war.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39700, 'the forces of evil', 'things that have a very bad influence or effect:', 'Poverty and ignorance, the bishop said, were the forces of evil in our society today.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39701, 'the frontiers of something', 'the limits of what is known or what has been done before in an area of knowledge or an activity:', 'the frontiers of science and technology', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39702, 'the fur flies', 'If the fur flies, people have a bad argument:', 'The fur was really flying during that meeting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39703, 'the game is up', 'used to tell someone that you know what their secret activities or plans are and that these cannot continue:', 'Okay, you two, the game''s up! Give me the cigarettes - this time I''m telling your parents.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39704, 'the games (that) people play', 'the ways in which people behave in order to get an advantage:', 'Not telling the whole truth is one of the games that people play.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39705, 'the genuine article', 'a good and real example of a particular thing:', 'Those cowboy boots sure look like the genuine article.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39706, 'the gift of gab', 'the ability to speak easily and confidently in a way that makes people want to listen to you and believe you:', 'She''s got the gift of gab - she should work in sales and marketing.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39707, 'the gift of the gab', 'the ability to speak easily and confidently in a way that makes people want to listen to you and believe you:', 'She''s got the gift of the gab - she should work in sales and marketing.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39708, 'the glass is half empty', 'used to refer to an attitude of always thinking about the bad things in a situation rather than the good ones:', 'A pessimist says the glass is half empty but an optimist says that it is half full.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39709, 'the glass is half full', 'used to refer to an attitude of always thinking about the good things in a situation rather than the bad ones:', 'Align yourself with people who think the glass is half full.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39710, 'the good old days', 'If you talk about the good old days, you mean a time in the past when you believe life was better:', 'I wish my grandma would stop going on about the good old days.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39711, 'the gory details', 'the interesting and usually personal pieces of information about a person or event:', 'Come on, I want to know all the gory details about your date with Jon.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39712, 'the grand old man of something', 'a man who has been involved in a particular activity for a long time and is known and respected by a lot of people:', 'He''s been called the grand old man of Latin American literature.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39713, 'the grandaddy of something', 'the biggest, most important, or most powerful event or person of their type:', '"Modern Times" is a classic comedy starring Charlie Chaplin, the grandaddy of comic film actors.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39714, 'the grass is (always) greener (on the other side)', 'something that you say that means that other people always seem to be in a better situation than you, although they may not be:', 'I sometimes think I''d be happier teaching in Spain. Oh well, the grass is always greener on the other side!', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39715, 'the great and the good', 'important people:', 'The great and the good are calling on the government to support the arts.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39716, 'the groves of academe', 'universities considered as a whole:', 'It''s yet another novel set in the groves of academe.', 'idiom', NULL, NULL, 'literary, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39717, 'the hair of the dog (that bit you)', 'an alcoholic drink taken as a cure the morning after an occasion when you have drunk too much alcohol', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39718, 'the hand that rocks the cradle rules the world', 'said to emphasize that women have a strong influence on events through their children', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39719, 'the happy day', 'a marriage:', 'So when''s the happy day then?', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39720, 'the happy event', 'the birth of a child', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39721, 'the hard way', 'a way of doing something that makes it more difficult than it needs to be:', 'She always does things the hard way.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39722, 'the hard way', 'If you learn something the hard way, you learn from unpleasant experiences rather than by being taught:', 'If she won''t listen, she''ll have to learn/find out the hard way.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39723, 'the heat is on', 'If you say the heat is on, you mean that a time of great activity and/or pressure has begun:', 'With only months to go before the deadline, the heat is on.', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39724, 'the heavens open', 'If the heavens open, it suddenly starts to rain a lot:', 'Just as we got to the park, the heavens opened.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39725, 'the hell out of', 'very much:', 'You scared the hell out of me!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39726, 'the hell someone is/does, etc.', 'used to tell someone that you do not believe what they have said or that you will not allow them to do what they want:', '"I don''t need your advice, Gene, I know what''s good for me." "The hell you do!"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39727, 'the here and now', 'the present time:', 'Most people can''t be bothered thinking about their retirement - they''re too busy concentrating on the here and now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39728, 'the highways and byways', 'the roads and paths of a place:', 'They travelled the highways and byways of Britain.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39729, 'the icing on the cake', 'something that makes a good situation even better:', 'I was just content to see my daughter in such a stable relationship but a grandchild, that really was the icing on the cake.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39730, 'the ink is not dry/still wet', 'You say that the ink is not dry/still wet on a document if it has just been written or produced:', 'The ink was barely dry on the peace agreement when fighting broke out again.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39731, 'the jewel in the crown', 'the best or most valuable part of something', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39732, 'the job/matter at hand', 'the job or matter that is important at the present moment:', 'Could you just concentrate on the job at hand?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39733, 'the job/matter in hand', 'the job or matter that is important at the present moment:', 'Could you just concentrate on the job in hand?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39734, 'the joke is on someone', 'If you say that the joke is on a particular person, you mean that that person has tried to make someone else look silly but has made himself or herself look silly instead.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39735, 'the jury is (still) out', 'If the jury is (still) out on a subject, people do not yet know the answer or have not yet decided if it is good or bad:', 'The jury''s still out on the safety of irradiated food.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39736, 'key something to someone/something', 'to arrange or plan something so that it is suitable for a particular person or situation:', 'The books are keyed to the interests of very young children.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39737, 'the kiss of death (for something)', 'something that will cause something else to fail:', 'The show’s bad ratings were the kiss of death for his acting career.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39738, 'the kiss of life', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39739, 'the knives are out', 'used to refer to a situation when people are being unpleasant about someone, or trying to harm someone:', 'The knives are out for the former president.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39740, 'the knock at/on the door', 'an occasion when police or soldiers come to take you away from your home:', 'During the dictatorship people had come to fear the knock at the door in the middle of the night.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39741, 'the lads', 'used to refer to the group of men that a young man spends time with socially, especially those who he drinks alcohol with or plays sport with:', 'I''m having a night out with the lads.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39742, 'the land of the midnight sun', 'the part of Europe inside the Arctic Circle where the sun is in the sky very late at night in the summer', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39743, 'the last but one', 'the one before the final one:', 'I''m almost finished - this is the last but one box to empty.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39744, 'the last someone heard/saw of someone/something', 'the last time someone heard anything about someone or something or the last time someone saw him, her, or it:', 'Then he went to Boston, and that was the last I saw of him.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39745, 'the last straw', 'the latest problem in a series of problems, that makes a situation impossible to accept:', 'The last straw was when the company fired most of the managers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39746, 'the last thing you want, need, etc.', 'something that you certainly do not want, need, etc.:', 'Go home? That''s the last thing I want to do!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39747, 'the last word in something', 'the best or most modern example of something:', 'In the 1990s these shoes were considered the last word in style.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39748, 'the law is an ass', 'the legal system or a particular law is wrong or not good enough, and should be changed:', 'If that is against the law, then the law is an ass.', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39749, 'the law of averages', 'the idea that over a period of time a particular thing will happen because it is just as likely to happen as the other possible events', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39750, 'the law of the jungle', 'the idea that people who care only about themselves will be most likely to succeed in a society or organization:', 'We hope for a world where the rule of law, not the law of the jungle, governs the conduct of nations.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39751, 'the least someone can do', 'something someone should do:', '"Do I have to go and say ''hi'' to him?" "Yes – he''s been very nice to you, so it''s the least you can do."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39752, 'the least someone can/could do', 'something someone should do:', 'I think the least you could do is offer to help.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39753, 'the length and breadth of somewhere', 'If you travel the length and breadth of a place, you go to every part of it:', 'She travelled the length and breadth of Ireland looking for her missing brother.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39754, 'the lesser of two evils', 'the less unpleasant of two choices, neither of which is good:', 'But allowing a criminal to go free is perhaps the lesser of two evils if the alternative is imprisoning an innocent person.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39755, 'the lie of the land', 'the shape or height of the land', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39756, 'the life and soul of the party', 'someone who is energetic and funny and at the centre of activity during social occasions', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39757, 'the light of your life', 'the person you love most', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39758, 'the likes of someone/something', 'someone or something that is equal to or as important as the person or thing being mentioned:', 'We haven’t seen the likes of Muhammad Ali since he retired.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39759, 'the lion''''s den', 'a dangerous or threatening place or situation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39760, 'the lion''''s share', 'the largest part or most of something:', 'Reputable charities spend the lion''s share of donations on aid and a tiny fraction on administration.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39761, 'the lion’s share of something', 'the largest part of something:', 'She didn’t do much, but she got the lion’s share of the attention from the teachers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39762, 'the long and the short of it', 'said when you want to explain the general situation without giving details:', 'The long and the short of it is that they are willing to start the work in January.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39763, 'the long arm of the law', 'the police:', 'You can''t escape the long arm of the law (= the police will catch you if you have done something illegal).', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39764, 'the long ball game', 'a way of playing football that involves sending a series of long high passes towards a tall or very fast forward, rather than passing the ball along the ground to the feet of another player', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39765, 'the low man on the totem pole', 'someone who has the least important position in an organization:', 'He started as the low man on the totem pole and worked his way up to be manager.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39766, 'the lower orders', 'the poorest social groups in society', NULL, 'idiom', NULL, NULL, 'old-fashioned, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39767, 'the lowest of the low', 'people who have no moral standards and no personal qualities', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39768, 'the lull before the storm', 'a time that seems quiet but will very soon be followed by something unpleasant happening:', 'Things seem quiet in the office right now, but this is just the lull before the storm.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39769, 'the lunatic fringe', 'people who have very strong opinions that are outside the usual range', NULL, 'idiom', NULL, NULL, 'disapproving, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39770, 'the man in the moon', '(in children''''s stories) the human face that you can imagine you see when you look at the moon', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39771, 'the man in the street', 'a man or men who think like most other people:', 'To win the election she needs to understand what the man in the street wants.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39772, 'the man/woman in someone''''s life', 'your romantic/sexual partner:', 'Who''s the new man in your life, eh?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39773, 'the man/woman in the street', 'an ordinary, average person whose opinions are considered to represent most people:', 'To win the election he needs to appeal to the typical man in the street.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39774, 'the man/woman on the Clapham omnibus', 'an imaginary person whose opinions or ideas are considered to be typical of those of ordinary British people:', 'The man on the Clapham omnibus probably knows nothing about Rwanda.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39775, 'the man/woman on the street', 'an ordinary, average person whose opinions are considered to represent most people:', 'To win the election he needs to appeal to the typical man on the street.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39776, 'the matter at hand', 'the subject or situation being considered:', 'Do these figures have any bearing on the matter at hand?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39777, 'the matter in hand', 'the subject or situation being considered:', 'Do these figures have any bearing on the matter in hand?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39778, 'the milk of human kindness', 'good, kind qualities:', 'She''s full of the milk of human kindness.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39779, 'the minute (that)', 'at the exact or first moment when:', 'The minute I saw him, I knew something was wrong.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39780, 'the mists of time', 'used to show that something happened a very long time ago and is difficult to remember clearly:', 'The precise details of what happened have been lost in the mists of time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39781, 'the moment of truth', 'an occasion when something important happens that tests someone or something and that will have an effect on the future:', 'Lift-off is always the moment of truth for a new rocket.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39782, 'the moon on a stick', 'everything that you could possibly want, including things that are difficult or impossible to get:', 'What more do you want, the moon on a stick?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39783, 'the more something happens the less another thing happens', 'as one thing happens repeatedly, another thing happens less or becomes less likely:', 'The more he insisted he was innocent, the less they seemed to believe him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39784, 'the more something happens the more another thing happens', 'as one thing happens repeatedly, another thing happens more or becomes more likely:', 'The more he talked, the more I liked him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39785, 'the more the merrier', 'used to say an occasion will be more enjoyable if a lot of people are there:', '"Do you mind if I bring a couple of friends to your party?" "Not at all - the more the merrier!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39786, 'the mother of all something', 'an extreme example of something:', 'We got caught in the mother of all storms.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39787, 'the naked eye', 'If something can be seen with the naked eye, it can be seen without the help of an instrument:', 'This organism is too small to be seen with the naked eye.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39788, 'the name of the game', 'the most important part of an activity, or the quality that you most need for that activity:', 'People say that in politics the name of the game is making the right friends.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39789, 'the nature of things', 'the usual and expected characteristics of life:', 'There are problems in every relationship – it’s in the nature of things.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39790, 'the new kid on the block', 'someone who is new in a place or organization and has many things to learn about it:', 'Realizing I was the new kid on the block in this job, I was determined to prove myself.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39791, 'the next best thing', 'the thing that is best, if you cannot have or do the thing you really want:', 'I really wanted to work in television but I ended up in radio, which is the next best thing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39792, 'the next but one', 'the one after the next one:', 'In the next but one paragraph, he states that his case does not raise any difficult questions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39793, 'the next thing I knew', 'used to talk about part of a story that happens in a sudden and surprising way:', 'A car came speeding around the corner, and the next thing I knew I was lying on the ground.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39794, 'the nineteenth hole', 'the bar at a golf course where people go to have drinks and talk after they have finished playing', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39795, 'the nuts and bolts', 'the practical facts about a particular thing, rather than theories or ideas about it:', 'When it came to the nuts and bolts of running a business, he was clearly unable to cope.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39796, 'the nuts and bolts of something', 'the basic facts or practical things that need to be understood or done:', 'He was a genius on paper, but when it came to the nuts and bolts of running a business he was a failure.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39797, 'the odd one out', 'a person or thing that is different from or kept apart from others that form a group or set:', 'Guess which number of the following sequence is the odd one out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39798, 'the old days', 'times in the past:', 'In the old days we only had four or five TV channels.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39799, 'the old-boy network', 'the way in which men who have been to the same expensive school or university help each other to find good jobs:', 'The old-boy network still operates in some City banks.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39800, 'the oldest profession (in the world)', 'prostitution (= the job of having sex for money)', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39801, 'the oldest trick in the book', 'a way of tricking someone that is still effective although it has been used a lot before:', 'It was the oldest trick in the book - one man distracted me while another stole my wallet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39802, 'the one about', 'the joke about:', 'Have you heard the one about the Italian, the American and the Australian?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39803, 'the one percent', 'the richest one percent of people, who are said to have most of the money, property, and power in society :', 'He promised to govern in the interests of all, and not just the one percent.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39804, 'the operative word', 'the most important word in a phrase, which explains the truth of a situation:', 'He was a painter - "was" being the operative word, since he died last week.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39805, 'the order of the day', 'in a parliament or in formal meetings, the list of matters to be discussed on a particular day', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39806, 'the order of the day', 'something that is very common or important:', 'On these TV channels, reality shows and repeats are becoming the order of the day.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39807, 'the other day', 'recently:', 'I saw him the other day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39808, 'the other side of the coin', 'a different way of considering a situation, making it seem either better or worse than it did originally:', 'I like having a white car, but the other side of the coin is that it soon gets dirty.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39809, 'the other way around', 'the opposite way or in the opposite order:', 'I should be telling you what to do, not the other way around.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39810, 'the outside world', 'things that are common in normal life but are not part of your experience:', 'After 20 years in prison, he had no idea about the outside world.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39811, 'the path of least resistance', 'the easiest way to continue:', 'I took the path of least resistance and agreed with the others.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39812, 'the patience of Job', 'the ability to remain patient and to do what you think you should do despite having many problems', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39813, 'the patter(ing) of tiny feet', 'something you say that means that someone is going to have a baby:', 'Are you telling me we''re going to be hearing the patter of tiny feet?', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39814, 'the pen is mightier than the sword', 'said to emphasize that thinking and writing have more influence on people and events than the use of force or violence', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39815, 'the penny drops', 'If the penny drops, you suddenly understand something:', 'She looked confused for a moment, then suddenly the penny dropped.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39816, 'the perfect hat trick', 'an occasion when a football player scores one goal with their left foot, one goal with their right foot, and one goal with their head', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39817, 'the pick of something', 'the best of a group of people or things:', 'The pick of this year''s three-year-old racehorses is Galileo.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39818, 'the picture of something', 'a very good example of a particular condition or attitude:', 'He’s the picture of health.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39819, 'the pits', 'infmla very bad or unpleasant thing:', 'When I first came to the college, this place was the pits, but it''s improved a lot.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39820, 'the plot thickens', 'said when a situation suddenly becomes more complicated or mysterious:', '"Now there are two men calling her up all the time." "The plot thickens!"', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39821, 'the polluter pays principle', 'the idea that the person or organization that causes pollution should pay to put right the damage that it causes', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39822, 'the pot calling the kettle black', 'something you say that means people should not criticize someone else for a fault that they have themselves:', 'Elliott accused me of being selfish. Talk about the pot calling the kettle black!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39823, 'the power behind the throne', 'someone who does not have an official position in a government or organization but who secretly controls it', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39824, 'the powers that be', 'important people who have authority over others:', 'It''s up to the powers that be to decide what should be done next.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39825, 'the primrose path', 'If you lead someone down the primrose path, you encourage that person to live an easy life that is full of pleasure but bad for them:', 'Unable to enjoy his newly acquired wealth, he felt he was being led down the primrose path to destruction.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39826, 'the proof of the pudding (is in the eating)', 'said to mean that you can only judge the quality of something after you have tried, used, or experienced it', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39827, 'the purse strings', 'the spending of money by a family, company, or country:', 'A recent survey showed that in 53 percent of families, women hold (= control) the purse strings.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39828, 'the race/gender, etc. card', 'a claim of unfair treatment based on race, sex, etc., when this is used as a way for someone to get an advantage:', 'He claims that talk of sexism is playing the gender card, attempting to distract from the fact that she did not do well in the debate.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39829, 'the rest is history', 'everything that happened since then is well known:', 'The Beatles had their first hit record in 1962 and the rest is history.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39830, 'the right stuff', 'the qualities needed to do or be something, especially something that most people would find difficult:', 'He has shown he has the right stuff to be a leader.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39831, 'the right/wrong/other way around', 'facing in a particular direction, or placed in a particular position:', 'She insists on turning all the upside-down cups in the cupboard the right way around.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39832, 'the rights and wrongs', 'the details of who or what is fair or unfair:', 'I don''t care about the rights and wrongs of the matter - I just want you both to stop arguing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39833, 'the road to hell is paved with good intentions', 'said to emphasize that you must not simply intend to behave well but you must act according to your intentions, because you will have problems or be punished if you do not', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39834, 'the ropes', 'the practices or rules you need to know in order to get something done:', 'I spent a day in our warehouse showing the new guy the ropes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39835, 'the rot sets in', '(of a situation) to begin to go wrong:', 'The rot set in when his parents divorced and he started taking drugs.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39836, 'the run of something', 'the freedom to use something:', 'While she''s away, I''ve got the run of her house.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39837, 'the same old thing', 'something that has not changed, with the result that it seems boring:', 'You get tired of eating the same old thing for breakfast.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39838, 'the same/that goes for someone/something', 'what I have said about one person or thing is also true for or relates to another person or thing:', 'You really need to take more care with your appearance, Chris - and the same goes for the rest of you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39839, 'the sands of time are running out', 'used to say that there is not much time left to do something', NULL, 'idiom', NULL, NULL, 'literary, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39840, 'the sap is rising', 'an expression used to mean that people start to have more energy and feel more interested in love and sex, for example in spring', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39841, 'the scales fall from someone''''s eyes', 'If the scales fall from your eyes, you suddenly know and understand the truth.', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39842, 'the scheme of things', 'the way things are organized or happen in a particular situation, or the way someone wants them to be organized:', 'I was disappointed not to get the job, but it''s not that important in the great/grand scheme of things (= when all things are considered).', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39843, 'the school/university of life', 'all the bad and good experiences that you have and that you learn from; used especially to talk about someone who is wise but not highly educated:', 'I learned my skills at the university of life.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39844, 'the scum of the earth', 'the worst type of people that can be imagined:', 'These men are the scum of the earth.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39845, 'the season of goodwill', 'the period around Christmas', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39846, 'the second (that)', 'as soon as:', 'The second I saw him, I knew he was going to be a star.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39847, 'the shape of things to come', 'the form or style that is likely to develop or be popular in the future:', 'I hope the fashions pictured in this magazine are not the shape of things to come.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39848, 'the shirt off someone''''s back', 'the last thing that someone has left:', 'He''s the kind of man who''d give you the shirt off his back.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39849, 'the shit out of someone/something', 'used to emphasize the degree of force of an action that you are describing:', 'His dad would beat/knock/kick the shit out of him if he disobeyed.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39850, 'the show must go on', 'said to encourage someone to continue with what they are doing, even if they are experiencing difficulties', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39851, 'the silent treatment', 'the act of not speaking to someone, or speaking to them very little, because you are angry or upset about something they have done:', 'The man and his wife were having some problems at home and were giving each other the silent treatment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39852, 'the sky is the limit', 'there is no limit:', 'Houseboats can be inexpensive, but on prices for bigger boats the sky is the limit .', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39853, 'the sky''''s the limit', 'there is no limit:', 'The sky''s the limit to what you can win in our competition.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39854, 'the slice/share of the cake', 'the amount of money, goods, etc., available:', 'Everyone should have a fair slice of the cake.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39855, 'the spirit is willing, but the flesh is weak', 'said when you would like to do something, but you do not have the time, skills, or energy necessary to do it', NULL, 'idiom', NULL, NULL, 'humorous, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39856, 'the squeaky wheel gets the grease', 'said to emphasize that attention is paid to those problems that are made most noticeable', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39857, 'the staff of life', 'bread, considered as one of the most important foods we eat', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39858, 'the stars align', 'used to say that a situation is very good or lucky, or becomes completely right in order for something to happen:', 'The stars aligned when they met and fell in love.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39859, 'the straight and narrow', 'If you keep on the straight and narrow, you behave in a way that is honest and moral:', 'My grandmother was strict and kept me on the straight and narrow.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39860, 'the straight and narrow (path)', 'a course of behavior that is correct:', 'Ray runs an after-school program meant to keep young people on the straight and narrow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39861, 'the streets are paved with gold', 'said about a place where it is easy to get rich, or where people imagine that it is:', 'Immigrant families soon discovered that the streets of New York were not paved with gold.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39862, 'the stuff of something', 'something that a particular type of thing is made of or based on:', 'Her appetite for shopping became the stuff of legend.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39863, 'the sun sets on something', 'If the sun sets on something, it ends:', 'It used to be said that Britain ruled an empire on which the sun would never set.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39864, 'the tail wagging the dog', 'a situation in which a large group has to do something to satisfy a small group', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39865, 'the thin end of the wedge', 'the beginning of a harmful development:', 'Identity cards for students could be the thin end of the wedge - soon everyone might have to carry identification.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39866, 'the thing is', 'used to introduce an explanation or an excuse:', 'The thing is, my parents like me to be home by ten o''clock.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39867, 'the thing is', 'used to emphasize the importance of what you are saying:', 'The thing is to keep a good distance from the car in front of you, when you''re driving in snow.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39868, 'the thing to do', 'what you are expected to do in a social situation:', 'Don''t forget to shake hands - it''s the thing to do, you know.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39869, 'the thinking woman''''s/man''''s crumpet', 'a way of describing a man or a woman who is popular with the opposite sex because they are intelligent as well as being physically attractive:', 'Paxman is surely the ultimate thinking woman''s crumpet.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39870, 'the third degree', 'asking serious questions and/or giving someone rough treatment to get information:', 'I got the third degree when I got home last night.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39871, 'the thought crosses someone''''s mind', 'If the thought of (doing) something crosses someone''''s mind, they think about it for a short time:', 'The thought had crossed my mind that I might need some help with the project.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39872, 'the three Rs', 'used to refer to the basic areas of education: reading, writing, and mathematics', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39873, 'the thrill of the chase', 'the excitement that you feel when you are trying to find something or achieve something difficult:', 'He craved power over others, not so much for its own sake as for the thrill of the chase.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39874, 'the time is ripe', 'If you say that the time is ripe, you mean that it is a suitable point for a particular activity:', 'I''m waiting till the time is ripe before I tell my parents that I failed my two exams.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39875, 'the time of your life', 'an extremely enjoyable experience:', 'We had the time of our lives at the party.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39876, 'the tip of the iceberg', 'a small, noticeable part of a problem, the total size of which is really much greater:', 'These small local protests are just the tip of the iceberg.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39877, 'the tip of the spear', 'a person or group of people that is the first to do something considered difficult or dangerous, especially a group of soldiers, etc. who are the first to enter a battle area:', 'Aircraft carriers and their battle groups have served as the leading edge of the US military - "the tip of the spear," as the admirals like to say.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39878, 'the tip of the spear', 'the leading position that someone or a group of people is in when there is a possibility of something difficult or dangerous happening :', 'Feeding troops at the tip of the spear remains one of the most difficult tasks for the US war machine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39879, 'the toast of something', 'The toast of a particular place is a person who is very much admired there for something they have recently done:', 'Not so long ago Diana was a little-known actress playing in a provincial theatre - these days she''s the toast of New York/the town.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39880, 'the trooping of the colour', 'a ceremony in which a military flag is carried in public with the soldiers that it represents marching behind it:', 'We watched the trooping of the colour live from Horse Guards Parade.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39881, 'the trouble with someone/something', 'the problem with someone or something:', 'The trouble with this place is they don’t care about the people who work here.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39882, 'the turn of the century', 'the time when a particular century ends and another begins:', 'My great-grandfather was born at the turn of the last century.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39883, 'the unacceptable face of something', 'the bad side to a particular system or set of beliefs:', 'The paper showed a picture of homeless people sleeping on the streets with the caption underneath "the unacceptable face of capitalism".', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39884, 'the undeserving poor', 'people who are poor because of their own actions and should not get sympathy from other people:', 'The poor fell into two categories: the deserving and the undeserving poor, depending on whether or not they were regarded as victims of circumstances or were held responsible for their present miserable condition.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39885, 'the usual suspects', 'the people or things you would expect to be present somewhere or doing a particular thing:', 'His heart attack was caused by the usual suspects: poor diet, stress, and smoking.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39886, 'the way things are', 'given the situation as it is now:', 'The way things stand, I cannot continue to work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39887, 'the way to a man''''s heart is through his stomach', 'said to mean that a woman can make a man love her by cooking him good meals', NULL, 'idiom', NULL, NULL, 'humorous, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39888, 'the ways of the world', 'the types of behaviour and ways of doing things that are acceptable:', 'He''s very young and still has a lot to learn about the ways of the world.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39889, 'the week/month/year before last', 'during the week/month/year before the previous one:', 'We had lunch together the week before last.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39890, 'the whole bit', 'the whole of something, including everything that is related to it:', 'He''s into jogging, squash, aerobics, the whole exercise bit.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39891, 'the whole enchilada', 'everything that could possibly be included:', 'Let''s throw a party - birthday cake, balloons, the whole enchilada.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39892, 'the whole nine yards', 'everything you can possibly want, have, or do in a particular situation :', 'When I was little, my family always had lots of pets - dogs, cats, hamsters, fish, rabbits - the whole nine yards.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39893, 'the whole street', 'everyone living along a particular road:', 'Keep your voice down, we don''t want the whole street to hear us!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39894, 'the woman in the street', 'a woman or women who think like most other people:', 'What does the woman in the street want from a fashion magazine?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39895, 'the world and his wife', 'a great many people, especially in a particular place at a particular time:', 'It''s going to be quite a party - the world and his wife will be there.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39896, 'the world is someone''''s oyster', 'If the world is your oyster, you can do what you want or go where you want:', 'You''re young and healthy and you have no commitments - the world is your oyster.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39897, 'the worm turns', 'used to describe when a person or group of people who have been treated badly for a long time suddenly become forceful and stop accepting a difficult situation:', 'It seems the worm has turned - after years of silence local people are beginning to protest about waste emissions from the factory.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39898, 'the worse for drink', 'drunk:', 'By the time I got to the party Patrick was already the worse for drink.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39899, 'the worse for wear', 'tired or in poor condition because of a lot of work or use:', 'After a month of journeying over rough roads, the drivers and their trucks were looking the worse for wear.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39900, 'the writing is on the wall', 'said to mean that there are clear signs that something will fail or no longer exist', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39901, 'the wrong/other side of the tracks', 'a part of a town that is considered poor and dangerous:', 'Her boyfriend came from the wrong side of the tracks.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39902, 'the year dot', 'a very long time ago:', 'I''ve known Peter since the year dot.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39903, 'the/a devil of a something', 'an extremely difficult or serious type of something:', 'a devil of a mess/problem
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39904, 'the/a glare of something', 'an occasion when something receives a very large amount of public attention:', 'The actor''s wedding took place in the full glare of publicity/the media.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39905, 'the/sb''''s dark side', 'the parts of a person, a group, an activity, etc. that are unpleasant, evil, or harmful:', 'She sings about the dark side to love.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39906, 'the/your average bear', 'a person who is not unusual in any way, for example not especially intelligent, interesting, etc.:', 'I like to think I''m smarter than the average bear.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39907, 'them and us', 'used when describing disagreements or differences, especially between different social groups:', 'If parents are encouraged to be involved in school, there is less chance of a them-and-us situation developing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39908, 'then again', 'used when you have had a new thought that is different from or the opposite of what you have just said:', 'I like to travel but, then again, I''m very fond of my home.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39909, 'then and there', 'immediately:', 'I suggested he call his mother and he did it there and then.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39910, 'there and back', 'adding together the distance or time to and from a particular place:', 'It was 20 miles there and back.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39911, 'there are plenty more fish in the sea', 'used to tell someone whose relationship has ended that there are many other people that they could have a relationship with:', 'Don''t cry over Pierre - there are plenty more fish in the sea!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39912, 'there are plenty of fish in the sea', 'used to tell someone whose relationship has ended that there are many other people that they could have a relationship with:', 'Don''t cry over Pierre - there are plenty of fish in the sea!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39913, 'there but for the grace of God (go I)', 'said when something bad that has happened to someone else could have happened to you', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39914, 'there is a God!', 'said in a bad situation when something good happens unexpectedly', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39915, 'there is no holding someone (back)', 'If there is no holding someone (back), they do something eagerly and cannot be stopped.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39916, 'there you go', 'used when giving something to someone, usually after a request for the thing, such as giving someone goods that they have bought', NULL, 'idiom', 'A2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39917, 'there you go', 'used to express the fact that you cannot change a situation so you must accept it:', 'We didn''t win the competition, but there you go - we can always try again next year.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39918, 'there you go', 'used to mean "I told you so":', 'There you go - I knew you''d forget if you didn''t write it down.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39919, 'there you go again', 'a way of emphasizing that an action is often repeated:', 'There they go again, making trouble.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39920, 'there''''ll be hell to pay', 'something you say that means someone will be very angry if something happens:', 'There''ll be hell to pay if she doesn''t get the money in time.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39921, 'there''''s a good boy/girl/dog!', 'used to show approval or encouragement:', 'Tie your shoelaces, there''s a good girl!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39922, 'there''''s a lot of it about', 'said to mean that the stated thing is very common', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39923, 'there''''s a method to your madness', 'you have a good reason for what you are doing, although you seem to be behaving strangely', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39924, 'there''''s a time and a place (for everything)', 'said when someone is behaving in a way that you do not think is suitable for the situation they are in', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39925, 'there''''s little to be said for something', 'said to mean that something has disadvantages:', 'Personally, I think there''s little to be said for such a policy.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39926, 'there''''s many a slip twixt cup and lip', 'said to emphasize that many bad things might happen before something is finished', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39927, 'there''''s method in your madness', 'you have a good reason for what you are doing, although you seem to be behaving strangely', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39928, 'there''''s no accounting for taste', 'said when it is difficult to explain why different people like different things, especially things that you do not like:', '"I love working at weekends." "Well, there''s no accounting for taste!"', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39929, 'there''''s no danger of that!', 'said to mean that something certainly will not happen:', '"Bye - don''t work too hard!" "There''s no danger of that!"', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39930, 'there''''s no escaping the fact', 'used to mean that something is certain:', 'There''s no escaping the fact (that) we won''t be able to complete these orders without extra staff.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39931, 'there''''s no help for it', 'there is no other choice in this situation:', 'If you catch them stealing again, there''ll be no help for it but (= except) to call the police.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39932, 'there''''s no knowing', 'If you say there''''s no knowing, you mean it is impossible to be certain about something:', 'There''s no knowing what she''ll do if she finds out about this.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39933, 'there''''s no knowing/telling/saying', 'it is not possible to know what will happen:', 'She''s very unpredictable, so there''s no knowing how she''ll react to the news.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39934, 'there''''s no rest for the wicked', 'said when you must continue with your work or other activity although you are very tired', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39935, 'there''''s no smoke without fire', 'If unpleasant things are said about someone or something, there is probably a good reason for it:', 'She says the accusations are not true, but there''s no smoke without fire.', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39936, 'there''''s no such thing as a free lunch', 'said to emphasize that you cannot get something for nothing:', '"I get to travel with my job but the downside is I have to give talks." "Well, there''s no such thing as a free lunch."', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39937, 'there''''s no such thing/person (as)', 'used to say that something or someone does not exist:', 'I''ve told you before, sweetie, there''s no such thing as ghosts!', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39938, 'there''''s no telling', 'it is not possible to know:', 'There’s no telling how her parents will react to the news.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39939, 'there''''s no time like the present', 'said to encourage someone to take action immediately instead of waiting', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39940, 'there''''s none so deaf as those who will not hear', 'said about someone who chooses to ignore advice or will not believe what they are told', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39941, 'there''''s nothing in something', 'used for saying that something you have been told is not true:', 'I heard a rumour that she''s leaving, but apparently there''s nothing in it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39942, 'there''''s nowt so queer as folk', 'said to emphasize that people sometimes behave in a very strange way', NULL, 'idiom', NULL, NULL, 'informal, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39943, 'there''''s one law for the rich and another for the poor', 'said when a rich person has not been punished for something that a poor person would be punished for', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39944, 'there''''s safety in numbers', 'said to emphasize that being part of a group makes you less likely to be harmed', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39945, 'there''''s something in something', 'used to admit that there is some value or truth in what someone does or says, although you do not completely approve of it:', 'I don''t go along with all his theories but there''s probably something in it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39946, 'there''''s something to be said for', 'said to mean that something has advantages:', 'There''s a lot to be said for living alone.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39947, 'there, there', 'something you say to comfort someone, especially a child:', 'There, there, don''t cry.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39948, 'thereby hangs a tale', 'said to someone when what they have asked about involves a long explanation:', '"Why are you limping?" "Ah, thereby hangs a tale."', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39949, 'therein lies', 'in what has just been mentioned we see the reason or explanation for (a particular situation, quality, or problem):', 'Her book is simply a collection of memories, told without conceit or self-absorption - and therein lies its power.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39950, 'these days', 'infmlnow:', 'I used to talk to my sister every night. These days, we hardly speak to each other.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39951, 'they should worry!', 'said about or to someone who clearly has no need to worry:', 'She should worry! She hasn''t a problem in the world.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39952, 'thick and fast', 'quickly and in large numbers:', 'Distress calls were pouring in, thick and fast, from all over the area.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39953, 'thick on the ground', 'existing in large numbers:', 'Female engineers are not too thick on the ground.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39954, 'thin down', 'If you thin down, you become less fat:', 'He''s thinned down a lot since I last saw him.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39955, 'things that go bump in the night', 'used to describe anything unknown that might be frightening, especially a noise', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39956, 'think again', 'to form a new opinion about something or decide to change your decision on it, often after learning more about it:', 'When the children are misbehaving, it makes me think again about having a large family.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39957, 'think ahead', 'to think carefully about what might happen in the future, or to make plans for things you want to do in the future:', 'The new year is a natural time to think ahead and make plans for the future.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39958, 'think back', 'to remember something that happened in the past:', 'It might help you to understand Julia if you think back to when you were her age.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39959, 'think better of something', 'to decide that something is not a good idea:', 'Originally we were going to buy John''s old car, but we thought better of it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39960, 'think big', 'to have plans to be very successful or powerful:', 'You need to think big if you want to succeed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39961, 'think for yourself', 'to make your own decisions and form your own opinions, without depending on other people:', 'You can''t keep asking me all the time, Anna - you''re going to have to learn to think for yourself.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39962, 'think long and hard', 'to take the time needed to understand something before making a decision about it:', 'I thought long and hard about it, and decided that I wouldn''t have the operation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39963, 'think nothing of something', 'to consider that an activity is easy and not unusual:', 'When I was younger, I thought nothing of riding my bike 50 miles in a day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39964, 'think of something', 'to produce a new idea or plan:', 'We''ll have to think of a pretty good excuse for being late.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39965, 'think of something/someone', 'If you think of something or someone in a particular way, you have that opinion about it, him, or her:', 'I think of him as someone who will always help me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39966, 'think of something/someone', 'to have a good opinion of someone or something:', 'She thinks very highly of her boss.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39967, 'think of something/someone', 'to have a low opinion of someone or something:', 'Her parents don''t think much of her new boyfriend.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39968, 'think of/about someone/something', 'to remember or imagine someone or something:', 'I thought of you immediately when they said they wanted someone who could speak English.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39969, 'think on your feet', 'to make a quick decision or give an answer quickly:', 'I''d never heard about the company before, so I had to think on my feet.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39970, 'think outside the box', 'to think imaginatively using new ideas instead of traditional or expected ideas', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39971, 'think poorly of someone/something', 'to have a low opinion of someone or something', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39972, 'think something out', 'to consider all the possible details of something:', 'The scheme was well thought out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39973, 'think something over', 'to consider an idea or plan carefully before making a decision:', 'I''ll think it over and give you an answer next week.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39974, 'think something over/through', 'to consider something carefully:', 'They’ve made me a good offer, but I’ll have to think it over.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39975, 'think something through', 'to carefully consider the possible results of doing something:', 'I need some time to think it through - I don''t want to make any sudden decisions.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39976, 'think something up', 'to produce a new idea or plan:', 'I don''t want to go tonight but I can''t think up a good excuse.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39977, 'think the (whole) world revolves around you', 'to think you are extremely important:', 'The trouble with John is he thinks the whole world revolves around him.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39978, 'think the sun shines out (of) someone''''s arse/backside', 'to love and admire someone so much that you do not think they have any bad qualities', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39979, 'think the sun shines out (of) someone''''s ass/butt', 'to love and admire someone so much that you do not think they have any bad qualities', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39980, 'think the world of someone/something', 'to have a very high opinion of someone or something:', 'I think the world of my niece - she''s a smart, loving girl.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39981, 'think twice', 'to consider something more carefully:', 'You might want to think twice before buying an insurance policy from them.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39982, 'thirst after/for something', 'to feel very strongly that you want and need a particular thing:', 'to be thirsting for justice/truth/adventure', 'phrasal verb', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39983, 'this and that', 'various things:', '"What were you talking about?" "Oh, this and that."', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39984, 'this is the life!', 'said to mean that you are very much enjoying the situation you are in', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39985, 'this minute', 'now or a very short time ago:', 'It doesn''t have to be done (right) this minute, but it does need to be finished this week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39986, 'this side of something', 'before reaching a particular age, date, place, etc.:', 'I can''t believe she''s this side of 50.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39987, 'this vale of tears', 'This vale of tears is the world we live in, seen as sad and difficult.', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39988, 'this, our, etc. neck of the woods', 'this, our, etc. part of a particular area:', 'We don''t often see you in this neck of the woods.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39989, 'thorn in your flesh/side', 'a person or thing that repeatedly annoys you or causes you pain:', 'A relentless campaigner, he was a thorn in the government''s side for a number of years.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39990, 'thorn in your side', 'someone or something that continually causes problems for you:', 'Money problems have been a thorn in our side since the day we got married.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39991, 'those were the days', 'something you say that means life was better at the time in the past that you are talking about:', 'We were young and madly in love. Ah, those were the days!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39992, 'those whom the gods love die young', 'sometimes said when someone has died young', NULL, 'idiom', NULL, NULL, 'literary, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39993, 'thrash something out', 'to discuss a problem in detail until you reach an agreement or find a solution:', 'If we have an important decision to make, we sometimes spend a whole day thrashing it out in a meeting.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39994, 'thrilled to bits', 'extremely pleased:', 'She was thrilled to bits with her present.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39995, 'throttle (something) back/down', 'to reduce speed, or to reduce the power and speed being produced by an engine:', 'The pilot throttled back (the engines) as he came in to land.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39996, 'through and through', 'completely:', 'My mother is Irish through and through.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39997, 'through thick and thin', 'If you support or stay with someone through thick and thin, you always support or stay with them, even if there are problems or difficulties:', 'She has stuck with me through thick and thin.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39998, 'throw (someone) a curve (ball)', 'to surprise someone with something that is difficult or unpleasant to deal with:', 'Mother Nature threw us a curve ball last winter with record-breaking amounts of snow.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (39999, 'throw (something) up', 'to vomit:', 'I spent all night throwing up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40000, 'throw something up', 'to produce new problems or ideas:', 'The meeting threw up some interesting ideas.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40001, 'throw something up', 'If you throw up your job, you choose to leave it or stop doing it:', 'He''s thrown up his job and gone off to Africa to work for a children''s charity.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40002, 'throw (your) money/cash around', 'to spend money, especially in an obvious and careless way, on things that are not necessary:', 'He lost his job, but still seems to have plenty of money to throw around.', 'idiom', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40003, 'throw a (monkey) wrench in the works', 'to do something that prevents a plan or activity from succeeding:', 'The funding for the project was withdrawn so that really threw a monkey wrench in the works.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40004, 'throw a party', 'to have a party:', 'Janelle threw a party for Brad''s 18th birthday.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40005, 'throw caution to the wind/winds', 'to do something without worrying about the risk or negative results:', 'I threw caution to the wind and bought the most expensive one.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40006, 'throw cold water on something', 'to be negative about someone''''s ideas or plans:', 'You''re always throwing cold water on my suggestions.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40007, 'throw down the gauntlet', 'to invite someone to fight or compete with you:', 'A price war looks likely now that a leading supermarket has thrown down the gauntlet to its competitors.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40008, 'throw good money after bad', 'to waste money by spending more money on something you have already spent money on that is no good:', 'Trying to fix that old car would just be throwing good money after bad.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40009, 'throw in the towel', 'to stop trying to do something because you have realized that you cannot succeed:', 'Three of the original five candidates for the Democratic presidential nomination have now thrown in the towel.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40010, 'throw money at something', 'to spend a lot of money on trying to solve a problem:', 'We won''t solve this problem by throwing money at it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40011, 'throw shade', 'to criticize someone or something publicly and show that you do not respect them:', 'This isn''t the first time that the actress has thrown shade at her ex-husband.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40012, 'throw shapes', 'to dance, especially in a way that attracts attention:', 'On a Saturday night, you''ll find her throwing shapes on the dance floor.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40013, 'throw someone back on their own resources', 'to force someone to take care of himself or herself without help from others:', 'When both his parents died, the boy was thrown back on his own resources.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40014, 'throw someone for a loop', 'to completely surprise someone:', 'When she told me she was married, it really threw me for a loop.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40015, 'throw someone in jail', 'to put someone in prison:', 'They don''t throw anyone in jail for parking illegally, but they will tow your car and charge you a fine.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40016, 'throw someone off balance', 'to confuse or upset someone for a short time by saying or doing something that they are not expecting:', 'The question threw him off balance for a moment.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40017, 'throw someone over', 'to finish a relationship with someone and start one with another person:', 'She threw him over for a richer man.', 'phrasal verb', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40018, 'throw someone to the dogs', 'to allow someone to be criticized or attacked, often in order to protect yourself from being criticized or attacked:', 'I really felt as if I''d been thrown to the dogs just to save other people''s reputations.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40019, 'throw someone to the lions', 'to put someone, or allow someone to be put, into a very unpleasant or difficult situation without helping them, especially as a way of protecting yourself:', 'He accused his former colleagues of throwing him to the lions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40020, 'throw someone under the bus', 'to do something harmful to someone else in order to gain an advantage for yourself:', 'He has been accused of throwing fellow Republicans under the bus for his personal agenda.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40021, 'throw something away', 'to waste a skill or opportunity:', 'You''ve spent three years working hard in college - don''t throw it all away.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40022, 'throw something away/out', 'to get rid of something that you do not want any more:', 'So when are you going to throw away those old magazines?', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40023, 'throw something back in someone''''s face', 'to say unkind things about someone''''s behaviour in the past during an argument:', 'She threw all his failures back in his face.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40024, 'throw something in', 'If a person or business selling goods throws something in, they provide it for free when you buy something else from them:', 'When I bought my new glasses, they threw in a free pair of prescription sunglasses.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40025, 'throw something off', 'If you throw off your clothes, you take them off quickly and carelessly:', 'They threw off their clothes and jumped in the sea.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40026, 'throw something off', 'to stop suffering from a cold or other illness that is not serious:', 'I can''t seem to throw off this cold.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40027, 'throw something/someone off', 'to escape from something or someone following you:', 'They threw the police off the scent by travelling on false passports.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40028, 'throw something on', 'to put on a piece of clothing quickly:', 'I just threw on my blouse and skirt and rushed out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40029, 'throw something out', 'see 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40030, 'throw something out', 'If people in authority throw out a plan, idea, case, etc. they refuse to accept or use it:', 'The case was thrown out by the courts due to lack of evidence.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40031, 'throw someone out', 'to force someone to leave a college, school, house, or organization:', 'She was thrown out of college after she was caught using drugs.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40032, 'throw something together', 'to make something quickly without special care or preparation:', 'I had to throw dinner together at the last minute.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40033, 'throw someone together', 'If two people are thrown together, they meet each other in a way that was not planned, or events cause them to meet unexpectedly:', 'We were thrown together by chance at a conference.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40034, 'throw the baby out with the bathwater', 'to lose valuable ideas or things in your attempt to get rid of what is not wanted', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40035, 'throw the book at someone', 'to severely punish someone:', 'After the accident, the safety inspector threw the book at the company directors.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40036, 'throw up your hands in horror/despair', 'to show that you are shocked or that you disagree strongly with something:', 'They threw up their hands in horror at his suggestion.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40037, 'throw your hat into the ring', 'to announce your intention of entering a competition or election', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40038, 'throw your voice', 'to make something that is not real, such as a toy, seem to be speaking', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40039, 'throw your weight around', 'to act as if you have a lot of power or authority', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40040, 'throw yourself at someone', 'to make it very obvious to someone that you want a sexual relationship with them:', 'I don''t know what it is about John, but women just seem to throw themselves at him.', 'phrasal verb', NULL, NULL, 'informal, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40041, 'throw yourself into something', 'to do something actively and enthusiastically:', 'She''s thrown herself into this new job.', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40042, 'throw yourself into something', 'to do something enthusiastically:', 'She’s thrown herself into this new job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40043, 'throw/put someone off the scent', 'to give someone false or confusing information to prevent them from discovering something that you do not want them to know about', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40044, 'thrust something on/upon someone', 'to force someone to accept or deal with something:', 'Fatherhood had been thrust on him.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40045, 'thumb through something', 'to turn the pages of a book, magazine, or a document quickly and only read small parts of it:', '"Have you read the report?" "Well, I thumbed through it quickly while I was eating breakfast."', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40046, 'thumb your nose at someone/something', 'to show a lack of respect toward someone or something:', 'Most pedestrians thumb their noses at jaywalking laws.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40047, 'thumbs down', 'used to show disapproval of something:', 'They gave our plan the thumbs down (= they have disagreed with our plan).', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40048, 'thumbs up', 'used to show approval of something:', 'So it''s the thumbs up for Brighton''s latest nightclub.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40049, 'thus far', 'until now:', 'We haven’t had any problems thus far.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40050, 'tick along', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40051, 'tick away/by', 'If time ticks away/by, it goes past:', 'With the final seconds ticking away, Milan scored a goal.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40052, 'tick over', 'If a business, job, or system is ticking over, it continues to work but makes little progress:', 'I''ll be able to keep things ticking over in the office until you get back.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40053, 'tick over', 'If the engine of a vehicle is ticking over, the engine is operating slowly although the vehicle is not moving:', 'I''ve left the car with the engine ticking over.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40054, 'tick someone off', 'to speak severely to and criticize someone who has done something wrong:', 'I had to tick him off for being late again.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40055, 'tick someone off', 'to annoy someone:', 'It really ticks me off when she doesn''t keep her promises.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40056, 'tick something off', 'to put a mark beside an item in a list to show that you have dealt with it:', 'That''s one more action point that we can tick off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40057, 'tick something off', 'to name items in a list:', 'She ticked off six reasons for saying no.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40058, 'tickle someone''''s fancy', 'If something tickles your fancy, you like it and want to have it:', 'Does anything on the menu tickle your fancy?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40059, 'tickle the ivories', 'to play the piano:', 'He''s the piano teacher who taught my daughter to tickle the ivories.', 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40060, 'tickled pink', 'infmlvery pleased:', 'I was tickled pink to be invited.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40061, 'tide someone over (something)', 'to help someone to work or operate normally through a difficult period, usually by lending them money:', 'Can you lend me some money to tide me over till the weekend?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40062, 'tidy something away', 'to put things back in drawers, cupboards, and other places where they are kept, after you have used them:', 'The children were expected to tidy away their toys before bedtime.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40063, 'tie (something) in', 'When ideas or statements tie in, they agree or are closely connected, and if you tie them in, you make them agree or connect closely:', 'I can''t tie in what he said today with what he told me last week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40064, 'tie (something) in with something', 'to plan an event or activity so that it combines with or happens at the same time as another, or to be planned in this way:', 'We''re trying to tie our holiday in with Jaimie''s business trip.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40065, 'tie sb into sth', 'to make someone accept a particular situation as part of an agreement:', 'Mobile phone companies usually tie customers into a minimum 12-month contract.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40066, 'tie someone (up) in knots', 'to confuse someone and make them unable to explain something clearly:', 'The Director of Studies tied me up in knots by asking tricky questions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40067, 'tie someone (up) in knots', 'to make someone upset, worried, or confused:', 'Start watching the way his guilt ties him up in knots.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40068, 'tie someone down', 'to limit someone''''s freedom:', 'He''s tied down by having to work every Saturday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40069, 'tie someone down', 'to make someone give you a clear decision:', 'I''ll try to tie her down on her plans.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40070, 'tie (someone/something) down', 'to hold someone or something in place with ropes:', 'Tie down anything that might blow away in the storm.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40071, 'tie someone up', 'to make a person unable to move by tying a rope or something similar around their body or part of their body:', 'The burglars had tied him up (to the bed).', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40072, 'tie someone up', 'When someone is tied up, they are busy or prevented from doing something, such as speaking to someone or going somewhere, because of being involved in another event or activity:', 'I''m afraid we can''t meet till Wednesday - I''m tied up on Monday and Tuesday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40073, 'tie something up', 'to fasten something together using string, rope, or something similar:', 'It was an old-fashioned parcel, tied up with string.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40074, 'tie something up', 'to cause something, often money or possessions, not to be available for use:', 'All my money is tied up in property.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40075, 'tie something to something', 'to show how one thing is connected to another:', 'Researchers have tied the increase in asthma to certain types of pollution.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40076, 'tie someone to something', 'to force someone to stay in a place:', 'Her work ties her to the east coast.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40077, 'tie the knot', 'to get married:', 'So when are you two going to tie the knot?', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40078, 'tie up with sb/sth', 'to form a relationship with another person or company that can help your business develop:', 'Hedge funds have been tying up with the larger banks to gain access to a wider client list.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40079, 'tied to your mother''''s/wife''''s apron strings', 'If you say that someone, especially a man, is tied to his mother''''s/wife''''s apron strings, it means that he is strongly influenced and controlled by that person.', NULL, 'idiom', NULL, NULL, 'old-fashioned, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40080, 'tighten something up', 'to make something become tighter, firmer, or less easy to move:', 'Now tighten up the screws.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40081, 'tighten (something) up', 'to make a rule, system, or law stronger and more difficult to avoid or ignore:', 'Are there any plans to tighten up on advertising controls?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40082, 'tighten the net', '(especially of the police) to become closer to catching someone, especially a criminal:', 'The police are tightening the net around the smugglers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40083, 'tighten up on sth', 'to be more careful about a particular situation:', 'The crisis forced financial institutions to tighten up on lending.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40084, 'tighten your belt', 'to spend less money than you did before because you have less money:', 'I''ve had to tighten my belt since I stopped working full-time.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40085, 'till/until kingdom come', 'for ever:', 'I don''t want to have to wait till kingdom come for you to make up your mind.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40086, 'till/until the cows come home', 'for a very long time:', 'I could sit here and argue with you till the cows come home, but it wouldn''t solve anything.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40087, 'tilt at windmills', 'to fight enemies who do not really exist', NULL, 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40088, 'tilt the balance/scales', 'If something tilts the balance, it is the thing that causes a particular situation to happen or a particular decision to be made when other situations or decisions are possible:', 'This might just tilt the balance in the government''s favour.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40089, 'time after time', 'again and again; repeatedly:', 'We''re hearing the same news story time after time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40090, 'time and (time) again', 'very often:', 'I’ve told you time and time again to lock both doors before you leave.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40091, 'time and tide wait for no man', 'said to emphasize that people cannot stop the passing of time, and therefore should not delay doing things', NULL, 'idiom', NULL, NULL, 'literary, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40092, 'time flies', 'used to mean that time passes surprisingly quickly:', 'Time flies when you''re having fun.', 'idiom', 'C2', NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40093, 'time hangs heavy', 'said when minutes, hours, weeks, etc. seem to go past very slowly:', 'Time hangs heavy in prison.', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40094, 'time is money', 'said to emphasize that you should not waste time, because you could be using it to earn money', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40095, 'time is of the essence', 'said to encourage someone to hurry', NULL, 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40096, 'time is on someone''''s side', 'If you say that time is on your side, or that you have time on your side, you mean that you do not have to do quickly whatever it is that you want or have to do:', 'We don''t have to make a final decision till next week, so time is on our side.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40097, 'time on your hands', 'a period when you have nothing you must do:', 'Now that she was retired, Mary found that she had a lot of time on her hands.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40098, 'time stands still', 'When time stands still, everything around you seems to stop:', 'I saw the car coming straight towards me, and for a moment time stood still.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40099, 'time will tell', 'you will discover in the future what the result of a present situation is:', 'Time will tell whether we made the right decision.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40100, 'time''''s a great healer', 'said to mean that a painful or difficult situation will seem less bad as time passes', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40101, 'times have changed', 'the situation is different now from the way it was in the past:', 'Times have changed and many more women now have executive jobs than in the past.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40102, 'time’s up', 'infml an activity is finished:', 'OK, everyone, time’s up – hand in your tests.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40103, 'tip (something/someone) over', 'to (cause to) fall over onto one side:', 'Be careful not to tip that cup of coffee over.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40104, 'tip over into something', 'If something tips over from something into something else, it stops being the first thing, and becomes the second:', 'At various points in the play, the action tips over from comedy into farce (= stops being funny and becomes ridiculous).', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40105, 'tip someone off', 'to warn someone secretly about something that will happen, so that they can take action or prevent it from happening:', '[ + that ] Somebody must have tipped the burglars off that the house would be empty.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40106, 'tip someone the wink', 'to give someone a piece of secret or private information that might bring an advantage to them:', 'Thanks for tipping me the wink about those cheap tickets, Bill.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40107, 'tip the balance', 'to cause a change, esp. in making something more likely to happen:', 'Introducing new fish to the lake tipped the balance and made it very hard for the trout that were already living there.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40108, 'tip the balance/scales', 'If something tips the balance or tips the scales, it is the thing that causes a particular situation to happen or a particular decision to be made, when other situations or decisions are possible:', 'The teams were evenly matched until two quick goals from Rooney tipped the balance in favour of England.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40109, 'tip your hand', 'If you tip your hand, you say what you are going to do or what you believe when you have been keeping it secret:', 'Despite weeks of media speculation, the president refused to tip his hand about his plans for re-election.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40110, 'tiptoe around something/someone', 'to avoid dealing with a difficult subject, problem, or person:', 'Jonathan keeps tiptoeing around the problem, instead of confronting it.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40111, 'tire of something/someone', 'to become bored with someone or something, or to stop enjoying an activity:', 'This is the kind of toy that kids will soon tire of.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40112, 'tire of something', 'to be annoyed by something', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40113, 'tire someone out', 'to make someone feel very tired:', 'Let the kids run around outside - that''ll tire them out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40114, 'tired and emotional', 'or polite phrase for
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40115, 'to a fault', 'more than is necessary:', 'Keri is generous to a fault.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40116, 'to a man', 'every person in a group:', 'There were 400 people at the meeting and they all, to a man, voted for the motion.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40117, 'to a tee', 'perfectly or completely:', 'That job would suit you to a tee.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40118, 'to a/some degree', 'partly:', 'To some degree I think that''s right, but there are other factors which affect the situation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40119, 'to add insult to injury', 'said when you feel that someone has made a bad situation worse by doing something else to upset you:', 'They told me I was too old for the job, and then to add insult to injury, they refused to pay my expenses!', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40120, 'to be left on the cutting room floor', 'to be filmed, but not included in the final version of a film or television programme:', 'The scene adds nothing and should have been left on the cutting room floor.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40121, 'to be left on the cutting room floor', 'to not be included in the final version of a list or plan:', 'Measures to encourage alternative energy investment were discussed, but left on the cutting room floor.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40122, 'to be on the safe side', 'to avoid risk:', 'Maybe it won’t rain, but to be on the safe side, take your umbrella.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40123, 'to be reckoned with', 'worth taking seriously because of being powerful, important, or good:', 'Are unions still a force to be reckoned with?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40124, 'to be sure', 'certainly:', 'This is not his best book, to be sure, but it is still worth reading.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40125, 'to be wise after the event', 'used to mean that it is easy to understand what you could have done to prevent something bad from happening after it has happened:', 'In retrospect, we should have insisted on checking his calculations, but it''s easy to be wise after the event.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40126, 'to begin with', 'at the start of a process, event, or situation:', 'There were six of us to begin with, then two people left.', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40127, 'to begin with', 'used to give the first important reason for something:', 'The hotel was awful! To begin with, our room was far too small.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40128, 'to boot', 'in addition:', 'He''s kind, handsome, and wealthy to boot.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40129, 'to cap it all', 'used when you mention something in addition to all the other (bad) things that have happened:', 'It''s been a terrible week and now, to cap it all, I''ve got a cold.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40130, 'to cap it all off', 'used when you mention something in addition to all the other (bad) things that have happened:', 'It''s been a terrible week and now, to cap it all off, I have a cold.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40131, 'to coin a phrase', 'something you say before using an expression that has been very popular or used too much:', 'I was, to coin a phrase, gobsmacked!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40132, 'to compare apples and/with oranges', 'used to say that two things are completely different and it is not sensible to compare them:', 'The ratio of exports to GDP is very misleading. It compares apples and oranges.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40133, 'to crown it all', 'used to say that something is the worst thing to happen in a series of unpleasant events:', 'I had lost my ticket, was soaked to the skin, and, to crown it all, discovered that my purse had been stolen.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40134, 'to cut a long story short', 'used when you are explaining what happened in a few words, without giving all the details:', 'He wanted to be a doctor but, to cut a long story short, he ended up as a pharmacist.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40135, 'to date', 'up to the present time:', 'This novel is his best work to date.', 'idiom', 'B2', NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40136, 'to death', 'a lot:', 'The movie scared the kids to death.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40137, 'to do someone a solid', 'to do something kind or helpful for someone:', 'Anyone care to do me a solid and tell me if I can claim this on my taxes?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40138, 'to err is human (to forgive divine).', 'something that you say that means that it is natural for people to make mistakes and it is important to forgive people when they do', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40139, 'to have arrived', 'to have achieved success and become famous:', 'He felt he had truly arrived when he got his first part in a Broadway play.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40140, 'to hell', 'If you wish or hope to hell that something is true or that it will happen, you are saying how strongly you want it to be true or to happen:', 'I hope to hell she hasn''t missed that plane.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40141, 'to hell with someone/something', 'used to say that you do not care about someone or something:', 'I was ready to say the hell with it and leave.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40142, 'to hold/clutch/clasp/take someone/something to your bosom', 'to hold someone or something close to your body with your arms:', 'She held him tightly to her bosom.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40143, 'to hold/clutch/clasp/take someone/something to your bosom', 'to accept someone or something very eagerly:', 'Her family immediately took her new husband to their bosoms.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40144, 'to make a long story short', 'used when you are explaining what happened in a few words, without giving all the details:', 'We started going out and, to make a long story short, we ended up getting serious about one another.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40145, 'to my eye', 'used when giving your opinion about the appearance of something or someone:', 'You see, to my eye, she looks better without make-up.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40146, 'to my mind', 'in my opinion:', 'The room has pink walls and a green carpet, which to my mind looks all wrong.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40147, 'to no avail', 'fml without any success or any effect:', 'The students asked the school to help them raise the money, but to no avail.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40148, 'to put it mildly', 'used for saying that something is much more extreme than your words suggest:', 'It has been a remarkable day, to put it mildly.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40149, 'to say nothing of ...', 'and in addition there is:', 'It would be an enormous amount of work, to say nothing of the cost.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40150, 'to say the least', 'used to show that what you are describing is in fact much more serious or important than you have suggested:', 'It''s going to be awkward, to say the least.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40151, 'to someone''''s face', 'If you say something unpleasant to someone''''s face, you say it to them directly, when you are together:', 'If you''ve got something to say, say it to my face.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40152, 'to someone''''s way of thinking', 'in a particular person''''s opinion:', 'To my way of thinking, the plan should never have been approved.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40153, 'to someone’s credit', 'deserving praise and respect:', 'It is to his credit that he''s willing to admit he has a problem.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40154, 'to spare', 'still available:', 'I caught the plane with only five minutes to spare.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40155, 'to start with', 'first:', 'We''ll need a half cup of sugar to start with, and then we''ll need another cup later.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40156, 'to tell (you) the truth', 'I have to admit:', 'To tell the truth, I couldn’t hear a word he said.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40157, 'to the bad', 'having lost or spent a particular amount of money as a result of something:', 'He ended the day £50 to the bad.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40158, 'to the best of my recollection', 'from what my memory tells me:', 'To the best of my recollection I have never seen her before.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40159, 'to the bitter end', 'until something is finished', NULL, 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40160, 'to the bone', 'all the way through, or very badly:', 'I was frozen/chilled to the bone after waiting so long for the bus.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40161, 'to the core', 'in every way:', 'He''s a Conservative to the core.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40162, 'to the core', 'to an extreme degree:', 'I was shocked to the core.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40163, 'to the day', 'exactly:', 'She died ten years ago to the day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40164, 'to the gills', 'used in expressions to mean completely full:', 'By the time the fourth course was served, I was stuffed to the gills.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40165, 'to the good', 'generally helpful:', 'Greater international stability can surely only be to the good.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40166, 'to the gunwales', 'If something is filled to the gunwales, it is extremely full:', 'A crowd of 50,000 packed the stadium almost to the gunwales.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40167, 'to the hilt', 'as much as possible:', 'We’re already being taxed to the hilt.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40168, 'to the last', 'until something is complete or has been achieved:', 'I think my position is right, and I''ll defend it to the last.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40169, 'to the last', 'until the end of someone''''s life:', 'She was a true patriot to the last.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40170, 'to the last (man)', 'until every person is dead:', 'Both sides have declared themselves ready to fight to the last man.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40171, 'to the letter', 'If you obey instructions or rules to the letter, you do exactly what you have been told to do, giving great attention to every detail:', 'I followed the instructions to the letter and it still went wrong.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40172, 'to the life', 'If a picture or description is someone to the life, it is exactly like that person:', 'That sketch is Joanna to the life.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40173, 'to the max', 'to the highest degree or level:', 'Too many guys in the gym are pushing their bodies to the max and not using the weights correctly.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40174, 'to the nth degree', 'as much or as far as possible:', 'We were questioned to the nth degree.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40175, 'to the point', 'expressing something very important or suitable for the subject being discussed:', 'Her comments on my work were very apt and to the point.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40176, 'to the tune of', 'in the approximate amount mentioned:', 'We’re in debt to the tune of $50,000.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40177, 'to top it all', 'If you have been describing bad things that happened, and then say that to top it all something else happened, you mean that the final thing was even worse:', 'The washing machine flooded, my car broke down, then to top it all I locked myself out of the house.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40178, 'to top it all off', 'If you have been describing bad things that happened, and then say that to top it all off something else happened, you mean that the final thing was even worse:', 'The washing machine started leaking, my car broke down, then to top it all off I locked myself out of the house.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40179, 'to wit', 'used to make clearer or more particular something that you have already said:', 'She''s starting to see the effects of the disease, to wit: her memory is less reliable and she can''t always find her way home after going somewhere.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40180, 'to your heart''''s content', 'If you do something to your heart''''s content, you do something enjoyable for as long as you want to do it:', 'You''ve got a whole week to yourself and you can read to your heart''s content.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40181, 'to your name', 'If you have nothing or very little to your name, you own very little or have no money:', 'He had arrived in America without a penny to his name.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40182, 'to/for all intents and purposes', 'in all the most important ways:', 'For all intents and purposes, the project is completed.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40183, 'to/until my dying day', 'as long as I live:', 'I''ll remember your kindness to my dying day.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40184, 'today North America, tomorrow the world', 'used to express the hope that success already achieved in one place will be continued in other places in the future:', '"We''ve just about cornered the market in Europe." "Well, today Europe, tomorrow the world".', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40185, 'toe the line', 'to do what you are expected to do without causing trouble for anyone:', 'If you want to get ahead, you’d better learn to toe the line.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40186, 'told you (so)', 'what I said before was correct:', '"I should never have lent him the money." "I told you so."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40187, 'tone in', 'When colours tone in, they match and look pleasant together:', 'The green of your scarf tones in with your shoes.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40188, 'tone something down', 'to make something less forceful or offensive, usually a piece of writing or a speech:', 'Some of the language in the original play has been toned down for the television version.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40189, 'tongues wagging', 'If what someone says or does starts tongues wagging, it causes other people to start talking and guessing things about their private lives:', 'Do you think if we leave the party together it will set/start tongues wagging?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40190, 'too bad', 'If you say something is too bad, you can mean either that you feel sympathy about a problem, or that you do not. The difference is in what is being talked about and the way that you say it:', 'It''s too bad that you can''t come to see Mark in his school play.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40191, 'too big for your boots', 'behaving as if you are more important than you really are:', 'He''s been getting a bit too big for his boots since he got that promotion.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40192, 'too big for your britches', 'behaving as if you are more important than you really are:', 'He''s been getting too big for his britches since he got that promotion.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40193, 'too cool for school', 'very fashionable and confident, in a way that impresses other people', NULL, 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40194, 'too good to be true', 'so good that it is hard to believe, or seeming very good but not real:', 'Her new job sounds too good to be true.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40195, 'too good to miss', 'If you say that something is too good to miss, you mean that it is a very good opportunity and that people should see it, do it, etc.:', 'Henri''s latest show is too good to miss.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40196, 'too little, too late', 'not enough of something that should have been provided earlier:', 'A spokeswoman described the aid for the refugees as too little, too late.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40197, 'too many chiefs and not enough Indians', 'too many managers and not enough people to do the work', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40198, 'too many cooks spoil the broth', 'said when there are too many people involved in trying to do the same thing, so that the final result will not be good', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40199, 'too many cooks spoil the soup', 'said when there are too many people involved in trying to do the same thing, so that the final result will not be good', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40200, 'too much information', 'used when you want to tell someone that what they have said should be kept private or is embarrassing', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40201, 'too much like hard work', 'If you say that an activity is too much like hard work, you do not want to do because it needs a lot of effort:', 'I don''t like gardening - it''s too much like hard work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40202, 'too much of a good thing', 'the fact that something pleasant becomes unpleasant because you have or do too much of it:', 'You can have too much of a good thing.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40203, 'too right', 'said when you agree completely:', '"You can''t do anything in this town if you don''t have any money." "Too right."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40204, 'tool (something/someone) up', 'to get together the equipment you need for doing or making something:', 'All you need to tool up for the trip is a good, waterproof stuff sack.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40205, 'tool (something/someone) up', 'to arm yourself (= get weapons ready) in preparation for something:', 'They tool up and go out looking for a fight.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40206, 'top and tail', 'to cut off the hard parts at each end of a fruit or vegetable when you prepare it for cooking:', 'Top and tail the beans.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40207, 'top dollar', 'a large amount of money:', 'Multinational companies pay top dollar for well-connected consultants.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40208, 'top out', 'to reach the highest point in a continuously changing level that is about to start becoming less again:', 'House prices have topped out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40209, 'top something off', 'to finish something in an enjoyable or successful way:', 'She topped off her performance with a dazzling encore.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40210, 'top something up', 'to add liquid in order to fill to the top a container that is already partly full:', 'Would you like me to top up your drink?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40211, 'top something up', 'to add more of something, especially money, to an existing amount to create the total you need:', 'Students were able to take out loans to top up their grants.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40212, 'top someone up', 'to put more drink into someone''''s glass or cup:', 'Your glass is nearly empty. Let me top you up.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40213, 'torn between something and something', 'finding it very difficult to choose between two possibilities:', 'She’s torn between her loyalty and her desire to tell the truth.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40214, 'toss (and turn)', 'to move around restlessly while sleeping or trying to sleep:', 'I was tossing and turning all night.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40215, 'toss something around', 'If you toss ideas, suggestions, or phrases around, you mention them and discuss them with other people.', NULL, 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40216, 'toss something aside', 'to throw away or get rid of something', NULL, 'phrasal verb', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40217, 'toss something away', 'to spend or lose something carelessly:', 'That much money is not to be tossed away lightly.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40218, 'toss something off', 'to do something quickly, especially in a careless way or with little effort:', 'She tossed off a reply to the letter before she left for the meeting.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40219, 'toss (someone) off', 'to give someone sexual pleasure by rubbing their sex organs, or to do this to yourself', NULL, 'phrasal verb', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40220, 'toss something out', 'to get rid of or remove something:', 'She tossed out my old chair.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40221, 'toss up', 'to throw a coin up into the air and guess which side will land facing up, as a way of making a decision:', 'Let''s toss up to see who goes first.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40222, 'tot something up', 'to add up numbers or amounts of something, or to have a particular number or amount as a total when added up:', 'She quickly totted up our bill and added an amount for the waiter.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40223, 'touch base', 'to talk to someone for a short time to find out how they are or what they think about something:', 'I just wanted to quickly touch base with you: did you get an email from my secretary about the meeting?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40224, 'touch base (with someone)', 'to talk briefly with someone:', 'I''ll touch base with him later to tell him about the meeting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40225, 'touch down', 'When an aircraft touches down, it lands.', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40226, 'touch on something', 'to speak briefly about something:', 'Of course, we only touched on how much I would be paid.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40227, 'touch on/upon something', 'to mention a subject quickly when speaking or writing about another subject:', 'The talk was about educational opportunities for adults, and the speaker also touched upon sources of finance.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40228, 'touch something in', 'to draw or paint a detail in a larger painting with quick light marks', NULL, 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40229, 'touch something off', 'to cause a violent or difficult series of events to suddenly begin:', 'The plans for a new airport have touched off a storm of protest.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40230, 'touch something up', 'to improve something by making small changes or additions:', 'She touched up her lipstick and brushed her hair.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40231, 'touch someone up', 'to touch someone''''s body in a sexual way without their permission:', 'She claimed that he had tried to touch her up.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40232, 'touch wood', 'said in order to avoid bad luck, either when you mention good luck that you have had in the past or when you mention hopes you have for the future:', 'The deal will be agreed on Wednesday, touch wood.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40233, 'touch/strike/hit a (raw) nerve', 'to upset someone:', 'The newspaper article touched a raw nerve - people still resent the closure of the local school.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40234, 'tough luck', 'said to show that you have no sympathy for someone''''s problems or difficulties:', '"They lost a lot of money on their investment." "Tough luck - they should have been more careful."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40235, 'tough something out', 'to deal with a difficult period or situation without becoming any less certain or determined in your plans or opinions:', 'It''s a difficult situation, but if we can just tough it out, things are bound to get better soon.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40236, 'toughen someone up', 'to make someone stronger:', 'The hard work certainly toughened those boys up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40237, 'tower above/over someone/something', 'to be very tall in comparison with someone or something else:', 'The new hotel towers over the Shanghai skyline.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40238, 'tower above/over something', 'to be much bigger and more successful than another thing of the same type:', 'One computer manufacturer towers above all the rest.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40239, 'toy with something', 'to consider something or doing something, but not in a very serious way, and without making a decision:', 'We''re toying with the idea of going to Peru next year.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40240, 'toy with something', 'to touch an object or move it around with your hand, without any purpose but while thinking about something else:', 'She just toyed with her salad.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40241, 'toy with someone/something', 'to not care seriously about someone or about their feelings, especially during a romantic friendship', NULL, 'phrasal verb', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40242, 'track something/someone down', 'to find something or someone after looking for it, him, or her in a lot of different places:', 'He finally managed to track down the book he wanted.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40243, 'trade down', 'to spend less money when you buy things than you did before:', 'Economists predict that shoppers will trade down this season, bypassing full-price stores to save money at bargain chains.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40244, 'trade down', 'to buy something, usually a house or car, that is of a lower value than the one you already have:', 'You only gain if you own residential property as an investment or you are anticipating trading down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40245, 'trade on something', 'to use something, especially a characteristic, for your own advantage and usually in an unfair way:', 'People are always trading on his generosity.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40246, 'trade on/upon something', 'to use something for your own advantage, esp. unfairly:', 'He ran the kind of political campaign that trades on people’s fear of crime.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40247, 'trade places (with someone)', 'to exchange positions with someone:', 'We traded places so he could sit near the window.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40248, 'trade something in', 'to give something you own as part of your payment for something you buy, especially a new type of the same thing:', 'He recently traded in his Jeep for a red Mercedes.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40249, 'trade something off', 'to accept a disadvantage or bad feature in order to have something good:', 'It may be possible to trade off manpower costs against computer costs.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40250, 'trade up', 'to buy something, usually a house or car that is of higher value than the one you already have:', 'trade up from sth to sth Refinancing is a strategy to trade up from a smaller home to a larger one.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40251, 'trade up/down', 'to buy something, usually a house or car, that is of higher or lower value than the one you already have:', 'Financial advisers warn against trading up to a larger home unless you are sure you can afford it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40252, 'traffic in sth', 'to buy and sell goods illegally:', 'He was convicted of trafficking in narcotics.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40253, 'trail away/off', 'When a person''''s voice or a similar sound trails away/off, it becomes quieter and less confident and then stops completely:', 'His voice trailed off as he saw the look on her face.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40254, 'trail off', 'to become less in amount or loudness:', 'His voice trailed off weakly and we could not hear the rest.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40255, 'travel light', 'to bring very few things with you when you go somewhere:', 'I like to carry my bags onto the plane, so I try to travel light.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40256, 'tread carefully/gently/lightly', 'to speak or behave carefully to avoid upsetting or causing offence to anyone:', 'The government knows it has to tread carefully on this issue.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40257, 'tread the boards', 'to act in plays:', 'It''s three years now since you''ve trodden the boards, Ken - how does it feel to be back?', 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40258, 'tread water', 'to float with your head above the water’s surface and your feet below you by moving your legs and arms up and down', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40259, 'tread water', 'To tread water is also to be active but without making progress or falling further behind:', 'Stock prices continued to tread water this week.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40260, 'treat someone like dirt', 'to treat someone extremely badly:', 'For years I allowed him to treat me like dirt.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40261, 'treat someone like royalty', 'to treat someone extremely well:', 'The staff in the hotel treated us like royalty.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40262, 'treat someone with kid gloves', 'to deal with someone very gently or carefully:', 'These athletes grow up being treated with kid gloves, and then they don''t know how the real world works.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40263, 'tremble to think', 'If you say that you tremble to think about a possible future event, you are worried or frightened about it:', 'I tremble to think what will happen when he finds out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40264, 'trespass on sth', 'to unfairly use someone else''''s ideas, time, help, etc. for your own advantage:', 'The Florida court seemed to be trespassing on the legislature''s prerogative.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40265, 'trespass on/upon something', 'to take unfair advantage of a good quality in someone''''s character:', 'They said we should stay another night, but I didn''t want to trespass on their hospitality.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40266, 'trials and tribulations', 'troubles and events that cause suffering:', 'the trials and tribulations of marriage', 'idiom', NULL, NULL, 'literary, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40267, 'trick of the trade', 'a clever method used by people who are experienced in a particular type of work or activity:', 'Magazines often improve photographs before they print them - it''s one of the tricks of the trade.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40268, 'trickle down (to sb/sth)', 'to start at the top of a system, organization, etc. and spread to all of it:', 'So far, the benefits of falling crude oil prices haven''t trickled down to consumers.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40269, 'tricks of the trade', 'methods that help you to do a job better or faster:', 'Journalists have to learn the tricks of the trade quickly if they want to get the good stories.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40270, 'tried and found wanting', 'tried and discovered to be not effective:', 'These policies, said the speaker, have been tried and found wanting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40271, 'trifle with someone/something', 'to treat someone or something carelessly or without respect:', 'He trifled with her affections (= feelings).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40272, 'trip (someone) up', 'to fall because you hit your foot on something, or to make someone fall by putting your foot in front of the other person''''s foot:', 'I''m terribly sorry. I didn''t mean to trip you up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40273, 'trip (someone) up', 'to make a mistake, or to cause someone to make a mistake:', 'The exam went quite well, until I tripped up on the last question.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40274, 'trip off the tongue', 'Something that trips off the tongue is easy to say or pronounce:', 'The new company will need to have a name that trips off the tongue and is easy to remember.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40275, 'trot something out', 'to provide an excuse, idea, opinion, or fact, especially one that has been used often before or one that is silly:', 'You trot out that argument whenever I try to discuss this with you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40276, 'trot someone out', 'to send someone to represent or defend your idea or opinion in public, in a boring and familiar way:', 'Whenever the president is in trouble, her spokesman is trotted out to face the press.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40277, 'trouble and strife', 'a way of saying "wife", using Cockney rhyming slang (= a type of slang in which certain words are used instead of other words that they rhyme with)', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40278, 'trudge through something', 'to do work or a particular task slowly and with effort or difficulty:', 'I spent the whole weekend trudging through this report, and I still haven''t finished reading it.', 'phrasal verb', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40279, 'true enough', 'correct or accurate but not completely explaining something:', 'It''s true enough that he had doubts about the project, but we have to look further to understand why he resigned.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40280, 'true to form', 'behaving the way other people expect someone to, based on previous experience:', 'True to form, he tried to get out of his doing any work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40281, 'true to your word', 'keeping a sincere promise:', 'True to his word, he paid back the money he borrowed from us.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40282, 'true to yourself', 'behaving according to your beliefs and doing what you think is right:', 'Try to remember that no matter how hard it gets, you have to remain true to yourself.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40283, 'trump something up', 'to accuse someone of something they have not done in order to have an excuse for punishing that person', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40284, 'trump up sth/trump sth up', 'to give or use false information so that someone will be accused of doing something wrong and punished:', 'The accusation, she said, was trumped up in order to get rid of her.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40285, 'trundle something out', 'to produce in a boring way something that has often been seen or used before:', 'They seem to trundle out the same old films every Christmas.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40286, 'trust someone (to do something)!', 'used to say that it is typical of someone to do something stupid:', 'Trust Chris to leave the tickets at home!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40287, 'truth be told', 'used when you are giving your honest opinion or admitting something:', 'Truth be told, I''m still not completely sure what happened.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40288, 'truth is stranger than fiction', 'said when you want to emphasize that real events or things are sometimes stranger than imaginary ones', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40289, 'truth will out', 'said to show that you believe the truth will always be discovered', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40290, 'try for something', 'to attempt to get something:', 'Are you going to try for that job in the sales department?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40291, 'try it on', 'to deceive someone or behave badly, especially in order to discover how much of your bad behaviour will be allowed:', 'He''s not really ill - he''s just trying it on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40292, 'try out for something', 'to compete for a position in a sports team or a part in a play:', 'Luke''s trying out for the college football team.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40293, 'try someone’s patience', 'to makes someone less patient:', 'Little kids get into everything, and it can really try your patience.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40294, 'try something for size', 'to test something or to think about an idea in order to decide if it works or if you can use it', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40295, 'try something on', 'to put on a piece of clothing to discover if it fits you or if you like it:', 'Try on the shoes to see if they fit.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40296, 'try something on for size', 'to test something or to think about an idea in order to decide if it works or if you can use it', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40297, 'try something out', 'to use something to discover if it works or if you like it:', 'Don''t forget to try out the equipment before setting up the experiment.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40298, 'try something out on someone', 'to find out what someone thinks about something:', 'We tried out the new song on a couple of friends, but they didn''t like it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40299, 'try your hand at something', 'to try doing something for the first time:', 'He decided to try his hand at knitting and discovered he was good at it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40300, 'try your luck', 'to try to achieve something although you know you might not succeed:', 'He''d always wanted to act and in 1959 came to London to try his luck on the stage.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40301, 'tuck in/tuck into something', 'to start eating something eagerly:', 'Judging by the way they tucked into their dinner, they must have been very hungry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40302, 'tuck someone in', 'to make someone comfortable in bed, especially a child, by arranging the covers around them:', 'Daddy, if I go to bed now will you tuck me in?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40303, 'tuck something away', 'to put something in a private, safe place:', 'Grandma always kept a little of money tucked away in case of an emergency.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40304, 'tucked away', 'hidden or difficult to find:', 'Van’s house is tucked away at the end of the road.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40305, 'tucker someone out', 'to make someone extremely tired:', 'I was tired. Disneyland tuckered me out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40306, 'tug at/touch your forelock', 'to show respect to someone in a higher position than you in a way that seems old-fashioned', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40307, 'tumble to something', 'to suddenly understand something:', 'I think he''s tumbled to our plan.', 'phrasal verb', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40308, 'tune (someone/something) out', 'to ignore someone or not give your attention to something or to what is happening around you:', 'Most of what he says is such garbage that I just tune him out.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40309, 'tune (something) up', 'If musicians who are preparing to play tune up their instruments, they make small changes to them so that they produce the correct notes:', 'After the orchestra had tuned up, the conductor walked on to the stage.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40310, 'tune (something) up', 'to tune an engine', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40311, 'tune (something) up', 'to prepare for something, or to prepare something for something, especially by making small changes to improve it:', 'Microsoft is tuning up for the release of its latest operating system.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40312, 'tune in', 'to watch or listen to a particular television or radio programme or station:', 'Be sure to tune in to next week''s show.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40313, 'tune in', 'to have a good understanding of what is happening in a situation or what other people are thinking:', 'She just doesn''t seem to be tuned in to her students'' needs.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40314, 'tuned in (to someone/something)', 'very aware of someone or something so that you understand that person or thing well:', 'She’s tuned in to all the latest fashions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40315, 'turf something out', 'to get rid of a number of things or something large that you do not want:', 'I turfed out a load of old shoes last week.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40316, 'turf someone out', 'to force someone to leave a place or an organization:', 'She''ll be turfed out of the study group if she carries on being disruptive.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40317, 'turn (someone) against someone/something', 'to start not to like or agree with someone or something, or to make someone do this:', 'After six years of fighting public opinion has turned against the war.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40318, 'turn (someone) back', 'to return in the direction you have come from, or to make someone do this:', 'We''re lost - we''ll have to turn back.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40319, 'turn (someone/something) into someone/something', 'to change and become someone or something different, or to make someone or something do this:', 'The council was hoping to turn a children''s home into a residence for adolescent girls.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40320, 'turn (something) upside down', 'to search everywhere for something, sometimes leaving a place very untidy:', 'I turned the apartment upside down but I couldn''t find the letter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40321, 'turn (something) upside down', 'to (cause something to) change completely and in a bad way:', 'Another poor harvest could turn the country''s economy upside down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40322, 'turn a blind eye', 'to ignore something that you know is wrong:', 'Management often turn a blind eye to bullying in the workplace.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40323, 'turn a deaf ear', 'to ignore someone when they complain or ask for something:', 'In the past they''ve tended to turn a deaf ear to such requests.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40324, 'turn a place inside out', 'to search every part of a place very carefully:', 'I''ve turned the house inside out but I still can''t find my keys.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40325, 'turn a profit', 'to begin to earn a profit:', 'He’s been in business five years, but has not yet turned a profit.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40326, 'turn around', 'used when talking about something that someone says, especially when they say it in a very direct way without worrying about people''''s reactions:', 'I can''t just turn round and say, "Sorry, it was all a big mistake."', 'phrasal verb', NULL, NULL, 'spoken', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40327, 'turn something around', 'to change an unsuccessful business, plan, or system so that it becomes successful:', 'The new management team turned the ailing company around in under six months.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40328, 'turn away', 'to move your face so you are not looking at something:', 'When they show an operation on TV, I have to turn away.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40329, 'turn someone away', 'to not allow someone to enter a place:', 'They turned us away at the entrance because we didn''t have tickets.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40330, 'turn back the clock', 'to remember or imagine times in the past:', 'Now we''re going to turn back the clock with some rock and roll from the 1950s.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40331, 'turn back the clock (on something)', 'to change something so that it behaves or exists as it did in the past:', 'They oppose efforts to turn the clock back on civil rights.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40332, 'turn in', 'to go to bed:', 'I usually turn in at about midnight.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40333, 'turn someone in', 'to take a criminal to the police, or to go to them yourself to admit a crime:', 'The hit-and-run driver turned himself in to the police the day after the accident.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40334, 'turn something in', 'to return something to an organization or a person in authority:', 'Please turn your old parking permits in at the end of the week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40335, 'turn something in', 'to produce results, usually good results:', 'Both companies turn in pretax profits of over 5.5 million annually.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40336, 'turn in your grave', 'If you say that a dead person would turn in their grave, you mean that they would be very angry or upset about something:', 'She''d turn in her grave if she knew what he was spending his inheritance on.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40337, 'turn into a pumpkin', 'used when saying what time you usually go home or go to bed at night:', 'It''s too late for me - I turn into a pumpkin at eleven o''clock.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40338, 'turn off (something)', 'to leave the road you are travelling on and travel along another one:', 'Turn off the motorway at the next exit.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40339, 'turn someone off', 'to stop someone feeling interested or excited, especially sexually:', 'I would think the smell of her breath would turn anyone off.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40340, 'turn on the waterworks', 'to start crying, especially too much or in a way that does not seem sincere:', 'You can turn on the waterworks all you want - I''m not going to change my mind!', 'idiom', NULL, NULL, 'old-fashioned, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40341, 'turn out', 'to happen in a particular way or to have a particular result, especially an unexpected one:', 'As events turned out, we were right to have decided to leave early.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40342, 'turn out', 'to be known or discovered finally and surprisingly:', '[ + to infinitive ] The truth turned out to be stranger than we had expected.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40343, 'turn out', 'If people turn out for an event, they go to be there or to watch:', 'Thousands of people turned out to welcome the team home.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40344, 'turn something out', 'to produce or make something, often quickly or in large amounts:', 'They turn out thousands of these games every week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40345, 'turn something out', 'If you turn out a container or the things in it, you empty it completely:', 'We turned out all the cupboards and drawers and found things we hadn''t seen for years.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40346, 'turn someone out', 'to force someone to leave:', 'He was turned out of his flat because he couldn''t pay the rent.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40347, 'turn someone out', 'to be beautifully, well, etc. dressed:', 'She''s always beautifully turned out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40348, 'turn over', 'If an engine turns over, its parts move in order to make the engine start running:', 'When I put the key in the ignition it turns over, but it won''t start.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40349, 'turn (something) over', 'to change to a different television station:', 'This programme''s boring - can I turn over to BBC2?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40350, 'turn over something', 'If a business turns over a particular amount of money, it does that amount of business during a stated period:', 'The profits are not high, but the company turns over more than $3.5 million every year.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40351, 'turn something over', 'to use or allow something to be used for a different purpose:', 'Grants are being offered to farmers who agree to turn over their land to parkland.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40352, 'turn something over', 'to think about something for a period of time:', 'His father had been turning the idea over in his mind for some time.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40353, 'turn somewhere/something over', 'to steal something from a place or to search it, making it very untidy or causing damage:', 'Did you hear Paul''s flat got turned over last week?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40354, 'turn over a new leaf', 'to start behaving in a better way:', 'Apparently he''s turned over a new leaf and he''s not smoking any more.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40355, 'turn over in your grave', 'to strongly disapprove:', 'Your father would turn over in his grave if he could hear the way you are talking to me now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40356, 'turn round', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40357, 'turn something round', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40358, 'turn someone on to something', 'to cause someone to be interested in something:', 'He turned me on to all kinds of music that I never would have heard otherwise.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40359, 'turn someone''''s head', 'If something turns someone''''s head, it has an influence on how that person behaves, especially by making them too proud:', 'Success has never turned her head - she''s still the same simple unaffected girl she always was.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40360, 'turn someone''''s stomach', 'to make someone feel sick, often because they are angry or upset about something:', 'The sight of Joe eating raw fish is enough to turn your stomach.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40361, 'turn someone/something loose', 'to free someone or something; to remove anything that limits the freedom of action of someone or something:', 'He turned the horse loose in the field.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40362, 'turn something on', 'to start to show a particular quality:', 'He can really turn on the charm when he wants to.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40363, 'turn on someone', 'to attack or criticize someone suddenly and unexpectedly:', 'Suddenly she just turned on me and accused me of undermining her.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40364, 'turn on something', 'If something turns on something else, it depends on it or is decided by it:', 'The success of the talks turns on whether both sides are willing to make some concessions.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40365, 'turn someone on', 'to make someone feel interested or excited, especially sexually:', 'Short men really turn me on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40366, 'turn something on its head', 'to cause something to be the opposite of what it was before:', 'These new findings turn the accepted theories on their head.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40367, 'turn something over to someone', 'to give something to someone in authority or someone who has a legal right to it, or to give someone legal responsibility for something:', 'They turned the videos over to the police.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40368, 'turn someone over to someone', 'to take a criminal to the police or other authority:', 'He was working here illegally and was terrified that his boss would turn him over to the authorities.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40369, 'turn something/someone down', 'to refuse an offer or request:', 'He offered her a trip to Australia but she turned it/him down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40370, 'turn tail', 'to turn around and run away, usually because you are frightened:', 'As soon as they saw we had guns, they turned tail and ran away.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40371, 'turn the air blue', 'to swear a lot (= use rude words), or to involve a lot of swearing:', 'I backed the car into a wall and turned the air blue, I''m ashamed to say.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40372, 'turn the clock back', 'If you try to turn the clock back, you want things to be the way they were in the past.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40373, 'turn the corner', 'If a situation turns the corner, it starts to improve after a difficult period:', 'After nine months of poor sales we''ve finally turned the corner.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40374, 'turn the other cheek', 'to not do anything to hurt someone who has hurt you:', 'Neither nation is renowned for turning the other cheek.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40375, 'turn the spotlight on something', 'to attract attention to something, usually to give information about something bad:', 'The documentary turned the spotlight on the low wages paid to manual workers.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40376, 'turn the tables', 'to change from being in a weaker position in relation to someone else to being in a stronger position:', 'The plaintiff’s lawyer turned the tables this morning by producing some strong new evidence.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40377, 'turn the tables on someone', 'to change a situation so that you now have an advantage over someone who previously had an advantage over you:', 'She turned the tables on her rival with allegations of corruption.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40378, 'turn to dust', 'to become worth nothing:', 'Every promise they have made has turned to dust.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40379, 'turn to jelly', 'to suddenly feel weak because you are frightened, nervous, or ill:', 'As she knocked on the director''s door, her legs turned to jelly.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40380, 'turn to someone/something', 'to ask a person or organization for help or support:', 'Without someone to turn to for advice, making the most appropriate choice can be difficult.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40381, 'turn to something', 'to start to do or use something bad, especially because you are unhappy:', 'She turned to drugs after the break-up of her marriage.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40382, 'turn (something) to something', 'If you turn to a particular subject, or you turn your thoughts or attention to it, you begin to speak, think, or write about it:', 'I''d like us now to turn our attention to next year''s budget.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40383, 'turn up (somewhere)', 'to arrive or appear somewhere, usually unexpectedly or in a way that was not planned:', 'Do you think many people will turn up?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40384, 'turn up', 'If a better situation or an opportunity to do something turns up, it happens or becomes available unexpectedly or in a way that was not planned:', 'Don''t worry about it - something will turn up, you''ll see.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40385, 'turn up', 'If something that you have been looking for turns up, you find it unexpectedly:', 'The missing letter eventually turned up inside a book.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40386, 'turn something up', 'to make a piece of clothing or part of a piece of clothing shorter, by folding the material and sewing it into position:', 'You could always turn the sleeves up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40387, 'turn something up', 'to discover something, especially information, after a lot of searching:', 'See what you can turn up about the family in the files.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40388, 'turn your back on something', 'to stop being involved in something:', 'The country cannot afford to turn its back on tourism.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40389, 'turn your back on someone', 'to refuse to help someone:', 'I don''t think he would turn his back on his brother, whatever he was accused of.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40390, 'turn your hand to something', 'If you say that someone could turn their hand to an activity or skill, you mean they could do it well, despite having no experience of it:', 'Stella''s very talented - she could turn her hand to anything.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40391, 'turn your nose up', 'to not accept something because you do not think it is good enough for you:', 'They turned their noses up at the only hotel that was available.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40392, 'turn your nose up at something', 'to refuse to accept something because you feel that it is not good enough for you:', 'She turned up her nose at the job because she didn’t think it had enough status.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40393, 'turn-up for the book(s)', 'a surprising or unexpected event:', 'Well, that''s a turn-up for the books - I never thought he''d get the job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40394, 'turn/come up trumps', 'to complete an activity successfully or to produce a good result, especially when you were not expected to:', 'John''s uncle came up trumps, finding us a place to stay at the last minute.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40395, 'turn/roll over in your grave', 'If you say that a dead person would turn or roll over in his or her grave, you mean that he or she would be very angry or upset about something:', 'She''d turn over in her grave if she knew what he was spending his inheritance on.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40396, 'turn/use something to good account', 'to use your skills and abilities to produce good results:', 'I think we''d all agree that you turned your negotiating skills to very good account in this afternoon''s meeting.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40397, 'tussle with something', 'to try hard to understand or deal with a difficult idea or problem:', 'It''s an idea that I''ve been tussling with for quite a while.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40398, 'twiddle your thumbs', 'to do nothing for a period of time, usually while you are waiting for something to happen:', 'I arrived early for the meeting so I was twiddling my thumbs for half an hour.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40399, 'twilight years', 'the last years of someone''''s life:', 'Old people often rely on pets for comfort and companionship in their twilight years.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40400, 'twilight zone', 'an area where two different ways of life or states of existence meet:', 'the twilight zone between life and death', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40401, 'twist someone around your little finger', 'to be able to persuade someone to do anything you want, usually because they like you so much:', 'He''d do anything for you. You''ve got him twisted around your little finger.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40402, 'twist someone''''s arm', 'to persuade someone to do something they do not want to do:', 'I didn''t want to go but Linda twisted my arm.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40403, 'twist/turn the knife (in the wound)', 'to make someone who is annoyed, worried, or upset feel even worse:', 'Just to turn the knife a little, he told me he''d seen my old girlfriend with her new man.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40404, 'two can play at that game', 'something that you say when you intend to harm someone in the same way as they harmed you:', 'When I found out that my husband had been having an affair, I thought "two can play at that game!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40405, 'two sides of the same coin', 'two things that different but closely related features of one idea:', 'Rewards and punishments are two sides of the same coin – both are used to control people and neither works very well.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40406, 'two wrongs don''''t make a right', 'said to emphasize that it is not acceptable to do something bad to someone just because they did something bad to you first', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40407, 'two''''s company, three''''s a crowd', 'said when two people are relaxed and enjoying each other''''s company but another person would make them feel less comfortable', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40408, 'type something in', 'to put an instruction or piece of information into your computer by pressing letters, numbers or other keys on your computer keyboard:', 'Type in your password.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40409, 'type something out/up', 'to make a typed copy of a piece of text that is written by hand:', 'Could you type up the minutes from the meeting, please?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40410, 'type sth up', 'to use a keyboard to make a printed copy of something that was written by hand:', 'Could you type up the report by Monday?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40411, 'uncivilized hour', 'a very early or very late time in the day:', 'Sorry to call you at such an uncivilized hour.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40412, 'under arms', 'provided with weapons and willing to fight:', 'The rebels now have thousands of people under arms.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40413, 'under fire', 'being attacked with guns or with severe criticism:', 'The troops were under fire for weeks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40414, 'under guard', 'being protected or being prevented from escaping:', 'The prisoners, under armed guard, performed public service duties, such as cleaning up highways and parks.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40415, 'under lock and key', 'locked away safely:', 'Her jewellery is securely under lock and key at the bank.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40416, 'under lock and key', 'If a person, especially a criminal, is under lock and key, they are being kept in a place from which they cannot escape, usually a prison.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40417, 'under oath', 'having legally promised to tell the truth:', 'He was accused of lying under oath.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40418, 'under repair', 'being repaired:', 'This section of motorway will be under repair until January.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40419, 'under sail', 'travelling in a boat or ship with sails:', 'After ten hours under sail, they reached dry land.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40420, 'under someone''''s roof', 'in a home that belongs to someone:', 'While you''re under my roof, you have to live by my rules.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40421, 'under someone''''s thumb', 'under someone''''s control:', 'He''s got the committee firmly under his thumb - they agree to whatever he asks.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40422, 'under starter''''s orders', 'ready for the signal to start a race', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40423, 'under the cosh', 'If a football team is under the cosh, it is defending continuously:', 'We were really under the cosh with ten men and never really looked like getting back into the game.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40424, 'under the counter', 'Things bought under the counter are bought secretly and illegally:', 'The kids managed to get cigarettes under the counter.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40425, 'under the heel of something/someone', 'completely controlled by something or someone:', 'This country would never submit to living under the heel of a foreign power.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40426, 'under the influence', 'drunk:', 'Driving under the influence is a very serious offence.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40427, 'under the knife', 'while having a medical operation', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40428, 'under the name of', 'using the false name of:', 'Her detective stories were written under the name of Kramer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40429, 'under the pump', 'in a difficult situation or feeling a lot of pressure:', 'When his team are under the pump he generally comes up with a few good ideas.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40430, 'under the same roof', 'in the same building:', 'I refuse to live under the same roof as that man.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40431, 'under the sun', 'in existence; on earth:', 'I’ve tried everything under the sun to fix this lock, but I just can’t get it to work.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40432, 'under the table', 'If something is done under the table, it is a secret, hidden action:', 'They offered him money under the table to change his mind.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40433, 'under the weather', 'If someone is or feels under the weather, they feel ill:', 'I''m feeling a bit under the weather - I think I''m getting a cold.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40434, 'under the wire', 'If someone does something under the wire, they do it at the last possible moment:', 'They got in under the wire just before the entry requirements for the training program changed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40435, 'under wraps', 'secret:', 'They tried to keep the report under wraps.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40436, 'under your belt', 'learned or succeeded in, and now a part of your experience:', 'Now that you’ve got the required courses under your belt, you can take some electives.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40437, 'under your breath', 'quietly so that other people cannot hear exactly what you are saying:', 'He muttered something under his breath.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40438, 'under your feet', 'If someone is under your feet, they are near you in a way that is difficult and prevents you from doing what you want to do:', 'The children were under my feet all day so I couldn''t get anything done.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40439, 'under your nose', 'in the place where something belongs, or in an obvious place:', 'I’ve been looking for my keys and they were right here under my nose all the time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40440, 'under your own steam', 'If you do something under your own steam, you do it without help:', 'Do you want a lift or will you get there under your own steam?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40441, 'undress someone with your eyes', 'to look at someone''''s body with strong, and often unpleasant, sexual desire', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40442, 'until all hours', 'very late:', 'He stays up drinking until all hours.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40443, 'until you are blue in the face', 'If you say or shout something until you are blue in the face, you are wasting your efforts because you will get no results:', 'You can tell her to clean her room until you are blue in the face, but she won''t do it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40444, 'unto thine own self be true', 'used to say that you should only do what you think is right.', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40445, 'up a gum tree', 'in a very difficult situation:', 'When he died I was left up a gum tree.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40446, 'up a/the creek', 'in a difficult situation:', 'If any more people resign, we''ll be really up the creek.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40447, 'up a/the creek without a paddle', 'in a difficult situation, with no way of getting out of it:', 'Customers feel they have been left up the creek without a paddle by the bank.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40448, 'up and about', 'infml feeling well enough to get out of bed and move around', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40449, 'up and do something', 'to do something that is unexpected or different:', 'After 20 years of marriage, she up and left him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40450, 'up and running', 'If something, especially a system or a machine, is up and running it is operating:', 'The engineer soon got the air-conditioning up and running again.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40451, 'up for grabs', 'available and ready to be won or taken:', 'There are hundreds of prizes up for grabs.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40452, 'up in arms', 'angry or upset:', 'The union is up in arms over the reduction in health benefits.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40453, 'up in the air', 'If a matter is up in the air, it is uncertain, often because other matters have to be decided first:', 'The whole future of the project is still up in the air.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40454, 'up someone''''s ass', 'a rude phrase meaning driving too close to the car in front:', 'I had a sports car up my ass for the first 50 miles.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40455, 'up sticks', 'to take all the things that you own and go and live in a different place:', 'This is the fourth time in five years that we''ve had to up sticks.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40456, 'up the ante', 'If you up the ante, you increase your demands or the risks in a situation in order to achieve a better result:', 'The government has upped the ante by refusing to negotiate until a ceasefire has been agreed .', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40457, 'up the creek', 'infml in a difficult situation:', 'If any more people quit, we’ll really be up the creek.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40458, 'up the spout', 'wasted, spoiled, or not working correctly:', 'He said the decision meant that nearly £3m of shareholders'' money was up the spout.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40459, 'up the spout', 'pregnant:', 'She''s up the spout, but she won''t say who the father is.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40460, 'up till', 'until:', 'Up to yesterday, we had no idea where the child was.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40461, 'up to a point', 'partly, or to a limited degree:', 'Of course there is some truth in all this, but only up to a point.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40462, 'up to par', 'feeling or performing as good as usual, with nothing wrong:', 'Jenny had not been up to par physically and did not come close to winning a medal.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40463, 'up to scratch', 'reaching an acceptable standard:', 'Your last essay wasn''t up to scratch/didn''t come up to scratch.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40464, 'up to snuff', 'as good as it should be; of an acceptable standard:', 'The phone system just wasn''t up to snuff.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40465, 'up to speed', 'If you are up to speed with a subject or activity, you have all the latest information about it and are able to do it well:', 'We arranged for some home tutoring to get him up to speed with the other children in his class.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40466, 'up with', 'shouted or written on notices to show support:', 'Up with freedom, down with repression!', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40467, 'up your game', 'to try harder and improve the quality of what you are doing:', 'Abi has really upped her game this year, and is now in contention for a gold medal.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40468, 'up yours!', 'used to show that you very much dislike someone or the things that someone has just said or done', NULL, 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40469, 'up/down your alley', 'to be the type of thing that you are interested in or that you enjoy doing:', 'Kate loves dancing, so salsa lessons would be right up her alley.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40470, 'upset the apple cart', 'to cause trouble, especially by spoiling someone''''s plans', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40471, 'urge someone on', 'to encourage someone to do or achieve something:', 'The crowd was cheering and urging her on all through the race.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40472, 'use something up', 'to finish a supply of something:', 'Don''t use up all the milk - we need some for breakfast.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40473, 'use your head', 'used to tell someone in a slightly angry way to think more carefully about what they are doing:', 'Why didn''t you use your head and cover the furniture before you started painting?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40474, 'use your loaf', 'used to tell someone in a slightly angry way to think more carefully about what they are doing', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40475, 'usher something in', 'to be at the start of a new period, especially when important changes or new things happen, or to cause important changes to start happening:', 'These changes could usher in a period of dramatic economic growth.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40476, 'vamp something up', 'to make something more attractive and exciting:', 'The dress is simple and elegant, but you could vamp it up for evening wear with some stunning jewellery.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40477, 'vamp something up', 'to act like a vamp:', 'pictures of Sharon Stone vamping it up on the red carpet', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40478, 'vanish into thin air', 'to disappear suddenly and completely:', 'The ship simply vanished into thin air.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40479, 'vanish/go up/disappear in a puff of smoke', 'to disappear suddenly and completely:', 'One moment he was standing behind me, the next he had vanished in a puff of smoke.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40480, 'variety is the spice of life', 'said to emphasize that doing many different things, or often changing what you do, makes life interesting', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40481, 'various and sundry', 'many different:', 'He spent an hour telling me about various and sundry ideas he has for making money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40482, 'veg out', 'to relax and spend time doing very little:', 'I''m exhausted - I think I''ll just go home and veg out in front of the TV tonight.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40483, 'venture on/upon something', 'to try to do something difficult or dangerous:', 'The wind was so strong that when we did finally venture on a walk, we were nearly swept away.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40484, 'verge on something', 'to be almost a particular state, quality, or feeling, especially one that is very bad or very good:', 'At times, his performance verged on brilliance, but at others it was nothing special.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40485, 'very good', 'a way of saying yes to someone who is in a higher position or rank than you:', '"Higgins, you may go now." "Very good, sir."', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40486, 'very well', 'a way of saying yes to someone or of agreeing to do what someone asks:', '"Can''t I stay for five minutes longer?" "Oh, very well."', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40487, 'vest in sb/sth', 'if property, shares, etc. vest in someone, they legally become theirs:', 'The author''s copyrights became vested in his trustee when he died.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40488, 'vest sth in sb/sth', 'if power or authority is vested in someone, they are officially given that power or authority:', 'The President exercised all the powers vested in his office to stop the attacks.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40489, 'vest sb with sth', 'if someone is vested with power, the right, etc. to do something, they are officially able or allowed to do it:', 'The new Chancellor has been vested with the power to make any changes required to reduce the national deficit.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40490, 'vest sb with sth', 'if someone is vested with shares, land, or other property, they legally own them:', 'When a son reached the age of 21 years, he was vested with a title in the property.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40491, 'villain of the piece', 'The villain of the piece is someone or something that is seen as being the cause of trouble on a particular occasion:', 'When the minister was forced to resign, the press was generally seen as the villain of the piece.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40492, 'virgin territory', 'a completely new area of activity:', 'The company is moving into markets that until now have been virgin territory.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40493, 'visit something on/upon someone', 'to cause damage to a place or to harm a person:', 'He left in 1983, horrified by the devastation that warfare and famine had visited on his homeland.', 'phrasal verb', NULL, NULL, 'old use, formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40494, 'visit with someone', 'to spend time talking with someone you know:', 'My grandmother was visiting with one of her friends on the porch.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40495, 'voice within you', 'your conscience (= the part of you that tells you when you are doing something wrong):', 'Suddenly this voice within her told her to stop being so stupid.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40496, 'vote something down', 'to defeat something such as a law or plan by voting against it:', 'The proposal to build a new road was voted down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40497, 'vote something down', 'to show that you do not like or agree with something on the internet by clicking on a symbol such as an arrow or thumb pointing down:', 'Users tend to vote down any rude or juvenile comments.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40498, 'vote something through', 'to accept and make possible something such as a law or plan by voting for it:', 'The committee voted through a proposal to cut the defence budget.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40499, 'vote something up', 'to show that you like or agree with something on the internet by clicking on a symbol such as an arrow or thumb pointing up:', 'If you found this article useful, please vote it up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40500, 'vote something up or down', 'to approve or not approve something such as a law or plan by voting for it:', 'The plan cannot be amended - the state legislature must either vote it up or vote it down.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40501, 'vote with your feet', 'to show your opinion by leaving an organization or by no longer supporting, using, or buying something:', 'When the price of skiing doubled, tourists voted with their feet and just stopped going.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40502, 'vote with your wallet', 'to choose or vote according to what is best for you financially:', 'Most people seem to have voted with their wallets rather than with their hearts.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40503, 'vouch for something/someone', 'to say that you know from experience that something is true or good, or that someone is honest and has a good character:', 'Patricia has checked the reports and can vouch for the accuracy of the information.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40504, 'wade in', 'to start to do or say something in a forceful way, often without thinking about it carefully:', 'Even when she knows nothing about it, she wades in with her opinion.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40505, 'wade into something', 'to become involved in a difficult situation, often without thinking about it carefully', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40506, 'wade through something', 'to spend a lot of time and effort doing something boring or difficult, especially reading a lot of information:', 'We had to wade through pages of legal jargon before we could sign the contract.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40507, 'waifs and strays', 'people with no homes:', 'Her house is always full of waifs and strays.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40508, 'wait (on) table(s)', 'to serve meals to people in a restaurant, as your job', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40509, 'wait (on) tables', 'to serve meals to people in a restaurant:', 'She waited tables to pay for college.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40510, 'wait a minute', 'used for getting someone''''s attention, or when you suddenly think of something important:', 'Wait a minute – I know what we can do.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40511, 'wait a minute/moment/second', 'said in order to interrupt someone or to get their attention, or when you have suddenly thought of something important:', 'Now, wait a moment - I don''t agree with that.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40512, 'wait and see', 'to wait to discover what will happen:', 'No decision will be made until next year, so you''ll just have to wait and see.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40513, 'wait around', 'to stay in a place and do nothing while you wait for someone to arrive or something to happen:', 'We spent the whole day waiting around for something exciting to happen, but nothing did.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40514, 'wait at table(s)', 'to serve meals to people in a restaurant, as your job', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40515, 'wait behind', 'to stay in a place after all the other people have left:', 'The teacher made us wait behind after class.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40516, 'wait for it', 'used to show that you are about to say something surprising, funny, or difficult to believe:', 'Depending on who you believe, the problem is either too much political interference or - wait for it - not enough.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40517, 'wait for it', 'used to tell someone not to not start until the correct moment:', 'Wait for it! I haven''t said "go" yet.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40518, 'wait for someone/something', 'to be expecting someone or something and be prepared to deal with him, her, or it:', 'When the thieves left the building, the police were waiting for them.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40519, 'wait for someone', 'If something is waiting for you, it has been left or prepared for you to collect, use, enjoy, or deal with when you arrive:', 'An envelope was waiting for me when I got home.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40520, 'wait something for someone', 'to delay serving a meal until someone arrives:', 'Don''t wait dinner for me - I''ll be home late.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40521, 'wait in', 'to stay at home because you are expecting someone or something to arrive, or someone to phone you:', 'I waited in for the plumber all morning, but he didn''t turn up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40522, 'wait in the wings', 'If someone or something is waiting in the wings, they are not yet active or important, but are ready or likely to be so soon:', 'The team has several talented young players waiting in the wings.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40523, 'wait on someone/something', 'to serve food and drink, especially to customers in a restaurant:', 'The staff who waited on us at dinner were excellent.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40524, 'wait on someone', 'to do everything for someone so that that person does not have to do anything for himself or herself:', 'While she was pregnant, her husband waited on her hand and foot (= did everything for her).', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40525, 'wait on something', 'to wait until you know the result of an activity before doing or deciding something:', 'The lawyers are waiting on the jury''s verdict.', 'phrasal verb', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40526, 'wait something out', 'to wait until something unpleasant has ended:', 'I''d rather wait out the storm than drive home immediately.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40527, 'wait till/until ...', 'said when you are excited about seeing another person''''s reaction to something special or unusual:', 'Wait till you see what Rachel''s wearing!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40528, 'wait up', 'to not go to bed at night because you are expecting someone to arrive:', 'I''ll be home after midnight, so don''t wait up for me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40529, 'wait your turn', 'to wait until it is really your turn to do or get something:', 'If people were more polite, they would wait their turn.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40530, 'wake up and smell the coffee', 'used to tell someone that they are wrong about a particular situation and must realize what is really happening', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40531, 'wake up to something', 'to start to understand that a situation or problem exists:', 'Governments are finally waking up to the fact that the environment should be cleaned up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40532, 'wake (someone) up', 'to (cause to) become conscious after sleeping:', 'Come on, wake up - breakfast is ready.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40533, 'wake (someone) up', 'to start to react to a situation after a period in which you have done very little, or to make someone start to react to a situation:', 'Companies need to wake up and pay attention to the public''s increasing concern about the environment.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40534, 'walk all over someone', 'to treat someone very badly or defeat them very easily:', 'If you don''t want to work at the weekend, say so - don''t let the boss walk all over you.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40535, 'walk away', 'to stop being involved in a situation because it is difficult to deal with or does not give you any advantages:', 'You can''t just walk away from a marriage at the first sign of a problem.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40536, 'walk away', 'to escape an accident without being badly hurt:', 'She overturned the car, but walked away from it without a scratch.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40537, 'walk away with something', 'to win a prize or competition very easily:', 'He walked away with all three gold medals.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40538, 'walk back something', 'to change an opinion that you had expressed before or admit that a statement you made was wrong:', 'He has since walked back his opposition to the bill.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40539, 'walk free', 'to not be charged with a crime, or to be allowed to leave a court after being found not guilty of a crime:', 'They were not arrested or charged and walked free after a seven-hour interrogation.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40540, 'walk free', 'to leave a prison or other place where you have been kept as a prisoner:', 'After two weeks of negotiations the hostages walked free.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40541, 'walk free', 'to be able to walk somewhere without anyone stopping you or attacking you:', 'He said that he wanted to ensure that women, children, the elderly, and students can walk free on the streets without fear of being attacked.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40542, 'walk in on someone', 'to go into a room and see what someone is doing, when they did not want to be seen:', 'She walked in on me when I was getting undressed.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40543, 'walk into something', 'to get a job very easily:', 'She walked straight into a well-paid job after graduating from university.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40544, 'walk it', 'to win or succeed easily:', 'The team should walk it on Saturday.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40545, 'walk of life', 'When people talk about walk(s) of life, they are referring to different types of jobs and different levels of society:', 'Members of the gym include lawyers, teachers, plumbers, and hairdressers - people from all (different) walks of life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40546, 'walk off (somewhere)', 'to leave a place because you are angry or unhappy about something:', 'She threatened to walk off the film set because of the conditions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40547, 'walk something off', 'to walk in order to try and get rid of pain or an unpleasant feeling such as anger:', 'I''m going out to walk off this headache.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40548, 'walk off with something', 'to win something easily:', 'She walked off with the top prize.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40549, 'walk off with something', 'to steal something or take something without asking permission:', 'Who''s walked off with my cup?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40550, 'walk on air', 'to feel extremely excited or happy:', 'After the delivery of her baby, she was walking on air.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40551, 'walk on eggs', 'to be very careful not to offend or upset someone:', 'I find in business these days I''m walking on eggs; I have to be careful with everything I say.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40552, 'walk out', 'to leave an event such as a meeting or performance because you are angry or disapprove of something:', 'All the parents walked out (of the meeting) in protest.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40553, 'walk out', 'to suddenly leave your husband, wife, or partner and end your relationship with them:', 'He walked out on his wife and two kids.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40554, 'walk out', 'to stop working or leave your job because of a disagreement with your employer:', 'Workers are threatening to walk out.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40555, 'walk out on sth', 'if someone walks out on a job, etc., they leave before finishing it because they are not happy about something:', 'Workers who walked out on the job could be sacked for breach of contract.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40556, 'walk right into something', 'If you walk right into something, you are caught or tricked by it because you did not know what was happening:', 'We set a trap and they walked right into it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40557, 'walk the walk', 'to show that something is true by your actions rather than your words:', 'We''re at this meeting because we''re environmentalists who walk the walk.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40558, 'walk through something', 'to practise something, for example a performance, without an audience being present:', 'Let''s just walk through the scene one more time.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40559, 'walk someone through something', 'to slowly and carefully explain something to someone or show someone how to do something:', 'She walked me through the six-page document.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40560, 'walk/be on eggshells', 'to be very careful not to offend or upset someone:', 'If you''re sick you don''t want people treating you differently, and you really don''t want people walking on eggshells around you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40561, 'walk/tread a tightrope', 'If you walk/tread a tightrope, you have to deal with a difficult situation, especially one involving making a decision between two opposing plans of action:', 'Many manufacturers have to walk a tightrope between pricing their goods too high and not selling them, and pricing them low and losing money.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40562, 'walks of life', 'various levels of social position or achievement:', 'In my work I see people from all walks of life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40563, 'wall something in', 'to surround something with walls or tall structures:', 'The valley is walled in by high mountains.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40564, 'wall something off', 'to build a wall around a place:', 'The embassy is walled off from the street.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40565, 'wall something up', 'to fill a space in a wall with brick or stone:', 'We had to wall up an old window.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40566, 'wallow in something', 'to allow yourself to enjoy something completely:', 'My idea of a holiday is to stay in a five-star hotel and just wallow in luxury for a week.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40567, 'wallow in something', 'to remain in an unhappy emotional state without trying to get out of it, as if you are enjoying it or trying to get sympathy from other people:', 'I wish she''d do something to help herself instead of just wallowing in self-pity!', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40568, 'walls have ears', 'something you say to warn someone that it is not safe to speak at that particular time because other people might be listening', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40569, 'waltz through something', 'to complete something such as a test easily and successfully:', 'He waltzed through the first two rounds of the competition.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40570, 'want for something', 'to lack something you need:', 'We didn’t have much, but we never wanted for food.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40571, 'war clouds are gathering', 'If you say that war clouds are gathering over a particular country, you mean that a war seems increasingly likely there:', 'It was the 1930s and war clouds were gathering on the horizon in Europe.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40572, 'ward someone/something off', 'to prevent someone or something unpleasant from harming or coming close to you:', 'In the winter I take vitamin C to ward off colds.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40573, 'warm (someone/something) up', 'to become warmer or to make someone or something warmer:', 'The house soon warms up with the heating on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40574, 'warm (someone) up', 'to entertain people while they are waiting for a performance to start, for example by telling jokes:', 'He''s got a job warming up for TV studio audiences.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40575, 'warm something up', 'to heat food that has already been cooked:', 'You can just warm up the leftovers from yesterday''s meal in the microwave.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40576, 'warm up', 'If an event warms up, it starts to become more interesting, enjoyable, or exciting:', 'The party was only just starting to warm up as I left.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40577, 'warm up', 'to prepare yourself for a physical activity by doing some gentle exercises and stretches:', 'If you don''t warm up before exercising, you risk injuring yourself.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40578, 'warm down', 'to do some gentle exercises and stretches after you have done some intense physical activity, in order to allow your body to recover:', 'It’s also important to warm down after exercise, by repeating the stretching and gentle cardiovascular exercise you did in your warm up.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40579, 'warm something over', 'to use an idea that has been used before or to discuss a subject that has already been discussed before:', 'Voters are bored with politicians warming over old policies.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40580, 'warm to someone', 'to start to like someone:', 'I wasn''t sure about Sarah at first, but I warmed to her after we''d been out together a few times.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40581, 'warm to something', 'If you warm to an idea, you start to become interested in or enthusiastic about it:', 'Unfortunately, I had to leave just as the speaker was warming to his theme.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40582, 'warm up to someone/something', 'to begin to like or enjoy someone or something:', 'She was not a person who was easy to warm up to.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40583, 'warn someone off (something)', 'to tell someone not to do something because of danger or some other reason:', 'A series of flares had been placed along the pavement to warn off motorists.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40584, 'warts and all', 'describing or including all the bad qualities in a person''''s character, with no attempt to hide them:', 'He tried to paint the president as he really was, warts and all.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40585, 'wash (something) out', 'If a colour or dirty mark washes out, or if you wash it out, it disappears when you wash it:', 'Do you think these stains will wash out?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40586, 'wash something out', 'If an event or sports competition is washed out, it is prevented from happening or stopped early because of heavy rain:', 'The men''s tennis semifinals were washed out this morning.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40587, 'wash (something) up', 'to clean the plates, pans, and other things that you have used for cooking and eating:', 'He washed up his mug and put it back on the shelf.', 'phrasal verb', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40588, 'wash up', 'to wash your hands, especially before a meal:', 'Go wash up - your dinner''s ready.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40589, 'wash (with someone)', 'If an excuse or argument won''''t wash with someone, they are unlikely to believe or accept it.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40590, 'wash off', 'to come off the surface of something when water is used:', 'I don''t know if this paint will wash off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40591, 'wash something off', 'to remove something with flowing water:', 'She couldn''t wait to wash off the dirt.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40592, 'wash something away', 'If water or rain washes something away, it removes it or carries it away:', 'The blood on the pavement had been washed away by the rain overnight.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40593, 'wash something down', 'to clean a large object or surface with a liquid:', 'He washed the car down with soapy water.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40594, 'wash something down', 'to eat food or swallow medicine with a drink that helps or improves it:', 'Supper was fresh salmon and vegetables, washed down with a bottle of white wine.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40595, 'wash your dirty linen in public', 'People who wash their dirty linen in public discuss, or allow to be discussed in public, matters that should be kept private.', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40596, 'wash your hands of something', 'If you wash your hands of something that you were previously responsible for, you intentionally stop being involved in it or connected with it in any way:', 'She couldn''t wait to wash her hands of the whole project.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40597, 'wash your mouth out (with soap/soapy water)', 'an expression used humorously when someone has used a rude or offensive word', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40598, 'waste away', 'to gradually get thinner and weaker, in a way that is unhealthy:', 'You get thinner every time I see you, Sara - you''re wasting away!', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40599, 'waste no time', 'to start doing something immediately:', 'Caroline wasted no time in tackling her new responsibilities.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40600, 'waste not, want not', 'said to advise someone not to waste anything, because they might need it in the future', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40601, 'waste of space', 'a person or thing that is not useful or helpful:', 'That man is a total waste of space.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40602, 'waste your breath', 'If you waste your breath, you spend time and energy trying to give advice that is ignored:', 'Honestly, you''re wasting your breath - he doesn''t want to hear what anyone else has got to say.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40603, 'wasted on someone', 'If you say that something is wasted on someone, you mean that its quality is too high for that person and they will not understand its true value:', 'I''m not going to serve that good coffee to Chris and Melanie - it would be wasted on them.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40604, 'watch it', 'used to tell someone to be careful:', 'Watch it - you nearly knocked my head off with that plank!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40605, 'watch out for someone/something', 'to be careful to notice someone or something interesting:', 'Watch out for his latest movie, out next month.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40606, 'watch over someone', 'to protect someone and make certain that they are safe:', 'The prince has two bodyguards watching over him every hour of the day.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40607, 'watch paint dry', 'used to refer to an activity that you consider extremely boring:', '"Don''t you want to watch the football?" "To be honest, I would rather watch paint dry."', 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40608, 'watch sb like a hawk', 'to watch someone all the time, usually to make sure they do not do something bad:', 'When I was at home, mum and dad watched me like a hawk.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40609, 'watch sth like a hawk', 'to pay very close attention to something, usually to make sure nothing bad or unexpected happens:', 'I watch my online account like a hawk.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40610, 'watch the clock', 'to often notice the time and wish that it was later, especially when you are doing work that you do not like', NULL, 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40611, 'watch the world go by', 'to look at people as they go past:', 'I love sitting in the park watching the world go by.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40612, 'watch this space', 'used to say that there will very soon be an exciting change in the situation.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40613, 'watch your back', 'to be careful of the people around you, making certain that they do nothing to harm you:', 'I have to watch my back at work - there are a lot of people who would like my job.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40614, 'watch your step', 'be careful about how you behave, or you will get into trouble:', 'He''ll have to watch his step if he wants to keep that job of his!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40615, 'water something down', 'to add water to a drink, usually an alcoholic drink, in order to make it less strong', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40616, 'water something down', 'to deliberately make an idea or opinion less extreme, usually so that other people will accept it:', 'The party has watered down its ideals in order to appeal to the centre ground.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40617, 'water under the bridge', 'problems that someone has had in the past that they do not worry about because they happened a long time ago and cannot now be changed:', 'Yes, we did have our disagreements but that''s water under the bridge now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40618, 'watery grave', 'death by drowning (= dying because you cannot breathe underwater):', 'It was off the coast of Italy that Shelley went to his watery grave.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40619, 'wave after/upon wave', 'large quantities or groups of something, one after another:', 'Allied planes launched wave after wave of air attacks on the city.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40620, 'wave someone off', 'to wave to someone as they leave a place in order to say goodbye:', 'We went outside to wave her off.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40621, 'wave someone/something down', 'to make a driver stop their vehicle by waving your arms up and down:', 'If a car comes along, wave it down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40622, 'wave something aside', 'to refuse to consider what someone says:', 'She waved aside all my objections.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40623, 'wave/say goodbye to something', 'to accept that you will no longer have something you value or that you will not get something you hoped to receive:', 'Well, if you''ve argued with your boss you can wave goodbye to any chances of promotion!', 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40624, 'wave/show/fly the flag', 'to show support for the country, group, or organization that you belong to', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40625, 'wax and wane', 'to grow stronger and then weaker again:', 'His commitment to democracy and free markets has waxed and waned with his political fortunes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40626, 'way of life', 'the manner in which a person lives:', 'Sleeping in doorways, begging for food and money - it''s not an enviable way of life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40627, 'way round', 'a way of dealing with or avoiding a problem:', 'There''s no way round this problem.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40628, 'way to go!', 'used to tell someone they have done well, or used humorously when someone has done something stupid:', 'I heard you girls won the contest. Way to go!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40629, 'way/direction the wind blows', 'If a person tries to discover which way the wind blows/is blowing, they try to discover information about a situation, especially other people''''s opinions, before they take action:', 'I think I''ll see which way the wind is blowing before I vote at the board meeting.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40630, 'ways and means', 'The ways and means of achieving something are the methods and other things needed to make it happen:', 'With computer technology, even people working on their own have the ways and means to produce professional-looking documents.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40631, 'we''''ll (soon) see about that', 'used when you are angry about something that you feel is unfair and that you intend to stop happening:', 'He wants to park his car on my lawn? Well, we''ll soon see about that!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40632, 'weak at the knees', 'If you go weak at the knees, you lose your strength and feel you are going to fall over, usually because of seeing or talking about either someone you are very attracted to or because of something unpleasant or frightening:', 'The thought of kissing him made me go weak at the knees.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40633, 'wean someone off something', 'to make someone gradually stop using something that is bad for them:', 'It''s difficult to wean addicts off cocaine once they''re hooked.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40634, 'wean someone on something', 'If someone is weaned on something, they have learned about and been influenced by it when young:', 'This generation has been weaned on computer games.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40635, 'wear (something) away', 'to become thin and disappear after repeated use or rubbing, or to cause something to become thin and disappear in this way:', 'In some diseases, the protective layer in a joint wears away.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40636, 'wear off', 'If a feeling or the effect of something wears off, it gradually disappears:', 'Most patients find that the numbness from the injection wears off after about an hour.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40637, 'wear on', 'If a period of time wears on, it seems to pass very slowly:', 'She felt less confident about finishing the work as the week wore on.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40638, 'wear sackcloth and ashes', 'to show by your behaviour that you are very sorry for something you did that was wrong', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40639, 'wear someone down', 'to make someone feel tired and less able to deal successfully with a situation:', 'Both sides are trying to wear the other down by being obstinate in the negotiations.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40640, 'wear someone out', 'to make someone extremely tired:', 'Walking around a museum all day really wears you out.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40641, 'wear (something) out', 'to use something so much that it is damaged and cannot be used any more, or to become damaged in this way:', 'Moving parts in engines wear out much more quickly than stationary parts.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40642, 'wear the pants', '(especially of a woman) to be the person in a relationship who is in control and who makes decisions for both people:', 'Brian may seem domineering, but it''s Lisa that really wears the pants in that relationship.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40643, 'wear the trousers', '(especially of a woman) to be the person in a relationship who is in control and who makes decisions for both people:', 'Blake may seem bossy, but it''s Lisa that really wears the trousers in that relationship.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40644, 'wear thin', 'If your patience wears thin, you become less and less patient:', 'I''ve warned you several times about being late and my patience is wearing thin.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40645, 'wear thin', 'If something such as a joke wears thin, it becomes boring or annoying or stops being funny or effective, because it has been seen, heard, or used too much:', 'Tony, the joke is beginning to wear thin now - it''s time to stop.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40646, 'wear your heart on your sleeve', 'to make your feelings and emotions obvious rather than hiding them', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40647, 'weasel out (of something)', 'to avoid doing something that you have agreed to do, especially by being dishonest:', 'Although they had signed the contract they tried to weasel out of the deal later.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40648, 'weather the storm', 'If someone or something weathers the storm, they successfully deal with a very difficult problem:', 'In the next few days we will see if the ambassador can weather the political storm caused by his remarks.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40649, 'wedded to something', 'believing strongly in something:', 'He remains wedded to the free-enterprise system.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40650, 'wedded to something', 'If something is wedded to something else, the two are closely connected:', 'San Diego''s economy is wedded to the military.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40651, 'weed something/someone out', 'to get rid of unwanted things or people from a group:', 'The first round of interviews only really serves to weed out the very weakest of applicants.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40652, 'week after week', 'for many weeks, for a long time, or usually:', 'I get up very early, week in, week out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40653, 'weigh a ton', 'to be very heavy:', 'What on earth have you got in this bag, Elaine? It weighs a ton!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40654, 'weigh in', 'to be officially weighed before competing in a sport, especially boxing or horse racing:', 'Tyson weighed in at 245 lb for the fight.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40655, 'weigh in', 'to become involved in an argument or discussion in a forceful way:', 'Several leading architects weighed in with criticisms regarding the design of the new museum.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40656, 'weigh on someone/something', 'If a problem or responsibility weighs on you, it makes you worried or unhappy:', 'He''s under huge pressure at work and it''s really weighing on him.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40657, 'weigh someone/something down', 'If someone or something is weighed down with something, they are carrying a lot of or too much of it:', 'Weighed down with supplies, they found the steep path difficult to climb.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40658, 'weigh someone down', 'to make a person feel worried and unhappy because of problems, responsibilities, and duties:', 'I thought she looked somehow older, weighed down by all her new responsibilities.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40659, 'weigh something out', 'to measure an amount of something:', 'Will you weigh out two kilograms of flour for me please?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40660, 'weigh something up', 'to think carefully about the advantages or disadvantages of a situation before making a decision:', 'I''m weighing up my options before I decide to apply for the job.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40661, 'weigh someone/something up', 'to form an opinion about someone''''s abilities and character or a situation by thinking about him, her, or it carefully:', 'I weighed up my chances of escape, and decided to wait for a better moment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40662, 'weigh your words', 'to carefully think about everything you are going to say before you say it:', 'He gave evidence to the court, weighing each word as he spoke.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40663, 'weight off your mind', 'a worry that you had but that is now gone:', 'It was a weight off my mind, knowing she arrived home safe.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40664, 'well and truly', 'completely:', 'The party was well and truly over when he arrived.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40665, 'well away', 'completely involved in what you are doing:', 'He was soon well away on (= talking a lot about) his favourite subject of steam train conservation.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40666, 'well away', 'very drunk:', 'After five pints of lager and a couple of whiskies I was well away (= drunk).', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40667, 'well in (with)', 'to have a good relationship with someone in which they like you and from which you get an advantage:', 'He''s well in with the boss, these days.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40668, 'well out of something', 'lucky not to be involved:', '"Did I tell you the company went bust the month after I left?" "Really? Oh, you''re well out of that!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40669, 'well, I never (did)!', 'said when you are very surprised at something:', '"Sophie''s brother''s been married seven times." "Well, I never (did)!"', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40670, 'went out with the ark', 'If an object or method went out with the ark, it has not been used for a long time.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40671, 'wet your pants', 'to urinate in your clothes:', 'Tilly had wet her pants so I was looking for somewhere to change her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40672, 'wet your whistle', 'to have an alcoholic drink', NULL, 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40673, 'whang on', 'to talk or write a lot about something, often in a way that is annoying:', 'I spent 700 words whanging on about how happy I am that she''s found love.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40674, 'what ... for?', 'why:', 'What did you do that for?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40675, 'what I wouldn''''t give for something', 'used to say that you want something very much:', 'What I wouldn''t give for a cold drink!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40676, 'what a business!', 'used to mean that something was annoying and caused a lot of trouble for you:', 'It took ages to put together the documentation needed to get into the country - what a business!', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40677, 'what about?', 'used to suggest something:', 'What about Lola - Shall we invite her?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40678, 'what an idea!', 'something you say to show that you think a suggestion is stupid:', 'I can''t turn up at a funeral in a pink jacket. What an idea!', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40679, 'what are friends for?', 'said to a friend who has thanked you for doing something special for them', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40680, 'what are you going to do?', 'used to say that there is nothing you can do to make a situation better', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40681, 'what are you like?', 'used when someone has said or done something silly:', '"Of course Emma''s only worry was whether her lipstick had smudged." "Emma! What is she like?"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40682, 'what do you bet?', 'used to say that it is very likely that something is true or will happen', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40683, 'what do you have to say for yourself?', 'used to ask someone to explain why they have done something bad:', 'Well, you''ve ruined my car - what have you got to say for yourself?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40684, 'what do you know', 'used for expressing surprise:', 'Well, what do you know? The flight arrived on time.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40685, 'what do you mean?', 'used to show that you are annoyed or that you disagree:', 'What do you mean, it was my fault?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40686, 'what do you say', 'infml used for making a suggestion:', 'What do you say we sell the car?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40687, 'what good is ...', 'a way of asking what the purpose of (doing) something is:', 'What good is sitting alone in your room?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40688, 'what if?', 'used to ask about something that could happen in the future, especially something bad:', 'What if the bus is late?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40689, 'what is he, are they, etc. like?', 'said to ask someone to describe someone or something to you:', 'What was her boyfriend like?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40690, 'what is someone/something like?', 'something you say to ask someone to describe someone or something:', 'You''ve met Jane''s new girlfriend, haven''t you? What''s she like?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40691, 'what makes someone tick', 'If you know what makes someone tick, you understand why that person behaves the way he or she does.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40692, 'what more do you want - jam on it?', 'used to say that someone should be grateful for what they have or have been offered, and not demand something better:', 'They''ve given him a holiday in Italy. What more does he want - jam on it?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40693, 'what of it?', 'used to rudely say that you do not think something is important:', '"That''s the third time you''ve done that!" "Yeah, what of it?"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40694, 'what on earth', 'used for showing surprise:', 'What on earth is going on in there?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40695, 'what price...?', 'said when you think it is possible that the admiration, success, etc. that has been achieved was not worth all the suffering it has caused:', 'What price victory when so many people have died in the struggle?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40696, 'what someone is (really) made of', 'how strong, clever, or brave someone is:', 'The race next week will be a chance for her to show what she''s made of.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40697, 'what someone says, goes', 'said to mean that you must do whatever a particular person says:', 'Around here, kid, what I say, goes!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40698, 'what the actual fuck?', 'used to emphasize that you do not understand what is happening or why someone has done something:', 'What the actual fuck is wrong with you, man?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40699, 'what the blazes...?', 'used to give force to something you feel angry about:', 'What the blazes did he do that for?', 'idiom', NULL, NULL, 'old-fashioned, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40700, 'what the heck', 'used to say that you will do something although you know you should not do it:', 'The doctor said I shouldn''t drink, but what the heck.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40701, 'what the hell', 'said when you suddenly realize that your plan is not important to you and that you will do something else:', 'I was supposed to be working this evening but what the hell - I''ll see you at the bar in half an hour.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40702, 'what the hey', 'used to ask a question when you are angry or surprised:', 'Wait! What are you doing to me? What the hey?', 'idiom', NULL, NULL, 'spoken', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40703, 'what the hey', 'used to say that something does not matter:', 'We''re not going to make any money out of it, but what the hey.', 'idiom', NULL, NULL, 'spoken', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40704, 'what with', 'used to talk about the reasons for a particular situation, especially a bad or difficult situation:', 'I''m very tired, what with travelling all day yesterday and having a disturbed night.', 'idiom', 'C2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40705, 'what with one thing and another', 'You say what with one thing and another when you want to explain that the reason you have failed to do something is because you have been very busy:', 'What with one thing and another, I forgot to call you yesterday.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40706, 'what you lose on the swings you gain on the roundabouts', 'said to mean that the positive and negative results of a situation or action balance each other:', '"The route through town would be shorter, but there''ll be more traffic." "Well, it''s just swings and roundabouts."', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40707, 'what you see is what you get', 'said to show that there is nothing hidden', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40708, 'what''''s cooking?', 'used to ask about what is happening or what someone is planning:', 'Hi there! What''s cooking? Are we going out?', 'idiom', NULL, NULL, 'old-fashioned, slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40709, 'what''''s done is done', 'said when you cannot change something that has already happened', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40710, 'what''''s eating someone?', 'used to ask why someone seems angry or upset:', 'Jack''s in a strange mood - I wonder what''s eating him?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40711, 'what''''s it worth (to you)?', 'said when you want to know what someone will give you if you give them the piece of information they have asked for:', '"Do you know where Dave''s living now?" "What''s it worth?"', 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40712, 'what''''s more', 'used to add something surprising or interesting to what you have just said:', 'The decorations were absolutely beautiful and what''s more, the children had made them themselves.', 'idiom', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40713, 'what''''s not to like?', 'used to say that you think something is very good, and that nobody could disagree with your opinion :', 'It''s a big house with a swimming pool. What''s not to like?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40714, 'what''''s on', 'used to mean "what is happening". This phrase is often used as the title of the part of a newspaper that tells you about events and entertainment happening in the next week or month.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40715, 'what''''s sauce for the goose is sauce for the gander', 'said to emphasize that if one person is allowed to do something or to behave in a particular way, then another person must be allowed to do that thing or behave in that way, too', NULL, 'idiom', NULL, NULL, 'old-fashioned, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40716, 'what''''s something in aid of?', 'said when you want to know the reason for something:', 'What''s all this shouting in aid of?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40717, 'what''''s that (all) about (then)?', 'used when you do not understand why something or someone is so popular or fashionable:', 'Pierced tongues - what''s that about, then?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40718, 'what''''s the betting?', 'used to say that it is very likely that something is true or will happen:', 'What''s the betting Dan forgets to bring the tickets?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40719, 'what''''s the big idea?', 'used to ask someone why they have done something annoying:', 'What''s the big idea? I was watching that programme!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40720, 'what''''s the damage?', 'used to ask how much you have to pay for something', NULL, 'idiom', NULL, NULL, 'informal, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40721, 'what''''s the drill for something?', 'used to ask what the usual, correct way of doing or getting something is:', 'What''s the drill for getting paid for my expenses?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40722, 'what''''s the magic word?', 'said to a child who has not said "please" when asking for something:', '"Can I have another chocolate?" "What''s the magic word?" "Please."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40723, 'what''''s the score?', 'used to ask someone about what is going to happen, especially when arrangements have been confused:', 'What''s the score, then - are they coming?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40724, 'what''''s the use of...?', 'used to tell someone to stop worrying because worrying will not help:', 'Try not to get depressed - after all, what''s the use of worrying?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40725, 'what''''s the world coming to?', 'something you say that means that life is not as pleasant or safe as it was in the past:', 'What''s the world coming to when you can''t leave your house for five minutes without someone trying to break in and rob you?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40726, 'what''''s up?', 'used to ask someone what the problem is:', 'What''s up - why does everyone look so serious?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40727, 'what''''s up?', 'used as a friendly greeting and to ask someone how they are and what is happening:', 'What''s up, bro? How are you doing?', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40728, 'what''''s what', 'the facts of a situation:', 'Gloria will know what''s what.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40729, 'what''''s with something?', 'used to say that you do not understand something, or to ask for an explanation of something:', 'The Greens have always had this public education policy so what''s with the big shock to people?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40730, 'what''''s your game?', 'something you ask when you want to know what someone is doing or secretly planning to do:', 'The porter saw me climbing over the wall and shouted "Hey you, what''s your game?"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40731, 'what, how, why, etc. in the world', 'used to emphasize your surprise when asking a question:', 'What in the world are you doing in the cupboard?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40732, 'what/whatever someone says goes', 'used to mean that you have to do what someone says:', 'It was Helen''s idea and what Helen says goes.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40733, 'what/where/how/why the devil', 'used to give emphasis to a question:', 'What the devil are you doing?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40734, 'what’s the matter', 'used for asking someone if there is a problem:', 'You look worried – what’s the matter?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40735, 'wheel around', 'to turn around quickly:', 'She wheeled around to face him and saw him take out a gun.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40736, 'wheel round', 'to turn round quickly:', 'She wheeled round to face him and saw him take out a gun.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40737, 'wheel something out', 'to use something or someone that you have used many times before in a way that is boring for other people:', 'Every time we have this argument you wheel out the same old statistics, and I''m still not convinced!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40738, 'wheels within wheels', 'hidden or unknown things that influence a particular situation, making it more complicated than it at first seems', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40739, 'when all is said and done', 'said when you are about to tell someone the most important fact they should remember in a situation:', 'When all is said and done, you can only do your best.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40740, 'when hell freezes over', 'If you say that something will happen when hell freezes over, you mean that it will never happen.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40741, 'when in Rome (do as the Romans do)', 'when you are visiting another place, you should follow the customs of the people in that place:', 'I don''t drink wine usually but on holiday, well, when in Rome...', 'idiom', NULL, NULL, 'SAYING', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40742, 'when it rains it pours', 'said when one bad thing happens, followed by a lot of other bad things that make a bad situation worse', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40743, 'when push comes to shove', 'when all the easy answers to a problem have not worked, and something else must be tried:', 'Only a few people were there to help me when push came to shove.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40744, 'when someone was a (mere) twinkle in their father''''s eye', 'at a time before someone was born', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40745, 'when the chips are down', 'when you are in a very difficult or dangerous situation, especially one that makes you understand the true value of people or things:', 'One day when the chips are down, you will know who your true friends are.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40746, 'when the going gets rough/tough', 'when a situation becomes difficult or unpleasant:', 'I run the farm on my own but a local boy helps me out when the going gets tough.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40747, 'when the going gets tough, the tough get going', 'said to emphasize that when conditions become difficult, strong people take action', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40748, 'where someone is coming from', 'the feelings someone has that cause that person to have a particular opinion:', 'I don’t agree with you entirely, but I understand where you’re coming from.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40749, 'where there''''s a will there''''s a way', 'used to mean that if you are determined enough, you can find a way to achieve what you want, even if it is very difficult', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40750, 'where there''''s muck there''''s brass', 'said to mean that a lot of money can be made from business activities that are dirty or unpleasant', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40751, 'where there''''s smoke there''''s fire', 'If unpleasant things are said about someone or something, there is probably a good reason for it:', 'She says the accusations are not true, but where there''s smoke there''s fire.', 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40752, 'where to turn', 'what to do or whom to ask for help:', 'She had no money and didn’t know where to turn for help.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40753, 'whether or not', 'used for saying that it is not important which of two possibilities is true:', 'Whether or not you like it, I’m going out tonight.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40754, 'which is which', 'used in expressions that relate to being able to see the difference between two very similar things or people:', 'For the first few months the babies looked so alike I couldn''t tell which was which.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40755, 'which way to turn', 'what to do or whom to ask for help:', 'Economic uncertainty left many companies not knowing which way to turn.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40756, 'while sb is at it', 'at the same time as or in addition to doing something else:', 'I''m contributing to the economy and enjoying myself while I''m at it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40757, 'while something away', 'to spend time in a relaxed way because you have nothing to do or you are waiting for something else to happen:', 'We whiled away the afternoon playing cards in front of the fire.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40758, 'while the cat''''s away, the mice will play', 'said when the person who is in charge of a place is not there, and the people there behave badly', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40759, 'while the going is good', 'while an opportunity lasts:', 'Many people fear that the newly elected government will be ousted in a military coup and are leaving their country while the going is good.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40760, 'whip someone into something', 'If you whip someone into a particular state, you quickly and effectively cause them to be in that state:', 'Karl Smith, the 19-year old singer, had whipped the crowd of teenage girls into a frenzy merely by removing his shirt.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40761, 'whip something up', 'to encourage or cause people to have strong feelings about something:', 'She criticized the organization for trying to whip up anti-immigrant prejudice.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40762, 'whip something up', 'to make food or a meal very quickly and easily:', 'I have just enough time to whip up an omelette.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40763, 'whip something/someone into shape', 'to take action to get something or someone into the good condition that you would like:', 'to whip the economy into shape
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40764, 'whiter than white', 'never doing anything wrong:', 'I was never convinced by the image of the whiter than white princess depicted in the press.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40765, 'whittle away at something', 'to gradually reduce the size or importance of something:', 'These measures will whittle away at the budget deficit.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40766, 'whittle something down', 'to gradually reduce the size of something or the number of people in a group:', 'We had 80 applicants for the job, but we''ve whittled them down to six.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40767, 'who can say?', 'no one knows:', '"Is it possible?" "Who can say?"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40768, 'who cares', 'used for showing you are not interested in something:', '“There’s a dorm meeting tonight.” “Who cares?”', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40769, 'who needs...?', 'used to mean that the thing referred to is not necessary or useful, or causes trouble:', 'Men! Who needs them?', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40770, 'who shall remain nameless', 'used when you are telling people about a bad thing that someone else has done:', 'One boy, who shall remain nameless, has been late every day this week.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40771, 'who would have thought', 'used for showing surprise at a piece of information:', 'She’s written two novels since graduating? Who’d have thought?', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40772, 'who would have thought it?', 'used to say that you are very surprised something has happened:', 'So, Alex is going out with Hannah. Who would have thought it?', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40773, 'who would''''ve thunk it?', 'used for expressing surprise, or sometimes in a humorous way when something is not at all surprising:', 'The songwriter, singer and entertainer became a US congressman. Who would''ve thunk it?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40774, 'who''''s who', 'the people who are most important in a particular group', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40775, 'who''''s who', 'a book containing information about the world''''s richest or most famous people:', 'The guest list reads like a Who''s Who of top American businessmen.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40776, 'whoop it up', 'to enjoy yourself in a noisy and excited way', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40777, 'why don''''t you...?', 'used to make a suggestion:', 'Why don''t you come with us?', 'idiom', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40778, 'why keep a dog and bark yourself?', 'said when you want to know why someone would do something himself or herself when that person already pays someone else to do it', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40779, 'why not...?', 'used to make a suggestion or to express agreement:', 'Why not use my car? You''ll fit more in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40780, 'wide open to something', 'likely to be influenced by something:', 'I’m wide open to suggestions.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40781, 'wig out', 'to react or behave in a very excited or wild way:', 'Sometimes he''d wig out in the studio and break stuff and just split.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40782, 'wild about something', 'to like something a lot:', 'I’m not wild about apples.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40783, 'wild horses wouldn''''t drag me', 'If you say wild horses would not drag you somewhere, you mean that nothing could persuade you to go there:', 'Wild horses wouldn''t drag me to a party tonight.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40784, 'wilderness years', 'a period of time when someone, such as a politician, no longer has a position of authority, fame, or success and is not in the news:', 'His wilderness years in the Eighties were spent mainly in Los Angeles.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40785, 'will do', 'used to agree to do something that someone has asked you to do:', '"Can you ask them to come in tomorrow afternoon?" "Will do."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40786, 'will have', 'used for referring to the past from a point in the future:', 'By the time we get there, Jim will have left.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40787, 'will never hear the end of it', 'If you say you will never hear the end of it, you mean that someone is repeatedly going to speak proudly, disapprovingly, etc. about something:', 'If Linda gets that promotion, we''ll never hear the end of it.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40788, 'will not take no for an answer', 'to not allow someone to refuse what you have offered:', 'I told Steve I''m not interested, but he keeps asking me out - he won''t take no for an answer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40789, 'wimp out', 'to decide not to do something because you are too frightened:', 'I was going to do a parachute jump but I wimped out at the last minute.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40790, 'win (something) hands down', 'to win something/beat someone very easily:', 'She won the debate hands down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40791, 'win hands down', 'to win very easily', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40792, 'win big', 'to win easily or win a lot:', 'He could win big if he gets the voters out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40793, 'win big', 'to gain or make a lot of money:', 'Most of the investors should win big.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40794, 'win out', 'to succeed after a lot of difficulty:', 'The more cautious approach won out in the end.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40795, 'win sb/sth back', 'to get something that you had before but lost temporarily:', 'The telecoms giant cut prices in a move to win back customers from competitors.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40796, 'win someone over', 'to persuade someone to support you or agree with you, often when they were opposed to you before:', 'He''s not sure about the idea, but I''m sure we''ll win him over in the end.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40797, 'win someone round', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40798, 'win the day', 'to persuade people to support your ideas or opinions', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40799, 'win through', 'to finally succeed after trying hard to achieve something:', 'Most people are fairly confident that the workers will win through in the end.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40800, 'win/gain your spurs', 'to achieve something that proves that you are skilled in a particular type of activity and to therefore win the respect of other people:', 'He won his political spurs fighting hospital closures during his time as a local councillor in Bristol.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40801, 'wind (something) down', 'to end gradually or in stages, or to cause something to do this:', 'The government intends to wind the scheme down in the spring.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40802, 'wind (something) down', 'If a business or organization winds down, or if someone winds it down, the amount of work it does is gradually reduced until it closes completely:', 'They''re winding down their operations abroad because they''re losing money.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40803, 'wind down', 'to gradually relax after doing something that has made you tired or worried:', 'When he goes on holiday, it takes him the first couple of days just to wind down.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40804, 'wind something up', 'to close a business or organization:', 'Lawyers were called in to wind up the company.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40805, 'wind up', 'to find yourself in an unexpected and usually unpleasant situation, especially as a result of what you do:', 'If he keeps doing stuff like that he''s going to wind up in prison!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40806, 'wind (something) up', 'to end, or to make an activity end:', 'I think it''s about time we wound this meeting up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40807, 'wind someone up', 'to annoy or upset someone:', 'It really winds me up when he goes on about teachers having an easy life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40808, 'wind someone up', 'to tell someone something that is not true in order to make a joke:', 'Are you serious or are you just trying to wind me up?', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40809, 'wine and dine someone', 'to entertain someone with food and drink, esp. expensive food and drink:', 'They wine and dine clients in festive tents, promoting their image of achievement and success.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40810, 'wink at something', 'to pretend not to notice something bad that is happening because it is more convenient for you', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40811, 'winkle something/someone out', 'to get or find something or someone with difficulty:', 'I managed to winkle the truth out of him eventually.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40812, 'wipe something down', 'to clean the surface of something, such as a table, with a cloth:', 'Every night we wipe the tables down before we shut the restaurant.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40813, 'wipe something off something', 'to remove something from something:', 'All their customer information was wiped off the computer by a virus.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40814, 'wipe something off the map', 'to destroy completely:', 'There are bombs so powerful that whole nations could be wiped off the map by them.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40815, 'wipe something out', 'to destroy something completely:', 'Whole villages were wiped out in the fighting.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40816, 'wipe out', 'to lose control, especially in a vehicle, and have an accident:', 'I was going too fast and I wiped out on the bend.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40817, 'wipe something up', 'to remove a substance, usually liquid, with a cloth or something similar:', 'I was just wiping up the soup that you spilled in the kitchen.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40818, 'wipe the floor with someone', 'to defeat someone very easily:', '"I hear Italy beat France in the semifinals last night." "Beat them? They wiped the floor with them!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40819, 'wipe the slate clean', 'to start a new and better way of behaving, forgetting about any bad experiences in the past:', 'A new relationship presents you with the opportunity to wipe the slate clean.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40820, 'wipe the smile off someone''''s face', 'to make someone feel less happy or confident, especially someone who is annoying you because they think they are very clever:', 'Tell him you saw Helena at the cinema with another guy - that should wipe the smile off his face!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40821, 'wire sth up (to sth)', 'to connect a piece of electrical equipment to something else, or to connect the wires inside it so that it works:', 'An increasing number of homes are wired up to receive HD TV.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40822, 'wise to something', 'infml aware of a situation or way of doing something, esp. one that is dishonest:', 'He calls in sick almost every Monday with some phony story – I’m wise to him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40823, 'wise up', 'to start to understand a situation or fact and believe what you hear about it, even if it is difficult or unpleasant:', 'Those who think this is a harmless recreational drug should wise up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40824, 'wish something away', 'to do nothing and hope that a problem will disappear:', 'Some people seem to think if they wish the disease away, then it will go away.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40825, 'wish you had never been born', 'to be extremely unhappy:', 'When I''ve finished with you you''re going to wish you''d never been born!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40826, 'with (all due) respect', 'used to express polite disagreement in a formal situation:', 'With all due respect, Sir, I cannot agree with your last statement.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40827, 'with (brass) knobs on', 'If you describe something as a particular thing with knobs on, you mean it has similar qualities to that thing but they are more extreme:', 'Disney World was like an ordinary amusement park with knobs on.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40828, 'with a bang', 'If something starts, ends, returns, etc. with a bang, it starts, ends, etc. in a very exciting and noticeable way:', 'She took some time off last year, but she''s back with a bang with her new album.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40829, 'with a capital A, B, etc.', 'said after the name of a particular quality to say that it is very strong, using its first letter:', 'He''s trouble with a capital T!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40830, 'with a difference', 'used to say that something is unusual, and more interesting or better than other things of the same type:', 'Try new Cremetti - the ice cream with a difference.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40831, 'with a small "c", "d", etc.', 'used to say something is more general or less extreme than the usual meaning:', 'UK She is deeply conservative with a small "c" (= has traditional values, rather than being a member or supporter of the Conservative Party).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40832, 'with a vengeance', 'with great force or extreme energy:', 'He''s been working with a vengeance over the past few weeks to make up for lost time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40833, 'with a view to doing something', 'with the aim of doing something:', 'These measures have been taken with a view to increasing the company''s profits.', 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40834, 'with a will', 'with energy and determination:', 'They worked with a will and had cleared the path by 10 a.m.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40835, 'with all my heart', 'completely:', 'I love you with all my heart.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40836, 'with any luck', 'used before describing an event or a result that you are hoping for:', 'With any luck (= I hope that) we should get to Newcastle by early evening.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40837, 'with bells on', 'To do something or go somewhere with bells on is to do it or go there eagerly:', '"Are you coming to Paul''s tonight." "Sure, I''ll be there - with bells on."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40838, 'with child', 'fml pregnant:', 'The painting is of a woman with child.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40839, 'with dispatch', 'quickly and effectively', NULL, 'idiom', NULL, NULL, 'old-fashioned, formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40840, 'with every fiber of your being', 'If you want or believe something with every fiber of your being, you want or believe it very much:', 'She wanted to win the race with every fiber of her being.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40841, 'with every fibre of your being', 'If you want or believe something with every fibre of your being, you want or believe it very much:', 'She wanted to win the race with every fibre of her being.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40842, 'with flying colors', 'If you do something such as pass an exam with flying colors, you do it very successfully.', NULL, 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40843, 'with flying colours', 'If you do something such as pass an exam with flying colours, you do it very successfully.', NULL, 'idiom', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40844, 'with friends like you, who needs enemies?', 'said to or about someone who says he or she is your friend but who is treating you very badly', NULL, 'idiom', NULL, NULL, 'humorous, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40845, 'with guns blazing', 'If you do something, especially argue, with guns blazing, you do it with a lot of force and energy:', 'I went into the meeting with guns blazing, determined not to let him win.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40846, 'with might and main', 'with as much effort as possible:', 'They shouted with might and main but nobody came to rescue them.', 'idiom', NULL, NULL, 'old-fashioned, literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40847, 'with no thought for something', 'not thinking about a particular thing:', 'With no thought for his own safety, he rushed towards the burning car.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40848, 'with one voice', 'If a group of people express an opinion or decide something with one voice, they all agree:', 'The committee decided with one voice to accept the proposal.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40849, 'with open arms', 'in a very friendly way', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40850, 'with pleasure', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40851, 'with that', 'and then, or after doing or saying that:', '"I still think you''re wrong," he said and with that he drove away.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40852, 'with the best of them', 'as well as anyone:', 'He can dance with the best of them.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40853, 'with the best will in the world', 'used to mean "I would like to if I possibly could", in a situation where you cannot do something:', 'With the best will in the world, I can''t employ him in the shop unless I can trust him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40854, 'with the naked eye', 'without using any special device for making images larger:', 'We live miles away, but on a clear night, you can see the city skyscrapers with the naked eye.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40855, 'with the slate wiped clean', 'with your past mistakes or crimes forgotten', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40856, 'with the wisdom of hindsight', 'with the knowledge that experience gives you:', 'With the wisdom of hindsight we now know that the old-fashioned aerosol sprays were a mistake.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40857, 'with your bare hands', 'without using any type of tool or weapon:', 'He wrestled the lion to the ground with his bare hands.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40858, 'with your eyes closed', 'very easily:', 'I can find your house with my eyes closed.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40859, 'with your eyes closed/shut', 'If you could do something with your eyes closed or shut, you could do it very easily because you have done it many times:', 'I could do that journey with my eyes shut.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40860, 'with your eyes closed/shut', 'noticing nothing:', 'Half the time you go around with your eyes shut.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40861, 'with your eyes open', 'knowing about all the problems there could be with something you want to do:', 'I went into this marriage with my eyes open.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40862, 'with your last/dying breath', 'just before you die:', 'She asked him with her dying breath to take care of her child.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40863, 'with your own fair hand(s)', 'used to say that you have made something yourself:', '"Where did you get this cake?" "I made it with my own fair hands."', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40864, 'wither on the vine', 'If something withers on the vine, it is destroyed very gradually, usually because no one does anything to help or support it:', 'When the new resort was built, the tourist trade in smaller hotels withered on the vine.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40865, 'within an inch of something', 'very close to something:', 'She came within an inch of losing her life.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40866, 'within limits', 'to some extent, but not allowing everything:', 'I''ll pay for what you need - within limits.', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40867, 'within living memory', 'If something has happened within living memory, it can be remembered by some people who are still alive:', 'There is possibly less chance of another world war while the last one is within living memory.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40868, 'within reason', 'if you use good judgment:', 'You can say whatever you like, within reason.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40869, 'within shouting distance', 'very close:', 'We live within shouting distance of the station.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40870, 'within striking distance', 'near:', 'We live within striking distance of both Baltimore and Washington.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40871, 'within striking distance', 'very near to getting or achieving something:', 'His victory in the Brazilian Grand Prix puts him within striking distance of the world championship.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40872, 'within your memory', 'at a time that you are able to remember:', 'Women gained the vote within my grandmother''s memory.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40873, 'without (so much as) a backward glance', 'If you leave without a backward glance, you are completely happy to leave and have no sad feelings about it:', 'She left the city where she had lived all her life without a backward glance.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40874, 'without a care in the world', 'without worrying about anything:', 'Look at her, not a care in the world!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40875, 'without a murmur', 'without even a small complaint:', 'For once the children went to bed without a murmur.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40876, 'without fail', 'in every case, or for certain:', 'She takes a walk every morning without fail.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40877, 'without fear or favour', 'in an equal and fair way:', 'The appointments are made without fear or favour.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40878, 'without further ado', 'with no more delay:', 'And now, without further ado, here is our special guest speaker.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40879, 'without issue', 'If someone dies without issue, they have no children.', NULL, 'idiom', NULL, NULL, 'old-fashioned, specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40880, 'without so much as a by-your-leave', 'without asking for permission:', 'That''s twice now he''s just walked in here without so much as a by-your-leave and picked a book off the shelf!', 'idiom', NULL, NULL, 'old-fashioned, disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40881, 'witness to something', 'to say publicly, especially in a law court, that something is true or that it happened:', 'A handwriting expert witnessed to the authenticity of the letter.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40882, 'woe betide someone', 'said when there will be trouble for someone, or someone will be punished, if they do a particular thing:', 'This is the second time he''s been sent home from school this month, so woe betide him if it happens again!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40883, 'woe is me', 'said to express how unhappy you are:', 'I''m cold and wet and I don''t have enough money for the bus home. Oh woe is me!', 'idiom', NULL, NULL, 'old use, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40884, 'won''''t hear a word (said) against someone/something', 'If you won''''t hear a word said against someone or something, you refuse to believe anything bad about him, her, or it:', 'He''s completely infatuated with the woman and won''t hear a word said against her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40885, 'won''''t thank you for doing something', 'If someone won''''t thank you for doing something, they will not be pleased if you do it:', 'She won''t thank you for telling everyone how old she is.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40886, 'wonders never cease', 'an expression of surprise used when something unusual or unexpected happens:', 'Lynda actually managed to get up before ten o''clock. Wonders never cease!', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40887, 'word gets around', 'When word gets around, news spreads fast within a group of people:', '"I hear you were having drinks with a tall, dark, handsome man last night." "Wow, word gets around fast, doesn''t it?"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40888, 'word has it', 'used to refer to something that is generally thought to be true although not official or known to be a fact:', 'Word has it (that) they may separate.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40889, 'words fail me', 'said to emphasize your surprise or shock, especially at something you have just seen or been told:', '"So what did you think of Olive''s pink outfit?" "Words fail me. I''ve never seen anything quite like it!"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40890, 'work (yourself) up to something', 'to gradually prepare yourself for something difficult:', 'He''s very shy, but he''s slowly working (his way/himself) up to letting her know what he feels about her.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40891, 'work a treat', 'to operate very well:', 'This new drill works a treat on hard metals.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40892, 'work against/for someone', 'to make it more difficult, or easier, for someone to achieve something:', 'Inexperience can work against someone looking for a job.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40893, 'work at something', 'to try hard to achieve something:', 'Most couples would agree that for a marriage to succeed, both parties have to work at it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40894, 'work like a charm', 'to be very effective, possibly in a surprising way:', 'Flattery usually works like a charm on him.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40895, 'work like a dog', 'to work very hard:', 'You can work like a dog and still not make ends meet.', 'idiom', NULL, NULL, 'approving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40896, 'work on something', 'to spend time repairing or improving something:', 'His dancing technique is good, but he needs to work on his stamina.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40897, 'work on someone', 'to try to persuade or influence someone:', '[ + to infinitive ] I''m working on my father to get him to take me to the airport.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40898, 'work someone over', 'to attack and injure someone:', 'Do you want me to get some of the lads to work him over?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40899, 'work someone''''s ass off', 'a rude phrase meaning to make someone work very hard:', 'They work your ass off but they pay you well.', 'idiom', NULL, NULL, 'offensive', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40900, 'work something off', 'If you work off an unpleasant feeling, you get rid of it by doing something energetic:', 'She works off stress by running for at least half an hour every day.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40901, 'work something out', 'to do a calculation to get an answer to a mathematical question:', 'We need to work out the total cost of the project.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40902, 'work something out', 'to understand something or to find the answer to something by thinking about it:', '[ + question word ] There will be a full investigation to work out what caused the accident.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40903, 'work out', 'to exercise in order to improve the strength or appearance of your body:', 'Huw works out in the gym two or three times a week.', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40904, 'work out', 'to be the result of a calculation:', 'These figures work out differently each time I add them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40905, 'work out', 'to happen or develop in a particular way:', 'How is the new monitoring procedure working out?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40906, 'work someone out', 'to understand the reasons for someone''''s behaviour:', 'Why does he behave like that? I can''t work him out at all.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40907, 'work (something) out', 'If a problem or difficult situation works out, it gradually becomes better or satisfactory, and if you work it out, you make it better or satisfactory:', 'Don''t worry about anything - it''ll all work out (for the best) in the end, you''ll see.', 'phrasal verb', 'B2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40908, 'work the land', 'to grow crops, esp. as a job:', 'He''s the fourth generation of his family to have worked the land.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40909, 'work through something', 'to manage a problem that has many different parts step by step:', 'It''s a complex situation but we''ll work through it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40910, 'work till/until you drop', 'to work until you are so tired that you cannot work any more', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40911, 'work up something', 'to develop an emotional or physical state that you feel strongly, after a period of effort or time:', 'We worked up a real appetite climbing in the mountains.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40912, 'work someone up', 'to make yourself or another person feel upset or feel strong emotions:', 'Try not to work yourself up about the exams.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40913, 'work wonders', 'to cause improvements or have a very good effect:', 'A little flattery can work wonders.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40914, 'work wonders/miracles', 'to produce very good effects:', 'A little bit of oil works wonders on squeaky hinges.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40915, 'work your fingers to the bone', 'to work extremely hard, especially for a long time:', 'She worked her fingers to the bone to provide a home and food for seven children.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40916, 'work your way around to something', 'to prepare yourself slowly for doing something:', 'I think they''re both gradually working their way around to talking to each other again.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40917, 'work your way up', 'to achieve a better position within the organization you work for:', 'She quickly worked her way up to vice president.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40918, 'work your way up/to the top', 'to make progress in a process or structure:', 'He started as an office junior and worked his way up through the company to become a senior manager.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40919, 'work/do wonders', 'to have a very good effect:', 'Doctors have discovered that keeping a pet can do wonders for your health.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40920, 'work/go like a dream', 'to work or go extremely well, without any problems:', 'The whole plan worked like a dream.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40921, 'work/laugh/freeze, etc. your arse off', 'a rude phrase used to emphasize that someone works very hard, laughs very much, is very cold, etc.:', 'She worked her arse off to get this done.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40922, 'work/laugh/freeze, etc. your ass off', 'a rude phrase used to emphasize that someone works very hard, laughs very much, is very cold, etc.:', 'I worked my ass off for that man.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40923, 'work/play/fight your guts out', 'to work extremely hard:', 'I''ve been working my guts out these past few weeks and all he can do is criticize.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40924, 'worm something out of someone', 'to try and get information from someone that they are trying to keep secret:', 'He wasn''t going to tell me, but I managed to worm it out of him.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40925, 'worm yourself/your way into something', 'to gradually achieve a position of trust, possibly by being dishonest:', 'He wormed himself into her affections without her ever suspecting he only did it for her money.', 'phrasal verb', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40926, 'worry at something', 'to shake, pull at, or touch something repeatedly:', 'The dog was worrying at its bone.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40927, 'worry at something', 'to keep trying to find a way of solving a problem:', 'She''ll worry at those figures until she''s sure they''ve been done correctly.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40928, 'worse luck', 'said at the end of a statement to show unhappiness or anger about what has been stated:', 'I have to work on Saturday, worse luck.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40929, 'worship at the shrine/altar of something', 'to completely support or follow a particular idea, principle, etc.:', 'She thinks that young people today are becoming increasingly selfish, and worship at the shrine of individual happiness and gratification.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40930, 'worship the ground someone walks on', 'to love and admire someone very much:', 'I worship the ground you walk on - you must know that by now.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40931, 'worth it', 'enjoyable or useful despite the fact that you have to make an effort:', 'It was a long climb to the top of the hill, but the view from the top was worth it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40932, 'worth your salt', 'good at your job:', 'Any accountant worth their salt should be aware of the latest changes in taxation.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40933, 'worth your while', 'important, useful, or satisfying enough to be worth the effort you make:', 'It would be worth your while to see if you can still get tickets to the show.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40934, 'would (just) as soon', 'If you would (just) as soon do something or would sooner do something, you would prefer to do it rather than something else that is possible:', '"Would you like to go out for dinner?" "I''d just as soon stay in - I''m not feeling very well."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40935, 'would give your eyeteeth for something', 'If you would give your eyeteeth for something, you would like it very much:', 'Most people would give their eyeteeth for hair like yours.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40936, 'would not do something for all the tea in China', 'used to say that nothing could persuade you to do something:', 'I wouldn''t take that job for all the tea in China.', 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40937, 'would you like...?', 'used when offering something or inviting someone:', 'Would you like a drink?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40938, 'wouldn''''t be seen dead', 'If someone wouldn''''t be seen dead in a particular place or doing a particular thing, they would never do it, usually because it would be too embarrassing:', 'I wouldn''t be seen dead wearing a dress like that.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40939, 'wouldn''''t dream of something/doing something', 'used to say that you would not do something because you think it is wrong or silly:', 'My father is very generous, but I wouldn''t dream of actually asking him for money!', 'idiom', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40940, 'wouldn''''t have it any other way', 'used to say that you would not want a situation to be different, even though it has problems connected with it:', 'It''s never going to be easy having kids but I wouldn''t have it any other way.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40941, 'wouldn''''t hurt a fly', 'If you say that someone wouldn''''t hurt a fly, you mean they are gentle and would not do anything to injure or offend anyone.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40942, 'wouldn''''t know something if you fell over one/it', 'used to say that someone would not recognize something even if it was obvious:', 'She wouldn''t know a bargain if she fell over one!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40943, 'wouldn’t wish something on anyone', 'used for saying you would not want anyone to experience something very bad:', 'Having the flu was awful – I wouldn''t wish it on anyone.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40944, 'wrap (someone) up', 'to dress in warm clothes, or to dress someone in warm clothes:', 'Wrap up well - it''s cold outside.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40945, 'wrap something up', 'to cover or surround something in paper, cloth, or other material:', 'Have you wrapped up Jenny''s present yet?', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40946, 'wrap something up', 'to complete something successfully:', 'That just about wraps it up for today.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40947, 'wrap someone (up) in cotton wool', 'to try to protect someone too carefully:', 'You can''t wrap (up) your children in cotton wool forever.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40948, 'wrap someone around your little finger', 'to persuade someone easily to do what you want them to do:', 'She could wrap her father around her little finger.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40949, 'wrap something around someone/something', 'to put a piece of clothing or material around someone or something, usually to keep them or it warm:', 'It was so cold that he wrapped a scarf tightly around his face.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40950, 'wrap something around someone/something', 'to put part of your body, such as your fingers or arms, tightly around something or someone:', 'She wrapped her arms around her knees.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40951, 'wrap yourself in the flag', 'to show great loyalty and support for your country in a way that does not ask questions:', 'Although national pride is important to the prime minister, he does not wrap himself in the flag as his predecessor used to do.', 'idiom', NULL, NULL, 'disapproving', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40952, 'wrapped (up) in secrecy', 'If something such as plan is wrapped (up) in secrecy, the details about it are kept secret.', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40953, 'wrestle with something', 'to try very hard to deal with a problem or to make a difficult decision:', 'The government is wrestling with difficult economic problems.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40954, 'wriggle off the hook', 'If someone wriggles off the hook, they avoid a responsibility.', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40955, 'wriggle out of something', 'to avoid doing something that you do not want to do:', 'He promised he''d help me paint the living room, but now he''s trying to wriggle out of it.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40956, 'wring someone’s neck', 'used for emphasizing that you are very angry at someone:', 'I could wring her neck for getting me in such trouble.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40957, 'wring something from someone', 'to force or persuade someone to give or tell you something:', 'Congress is seeking to wring concessions from a weakened President.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40958, 'wring something from/out of someone', 'to force or persuade someone to give you something:', 'They managed to wring a few concessions from the bosses.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40959, 'wring your hands', 'If you wring your hands, you show that you are worried or unhappy:', 'Car dealers are wringing their hands over low sales this summer.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40960, 'wrinkle your nose', 'to show surprise, uncertainty, or disgust at something:', '"Oooh, yuck!" 7-year-old Pamela says, wrinkling her nose as she wipes gooey paste from her fingers onto her sweat pants.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40961, 'writ large', 'If one thing is another thing writ large, it is similar to it but larger or more obvious:', 'Hollywood is often said to be American society writ large.', 'idiom', NULL, NULL, 'formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40962, 'write back', 'to reply to someone''''s letter:', 'I''ll write back and tell her we''re coming.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40963, 'write in', 'to write a letter to a newspaper, television company, or other organization, to express an opinion or ask something:', '[ + to infinitive ] People have written in to complain about the show.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40964, 'write someone in', 'to add someone''''s name to the official list for an election in order to show that you want to vote for them:', 'a write-in candidate/campaign', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40965, 'write off/away for something', 'to write a letter to an organization asking them to send you something:', 'Did you write off for a brochure?', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40966, 'write out something', 'to write something on paper with all the necessary details:', 'Write the check out to me.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40967, 'write someone out of something', 'to change the story of a regular television or radio programme so that a particular character is not in it any more', NULL, 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40968, 'write something down', 'to write something on a piece of paper so that you do not forget it:', 'Did you write down Jo''s phone number?', 'phrasal verb', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40969, 'write something down', 'to show in a company''''s accounts (= financial records) that something is worth less than it was before:', 'The building cost £700,000 to build, but it was written down to £300,000.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40970, 'write something into something', 'to add a particular detail or rule to a document:', 'An agreement to produce five novels a year was written into her contract.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40971, 'write something off', 'to accept that an amount of money has been lost or that a debt will not be paid:', 'The World Bank is being urged to write off debts from developing countries.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40972, 'write something off', 'to be able to use the cost of something you have bought to reduce the amount of tax you owe:', 'You might be able to write off the car as a business expense.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40973, 'write something off', 'to damage a vehicle so badly that it cannot be repaired:', 'His car was completely written off in the accident.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40974, 'write someone/something off', 'to decide that a particular person or thing will not be useful, important, or successful:', 'A lot of companies seem to write people off if they''re over 50.', 'phrasal verb', 'C2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40975, 'write something up', 'to write something in a complete or final form using notes that you have made:', 'Have you written up that report yet?', 'phrasal verb', 'C1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40976, 'write someone up', 'to report someone for not obeying a law or rule:', 'The cop said he''d have to write me up for not stopping at the red light.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40977, 'written all over someone''''s face', 'If an emotion is written all over someone''''s face, it is clear what they are feeling:', 'Guilt was written all over her face.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40978, 'written in the stars', 'If you believe that something is written in the stars, you believe that it will be made to happen by a force that controls the future:', 'It was written in the stars that they would meet and fall in love.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40979, 'ye gods!', 'used to show surprise:', 'Ye gods man, what are you doing!', 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40980, 'yea or nay', 'yes or no:', 'They have the power to hire and fire managers and say yea or nay to big investment projects.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40981, 'yeah, right!', 'used when you do not believe what someone has said:', '"I always miss you when I go away ." "Yeah, right!"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40982, 'year in and year out', 'every year, especially in a way that seems boring:', 'We go to Mike''s parents every summer - it''s the same thing year in and year out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40983, 'year in, year out', 'every year, especially in a way that seems boring:', 'We go to Mike''s parents every summer - it''s the same thing year in, year out.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40984, 'yes and no', 'used when you cannot give a particular answer to a question:', '"Is the job going okay?" "Well, yes and no."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40985, 'yes, sir', 'used for expressing strong agreement:', 'He asked if he could talk to me, and I said, "Yes, sir."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40986, 'yield to something', 'to agree to do something that you do not want to do or should not do:', 'It''s very easy to yield to temptation and spend too much money.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40987, 'you and me both', 'I feel the same way as you or have had the same experience:', '"I''ve started to wonder how my life ended up as such a mess." "You and me both."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40988, 'you bet', 'used to emphasize a statement or to mean "certainly":', '"Are you coming to the party?" "You bet!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40989, 'you bet', 'used when someone thanks you :', '"Thanks for your help." "You bet. Anytime."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40990, 'you betcha', 'used to say "yes" very strongly, or to show that you are very sure about something:', 'Were there surprises? You betcha.', 'idiom', NULL, NULL, 'not standard, informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40991, 'you can bet your life', 'used to say that you are completely certain that something is true or will happen:', 'You can bet your bottom dollar that she''ll be the next president.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40992, 'you can lead a horse to water, but you can''''t make him drink', 'used to emphasize that you can make it easy for someone to do something, but you cannot force them to do it', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40993, 'you can say that again!', 'used to show that you completely agree with what someone has said', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40994, 'you can''''t judge a book by its cover', 'said to show that you cannot know what something or someone is like by looking only at that person or thing''''s appearance', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40995, 'you can''''t make a silk purse out of a sow''''s ear', 'used to mean that you cannot make something good out of something that is naturally bad', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40996, 'you can''''t make an omelet without breaking eggs', 'it is hard to achieve something important without causing unpleasant effects', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40997, 'you can''''t make an omelette without breaking eggs', 'it is hard to achieve something important without causing unpleasant effects', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40998, 'you can''''t make bricks without straw', 'used to say that you cannot make something without the necessary materials', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (40999, 'you can''''t say fairer than that', 'used to say that you think an offer or arrangement is good', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41000, 'you can''''t teach an old dog new tricks', 'said to mean that it is very difficult to teach someone new skills or to change someone''''s habits or character', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41001, 'you can''''t win ''''em all', 'something you say that means it is not possible to succeed at everything you do:', 'It would have been great to get the job but I suppose you can''t win ''em all.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41002, 'you can’t miss it', 'it is easy to find:', 'To get to the mall, go to the next traffic light and make a left – you can''t miss it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41003, 'you can’t win them all', 'no person can always succeed:', '"I was sorry to hear that someone else got the job." "Oh well, you can''t win them all."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41004, 'you could cut the atmosphere with a knife', 'used to describe a situation in which everyone is feeling very angry or nervous and you feel that something unpleasant could soon happen', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41005, 'you could have heard a pin drop', 'something that you say in order to describe a situation where there was complete silence, especially because people were very interested or very surprised by what was happening:', 'Margaret''s ex-husband turned up at the wedding. Honestly, you could have heard a pin drop.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41006, 'you could have knocked me down/over with a feather', 'said when you are extremely surprised', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41007, 'you couldn''''t make it up', 'used to express great surprise, and often disapproval, about something that has happened:', 'Millionaire tax avoiders are asking the public to donate money. You couldn''t make it up.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41008, 'you do you', 'used to say that someone should do what they think is best, what they enjoy most, or what suits their personality:', 'In fact, being one''s true self is one of the biggest pieces of advice Douglas gives. "You do you," she says.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41009, 'you don''''t say!', 'used either to express surprise or lack of surprise in a humorous and slightly unkind way:', '"He''s lost his job." "You don''t say!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41010, 'you got it', 'used to say that you will quickly do what someone has asked you to do:', '"Would you get me a coffee?" "Sure, you got it!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41011, 'you have (got) to be kidding', 'used to show that you are very surprised by what someone has said and do not accept it:', 'You want me to drive into the city? You’ve got to be kidding.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41012, 'you have no idea', 'said for emphasis when you are describing how good or bad an experience is:', 'Flying a plane is wonderful, you have no idea.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41013, 'you know', 'a phrase with little meaning, used while you are trying to think of what to say next:', 'Well I just thought, you know, I''d better agree to it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41014, 'you know', 'used when trying to help someone remember something or when trying to explain something:', 'What''s the name of that guy on TV - you know, the one with the silly voice?', 'idiom', 'B1', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41015, 'you know something?', 'said before giving an opinion or a piece of information:', 'You know something? I don''t think I like that man.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41016, 'you live and learn', 'said when you hear or discover something that is surprising:', 'I had no idea they were related. Oh well, you live and learn.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41017, 'you may well ask', 'it would be very interesting to know:', 'How could Jonathan afford to buy a new car? You may well ask.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41018, 'you mean', 'used as part of a question when you are not sure of the facts or are expressing surprise:', '"They all showed up." "You mean the entire family?"', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41019, 'you might as well be hanged for a sheep as for a lamb', 'said to mean that because the punishment for a bad action and an even worse one will be the same, you have no reason not to do the worse one', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41020, 'you must be joking', 'said in answer to something that someone has said, meaning that you do not believe they need said it seriously, or you think it is a stupid thing to say:', 'You''ve got to be joking if you think I''m going to stand in the rain watching you play tennis!', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41021, 'you name it', 'used to say there are many things to choose from:', 'Gin, vodka, whisky, beer - you name it, I''ve got it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41022, 'you never can tell', 'there is no way of knowing or being certain, esp. about the future:', 'It sounds like a nice place to live, but you never can tell – we may end up hating it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41023, 'you never know', 'said to mean there is a possibility that something good might happen, even if it is slight:', 'You never know, she might change her mind.', 'idiom', 'B2', NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41024, 'you pays your money and you takes your choice/chance', 'You are responsible for your decisions and cannot blame anyone else when what you have chosen is not successful.', NULL, 'idiom', NULL, NULL, 'informal, saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41025, 'you said it!', 'used to say that you agree with what has just been said:', '"How stupid of me to lend him that money!" "You said it!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41026, 'you scratch my back and I''''ll scratch yours', 'used to tell someone that if they help you, you will help them', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41027, 'you see', 'used when you hope someone else will understand what you are saying or asking:', 'You see, it''s better if you do your homework before dinner.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41028, 'you should be so lucky!', 'used to say that someone is very unlikely to get what they want:', '"She''s going to ask for a salary increase." "She should be so lucky!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41029, 'I should be so lucky!', 'said when what you want is extremely unlikely to happen:', '"You might win first prize." "I should be so lucky."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41030, 'you should get out more', 'used to tell someone that they are spending too much time doing things that are boring or not important:', '"I arranged all my CDs in alphabetical order." "Mmm, I think you should get out more, Mike."', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41031, 'you should have seen/heard something/someone', 'seeing or hearing something or someone would have interested or entertained you very much:', 'You should have seen her - she was furious!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41032, 'you shouldn''''t have', 'said when thanking someone who has unexpectedly done something generous, such as given you a present, to mean that they did not need to do it for you:', 'Flowers! You shouldn''t have!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41033, 'you snooze, you lose', 'used to mean that if you do not pay attention and do something quickly, someone else will do it instead of you:', 'You have to take advantage of those deals while you can. It''s a case of "you snooze you lose" in the current market.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41034, 'you the man!', 'used to praise a person who has done something well', NULL, 'idiom', NULL, NULL, 'not standard', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41035, 'you win!', 'something you say to someone who has persuaded you to do something that you did not intend to do, especially when that person has used force and you are angry:', 'Okay, you win - you can go to the party! But you''d better be home by midnight!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41036, 'you''''re a star!', 'something you say to someone when they have been nice and helpful to you', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41037, 'you''''re getting colder', 'said by children playing a guessing or searching game to tell the person who is guessing or searching that he or she is getting further away from the answer or hidden object', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41038, 'you''''re having a laugh', 'used to show that you think that what someone has just said is not reasonable or fair:', '£500 to cut down a tree - you''re having a laugh, mate!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41039, 'you''''re joking!', 'something you say to show that you are surprised by what someone has said, or do not believe it is true:', '"Hey, Maria''s leaving." "You''re joking!"', 'idiom', 'B1', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41040, 'you''''re on!', 'used as a way of expressing agreement to something happening:', '"I''ll give you £50 for your bike." "You''re on!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41041, 'you''''re telling me!', 'used to say that you strongly agree with what someone has just said:', '"Stephen''s in such a bad mood today." "You''re telling me!"', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41042, 'you''''re welcome', 'said as a polite answer when someone thanks you for doing something:', '"Thank you so much for helping." "You''re welcome."', 'idiom', 'A2', NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41043, 'you''''ve got nothing to lose', 'used to say that you cannot make things worse, or cause any disadvantages for yourself by doing a particular thing:', 'Why don''t you take the job? You''ve got nothing to lose.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41044, 'you''''ve got to laugh', 'said when you can see something funny in a difficult situation', NULL, 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41045, 'you''''ve made your bed, now lie in it', 'said to someone who must accept the unpleasant results of something they have done', NULL, 'idiom', NULL, NULL, 'saying', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41046, 'you(''''d) have to see it to believe it', 'to be so extreme that it is difficult to believe:', 'The prices in that place are so ridiculous, you''d have to see it to believe it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41047, 'you/you''''ve got this', 'used to tell someone that you believe they can or will succeed in dealing with something:', 'I know you can lose that weight! You got this!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41048, 'young at heart', 'thinking and behaving as if you are younger than you really are:', 'Dad may be nearly 90 but he''s still young at heart.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41049, 'young lady/man', 'used when you are speaking angrily to a young person:', 'Mind your language, young lady!', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41050, 'young lady/man', 'someone''''s girlfriend or boyfriend:', 'If you would bring your young man along too, we would be delighted to meet him.', 'idiom', NULL, NULL, 'old-fashioned, humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41051, 'young love', 'love between young people', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41052, 'your beauty sleep', 'the sleep that you need in order to feel and look healthy and attractive', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41053, 'your best bib and tucker', 'your best clothes that you wear on special occasions', NULL, 'idiom', NULL, NULL, 'old-fashioned', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41054, 'your best/strongest/trump card', 'your main advantage over other people', NULL, 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41055, 'your ears must be burning', 'something that you say to someone who is being talked about:', 'All this talk about Emma - her ears must be burning!', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41056, 'your eyes pop out of your head', 'a way of describing the way you look when you are extremely surprised to see something or someone:', 'When she saw the amount written on the cheque, her eyes nearly popped out of her head.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41057, 'your guess is as good as mine', 'I have no way of knowing exactly what happened or what will happen:', '"Do you think she''d go out with me if I asked her?" "Your guess is as good as mine."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41058, 'your guess is as good as mine', 'something you say when you do not know the answer to a question:', '"What''s he doing?" "Your guess is as good as mine."', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41059, 'your heart aches', 'If your heart aches, you feel sad or feel sympathy and sadness for the suffering of other people:', 'His heart ached with pity for her.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41060, 'your heart goes out to someone', 'If your heart goes out to someone who is in trouble, you feel sympathy for them:', 'Our hearts go out to the families of the victims of this terrible tragedy.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41061, 'your heart isn''''t in it', 'If your heart isn''''t in it, you do not feel interested or enthusiastic about something:', 'I tried to look interested, but my heart wasn''t in it.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41062, 'your heart skips/misses a beat', 'When your heart skips/misses a beat, you feel very excited or nervous:', 'Every time he looks at me my heart skips a beat.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41063, 'your hour has come', 'If you think your hour has come, you think you are going to die:', 'I thought my hour had come when he pointed his gun at me.', 'idiom', NULL, NULL, 'literary', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41064, 'your lips are sealed', 'you will not talk about something:', '"I want the party to be a surprise." "Don’t worry, my lips are sealed."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41065, 'your lord and master', 'a person who has authority over you, or your husband', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41066, 'your luck''''s in!', 'used to tell someone that they have been lucky or successful:', 'He''s been looking at you all evening - I think your luck''s in, Cath.', 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41067, 'your marbles', 'your mental health or your ability to think and remember clearly:', 'I think he''s losing his marbles (= starting to forget things or become crazy).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41068, 'your mind is a blank/goes blank', 'When your mind is a blank/goes blank, you cannot remember a particular thing, or you cannot remember anything:', 'I tried to remember her name, but my mind was a complete blank/went completely blank.', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41069, 'your mind is on something', 'When your mind is on something, you think about it or give attention to it:', 'I couldn''t concentrate on my work - my mind was on other things.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41070, 'your name is mud', 'If your name is mud, other people are angry with you because of something you have said or done:', 'If he doesn''t turn up tonight, his name will be mud.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41071, 'your nearest and dearest', 'your family, especially those that you live with or are very involved with', NULL, 'idiom', NULL, NULL, 'humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41072, 'your number is up', 'When your number is up, you are going to die:', 'When the plane started to shake, I just thought my number was up.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41073, 'your number is up', 'When your number is up, you can no longer continue doing a job, activity, etc.:', 'He says that a chief executive can usually tell his number is up from the staff gossip.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41074, 'your secret''''s safe with me', 'used to say that you will not tell anyone what you have just been told:', '"I''d appreciate it if you kept quiet about this." "Don''t worry - your secret''s safe with me."', 'idiom', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41075, 'your two cents'''' worth', 'your spoken opinion on a particular matter:', 'I thought I''d just throw in (= add) my two cents'' worth.', 'idiom', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41076, 'your word is your bond', 'If someone''''s word is their bond, they always keep a promise:', '"But listen, you have to promise never to tell anyone." "My word is my bond."', 'idiom', NULL, NULL, 'old-fashioned, formal', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41077, 'yours truly', 'used to mean the person who is speaking or writing, often when they are talking about something they have done unwillingly:', 'She didn''t have any money, so yours truly ended up having to lend her some.', 'idiom', NULL, NULL, 'informal, mainly humorous', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41078, 'zero in on something/someone', 'to aim a weapon directly at something or someone:', 'Modern military aircraft use computers to help them zero in on their targets.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41079, 'zero in on something', 'to direct all your attention towards a particular thing:', 'We must decide on our target market, then zero in on it.', 'phrasal verb', NULL, NULL, NULL, 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41080, 'zero to hero', 'a situation in which someone changes quickly from being unpopular or unsuccessful to being very popular or successful:', 'Reeve shot from zero to hero in the 1978 blockbuster, Superman.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41081, 'zip it', 'a rude and angry way of telling someone to stop talking:', 'Just zip it - I''m tired of listening to you complain.', 'idiom', NULL, NULL, 'slang', 'unknown', NULL, NULL, NULL, DEFAULT, 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41082, 'zip something/someone up', 'to fasten a piece of clothing by using its zip, or to help someone close the zip on a piece of clothing they are wearing:', 'Could you zip me up, please?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41083, 'zip your lip', 'to say nothing or stop talking:', 'He''s the sort of man who rarely bothers to zip his lip.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41084, 'zip your lip', 'to say nothing or stop talking:', 'He''s the sort of man who rarely bothers to zip his lip.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41085, 'zone out', 'to stop paying attention and not hear or see what is around you for a short period of time :', 'When the men start talking about football, I just zone out.', 'phrasal verb', NULL, NULL, 'specialized', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41086, 'zoom in', 'to adjust a camera to make a person or thing being photographed appear larger or closer:', 'At the beginning of the movie, the camera zooms in to show two people sitting by the side of a river.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41087, 'zoom in on something', 'to notice and give special attention to something:', 'Henry immediately zoomed in on the weakest part of my argument.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41088, 'zoom in/out', 'to (cause a camera or computer to) make the image of something or someone appear much larger and nearer, or much smaller and further away:', 'At the beginning of the film, the camera zooms in to show two people sitting by the side of a river.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Category, Registers, Difficulty, Synonyms, Antonyms, RelatedLexicon, CreatedAt, TypeId) VALUES
  (41089, 'zoom out', 'to adjust a camera to make a person or thing being photographed appear smaller or farther away:', 'Zoom out and aim at Uncle Dave flipping burgers on the grill.', 'phrasal verb', NULL, NULL, 'informal', 'unknown', NULL, NULL, NULL, DEFAULT, 3);
